(* Tools rows are the exact projection the renderer draws, so their scroll
   bound belongs to that projection rather than a second reconstruction in
   the state module. The Memory overview's header is wrapped to the terminal
   width, so its chrome is the renderer's too. Every other counted surface
   remains state-owned. *)
let scrolled_surface state surface =
  match surface with
  | Tools -> Some (Masc_tui_render.tools_scrolled state)
  | Memory when Option.is_none state.memory_facts_keeper ->
      let terminal_rows, cols = get_terminal_size () in
      let budget =
        Masc_tui_render_prim.surface_chrome_budget
          ~frame:Masc_tui_render_prim.Chrome_screen state ~terminal_rows
      in
      Some (Masc_tui_render_memory.memory_overview_scrolled ~cols ~budget state)
  (* Runtime's authority row wraps to the terminal width too, so its bound is
     read at that width for the same reason the Memory overview's is. *)
  | Runtime ->
      let terminal_rows, cols = get_terminal_size () in
      let rows = Masc_tui_types.surface_body_rows state ~terminal_rows in
      Masc_tui_types.runtime_scrolled ~rows ~cols state
  | Lanes when state.lanes_mode = Lanes_overview ->
      let terminal_rows, cols = get_terminal_size () in
      let rows = Masc_tui_types.surface_body_rows state ~terminal_rows in
      Some (Masc_tui_types.lanes_overview_projection state ~rows ~cols).lop_scroll
  (* The models pane's document depends on the pane width: narrow panes draw
     one wrapped item per binding, taller than the table it replaces. *)
  | Config when state.config_pane = Config_models ->
      Some (Masc_tui_render.config_models_scrolled state)
  | Overview | Acting | Metrics | Lanes | Clients | Board | Approvals | Planning | Schedules
  | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors | Resources
  | System_logs | Keepers _ | (Memory|Config) ->
      (* The Config runtime pane's chrome reads the terminal width too. The
         dimension-dependent Lanes overview is handled above. *)
      let _terminal_rows, cols = get_terminal_size () in
      Masc_tui_types.scrolled_surface state ~cols surface
;;

(* What one wheel detent moves. Terminals report three lines per detent, so a
   notch here is worth what a notch is worth in a pager. *)
let wheel_notch_rows = 3

(* The bound comes from [scrolled_surface], which the drawing reads too, so a
   keypress cannot move past what the frame can show. Surfaces the state
   cannot count keep their old unbounded step; the drawing still clamps those
   on the way past. *)
(* The rows a surface's list actually draws in. A surface that puts a preview
   under its list says so in its [scrolled], and both movers ask here: a bound
   worked out from the full body while the frame draws half of it is not a
   bound, and the rows past the shortened list stop being reachable. *)
let surface_body_height ~rows
    { sc_count; sc_chrome; sc_preview_keep } =
  Masc_tui_scroll.content_height ~rows ~chrome:sc_chrome ~count:sc_count
    ~preview_keep:sc_preview_keep

let move_surface_scroll (state : state) ~rows ~delta ~current =
  match scrolled_surface state state.view with
  | None -> Masc_tui_scroll.step_uncounted ~delta current
  | Some scrolled ->
      let height = surface_body_height ~rows scrolled in
      if delta >= 0 then
        Masc_tui_scroll.down ~count:scrolled.sc_count ~height current
      else Masc_tui_scroll.up ~count:scrolled.sc_count ~height current

let move_surface_to_end (state : state) ~rows ~current =
  match scrolled_surface state state.view with
  | None -> current
  | Some scrolled ->
      let height = surface_body_height ~rows scrolled in
      Masc_tui_scroll.maximum ~count:scrolled.sc_count ~height

(* The rows a surface has to draw in. The same arithmetic the drawing does --
   a bound worked out from a different height than the frame uses is not a
   bound. Reading the terminal's own rows here, as this did, left the log
   surface's keypress bound one row looser than the frame it moved within, and
   subtracting only the composer left it one row looser again on every screen
   the agenda strip was on. Both readers now ask
   {!Masc_tui_types.surface_body_rows}. *)
let surface_rows (state : state) =
  let terminal_rows, _columns = get_terminal_size () in
  Masc_tui_types.surface_body_rows state ~terminal_rows

let tools_scroll_viewport state =
  tools_task_presented_viewport state ~fallback:(fun () ->
    let scrolled = Masc_tui_render.tools_scrolled state in
    scrolled.sc_count, surface_body_height ~rows:(surface_rows state) scrolled)

(* Page keys move almost one visible body, leaving a few rows of overlap so
   the reader keeps their place across the jump. Individual renderers clamp
   the result against their exact wrapped-line count. *)
let surface_page_rows (state : state) = max 1 (surface_rows state - 8)

let runtime_config_assignment_rows (state : state) =
  Masc_tui_types.runtime_config_active_rows state
  |> List.filter_mapi (fun index row ->
       if Masc_tui_code_lexer.row_has_assignment row then Some index else None)

(* Pick an actual value row at or beyond [target] in the requested direction.
   The cursor never lands on a comment, table heading, or blank line; those
   rows stay visible as context around the selected field. *)
let runtime_config_row_near rows ~direction ~target =
  match rows with
  | [] -> 0
  | first :: _ when direction >= 0 ->
      (* [Option.value ~default:(List.hd (List.rev rows))] evaluated the
         default eagerly, so it reversed the whole row list on every call
         even when the find succeeded. The fold keeps the last row without
         building a reversed copy; [first] stands in for the impossible
         empty case because this arm already matched a head. *)
      (match List.find_opt (fun row -> row >= target) rows with
       | Some row -> row
       | None ->
         Option.value ~default:first
           (List.fold_left (fun _ latest -> Some latest) None rows))
  | first :: _ ->
      List.fold_left
        (fun selected row -> if row <= target then row else selected)
        first rows

let set_runtime_config_cursor_near ?(keep_scroll = false) state ~direction ~target =
  let rows = runtime_config_assignment_rows state in
  let cursor = runtime_config_row_near rows ~direction ~target in
  state.runtime_config_cursor <- cursor;
  if not keep_scroll then
    state.config_scroll <-
      Masc_tui_scroll.ensure_visible ~cursor
        ~height:(Masc_tui_render.config_content_height state)
        state.config_scroll

(* The table header a lexed runtime.toml row opens, read by the TOML grammar:
   whitespace, quoted keys and a trailing comment are the parser's to settle,
   so [[providers."glm-coding"]  # note] and [[providers.glm-coding]] name
   one table. The raw source view stays the one authority for both what is
   shown and what $EDITOR later receives. *)
let runtime_config_row_header segments =
  Toml_line_editor.header_of_line (String.concat "" (List.map fst segments))

let runtime_config_section_line ~path rows =
  List.find_index
    (fun segments ->
       match runtime_config_row_header segments with
       | Some (Toml_line_editor.Table found) -> List.equal String.equal found path
       | Some (Toml_line_editor.Table_array _) | None -> false)
    rows

(* A table path as runtime.toml spells it, for the notes that name it. *)
let runtime_config_path_text path =
  String.concat "." (List.map Toml_line_editor.render_key path)

(* Rows of context kept above a jumped-to heading, so the reader sees what
   precedes the table rather than landing on its first line. *)
let runtime_config_jump_context_rows = 3

(* Consume a cross-surface source jump after runtime.toml has landed. The
   cursor itself stays on a value row, while the viewport leaves the table
   heading visible as context. A table with no value of its own leaves the
   cursor on a later table's row; the heading asked for is what stays in
   view then. *)
let apply_runtime_config_jump state =
  match state.runtime_config_jump_section, state.runtime_config_view with
  | Some _, _ when state.view <> Config || state.config_pane <> Config_runtime ->
    state.runtime_config_jump_section <- None;
    None
  | Some path, Some _ ->
    let rows = Masc_tui_types.runtime_config_active_rows state in
    state.runtime_config_jump_section <- None;
    state.config_pane <- Config_runtime;
    state.runtime_config_status_open <- false;
    let found = runtime_config_section_line ~path rows in
    (match found with
     | Some index ->
       set_runtime_config_cursor_near state ~direction:1 ~target:index;
       let height = Masc_tui_render.config_content_height state in
       let preferred_scroll =
         max 0 (index - min runtime_config_jump_context_rows (height - 1))
       in
       let cursor = state.runtime_config_cursor in
       let another_table_between =
         rows
         |> List.filteri (fun row_index _ -> row_index > index && row_index < cursor)
         |> List.exists (fun row -> Option.is_some (runtime_config_row_header row))
       in
       state.config_scroll <-
         (if cursor < index || cursor - index >= height || another_table_between
          then preferred_scroll
          else Masc_tui_scroll.ensure_visible ~cursor ~height preferred_scroll)
     | None -> ());
    Some (runtime_config_path_text path, Option.is_some found)
  | None, _ | Some _, None -> None

let open_runtime_model_source state runtime_id =
  state.runtime_model_form <- None;
  state.config_pane <- Config_runtime;
  state.runtime_config_status_open <- false;
  state.runtime_config_view_error <- None;
  state.config_scroll <- 0;
  state.runtime_config_cursor <- 0;
  let paths = match String.index_opt runtime_id '.' with
    | None -> []
    | Some index ->
        let provider = String.sub runtime_id 0 index in
        let model = String.sub runtime_id (index + 1)
            (String.length runtime_id - index - 1) in
        [[provider; model]; ["models"; model]; ["providers"; provider]] in
  state.runtime_config_jump_section <-
    (match state.runtime_config_view with
     | None -> None
     | Some {rcv_rows; _} -> List.find_opt
         (fun path -> Option.is_some (runtime_config_section_line ~path rcv_rows)) paths)

let move_runtime_config_cursor state ~delta =
  let direction = if delta >= 0 then 1 else -1 in
  set_runtime_config_cursor_near state ~direction
    ~target:(state.runtime_config_cursor + direction)

(* A row cursor over a plain listing: the keypress moves the cursor and the
   window follows with the smallest move that keeps it visible. Reads the
   same [scrolled_surface] bound the drawing uses, so the cursor cannot name
   a row the frame will not draw. *)
(* The rows a surface's list can draw in once the cursor is on [cursor].

   The dynamic-chrome lists measured here are asked at the landing row: a follow
   worked out from the layout before the move puts the landing outside the
   window it measured, and the step key and the jump keys were working that
   out differently -- the step recomputed, the landing did not. Every other
   list's [scrolled] is the same at every row. *)
let surface_body_height_at (state : state) ~cursor scrolled =
  let terminal_rows, cols = get_terminal_size () in
  let screen_budget () =
    Masc_tui_render_prim.surface_chrome_budget
      ~frame:Masc_tui_render_prim.Chrome_screen state ~terminal_rows
  in
  if state.repository_changes_open && Option.is_none state.repository_changes_diff_path then
    Masc_tui_render_repositories.repository_changes_content_height state
      ~cols ~budget:(screen_budget ()) ~cursor
  else if state.view = Repositories && not state.repository_changes_open then
    Masc_tui_render.repository_studio_content_height state ~cols
      ~budget:(screen_budget ()) ~cursor
  else if state.view = Memory && state.memory_page = Memory_facts && Option.is_some state.memory_facts_keeper then
    Masc_tui_render_memory.memory_facts_content_height ~cols
      ~budget:(screen_budget ()) ~cursor state
  else if state.view = Memory && Option.is_none state.memory_facts_keeper then
    surface_body_height ~rows:(screen_budget () + Masc_tui_frame.chrome_rows) scrolled
  else if state.view = Connectors && Option.is_none (Masc_tui_types.browser_lane_on_screen state) then
    let fixed =
      2
      + (if Option.is_some (Masc_tui_types.connectors_read_notice state) then 1 else 0)
      + (if Option.is_some state.connectors_error then 2 else 0)
    in
    max 1 (screen_budget () - fixed)
  else if state.view = Config && state.config_pane = Config_runtime && not state.runtime_config_status_open then
    Masc_tui_render.config_content_height state
  else surface_body_height ~rows:(surface_rows state) scrolled

let move_row_cursor (state : state) ~delta ~cursor ~scroll =
  match scrolled_surface state state.view with
  | None -> (cursor, Masc_tui_scroll.step_uncounted ~delta scroll)
  | Some ({ sc_count; _ } as scrolled) ->
      (* [delta], not its sign. The two steppers move one row, and reading
         only the direction meant a page key that routed through here moved
         one row while its key table said "page" -- Verification, Harness,
         Clients and the Git-changes list all read as j/k. *)
      let cursor = Masc_tui_scroll.cursor_move ~count:sc_count ~delta cursor in
      let height = surface_body_height_at state ~cursor scrolled in
      (cursor, Masc_tui_scroll.ensure_visible ~cursor ~height scroll)

(* The Identity tab's provider list. The key moves the cursor only: the
   detail pane draws the provider rows below whatever failure, progress and
   preamble lines that frame carries, so the frame is where the cursor's line
   is known and kept in view ([Masc_tui_render_identity.drawn.cursor_row]). *)
let move_identity_cursor (state : state) ~delta =
  match state.identity_view with
  | None -> ()
  | Some (_keeper_name, providers) ->
      let listing = Masc_tui_identity_input.current_listing state in
      let count =
        List.length (Masc_tui_identity_model.identity_connectable ~listing providers)
      in
      if count > 0 then begin
        let cursor =
          Masc_tui_identity_model.identity_cursor_clamped ~listing ~providers
            state.identity_cursor
        in
        state.identity_cursor <- Masc_tui_scroll.cursor_move ~count ~delta cursor
      end

let keeper_log_content_height (state : state) =
  Metrics_tail.content_height ~terminal_rows:(surface_rows state)
    ~error:None

let keeper_log_row_count (state : state) =
  let _, cols = get_terminal_size () in
  List.length (Masc_tui_types.keeper_log_rows state ~cols)

let approval_decision_key = function
  | Confirm -> "y"
  | Deny -> "n"

let approval_decision_done = function
  | Confirm -> "Confirmed"
  | Deny -> "Denied"

let approval_decision_unverified = function
  | Confirm -> "Confirmation outcome unverified"
  | Deny -> "Denial outcome unverified"

open Masc_tui_async_protocol

let machine_view = ref (ref ())
let retire_machine_view () = machine_view := ref ()
type pending_msx_checkpoint = {
  checkpoint_operation_id : string;
  checkpoint_restore : bool;
  checkpoint_slot : string;
  checkpoint_workspace : Tui_decode.server_identity;
}
module Checkpoint_pending = Masc_tui_msx_checkpoint_pending
let pending_msx_checkpoints : pending_msx_checkpoint list ref = ref []
let checkpoint_storage_errors : (string, string) Hashtbl.t = Hashtbl.create 4
let checkpoint_root workspace = Tui_decode.Canonical_path.to_string workspace.Tui_decode.sid_masc_root
let checkpoint_binding pending =
  Result.map (fun operation_id ->
    {Checkpoint_pending.operation_id; restore=pending.checkpoint_restore; slot=pending.checkpoint_slot;
     base_path=Tui_decode.Canonical_path.to_string pending.checkpoint_workspace.sid_base_path;
     masc_root=checkpoint_root pending.checkpoint_workspace})
    (Keeper_operation_id.of_string pending.checkpoint_operation_id)
let recover_checkpoints state workspace =
  let root = checkpoint_root workspace in
  let base_path = Tui_decode.Canonical_path.to_string workspace.Tui_decode.sid_base_path in
  (* Other TUI processes can publish an unresolved intent after our first read.
     Read the shared inventory on every write-admission check. *)
  if Result.is_ok (Masc_tui_types.workspace_change_origin state) then
    match Checkpoint_pending.load ~masc_root:root with
    | Error detail ->
        Hashtbl.replace checkpoint_storage_errors root detail;
        state.msx_notice <- Some ("Checkpoint intent storage unavailable; machine changes blocked: " ^ detail)
    | Ok bindings ->
        (* [load] keeps only bindings under [root], and the filter keeps only
           those under [base_path], so each one names [workspace]'s paths. *)
        let recovered = List.map (fun (binding : Checkpoint_pending.binding) ->
          {checkpoint_operation_id=Keeper_operation_id.to_string binding.operation_id;
           checkpoint_restore=binding.restore; checkpoint_slot=binding.slot;
           checkpoint_workspace=workspace})
          (List.filter (fun (binding : Checkpoint_pending.binding) -> binding.base_path=base_path) bindings) in
        pending_msx_checkpoints := recovered @ List.filter (fun pending ->
          Tui_decode.Canonical_path.to_string pending.checkpoint_workspace.sid_base_path <> base_path
          || checkpoint_root pending.checkpoint_workspace <> root) !pending_msx_checkpoints;
        Hashtbl.remove checkpoint_storage_errors root;
        if recovered <> [] then
          state.msx_notice <- Some "Unresolved checkpoint recovered; F5 inspects its original receipt before machine control resumes."
let checkpoint_for_workspace state =
  match state.server_identity with
  | None -> None
  | Some workspace ->
      recover_checkpoints state workspace;
      List.find_opt (fun pending ->
        Tui_decode.Canonical_path.equal pending.checkpoint_workspace.sid_base_path
          workspace.sid_base_path
        && checkpoint_root pending.checkpoint_workspace = checkpoint_root workspace)
        !pending_msx_checkpoints
let remember_checkpoint pending =
  let root = checkpoint_root pending.checkpoint_workspace in
  match checkpoint_binding pending with
  | Error detail -> Error detail
  | Ok binding ->
      (match Checkpoint_pending.remember ~masc_root:root binding with
       | Error detail -> Error detail
       | Ok () -> pending_msx_checkpoints := pending :: !pending_msx_checkpoints; Ok ())
let forget_checkpoint pending =
  let root = checkpoint_root pending.checkpoint_workspace in
  match Result.bind (checkpoint_binding pending) (Checkpoint_pending.forget ~masc_root:root) with
  | Error detail -> Hashtbl.replace checkpoint_storage_errors root detail
  | Ok () ->
      Hashtbl.remove checkpoint_storage_errors root;
      pending_msx_checkpoints := List.filter (fun held ->
        held.checkpoint_operation_id <> pending.checkpoint_operation_id
        || checkpoint_root held.checkpoint_workspace <> root) !pending_msx_checkpoints
let machine_changes_allowed state =
  Result.is_ok (Masc_tui_types.workspace_change_origin state)
  && Option.is_none (checkpoint_for_workspace state)
  && not (Option.exists (fun workspace -> Hashtbl.mem checkpoint_storage_errors (checkpoint_root workspace)) state.server_identity)
let machine_change_refusal = "MSX control requires a verified server matching this TUI's local workspace."

(* The cached identity only describes the last read. A machine mutation
   revalidates its captured endpoint immediately before dispatch, and its
   completion owns only the view and authority that requested it. A change
   the workspace guard stops never left, so it goes to [withdrawn] with its
   refusal, apart from [deliver]'s refusals and unknown outcomes (RFC §2). *)
let run_machine_change ?(checkpoint_boundary=false) state ~mailbox ~refused ~unknown ~withdrawn ~deliver write =
  let authority = state.workspace_authority in
  let view = ref !machine_view in
  let port = state.port in
  let identity = state.server_identity in
  let check = Masc_tui_transport.Workspace_admission.capture_admission state ~mailbox in
  let current () =
    authority = state.workspace_authority && !view == !machine_view && port = state.port
  in
  (* The identity the check confirmed is the one the request carries, so the
     server compares it again at the moment it applies the change. *)
  let admission =
    try
      if not (machine_changes_allowed state) then Error (Request_failed machine_change_refusal)
      else match identity, check () with
      | _, Error refusal -> Error (Request_withdrawn refusal)
      | None, Ok () -> Error (Request_withdrawn Workspace_identity_not_confirmed)
      | Some expected, Ok () when current () && machine_changes_allowed state -> Ok expected
      | Some _, Ok () -> Error (Request_failed "MSX control view or workspace authority withdrawn")
    with
    | Eio.Cancel.Cancelled _ as exn -> raise exn
    | exn -> Error (Request_failed (Printexc.to_string exn))
  in
  match admission with
  | Error (Request_failed detail) when current () ->
      state.machine_interaction <- Observe_machine;
      deliver None (Error (refused detail))
  | Error (Request_withdrawn refusal) when current () ->
      state.machine_interaction <- Observe_machine;
      withdrawn refusal
  | Error (Request_failed _ | Request_withdrawn _) -> ()
  | Ok expected_workspace ->
      let result =
        try
            if checkpoint_boundary then begin
              retire_machine_view ();
              view := !machine_view;
              state.msx_live_in_flight <- None
            end;
            (* No yield separates retirement from the checkpoint callback,
               which records its pending identity before sending HTTP. *)
            write ~port ~expected_workspace
        with
        | Eio.Cancel.Cancelled _ as exn -> raise exn
        | exn -> Error (unknown (Printexc.to_string exn))
      in
      if current () then deliver (Some expected_workspace) result

;;

let launch_artifact_checks_load state ~mailbox =
  if server_authority_ready state then
    match Masc_tui_fetched.refresh ~equal:Unit.equal state.artifact_checks ~key:() with
    | Already_loading -> ()
    | Started (reading, request) ->
      state.artifact_checks <- reading;
      let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
      Masc_tui_transport.Workspace_admission.launch_json_read state ~mailbox
        ~boundary_error:(fun detail -> Request_failed detail)
        ~withdrawn:(fun refusal -> Request_withdrawn refusal)
        ~deliver:(fun result -> Artifact_msg (Artifact_checks_loaded (request, result)))
        (fun () ->
          let open Result.Syntax in
          Result.map_error (fun detail -> Request_failed detail) @@
          let* json = Masc_tui_http.get_json ~host ~port ~path:"/api/v1/published-artifact-checks" in
          Masc_tui_artifact_checks.of_json ~received_at:(Unix.gettimeofday ()) json)

let launch_resources_load state ~mailbox =
  Masc_tui_resources_requests.launch_list state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
    ~launch:(Masc_tui_transport.Workspace_admission.launch_json_read state ~mailbox
      ~boundary_error:(fun detail -> Request_failed detail)
      ~withdrawn:(fun refusal -> Request_withdrawn refusal))
    ~check:(Masc_tui_transport.Workspace_admission.capture_admission state ~mailbox);
  launch_artifact_checks_load state ~mailbox

let resource_export_is_current state prompt =
  if state.workspace_authority <> prompt.rsp_authority
     || state.workspace_read_authority != prompt.rsp_read_authority then
    Error "The workspace changed; cancel and select the report again"
  else match Masc_tui_resource_document.export_source state with
    | Ok current when Masc_tui_resource_export.same current prompt.rsp_document -> Ok ()
    | Ok _ -> Error "The selected report revision changed; cancel and select it again"
    | Error detail -> Error detail

let open_resource_save_prompt state =
  match Masc_tui_resource_document.export_source state with
  | Error detail -> report_action state "error" detail
  | Ok document ->
    (match workspace_input_identity_of_server state.server_identity with
     | None -> report_action state "error" "Confirm the workspace before saving this report"
     | Some workspace ->
       let directory = Sys.getcwd () in
       let path = Masc_tui_message_input.create () in
       Masc_tui_message_input.insert path
         (Filename.concat directory (Masc_tui_resource_export.suggested_name document));
       state.resource_save_prompt <- Some {
         rsp_owner = ref (); rsp_document = document; rsp_path = path;
         rsp_authority = state.workspace_authority;
         rsp_read_authority = state.workspace_read_authority;
         rsp_workspace = workspace; rsp_directory = directory; rsp_error = None })

type resource_save_observation =
  | Save_not_entered
  | Save_entered
  | Save_observed of resource_save_outcome

let save_resource_source state ~mailbox prompt =
  match resource_export_is_current state prompt with
  | Error detail -> prompt.rsp_error <- Some detail
  | Ok () ->
    let input_path = Masc_tui_message_input.contents prompt.rsp_path in
    if String.equal input_path "" then prompt.rsp_error <- Some "Enter a destination file path"
    else if resource_save_pending_for_prompt state prompt then ()
    else match Eio_context.get_env_opt () with
    | None -> prompt.rsp_error <- Some "The local filesystem is unavailable"
    | Some env ->
      let request = {
        save_form = prompt.rsp_owner;
        save_document = prompt.rsp_document; save_input_path = input_path;
        save_path = resource_save_path prompt; save_workspace = prompt.rsp_workspace } in
      state.resource_save_receipts <- {save_request=request;save_phase=Resource_save_pending}
        :: state.resource_save_receipts;
      prompt.rsp_error <- None;
      state.resource_scroll <- Masc_tui_scroll.Position.first;
      let observed = ref Save_not_entered in
      let boundary detail = match !observed with
        | Save_not_entered -> Resource_save_not_started detail
        | Save_entered -> Resource_save_unconfirmed {detail;cause=None}
        | Save_observed outcome -> outcome in
      let deliver outcome = Resource_msg (Resource_saved (request, outcome)) in
      Masc_tui_transport.Workspace_admission.launch_guarded_request ~operation:true state ~mailbox ~boundary_error:boundary
        ~withdrawn:(fun refusal -> Resource_save_kept_back refusal)
        ~cancelled_by:(fun () -> deliver (match !observed with
          | Save_not_entered -> Resource_save_not_started "Save cancelled before file creation"
          | Save_entered -> Resource_save_interrupted None
          | Save_observed outcome -> outcome))
        ~deliver:(function Ok outcome | Error outcome -> deliver outcome)
        (fun () ->
          match resource_export_is_current state prompt with
          | Error detail -> Ok (Resource_save_not_started detail)
          | Ok () ->
            observed := Save_entered;
            match Masc_tui_resource_export.save ~fs:env#fs ~path:request.save_path request.save_document with
            | result ->
                let outcome = Resource_save_result result in
                observed := Save_observed outcome;
                Ok outcome
            | exception (Eio.Cancel.Cancelled _ as exn) ->
                let backtrace = Printexc.get_raw_backtrace () in
                observed := Save_observed (Resource_save_interrupted
                  (Masc_tui_resource_export.cancellation exn));
                Printexc.raise_with_backtrace exn backtrace
            | exception exn ->
                let backtrace = Printexc.get_raw_backtrace () in
                (match Masc_tui_resource_export.cancellation exn with
                 | Some cancellation ->
                     observed := Save_observed (Resource_save_interrupted (Some cancellation));
                     Printexc.raise_with_backtrace exn backtrace
                 | None ->
                     let outcome = Resource_save_unconfirmed {
                       detail=Printexc.to_string exn;cause=Some exn} in
                     observed := Save_observed outcome;
                     Ok outcome))

let open_resource_in_dashboard state ~mailbox =
  match Masc_tui_resource_document.export_source state with
  | Error detail -> report_action state "error" detail
  | Ok document ->
    let authority = state.workspace_authority in
    let reading = state.workspace_read_authority in
    let port = state.port in
    let url = Masc_tui_resource_export.dashboard_url ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port document in
    let failed detail = Request_failed detail in
    Masc_tui_transport.Workspace_admission.launch_guarded_request ~operation:true state ~mailbox ~boundary_error:failed
      ~withdrawn:(fun refusal -> Request_withdrawn refusal)
      ~cancelled:(Resource_msg (Resource_exported (Masc_tui_resource_export.label document,
        Error (failed ("Browser opening interrupted; whether the browser opened is unknown: " ^ url)))))
      ~deliver:(fun result -> Resource_msg (Resource_exported (Masc_tui_resource_export.label document, result)))
      (fun () ->
        if authority <> state.workspace_authority || reading != state.workspace_read_authority then
          Error (failed "The workspace changed before opening this report")
        else match Masc_tui_resource_document.export_source state with
        | Error detail -> Error (failed detail)
        | Ok current when not (Masc_tui_resource_export.same current document) ->
            Error (failed "The selected report changed before opening")
        | Ok _ ->
          Eio_guard.run_in_systhread ~label:"tui-report-browser" (fun () ->
            Masc_tui_browser.open_url url)
          |> Result.map (fun opener -> "Opened " ^ url ^ " via " ^ opener ^ "; browser authentication may be required")
          |> Result.map_error failed)

let launch_resources_read state ~mailbox ~key =
  withdraw_resource_diagram_pending state;
  let share_origin = Result.to_option (workspace_change_origin state) in
  Masc_tui_resources_requests.launch_read state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
    ~share_origin
    ~launch:(Masc_tui_transport.Workspace_admission.launch_json_read state ~mailbox
      ~boundary_error:(fun detail -> Request_failed detail)
      ~withdrawn:(fun refusal -> Request_withdrawn refusal))
    ~check:(Masc_tui_transport.Workspace_admission.capture_admission state ~mailbox) ~key

let launch_artifact_check_change state ~mailbox =
  let entry = match state.resource_focus with
    | Right_pane -> Option.map Masc_tui_resource_document.entry
        (Masc_tui_resource_document.current state)
    | Left_pane -> Option.bind (visible_resources state) (fun entries ->
        List.nth_opt entries state.resources_cursor) in
  match entry, state.server_identity with
  | (None | Some (Masc_tui_resource_catalog.Mcp _)), _ ->
    report_action state "error" "Select a published report revision to check or uncheck"
  | Some (Report _), None ->
    Masc_tui_transport.Request_notice.report_kept_back state ~request:Kept_request.Report_check workspace_identity_unread Nothing_kept
  | Some (Report report), Some expected_workspace ->
    match Masc_tui_resources_updates.begin_check state ~report with
    | Error (Request_failed detail) -> report_action state "error" detail
    | Error (Request_withdrawn refusal) ->
      Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Report_check refusal
    | Ok request ->
      let credential = Masc_tui_http.bind_credential () in
      let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
      report_action state "system" "Saving confirmation; refresh follows the result";
      Masc_tui_transport.Workspace_admission.launch_guarded_request ~operation:true state ~mailbox
        ~boundary_error:(fun detail -> Request_failed detail)
        ~withdrawn:(fun refusal -> Request_withdrawn refusal)
        ~deliver:(fun result -> Artifact_msg (Artifact_check_changed (request, result)))
        (fun () -> Masc_tui_http.post_artifact_check ~credential ~expected_workspace
          ~host ~port ~request
          |> Result.map_error (fun detail -> Request_failed detail))

module Artifact_share_pending = Masc_tui_artifact_share_pending

let artifact_share_journal_path origin =
  Artifact_share_pending.journal_path ~masc_root:origin.wi_masc_root

let open_resource_report state =
  match Masc_tui_resource_document.current state with
  | Some {entry = Masc_tui_resource_catalog.Report report; _} -> Ok report
  | Some {entry = Mcp _; _} | None -> Error "Open a published report in the detail pane"

(* The share POST the workspace guard stopped: the notice, the report, and
   the way to settle the intent already recorded for it, which a later
   attempt may still apply. *)
let report_resource_share_kept_back state (request : resource_share_request) refusal =
  let ko = state.ui_language = Lang_ko in
  report_action state "error"
    (String.concat " · "
       [ workspace_refusal_text ~ko ~request:Kept_request.Resource_share refusal
       ; request.share_report.id
       ; (if ko then "U 로 기록된 작업을 맞추세요" else "use U to reconcile the recorded operation") ])

let launch_resource_share state ~mailbox ~report ~entry ~recovery ~dispatch_allowed =
  let captured_authority = state.workspace_authority in
  match state.server_identity, workspace_change_origin state with
  | Some expected_workspace, Ok origin
    when entry.Artifact_share_pending.base_path = origin.wi_base_path
         && entry.masc_root = origin.wi_masc_root && entry.artifact_id = report.Masc_tui_resource_catalog.id ->
    let operation = entry.request in
    let path = artifact_share_journal_path origin in
    let on_observed entries =
      List.iter (fun (observed : Artifact_share_pending.entry) ->
        if observed.masc_root = origin.wi_masc_root then record_resource_share_observation state observed) entries in
    (match Masc_tui_resources_updates.begin_share_change ~recovery state ~report ~entry with
     | Error (Request_failed detail) -> report_action state "error" detail
     | Error (Request_withdrawn refusal) ->
       Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Resource_share refusal
     | Ok request ->
       report_action state "system" (if recovery then
         "Reconciling the original share operation; it may be applied now"
         else if operation.requested then "Enabling external sharing" else "Revoking external sharing");
       let credential = Masc_tui_http.bind_credential () in
       let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
       let identity = Some expected_workspace in
       let context detail = Printf.sprintf
         "operation %s, observed share version %d, publication v%d (%s): %s"
         operation.operation_id operation.expected_version operation.expected_artifact_revision
         operation.expected_artifact_sha256 detail in
       let journal_started = ref false in
       let attempt = Masc_tui_artifact_share_attempt.create () in
       let failure detail =
         if !journal_started || Masc_tui_artifact_share_attempt.dispatched attempt
         then Resource_share_unknown (context detail) else Resource_share_not_started detail in
       Masc_tui_transport.Workspace_admission.launch_result ~operation:true state ~mailbox
         ~boundary_error:failure
         ~cancelled_by:(fun () -> Resource_msg (Resource_share_changed (request, Error (failure "interrupted"))))
         ~deliver:(fun result -> Resource_msg (Resource_share_changed (request, result)))
         (fun () ->
           (* The filesystem transaction and its lock belong to this worker, not
              to the input loop. A cancelled system-thread write may finish. *)
           journal_started := true;
           let prepared = if recovery then
               Artifact_share_pending.restore ~on_observed ~path entry |> Result.map (fun () -> Artifact_share_pending.Prepared)
             else Artifact_share_pending.prepare_checked ~on_observed ~path entry in
           match prepared with
           | Error detail -> Error (Resource_share_unknown (context ("Share intent storage could not be confirmed: " ^ detail)))
           | Ok (Artifact_share_pending.Not_prepared detail) ->
             Ok (Resource_share_not_prepared ("Share intent was not recorded: " ^ detail))
           | Ok (Artifact_share_pending.Already_pending _) ->
             Ok (Resource_share_not_prepared "Another recorded share operation must be resolved first")
           | Ok (Artifact_share_pending.Already_pending_with_storage_failure (_, detail)) ->
             Ok (Resource_share_not_prepared ("Another operation was observed; journal storage failed: " ^ detail))
           | Ok Artifact_share_pending.Prepared ->
             match Masc_tui_artifact_share_attempt.perform attempt
               ~preflight:(fun () ->
                 match Masc_tui_transport.Workspace_admission.admit_request state ~mailbox ~authority:captured_authority ~identity ~host ~port () with
                 | Error refusal -> Error (Request_withdrawn refusal)
                 | Ok () ->
                   (match resource_share_dispatch_refusal state ~origin ~entry ~recovery with
                    | Some detail -> Error (Request_failed detail)
                    | None when dispatch_allowed () -> Ok ()
                    | None -> Error (Request_failed "An interrupt or termination is awaiting handling")))
               ~send:(fun () -> Masc_tui_http.post_artifact_share ~credential ~expected_workspace
                 ~host ~port ~id:entry.artifact_id ~shared:operation.requested
                 ~operation_id:operation.operation_id ~expected_version:operation.expected_version
                 ~expected_artifact_revision:operation.expected_artifact_revision
                 ~expected_artifact_sha256:operation.expected_artifact_sha256) with
             | Not_sent (Request_failed detail) -> Ok (Resource_share_not_sent detail)
             | Not_sent (Request_withdrawn refusal) -> Ok (Resource_share_kept_back refusal)
             | Sent (Error detail) -> Error (Resource_share_unknown (context detail))
             | Sent (Ok result) ->
               (match Artifact_share_pending.settle ~on_observed ~path entry with
                | Error detail -> Error (Resource_share_unknown
                    (context ("Receipt arrived but recovery storage did not settle: " ^ detail)))
                | Ok _ -> Ok (match result with
                  | Masc_tui_http.Artifact_share_applied shared -> Resource_share_applied shared
                  | Masc_tui_http.Artifact_share_conflict shared -> Resource_share_conflict shared))))
  | (Some _ | None), (Ok _ | Error _) ->
    report_action state "error" "The original share operation belongs to a different or unverified workspace"

let toggle_resource_external_share state ~mailbox ~dispatch_allowed =
  state.resource_share_recovery_prompt <- None;
  match Masc_tui_resource_document.external_share_change state, workspace_change_origin state with
  | Error detail, _ | _, Error detail -> report_action state "error" detail
  | Ok (report, shared), Ok origin ->
    (match state.resource_share_version, state.resource_revision_history with
     | Some expected_version, latest :: _ when String.equal latest.id report.id ->
       let request : Masc.Published_artifact_share.request = {
         operation_id=Random_id.uuid_v7 (); expected_version; requested=shared;
         expected_artifact_revision=latest.revision.revision;
         expected_artifact_sha256=latest.revision.body.sha256 } in
       let entry : Artifact_share_pending.entry = {base_path=origin.wi_base_path;
         masc_root=origin.wi_masc_root; artifact_id=report.id; request} in
       launch_resource_share state ~mailbox ~report ~entry ~recovery:false ~dispatch_allowed
     | Some _, _ :: _ | Some _, [] | None, ([] | _ :: _) ->
       report_action state "error" "Share version or latest publication is unavailable; reread this report")

let begin_resource_share_recovery_lookup state ~mailbox =
  match open_resource_report state, workspace_change_origin state, state.resource_share_recovery_lookup with
  | Error detail, _, _ | _, Error detail, _ -> report_action state "error" detail
  | Ok _, Ok _, Some _ -> report_action state "system" "Checking the recorded share operation"
  | Ok report, Ok origin, None when List.exists (fun pending ->
      pending.share_workspace_identity = origin && String.equal pending.share_report.id report.id)
      state.resource_share_pending ->
    report_action state "system" "A sharing attempt for this artifact is still running; wait for its result."
  | Ok report, Ok origin, None ->
    let request = { recovery_lookup_owner=ref (); recovery_lookup_workspace=state.workspace_authority;
      recovery_lookup_origin=origin; recovery_lookup_key=Masc_tui_resource_catalog.Report_revision report } in
    Masc_tui_resources_updates.begin_share_recovery_lookup state ~origin ~report;
    state.resource_share_recovery_lookup <- Some request;
    report_action state "system" "Checking the recorded share operation";
    let path = artifact_share_journal_path origin in
    Masc_tui_transport.Workspace_admission.launch_result ~observation:true state ~mailbox
      ~boundary_error:Fun.id
      ~cancelled:(Resource_msg (Resource_share_recovery_loaded (request, Error "Recovery lookup interrupted")))
      ~deliver:(fun result -> Resource_msg (Resource_share_recovery_loaded (request, result)))
      (fun () ->
        let on_observed entries = List.iter (fun (entry : Artifact_share_pending.entry) ->
          if entry.masc_root = origin.wi_masc_root then record_resource_share_observation state entry) entries in
        Artifact_share_pending.observe ~on_observed ~path () |> Result.map (fun (_, entries) ->
          List.find_opt (fun (entry : Artifact_share_pending.entry) ->
            entry.base_path = origin.wi_base_path && entry.masc_root = origin.wi_masc_root
            && entry.artifact_id = report.id) entries))

let recover_resource_external_share state ~mailbox ~confirm ~dispatch_allowed =
  if not confirm then begin_resource_share_recovery_lookup state ~mailbox
  else match open_resource_report state, workspace_change_origin state, state.resource_share_recovery_prompt with
  | Ok report, Ok origin, Some held
    when held.recovery_workspace = state.workspace_authority
         && held.recovery_entry.base_path = origin.wi_base_path
         && held.recovery_entry.masc_root = origin.wi_masc_root
         && Masc_tui_resource_catalog.equal_key held.recovery_key (Report_revision report) ->
    if Masc_tui_artifact_share_confirmation.ready held.recovery_confirmation then begin
      state.resource_share_recovery_prompt <- None;
      launch_resource_share state ~mailbox ~report ~entry:held.recovery_entry ~recovery:true ~dispatch_allowed
    end else report_action state "system" "Wait for the recovery preview before confirming."
  | (Ok _ | Error _), (Ok _ | Error _), (Some _ | None) ->
    state.resource_share_recovery_prompt <- None;
    report_action state "system" "Press U to inspect the current recovery operation first."

let resource_share_is_owned state request =
  List.exists (fun current -> current.share_owner == request.share_owner) state.resource_share_pending

let resource_public_copy_is_current state copy =
  state.view = Resources && state.resource_focus = Right_pane
  && state.workspace_authority = copy.public_copy_workspace
  && state.workspace_read_authority == copy.public_copy_read_authority
  && workspace_change_origin state = Ok copy.public_copy_origin
  && match Masc_tui_resource_document.current state with
     | Some reading ->
       Masc_tui_resource_catalog.equal_key (Masc_tui_resource_catalog.key reading.entry) copy.public_copy_key
       && reading.public_url = Some (Ok copy.public_copy_url)
     | None -> false

let finish_resource_share state request result =
  withdraw_resource_diagram_pending state;
  let read_key = Masc_tui_resources_updates.share_changed state request ~result in
  let key = request.share_workspace_identity, request.share_report.id in
  match result with
  | Ok (Resource_share_applied _ | Resource_share_conflict _) -> read_key
  | Ok (Resource_share_not_prepared _) -> read_key
  | Error (Resource_share_not_started _) when not request.share_recovery -> read_key
  | Ok (Resource_share_not_sent _ | Resource_share_kept_back _)
  | Error (Resource_share_unknown _ | Resource_share_not_started _) ->
    if not (List.mem key state.resource_share_uncertain_ids) then
      state.resource_share_uncertain_ids <- key :: state.resource_share_uncertain_ids;
    None

(* Wire the web-link-preview background fetcher. On the first cache miss for a
   URL, Masc_tui_link_preview renders the synthesized card immediately and calls
   this hook; the fetched <title>/og:* then replace that entry in the shared
   cache, and the next render (a periodic loader tick, sub-second) shows the real
   card. A failed fetch leaves the synthesized card. Runs on its own daemon fiber
   so a slow site never blocks the render loop, and sends no masc auth header to
   the third-party URL. *)
(* Set once the image helpers below are in scope: downloads and decodes a
   preview's image into a half-block mosaic off the render loop. A no-op until
   then, so a preview fetched during early init simply carries no mosaic. *)
let compute_and_store_mosaic : (string -> unit) ref = ref (fun _ -> ())

let () =
  Masc_tui_link_preview.set_background_fetch (fun url ->
      match Eio_context.get_switch_opt () with
      | None -> ()
      | Some sw ->
          Eio.Fiber.fork_daemon ~sw (fun () ->
              (match Masc_tui_http.fetch_link_preview_body ~url with
               | Ok body ->
                   let preview = Masc_tui_link_preview.parse_og_html ~url ~body in
                   Masc_tui_link_preview.cache_store preview;
                   (match preview.Masc_tui_link_preview.image_url with
                    | Some img -> !compute_and_store_mosaic img
                    | None -> ())
               | Error _ -> ());
              `Stop_daemon))


(* The strict decode carries no tool information, so the rows the live pane
   drew are the only record of what the turn did. They are committed before
   the reply lands so the scrollback reads in the order it happened. *)
(* Ask the server to interrupt the turn this request opened.

   Nothing here decides that the turn stopped. The server reports whether it
   signalled the running fiber, and a turn parked in an uncancellable section
   keeps going after that (masc #29229). The stream ending is the proof, so the
   pane keeps drawing until it does. *)
(* Load the keeper's durable transcript. Runs on its own fiber: the pane stays
   responsive, and a slow or unreachable server costs the scrollback rather than
   the keypress that asked for it. *)
let launch_msx_live_read (state : Masc_tui_types.state) ~mailbox =
  if not (server_authority_ready state) || Option.is_some (checkpoint_for_workspace state) then () else
  let current_view = !machine_view in
  match state.msx_live_in_flight with
  | Some pending when pending.live_view == current_view && pending.live_port = state.port -> ()
  | Some _ | None ->
    (* An abandoned view's slow read does not own the reopened screen. Its
       reply still has to match this exact slot before it can settle it. *)
    let request = { live_view = current_view; live_port = state.port } in
    let since = Masc_tui_machine_live.since state.msx_live in
    let expected_workspace = state.server_identity in
    state.msx_live_owed <- Masc_tui_owed_read.started state.msx_live_owed;
    state.msx_live_in_flight <- Some request;
    Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox ~boundary_error:(fun detail -> Request_failed detail)
      ~withdrawn:(fun refusal -> Request_withdrawn refusal)
      ~deliver:(fun result -> Msx_msg (Msx_live_loaded (request, result)))
      (fun () -> Masc_tui_http.fetch_machine_live ?expected_workspace ~host:Masc_tui_transport.Workspace_admission.server_peer_host
        ~port:request.live_port Masc.Machine_lane.Msx ~since
        |> Result.map_error (fun detail -> Request_failed detail))
;;


let launch_dos_live_read (state : Masc_tui_types.state) ~mailbox =
  if server_authority_ready state then begin
  let current_view = !machine_view in
  match state.dos_live_in_flight with
  | Some pending when pending.live_view == current_view && pending.live_port = state.port -> ()
  | Some _ | None ->
    let request = { live_view = !machine_view; live_port = state.port } in
    state.dos_live_owed <- Masc_tui_owed_read.started state.dos_live_owed;
    state.dos_live_in_flight <- Some request;
    let since = Masc_tui_machine_live.since state.dos_live in
    Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox ~boundary_error:(fun detail -> Request_failed detail)
      ~withdrawn:(fun refusal -> Request_withdrawn refusal)
      ~deliver:(fun result -> Dos_live_loaded (request, result))
      (fun () -> Masc_tui_http.fetch_machine_live ~host:Masc_tui_transport.Workspace_admission.server_peer_host
        ~port:request.live_port Masc.Machine_lane.Dos ~since
        |> Result.map_error (fun detail -> Request_failed detail))
  end
;;

let cancel_board_preparation state =
  Option.iter (fun request -> Masc_tui_workspace_job.cancel_observation state
    ~key:(Masc_tui_board_reader.preparation_job request))
    (Masc_tui_board_reader.pending_preparation state.board_reader)

let close_board_reader state =
  Option.iter (fun request -> Masc_tui_workspace_job.cancel_observation state
    ~key:(Masc_tui_board_reader.request_job request))
    (Masc_tui_board_reader.pending state.board_reader);
  cancel_board_preparation state;
  state.board_reader <- Masc_tui_board_reader.close state.board_reader;
  state.board_reader_owner <- None

let launch_board_read state ~mailbox ~kind key =
  close_board_reader state;
  if server_authority_ready state then begin
    let content_kind=match kind with Ak_image -> Masc_tui_board_reader.Image_bytes
      | Ak_file | Ak_score | Ak_video | Ak_youtube | Ak_external_link
      | Ak_audio | Ak_midi | Ak_unknown _ -> Document in
    let reader,request=Masc_tui_board_reader.open_read ~content_kind ~key state.board_reader in
    state.board_reader <- reader;
    state.board_reader_owner <- Some (state.workspace_authority,state.workspace_read_authority,kind);
    let host=Masc_tui_transport.Workspace_admission.server_peer_host and port=state.port in
    Option.iter (fun request ->
      Masc_tui_transport.Workspace_admission.launch_json_read ~key:(Masc_tui_board_reader.request_job request) state ~mailbox
        ~boundary_error:(fun detail -> Request_failed detail)
        ~withdrawn:(fun refusal -> Request_withdrawn refusal)
        ~deliver:(fun result -> Board_msg (Board_attachment_loaded (request,result)))
        (fun () ->
          let open Result.Syntax in
          Result.map_error (fun detail -> Request_failed detail) @@
          let* bytes=Masc_tui_http.get_workspace_bytes ~host ~port
            ~max_body_bytes:Masc_tui_board_upload.max_attachment_bytes
            ~path:("/api/v1/artifact-bytes/" ^ key.Masc_tui_board_reader.sha256) in
          Masc_tui_response_decode.run ~name:"board.attachment.decode_wait" (fun () ->
            Masc_tui_board_reader.validate key bytes))) request
  end

let prepare_board_read state ~mailbox ~cols =
  match current_board_reader state with
  | None -> close_board_reader state
  | Some current ->
    let reader,request=Masc_tui_board_reader.start_preparation
      ~width:(Masc_tui_render_overlays.detail_reading_width cols) current in
    (match request with
     | None -> ()
     | Some request ->
       cancel_board_preparation state;
       state.board_reader <- reader;
       Masc_tui_transport.Workspace_admission.launch_result ~observation:true ~key:(Masc_tui_board_reader.preparation_job request) state ~mailbox
         ~boundary_error:Fun.id ~deliver:(fun result -> Board_msg (Board_attachment_prepared (request,result)))
         (fun () -> Masc_tui_response_decode.run ~name:"board.attachment.prepare_wait"
           (fun () -> Ok (Masc_tui_board_reader.prepare request))))

type board_original_action = Save_board_original | Open_board_image

let board_image_open_worker = Masc_tui_board_preview_work.create ()
let board_image_prepare_worker = Masc_tui_board_preview_work.create ()
let board_image_open_reaper : (bool Atomic.t * Thread.t) option ref = ref None

(* The reaper owns the child even if its Eio observer is cancelled. On normal
   process exit, request cancellation and join it before the runtime exits. *)
let () = at_exit (fun () ->
  Option.iter (fun (cancelled,thread) ->
    Atomic.set cancelled true;
    Thread.join thread) !board_image_open_reaper)

let use_board_read state ~mailbox ~action =
  let source = match action with
    | Save_board_original -> Masc_tui_board_reader.saved_source state.board_reader
        |> Option.map (fun (request,key,bytes) -> None,request,key,bytes)
    | Open_board_image when Masc_tui_board_preview_work.is_busy board_image_open_worker -> None
    | Open_board_image ->
        let reader,source=Masc_tui_board_reader.begin_original_open state.board_reader in
        state.board_reader <- reader;
        Option.map (fun (attempt,request,key,bytes) -> Some attempt,request,key,bytes) source in
  match source with
  | None -> ()
  | Some (attempt,request,key,bytes) ->
    let clear_pending () = Option.iter (fun attempt ->
      state.board_reader <- Masc_tui_board_reader.finish_original_open state.board_reader request attempt) attempt in
    let cancelled = Option.map (fun attempt ->
      Board_msg (Board_attachment_saved (request,Ok (Board_image_open_failed (attempt,"Image opening cancelled"))))) attempt in
    Masc_tui_transport.Workspace_admission.launch_result ~operation:true ?cancelled ~on_not_run:clear_pending state ~mailbox ~boundary_error:Fun.id
      ~deliver:(fun result ->
        let result=match attempt,result with
          | Some attempt,Error error -> Ok (Board_image_open_failed (attempt,error))
          | Some _,Ok _ | None,(Ok _ | Error _) -> result in
        Board_msg (Board_attachment_saved (request,result)))
      (fun () -> Eio_unix.run_in_systhread (fun () ->
        let prepare () =
        let kind=match attempt with None -> Ak_file | Some _ -> Ak_image in
        let attachment={ba_kind=kind;ba_source=As_artifact {sha256=key.sha256;bytes=key.bytes};ba_name=key.name} in
        match Masc_tui_attachment_action.prepare ~fetch:(fun ~sha256:_ -> Ok bytes) attachment with
        | Error outcome -> Error (Masc_tui_attachment_action.describe_outcome outcome)
        | Ok prepared -> match attempt with
          | Some attempt -> Ok (Board_image_open_ready (attempt,prepared))
          | None ->
              let outcome=Masc_tui_attachment_action.perform prepared ~midi_soundfont:None in
              let description=Masc_tui_attachment_action.describe_outcome outcome in
              match outcome.result with
              | Failed _ -> Error description
              | Saved _ | Played | Opened -> Ok (Board_saved_original description) in
        Masc_tui_board_preview_work.run board_image_prepare_worker prepare))


(* The MCP resource inventory, and one resource's text. Each operation
   opens its own session: a human-cadence browser does not earn a held
   connection, and a stale session id would be a second failure mode. *)

let tree_diff_base_ref = "HEAD"

let pr_number_of_subject subject =
  let n = String.length subject in
  let rec scan i best =
    if i >= n then best
    else if
      subject.[i] = '(' && i + 2 < n && subject.[i + 1] = '#'
    then begin
      let rec digits j acc =
        if j < n && subject.[j] >= '0' && subject.[j] <= '9' then
          digits (j + 1) ((acc * 10) + (Char.code subject.[j] - 48))
        else (j, acc)
      in
      let stop, value = digits (i + 2) 0 in
      if value > 0 && stop < n && subject.[stop] = ')' then
        scan (stop + 1) (Some value)
      else scan (i + 1) best
    end
    else scan (i + 1) best
  in
  scan 0 None

(* The codebase slug for the surface's scope, when it has one. Only a
   repository row carries the server-minted slug (RFC-0378: the client
   never re-derives it); the other scopes honestly have none. *)
(* Same fiber-and-mailbox shape as the notes read below. Scoped by the same
   keeper / repo axes the file itself was read through, so the margin
   describes the checkout on screen rather than whichever one the server
   would default to. *)
let repository_change_scope_equal left right =
  match left, right with
  | Tui_decode.Repository_change_project, Tui_decode.Repository_change_project ->
      true
  | ( Tui_decode.Repository_change_repository left_id
    , Tui_decode.Repository_change_repository right_id ) ->
      String.equal left_id right_id
  | Tui_decode.Repository_change_project, Tui_decode.Repository_change_repository _
  | Tui_decode.Repository_change_repository _, Tui_decode.Repository_change_project ->
      false

let launch_repository_changes_load state ~mailbox ~scope =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
    ~deliver:(fun result ->
      enqueue_async mailbox (Repository_msg (Repository_changes_loaded (scope, result))))
    (fun () ->
      match scope with
      | Tui_decode.Repository_change_project ->
          Masc_tui_loader.load_project_changes ~host ~port
      | Tui_decode.Repository_change_repository repository_id ->
          Masc_tui_loader.load_repository_changes ~host ~port ~repository_id)
  end

let launch_repository_changes_diff_load state ~mailbox ~scope ~path =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  state.repository_changes_diff_generation <- state.repository_changes_diff_generation + 1;
  let request =
    { rdr_scope = scope; rdr_path = path
    ; rdr_generation = state.repository_changes_diff_generation }
  in
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  let repo =
    match scope with
    | Tui_decode.Repository_change_repository repository_id -> Some repository_id
    | Tui_decode.Repository_change_project -> None
  in
  Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
    ~deliver:(fun result ->
      enqueue_async mailbox (Repository_msg (Repository_changes_diff_loaded (request, result))))
    (fun () ->
      Masc_tui_loader.load_git_diff ~host ~port ?repo ~keeper:None ~path
        ~against:(Masc_tui_http.Working_tree_against tree_diff_base_ref) ())
  end

let diff_text_max_width text =
  String.split_on_char '\n' text
  |> List.fold_left (fun widest line ->
       max widest (Message_layout.display_width (Terminal_text.single_line line))) 0

let git_diff_body_max_width (diff : Tui_decode.git_diff) =
  List.fold_left (fun widest (row : Tui_decode.git_diff_row) ->
    max widest (Message_layout.display_width
      (Terminal_text.single_line row.gdr_text))) 0 diff.gd_rows

let refresh_recorded_diff_bounds state ~reset =
  let width = match opened_file_change state with
    | None -> 0
    | Some change ->
        (match change.Tui_decode.fc_kind with
         | Tui_decode.Fc_edited { before; after; _ } ->
             max (diff_text_max_width before) (diff_text_max_width after)
         | Tui_decode.Fc_inserted { text; _ } -> diff_text_max_width text
         | Tui_decode.Fc_written { content } -> diff_text_max_width content
         | Tui_decode.Fc_materialized _ -> 0) in
  state.changes_diff_max_width <- width;
  state.changes_diff_hscroll <-
    if reset then 0
    else min state.changes_diff_hscroll (max 0 (width - 1))

let open_repository_change_diff state ~mailbox ~scope
    (change : Tui_decode.repository_change) =
  state.repository_changes_diff <- None;
  state.repository_changes_diff_error <- None;
  state.repository_changes_diff_path <- Some change.rc_path;
  state.repository_changes_diff_hscroll <- 0;
  state.repository_changes_diff_max_width <- 0;
  state.repository_changes_diff_scroll <- 0;
  launch_repository_changes_diff_load state ~mailbox ~scope ~path:change.rc_path

let close_repository_changes_diff state =
  state.repository_changes_diff <- None;
  state.repository_changes_diff_error <- None;
  state.repository_changes_diff_path <- None;
  state.repository_changes_diff_hscroll <- 0;
  state.repository_changes_diff_max_width <- 0;
  state.repository_changes_diff_scroll <- 0

let open_repository_changes state ~mailbox ~scope =
  state.repository_changes_open <- true;
  state.repository_changes_scope <- Some scope;
  state.repository_changes <- None;
  state.repository_changes_error <- None;
  state.repository_changes_cursor <- 0;
  state.repository_changes_scroll <- 0;
  state.repository_changes_diff <- None;
  state.repository_changes_diff_error <- None;
  state.repository_changes_diff_path <- None;
  state.repository_changes_diff_hscroll <- 0;
  state.repository_changes_diff_max_width <- 0;
  state.repository_changes_diff_scroll <- 0;
  launch_repository_changes_load state ~mailbox ~scope

let refresh_repository_changes state ~mailbox =
  match state.repository_changes_scope with
  | None -> ()
  | Some scope ->
      (match state.repository_changes_diff_path with
       | Some path ->
           launch_repository_changes_diff_load state ~mailbox ~scope ~path
       | None ->
           launch_repository_changes_load state ~mailbox ~scope)

let open_repository_change_in_code state ~mailbox ~scope
    (change : Tui_decode.repository_change) =
  set_code_scope state
    (match scope with
     | Tui_decode.Repository_change_project -> Code_scope_project
     | Tui_decode.Repository_change_repository repository_id ->
         Code_scope_repo repository_id);
  let parent = Filename.dirname change.rc_path in
  state.code_dir <- (if String.equal parent "." then "" else parent);
  state.code_cursor <- 0;
  state.code_listing <- Masc_tui_fetched.clear state.code_listing;
  state.code_file <- Masc_tui_fetched.clear state.code_file;
  state.code_file_resume_intent <- Refresh_code_file;
  state.code_focus_file <- Left_pane;
  close_repository_changes state;
  state.view <- Code;
  Masc_tui_code_requests.launch_entries_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state mailbox);
  Masc_tui_code_requests.launch_file_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state mailbox) ~path:change.rc_path

(* One step back on the Code surface, for Esc and for Left. Both take the step
   [Masc_tui_keys.code_back_step] names; when none is left, [leave] runs. Esc
   passes the way out to the ring parent and Left passes nothing, so Left
   stays on the surface. *)
let step_code_back state ~mailbox ~leave =
  let reload () =
    state.code_cursor <- 0;
    state.code_listing <- Masc_tui_fetched.clear state.code_listing;
    Masc_tui_code_requests.launch_entries_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
      ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state mailbox)
  in
  match Masc_tui_keys.code_back_step state with
  | Close_code_notes -> state.code_notes_open <- false
  | Close_code_diff -> close_code_diff state
  | Close_code_history -> state.code_history_open <- false
  | Return_to_code_tree -> state.code_focus_file <- Left_pane
  | Climb_code_directory ->
      (* Up one directory; "." from Filename.dirname means the root, which
         this surface spells "". *)
      let parent = Filename.dirname state.code_dir in
      state.code_dir <- (if String.equal parent "." then "" else parent);
      reload ()
  | Climb_to_code_project ->
      (* Above a keeper's or a repository's root sits the project tree the
         surface started on. *)
      set_code_scope state Code_scope_project;
      reload ()
  | Leave_code_for_workspace -> leave ()

(* Where the change is on this machine.

   All three shapes resolve inside the keeper's own bundle, because that is
   where the write happened. An operator's checkout of the same repository is
   a different tree and this surface does not know where it is; naming the
   keeper's copy is the answer that is true.

   A Docker keeper's bundle is not on this filesystem at all, so the path may
   not exist. The caller checks before handing it to an editor rather than
   opening an empty buffer under a real file's name. *)
let change_absolute_path ~base_path (change : Masc.Tui_decode.file_change) =
  let bundle =
    Filename.concat base_path
      (Playground_paths.bundle_root change.Masc.Tui_decode.fc_keeper)
  in
  match change.Masc.Tui_decode.fc_location with
  | Masc.Tui_decode.Fc_at_absolute_path { path } -> path
  | Masc.Tui_decode.Fc_in_bundle { bundle_path } -> Filename.concat bundle bundle_path
  | Masc.Tui_decode.Fc_in_repo { repo_id; relative_path } ->
      Filename.concat bundle
        (Playground_paths.bundle_relative_repo_path ~repo_id relative_path)

(* The address the git-diff read wants: relative to the keeper's playground,
   because that is the root the server resolves ?keeper= against. Absolute
   writes have no such address -- a worktree beside the clones is not under
   the playground -- so they have no tree reading either, and the caller is
   told rather than sent a path the server would resolve somewhere else. *)
let change_bundle_relative_path (change : Masc.Tui_decode.file_change) =
  match change.Masc.Tui_decode.fc_location with
  | Masc.Tui_decode.Fc_in_bundle { bundle_path } -> Some bundle_path
  | Masc.Tui_decode.Fc_in_repo { repo_id; relative_path } ->
      Some (Playground_paths.bundle_relative_repo_path ~repo_id relative_path)
  | Masc.Tui_decode.Fc_at_absolute_path _ -> None

(* The window the Changes surface asks for. A day is what an operator means
   by "what has this keeper been doing"; the server's own ceiling is what the
   read costs, and it clamps anything wider. *)
let changes_window_hours = 24.0

let launch_workspace_activity state ~mailbox ~repo_id =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  match Masc_tui_fetched.start ~equal:String.equal state.workspace_activity ~key:repo_id with
  | Masc_tui_fetched.Already_loading -> ()
  | Masc_tui_fetched.Started (next, request) ->
      state.workspace_activity <- next;
      let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
      let run () =
        let result = try Masc_tui_http.fetch_repository_activity ~host ~port
            ~repo_id ~window_hours:changes_window_hours
          with Eio.Cancel.Cancelled _ as exn -> raise exn
             | exn -> Error (Printexc.to_string exn) in
        let result = Result.bind result (fun snapshot ->
          if String.equal snapshot.Tui_decode.ras_repo_id repo_id then Ok snapshot
          else Error "repository activity response names another repository") in
        enqueue_async mailbox (Workspace_msg (Workspace_activity_loaded (request, result)))
      in
      match Eio_context.get_switch_opt () with
      | Some sw -> Eio.Fiber.fork_daemon ~sw (fun () -> run (); `Stop_daemon)
      | None -> enqueue_async mailbox (Workspace_msg (Workspace_activity_loaded (request, Error "Eio switch is unavailable")))
  end

let launch_file_changes_load state ~mailbox ~keeper_name =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  state.changes_inflight <- true;
  Masc_tui_transport.Workspace_admission.launch_guarded_async_read state ~mailbox
    ~deliver:(fun result ->
      enqueue_async mailbox (File_changes_loaded (keeper_name, result)))
    (Masc_tui_transport.Workspace_admission.capture_json_read state (fun () ->
      Masc_tui_loader.load_keeper_file_changes ~host ~port ~keeper_name
        ~window_hours:changes_window_hours))

  end

(* The pane's Changes tab asks for the selected keeper's changes through
   the fetch helper, so a request already in flight is not repeated and an
   answer for another keeper is dropped on arrival. *)

let launch_acting_pane_changes_load ?(force = false) state ~mailbox ~keeper_name =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  let key = { apk_keeper = keeper_name
            ; apk_scope = state.workspace_authority, state.workspace_read_authority } in
  let start =
    match force, Masc_tui_fetched.current_key state.acting_pane_changes with
    | true, _ -> Masc_tui_fetched.refresh
    | false, Some current when Masc_tui_fetched.in_flight state.acting_pane_changes
                        && not (same_acting_pane_key current key) -> Masc_tui_fetched.refresh
    | false, (Some _ | None) -> Masc_tui_fetched.start
  in
  match
    start ~equal:(if force then same_acting_pane_key else same_acting_pane_keeper)
      state.acting_pane_changes ~key
  with
  | Masc_tui_fetched.Already_loading -> ()
  | Masc_tui_fetched.Started (next, request) -> (
      state.acting_pane_changes_loss_followup <- None;
      state.acting_pane_changes <- next;
      let host = Masc_tui_transport.Workspace_admission.server_peer_host in
      let port = state.port in
      Masc_tui_transport.Workspace_admission.launch_guarded_async_read state ~mailbox
        ~deliver:(fun result ->
          enqueue_async mailbox (Acting_pane_changes_loaded (request, result)))
        (Masc_tui_transport.Workspace_admission.capture_json_read state (fun () ->
          Masc_tui_loader.load_keeper_file_changes ~host ~port ~keeper_name
            ~window_hours:changes_window_hours)))

  end

(* The Changes tab is live only while it is on screen: the pane drawn, the
   tab up, a keeper under the cursor. [refresh] asks again whatever is
   known; [ensure] asks only for a keeper never asked about, so the loop
   can call it after every input without repeating a settled fetch. *)

let acting_pane_source_current (state : state) =
  match state.acting_pane_presented.frame_source with
  | Some source when same_acting_pane_scope source.aps_scope
                       (state.workspace_authority, state.workspace_read_authority)
                     && server_authority_ready state ->
      true
  | Some _ | None -> false

let acting_pane_changes_keeper (state : state) =
  let _, cols = Masc_tui_ansi.get_terminal_size () in
  if Masc_tui_render.acting_pane_columns state ~terminal_cols:cols <= 0 then None
  else
    match state.acting_pane_tab with
    | Masc_tui_acting_pane.Tab_fleet -> None
    | Masc_tui_acting_pane.Tab_changes ->
        Option.map (fun (keeper : keeper) -> keeper.k_name) (selected_keeper state)

let refresh_acting_pane_changes ?(force = false) state ~mailbox =
  match acting_pane_changes_keeper state with
  | None -> ()
  | Some keeper_name -> launch_acting_pane_changes_load ~force state ~mailbox ~keeper_name

let ensure_acting_pane_changes state ~mailbox =
  match acting_pane_changes_keeper state with
  | None -> ()
  | Some keeper_name ->
      let key = { apk_keeper = keeper_name
                ; apk_scope = state.workspace_authority, state.workspace_read_authority } in
      if acting_pane_read_needed ~key state.acting_pane_changes then
        launch_acting_pane_changes_load state ~mailbox ~keeper_name

let launch_keeper_chat_file_changes_load ?(force = false) state ~mailbox
    ~keeper_name =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  if state.msg_tool_visibility <> Tools_full then ()
  else begin
    if
      not
        (Option.equal String.equal state.msg_file_changes_keeper
           (Some keeper_name))
    then Masc_tui_chat_input.Message_draft_recall.reset_message_file_changes state (Some keeper_name);
    if state.msg_file_changes_loading then
      if force then state.msg_file_changes_refresh_pending <- true else ()
    else if
      (Option.is_some state.msg_file_changes
       || Option.is_some state.msg_file_changes_error)
      && not force
    then ()
    else begin
      state.msg_file_changes_generation <- state.msg_file_changes_generation + 1;
      let generation = state.msg_file_changes_generation in
      state.msg_file_changes_loading <- true;
      state.msg_file_changes_refresh_pending <- false;
      let host = Masc_tui_transport.Workspace_admission.server_peer_host in
      let port = state.port in
      let read = Masc_tui_transport.Workspace_admission.capture_json_read state (fun () ->
        Masc_tui_loader.load_keeper_file_changes ~host ~port ~keeper_name
          ~window_hours:changes_window_hours) in
      let run () =
        let result =
          try (match read () with
            | Error refusal -> Error (Request_withdrawn refusal)
            | Ok result -> Result.map_error (fun detail -> Request_failed detail) result)
          with
          | Eio.Cancel.Cancelled _ as exn -> raise exn
          | exn -> Error (Request_failed (Printexc.to_string exn))
        in
        enqueue_async mailbox
          (Keeper_msg (Keeper_chat_file_changes_loaded (generation, keeper_name, result)))
      in
      match Eio_context.get_switch_opt () with
      | Some sw ->
          Eio.Fiber.fork_daemon ~sw (fun () ->
              run ();
              `Stop_daemon)
      | None ->
          enqueue_async mailbox
            (Keeper_msg (Keeper_chat_file_changes_loaded
               ( generation
               , keeper_name
               , Error (Request_failed "Eio switch is unavailable") )))
    end
  end
  end

let launch_keeper_chat_tool_details_load ?(force = false) state ~mailbox
    ~keeper_name =
  if server_authority_ready state then begin
  if state.msg_tool_visibility = Tools_compact then ()
  else begin
    launch_keeper_chat_file_changes_load ~force state ~mailbox ~keeper_name;
    Masc_tui_work_requests.Schedule_call_requests.launch_keeper_calls_load ~force state ~mailbox keeper_name
  end

  end

(* Changes follows the selected Keeper, but the surface is useful precisely
   when comparing more than one Keeper. Brackets move that shared selection
   and invalidate every row whose identity belonged to the previous Keeper;
   the stamped async response below already rejects a late answer. *)

let cycle_changes_keeper state ~mailbox ~delta =
  let count = List.length state.keepers in
  if count > 0 then begin
    let current =
      match state.changes_keeper with
      | Some keeper_name ->
          let rec find index = function
            | [] -> min state.keeper_cursor (count - 1)
            | (keeper : keeper) :: rest ->
                if String.equal keeper.k_name keeper_name
                then index
                else find (index + 1) rest
          in
          find 0 state.keepers
      | None -> min state.keeper_cursor (count - 1)
    in
    let next = (current + delta + count) mod count in
    match List.nth_opt state.keepers next with
    | None -> ()
    | Some keeper ->
        state.keeper_cursor <- next;
        state.changes_keeper <- Some keeper.k_name;
        state.changes <- None;
        state.changes_error <- None;
        state.changes_inflight <- false;
        state.changes_cursor <- 0;
        state.changes_scroll <- 0;
        state.changes_diff_row <- None;
        state.changes_diff_scroll <- 0;
        state.changes_tree_diff <- None;
        state.changes_tree_diff_error <- None;
        state.changes_tree_diff_path <- None;
        launch_file_changes_load state ~mailbox ~keeper_name:keeper.k_name
  end

(* What the tree holds for one file, against its last commit. HEAD rather
   than a branch point: the question the surface answers is "did this survive
   into the tree", and a merge base would answer a different one. *)
let launch_git_diff_load state ~mailbox ~keeper ~path =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
    ~deliver:(fun result ->
      enqueue_async mailbox (Git_diff_loaded (path, result)))
    (fun () ->
      Masc_tui_loader.load_git_diff ~host ~port ~keeper ~path
        ~against:(Masc_tui_http.Working_tree_against tree_diff_base_ref) ())
  end

let launch_harness_load state ~mailbox =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  if state.harness_inflight then ()
  else begin
    state.harness_inflight <- true;
    state.harness_owed <- Masc_tui_owed_read.started state.harness_owed;
    let host = Masc_tui_transport.Workspace_admission.server_peer_host in
    let port = state.port in
    Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
      ~on_not_run:(fun () ->
        state.harness_inflight <- false;
        state.harness_owed <- Masc_tui_owed_read.abandoned state.harness_owed)
      ~deliver:(fun result ->
        enqueue_async mailbox (Harness_msg (Harness_loaded result)))
      (fun () -> Masc_tui_loader.load_harness ~host ~port)
  end
  end

(* The Home Health line, drawn on every surface. *)
let launch_overview_load state ~mailbox =
  if server_authority_ready state && not state.overview_inflight then begin
    let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
    state.overview_inflight <- true;
    state.overview_owed <- Masc_tui_owed_read.started state.overview_owed;
    let host = Masc_tui_transport.Workspace_admission.server_peer_host in
    let port = state.port in
    Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
      ~on_not_run:(fun () ->
        state.overview_inflight <- false;
        state.overview_owed <- Masc_tui_owed_read.abandoned state.overview_owed)
      ~deliver:(fun result -> enqueue_async mailbox (Overview_loaded result))
      (fun () -> Masc_tui_loader.load_overview ~host ~port)
  end

let launch_fusion_runs_load ?(demand = Masc_tui_fusion_updates.Share) state ~mailbox =
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  if server_authority_ready state then
  match Masc_tui_fusion_updates.begin_runs state ~demand with
  | None -> ()
  | Some request ->
      let host = Masc_tui_transport.Workspace_admission.server_peer_host in
      let port = state.port in
      let read = Masc_tui_transport.Workspace_admission.capture_json_read state (fun () ->
        Masc_tui_loader.load_fusion_runs ~host ~port) in
      let run () =
        let result =
          try (match read () with
            | Error refusal -> Error (Request_withdrawn refusal)
            | Ok result -> Result.map_error (fun detail -> Request_failed detail) result) with
          | Eio.Cancel.Cancelled _ as exn -> raise exn
          | exn -> Error (Request_failed (Printexc.to_string exn))
        in
        enqueue_async mailbox (Fusion_msg (Fusion_runs_loaded (request, result)))
      in
      (match Eio_context.get_switch_opt () with
       | Some sw ->
           Eio.Fiber.fork_daemon ~sw (fun () ->
               run ();
               `Stop_daemon)
       | None ->
           enqueue_async mailbox
             (Fusion_msg (Fusion_runs_loaded
                (request, Error (Request_failed "Eio switch is unavailable")))))

let revalidate_visible_fusion state ~mailbox =
  let demand = Masc_tui_fusion_updates.After_change in
  Masc_tui_fusion_updates.revalidate_visible state
    ~runs:(fun () -> launch_fusion_runs_load ~demand state ~mailbox)
    ~detail:(fun run_id -> Masc_tui_work_actions.Detail_navigation.launch_fusion_detail_load ~demand state ~mailbox ~run_id)
    ~historical:(fun reference ->
      Masc_tui_work_actions.Detail_navigation.launch_fusion_historical_detail_load ~demand state ~mailbox ~reference)

let resume_fusion_after_observer_failure state ~mailbox =
  Masc_tui_fusion_updates.observer_failed state
    ~runs:(fun () -> launch_fusion_runs_load state ~mailbox)
    ~detail:(fun run_id -> Masc_tui_work_actions.Detail_navigation.launch_fusion_detail_load state ~mailbox ~run_id)
    ~historical:(fun reference ->
      Masc_tui_work_actions.Detail_navigation.launch_fusion_historical_detail_load state ~mailbox ~reference)

(* The server's reading of which Keepers the memory recall judgment reaches,
   asked when the [m] form opens and drawn in it. Each open takes a new
   generation, so the answer for a form the operator already left is dropped
   ([Masc_tui_types.finish_memory_recall_standing_read]). *)
(* The two requests behind the launch form. Neither is inflight-guarded by
   a field of its own: the form's state says which request it waits on, and
   the generation in the answer says whether it is still that one. *)

let launch_fusion_launch_options_load state ~mailbox =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  state.fusion_launch_generation <- state.fusion_launch_generation + 1;
  let generation = state.fusion_launch_generation in
  state.fusion_launch <- Some (Fusion_launch_reading_presets generation);
  state.fusion_scroll <- 0;
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
    ~deliver:(fun result ->
      enqueue_async mailbox (Fusion_msg (Fusion_launch_options_loaded (generation, result))))
    (fun () -> Masc_tui_loader.load_fusion_launch_options ~host ~port)

  end

(* Named apart from [Masc_tui_loader.launch_fusion_run], which it calls: one
   name for both is a shadow that turns a missing qualifier into unbounded
   recursion rather than a compile error. *)

let start_fusion_run state ~mailbox ~(request : Masc_tui_fusion_launch.request) =
  state.fusion_launch_generation <- state.fusion_launch_generation + 1;
  let generation = state.fusion_launch_generation in
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox ~boundary_error:(fun detail -> Request_failed detail)
    ~withdrawn:(fun refusal -> Request_withdrawn refusal)
    ~deliver:(fun result -> Fusion_msg (Fusion_launched (generation, result)))
    (fun () -> Masc_tui_loader.launch_fusion_run ~host ~port ~request
      |> Result.map_error (fun detail -> Request_failed detail))

let launch_lanes_load state ~mailbox =
  if server_authority_ready state then begin
  if state.standalone_lanes_inflight then ()
  else begin
    state.standalone_lanes_inflight <- true;
    state.lanes_owed <- Masc_tui_owed_read.started state.lanes_owed;
    let host = Masc_tui_transport.Workspace_admission.server_peer_host in
    let port = state.port in
    state.standalone_lanes_generation <- state.standalone_lanes_generation + 1;
    let standalone_generation = state.standalone_lanes_generation in
    Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox ~boundary_error:(fun detail -> Request_failed detail)
      ~withdrawn:(fun refusal -> Request_withdrawn refusal)
      ~deliver:(fun result -> Lane_msg (Lane_inventory_loaded (standalone_generation, result)))
      (fun () -> Masc_tui_loader.load_lane_inventory ~host ~port
        |> Masc_tui_async_read.attribute Masc_tui_async_read.Standalone_lanes
        |> Result.map_error (fun detail -> Request_failed detail))
  end

  end

(* A re-read that has to happen: a write's read-back, or the operator's [r].
   A load already out may have left before the change it has to show, so
   one more is queued behind it instead of the request being dropped. *)

let launch_lanes_reread state ~mailbox =
  if state.standalone_lanes_inflight
  then state.standalone_lanes_reread_pending <- true
  else launch_lanes_load state ~mailbox

let launch_machine_activity_read state ~mailbox owner =
  if server_authority_ready state then begin
  match Masc_tui_types.machine_activity_session state owner with
  | None -> ()
  | Some session ->
    state.machine_activity_generation <- state.machine_activity_generation + 1;
    (match Masc_tui_machine_activity.start_read ~generation:state.machine_activity_generation session with
     | None -> ()
     | Some (session, request) ->
       Masc_tui_types.put_machine_activity state session;
       let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
       let check = Masc_tui_transport.Workspace_admission.capture_admission state ~mailbox in
       Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox ~boundary_error:(fun detail -> Request_failed detail)
         ~withdrawn:(fun refusal -> Request_withdrawn refusal)
         ~deliver:(fun result -> Machine_msg (Machine_activity_read (request,result))) (fun () ->
           let document = Result.map (fun (reading : Masc_tui_runtime_config_view.reading) ->
             {Masc_tui_runtime_config_edit.path=reading.path;
              source_text=reading.source_text;source_revision=reading.metadata.source_revision})
             (Masc_tui_loader.load_runtime_config_view ~host ~port) in
           let check () = Result.map_error (fun refusal -> Request_withdrawn refusal) (check ()) in
           Result.bind (check ()
             |> Result.map_error (Masc_tui_transport.Request_notice.request_failure_after_read state ~request:Kept_request.Runtime_config_read)) (fun () ->
           let activity = Result.bind (Masc_tui_loader.load_lane_inventory ~host ~port)
             (fun snapshot ->
               match List.find_opt (fun (row : Masc.Tui_decode_lane_inventory.row) ->
                 row.selection = Machine owner.Masc_tui_machine_activity.machine) snapshot.rows with
               | Some {state=Machine_state (activity,_);_} ->
                   Ok (match activity with
                     | Machine_enabled -> Machine_configuration.Enabled
                     | Machine_disabled -> Machine_configuration.Disabled
                     | Machine_unobserved -> Machine_configuration.Unobserved)
               | None
               | Some {state=(Exact_state _ | Browser_clients _ | Package_state _);_} ->
                   Error "The selected machine is absent from the server reading.") in
           Result.map (fun () -> Masc_tui_machine_activity.{document;activity})
             (check ()
              |> Result.map_error (Masc_tui_transport.Request_notice.request_failure_after_read state ~request:Kept_request.Lanes_read)))))
  end

let launch_machine_activity_save state ~mailbox session =
  let module Activity = Masc_tui_machine_activity in
  state.machine_activity_generation <- state.machine_activity_generation + 1;
  match Activity.start_save ~generation:state.machine_activity_generation session with
  | Error notice ->
    report_action state "error"
      (Masc_tui_activity_notice.text ~ko:(state.ui_language = Lang_ko) notice)
  | Ok (session,request,write) ->
    Masc_tui_types.put_machine_activity state session;
    let authority=state.workspace_authority and identity=state.server_identity in
    Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox
      ~boundary_error:(fun detail -> `Save (Masc_tui_http.Runtime_config_save_refused detail))
      ~withdrawn:(fun refusal -> `Kept_back refusal)
      ~deliver:(fun result ->
        let result = match result with
          | Ok receipt -> Ok (Activity.Saved receipt)
          | Error (`Save (Masc_tui_http.Runtime_config_conflict current)) -> Ok (Activity.Conflict current)
          | Error (`Save (Masc_tui_http.Runtime_config_save_refused detail)) -> Ok (Activity.Refused detail)
          | Error (`Save (Masc_tui_http.Runtime_config_save_unconfirmed detail)) ->
              Ok (Activity.Unconfirmed detail)
          | Error (`Kept_back refusal) -> Error refusal in
        Machine_msg (Machine_activity_saved (request,result)))
      (fun () -> Masc_tui_surface_requests.Runtime_config_requests.save_runtime_config_text ~prior_contact:Masc_tui_server_lifecycle.Server_reached state ~mailbox ~authority ~identity
        ~expected_source_path:write.expected_source_path ~expected_source_revision:write.expected_source_revision write.source_text)

let open_machine_activity state ~mailbox machine =
  match Masc_tui_types.runtime_config_workspace state with
  | None -> report_action state "error" "Verify the workspace before editing Lane activity."
  | Some workspace ->
    let owner = {Masc_tui_machine_activity.workspace;machine} in
    if Masc_tui_types.machine_activity_session state owner=None then
      Masc_tui_types.put_machine_activity state (Masc_tui_machine_activity.create owner);
    state.exact_activity_open <- None;
    state.machine_activity_open <- Some owner;
    state.lane_run_detail_scroll <- 0;
    launch_machine_activity_read state ~mailbox owner

let launch_exact_activity_read state ~mailbox owner =
  if server_authority_ready state then begin
  match Masc_tui_types.exact_activity_session state owner with
  | None -> ()
  | Some session ->
    state.exact_activity_generation <- state.exact_activity_generation + 1;
    (match Masc_tui_exact_activity.start_read ~generation:state.exact_activity_generation session with
     | None -> ()
     | Some (session, request) ->
       Masc_tui_types.put_exact_activity state session;
       let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
       Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox ~boundary_error:(fun detail -> Request_failed detail)
         ~withdrawn:(fun refusal -> Request_withdrawn refusal)
         ~deliver:(fun result -> Exact_msg (Exact_activity_read (request,result))) (fun () ->
           Masc_tui_loader.load_runtime_config_view ~host ~port
           |> Result.map (fun (reading : Masc_tui_runtime_config_view.reading) ->
             {Masc_tui_runtime_config_edit.path=reading.path;source_text=reading.source_text;
              source_revision=reading.metadata.source_revision})
           |> Result.map_error (fun detail -> Request_failed detail)))
  end

let launch_exact_activity_save state ~mailbox session =
  let module Activity = Masc_tui_exact_activity in
  state.exact_activity_generation <- state.exact_activity_generation + 1;
  match Activity.start_save ~generation:state.exact_activity_generation session with
  | Error notice ->
    report_action state "error"
      (Masc_tui_activity_notice.text ~ko:(state.ui_language = Lang_ko) notice)
  | Ok (session,request,write) ->
    Masc_tui_types.put_exact_activity state session;
    let authority=state.workspace_authority and identity=state.server_identity in
    Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox
      ~boundary_error:(fun detail -> `Save (Masc_tui_http.Runtime_config_save_refused detail))
      ~withdrawn:(fun refusal -> `Kept_back refusal)
      ~deliver:(fun result ->
        let result = match result with
          | Ok receipt -> Ok (Activity.Saved receipt)
          | Error (`Save (Masc_tui_http.Runtime_config_conflict current)) -> Ok (Activity.Conflict current)
          | Error (`Save (Masc_tui_http.Runtime_config_save_refused detail)) -> Ok (Activity.Refused detail)
          | Error (`Save (Masc_tui_http.Runtime_config_save_unconfirmed detail)) ->
              Ok (Activity.Unconfirmed detail)
          | Error (`Kept_back refusal) -> Error refusal in
        Exact_msg (Exact_activity_saved (request,result)))
      (fun () -> Masc_tui_surface_requests.Runtime_config_requests.save_runtime_config_text ~prior_contact:Masc_tui_server_lifecycle.Server_reached state ~mailbox ~authority ~identity
        ~expected_source_path:write.expected_source_path ~expected_source_revision:write.expected_source_revision write.source_text)

let open_exact_activity state ~mailbox lane =
  match Masc_tui_types.runtime_config_workspace state with
  | None -> report_action state "error" "Verify the workspace before editing Lane activity."
  | Some workspace ->
    let owner = {Masc_tui_exact_activity.workspace;lane} in
    if Masc_tui_types.exact_activity_session state owner=None then
      Masc_tui_types.put_exact_activity state (Masc_tui_exact_activity.create owner);
    state.machine_activity_open <- None;
    state.exact_activity_open <- Some owner;
    state.lane_run_detail_scroll <- 0;
    launch_exact_activity_read state ~mailbox owner

let launch_clients_load state ~mailbox =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  if state.clients_surface_inflight then ()
  else begin
    state.clients_surface_inflight <- true;
    (* Marks the read in flight on the owed read, so the answer settles
       it rather than leaving it due for the next loop. *)
    begin_clients_read state;
    let host = Masc_tui_transport.Workspace_admission.server_peer_host in
    let port = state.port in
    state.clients_surface_generation <- state.clients_surface_generation + 1;
    let generation = state.clients_surface_generation in
    Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
      ~on_not_run:(fun () ->
        state.clients_surface_inflight <- false;
        abandon_clients_read state)
      ~deliver:(fun result ->
        enqueue_async mailbox (Clients_loaded (generation, result)))
      (fun () -> Masc_tui_loader.load_clients ~host ~port)
  end
  end

let launch_lane_runs_load ?before state ~mailbox ~(lane : Lane_run_identity.t) =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  state.lane_runs_generation <- state.lane_runs_generation + 1;
  let generation = state.lane_runs_generation in
  state.lane_runs_loading <- true;
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
    ~deliver:(fun result ->
      enqueue_async mailbox (Lane_msg (Lane_runs_loaded (lane, generation, before, result))))
    (fun () -> Masc_tui_http.fetch_lane_runs ?before ~host ~port ~lane ())
  end

let launch_lane_run_detail_load state ~mailbox ~run_id =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  state.lane_run_detail_generation <- state.lane_run_detail_generation + 1;
  let generation = state.lane_run_detail_generation in
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
    ~deliver:(fun result ->
      enqueue_async mailbox (Lane_msg (Lane_run_detail_loaded (run_id, generation, result))))
    (fun () -> Masc_tui_http.fetch_lane_run_detail ~host ~port ~run_id)

  end

(* History targets are logical observation identities. Opening one drops the
   previous list; it never requires a current configuration/installation row. *)

let open_lane_run_list state ~mailbox (lane : Lane_run_identity.t) =
  begin_lane_run_list state lane;
  launch_lane_runs_load state ~mailbox ~lane

let open_lane_run_detail state ~mailbox ~(lane : Lane_run_identity.t) ~run_id =
  state.lanes_mode <- Lanes_run_detail (lane, run_id);
  state.lane_run_detail <- None;
  state.lane_run_detail_error <- None;
  state.lane_run_detail_scroll <- 0;
  state.lane_run_preflight_details <- false;
  state.lane_run_detail_content_height <- 0;
  launch_lane_run_detail_load state ~mailbox ~run_id

(* The run under the list cursor. Enter opens it from the list, and [ and ]
   reopen through it after moving the cursor under an open detail, so a step
   reads everything an open reads. *)
let open_selected_lane_run state ~mailbox ~(lane : Lane_run_identity.t) =
  match
    Option.bind state.lane_runs (fun runs ->
      List.nth_opt runs state.lane_runs_cursor)
  with
  | Some (run : Tui_decode.lane_run_summary) ->
      open_lane_run_detail state ~mailbox ~lane ~run_id:run.lrs_run_id
  | None -> ()

(* Back from a run's detail to the list it was opened from. [ and ] move the
   list cursor while the detail covers the list, so the window is brought to
   the cursor here; without it the list came back showing the rows around the
   run that was opened first, with no selected row on screen. *)
let close_lane_run_detail state ~(lane : Lane_run_identity.t) =
  state.lanes_mode <- Lanes_run_list lane;
  state.lane_run_detail <- None;
  state.lane_run_detail_error <- None;
  state.lane_run_detail_scroll <- 0;
  match scrolled_surface state state.view with
  | None -> ()
  | Some scrolled ->
      let height = surface_body_height ~rows:(surface_rows state) scrolled in
      state.lane_runs_scroll <-
        Masc_tui_scroll.ensure_visible ~cursor:state.lane_runs_cursor ~height
          state.lane_runs_scroll

let launch_measurement_artifact_load state ~mailbox ~sha256 =
  if server_authority_ready state then begin
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  state.lane_run_detail_generation <- state.lane_run_detail_generation + 1;
  let generation = state.lane_run_detail_generation in
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
    ~deliver:(fun result ->
      enqueue_async mailbox (Measurement_artifact_loaded (sha256, generation, result)))
    (fun () -> Masc_tui_http.fetch_measurement_artifact ~host ~port ~sha256)
  end

let open_measurement_artifact state ~mailbox ~sha256 =
  state.lanes_mode <- Lanes_measurement_detail sha256;
  state.measurement_report <- None;
  state.lane_run_detail_error <- None;
  state.lane_run_detail_scroll <- 0;
  state.lane_run_detail_content_height <- 0;
  launch_measurement_artifact_load state ~mailbox ~sha256

(* Everything that names a row stops meaning anything when the surface moves
   to another page or another list: the cursor, the scroll, the open detail
   and a half-armed approve all point at rows this surface is about to stop
   holding. The arm in particular must go -- a second press landing on a row
   that arrived from a different page would approve a task the operator never
   looked at. *)
let reset_verification_rows state =
  state.verification_cursor <- 0;
  state.verification_scroll <- 0;
  Masc_tui_work_actions.Verification_actions.cancel_verification_evidence_load state
    ~reason:(Verification_evidence_read.Interrupted "The original verification detail was closed.");
  state.verification_detail_request_id <- None;
  state.verification_detail_scroll <- 0;
  state.verification_verdict_armed <- None;
  state.verification_verdict_error <- None;
  state.verification_verdict_inflight <- None

let launch_verification_load state ~mailbox =
  if server_authority_ready state then begin
  if state.verification_inflight then ()
  else begin
    state.verification_inflight <- true;
    state.verification_owed <- Masc_tui_owed_read.started state.verification_owed;
    let host = Masc_tui_transport.Workspace_admission.server_peer_host in
    let port = state.port in
    (* Read once, here, rather than inside the fiber: the operator can press
       another view key while this load is in flight, and the answer that
       arrives must be the one that was asked for. *)
    let view = state.verification_view in
    let offset = state.verification_offset in
    Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox ~boundary_error:(fun detail -> Request_failed detail)
      ~withdrawn:(fun refusal -> Request_withdrawn refusal)
      ~deliver:(fun result -> Verification_msg (Verification_loaded result))
      (fun () -> Masc_tui_loader.load_verification ~host ~port ~limit:200 ~view ~offset
        |> Result.map_error (fun detail -> Request_failed detail))
  end
  end

(* One surface's row list: how many rows it has, which one the cursor is on,
   and how to put the cursor somewhere else.

   These three facts lived in three separate exhaustive matches over
   [surface], each naming every variant so the compiler would flag a new one.
   Naming is not agreeing: the Keeper detail's context inspector had a
   landing and searchable rows but no cursor reading, so [n] and [N] restarted
   from the first row every press. A fourth match -- the count Home and End
   need -- would have been a fourth chance to drift, so the three are one
   record built in one place instead.

   [None] is a surface with no row cursor, or one whose rows only exist once
   the frame is built. Those keep the keys they already have: Activity has g
   and G, the Keeper log and the Tools readings have their own Home and End.
   The two Tools lists walk a selection rather than a row of the page, so
   [Masc_tui_list_moves] moves them itself. *)
type row_list = Masc_tui_list_moves.row_list = {
  rl_count : int;
  rl_cursor : int;
  rl_place : int -> unit;
}

(* The list a surface draws: its row cursor, and the list it is, whose
   drawn height the frame reports and a page key moves by (RFC
   tui-one-screen-grammar §3.1). *)
type on_screen = Masc_tui_list_moves.on_screen = {
  os_list : paged_list;
  os_rows : row_list option;
}

(* The task whose detail is on screen, which is not the same as a detail id
   being set: [render_surface] falls back to the list when the id names a row
   the backlog no longer holds -- after an archived task link, or a refresh
   that removed it. Asking the renderer's own question here keeps Home and End
   on the surface the reader is looking at; a stale id used to send both keys
   into a scroll nothing was drawing while the visible list refused them. *)
let task_detail_on_screen (state : state) =
  Masc_tui_task_selection.detail_row ~detail_id:state.task_detail_id
    ~tasks:(Masc_tui_types.task_domain_values state)


let list_on_screen (state : state) : on_screen option =
  let terminal_rows, cols = get_terminal_size () in
  (* The window follows a named row the same way it follows a step, through
     [surface_body_height] rather than [rows - sc_chrome]: a surface that
     gives half its rows to a preview says so in [sc_preview_keep], and a
     height that ignores it lands the cursor under the preview while
     [ensure_visible] reports the row as already on screen. *)
  let follow ?(lead = 0) ~cursor scroll set_scroll =
    match scrolled_surface state state.view with
    | None -> ()
    | Some scrolled ->
        let height = surface_body_height_at state ~cursor scrolled in
        set_scroll (Masc_tui_scroll.ensure_visible_with_lead ~cursor ~lead ~height scroll)
  in
  let listed list rows = Some { os_list = list; os_rows = Some rows } in
  (* A list whose rows the drawing windows around the cursor: nothing to
     scroll, so the landing is on screen as soon as the cursor names it. *)
  let windowed list ~count ~cursor place =
    listed list { rl_count = count; rl_cursor = cursor; rl_place = place }
  in
  (* A list with a scroll of its own, which follows the cursor. Its count is
     the one the keypress bound already uses, so a jump cannot land on a row
     a step cannot reach. *)
  let scrolling list ~cursor ~scroll ~set_cursor ~set_scroll =
    Option.bind (scrolled_surface state state.view) (fun scrolled ->
      listed list
        { rl_count = scrolled.sc_count
        ; rl_cursor = cursor
        ; rl_place =
            (fun index ->
              set_cursor index;
              follow ~cursor:index scroll set_scroll)
        })
  in
  (* The Git changes overlay before the surface it is drawn over, the way
     [Masc_tui_surface_search.surface_row_texts] answers it: it draws over Keepers as well as
     Repositories and Code, and an arm per surface left the Keepers host
     naming the roster cursor while the overlay was the list on screen. A key
     that landed there moved a cursor nobody could see. The diff replaces the
     list, and what it draws follows [repository_changes_diff_scroll] rather
     than a row. *)
  if state.context_inspector_open then
    if state.context_inspector_tab = Masc_tui_context_inspector.Exact_input
       && Option.is_none state.context_inspector_exact then
      Option.bind state.context_inspector_reading (fun (_, reading) ->
        Option.bind (Masc_tui_context_inspector.observed_input reading) (fun input ->
          let count = List.length (Masc_tui_context_inspector.exact_input_items input) in
          if count = 0 then None else
            windowed Context_inspector_items ~count ~cursor:state.context_inspector_cursor
              (fun index ->
              state.context_inspector_cursor <- index;
              state.context_inspector_detail_scroll <- 0)))
    else None
  else if state.repository_changes_open then
    (match state.repository_changes_diff_path with
     | Some _ -> None
     | None ->
         scrolling Repository_change_rows ~cursor:state.repository_changes_cursor
           ~scroll:state.repository_changes_scroll
           ~set_cursor:(fun i -> state.repository_changes_cursor <- i)
           ~set_scroll:(fun s -> state.repository_changes_scroll <- s))
  else
  match state.view with
  | Keepers Keeper_list ->
      (* Search chooses a Keeper row, which a folded group opens to show.
         The move keys walk the stops instead ([list_moves]), a page of the
         stops the frame drew. *)
      windowed Keeper_stops ~count:(List.length state.keepers) ~cursor:state.keeper_cursor
        (choose_keeper_row state)
  | Lanes ->
      (match state.lanes_mode with
       (* Follow the cursor explicitly on jumps and moves while drawing also
          keeps it visible after viewport resize. *)
       | Lanes_run_list _ ->
           scrolling Lane_runs ~cursor:state.lane_runs_cursor ~scroll:state.lane_runs_scroll
             ~set_cursor:(fun i -> state.lane_runs_cursor <- i)
             ~set_scroll:(fun s -> state.lane_runs_scroll <- s)
       | Lanes_run_detail _ | Lanes_measurement_detail _ | Lanes_inventory_detail _ -> None
       | Lanes_overview ->
           listed Lane_inventory
             {rl_count=lanes_inventory_count state;rl_cursor=state.lanes_cursor;
              rl_place=(fun index ->
                   if index <> state.lanes_cursor then
                     Masc_tui_types.dismiss_runtime_lane_notice state;
                   state.lanes_action_error <- None;
                   select_inventory_lane state index;
                   Option.iter (fun cursor ->
                     follow ~lead:(lane_inventory_lead state) ~cursor state.lanes_scroll
                       (fun scroll -> state.lanes_scroll <- scroll))
                     (lane_inventory_visual_cursor state))})
  | Clients ->
      scrolling Client_rows ~cursor:state.clients_surface_cursor
        ~scroll:state.clients_surface_scroll
        ~set_cursor:(fun i -> state.clients_surface_cursor <- i)
        ~set_scroll:(fun s -> state.clients_surface_scroll <- s)
  | Verification ->
      scrolling Verification_rows ~cursor:state.verification_cursor
        ~scroll:state.verification_scroll
        ~set_cursor:(fun i -> state.verification_cursor <- i)
        ~set_scroll:(fun s -> state.verification_scroll <- s)
  | Harness ->
      scrolling Harness_rows ~cursor:state.harness_cursor
        ~scroll:state.harness_scroll
        ~set_cursor:(fun i -> state.harness_cursor <- i)
        ~set_scroll:(fun s -> state.harness_scroll <- s)
  | Memory ->
      if Option.is_some state.memory_facts_keeper then
        scrolling Memory_fact_rows ~cursor:state.memory_facts_cursor
          ~scroll:state.memory_facts_scroll
          ~set_cursor:(fun i -> state.memory_facts_cursor <- i)
          ~set_scroll:(fun s -> state.memory_facts_scroll <- s)
      else
        scrolling Memory_keepers ~cursor:state.memory_health_cursor
          ~scroll:state.memory_health_scroll
          ~set_cursor:(fun i -> state.memory_health_cursor <- i)
          ~set_scroll:(fun s -> state.memory_health_scroll <- s)
  | Repositories ->
      scrolling Repository_rows ~cursor:state.repositories_cursor
        ~scroll:state.repositories_scroll
        ~set_cursor:(fun i -> state.repositories_cursor <- i)
        ~set_scroll:(fun s -> state.repositories_scroll <- s)
  | Connectors ->
      scrolling Connector_rows ~cursor:state.connectors_cursor
        ~scroll:state.connectors_scroll
        ~set_cursor:(fun i -> state.connectors_cursor <- i)
        ~set_scroll:(fun s -> state.connectors_scroll <- s)
  | Runtime ->
      scrolling Runtime_rows ~cursor:state.runtime_cursor
        ~scroll:state.runtime_surface_scroll
        ~set_cursor:(fun i ->
          (* The lane editor's line is about the row the key acted on. *)
          if i <> state.runtime_cursor then
            Masc_tui_types.dismiss_runtime_lane_notice state;
          state.runtime_cursor <- i)
        ~set_scroll:(fun s -> state.runtime_surface_scroll <- s)
  | System_logs ->
      scrolling System_log_rows ~cursor:(system_logs_page state).lp_cursor
        ~scroll:(system_logs_page state).lp_scroll
        ~set_cursor:(fun i -> edit_system_logs_page state (fun page -> {page with lp_cursor=i}))
        ~set_scroll:(fun s -> edit_system_logs_page state (fun page -> {page with lp_scroll=s}))
  | Changes ->
      scrolling Change_rows ~cursor:state.changes_cursor
        ~scroll:state.changes_scroll
        ~set_cursor:(fun i -> state.changes_cursor <- i)
        ~set_scroll:(fun s -> state.changes_scroll <- s)
  | Code ->
      (* Two panes left once the overlay is answered above: the open file,
         which carries its own pane height, and the tree everything else hangs
         off, which windows itself around the cursor. *)
      if
        state.code_focus_file = Right_pane && not state.code_history_open
        && not state.code_diff_open && not state.code_notes_open
      then
        (match Masc_tui_fetched.current state.code_file with
         | Some (_, Masc_tui_fetched.Ready { cfd_rows = rows; _ }) ->
             listed Code_file_lines
               { rl_count = Array.length rows
               ; rl_cursor = state.code_file_cursor
               ; rl_place =
                   (fun index ->
                     state.code_file_cursor <- index;
                     state.code_file_scroll <-
                       Masc_tui_scroll.ensure_visible ~cursor:index
                         ~height:(Masc_tui_render_code.code_pane_content_height state)
                         state.code_file_scroll)
               }
         (* Nothing to move through while the file is still being read, and
            nothing to move through if it failed. *)
         | Some (_, (Masc_tui_fetched.Loading | Masc_tui_fetched.Stale _ | Masc_tui_fetched.Failed _))
         | Some (_, Masc_tui_fetched.Absent)
         | None -> None)
      else
        windowed Code_tree_entries ~count:(List.length (code_entries state))
          ~cursor:state.code_cursor (fun index -> state.code_cursor <- index)
  | Board ->
      (match state.board_mode with
       | Board_read _ | Board_compose -> None
       | Board_list ->
           windowed Board_post_rows ~count:(List.length (board_posts state))
             ~cursor:state.board_cursor (fun index -> state.board_cursor <- index))
  | Planning ->
      (match state.planning_mode with
       | Planning_detail _ -> None
       | Planning_list
         when Masc_tui_overview_tasks.is_focused state.task_focus ->
           if Option.is_some (task_detail_on_screen state) then None
           else
             let rows = Masc_tui_overview_tasks.work_rows state.tasks in
             let cursor =
               Option.value ~default:0
                 (Masc_tui_overview_tasks.work_selected_index state.tasks
                    ~selected:(Masc_tui_overview_tasks.selection state.task_focus))
             in
             windowed Task_entries ~count:(List.length rows) ~cursor
               (fun index ->
               task_list_user_focus state
                 (Masc_tui_overview_tasks.Task_focus
                   { selected =
                       Option.map (fun (task : Tui_decode.task) -> task.id)
                         (List.nth_opt rows index) }))
       | Planning_list ->
           let count =
             match state.planning with
             | None -> 0
             | Some snapshot ->
                 List.length
                   (planning_visible_goals ~filter:state.planning_filter
                      ~sort:state.planning_sort snapshot.pl_goals)
           in
           windowed Goal_entries ~count ~cursor:state.planning_cursor
             (fun index -> state.planning_cursor <- index))
  (* Three lists that carry no row search yet (#35306). Home, End and the
     page keys reach them through here, which is what makes these arms live
     rather than a landing nobody calls. *)
  | Approvals ->
      windowed Approval_items ~count:(List.length (Masc_tui_approvals_model.approval_items state))
        ~cursor:state.approval_cursor (fun index -> state.approval_cursor <- index)
  | Schedules ->
      (match Masc_tui_work_actions.Board_schedule_actions.schedule_detail_on_screen state with
       | Some _ -> None
       | None ->
           let count =
             match state.schedules with
             | None -> 0
             | Some snapshot -> List.length snapshot.scs_rows
           in
           windowed Schedule_rows ~count ~cursor:state.schedule_cursor
             (fun index -> state.schedule_cursor <- index))
  | Fusion ->
      (match state.fusion_mode with
       | Fusion_detail _ | Fusion_historical_detail _ -> None
       | Fusion_list ->
           windowed Fusion_entries
             ~count:(List.length (Masc_tui_fusion_model.fusion_list_entries state))
             ~cursor:state.fusion_cursor (fun index -> state.fusion_cursor <- index))
  (* The list pane draws its window around the cursor rather than holding a
     scroll of its own, so a landing is on screen the moment the cursor names
     it. With the text focused j/k scrolls the reading instead and there is no
     row to land on -- the same condition [Masc_tui_surface_search.surface_row_texts] reads. *)
  | Resources ->
      (match state.resource_focus, visible_resources state with
       | Right_pane, _ | _, None -> None
       | Left_pane, Some rows ->
           windowed Resource_entries ~count:(List.length rows) ~cursor:state.resources_cursor
             (fun index -> state.resources_cursor <- index))
  (* Under the Actions and Everything filters the ring is read by a cursor,
     not by a scroll: [render_acting] recomputes the scroll from
     [acting_cursor] every frame and reports both back, so a key that moved
     only the scroll was undone before it was drawn. The Turns filter has no
     cursor and stays a reading. *)
  | Acting
    when Option.is_none state.acting_detail
         && state.acting_filter <> Masc_tui_acting.Turns ->
      windowed Activity_events
        ~count:(List.length (acting_flat_entries state))
        ~cursor:state.acting_cursor
        (fun index ->
          state.acting_cursor <- index;
          (* Landing on the newest row means the rows above it have been seen --
             the rule j/k and the g binding already apply. Left out, Home drew
             the newest row while the header still claimed there were new events
             above and prompted (g) for them. *)
          if index = 0 then state.acting_unseen <- 0)
  (* Same shape on the Runs tab: the drawing pulls [detail_scroll] to whatever
     [keeper_run_cursor] names, which is why j and k move the cursor and set
     the scroll to it. An edge jump has to name a run for the same reason. *)
  | Keepers Keeper_detail
    when state.detail_tab = Detail_runs && not state.context_inspector_open ->
      let runs = List.length (Masc_tui_fusion_model.selected_keeper_runs state) in
      windowed Keeper_runs ~count:runs ~cursor:state.keeper_run_cursor
        (fun index ->
        state.keeper_run_cursor <- index;
        state.detail_scroll <- index)
  (* The Identity tab is read by a cursor too, and the drawing keeps the
     cursor's row in view, so an edge jump names a service. *)
  | Keepers Keeper_detail
    when state.detail_tab = Detail_identity && not state.context_inspector_open ->
      (match state.identity_view with
       | None -> None
       | Some (_, providers) ->
         let listing = Masc_tui_identity_input.current_listing state in
         windowed Identity_services
           ~count:(List.length (Masc_tui_identity_model.identity_connectable ~listing providers))
           ~cursor:
             (Masc_tui_identity_model.identity_cursor_clamped ~listing ~providers
                state.identity_cursor)
           (fun index -> state.identity_cursor <- index))
  (* Overview's move keys select a destination ([Masc_tui_home.home_move])
     rather than move a cursor, so it hands over only the list it is. *)
  | Overview -> Some { os_list = Overview_destinations; os_rows = None }
  (* The models table is read by a cursor [e] acts on. The stored scroll is
     the window the cursor settled, so a key inside the window moves only
     the mark, and the column names stay on screen until the selection
     passes the first window. *)
  | Config when state.config_pane = Config_models ->
      Option.map (fun (list : Masc_tui_render_config.models_list) ->
        { os_list = Model_bindings
        ; os_rows =
            Some
              { rl_count = list.ml_count
              ; rl_cursor = state.config_models_cursor
              ; rl_place =
                  (fun index ->
                    state.config_models_cursor <- index;
                    state.config_scroll <- list.ml_window ~cursor:index state.config_scroll)
              } })
        (Masc_tui_render_config.config_models_list state ~terminal_rows ~cols)
  (* Named rather than caught. A surface that grows a row cursor is added
     above in one place, and a [_] here would let it be forgotten silently --
     which is how the context inspector came to have a landing with no
     reading. *)
  (* The Skill list and the async request list walk their selection rather
     than a row, and read their page where they walk it
     ([Masc_tui_list_moves.moves]). *)
  | Acting | Metrics | Keepers Keeper_detail | Keepers Keeper_logs
  | Keepers Keeper_calls | Keepers Keeper_message | Keepers Keeper_runtime_pick
  | Config | Tools ->
      None

let row_list (state : state) : row_list option =
  Option.bind (list_on_screen state) (fun list -> list.os_rows)

(* The reading pane on screen, when one is: a pane whose rows the drawing
   formats -- a post and its comments, a keeper's detail, a diff -- rather
   than rows the state can count. Named as the {!Masc_tui_types.clamped_scroll}
   it reports back through, so Home and End write the field the frame then
   corrects: End names a row past any real end and the frame says where that
   landed.

   Home is 0 and End is the far end for every pane here, and that one rule
   reads correctly whichever way a pane is ordered. A log-shaped pane counts
   rows back from the newest, so its 0 is now and its far end is the oldest
   row it holds -- which is how Keeper logs has read since it was written.

   Named rather than caught, like [row_list]: a surface that grows a reading
   pane is added here once, and a [_] would let one be forgotten. That is how
   these came to have no way to reach their own ends -- a post with three
   hundred comments took a page key held down, and the way back up took it
   held down again. *)
let reading_pane (state : state) ~cols : (int -> Masc_tui_types.clamped_scroll) option
    =
  let pane f = Some f in
  match state.view with
  (* The Git changes reader draws over whichever surface opened it, so it
     answers before the surface underneath does. Its list is not a reading
     pane: [row_list] has it. *)
  | _ when state.repository_changes_open ->
      (match state.repository_changes_diff_path with
       | Some _ -> pane (fun v -> Repository_changes_diff_scroll v)
       | None -> None)
  | Acting ->
      (match state.acting_detail with
       | Some _ -> pane (fun v -> Acting_detail_scroll v)
       (* The ring itself reads newest first, so Home is now. [g] already
          says that; this gives the key every other reader uses. Only under
          the Turns filter: the other two are read by a cursor and [row_list]
          has them. *)
       | None when state.acting_filter = Masc_tui_acting.Turns ->
           pane (fun v -> Acting v)
       | None -> None)
  (* The Terminal reads like scrollback: Home is the oldest output it kept and
     End the newest, where it follows again. It counts rows back from the
     newest, so Home's 0 names the far end and End's far end names 0. *)
  | Keepers Keeper_detail
    when (not state.context_inspector_open) && state.detail_tab = Detail_terminal ->
      pane (fun edge ->
        Keeper_terminal_scroll (if edge = 0 then Masc_tui_types.clamped_scroll_end else 0))
  (* Except with the context inspector open, where the body is that tab's
     item list and [row_list] owns the cursor -- and except on the Runs and
     Identity tabs, where the drawing follows a cursor and [row_list] has it. *)
  | Keepers Keeper_detail
    when (not state.context_inspector_open)
         && state.detail_tab <> Detail_runs
         && state.detail_tab <> Detail_identity ->
      pane (fun v -> Keeper_detail v)
  | Keepers Keeper_calls -> pane (fun v -> Keeper_calls v)
  | Approvals ->
      if state.approval_detail_open then
        pane (fun v -> Approval_detail_scroll (v, None))
      else None
  | Board ->
      (match state.board_mode with
       | Board_read _ when Masc_tui_types.board_read_focus state ~cols = Right_pane ->
           pane (fun v ->
             if state.board_comments_focused then
               Board_read (state.board_scroll, v)
             else Board_read (v, state.board_comment_scroll))
       | Board_read _ | Board_list | Board_compose -> None)
  | Planning ->
      (match state.planning_mode with
       | Planning_detail _ when Option.is_some (Masc_tui_work_actions.Goal_actions.goal_detail_on_screen state) ->
           pane (fun v -> Planning_detail_scroll v)
       | Planning_detail _ -> None
       (* The id alone is not the screen: one that names a task the backlog
          dropped draws the list, and [row_list] owns that. *)
       | Planning_list
         when Masc_tui_overview_tasks.is_focused state.task_focus
              && Option.is_some (task_detail_on_screen state) ->
           pane (fun v -> Task_detail (v, None))
       | Planning_list -> None)
  | Fusion ->
      (match state.fusion_mode with
       | Fusion_detail _ | Fusion_historical_detail _ ->
           pane (fun v -> Fusion_detail_scroll v)
       | Fusion_list -> None)
  | Schedules ->
      if Option.is_some (Masc_tui_work_actions.Board_schedule_actions.schedule_detail_on_screen state) then
        pane (fun v -> Schedule_detail_scroll v)
      else None
  | Verification ->
      if Option.is_some state.verification_detail_request_id then
        pane (fun v -> Verification_detail_scroll v)
      else None
  | Harness ->
      (match state.harness_detail with
       | Some _ -> pane (fun v -> Harness_detail_scroll v)
       | None -> None)
  | Runtime ->
      (match state.runtime_detail_target with
       | Some _ -> pane (fun v -> Runtime_detail_scroll v)
       | None -> None)
  | System_logs ->
      (match (system_logs_page state).lp_detail_seq with
       | Some _ -> pane (fun v -> System_log_detail_scroll v)
       | None -> None)
  | Lanes ->
      (match state.lanes_mode with
       | Lanes_run_detail _ | Lanes_measurement_detail _ | Lanes_inventory_detail _ ->
           pane (fun scroll ->
             Lane_run_detail_scroll
               { scroll; content_height = state.lane_run_detail_content_height })
       | Lanes_run_list _ | Lanes_overview -> None)
  | Changes ->
      (match state.changes_diff_row with
       | Some _ -> pane (fun v -> Changes_diff_scroll v)
       | None -> None)
  (* Two panes read this way and still answer no, each for a reason of its
     own rather than for want of an arm.

     The chat scroll is pinned to a row it anchors on across live appends,
     and the history behind it is paged in from the server -- so the far end
     is not a row the client holds, and naming one past what is loaded would
     ask the pin to settle on a row that has not arrived.

     The chat scroll is the one left. *)
  | Keepers Keeper_message -> None
  (* Metrics was here for want of a report, and that reason had gone stale:
     [render_metrics] already answers [Metrics_scroll] through
     [surface_chrome]'s [Self_scrolled] overflow, so the generic End sentinel is
     corrected after drawing exactly as the other reading panes are. *)
  | Metrics -> pane (fun scroll ->
      Metrics_scroll { scroll; content_height = state.metrics_content_height;
                       card_rows = state.metrics_scroll_card_rows })
  (* The voice pane is lines the frame lays out; its wizard takes its own keys
     while open. *)
  | Config when state.config_pane = Config_voice -> pane (fun v -> Voice_scroll v)
  | Config when state.config_pane = Config_params ->
      pane (fun scroll ->
        Runtime_params_scroll { scroll; max_scroll = state.config_document_max_scroll })
  | Config when state.config_pane = Config_presets ->
      pane (fun scroll ->
        Preset_detail_scroll
          { scroll; max_scroll = state.config_document_max_scroll; confirmation = None })
  (* Surfaces whose whole body is a row list, which [row_list] answers for,
     and the two panes that own every key while they are open. *)
  | Keepers Keeper_detail | Keepers Keeper_list | Keepers Keeper_logs
  | Keepers Keeper_runtime_pick | Memory | Repositories | Clients
  | Connectors | Code | Config | Resources | Tools ->
      None
  (* A fixed summary that fits its frame: nothing on it scrolls. *)
  | Overview -> None


let move_resource_document state movement =
  let _, cols = get_terminal_size () in
  let count, height = Masc_tui_render_resources.document_viewport state
      ~rows:(surface_rows state) ~cols in
  state.resource_scroll <- Masc_tui_scroll.Position.move ~count ~height
      movement state.resource_scroll

let page_resource_document state direction =
  let _, cols = get_terminal_size () in
  let count, height = Masc_tui_render_resources.document_viewport state
      ~rows:(surface_rows state) ~cols in
  state.resource_scroll <- Masc_tui_scroll.Position.move ~count ~height
    (Masc_tui_scroll.Position.By (direction * Masc_tui_scroll.page_step ~height))
    state.resource_scroll

(* Move the active surface's row cursor to the next row whose search text
   contains [query], scanning from [after] and wrapping; [backwards] walks
   the other way. A miss moves nothing. The searched list is the one
   [Masc_tui_surface_search.surface_row_texts] answers -- the same list the row cursor names -- and
   the window follows the landing so the match is visible. *)
let search_row_cursor state =
  if state.view = Resources && state.resource_focus = Right_pane
     && not state.context_inspector_open && not state.repository_changes_open
  then Some (Masc_tui_resource_reading.cursor state.resource_search_position)
  else Option.map (fun r -> r.rl_cursor) (row_list state)

let place_row_cursor state index =
  Option.iter (fun r -> r.rl_place index) (row_list state)

(* The list the six move keys walk (RFC tui-one-screen-grammar §3.1). The
   choice lives in [Masc_tui_list_moves], which a test links; this only hands
   it the surface's rows and the Tools follow, which need the frame's
   geometry. *)
(* The window follows the selection a Tools move key landed on
   ([Masc_tui_render_tools.follow]). *)
let follow_tools_list (state : state) list =
  let terminal_rows, cols = get_terminal_size () in
  let display = Masc_tui_render_tools.tools_display ~cols ~terminal_rows state in
  let landing =
    match list with
    | Masc_tui_list_moves.Tools_skills -> Masc_tui_render_tools.skill_landing state display
    | Tools_async_requests -> Masc_tui_render_tools.request_landing state display
  in
  match landing, scrolled_surface state state.view with
  | Some landing, Some scrolled ->
      let height = surface_body_height_at state ~cursor:landing.entry.first_row scrolled in
      tools_task_user_scroll state
        (Masc_tui_render_tools.follow landing ~height state.tools_scroll)
  | None, _ | Some _, None -> ()

(* The selection of the Tools list on screen, brought into view where the
   window may have left it: arriving on the pane, back from an open request,
   or after a read moved the selection. A reading has no selection and keeps
   its scroll. *)
let follow_tools_selection (state : state) =
  if state.view = Tools then
    Option.iter (follow_tools_list state) (Masc_tui_list_moves.tools_list state)

(* Where f leaves the page it opens: the chosen Composition's performance
   card at the top of the window. The renderer draws it under the Skill list
   and says where ([card]); the card grows downward as the measurements
   arrive, so its first row stays put. With no card drawn, the selected
   Skill's own rows take its place. *)
let tools_performance_card_top (state : state) =
  let terminal_rows, cols = get_terminal_size () in
  let display = Masc_tui_render_tools.tools_display ~cols ~terminal_rows state in
  match display.card, display.cursor with
  | Some { first_row; _ }, (Some _ | None) | None, Some { first_row; _ } -> first_row
  | None, None -> 0
let list_moves (state : state) =
  Masc_tui_list_moves.moves state ~on_screen:(fun () -> list_on_screen state)
    ~follow:(follow_tools_list state)

(* A move key on the list on screen. A page key names no page of its own:
   the list's drawn height decides it. *)
let move_list (state : state) (key : Masc_tui_scroll.key_move) =
  Option.iter (fun moves -> moves key) (list_moves state)


(* Standalone rows never scroll, so an action notice only has to be retained
   until movement or navigation clears it. *)
let show_lanes_action_error state detail =
  state.lanes_action_error <- Some detail

let search_jump ?(backwards = false) state ~query ~after =
  let query = surface_search_query state.view query in
  let _, cols = get_terminal_size () in
  match Masc_tui_surface_search.surface_row_texts ~cols state state.view with
  | None -> ()
  | Some texts ->
      (* Into an array before the scan, not walked per index. The scan visits
         every row once and [List.nth_opt] walked to each from the front, so a
         query that matched nothing cost the list squared: on a twenty-
         thousand-line file open on the Code surface, one keystroke took about
         a third of a second, and the search runs on every keystroke. *)
      let texts = Array.of_list texts in
      let total = Array.length texts in
      if String.length query > 0 && total > 0 then begin
        let matches index =
          Masc_tui_pick_list.lowercase_contains ~needle:query texts.(index)
        in
        let rec scan step =
          if step > total then ()
          else begin
            let index =
              if backwards then (after - step + (total * 2)) mod total
              else (after + step + total) mod total
            in
            if matches index then begin
              if state.view = Lanes then begin
                state.lanes_action_error <- None;
                Masc_tui_types.dismiss_runtime_lane_notice state
              end;
              if state.view = Resources && state.resource_focus = Right_pane
                 && not state.context_inspector_open && not state.repository_changes_open
              then Masc_tui_resources_updates.place_search_match state
                ~cols:(resource_content_cols state ~cols) ~query ~count:total ~index
              else place_row_cursor state index
            end
            else scan (step + 1)
          end
        in
        scan 1
      end

(* Reads the palette rather than taking a colour, so every caller sends
   whatever is in force at the moment it asks -- picking a scheme, dropping
   one, and the first paint all go through the same answer.

   Gated on the reader's own pick rather than on the palette alone. The
   palette is also what the terminal answered about itself, and sending a
   terminal its own colours back is masc claiming an opinion it does not
   have. It read as harmless while only the page travelled; the sixteen
   make it a round trip through masc's 8-bit parse of a reply a terminal
   may have given at 16. *)
let sync_theme_page state =
  Frame_presenter.sync_scheme ~write:Masc_tui_terminal_out.write
    ~flush:Masc_tui_terminal_out.flush
    (match state.theme_choice with
     | None -> None
     | Some _ ->
       Option.map
         (fun palette ->
           { Frame_presenter.foreground =
               Masc_tui_terminal_palette.foreground palette
           ; background = Masc_tui_terminal_palette.background palette
           ; ansi =
               Array.init Masc_tui_terminal_palette.ansi_slot_count
                 (Masc_tui_terminal_palette.ansi palette)
           })
         (Masc_tui_terminal_palette.current ()))

(* Esc, and leaving the pane. Restoring goes through the same two calls a
   pick does, so a preview cannot leave the screen and the background
   disagreeing. *)
let cancel_theme_preview state =
  match state.theme_before_preview with
  | None -> ()
  | Some previous ->
    state.theme_before_preview <- None;
    (match previous with
     (* See Masc_tui_theme_choice.apply: [previous] was applied successfully. *)
     | Some name -> ignore (Masc_tui_theme_choice.apply name : bool)
     | None -> Masc_tui_theme_choice.follow_terminal ());
    state.theme_choice <- previous;
    sync_theme_page state

(* Live preview, the way a theme picker is expected to work: moving the
   cursor draws in that scheme so the reader judges it on the screen they
   actually use, Enter keeps it, Esc puts back whatever was in force before
   they walked in.

   The scheme in force is remembered on the first preview rather than on
   entering the pane: entering and leaving without moving should cost
   nothing, and there is no "they might" to record. *)
let filtered_theme_entries state =
  let all = Masc_tui_theme_choice.entries () in
  match state.theme_filter with
  | `All -> all
  | `Dark ->
      List.filter (fun (e : Masc_tui_theme_choice.entry) -> not e.light) all
  | `Light -> List.filter (fun (e : Masc_tui_theme_choice.entry) -> e.light) all

let preview_theme_under_cursor state =
  if state.theme_before_preview = None
  then state.theme_before_preview <- Some state.theme_choice;
  match List.nth_opt (filtered_theme_entries state) state.theme_cursor with
  | None -> ()
  | Some entry ->
    if Masc_tui_theme_choice.apply entry.Masc_tui_theme_choice.name
    then begin
      state.theme_choice <- Some entry.Masc_tui_theme_choice.name;
      sync_theme_page state
    end

(* The themes pane's filter, by [f] or by a press on its chip. The cursor
   stays on a row the narrower list still has, and a preview in force moves
   to the scheme now under it. *)
let enter_theme_filter state filter =
  state.theme_filter <- filter;
  let count = List.length (filtered_theme_entries state) in
  state.theme_cursor <- min state.theme_cursor (max 0 (count - 1));
  if Option.is_some state.theme_before_preview then
    preview_theme_under_cursor state

(* What a surface reads on arrival. [goto_surface] asks for it after its
   navigation resets, and [resume_reads_after_authority_change] asks again
   for the surface on view when a refresh moves the read authority, so a
   surface listed here is read again after the move without a second list.
   Surfaces whose data ride the refresh bundle ([surface_needs]) read
   nothing here. *)
(* The held tool calls (Overview, Approvals) and the tool approval modes
   (Keepers) read when their surface opens or the authority resumes, on a
   revalidation, when the server announces their change, and again after a
   failed read (RFC-0480 §3.1). *)
let owe_held_calls_read state =
  state.held_calls_owed <- Masc_tui_owed_read.changed state.held_calls_owed

let owe_tool_modes_read state =
  state.tool_modes_owed <- Masc_tui_owed_read.changed state.tool_modes_owed

(* The turns are owed when the server says a Keeper's turns changed, when a
   preview changed that a surface on screen draws, on a revalidation or a
   resumed authority, and after any failed turns read (RFC-0481 §3.4, §3.5).
   The debt is read only while something uses the answer
   ({!keeper_turns_in_use}); until then it stays owed. *)
let owe_keeper_turns_read state =
  state.keeper_turns_owed <- Masc_tui_owed_read.changed state.keeper_turns_owed

(* Who uses the turns answer: the surfaces that draw a running turn (the
   Keepers list rows, a Keeper's chat, Metrics, the answering overlay), and
   chat input held for a Keeper's control token, which only a turns answer
   brings. *)
let keeper_turns_in_use state =
  state.answering_open
  || not (Masc_tui_keeper_chat_queue.is_empty state.msg_queued)
  || state.keeper_interactive_waiting <> []
  || state.keeper_chat_control_pending <> []
  || (match state.view with
      | Keepers (Keeper_list | Keeper_message) | Metrics -> true
      | Keepers (Keeper_detail | Keeper_logs | Keeper_calls | Keeper_runtime_pick)
      | Overview | Approvals | Acting | Memory | Lanes | Clients | Board | Planning
      | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes
      | Connectors | Runtime | Config | Resources | Tools | System_logs ->
          false)

(* The waiting list is drawn by the Keepers list only: its rows and the
   Activity pane beside them. *)
let keeper_waiting_in_use state =
  match state.view with
  | Keepers Keeper_list -> true
  | Keepers (Keeper_message | Keeper_detail | Keeper_logs | Keeper_calls | Keeper_runtime_pick)
  | Overview | Approvals | Acting | Metrics | Memory | Lanes | Clients | Board | Planning
  | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
  | Runtime | Config | Resources | Tools | System_logs ->
      false

(* A waiting change marks its Keepers unverified and owes the list a read,
   which {!launch_owed_keeper_waiting} starts while the list is in use. *)
let owe_keeper_waiting_read ?change state =
  Option.iter (note_keeper_waiting_change state) change;
  state.keeper_waiting_owed <- Masc_tui_owed_read.changed state.keeper_waiting_owed

(* Where a Keeper's running-turn preview is drawn: its own chat pane's
   activity line, the Keepers list's last activity, and the answering
   overlay. A preview change is read only while one of them is on screen
   (RFC-0481 §3.5). *)
let preview_on_screen state ~keeper_name =
  state.answering_open
  ||
  match state.view with
  | Keepers Keeper_list -> true
  | Keepers Keeper_message ->
      Option.equal String.equal state.msg_target_keeper_name (Some keeper_name)
  | Keepers (Keeper_detail | Keeper_logs | Keeper_calls | Keeper_runtime_pick)
  | Overview | Approvals | Acting | Metrics | Memory | Lanes | Clients | Board | Planning
  | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
  | Runtime | Config | Resources | Tools | System_logs ->
      false

(* The Verification queue reads when the server says its request store, a
   run registry or the backlog changed, on a revalidation, and again after a
   failed read (RFC-0480 §3.4). *)
let owe_verification_read state =
  state.verification_owed <- Masc_tui_owed_read.changed state.verification_owed

(* The repository list reads when the server says the catalog changed, on a
   revalidation and on arrival, and again after a failed read (RFC-0480
   §3.4). *)
let owe_repositories_read state =
  state.repositories_owed <- Masc_tui_owed_read.changed state.repositories_owed

let pushed_read state source =
  Option.value ~default:Masc_tui_owed_read.settled (List.assoc_opt source state.pushed_reads)

let set_pushed_read state source read =
  state.pushed_reads <- (source, read) :: List.remove_assoc source state.pushed_reads

(* A bundle source in [pushed_sources] reads again when the server announces
   its change while its surface is on screen, and after a failed read
   (RFC-0480 §3.4). Entering the surface and a revalidation read it in the
   surface bundle. *)
let owe_pushed_read state source =
  set_pushed_read state source (Masc_tui_owed_read.changed (pushed_read state source))

(* The Usage view's provider windows and runtime quota standing read again
   when the server announces a usage report or a standing change; the
   provider history reads again on a usage report and once the UTC day a
   history request started on has ended. Both read on a revalidation and
   after a failed read (RFC-0480 §3.4). *)
let owe_provider_usage_reads state =
  owe_pushed_read state Surface_read_source.Runtime_quota;
  owe_pushed_read state Surface_read_source.Provider_history

let owe_provider_standing_read state =
  owe_pushed_read state Surface_read_source.Runtime_quota

(* The Usage view's Keeper usage reads again when the server announces that
   its cost window took or dropped a row, on a revalidation and after a
   failed read (RFC-0480 §3.4). *)
let owe_keeper_costs_read state =
  owe_pushed_read state Surface_read_source.Keeper_usage

let owe_provider_history_day state ~now =
  match state.provider_history_reread_at with
  | Some at when Masc_tui_wake.reached_wall Masc_tui_wake.Provider_history_day ~now ~at ->
      state.provider_history_reread_at <- None;
      owe_pushed_read state Surface_read_source.Provider_history
  | Some _ | None -> ()

(* Owed reads wait on this clock, so a wall-clock step cannot stretch a
   retry. *)
let keeper_execute_stream_reconnect_s = 2.0
let keeper_execute_stream_max_reconnect_s = 30.0

(* The pointer press a drag in the browser picture holds; the cadence read
   yields to it, so it is defined before the first launch that checks it. *)
let browser_pointer_press : (int * int * Browser_lane.Pointer.point) option ref = ref None

(* A failed read leaves its record waiting, whoever started it: a read on
   entering a surface, which the record never saw start, retries on the same
   clock as one it started. *)
let failed_read owed =
  Masc_tui_owed_read.failed ~retry_s:Masc_tui_transport.Event_streams.stream_reconnect_s
    ~max_retry_s:keeper_execute_stream_max_reconnect_s ~now:(Masc_tui_wake.Mono.now ())
    (Masc_tui_owed_read.answering owed)

(* A placeholder answer, whoever started the read, is read again on the
   failed read's clock; a change announced during it is read now. *)
let placeholder_read owed =
  Masc_tui_owed_read.placeholder ~retry_s:Masc_tui_transport.Event_streams.stream_reconnect_s
    ~max_retry_s:keeper_execute_stream_max_reconnect_s ~now:(Masc_tui_wake.Mono.now ())
    (Masc_tui_owed_read.answering owed)

(* runtime.toml reads when the server says it committed a text of it, on
   arrival and on a revalidation, and again after a failed read (RFC-0482
   L4). *)
let owe_runtime_config_read state =
  state.runtime_config_owed <- Masc_tui_owed_read.changed state.runtime_config_owed;
  (* The Usage view draws a quota row for each runtime the file declares. *)
  owe_pushed_read state Surface_read_source.Runtime_quota

(* The panes that draw runtime.toml. *)
let runtime_config_on_screen state =
  state.view = Config
  && (match state.config_pane with
      | Config_runtime | Config_models | Config_themes -> true
      | Config_prompts | Config_presets | Config_params | Config_voice -> false)

(* The connectors read again when [gate_connector_changed] arrives while they
   are on screen, and after a failed read (RFC-0480 §3.1). *)
let owe_connectors_read state =
  state.connectors_owed <- Masc_tui_owed_read.changed state.connectors_owed

(* Harness reads when the server says a verdict or a label was recorded, on a
   revalidation and on arrival, and again after a failed read (RFC-0480
   §3.4). *)
let owe_harness_read state =
  state.harness_owed <- Masc_tui_owed_read.changed state.harness_owed

let launch_owed_machine_live state ~mailbox =
  let launch machine visible owed in_flight set_owed launch_read =
    if not visible || state.machine_source <> machine then set_owed Masc_tui_owed_read.settled
    else begin
      let owed = if Option.is_none in_flight then Masc_tui_owed_read.abandoned owed else owed in
      set_owed owed;
      if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) owed then launch_read state ~mailbox
    end
  in
  launch Masc.Machine_lane.Msx (state.msx_open && not state.msx_menu_open)
    state.msx_live_owed state.msx_live_in_flight
    (fun owed -> state.msx_live_owed <- owed) launch_msx_live_read;
  launch Masc.Machine_lane.Dos state.msx_open state.dos_live_owed state.dos_live_in_flight
    (fun owed -> state.dos_live_owed <- owed) launch_dos_live_read

let launch_owed_browser_observation state ~mailbox =
  match browser_lane_on_screen state with
  | None -> state.browser_observation_owed <- Masc_tui_owed_read.settled
  | Some view ->
      let owed = match view.Browser_lane_view.load with
        | Browser_lane_view.Loading _ -> state.browser_observation_owed
        | Browser_lane_view.Idle -> Masc_tui_owed_read.succeeded state.browser_observation_owed
        | Browser_lane_view.Failed _ ->
            (match state.browser_observation_owed with
             | Masc_tui_owed_read.Settled | Masc_tui_owed_read.Reading _ ->
                 failed_read state.browser_observation_owed
             | Masc_tui_owed_read.Owed _ | Masc_tui_owed_read.Waiting _ ->
                 state.browser_observation_owed)
        | Browser_lane_view.No_browser -> Masc_tui_owed_read.settled
      in
      state.browser_observation_owed <- owed;
      if server_authority_ready state
         && Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) owed
         && Option.is_none !browser_pointer_press then begin
        let viewport = if state.image_open then Option.map fst state.browser_viewport else None in
        match Browser_lane_view.observation_operation ?viewport view with
        | Some operation ->
            state.browser_observation_owed <- Masc_tui_owed_read.started owed;
            Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox operation
        | None -> state.browser_observation_owed <- Masc_tui_owed_read.abandoned owed
      end

let launch_owed_lanes state ~mailbox =
  if state.view <> Lanes then
    state.lanes_owed <- Masc_tui_owed_read.settled
  else begin
    if not state.standalone_lanes_inflight then
      state.lanes_owed <- Masc_tui_owed_read.abandoned state.lanes_owed;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) state.lanes_owed then
      launch_lanes_load state ~mailbox
  end

let launch_owed_lane_addons state ~mailbox =
  match state.lane_addons_owed with
  | None -> ()
  | Some ((owner, epoch), owed) ->
      (match state.lane_addons with
       | None -> state.lane_addons_owed <- None
       | Some view ->
           (match view.Masc_tui_lane_addons.screen with
            | Masc_tui_lane_addons.Overview | Masc_tui_lane_addons.Detail _ ->
                let matches =
                  match view.Masc_tui_lane_addons.screen with
                  | Masc_tui_lane_addons.Detail (open_id, incarnation) ->
                      String.equal owner open_id && String.equal epoch incarnation
                  | Masc_tui_lane_addons.Overview -> false
                in
                if not matches then state.lane_addons_owed <- None
                else begin
                  let busy =
                    Option.is_some view.draft || Option.is_some view.document_key
                    || Option.is_some view.action_menu || Option.is_some view.installer
                    || Option.is_some view.subscription_panel || Option.is_some view.evidence_prompt
                    || Option.is_some (Masc_tui_lane_addons.pending_action view)
                  in
                  if view.loading || busy then ()
                  else begin
                    let owed = Masc_tui_owed_read.abandoned owed in
                    state.lane_addons_owed <- Some ((owner, epoch), owed);
                    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) owed then
                      Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox
                        ~target:(Masc_tui_lane_addons.Read_detail (owner, epoch))
                        Masc_tui_lane_addons.Inspect
                  end
                end))

let owe_machine_live_read state machine =
  let visible = match machine with
    | Masc.Machine_lane.Msx -> state.msx_open && not state.msx_menu_open
    | Masc.Machine_lane.Dos -> state.msx_open
  in
  if visible && state.machine_source = machine then
    match machine with
    | Masc.Machine_lane.Msx ->
        state.msx_live_owed <- Masc_tui_owed_read.changed state.msx_live_owed
    | Masc.Machine_lane.Dos ->
        state.dos_live_owed <- Masc_tui_owed_read.changed state.dos_live_owed

(* The fleet memory health reads on arrival, on a revalidation, when a row
   read cannot be merged, and again after a failed read (RFC-0487). *)
let owe_memory_health_read state =
  state.memory_facts_owed <- Masc_tui_owed_read.changed state.memory_facts_owed;
  state.memory_activity_owed <- Masc_tui_owed_read.changed state.memory_activity_owed;
  state.memory_health_owed <- Masc_tui_owed_read.changed state.memory_health_owed

let owe_memory_world_read state =
  state.memory_world <- Masc_tui_memory_world.changed state.memory_world

(* The input pane shows the selected Keeper's turn records. A memory health
   answer may be about them: the fleet read, or a pushed row of that Keeper. *)
let owe_memory_input_read state =
  state.memory_input_owed <- Masc_tui_owed_read.changed state.memory_input_owed

(* A memory health push names the Keeper whose input was written. That
   Keeper's row is read on its own and merged into the fleet answer, so a
   Keeper that writes often costs one row per push (RFC-0487). *)
let owe_memory_health_row state keeper =
  if Masc_tui_fetched.current_key state.memory_facts = Some keeper then
    state.memory_facts_owed <- Masc_tui_owed_read.changed state.memory_facts_owed;
  if Masc_tui_fetched.current_key state.memory_activity = Some keeper then
    state.memory_activity_owed <- Masc_tui_owed_read.changed state.memory_activity_owed;
  if not (List.exists (String.equal keeper) state.memory_health_rows_owed) then
    state.memory_health_rows_owed <- state.memory_health_rows_owed @ [ keeper ]

(* The Home Health line reads when the server announces it moved, on a
   revalidation, when the workspace authority changes, and again after a
   failed read (RFC-0480 §3.4). *)
let owe_overview_read state =
  state.overview_owed <- Masc_tui_owed_read.changed state.overview_owed

(* A dataset push owes a read to the surface that shows that dataset. *)
let owe_keeper_log_read state keeper =
  match keeper_log_target state with
  | Some selected when String.equal selected.k_name keeper ->
      state.keeper_log_owed <- Masc_tui_owed_read.changed state.keeper_log_owed
  | Some _ | None -> ()

let owe_goal_projection_reads state =
  owe_pushed_read state Surface_read_source.Planning;
  owe_pushed_read state Surface_read_source.Overview_goals

let owe_runtime_surface_read state =
  state.runtime_surface_owed <- Masc_tui_owed_read.changed state.runtime_surface_owed

let owe_ask_followup_read state =
  state.ask_followup_owed <- Masc_tui_owed_read.changed state.ask_followup_owed

let owe_open_lane_addon_read state =
  match state.lane_addons with
  | Some { Masc_tui_lane_addons.screen = Masc_tui_lane_addons.Detail (open_id, incarnation); _ } ->
      let owed = match state.lane_addons_owed with
        | Some ((owner, epoch), owed) when String.equal owner open_id
            && String.equal epoch incarnation -> owed
        | Some _ | None -> Masc_tui_owed_read.settled
      in
      state.lane_addons_owed <-
        Some ((open_id, incarnation), Masc_tui_owed_read.changed owed)
  | Some { Masc_tui_lane_addons.screen = Masc_tui_lane_addons.Overview; _ } | None -> ()

let owe_push_owned_revalidation state =
  if state.view = Lanes then
    state.lanes_owed <- Masc_tui_owed_read.changed state.lanes_owed;
  owe_open_lane_addon_read state;
  owe_machine_live_read state state.machine_source;
  if Masc_tui_types.ask_followup_unfinished state then owe_ask_followup_read state

let owe_dataset_read state (dataset : Masc.Workspace_dataset_event.dataset) =
  match dataset with
  | Masc.Workspace_dataset_event.Repositories -> owe_repositories_read state
  | Masc.Workspace_dataset_event.Backlog ->
      (* The feed handler reads Backlog's six reads itself: Work needs its
         mailbox, and the other five go with it. *)
      ()
  | Masc.Workspace_dataset_event.Verification_requests -> owe_verification_read state
  | Masc.Workspace_dataset_event.Keeper_metrics { keeper } -> owe_keeper_log_read state keeper
  | Masc.Workspace_dataset_event.Harness_verdicts -> owe_harness_read state
  | Masc.Workspace_dataset_event.Goals -> owe_goal_projection_reads state
  | Masc.Workspace_dataset_event.Runtime_config -> owe_runtime_config_read state
  | Masc.Workspace_dataset_event.Connectors -> owe_connectors_read state
  | Masc.Workspace_dataset_event.Keeper_oauth_attempts { keeper } ->
      Masc_tui_types.owe_identity_login_read state keeper
  | Masc.Workspace_dataset_event.Skill_activations { keeper } -> owe_skill_activations_read state keeper
  | Masc.Workspace_dataset_event.Skill_catalog ->
      owe_tools_catalog_read state;
      owe_every_skill_usage_read state
  | Masc.Workspace_dataset_event.Clients -> owe_clients_read state
  | Masc.Workspace_dataset_event.Account_emails ->
      owe_pushed_read state Surface_read_source.Account_emails
  | Masc.Workspace_dataset_event.Provider_usage -> owe_provider_usage_reads state
  | Masc.Workspace_dataset_event.Provider_standing -> owe_provider_standing_read state
  | Masc.Workspace_dataset_event.Keeper_costs -> owe_keeper_costs_read state
  | Masc.Workspace_dataset_event.Workspace_health -> owe_overview_read state
  | Masc.Workspace_dataset_event.Runtime_probe | Masc.Workspace_dataset_event.Runtime_metrics ->
      owe_runtime_surface_read state
  | Masc.Workspace_dataset_event.Machine_live { machine } -> owe_machine_live_read state machine
  | Masc.Workspace_dataset_event.Browser_observation observation ->
      if Masc_tui_types.observer_browser_scope_of_state state = Some observation.scope then
        state.browser_observation_owed <- Masc_tui_owed_read.changed state.browser_observation_owed
  | Masc.Workspace_dataset_event.Memory_health { keeper } -> owe_memory_health_row state keeper
  | Masc.Workspace_dataset_event.World_memory -> owe_memory_world_read state
  | Masc.Workspace_dataset_event.Dashboard_observation _ -> ()
  | Masc.Workspace_dataset_event.Play_room _ | Masc.Workspace_dataset_event.Play_seats ->
      state.play_room <- Option.map Masc_tui_play_room.revalidate state.play_room
  | (Masc.Workspace_dataset_event.Lanes | Masc.Workspace_dataset_event.Lane_addons _) as dataset ->
      let module Decision = Masc_tui_lane_read_decision in
      let addon = Option.bind state.lane_addons (fun (view : Masc_tui_lane_addons.t) ->
        match view.screen with
        | Masc_tui_lane_addons.Detail (instance_id, _) -> Some instance_id
        | Masc_tui_lane_addons.Overview -> None)
      in
      (match Decision.of_views ~lanes:(state.view = Lanes) ~addon dataset with
       | Decision.Read_lanes -> state.lanes_owed <- Masc_tui_owed_read.changed state.lanes_owed
       | Decision.Read_addon instance_id ->
           (match state.lane_addons with
            | Some { Masc_tui_lane_addons.screen = Detail (open_id, _); _ }
              when String.equal open_id instance_id -> owe_open_lane_addon_read state
            | Some { Masc_tui_lane_addons.screen = Overview | Detail _; _ } | None -> ())
       | Decision.Ignore -> ())

(* The durable async requests the Keepers list and Tools draw read under the
   same rules. *)
let owe_async_requests_read state =
  state.async_requests_owed <- Masc_tui_owed_read.changed state.async_requests_owed

let launch_surface_reads state ~mailbox (surface : surface) =
  if server_authority_ready state then
  match surface with
  | Lanes -> launch_lanes_load state ~mailbox
  | Clients -> owe_clients_read state
  (* The list draws nothing from the Keeper composite; Info and Secrets read
     it on entry and when it changes. Keeper_list reads memory health for its
     second-row axis cells (RFC-0511 A4). *)
  | Keepers Keeper_list ->
      owe_tool_modes_read state;
      owe_async_requests_read state;
      owe_memory_health_read state;
      owe_memory_world_read state;
      Masc_tui_surface_requests.Memory_repository_requests.launch_memory_health_load state ~mailbox
  | Keepers
      ( Keeper_detail | Keeper_logs | Keeper_calls | Keeper_message
      | Keeper_runtime_pick ) ->
      owe_tool_modes_read state;
      owe_async_requests_read state
  | Overview -> owe_held_calls_read state
  | Approvals ->
      Masc_tui_work_requests.Approval_gate_requests.launch_keeper_tool_approvals_load ~intent:Snapshot_read.Refresh state ~mailbox;
      Masc_tui_work_requests.Approval_gate_requests.launch_gate_snapshot_load ~intent:Snapshot_read.Refresh state ~mailbox
  | Schedules -> Masc_tui_work_requests.Schedule_call_requests.launch_schedules_load ~intent:Snapshot_read.Refresh state ~mailbox
  (* Arriving owes the queue a read as well as starting one: a read already
     in flight may have begun before a change that came while the queue was
     off screen, and the owed read follows it. *)
  | Verification ->
      owe_verification_read state;
      launch_verification_load state ~mailbox
  | Planning -> launch_verification_load state ~mailbox
  | Fusion ->
      let demand = Masc_tui_fusion_updates.After_change in
      launch_fusion_runs_load ~demand state ~mailbox;
      (match state.fusion_mode with
       | Fusion_list -> ()
       | Fusion_detail run_id ->
           Masc_tui_work_actions.Detail_navigation.launch_fusion_detail_load ~demand state ~mailbox ~run_id
       | Fusion_historical_detail reference ->
           Masc_tui_work_actions.Detail_navigation.launch_fusion_historical_detail_load ~demand state ~mailbox ~reference)
  (* Arriving owes the fleet a read as well as starting one: a read already in
     flight may have begun before a write announced while the surface was off
     screen. Metrics shows the same health and owes it the same way. *)
  | Memory ->
      owe_memory_health_read state;
      owe_memory_world_read state;
      Masc_tui_surface_requests.Memory_repository_requests.launch_memory_health_load state ~mailbox
  | Repositories ->
      owe_repositories_read state;
      Masc_tui_surface_requests.Memory_repository_requests.launch_repositories_load state ~mailbox
  | Harness ->
      owe_harness_read state;
      launch_harness_load state ~mailbox
  | Changes -> (
      match state.changes_keeper with
      | Some keeper_name -> launch_file_changes_load state ~mailbox ~keeper_name
      | None -> ())
  | Connectors -> (
      match browser_lane_on_screen state with
      | None ->
          owe_connectors_read state;
          Masc_tui_surface_requests.Connector_volume_requests.launch_connectors_load state ~mailbox
      | Some _ -> Masc_tui_surface_requests.Lane_browser_requests.refresh_browser_lane state ~mailbox)
  | Runtime -> Masc_tui_surface_requests.Memory_repository_requests.launch_runtime_surface_load state ~mailbox ~force:false
  | Tools ->
      owe_async_requests_read state;
      owe_tools_reads state;
      Masc_tui_work_requests.Tools_task_requests.launch_tools_load state ~mailbox
  | Config -> (
      (* Each pane loads its own source. Named rather than left to an
         if/else chain: a pane added later should have to say where its data
         comes from instead of quietly inheriting runtime.toml's. *)
      match state.config_pane with
      | Config_prompts -> Masc_tui_surface_requests.Prompt_preset_requests.launch_prompts_load state ~mailbox
      | Config_presets -> Masc_tui_surface_requests.Prompt_preset_requests.launch_presets_load state ~mailbox
      | Config_params -> Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_params_load state ~mailbox
      | Config_voice -> Masc_tui_work_requests.Voice_requests.launch_voice_config_load state ~mailbox
      | Config_runtime | Config_models | Config_themes ->
          owe_runtime_config_read state;
          Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_config_load state ~mailbox)
  | Resources -> launch_resources_load state ~mailbox
  | Code -> Masc_tui_code_requests.launch_entries_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state mailbox)
  | Metrics ->
      owe_memory_health_read state;
      Masc_tui_surface_requests.Memory_repository_requests.launch_memory_health_load state ~mailbox;
      Masc_tui_work_requests.Approval_gate_requests.launch_keeper_tool_approvals_load ~intent:Snapshot_read.Refresh state ~mailbox;
      Masc_tui_work_requests.Approval_gate_requests.launch_gate_snapshot_load ~intent:Snapshot_read.Refresh state ~mailbox;
      Masc_tui_work_requests.Approval_gate_requests.launch_keeper_tool_modes_load state ~mailbox
  | Acting | Board | System_logs -> ()

(* Move to a surface, fetching what that surface shows on arrival. Tab,
   Shift-Tab, and any future jump go through here so no direction can forget
   a load the other performs. Surfaces not listed read through their owed
   reads ([surface_needs]); the ones here are snapshots that would otherwise
   read as empty until their next change. *)
(* Leaving the Browser lane returns to the surface it was opened from. That is
   an arrival: while the lane covered the surface, the surface was off screen
   and dropped what it owed, so it reads the way it reads on arrival. *)
let leave_browser_lane state ~mailbox =
  hide_browser_lane state;
  launch_surface_reads state ~mailbox state.view

let goto_surface ?(from_reference = false) state ~mailbox (destination : surface) =
  if state.view <> Memory || destination <> Memory then state.memory_return <- None;
  if state.view = Memory && destination <> Memory then begin
    state.memory_fact_detail_open <- false;
    state.memory_fact_detail_scroll <- 0
  end;
  state.code_hover <- None;
  state.runtime_config_jump_section <- None;
  if destination <> Tools && state.tools_async_detail_open then Masc_tui_work_requests.Tools_task_requests.close_tools_async_detail state;
  if destination <> Tools then state.tools_skill_focus <- Choosing_skill;
  state.keeper_navigation_open <- false;
  state.keeper_message_focus <- Right_pane;
  state.runtime_model_jump <- None;
  Masc_tui_work_requests.Schedule_call_requests.close_chat_call_reader state;
  close_detail_reading state;
  state.detail_focus_recovery <- None;
  (* The browser reader owns Connectors; refocusing it keeps the reader.
     The transport-list palette hides it explicitly before arriving here.
     Repository changes can overlay any surface, so every jump closes them. *)
  state.home_opened_request <- None;
  if destination = Overview then begin
    save_message_draft state;
    let was_focused = state.composer_focused in
    state.composer_focused <- false;
    if was_focused then Masc_tui_transport.Workspace_admission.enqueue mailbox (Keeper_msg Keeper_composer_released)
  end;
  if not from_reference then state.followed_from <- None;
  leave_browser_lane_for_surface state destination;
  if state.repository_changes_open then close_repository_changes state;
  (match state.view with
   | Config when state.config_pane = Config_themes && destination <> Config ->
       cancel_theme_preview state
   | Overview | Acting | Metrics | Memory | Lanes | Clients | Board | Approvals | Planning
   | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
   | Runtime | Resources | Tools | System_logs | Keepers _ | Config -> ());
  if state.view = Lanes || destination = Lanes then
    state.lanes_action_error <- None;
  (* The lane editor's line belongs to the view that drew it. *)
  if destination <> state.view then begin
    Masc_tui_types.dismiss_runtime_lane_notice state;
    state.slot_editor <- None;
    state.runtime_lane_pick <- None
  end;
  (* Arriving is also a navigation: these resets belong to the move, not to
     the reading, so a reread after an authority change leaves them alone. *)
  (match destination with
   | Planning ->
       (* Work opens on its Goals. The task list is a focus taken with [t],
          or by a jump to one task, which sets it after this returns.
          Inheriting it made every later Tab into Work show only Tasks. *)
       state.task_detail_id <- None;
       reset_task_detail_scroll state;
       state.task_focus <- Masc_tui_overview_tasks.No_task_focus
   | Changes -> (
       (* The surface follows whoever is selected on Keepers. Arriving with a
          different keeper selected than the one already loaded drops the old
          rows first: showing one keeper's files under another's name for the
          length of a request is the confusion this surface exists to end. *)
       let selected = Option.map (fun (k : keeper) -> k.k_name) (selected_keeper state) in
       match selected with
       | Some name when not (Option.equal String.equal state.changes_keeper (Some name)) ->
           state.changes_keeper <- Some name;
           state.changes <- None;
           state.changes_error <- None;
           state.changes_inflight <- false;
           state.changes_cursor <- 0;
           state.changes_scroll <- 0;
           state.changes_diff_row <- None;
           state.changes_diff_scroll <- 0;
           state.changes_tree_diff <- None;
           state.changes_tree_diff_error <- None;
           state.changes_tree_diff_path <- None
       | Some _ | None -> ())
   | Connectors -> (
       match browser_lane_on_screen state with
       | None -> ()
       | Some _ -> release_composer_for_browser_reader state)
   | Metrics ->
       (* Usage is the top-level account reading. Explicit telemetry entry
          opts into diagnostics after navigation, rather than inheriting it. *)
       state.usage_telemetry_open <- false;
       reset_metrics_scroll state
   | Overview | Acting | Memory | Lanes | Clients | Board | Approvals
   | Schedules | Verification | Harness | Fusion | Repositories | Code
   | Runtime | Config | Resources | Tools | System_logs
   | Keepers
       ( Keeper_list | Keeper_detail | Keeper_logs | Keeper_calls
       | Keeper_message | Keeper_runtime_pick ) ->
       ());
  launch_surface_reads state ~mailbox destination;
  (* Leaving Approvals drops a half-armed decision, exactly as the old Tab
     arm did on the Approvals -> Board step. *)
  (match state.view with
   | Approvals when destination <> Approvals ->
       state.pending_approval_action <- None;
       state.approval_value_reading <- None
   | Overview | Acting | Metrics | Memory | Lanes | Clients | Board | Planning | Schedules
   | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors | Runtime | Config
   | Resources | Tools | System_logs | Keepers _ | Approvals -> ());
  if state.view = Keepers Keeper_list || destination = Keepers Keeper_list then
    transition_keeper_view state destination
  else
    state.view <- destination;
  (* The scroll a pane kept from an earlier visit may not show the selection
     the first move key steps from. *)
  if destination = Tools then follow_tools_selection state

(* One step around the ring the surface strip draws. Tab and Shift-Tab
   call this; so does board compose when its handler declines the key, so
   "Tab falls through" stays true while composing. *)
let cycle_surface state ~mailbox ~backwards =
  let ring = Masc_tui_types.surface_ring in
  let count = List.length ring in
  if count > 0 then begin
    let step = if backwards then count - 1 else 1 in
    let index =
      (Masc_tui_surface_navigation.surface_ring_index state.view + step) mod count
    in
    goto_surface state ~mailbox (fst (List.nth ring index))
  end

let launch_keeper_older_page state ~mailbox ~keeper_name ~cursor =
  if server_authority_ready state then begin
  Masc_tui_frame_timing.time_stage ~name:"chat.older.requested" (fun () -> ());
  (* Explicit/resumed paging owns the cursor from here. A still-running cold
     first page must not later rewind it, even if both requested [None]. *)
  (match state.msg_history_inflight with
   | Some request when String.equal (Keeper_history_read.keeper request) keeper_name ->
       Keeper_history_read.retire_page request;
       if not (Keeper_history_read.pending request) then state.msg_history_inflight <- None
   | Some _ | None -> ());
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  let generation = state.msg_history_load_generation in
  state.msg_older_loading <- true;
  let run () =
    let result =
      try
        Masc_tui_http.fetch_keeper_chat_history_page ~host ~port ~keeper_name
          ~cursor
      with
      | Eio.Cancel.Cancelled _ as exn -> raise exn
      | exn -> Error (Keeper_chat_history.Page_read_failed (Printexc.to_string exn))
    in
    enqueue_async mailbox
      (Keeper_msg (Keeper_chat_older_loaded (generation, keeper_name, cursor, result)))
  in
  match Eio_context.get_switch_opt () with
  | Some sw ->
      Eio.Fiber.fork_daemon ~sw (fun () ->
          run ();
          `Stop_daemon)
  | None ->
      enqueue_async mailbox
        (Keeper_msg (Keeper_chat_older_loaded
           (generation, keeper_name, cursor, Error (Keeper_chat_history.Page_read_failed "Eio switch is unavailable"))))
  end

let launch_keeper_native_tasks_load ?(mode=Masc_tui_native_tasks.Suffix) state ~mailbox ~keeper_name =
  let eligible = server_authority_ready state in
  if mode=Masc_tui_native_tasks.Audit
     && not (List.mem keeper_name state.msg_native_tasks_audit_pending) then
    state.msg_native_tasks_audit_pending <- keeper_name :: state.msg_native_tasks_audit_pending;
  if eligible && not (List.mem_assoc keeper_name state.msg_native_tasks_inflight) then begin
    let mode = if List.mem keeper_name state.msg_native_tasks_audit_pending
      then Masc_tui_native_tasks.Audit else mode in
    state.msg_native_tasks_audit_pending <-
      List.filter ((<>) keeper_name) state.msg_native_tasks_audit_pending;
    let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
    let authority = state.workspace_authority in
    let identity = state.server_identity in
    let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
    let previous = Option.value ~default:Masc_tui_native_tasks.empty
        (List.assoc_opt keeper_name state.msg_native_tasks) in
    state.msg_native_tasks_inflight <- (keeper_name,mode) :: state.msg_native_tasks_inflight;
    let read_authority = state.workspace_read_authority in
    Masc_tui_transport.Workspace_admission.launch_async_read_with state ~mailbox
      ~boundary_error:(fun detail -> Masc_tui_native_tasks.Transport detail)
      ~withdrawn:(fun refusal -> Masc_tui_native_tasks.Kept_back
        (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
          ~request:Kept_request.Native_tasks_read refusal))
      ~deliver:(fun result -> enqueue_async mailbox (Keeper_msg (Keeper_native_tasks_loaded (keeper_name,result))))
      (fun () -> Masc_tui_native_tasks.read ~mode ~keeper_name ~previous
        ~fetch:(fun path ->
          let open Result.Syntax in
          let retired () = if read_authority == state.workspace_read_authority then Ok ()
            else Error (Masc_tui_native_tasks.Transport "workspace observation read was retired") in
          (* The guard's refusal is the kept-back notice, never a transport
             failure (RFC §2). *)
          let admit () = Masc_tui_transport.Workspace_admission.admit_request state ~mailbox ~authority ~identity ~host ~port () in
          let* () = retired () in
          let* () = admit () |> Result.map_error (fun refusal -> Masc_tui_native_tasks.Kept_back
            (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
              ~request:Kept_request.Native_tasks_read refusal)) in
          let result = Masc_tui_http.http_get ~host ~port ~path
            |> Result.map_error (fun detail -> Masc_tui_native_tasks.Transport detail) in
          let* () = retired () in
          let* () = admit () |> Result.map_error (fun refusal -> Masc_tui_native_tasks.Transport
            (Masc_tui_transport.Request_notice.workspace_response_refusal_text state ~request:Kept_request.Native_tasks_read refusal)) in
          result))
  end

let launch_keeper_child_content_load ?(mode=Masc_tui_child_content.Suffix) state ~mailbox ~keeper_name =
  (* Reading retained server observations does not submit a message or use
     local attachment paths. Remote/missing roster rows are not a refusal. *)
  let eligible = server_authority_ready state in
  (* An explicit Audit is retained intent even while reading is unconfirmed;
     it does not authorize an HTTP request. Workspace withdrawal clears it. *)
  let audit_running = match List.assoc_opt keeper_name state.msg_child_content_inflight with
    | Some Masc_tui_child_content.Audit -> true
    | None | Some Masc_tui_child_content.Suffix -> false in
  if mode=Masc_tui_child_content.Audit && not audit_running
     && not (List.mem keeper_name state.msg_child_content_audit_pending) then
    state.msg_child_content_audit_pending <- keeper_name :: state.msg_child_content_audit_pending;
  if eligible && not (List.mem_assoc keeper_name state.msg_child_content_inflight) then begin
    let mode = if List.mem keeper_name state.msg_child_content_audit_pending
      then Masc_tui_child_content.Audit else mode in
    state.msg_child_content_audit_pending <-
      List.filter ((<>) keeper_name) state.msg_child_content_audit_pending;
    let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
    let authority = state.workspace_authority in
    let identity = state.server_identity in
    let reading = state.workspace_read_authority in
    let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
    let previous = Option.value ~default:Masc_tui_child_content.empty
        (List.assoc_opt keeper_name state.msg_child_content) in
    state.msg_child_content_inflight <- (keeper_name,mode) :: state.msg_child_content_inflight;
    Masc_tui_transport.Workspace_admission.launch_async_read_with state ~mailbox
      ~boundary_error:(fun detail -> Masc_tui_child_content.Transport detail)
      ~withdrawn:(fun refusal -> Masc_tui_child_content.Kept_back
        (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
          ~request:Kept_request.Child_content_read refusal))
      ~deliver:(fun result -> enqueue_async mailbox (Keeper_msg (Keeper_child_content_loaded (keeper_name,result))))
      (fun () -> Masc_tui_child_content.read ~mode ~keeper_name ~previous
        ~fetch:(fun path ->
          let open Result.Syntax in
          (* The guard's refusal is the kept-back notice, never a transport
             failure (RFC §2). *)
          let retired () =
            if reading != state.workspace_read_authority then
              Error (Masc_tui_child_content.Transport "Child observation read was retired")
            else Ok () in
          let admit () = Masc_tui_transport.Workspace_admission.admit_request state ~mailbox ~authority ~identity ~host ~port () in
          let* () = retired () in
          let* () = admit () |> Result.map_error (fun refusal -> Masc_tui_child_content.Kept_back
            (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
              ~request:Kept_request.Child_content_read refusal)) in
          let result = Masc_tui_http.http_get ~host ~port ~path
            |> Result.map_error (fun detail -> Masc_tui_child_content.Transport detail) in
          let* () = retired () in
          let* () = admit () |> Result.map_error (fun refusal -> Masc_tui_child_content.Transport
            (Masc_tui_transport.Request_notice.workspace_response_refusal_text state ~request:Kept_request.Child_content_read refusal)) in
          result))
  end

(* The owed history read of [keeper_name] under the current workspace
   reading, when the record is theirs. *)
let current_history_owed state ~keeper_name =
  match state.msg_history_owed with
  | Some owed
    when String.equal owed.kho_keeper keeper_name
         && owed.kho_authority = state.workspace_authority
         && owed.kho_reading == state.workspace_read_authority ->
      Some owed
  | Some _ | None -> None

(* Move the owed history read of [keeper_name]. A record of another Keeper or
   reading is replaced. [audit] is kept until a forced read starts. *)
let update_history_owed ?(audit = false) state ~keeper_name transition =
  let owed =
    match current_history_owed state ~keeper_name with
    | Some owed -> owed
    | None ->
        { kho_keeper = keeper_name
        ; kho_authority = state.workspace_authority
        ; kho_reading = state.workspace_read_authority
        ; kho_read = Masc_tui_owed_read.settled
        ; kho_audit = false }
  in
  state.msg_history_owed <-
    Some { owed with kho_read = transition owed.kho_read; kho_audit = owed.kho_audit || audit }

let launch_keeper_history_load ?(load_file_changes = true) ?(force = false) state ~mailbox
    ~keeper_name =
  let other_page_pending = match state.keeper_schedules_pending with
    | Some (request, page, _) when String.equal request.drr_keeper keeper_name
                                && Option.is_some page.sp_cursor ->
        keeper_schedule_page_pending state ~keeper_name page
    | Some _ | None -> false in
  if force || other_page_pending || not (keeper_schedule_first_page_available state keeper_name) then
    Masc_tui_work_requests.Schedule_call_requests.launch_keeper_chat_schedules_load state ~mailbox ~keeper_name;
  if force then state.msg_preparation_details <-
    Masc_tui_preparation_details.refresh ~keeper_name state.msg_preparation_details;
  launch_keeper_child_content_load
    ~mode:(if force then Masc_tui_child_content.Audit else Masc_tui_child_content.Suffix)
    state ~mailbox ~keeper_name;
  launch_keeper_native_tasks_load
    ~mode:(if force then Masc_tui_native_tasks.Audit else Masc_tui_native_tasks.Suffix)
    state ~mailbox ~keeper_name;
  if server_authority_ready state then begin
  let identity = state.server_identity in
  let authority = state.workspace_authority in
  if keeper_available_for_new_message state keeper_name then begin
  let already_inflight =
    match state.msg_history_inflight with
    | Some request -> String.equal (Keeper_history_read.keeper request) keeper_name
    | None -> false
  in
  (* Joined or started below, a read of this Keeper is on the wire. *)
  note_chat_entry_read state ~keeper_name;
  if already_inflight && not force then ()
  else begin
    (* An unforced read cannot settle an owed audit: the audit stays owed and
       runs once this read lands. *)
    (match current_history_owed state ~keeper_name with
     | Some owed when owed.kho_audit && not force -> ()
     | Some _ | None ->
         update_history_owed state ~keeper_name Masc_tui_owed_read.started;
         Option.iter
           (fun owed -> state.msg_history_owed <- Some { owed with kho_audit = false })
           state.msg_history_owed);
    let host = Masc_tui_transport.Workspace_admission.server_peer_host in
    let port = state.port in
    state.msg_history_load_generation <- state.msg_history_load_generation + 1;
    let first_page = state.msg_loaded_keeper <> Some keeper_name
      || not (keeper_chat_history_received state.msg_loaded_sources.kcs_history) in
    state.msg_older_loading <- first_page;
    let request = Keeper_history_read.create
      ~generation:state.msg_history_load_generation ~keeper:keeper_name
      ~authority ~reading:state.workspace_read_authority ~first_page in
    state.msg_history_inflight <- Some request;
    let publish source result =
      Keeper_history_read.publish request source
        ~ready_at_ns:(Mtime_clock.elapsed_ns ()) result in
    let read source fetch =
      (* Each source keeps its own identity-probe chain. Neither result waits
         for its sibling or for capacity in the shared mailbox. *)
      (* The guard's refusal stays typed apart from the read's own failure,
         so the pane draws it as kept back (RFC §2). *)
      let check_request = Masc_tui_transport.Workspace_admission.admission_sequence state ~mailbox ~authority ~identity ~host ~port in
      let request = match source with
        | Keeper_history_read.History -> Kept_request.Keeper_history_read
        | Keeper_history_read.Initial_reply -> Kept_request.Keeper_reply_read
        | Keeper_history_read.Memory -> Kept_request.Keeper_memory_read in
      let result =
        try
          let open Result.Syntax in
          let check () = Result.map_error (fun refusal -> Request_withdrawn refusal) (check_request ()) in
          let* () = check () in
          let* reading = fetch ~host ~port ~keeper_name
            |> Result.map_error (fun detail -> Request_failed detail) in
          let* () = check () |> Result.map_error (Masc_tui_transport.Request_notice.request_failure_after_read state ~request) in
          Ok reading
        with
        | Eio.Cancel.Cancelled _ as exn -> raise exn
        | exn ->
            let detail = Printexc.to_string exn in
            Error (Request_failed (match source with
              | Keeper_history_read.History -> detail
              | Keeper_history_read.Initial_reply -> "initial reply: " ^ detail
              | Keeper_history_read.Memory -> "memory journal: " ^ detail))
      in
      publish source result
    in
    let read_page () =
      let check_request = Masc_tui_transport.Workspace_admission.admission_sequence state ~mailbox ~authority ~identity ~host ~port in
      let result =
        try
          let open Result.Syntax in
          let check () = Result.map_error (fun refusal -> Request_withdrawn refusal) (check_request ()) in
          let* () = check () in
          let* page = Masc_tui_http.fetch_keeper_chat_history_page ~host ~port ~keeper_name ~cursor:None
            |> Result.map_error (fun error ->
                 Request_failed (Keeper_chat_history.page_error_to_string error)) in
          let* () = check ()
            |> Result.map_error (Masc_tui_transport.Request_notice.request_failure_after_read state ~request:Kept_request.Keeper_history_read) in
          Ok page
        with
        | Eio.Cancel.Cancelled _ as exn -> raise exn
        | exn -> Error (Request_failed (Printexc.to_string exn)) in
      Keeper_history_read.publish_page request ~ready_at_ns:(Mtime_clock.elapsed_ns ()) result
    in
    let not_run detail =
      publish Keeper_history_read.History (Error (Request_failed detail));
      publish Keeper_history_read.Memory (Error (Request_failed detail));
      publish Keeper_history_read.Initial_reply (Error (Request_failed detail));
      Keeper_history_read.publish_page request ~ready_at_ns:(Mtime_clock.elapsed_ns ())
        (Error (Request_failed detail)) in
    (match Eio_context.get_switch_opt () with
     | Some sw ->
         (try
            Masc_tui_transport.Workspace_admission.fork_job ~kind:Masc_tui_workspace_precondition.Observation state ~mailbox ~sw (fun () ->
              Eio.Fiber.all
                ([ (fun () -> read Keeper_history_read.History Masc_tui_http.fetch_keeper_chat_history)
                 ; (fun () -> read Keeper_history_read.Memory Masc_tui_http.fetch_keeper_memory_journal) ]
                 @ if first_page then
                     [read_page; (fun () -> read Keeper_history_read.Initial_reply
                         Masc_tui_http.fetch_keeper_chat_initial_reply)]
                   else []))
          with
          | Eio.Cancel.Cancelled _ as exn -> raise exn
          | exn -> not_run (Printexc.to_string exn))
     | None -> not_run "Eio switch is unavailable");
    (* Full tool detail owns the only lazy read. Compact chat remains byte- and
       network-compatible; repeated history refreshes reuse this separate cache. *)
    if load_file_changes then
      launch_keeper_chat_tool_details_load state ~mailbox ~keeper_name
  end
  end
  end

(* Read the open chat's owed history once the pane can take it: the chat is
   on screen at its newest row and no history read is in flight. Runs on
   every loop iteration; it reads only when {!Masc_tui_owed_read.due} says so. *)
let launch_owed_history state ~mailbox =
  match state.msg_history_owed with
  | None -> ()
  | Some owed ->
      if owed.kho_authority <> state.workspace_authority
         || owed.kho_reading != state.workspace_read_authority
         || state.msg_target_keeper_name <> Some owed.kho_keeper
      then state.msg_history_owed <- None
      else if
        Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) owed.kho_read
        && state.view = Keepers Keeper_message && state.msg_scroll = 0
        && server_authority_ready state
        && keeper_available_for_new_message state owed.kho_keeper
        && Option.is_none state.msg_history_inflight
      then
        launch_keeper_history_load ~force:owed.kho_audit state
          ~mailbox ~keeper_name:owed.kho_keeper

(* Runs on every loop iteration; it reads only a visible Fusion reading whose
   failed read is due. *)
let launch_owed_fusion state ~mailbox =
  Masc_tui_fusion_updates.retry_due_visible state ~now:(Masc_tui_wake.Mono.now ())
    ~runs:(fun () -> launch_fusion_runs_load state ~mailbox)
    ~detail:(fun run_id -> Masc_tui_work_actions.Detail_navigation.launch_fusion_detail_load state ~mailbox ~run_id)
    ~historical:(fun reference ->
      Masc_tui_work_actions.Detail_navigation.launch_fusion_historical_detail_load state ~mailbox ~reference)

(* The Keeper detail's composite reading: Info's execution facts and the
   Secrets tab read one Keeper's [/api/v1/keepers/<name>/composite]. It is
   read when a tab opens or [r] asks, when [keeper_composite_changed] names
   the Keeper, and again after a failed read (RFC-0480 §3.1). *)
let current_composite_owed state ~keeper_name =
  match state.keeper_composite_owed with
  | Some owed
    when String.equal owed.kco_keeper keeper_name
         && owed.kco_reading == state.detail_read_authority ->
      Some owed
  | Some _ | None -> None

(* A record of another Keeper or detail reading is replaced. *)
let update_composite_owed state ~keeper_name transition =
  let owed =
    match current_composite_owed state ~keeper_name with
    | Some owed -> owed
    | None ->
        { kco_keeper = keeper_name
        ; kco_reading = state.detail_read_authority
        ; kco_read = Masc_tui_owed_read.settled }
  in
  state.keeper_composite_owed <- Some { owed with kco_read = transition owed.kco_read }

(* An answer moves only the record it was read for. *)
let settle_composite_owed state ~keeper_name transition =
  match current_composite_owed state ~keeper_name with
  | Some owed ->
      state.keeper_composite_owed <- Some { owed with kco_read = transition owed.kco_read }
  | None -> ()

let keeper_composite_on_screen state ~keeper_name =
  state.view = Keepers Keeper_detail
  && (match state.detail_tab with
      | Detail_info | Detail_secrets -> true
      | Detail_items | Detail_sandbox | Detail_instructions | Detail_github
      | Detail_identity | Detail_channels | Detail_automation | Detail_runs
      | Detail_terminal -> false)
  && (match selected_keeper state with
      | Some keeper -> String.equal keeper.k_name keeper_name
      | None -> false)

let launch_keeper_composite_load state ~mailbox ~keeper_name =
  if server_authority_ready state && Option.is_none state.keeper_composite_inflight then begin
    let authority = state.detail_read_authority in
    let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
    state.keeper_composite_inflight <- Some keeper_name;
    settle_composite_owed state ~keeper_name Masc_tui_owed_read.started;
    let host = Masc_tui_transport.Workspace_admission.server_peer_host in
    let port = state.port in
    Masc_tui_transport.Workspace_admission.launch_async_read state ~mailbox
      ~on_not_run:(fun () ->
        if authority == state.detail_read_authority then begin
          state.keeper_composite_inflight <- None;
          settle_composite_owed state ~keeper_name Masc_tui_owed_read.abandoned
        end)
      ~deliver:(fun result ->
        enqueue_async mailbox (Keeper_msg (Keeper_composite_loaded (authority, keeper_name, result))))
      (fun () -> Masc_tui_loader.load_keeper_composite ~host ~port ~keeper_name)
  end

(* Runs on every loop iteration; it reads only the Keeper on screen whose
   read is due. *)
let launch_owed_keeper_composite state ~mailbox =
  match state.keeper_composite_owed with
  | None -> ()
  | Some owed ->
      if owed.kco_reading != state.detail_read_authority
      then state.keeper_composite_owed <- None
      else if
        Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) owed.kco_read
        && keeper_composite_on_screen state ~keeper_name:owed.kco_keeper
        && Option.is_none state.keeper_composite_inflight
      then launch_keeper_composite_load state ~mailbox ~keeper_name:owed.kco_keeper

let owe_keeper_composite_read state ~mailbox ~keeper_name =
  update_composite_owed state ~keeper_name Masc_tui_owed_read.changed;
  launch_owed_keeper_composite state ~mailbox

(* The Keeper_calls surface reads the selected Keeper's tool calls when it
   opens or [r] asks, when [keeper_tool_call] names the Keeper, on a
   revalidation, and again after a failed read (RFC-0480 §3.1). *)
let current_calls_owed state ~keeper_name =
  match state.keeper_calls_owed with
  | Some owed
    when String.equal owed.kclo_keeper keeper_name
         && owed.kclo_reading == state.detail_read_authority ->
      Some owed
  | Some _ | None -> None

let update_calls_owed state ~keeper_name transition =
  let owed =
    match current_calls_owed state ~keeper_name with
    | Some owed -> owed
    | None ->
        { kclo_keeper = keeper_name
        ; kclo_reading = state.detail_read_authority
        ; kclo_read = Masc_tui_owed_read.settled }
  in
  state.keeper_calls_owed <- Some { owed with kclo_read = transition owed.kclo_read }

let settle_calls_owed state ~keeper_name transition =
  match current_calls_owed state ~keeper_name with
  | Some owed ->
      state.keeper_calls_owed <- Some { owed with kclo_read = transition owed.kclo_read }
  | None -> ()

(* Runs on every loop iteration. A read the chat pane started for the same
   slot is let finish first, so this record moves only with its own read. *)
let launch_owed_keeper_calls state ~mailbox =
  match state.keeper_calls_owed with
  | None -> ()
  | Some owed ->
      if owed.kclo_reading != state.detail_read_authority
      then state.keeper_calls_owed <- None
      else if
        Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) owed.kclo_read
        && state.view = Keepers Keeper_calls
        && (match selected_keeper state with
            | Some keeper -> String.equal keeper.k_name owed.kclo_keeper
            | None -> false)
        && server_authority_ready state
        && not state.keeper_calls_loading
      then begin
        settle_calls_owed state ~keeper_name:owed.kclo_keeper Masc_tui_owed_read.started;
        Masc_tui_work_requests.Schedule_call_requests.launch_keeper_calls_load ~force:true state ~mailbox owed.kclo_keeper
      end

let owe_keeper_calls_read state ~mailbox ~keeper_name =
  update_calls_owed state ~keeper_name Masc_tui_owed_read.changed;
  launch_owed_keeper_calls state ~mailbox

(* The Board post being read or replied to reads when it opens or [r] asks, when
   [notifications/board] names it or names no post, after the operator's own
   comment or vote, on a revalidation or a resumed authority, and again after
   a failed read (RFC-0480 §3.1). *)
let board_post_on_screen state =
  if state.view = Board then
    match state.board_mode with
    | Board_read post_id -> Some post_id
    | Board_compose -> state.board_compose_reply_to
    | Board_list -> None
  else None

let settle_board_post_owed state ~post_id transition =
  match state.board_post_owed with
  | Some owed when String.equal owed.bpo_post post_id ->
      state.board_post_owed <- Some { owed with bpo_read = transition owed.bpo_read }
  | Some _ | None -> ()

(* Runs on every loop iteration. A read already in flight for the post is let
   finish first. A post no longer open drops its record: opening it again
   reads it. *)
let launch_owed_board_post state ~mailbox =
  match state.board_post_owed with
  | None -> ()
  | Some owed
    when not (Option.equal String.equal (board_post_on_screen state) (Some owed.bpo_post)) ->
      state.board_post_owed <- None
  | Some owed ->
      let post_id = owed.bpo_post in
      let reading = Board_detail.reading state.board_detail ~post_id in
      (* A read the detail retired (a mode swap, leaving and reopening) never
         completes, so its record is owed again. *)
      let read =
        if reading then owed.bpo_read else Masc_tui_owed_read.abandoned owed.bpo_read
      in
      state.board_post_owed <- Some { owed with bpo_read = read };
      if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read
         && server_authority_ready state
         && not reading
      then begin
        state.board_post_owed <-
          Some { owed with bpo_read = Masc_tui_owed_read.started read };
        Masc_tui_board_requests.start_board_post_refresh state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
          ~port:state.port ~post_id
          ~launch:(Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox
            ~boundary_error:(fun detail -> Request_failed detail)
            ~withdrawn:(fun refusal -> Request_withdrawn refusal))
      end

let owe_board_post_read state ~mailbox ~post_id =
  let owed =
    match state.board_post_owed with
    | Some owed when String.equal owed.bpo_post post_id -> owed
    | Some _ | None -> { bpo_post = post_id; bpo_read = Masc_tui_owed_read.settled }
  in
  state.board_post_owed <-
    Some { owed with bpo_read = Masc_tui_owed_read.changed owed.bpo_read };
  launch_owed_board_post state ~mailbox

(* The Board list and hearth census read again when [notifications/board]
   arrives while the Board is on screen, and after a failed read
   (RFC-0480 §3.1). The read on entering the Board and a revalidation ride the
   surface refresh. *)
let owe_board_list_read state =
  state.board_list_owed <- Masc_tui_owed_read.changed state.board_list_owed

(* A surface dataset read can end without its answer being applied: a newer
   refresh ticket supersedes it, the workspace is not this checkout's, or the
   bundle carries no answer. Such a read waits like a failed one, so a cause
   that repeats does not read back to back. *)
let unanswered_read owed =
  Masc_tui_owed_read.failed ~retry_s:Masc_tui_transport.Event_streams.stream_reconnect_s
    ~max_retry_s:keeper_execute_stream_max_reconnect_s ~now:(Masc_tui_wake.Mono.now ()) owed

(* The Planning screen's Goals and their tree read again when
   [goal_projection_changed] or [Backlog] arrives while Planning is
   on screen, and after a failed read (RFC-0480 §3.1). The read on entering
   Planning and a revalidation ride the surface refresh. *)
let owe_planning_reads state =
  state.planning_owed <- Masc_tui_owed_read.changed state.planning_owed;
  state.overview_goals_owed <- Masc_tui_owed_read.changed state.overview_goals_owed

(* Every read that asks for the Board list or a Planning dataset starts its
   debt, whatever started it: a read on entering the surface or a
   revalidation that is superseded before it answers leaves the dataset owed,
   and [launch_owed_board_list] or [launch_owed_planning] reads it again. *)
let note_owed_surface_reads_started state (needs : Masc_tui_types.surface_needs) =
  if needs.needs_board then
    state.board_list_owed <- Masc_tui_owed_read.started state.board_list_owed;
  if needs.needs_planning then
    state.planning_owed <- Masc_tui_owed_read.started state.planning_owed;
  if needs.needs_overview_goals then
    state.overview_goals_owed <- Masc_tui_owed_read.started state.overview_goals_owed

(* Any surface bundle that reads a pushed source, full or scoped, is the read
   its owed change waits on. *)
let note_pushed_reads_started state (needs : Masc_tui_types.surface_needs) =
  let wanted = Surface_read_order.sources needs in
  List.iter
    (fun source ->
      if List.mem source wanted then
        set_pushed_read state source (Masc_tui_owed_read.started (pushed_read state source)))
    Masc_tui_types.pushed_sources

(* The questions a Keeper or an installation puts to the operator read again
   when their log changes, on a resumed authority, and after a failed read
   (RFC-0480 §3.1). Every full refresh reads them too. *)
let owe_asks_read state = state.asks_owed <- Masc_tui_owed_read.changed state.asks_owed

(* The confirmations waiting for an operator read again under the same rules:
   a change or a passed deadline, a resumed authority, a failed read. *)
let owe_pending_confirms_read state =
  state.pending_confirms_owed <- Masc_tui_owed_read.changed state.pending_confirms_owed

let launch_asks_read state ~mailbox =
  match state.server_identity with
  | None -> false
  | Some expected_workspace ->
    (match Masc_tui_types.begin_asks_read state with
     | None -> false
     | Some asks_request ->
       let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
       let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
       (* The guard's refusal stays [Request_withdrawn]: that read was not sent
          and is no failed read (RFC §2). *)
       Masc_tui_transport.Workspace_admission.launch_async_read_with state ~mailbox
         ~boundary_error:(fun detail -> Request_failed detail)
         ~withdrawn:(fun refusal -> Request_withdrawn refusal)
         ~deliver:(fun asks_result ->
           enqueue_async mailbox (Ask_msg (Asks_reloaded { asks_request; asks_result })))
         (fun () ->
           Masc_tui_http.fetch_asks ~expected_workspace ~host ~port ()
           |> Result.map_error (fun detail -> Request_failed detail));
       true)

(* Runs on every loop iteration. A read already in flight, the refresh's or
   this one's, is let finish first; one that will not deliver leaves the
   questions owed again. While an answer is being sent no read starts: the
   answer reads the questions again itself. *)
let launch_owed_asks state ~mailbox =
  let reading = Snapshot_read.in_flight state.asks_read in
  let read =
    if reading then state.asks_owed else Masc_tui_owed_read.abandoned state.asks_owed
  in
  state.asks_owed <- read;
  if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read
     && server_authority_ready state
     && not reading
     && launch_asks_read state ~mailbox
  then state.asks_owed <- Masc_tui_owed_read.started read

(* The Gate snapshot reads again when the queue, the standing rules or a Gate
   mode change, on a revalidation or a resumed authority, and after a failed
   read (RFC-0480 §3.1). Entering a surface and [r] read it directly. *)
let owe_gate_snapshot_read state =
  state.gate_snapshot_owed <- Masc_tui_owed_read.changed state.gate_snapshot_owed

let fail_gate_snapshot_read state =
  state.gate_snapshot_owed <- failed_read state.gate_snapshot_owed

(* Runs on every loop iteration. A Gate read already in flight is let
   finish first; one that will not deliver leaves the snapshot owed again. *)
let launch_owed_gate_snapshot state ~mailbox =
  let reading = Snapshot_read.in_flight state.gate_snapshot_read in
  let read =
    if reading then state.gate_snapshot_owed
    else Masc_tui_owed_read.abandoned state.gate_snapshot_owed
  in
  state.gate_snapshot_owed <- read;
  if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read
     && server_authority_ready state
     && not reading
  then Masc_tui_work_requests.Approval_gate_requests.launch_gate_snapshot_load state ~mailbox

let held_calls_on_screen state =
  match state.view with
  | Overview | Approvals -> true
  | Acting | Metrics | Memory | Lanes | Clients | Board | Planning | Schedules | Verification
  | Harness | Fusion | Repositories | Code | Changes | Connectors | Runtime | Config
  | Resources | Tools | System_logs | Keepers _ ->
      false

let tool_modes_on_screen state =
  match state.view with
  | Keepers _ -> true
  | Overview | Approvals | Acting | Metrics | Memory | Lanes | Clients | Board | Planning
  | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
  | Runtime | Config | Resources | Tools | System_logs ->
      false

(* Runs on every loop iteration. A held-call read already in flight is let
   finish first; one that will not deliver leaves the listing owed again. *)
let launch_owed_held_calls state ~mailbox =
  if not (held_calls_on_screen state) then
    state.held_calls_owed <- Masc_tui_owed_read.settled
  else begin
    let reading = Snapshot_read.in_flight state.keeper_tool_approvals_read in
    let read =
      if reading then state.held_calls_owed
      else Masc_tui_owed_read.abandoned state.held_calls_owed
    in
    state.held_calls_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read
       && server_authority_ready state
       && not reading
    then Masc_tui_work_requests.Approval_gate_requests.launch_keeper_tool_approvals_load state ~mailbox
  end

let verification_on_screen state =
  match state.view with
  | Verification -> true
  | Overview | Approvals | Acting | Metrics | Memory | Lanes | Clients | Board | Planning
  | Schedules | Harness | Fusion | Repositories | Code | Changes | Connectors | Runtime
  | Config | Resources | Tools | System_logs | Keepers _ ->
      false

let repositories_on_screen state =
  match state.view with
  | Repositories -> true
  | Overview | Approvals | Acting | Metrics | Memory | Lanes | Clients | Board | Planning
  | Schedules | Verification | Harness | Fusion | Code | Changes | Connectors | Runtime
  | Config | Resources | Tools | System_logs | Keepers _ ->
      false

(* The Connectors list, outside the Browser Lane, and a Keeper's channels tab
   draw the connectors. *)
let connectors_on_screen state =
  match state.view with
  | Connectors -> Option.is_none (browser_lane_on_screen state)
  | Keepers Keeper_detail -> state.detail_tab = Detail_channels
  | Keepers (Keeper_list | Keeper_logs | Keeper_calls | Keeper_message | Keeper_runtime_pick)
  | Overview | Approvals | Acting | Metrics | Memory | Lanes | Clients | Board | Planning
  | Schedules | Verification | Harness | Fusion | Code | Changes | Repositories | Runtime
  | Config | Resources | Tools | System_logs ->
      false

(* Runs on every loop iteration. Off screen nothing is owed: arriving on the
   surface reads it. A read already in flight is let finish first. *)
let launch_owed_connectors state ~mailbox =
  if not (connectors_on_screen state) then
    state.connectors_owed <- Masc_tui_owed_read.settled
  else begin
    let reading =
      Connector_read.reading_for ~authority:state.detail_read_authority state.connectors_read
    in
    let read =
      if reading then state.connectors_owed
      else Masc_tui_owed_read.abandoned state.connectors_owed
    in
    state.connectors_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading then
      Masc_tui_surface_requests.Connector_volume_requests.launch_connectors_load state ~mailbox
  end

(* Runs on every loop iteration. Off the panes that draw runtime.toml a change
   stays owed, so a pane reached without [launch_surface_reads] still reads
   it: the Config strip moves between panes inside one view, and Lanes [e]
   opens Config_runtime itself. A read already in flight is let finish
   first. *)
let launch_owed_overview state ~mailbox =
  let read =
    if state.overview_inflight then state.overview_owed
    else Masc_tui_owed_read.abandoned state.overview_owed
  in
  state.overview_owed <- read;
  if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not state.overview_inflight then
    launch_overview_load state ~mailbox

let launch_owed_runtime_surface state ~mailbox =
  if state.view <> Runtime then state.runtime_surface_owed <- Masc_tui_owed_read.settled
  else begin
    let reading = Option.is_some state.runtime_surface_inflight in
    let read =
      if reading then state.runtime_surface_owed
      else Masc_tui_owed_read.abandoned state.runtime_surface_owed
    in
    state.runtime_surface_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading then
      Masc_tui_surface_requests.Memory_repository_requests.launch_runtime_surface_load state ~mailbox ~force:false
  end

let launch_owed_runtime_config state ~mailbox =
  let reading =
    match state.runtime_config_read with
    | `Loading _ -> true
    | `Idle -> false
  in
  let read =
    if reading then state.runtime_config_owed
    else Masc_tui_owed_read.abandoned state.runtime_config_owed
  in
  state.runtime_config_owed <- read;
  if runtime_config_on_screen state
     && Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read
     && not reading
  then Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_config_load state ~mailbox

(* Runs on every loop iteration. Off screen nothing is owed: arriving on the
   surface reads it. A read already in flight is let finish first. *)
let launch_owed_repositories state ~mailbox =
  if not (repositories_on_screen state) then
    state.repositories_owed <- Masc_tui_owed_read.settled
  else begin
    let reading = state.repositories_inflight in
    let read =
      if reading then state.repositories_owed
      else Masc_tui_owed_read.abandoned state.repositories_owed
    in
    state.repositories_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading then
      Masc_tui_surface_requests.Memory_repository_requests.launch_repositories_load state ~mailbox
  end

(* The engine graphs' own [/health] read. It asks which server answers, as
   the refresh's probe does, outside any workspace scope: [/health] reads no
   workspace data, and the answer goes to the graphs only. *)
let launch_engine_sample_read state ~mailbox =
  let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
  Masc_tui_async_read.launch
    ~deliver:(fun result ->
      Masc_tui_transport.Workspace_admission.enqueue mailbox
        (Engine_sample_read (Masc_tui_engine_samples.reading_of_server result)))
    (fun () ->
      Masc_tui_workspace_read.without_binding (fun () ->
        Masc_tui_workspace_precondition.without (fun () ->
          Masc_tui_loader.load_server_reading ~host ~port)))

(* The engine graphs' samples (RFC tui-one-screen-grammar section 5.6). Runs
   on every loop iteration, as the owed reads do, and sets no timer of its
   own. Off the engine view its samples go and nothing is due. On it, a due
   sample takes the newest [/health] answer of the last two seconds, whoever
   asked for it, or asks [/health] itself, one read at a time. When the
   refresh pass is backing off, times without any answer stay blank. A
   sample changes the graphs and requests a frame (section 8).
   The view is on screen only while the surface is the frame: the help sheet,
   a reader, the account server's screen or the too-small notice draws over
   the whole terminal, and the graphs under it are not sampled. *)
let step_engine_samples state ~mailbox ~render_schedule =
  let terminal_rows, cols = get_terminal_size () in
  let now = Masc_tui_wake.Mono.now () in
  let capacity =
    match Masc_tui_render_metrics.engine_graph_capacity ~cols state with
    | None -> None
    | Some capacity ->
      (match
         Masc_tui_render.frame_choice state ~terminal_rows
           ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ()))
           ~now:(Unix.gettimeofday ())
       with
       | `Surface -> Some capacity
       | `Too_small _ | `Play_card _ | `Account_login _ | `Account_server _ | `Palette
       | `Collab _ | `Lane_addons _ | `Detail_reading _ | `About | `Context
       | `Keeper_deletions | `Help | `Agenda | `Answering | `Queue _ | `Link
       | `Client_detail _ -> None)
  in
  match capacity with
  | None -> state.engine_samples <- Masc_tui_engine_samples.hidden state.engine_samples
  | Some capacity ->
    let allow_read =
      Masc_tui_refresh_pace.screen_read_starts ~now:(Masc_tui_wake.Mono.now ()) Owed_read_due
        state.refresh_pace
    in
    let samples, step =
      Masc_tui_engine_samples.tick ~allow_read
        (Masc_tui_engine_samples.shown state.engine_samples ~now ~capacity)
        ~now ~newest:(Masc_tui_loader.health_answer ())
    in
    state.engine_samples <- samples;
    (match step with
     | Masc_tui_engine_samples.Nothing -> ()
     | Masc_tui_engine_samples.Sampled ->
       Render_schedule.request render_schedule Render_schedule.Background
     | Masc_tui_engine_samples.Read -> launch_engine_sample_read state ~mailbox)

let memory_health_on_screen state =
  match state.view with
  | Memory | Metrics | Keepers Keeper_list -> true
  | Overview | Approvals | Acting | Lanes | Clients | Board | Planning | Schedules
  | Verification | Harness | Repositories | Fusion | Code | Changes | Connectors | Runtime
  | Config | Resources | Tools | System_logs
  | Keepers
      ( Keeper_detail | Keeper_logs | Keeper_calls | Keeper_message
      | Keeper_runtime_pick ) ->
      false

(* Runs on every loop iteration. Off screen nothing is owed: arriving reads the
   fleet. One memory health read runs at a time. A fleet read that is owed goes
   first, and a failed read's wait holds the rows too. With nothing owed for the
   fleet, the rows pushes named are read one at a time. While a row of the held
   answer stands refused no row can be merged (the server counted that row and
   this build cannot), so the pushes owe the fleet instead. *)
let launch_owed_memory_health state ~mailbox =
  if not (memory_health_on_screen state) then begin
    state.memory_health_owed <- Masc_tui_owed_read.settled;
    state.memory_health_rows_owed <- []
  end
  else if not state.memory_health_inflight then begin
    let read = Masc_tui_owed_read.abandoned state.memory_health_owed in
    state.memory_health_owed <- read;
    match read, state.memory_health, state.memory_health_rows_owed with
    | (Masc_tui_owed_read.Owed _ | Waiting _ | Reading _), _, _ ->
        if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read then
          Masc_tui_surface_requests.Memory_repository_requests.launch_memory_health_load state ~mailbox
    | Settled, Some held, _ :: _ ->
        (match held.Masc.Tui_decode_memory_health.mhs_refused_keepers with
         | [] -> Masc_tui_surface_requests.Memory_repository_requests.launch_owed_memory_health_row state ~mailbox
         | _ :: _ ->
             state.memory_health_rows_owed <- [];
             owe_memory_health_read state)
    | Settled, Some _, [] -> ()
    | Settled, None, _ :: _ -> owe_memory_health_read state
    | Settled, None, [] -> ()
  end

(* The world line reads on arrival, revalidation and World_memory changes.
   Success settles its debt; a change during the read owes one follow-up and
   a failure keeps the shared typed retry. Hidden views keep their debt. *)
let launch_owed_memory_world state ~mailbox =
  let visible = (state.view = Memory && Option.is_none state.memory_facts_keeper)
    || (state.view = Keepers Keeper_list
        && Masc_tui_keeper_list_model.has_world state.keeper_list_view) in
  if visible && server_authority_ready state then
    match Masc_tui_memory_world.start ~now:(Masc_tui_wake.Mono.now ()) state.memory_world with
    | None -> ()
    | Some (next, request) ->
        state.memory_world <- next;
        let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
        Masc_tui_transport.Workspace_admission.launch_json_read state ~mailbox
          ~boundary_error:(fun detail -> Request_failed detail)
          ~withdrawn:(fun refusal -> Request_withdrawn refusal)
          ~deliver:(fun result -> Memory_msg (Memory_world_loaded (request, result)))
          (fun () -> Masc_tui_loader.load_memory_world ~host ~port
            |> Result.map_error (fun detail -> Request_failed detail))

(* Runs on every loop iteration. The input pane reads when the selection moves
   to another Keeper, when a memory health answer owes it, and again after a
   failed read, which waits like any owed read (RFC-0480 §3.1). Off Memory
   nothing is owed: arriving reads the fleet, whose answer owes the pane. The
   facts browser covers the pane and keeps what it owes, so closing the
   browser reads a change that came meanwhile. *)
let launch_owed_memory_input state ~mailbox =
  if not (state.view = Memory) then
    state.memory_input_owed <- Masc_tui_owed_read.settled
  else begin
    let reading = Masc_tui_fetched.in_flight state.memory_input in
    let read =
      if reading then state.memory_input_owed
      else Masc_tui_owed_read.abandoned state.memory_input_owed
    in
    state.memory_input_owed <- read;
    Masc_tui_surface_requests.Memory_repository_requests.launch_memory_input_load state ~mailbox
      ~refresh:((not reading) && Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read)
  end

let harness_on_screen state =
  match state.view with
  | Harness -> true
  | Overview | Approvals | Acting | Metrics | Memory | Lanes | Clients | Board | Planning
  | Schedules | Verification | Repositories | Fusion | Code | Changes | Connectors | Runtime
  | Config | Resources | Tools | System_logs | Keepers _ ->
      false

(* Runs on every loop iteration. Off screen nothing is owed: arriving on the
   surface reads it. A read already in flight is let finish first. *)
(* A Keeper's login attempt read runs on every loop: the wait does not sit
   behind a surface, because the operator who consented may be standing in
   front of any tab. A Keeper nobody waits on owes nothing; a read in flight
   is let finish first. *)
let launch_owed_identity_logins state ~mailbox =
  let now = Unix.gettimeofday () in
  Masc_tui_types.owe_identity_deadline_reads state ~now;
  if server_authority_ready state then
    Masc_tui_types.identity_login_pending_keepers state ~now
    |> List.iter (fun keeper_name ->
         let ready = Masc_tui_types.identity_login_read_ready state ~now keeper_name in
         if ready then
           Masc_tui_types.update_identity_login_read state keeper_name
             Masc_tui_owed_read.abandoned;
         let read = Masc_tui_types.identity_login_read state keeper_name in
         if ready && Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read then begin
           Masc_tui_types.update_identity_login_read state keeper_name
             Masc_tui_owed_read.started;
           Masc_tui_identity_requests.launch_view state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
             ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state mailbox) keeper_name
         end)

(* The Clients roster's owed read lives in {!Masc_tui_types}: owe, begin,
   abandon and settle, with the settle decision testable without the event
   loop. *)

(* Runs on every loop iteration. Off the Clients surface nothing is owed:
   arriving reads it. A read in flight is let finish first; one whose
   generation was superseded returns abandoned. *)
let launch_owed_clients state ~mailbox =
  if state.view <> Clients then state.clients_owed <- Masc_tui_owed_read.settled
  else begin
    let reading = state.clients_surface_inflight in
    let read =
      if reading then state.clients_owed
      else Masc_tui_owed_read.abandoned state.clients_owed
    in
    state.clients_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading then
      launch_clients_load state ~mailbox
  end

let launch_owed_harness state ~mailbox =
  if not (harness_on_screen state) then state.harness_owed <- Masc_tui_owed_read.settled
  else begin
    (match state.harness_stale_at with
     | Some stale_at
       when Masc_tui_wake.reached_wall Masc_tui_wake.Harness_stale
              ~now:(Unix.gettimeofday ()) ~at:stale_at ->
         state.harness_stale_at <- None;
         owe_harness_read state
     | Some _ | None -> ());
    let reading = state.harness_inflight in
    let read =
      if reading then state.harness_owed
      else Masc_tui_owed_read.abandoned state.harness_owed
    in
    state.harness_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading then
      launch_harness_load state ~mailbox
  end

(* Runs on every loop iteration. Off screen nothing is owed: arriving on the
   surface reads it. A read already in flight is let finish first. *)
let launch_owed_verification state ~mailbox =
  if not (verification_on_screen state) then
    state.verification_owed <- Masc_tui_owed_read.settled
  else begin
    let reading = state.verification_inflight in
    let read =
      if reading then state.verification_owed
      else Masc_tui_owed_read.abandoned state.verification_owed
    in
    state.verification_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading then
      launch_verification_load state ~mailbox
  end

(* Runs on every loop iteration. A turns read already in flight, whoever
   started it, is let finish first; a slot freed without an answer leaves the
   turns owed again. *)
let launch_owed_keeper_turns state ~mailbox =
  if List.exists (fun keeper_name -> preview_on_screen state ~keeper_name)
       state.keeper_previews_unread
  then owe_keeper_turns_read state;
  let reading = state.keeper_turns_inflight in
  let read =
    if reading then state.keeper_turns_owed
    else Masc_tui_owed_read.abandoned state.keeper_turns_owed
  in
  state.keeper_turns_owed <- read;
  if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading
     && keeper_turns_in_use state
  then Masc_tui_chat_dispatch.Chat_watching.launch_keeper_turns_load state ~mailbox

(* Runs on every loop iteration. A waiting read that failed is read again
   after a growing wait; one in flight is let finish first. *)
let launch_owed_keeper_waiting state ~mailbox =
  let reading = Keeper_waiting_read.in_flight state.keeper_waiting_read in
  let read =
    if reading then state.keeper_waiting_owed
    else Masc_tui_owed_read.abandoned state.keeper_waiting_owed
  in
  state.keeper_waiting_owed <- read;
  if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading
     && keeper_waiting_in_use state then
    Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load state ~mailbox

(* Runs on every loop iteration. The modes are not read while an operator's
   own mode press is in flight: the answer would be the stance from before
   it. An answer the listing refuses leaves the modes owed again. *)
let launch_owed_tool_modes state ~mailbox =
  if not (tool_modes_on_screen state) then
    state.tool_modes_owed <- Masc_tui_owed_read.settled
  else if
    Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) state.tool_modes_owed
    && server_authority_ready state
    && not (Approval.Flow.action_inflight state.approval_flow)
  then begin
    state.tool_modes_owed <- Masc_tui_owed_read.started state.tool_modes_owed;
    Masc_tui_work_requests.Approval_gate_requests.launch_keeper_tool_modes_load state ~mailbox
  end

let async_requests_on_screen state =
  match state.view with
  | Keepers Keeper_list | Tools -> true
  | Keepers (Keeper_detail | Keeper_logs | Keeper_calls | Keeper_message | Keeper_runtime_pick)
  | Overview | Approvals | Acting | Metrics | Memory | Lanes | Clients | Board | Planning
  | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
  | Runtime | Config | Resources | System_logs ->
      false

(* Runs on every loop iteration. A read already in flight is let finish
   first; one that will not deliver leaves the requests owed again. *)
let launch_owed_async_requests state ~mailbox =
  if not (async_requests_on_screen state) then
    state.async_requests_owed <- Masc_tui_owed_read.settled
  else begin
    let reading = state.tools_async_observation_inflight in
    let read =
      if reading then state.async_requests_owed
      else Masc_tui_owed_read.abandoned state.async_requests_owed
    in
    state.async_requests_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read
       && server_authority_ready state
       && not reading
    then begin
      state.async_requests_owed <- Masc_tui_owed_read.started read;
      Masc_tui_work_requests.Tools_task_requests.launch_tools_async_observation_load state ~mailbox
    end
  end

(* The open async request detail reads again when its Keeper's requests or
   one of its execution journals change, on a revalidation, and after a
   failed read (RFC-0480 §3.4). *)
let owe_tools_async_detail_read state keeper =
  if Option.exists (fun (target : Masc.Tui_decode_async_request.target) ->
       String.equal target.keeper_name keeper) state.tools_async_selection
  then state.tools_async_detail_owed <- Masc_tui_owed_read.changed state.tools_async_detail_owed

let owe_selected_tools_async_detail_read state =
  Option.iter (fun (target : Masc.Tui_decode_async_request.target) ->
      owe_tools_async_detail_read state target.keeper_name)
    state.tools_async_selection

(* Runs on every loop iteration. Only an open request detail owes a read;
   opening it reads it. A detail left open under another view keeps what it
   owes, so a push that came meanwhile reads it on return. *)
let launch_owed_tools_async_detail state ~mailbox =
  if not (state.tools_async_detail_open && Option.is_none state.tools_async_task_source) then
    state.tools_async_detail_owed <- Masc_tui_owed_read.settled
  else if state.view = Tools && state.tools_pane = Tools_async then begin
    let reading = Option.is_some state.tools_async_detail_request in
    let read =
      if reading then state.tools_async_detail_owed
      else Masc_tui_owed_read.abandoned state.tools_async_detail_owed
    in
    state.tools_async_detail_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading then
      Masc_tui_work_requests.Tools_task_requests.launch_tools_async_detail state ~mailbox
  end

(* The open source Task's body reads again when the backlog changes, on a
   revalidation, and after a failed read (RFC-0480 §3.4). Its history reads
   its first page on opening and more on request; [r] reads it again. *)
let owe_tools_async_task_read state =
  state.tools_async_task_owed <- Masc_tui_owed_read.changed state.tools_async_task_owed

(* Runs on every loop iteration. Only an open source Task owes a read. A
   Task left open under another view keeps what it owes. *)
let launch_owed_tools_async_task state ~mailbox =
  if not (state.tools_async_detail_open && Option.is_some state.tools_async_task_source) then
    state.tools_async_task_owed <- Masc_tui_owed_read.settled
  else if state.view = Tools && state.tools_pane = Tools_async then begin
    let reading = Option.is_some state.tools_async_task_body_request in
    let read =
      if reading then state.tools_async_task_owed
      else Masc_tui_owed_read.abandoned state.tools_async_task_owed
    in
    state.tools_async_task_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading then
      Masc_tui_work_requests.Tools_task_requests.launch_tools_async_task ~terminal_size:Masc_tui_render_prim.get_terminal_size state ~mailbox
  end

(* Runs on every loop iteration. The selected Keeper's inventory reads while
   any pane but Async is on screen, the skills catalog and each roster
   Keeper's Usage answer while the Usage pane is, the selected Keeper's
   activations while the Activations pane is, each when a push, an arrival
   or a failed read owes it (RFC-0483 §4.3). A part in flight is let
   finish first; one that will not deliver is owed again. What is owed off
   screen waits for its pane. *)
let launch_owed_tools state ~mailbox =
  let async_open =
    Option.is_some state.tools_async_task_source
    || (state.tools_pane = Tools_async && state.tools_async_detail_open)
  in
  if state.view = Tools && not async_open then begin
    let selected = Option.map (fun (row : keeper) -> row.k_name) (selected_keeper state) in
    (* A part in flight for a Keeper no longer selected is not this
       Keeper's read. *)
    let pending part =
      match part with
      | Tools_catalog_read | Tools_usage_read _ -> List.mem part state.tools_skill_pending
      | Tools_inventory_read | Tools_activations_read | Tools_async_read ->
          (match state.tools_read_inflight with
           | Some request when Option.equal String.equal request.tri_keeper selected ->
               List.mem part request.tri_pending
           | Some _ | None -> false)
    in
    let now = Masc_tui_wake.Mono.now () in
    let due part owed set =
      let reading = pending part in
      let read = if reading then owed else Masc_tui_owed_read.abandoned owed in
      if read != owed then set read;
      Masc_tui_owed_read.due ~now read && not reading
    in
    (* Every pane but Async draws the selected Keeper's Skill heading from
       the inventory's skill profiles, and its Skill keys act on them. The
       inventory follows the selected Keeper however the selection moved,
       like the activations. A wait after another Keeper's failed read is
       not this Keeper's: the read is owed now, with no failures behind it. *)
    let inventory_parts () =
      (match state.tools_inventory_owed with
       | Masc_tui_owed_read.(Settled | Waiting _)
         when not (Option.equal String.equal state.tools_inventory_keeper selected) ->
           state.tools_inventory_owed <-
             Masc_tui_owed_read.changed Masc_tui_owed_read.settled
       | Masc_tui_owed_read.(Settled | Owed _ | Reading _ | Waiting _) -> ());
      if due Tools_inventory_read state.tools_inventory_owed
           (fun owed -> state.tools_inventory_owed <- owed)
      then [ Tools_inventory_read ]
      else []
    in
    let parts =
      match state.tools_pane with
      | Tools_usage ->
          (* A Keeper that left the roster leaves its readings with it. *)
          keep_roster_skill_usage state;
          inventory_parts ()
          @ (if due Tools_catalog_read state.tools_catalog_owed
                  (fun owed -> state.tools_catalog_owed <- owed)
             then [ Tools_catalog_read ]
             else [])
          @ List.filter_map
              (fun (row : keeper) ->
                 let part = Tools_usage_read row.k_name in
                 if due part (keeper_skill_usage_owed state row.k_name)
                      (set_keeper_skill_usage_owed state row.k_name)
                 then Some part
                 else None)
              state.keepers
      | Tools_activations ->
          (* The pane follows the selected Keeper however the selection
             moved: the roster loading, a Keeper leaving it, or a key. *)
          (* A wait after the other Keeper's failed read is not this
             Keeper's: the read is owed now, with no failures behind it. *)
          (match state.tools_activations_owed with
           | Masc_tui_owed_read.(Settled | Waiting _)
             when activations_held_for_another ~selected state.tools_activations
                    state.tools_activations_error ->
               state.tools_activations_owed <-
                 Masc_tui_owed_read.changed Masc_tui_owed_read.settled
           | Masc_tui_owed_read.(Settled | Owed _ | Reading _ | Waiting _) -> ());
          inventory_parts ()
          @ (if due Tools_activations_read state.tools_activations_owed
                  (fun owed -> state.tools_activations_owed <- owed)
             then [ Tools_activations_read ]
             else [])
      | Tools_surface | Tools_storage
      | Tools_catalog (Tools_catalog_list | Tools_catalog_volumes _) -> inventory_parts ()
      | Tools_async -> []
    in
    match parts with
    | [] -> ()
    | _ :: _ -> Masc_tui_work_requests.Tools_task_requests.launch_tools_parts state ~mailbox parts
  end

(* The schedule list behind the agenda strip, drawn on every surface, and the
   Schedules page read again when the server says the schedules changed, on a
   revalidation or a resumed authority, and after a failed read
   (RFC-0480 §3.1). Entering Schedules and [r] read them directly. Each owes
   its own read: the two can be in flight at once, and one answering says
   nothing of the other. *)
let owe_schedules_read state =
  state.schedules_agenda_owed <- Masc_tui_owed_read.changed state.schedules_agenda_owed;
  state.schedules_page_owed <- Masc_tui_owed_read.changed state.schedules_page_owed

(* The agenda strip says its list may be behind until a read that began after
   this point answers: on a schedule change, on an observer reopen that did
   not resume cleanly, and after lost events. A read in flight is overtaken;
   its successor is the owed read, which bursts share. *)
let owe_agenda_revalidation state =
  state.schedules_agenda_freshness <- Masc_tui_agenda.Refresh_needed;
  owe_schedules_read state

let settled_schedule_read read = function
  | Ok _ -> Masc_tui_owed_read.succeeded read
  | Error _ -> failed_read read

(* Runs on every loop iteration. A read already in flight is let finish
   first; one that will not deliver leaves its surface owed again. Off
   Schedules the page owes nothing: entering it reads the page. On the first
   page the page read carries the agenda, so it also waits for an agenda read
   in flight rather than overtake it. *)
let launch_owed_schedules state ~mailbox =
  let page_on_screen = state.view = Schedules in
  let page_reading = Snapshot_read.in_flight state.schedules_read in
  let page_carries_agenda = Option.is_none state.schedules_page.sp_cursor in
  state.schedules_agenda_owed <-
    (if Snapshot_read.in_flight state.schedules_agenda_read then state.schedules_agenda_owed
     else Masc_tui_owed_read.abandoned state.schedules_agenda_owed);
  state.schedules_page_owed <-
    (if not page_on_screen then Masc_tui_owed_read.settled
     else if page_reading then state.schedules_page_owed
     else Masc_tui_owed_read.abandoned state.schedules_page_owed);
  if server_authority_ready state then begin
    let now = Masc_tui_wake.Mono.now () in
    let intent = Snapshot_read.Refresh in
    if page_on_screen && not page_reading
       && not (page_carries_agenda && Snapshot_read.in_flight state.schedules_agenda_read)
       && Masc_tui_owed_read.due ~now state.schedules_page_owed
    then Masc_tui_work_requests.Schedule_call_requests.launch_schedules_load ~intent state ~mailbox;
    if not (Snapshot_read.in_flight state.schedules_agenda_read)
       && Masc_tui_owed_read.due ~now state.schedules_agenda_owed
    then Masc_tui_work_requests.Schedule_call_requests.launch_schedule_agenda_load ~intent state ~mailbox
  end

(* The Keeper whose schedules are drawn: the chat pane's Keeper, the Keeper
   the Automation tab shows, or the Keeper under the cursor while the Story
   window is open (its story page tells the last wake from the same page). *)
let keeper_schedules_on_screen state =
  match state.view with
  | Keepers Keeper_message -> state.msg_target_keeper_name
  | Keepers Keeper_detail -> (
      match state.detail_tab with
      | Detail_automation -> Option.map (fun (keeper : keeper) -> keeper.k_name) (selected_keeper state)
      | Detail_info | Detail_items | Detail_sandbox | Detail_instructions | Detail_secrets
      | Detail_github | Detail_identity | Detail_channels | Detail_runs | Detail_terminal ->
          None)
  | Keepers Keeper_list -> (
      match state.keeper_story with
      | Some _ -> Option.map (fun (keeper : keeper) -> keeper.k_name) (selected_keeper state)
      | None -> None)
  | Keepers (Keeper_logs | Keeper_calls | Keeper_runtime_pick)
  | Overview | Approvals | Acting | Metrics | Memory | Lanes | Clients | Board | Planning
  | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
  | Runtime | Config | Resources | Tools | System_logs ->
      None

(* The Keeper whose newest turns the story page draws: the Keeper under the
   cursor while the Story window is open on that page. *)
let keeper_story_turns_on_screen state =
  match state.keeper_story with
  | Some Masc_tui_keeper_story.Story when state.view = Keepers Keeper_list ->
      keeper_schedules_on_screen state
  | Some
      ( Masc_tui_keeper_story.Story
      | Masc_tui_keeper_story.Schedule
      | Masc_tui_keeper_story.Memory
      | Masc_tui_keeper_story.World )
  | None -> None

(* One Keeper's schedules read again under the same rules as the fleet list,
   while the chat pane, the Automation tab or the Story window draws them:
   drawing a Keeper owes the read, and so do a change, a revalidation, a
   resumed authority and a failed read. *)
let owe_keeper_schedules_read state =
  Option.iter
    (fun keeper ->
      let read =
        match state.keeper_schedules_owed with
        | Some owed when String.equal owed.kso_keeper keeper -> owed.kso_read
        | Some _ | None -> Masc_tui_owed_read.settled
      in
      state.keeper_schedules_owed <-
        Some { kso_keeper = keeper; kso_read = Masc_tui_owed_read.changed read })
    (keeper_schedules_on_screen state)

(* A queue or reaction write owes a schedule list a read only where a drawn
   row reads that Keeper's queue (RFC-0480 §7: filter by the name first). *)
let owe_schedule_reads_for_queue_writes state ~keepers =
  (match state.view, state.schedules with
   | Schedules, Some snapshot when schedule_rows_read_queue_of ~keepers snapshot.scs_rows ->
       owe_schedules_read state
   | Schedules, (Some _ | None) | (Overview | Acting | Metrics | Memory | Lanes | Clients | Board
     | Approvals | Planning | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
     | Runtime | Config | Resources | Tools | System_logs | Keepers _), _ ->
       ());
  match keeper_schedules_on_screen state with
  | None -> ()
  | Some keeper ->
      let rows_read_the_queue =
        match state.keeper_schedules with
        | Some (listed, snapshot) when String.equal keeper listed ->
            schedule_rows_read_queue_of ~keepers snapshot.scs_rows
        (* The drawn Keeper's rows are not read yet; its own queue may be
           theirs. *)
        | Some _ | None -> List.mem keeper keepers
      in
      if rows_read_the_queue then owe_keeper_schedules_read state

(* A good answer that the pane did not take, or that is not the page it draws,
   read nothing for it: the record stays in flight, and the loop owes the read
   again as soon as none is on the wire. *)
let settle_keeper_schedules_read state ~keeper ~settles result =
  match state.keeper_schedules_owed with
  | Some owed when String.equal owed.kso_keeper keeper ->
      let read =
        match result with
        | Ok _ -> if settles then Masc_tui_owed_read.succeeded owed.kso_read else owed.kso_read
        | Error _ -> failed_read owed.kso_read
      in
      state.keeper_schedules_owed <- Some { owed with kso_read = read }
  | Some _ | None -> ()

(* A read of this Keeper's schedules is on the wire and still the current
   one for its tab. *)
let keeper_schedules_reading state ~keeper_name =
  match state.keeper_schedules_pending with
  | Some (request, _, _) when String.equal request.drr_keeper keeper_name -> (
      match pending_detail_read state ~tab:Detail_automation ~keeper:keeper_name with
      | Some current -> current.drr_generation = request.drr_generation
      | None -> false)
  | Some _ | None -> false

(* The answer is the current read of its Keeper's schedules, not one a newer
   read replaced. *)
let keeper_schedules_answer_current state (request : keeper_schedule_page_request) =
  match pending_detail_read state ~tab:Detail_automation ~keeper:request.kspr_detail.drr_keeper with
  | Some current -> current.drr_generation = request.kspr_detail.drr_generation
  | None -> false

(* Runs on every loop iteration. The record follows the Keeper drawn: a
   Keeper no longer drawn drops it, and a Keeper newly drawn owes the read.
   A read already on the wire for it answers that, once its answer is the page
   the pane draws ([keeper_schedules_answer_settles]). *)
let launch_owed_keeper_schedules state ~mailbox =
  match keeper_schedules_on_screen state with
  | None -> state.keeper_schedules_owed <- None
  | Some keeper_name ->
      let reading = keeper_schedules_reading state ~keeper_name in
      let owed =
        match state.keeper_schedules_owed with
        | Some owed when String.equal owed.kso_keeper keeper_name -> owed
        | Some _ | None ->
            let read = Masc_tui_owed_read.changed Masc_tui_owed_read.settled in
            { kso_keeper = keeper_name;
              kso_read = (if reading then Masc_tui_owed_read.started read else read) }
      in
      let read =
        if reading then owed.kso_read else Masc_tui_owed_read.abandoned owed.kso_read
      in
      state.keeper_schedules_owed <- Some { owed with kso_read = read };
      (* The Story window follows the cursor, so it has one Keeper's page on
         the wire at a time: the Keeper the cursor has come to waits for the
         read in flight, and every Keeper the cursor passed meanwhile starts
         none. *)
      let window_waits =
        state.view = Keepers Keeper_list
        && List.exists
             (fun (request : detail_read_request) ->
                request.drr_tab = Detail_automation
                && not (String.equal request.drr_keeper keeper_name))
             state.detail_reads
      in
      if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read
         && server_authority_ready state
         && not reading
         && not window_waits
      then begin
        Masc_tui_work_requests.Schedule_call_requests.launch_keeper_schedules_load state ~mailbox ~keeper_name;
        if keeper_schedules_reading state ~keeper_name then
          state.keeper_schedules_owed <-
            Some { owed with kso_read = Masc_tui_owed_read.started read }
      end

(* The story page's turns are read again after a push about the Keeper's
   turns, a revalidation, a resumed authority and a failed read. *)
let owe_keeper_story_turns_read state =
  state.keeper_story_turns_owed <- Masc_tui_owed_read.changed state.keeper_story_turns_owed

(* A push about turns owes the read only where the page draws that Keeper
   (RFC-0480 §7: filter by the name first). *)
let owe_keeper_story_turns_read_for state ~keepers =
  match keeper_story_turns_on_screen state with
  | Some keeper when List.mem keeper keepers -> owe_keeper_story_turns_read state
  | Some _ | None -> ()

(* Runs on every loop iteration. While the page is not drawn the read stays
   owed, so drawing it again reads it again: turns held from before the window
   closed are not the newest. One read is on the wire at a time: the Keeper the
   cursor has come to waits for the read in flight, and every Keeper the cursor
   passed meanwhile starts none. *)
let launch_owed_keeper_story_turns state ~mailbox =
  match keeper_story_turns_on_screen state with
  | None ->
      state.keeper_story_turns_owed <- Masc_tui_owed_read.changed Masc_tui_owed_read.settled
  | Some keeper_name ->
      let reading = Masc_tui_fetched.in_flight state.keeper_story_turns in
      let read =
        if reading then state.keeper_story_turns_owed
        else Masc_tui_owed_read.abandoned state.keeper_story_turns_owed
      in
      state.keeper_story_turns_owed <- read;
      let other_keeper_reading =
        reading && Masc_tui_fetched.current_key state.keeper_story_turns <> Some keeper_name
      in
      if not other_keeper_reading then
        Masc_tui_surface_requests.Memory_repository_requests.launch_keeper_story_turns_load state ~mailbox ~keeper_name
          ~refresh:(Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read)

(* One visible demand owns each shared source. A hidden preview cannot
   replace the canonical browser's fleet or Keeper target. *)
let launch_owed_memory state ~mailbox =
  let preview =
    if state.view = Keepers Keeper_list && state.keeper_story = Some Masc_tui_keeper_story.Memory
    then Option.map (fun (keeper : keeper) -> keeper.k_name) (selected_keeper state)
    else None in
  let facts_key = match state.view, state.memory_page with
    | Memory, Memory_facts -> state.memory_facts_keeper
    | Memory, Memory_changes -> None
    | (Overview | Acting | Metrics | Keepers _ | Lanes | Clients | Board | Approvals | Planning
      | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
      | Runtime | Config | Resources | Tools | System_logs), (Memory_facts | Memory_changes) -> preview in
  (match facts_key with
   | None -> state.memory_facts_owed <- Masc_tui_owed_read.changed Masc_tui_owed_read.settled
   | Some key ->
     let reading = Masc_tui_fetched.in_flight state.memory_facts in
     let owed = if reading then state.memory_facts_owed else Masc_tui_owed_read.abandoned state.memory_facts_owed in
     state.memory_facts_owed <- owed;
     if not (reading && Masc_tui_fetched.current_key state.memory_facts <> Some key)
        && (Masc_tui_fetched.current_key state.memory_facts <> Some key
            || Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) owed) then
       if String.equal key "*" then Masc_tui_surface_requests.Memory_repository_requests.launch_all_memory_facts_load state ~mailbox
       else Masc_tui_surface_requests.Memory_repository_requests.launch_memory_facts_load state ~mailbox ~keeper_name:key);
  let activity_key = match state.view, state.memory_page, state.memory_facts_keeper with
    | Memory, Memory_changes, Some keeper when not (String.equal keeper "*") -> Some keeper
    | Memory, (Memory_facts | Memory_changes), (Some _ | None) -> None
    | (Overview | Acting | Metrics | Keepers _ | Lanes | Clients | Board | Approvals | Planning
      | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
      | Runtime | Config | Resources | Tools | System_logs), (Memory_facts | Memory_changes), (Some _ | None) -> preview in
  match activity_key with
  | None -> state.memory_activity_owed <- Masc_tui_owed_read.changed Masc_tui_owed_read.settled
  | Some keeper_name ->
    let reading = Masc_tui_fetched.in_flight state.memory_activity in
    let owed = if reading then state.memory_activity_owed else Masc_tui_owed_read.abandoned state.memory_activity_owed in
    state.memory_activity_owed <- owed;
    if not (reading && Masc_tui_fetched.current_key state.memory_activity <> Some keeper_name) then
      Masc_tui_surface_requests.Memory_repository_requests.launch_memory_activity_read state ~mailbox ~keeper_name
        ~refresh:(Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) owed)
        state.memory_activity owed
        ~set_source:(fun source -> state.memory_activity <- source)
        ~set_owed:(fun owed -> state.memory_activity_owed <- owed)
        ~deliver:(fun request result -> Keeper_memory_activity_loaded (request, result))
        (fun () -> Masc_tui_http.fetch_keeper_memory_activity ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port ~keeper_name)

(* The Keeper whose chat pane is open; its native tasks and child content are
   drawn beside the transcript. *)
let chat_keeper_on_screen state =
  match state.view with
  | Keepers Keeper_message -> state.msg_target_keeper_name
  | Keepers (Keeper_list | Keeper_detail | Keeper_logs | Keeper_calls | Keeper_runtime_pick)
  | Overview | Approvals | Acting | Metrics | Memory | Lanes | Clients | Board | Planning
  | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
  | Runtime | Config | Resources | Tools | System_logs ->
      None

(* The chat pane's journals read when the pane opens on a Keeper, when the
   server announces a record in one, on a revalidation or a resumed
   authority, and again after a failed read (RFC-0480 §3.1). *)
let owe_chat_journal owed ~keeper =
  let read =
    match owed with
    | Some { cjo_keeper; cjo_read } when String.equal cjo_keeper keeper -> cjo_read
    | Some _ | None -> Masc_tui_owed_read.settled
  in
  Some { cjo_keeper = keeper; cjo_read = Masc_tui_owed_read.changed read }

let owe_chat_journal_read state ~keeper = function
  | Masc_tui_observer.Native_tasks_journal ->
      state.chat_native_tasks_owed <- owe_chat_journal state.chat_native_tasks_owed ~keeper
  | Masc_tui_observer.Child_content_journal ->
      state.chat_child_content_owed <- owe_chat_journal state.chat_child_content_owed ~keeper

let owe_chat_journal_reads state =
  Option.iter
    (fun keeper ->
      owe_chat_journal_read state ~keeper Masc_tui_observer.Native_tasks_journal;
      owe_chat_journal_read state ~keeper Masc_tui_observer.Child_content_journal)
    (chat_keeper_on_screen state)

let settle_chat_journal owed ~keeper ~succeeded =
  match owed with
  | Some ({ cjo_keeper; cjo_read } as owed) when String.equal cjo_keeper keeper ->
      Some
        { owed with
          cjo_read =
            (if succeeded then Masc_tui_owed_read.succeeded cjo_read else failed_read cjo_read) }
  | Some _ | None -> owed

(* One journal's record follows the pane: a Keeper no longer shown drops it,
   and the pane opening on a Keeper owes the read, which a read already on
   the wire for it answers. A read on the wire is let finish first; one that
   will not deliver leaves the read owed. *)
let follow_chat_journal owed ~on_screen ~reading ~launch =
  match on_screen with
  | None -> None
  | Some keeper ->
      let busy = reading keeper in
      let owed =
        match owed with
        | Some ({ cjo_keeper; _ } as owed) when String.equal cjo_keeper keeper -> owed
        | Some _ | None ->
            let read = Masc_tui_owed_read.changed Masc_tui_owed_read.settled in
            { cjo_keeper = keeper;
              cjo_read = (if busy then Masc_tui_owed_read.started read else read) }
      in
      let read = if busy then owed.cjo_read else Masc_tui_owed_read.abandoned owed.cjo_read in
      if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && (not busy) && launch keeper
      then Some { owed with cjo_read = Masc_tui_owed_read.started read }
      else Some { owed with cjo_read = read }

(* Runs on every loop iteration. *)
let launch_owed_chat_journals state ~mailbox =
  let on_screen = chat_keeper_on_screen state in
  let ready = server_authority_ready state in
  let native_reading keeper_name = List.mem_assoc keeper_name state.msg_native_tasks_inflight in
  let child_reading keeper_name = List.mem_assoc keeper_name state.msg_child_content_inflight in
  state.chat_native_tasks_owed <-
    follow_chat_journal state.chat_native_tasks_owed ~on_screen ~reading:native_reading
      ~launch:(fun keeper_name ->
        ready
        && (launch_keeper_native_tasks_load state ~mailbox ~keeper_name;
            native_reading keeper_name));
  state.chat_child_content_owed <-
    follow_chat_journal state.chat_child_content_owed ~on_screen ~reading:child_reading
      ~launch:(fun keeper_name ->
        ready
        && (launch_keeper_child_content_load state ~mailbox ~keeper_name;
            child_reading keeper_name))


(* One reading of what the operator typed, wherever they typed it: the
   composer row or the chat pane's input. Text goes to the keeper as it
   always did; a slash word is the TUI's to act on, and a mistyped one is
   reported rather than sent to the keeper as an instruction. *)

let handle_queue_panel_key state ~base_path ~mailbox ~presented_presses (panel : queue_panel) key =
  let module Inbox = Masc_tui_queue_inspection in
  let update f = update_queue_panel state ~keeper_name:panel.qp_keeper f in
  let notice ?(failure=false) text = update (fun panel ->
    {panel with qp_notice=Some (if failure then Queue_error text else Queue_info text)}) in
  let items () = queue_panel_items state panel in
  let move direction =
    let rows = items () in
    let budget = Masc_tui_render_overlays.queue_panel_list_budget state panel in
    update (queue_panel_move ~items:rows ~budget ~direction) in
  let selected () = queue_panel_selected_id ~items:(items ()) panel in
  let act command =
    if queue_panel_list_height ~items:(items ())
        ~budget:(Masc_tui_render_overlays.queue_panel_list_budget state panel) panel = 0 then ()
    else if panel.qp_reading = Queue_loading then notice "Wait for the current queue request"
    else if panel.qp_reading <> Queue_current || not (server_authority_ready state) then
      notice ~failure:true "Queue observation is unavailable; refresh before changing it"
    else if Option.is_none (selected ()) then notice "Select a waiting item with ↑/↓"
    else match Option.bind (presented_queue_selection presented_presses)
        (resolve_queue_selection ~require_action_ready:true ~state ~panel ~items:(items ())) with
    | None -> notice ~failure:true "Queue selection changed or has not been shown; review the selected row and retry"
    | Some (Inbox.Local_message id) ->
      if queue_local_reordering_held state ~keeper_name:panel.qp_keeper then
        notice "Unsent input is retained after a failed preflight; resume it before reordering"
      else (match command with
       | `Last ->
         (match Chat_queue.move_to_end state.msg_queued ~keeper_name:panel.qp_keeper ~request_id:id with
          | Error detail -> notice ~failure:true detail
          | Ok queue -> state.msg_queued <- queue; notice "Unsent message moved to the end")
       | `Next ->
         (match Chat_queue.move_to_front state.msg_queued ~keeper_name:panel.qp_keeper ~request_id:id with
          | Error detail -> notice ~failure:true detail
          | Ok queue ->
            state.msg_queued <- queue;
            notice "Moved first locally; sending still follows admission and any holds";
            Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox))
    | Some (Inbox.Server_message id) ->
      if Masc_tui_chat_dispatch.Queue_steer.run_next_busy_for state panel.qp_keeper then
        notice "Another message priority change is pending; wait and refresh"
      else Masc_tui_collab_queue.Keeper_queue.launch_keeper_queue state ~mailbox ~keeper_name:panel.qp_keeper
          (match command with `Next -> Inbox.Run_next id | `Last -> Inbox.Move_to_end id)
    | Some (Inbox.Event (reference, incarnation)) ->
      let urgency = match command with `Next -> Keeper_event_queue.Immediate | `Last -> Low in
      Masc_tui_collab_queue.Keeper_queue.launch_keeper_queue state ~mailbox ~keeper_name:panel.qp_keeper
        (Inbox.Prioritize_event (reference, incarnation, urgency))
    | Some (Inbox.Running_message _) -> notice "This message is already running"
    | Some (Inbox.Schedule _) -> notice "Can't reorder schedule here; due work may wait" in
  if key = "?" then begin
    state.help_open <- true;
    state.help_scroll <- 0
  end else if Option.is_some panel.qp_detail then
    let count, height = Masc_tui_render_overlays.queue_panel_detail_viewport state panel in
    (match key with
     | "esc" | "\r" | "\n" | "enter" -> update (fun panel -> {panel with qp_detail=None})
     | "j" | "down" -> update (fun panel -> {panel with qp_detail_scroll=
         Masc_tui_scroll.down ~count ~height panel.qp_detail_scroll})
     | "k" | "up" -> update (fun panel -> {panel with qp_detail_scroll=
         Masc_tui_scroll.up ~count ~height panel.qp_detail_scroll})
     | "pagedown" -> update (fun panel -> {panel with qp_detail_scroll=
         Masc_tui_scroll.page_down ~count ~height panel.qp_detail_scroll})
     | "pageup" -> update (fun panel -> {panel with qp_detail_scroll=
         Masc_tui_scroll.page_up ~count ~height panel.qp_detail_scroll})
     | "home" -> update (fun panel -> {panel with qp_detail_scroll=0})
     | "end" -> update (fun panel -> {panel with qp_detail_scroll=Masc_tui_scroll.maximum ~count ~height})
     | _ -> ())
  else match key with
  | "esc" -> state.queue_panel <- None
  | "f" -> update (fun panel -> {panel with qp_layout=Masc_tui_queue_layout.toggle panel.qp_layout})
  | "j" | "down" -> move `Down
  | "k" | "up" -> move `Up
  | "\r" | "\n" | "enter" ->
    (match selected () with
     | None -> notice "Select an item with ↑/↓"
     | Some _ ->
       (match Option.bind (presented_queue_selection presented_presses)
                (resolve_queue_selection ~require_action_ready:false ~state ~panel ~items:(items ())) with
        | Some id -> update (fun panel -> {panel with qp_detail=Some id; qp_detail_scroll=0})
        | None -> notice ~failure:true "Queue selection changed or has not been shown; review the selected row and retry"))
  | "pageup" | "pagedown" | "home" | "end" ->
    let budget = Masc_tui_render_overlays.queue_panel_list_budget state panel in
    let rows = items () in
    let count = List.length rows in
    update (fun panel ->
      let old_height = queue_panel_list_height ~items:rows ~budget panel in
      let old_scroll = queue_panel_scroll ~items:rows ~height:old_height panel in
      let panel = {panel with qp_selected=None} in
      let budget = Masc_tui_render_overlays.queue_panel_list_budget state panel in
      let height = queue_panel_list_height ~items:rows ~budget panel in
      let scroll = (match key with
        | "pageup" ->
          Masc_tui_scroll.page_up ~count ~height:old_height old_scroll
          |> Masc_tui_scroll.normalize ~count ~height
        | "pagedown" ->
          Masc_tui_scroll.page_down ~count ~height:old_height old_scroll
          |> Masc_tui_scroll.normalize ~count ~height
        | "home" -> 0
        | "end" -> Masc_tui_scroll.maximum ~count ~height
        | _ -> old_scroll) in
      {panel with qp_scroll=scroll})
  | "r" -> Masc_tui_collab_queue.Keeper_queue.launch_keeper_queue state ~mailbox ~keeper_name:panel.qp_keeper Inbox.Inspect
  | "n" -> act `Next
  | "l" -> act `Last
  | _ -> ()
;;

(* Ctrl-V. A terminal never delivers a pasted image: bracketed paste carries
   text, and a clipboard holding a screenshot has no text form to send. So the
   bytes are fetched from the clipboard itself and staged the way a dropped
   file is -- same size limit, same media-type sniff, same staging list.

   The answer goes to the chat pane rather than the event log because that is
   the surface the operator is looking at when they press this key; with no
   keeper selected [chat_notice] falls back to the log on its own.

   The draft gets a marker where the image went. Without one, a staged image
   and a keystroke the terminal ate look identical from the composer, and the
   operator would learn which it was only after the turn came back. *)
let paste_clipboard_image state =
  let notice = Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:state.msg_target_keeper_name in
  match Masc_tui_clipboard.read_image () with
  | Error error ->
    notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
      ("Ctrl-V: " ^ Masc_tui_clipboard.error_to_string error)
  | Ok bytes ->
    (* Numbered by staging order and restarting at 1 with each message, so the
       marker in the draft and the attachment beside it carry the same number:
       the keeper reads "[Image #2]" and has an image-2.png to look at. *)
    let index = List.length state.msg_attachments + 1 in
    let name = Printf.sprintf "image-%d.png" index in
    (match Masc_tui_attachment.of_bytes ~name bytes with
     | Error error ->
       notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
         ("Ctrl-V: " ^ Masc_tui_attachment.error_to_string error)
     | Ok attachment ->
       Masc_tui_chat_input.Message_draft_recall.forget_recall state;
       (Masc_tui_message_input.invalidate_revision state.msg_input; state.msg_attachments <- state.msg_attachments @ [ attachment ]);
       Masc_tui_chat_input.Message_draft_recall.note_attachment_staged state;
       (* A marker run into the word before it changes that word. Only a draft
          that does not already end in whitespace needs the separator. *)
       let before = Masc_tui_message_input.before_cursor state.msg_input in
       let needs_separator =
         String.length before > 0
         && (match before.[String.length before - 1] with
             | ' ' | '\n' | '\t' -> false
             | _ -> true)
       in
       if needs_separator then Masc_tui_message_input.insert_char state.msg_input ' ';
       Masc_tui_message_input.insert state.msg_input (Printf.sprintf "[Image #%d] " index);
       notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
         (Printf.sprintf
            "pasted [Image #%d] (%s, %d bytes) \xc2\xb7 %d staged for the next message"
            index
            attachment.Masc_tui_keeper_chat_projection.mime_type
            attachment.Masc_tui_keeper_chat_projection.size
            (List.length state.msg_attachments)))
;;

(* Whether this terminal draws pictures. Asked once, before the first frame,
   and remembered: the answer cannot change while the process runs, and asking
   again would put another reply on the key stream. [None] until asked. *)
let terminal_draws_images = ref None
let active_graphics_protocol = ref Masc_tui_graphics.Unsupported_protocol
let image_cell_pixels = ref None
let browser_image_region : Masc_tui_graphics.image_region option ref = ref None

let observer_browser_scope state =
  if Option.is_some !browser_pointer_press then None
  else Masc_tui_types.observer_browser_scope_of_state state

(* Said the same at both doors a picture comes through: the capability was
   asked once and the answer cannot change, so neither does the sentence that
   reports it. *)
let terminal_draws_no_images =
  "this terminal does not draw images (it did not answer the graphics query)"

(* Pixel-graphics payloads go through here, wrapped for tmux when this process
   is inside one. tmux eats an escape it does not recognise, so
   these reach the terminal underneath only when they are wrapped -- and only
   when tmux was configured to pass them through, which is the operator's
   setting and not something this can check. *)
let write_to_terminal payload =
  let payload =
    match Sys.getenv_opt "TMUX" with
    | Some _ -> Masc_tui_graphics.tmux_wrapped payload
    | None -> payload
  in
  Masc_tui_terminal_out.write payload;
  Masc_tui_terminal_out.flush ()

(* Read once: these variables describe where this process started and do not
   change under it. An operator who attaches to its tmux pane from elsewhere
   later is why a tmux session also sends the text to the terminal. *)
let copy_session = Masc_tui_clipboard.copy_session Sys.getenv_opt

(* Copied text goes to the desktop clipboard when a tool here can take it, and
   to the terminal as OSC 52 when none can or the session needs both. Only the
   OSC 52 write lands on the terminal, so only it marks the presented frame as
   damaged. *)
let copy_text_out text =
  Masc_tui_clipboard.copy_text copy_session text ~write_osc52:(fun text ->
    Terminal_write_repair.note ();
    write_to_terminal (Link.osc52_copy text))

(* Cursor movement, SGR and text belong to the tmux pane itself, so they
   must not be wrapped in the passthrough used by the helper above. *)
let write_terminal_text payload =
  Masc_tui_terminal_out.write payload;
  Masc_tui_terminal_out.flush ()

(* RFC-msx-surface-focus-mode stage 1: the spectator's pixels ride the
   InteractiveSurface contract. The poll owns [msx_surface_frame]; the
   surface's [current] reads it and the renderer asks the surface, so
   [Masc_tui_msx] never touches the pixel fields of
   [Masc_tui_types.msx_frame] again. [press] has no consumer yet — stage 2
   routes driving keys through [handle_input]. *)
let msx_surface_frame : Masc_tui_types.msx_frame option ref = ref None

let msx_surface =
  Masc_tui_interactive.msx
    ~fetch:(fun () -> !msx_surface_frame)
    ~press:(fun _key -> false)
;;

let msx_surface_current () =
  let module S = (val msx_surface) in
  S.current ()
;;

let render_spectator (state : Masc_tui_types.state) =
  (* Layout is pure; publish its navigation bounds only after the complete
     spectator frame is written. A hidden room has no scrollable rows. *)
  let ko = state.ui_language = Masc_tui_types.Lang_ko in
  let next_room = ref (Option.map (fun room ->
    fst (Masc_tui_play_room.layout ~ko room ~width:0 ~height:0)) state.play_room) in
  let room = Option.map (fun room ~width ~height ->
    let next, lines = Masc_tui_play_room.layout ~ko room ~width ~height in
    next_room := Some next;
    lines) state.play_room in
  let room_footer = Option.map (Masc_tui_play_room.footer ~ko) state.play_room in
  (match state.machine_source with
  | Masc.Machine_lane.Msx ->
      Masc_tui_msx.render ~write:write_to_terminal ?notice:state.msx_notice
        ?room ?room_footer
        ~interaction:state.machine_interaction
        ~connection:state.connection_status ~live:state.msx_live state.msx_frame
        (msx_surface_current ())
  | Masc.Machine_lane.Dos ->
      Masc_tui_msx.render_live ~write:write_to_terminal ~connection:state.connection_status
        ?room ?room_footer
        ~activity:state.dos_activity Masc.Machine_lane.Dos state.dos_live);
  state.play_room <- !next_room
;;

let room_workspace_ready state =
  match state.workspace_identity, workspace_input_identity_of_server state.server_identity with
  | Workspace_identity_match, Some _ -> true
  | (Workspace_identity_unread | Workspace_identity_match_unconfirmed _ | Workspace_identity_mismatch _), _
  | Workspace_identity_match, None -> false

let launch_play_room state ~mailbox request =
  if room_workspace_ready state then begin
  let credential = Masc_tui_http.bind_credential () in
  Option.iter (fun expected_workspace ->
  Masc_tui_surface_requests.Prompt_preset_requests.launch_preset_call state ~mailbox
    ~call:(fun ~host ~port ->
      let fields = match Masc_tui_play_room.request_json request with
        | `Assoc fields -> fields | _ -> assert false in
      let body = `Assoc (Masc_tui_http.expected_workspace_field expected_workspace :: fields) in
      Masc_tui_http.post_json_bound ~credential ~host ~port ~path:"/api/v1/play/room"
        ~body:(Yojson.Safe.to_string body)
      |> fun result -> Result.bind result Masc.Play_room.view_of_json)
    ~wrap:(fun result -> Play_msg (Play_room_received (request, result)))) state.server_identity
  end

let poll_play_room state ~mailbox =
  if room_workspace_ready state then begin
  let watching = state.msx_open && not state.msx_menu_open in
  if watching && Option.is_some (workspace_input_identity_of_server state.server_identity)
    && Option.is_none state.play_room
  then state.play_room <- Some (Masc_tui_play_room.create ());
  Option.iter (fun room ->
    let room = Masc_tui_play_room.active room watching in
    let room, request =
      Masc_tui_play_room.poll room ~now:(Masc_tui_wake.Mono.now ()) ~machine:state.machine_source
    in
    state.play_room <- Some room;
    Option.iter (launch_play_room state ~mailbox) request) state.play_room
  end

let send_play_room state ~mailbox =
  if room_workspace_ready state then
  Option.iter (fun room ->
    let room, request =
      Masc_tui_play_room.send ~ko:(state.ui_language = Lang_ko) room ~machine:state.machine_source in
    state.play_room <- Some room;
    Option.iter (launch_play_room state ~mailbox) request) state.play_room

(* A live read names no mode, media or players. Keep the last tick metadata
   only within the same incarnation, so a keypress does not briefly erase the
   title while a replacement machine never inherits its predecessor's name. *)
let msx_frame_of_live ~previous_live ~previous_frame
    (view : Masc_tui_machine_live.view) =
  match view with
  | Masc_tui_machine_live.Showing ({ time = Masc_tui_machine_live.Frame number; _ } as p) ->
      let meta =
        match previous_live, previous_frame with
        | Masc_tui_machine_live.Showing old, Some frame
          when String.equal old.mark.incarnation p.mark.incarnation -> frame.msx_meta
        | ( ( Masc_tui_machine_live.Showing _ | Masc_tui_machine_live.Unread
            | Masc_tui_machine_live.Not_loaded | Masc_tui_machine_live.Failed _
            | Masc_tui_machine_live.Kept_back _ ),
            _ ) -> None
      in
      (view, Some { Masc_tui_types.msx_number = number; msx_width = p.width;
                    msx_height = p.height; msx_rgb = p.rgb; msx_meta = meta })
  | Masc_tui_machine_live.Showing { time = Masc_tui_machine_live.Untimed; _ } ->
      (Masc_tui_machine_live.Failed "an MSX answer carried no frame number", None)
  | Masc_tui_machine_live.Unread | Masc_tui_machine_live.Not_loaded
  | Masc_tui_machine_live.Failed _ | Masc_tui_machine_live.Kept_back _ -> (view, None)
;;

(* A live read the workspace guard stopped was never sent, so the screen
   says it was kept back and not that the machine could not be read (RFC §2). *)
let advance_machine_live state ~request view = function
  | Ok answer -> Masc_tui_machine_live.advance view (Ok answer)
  | Error (Request_failed detail) -> Masc_tui_machine_live.advance view (Error detail)
  | Error (Request_withdrawn refusal) ->
      Some (Masc_tui_machine_live.Kept_back
        (workspace_refusal_text ~ko:(state.ui_language = Lang_ko) ~request refusal))

(* A read of the MSX screen through the live route, asked with the counter
   of the picture drawn from the last one. An unchanged answer leaves the
   frame alone. Admission before the read and rejection after its attempt
   preserve different facts. *)
let with_msx_observation state ~mailbox ~request read apply =
  let check = Masc_tui_transport.Workspace_admission.capture_admission state ~mailbox in
  let kept_back refusal =
    state.msx_notice <-
      Some (workspace_refusal_text ~ko:(state.ui_language = Lang_ko) ~request refusal) in
  match check () with
  | Error refusal -> kept_back refusal
  | Ok () ->
      let result = read () in
      (match check () with
       | Error refusal ->
           state.msx_notice <- Some (Masc_tui_transport.Request_notice.workspace_response_refusal_text state ~request refusal)
       | Ok () -> apply result)

let observe_msx_carts state ~mailbox =
  with_msx_observation state ~mailbox ~request:Kept_request.Msx_carts_read
    (fun () -> Masc_tui_http.fetch_msx_carts ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port)
    (fun carts -> state.msx_carts <- carts)

let observe_msx_frame ?expected_workspace
    ?(current = fun () -> true) (state : Masc_tui_types.state) ~mailbox =
  if Option.is_some (checkpoint_for_workspace state) then () else
  let captured_view = !machine_view in
  (* The read that follows a change the server admitted for [expected_workspace]
     carries that workspace, and the server that answers it compares it with
     its own. A server swapped in at any point, including A -> B -> A, answers
     409 and its picture never reaches this view. *)
  with_msx_observation state ~mailbox ~request:Kept_request.Msx_screen_read (fun () ->
    (* The decoder has checked that MSX has no activity feed. Only its
       picture answer is needed by the MSX view. *)
    Result.map fst
      (Masc_tui_http.fetch_machine_live ?expected_workspace ~host:Masc_tui_transport.Workspace_admission.server_peer_host
         ~port:state.port Masc.Machine_lane.Msx
         ~since:(Masc_tui_machine_live.since state.msx_live)))
    (fun result ->
  if current () && captured_view == !machine_view
     && Option.is_none (checkpoint_for_workspace state) then begin
  (match Masc_tui_machine_live.advance state.msx_live result with
   | None -> ()
   | Some view ->
       let view, frame =
         msx_frame_of_live ~previous_live:state.msx_live
           ~previous_frame:state.msx_frame view
       in
       state.msx_live <- view;
       state.msx_frame <- frame;
       msx_surface_frame := frame)
  end)
;;

(* The response binds workspace and operation together; health samples around
   an unrelated live read cannot establish either completion or pixel identity. *)
let inspect_pending_msx_checkpoint (state : Masc_tui_types.state) pending =
  let authority = state.workspace_authority and view = !machine_view and port = state.port in
  let current () = authority=state.workspace_authority && view == !machine_view && port=state.port in
  let result = Masc_tui_http.inspect_msx_checkpoint
    ~expected_workspace:pending.checkpoint_workspace
    ~operation_id:pending.checkpoint_operation_id ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port
    ~restore:pending.checkpoint_restore ~slot:pending.checkpoint_slot in
  if current () then
    match result with
    | Error detail -> state.msx_notice <- Some ("Checkpoint inspection failed; retained screen: " ^ detail)
    | Ok Tui_decode.Checkpoint_pending -> state.msx_notice <- Some "Checkpoint is still pending; F5 inspects its receipt."
    | Ok (Checkpoint_unknown detail) -> state.msx_notice <- Some ("Checkpoint remains unknown: " ^ detail)
    | Ok (Checkpoint_refused detail) ->
        forget_checkpoint pending;
        state.msx_notice <- Some ("Checkpoint refused: " ^ detail)
    | Ok (Checkpoint_committed _) when not pending.checkpoint_restore ->
        forget_checkpoint pending;
        state.msx_notice <- Some "Saved quick checkpoint; operation receipt verified."
    | Ok (Checkpoint_committed None) ->
        state.msx_notice <- Some "Restore completed; awaiting its workspace-bound current screen."
    | Ok (Checkpoint_committed (Some json)) ->
        let decoded = Eio_guard.run_in_systhread ~label:"tui-checkpoint-live-decode"
          (fun () -> Masc_tui_machine_live.decode Masc.Machine_lane.Msx json) in
        if current () then (match decoded with
         | Error detail -> state.msx_notice <- Some ("Restore completed; retained screen because inspection failed: " ^ detail)
         | Ok (Unchanged _, _) -> state.msx_notice <- Some "Restore completed; inspection omitted the requested current pixels."
         | Ok ((No_machine | Picture _) as answer, _) ->
             (* Only valid receipt-bound pixels replace cached pixels. No old
                tick token can survive admission across this checkpoint. *)
             Option.iter (fun live ->
               let live,frame = msx_frame_of_live ~previous_live:state.msx_live
                 ~previous_frame:state.msx_frame live in
               state.msx_live <- live; state.msx_frame <- frame; msx_surface_frame := frame)
               (Masc_tui_machine_live.advance state.msx_live (Ok answer));
             forget_checkpoint pending;
             state.msx_notice <- Some "Restore completed; showing workspace state observed afterwards.")
;;

(* The MSX door opens on the load menu (RFC-0439 3.7): the human picks a game
   before watching one. Fetch the frame so the menu can offer "watch" when a
   game is already loaded, and the inventory so there is something to pick.
   Both are bounded loopback calls; the overlay then owns the terminal until a
   game is chosen or [esc].

   Collab's [g] action and the palette's "go MSX" both open this media picker.
   [&] opens Collab, whose watch actions go directly to observation. *)
let open_msx_screen (state : Masc_tui_types.state) ~mailbox =
  withdraw_resource_diagram_pending state;
  retire_machine_view ();
  state.machine_interaction <- Observe_machine;
  (* The spectator takes ownership from any image preview. A pending async
     preview must not keep its old surface alive underneath the game. *)
  state.image_request_generation <- state.image_request_generation + 1;
  state.browser_viewport <- None;
  if state.image_open then begin
    Masc_tui_msx.invalidate ();
    write_to_terminal Masc_tui_graphics.delete_all;
    state.image_open <- false;
    state.image_inspection <- None;
    state.image_pixel_source <- None;
    state.image_cell_view <- None
  end;
  observe_msx_frame state ~mailbox;
  observe_msx_carts state ~mailbox;
  Masc_tui_msx.open_menu ~write:write_to_terminal state;
  (* A first DOS read may carry a full screen. Let the menu accept keys while
     the read is in flight, and redraw its watch row when it arrives. *)
  launch_dos_live_read state ~mailbox

(* An inventory row names the shared machine itself. Opening it observes the
   current screen; Collab's [g] action opens the separate media selection menu. *)
let open_msx_spectator (state : Masc_tui_types.state) ~mailbox =
  withdraw_resource_diagram_pending state;
  retire_machine_view ();
  state.machine_interaction <- Observe_machine;
  state.image_request_generation <- state.image_request_generation + 1;
  state.browser_viewport <- None;
  if state.image_open then begin
    Masc_tui_msx.invalidate ();
    write_to_terminal Masc_tui_graphics.delete_all;
    state.image_open <- false;
    state.image_inspection <- None;
    state.image_pixel_source <- None;
    state.image_cell_view <- None
  end;
  state.machine_source <- Masc.Machine_lane.Msx;
  state.msx_open <- true;
  state.msx_menu_open <- false;
  state.msx_live <- Masc_tui_machine_live.Unread;
  state.msx_frame <- None;
  msx_surface_frame := None;
  state.msx_notice <- None;
  render_spectator state;
  launch_msx_live_read state ~mailbox

(* DOS has a spectator of its own. Enter it directly from the palette; the
   MSX media picker is only for choosing MSX media. No key from this view is
   forwarded to DOS, whose input and controller remain server-owned. *)
let open_dos_screen (state : Masc_tui_types.state) ~mailbox =
  withdraw_resource_diagram_pending state;
  retire_machine_view ();
  state.image_request_generation <- state.image_request_generation + 1;
  state.browser_viewport <- None;
  if state.image_open then begin
    Masc_tui_msx.invalidate ();
    write_to_terminal Masc_tui_graphics.delete_all;
    state.image_open <- false;
    state.image_inspection <- None;
    state.image_pixel_source <- None;
    state.image_cell_view <- None
  end;
  state.machine_source <- Masc.Machine_lane.Dos;
  state.msx_open <- true;
  state.msx_menu_open <- false;
  state.dos_live <- Masc_tui_machine_live.Unread;
  render_spectator state;
  launch_dos_live_read state ~mailbox

let handle_collab_action state ~mailbox view action =
  let owner = Masc_tui_collab.owner view in
  match action with
  | Masc_tui_collab.Stay -> ()
  | Close -> state.collab <- None; state.quit_armed <- None
  | Watch Masc.Machine_lane.Msx -> open_msx_spectator state ~mailbox
  | Watch Masc.Machine_lane.Dos -> open_dos_screen state ~mailbox
  | Game_menu -> open_msx_screen state ~mailbox
  | Refresh -> Masc_tui_collab_queue.Collab_play.refresh_collab state ~mailbox (Masc_tui_collab.owner view)
  | Resolve_unknown request_id ->
      (match Masc_tui_types.resolve_play_change state ~request_id with
       | Ok () ->
           Masc_tui_collab_queue.Collab_play.collab_notice state owner ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             "Operator confirmed the original request finished; refreshing current invite status.";
           Masc_tui_collab_queue.Collab_play.sync_collab_access state;
           Masc_tui_collab_queue.Collab_play.refresh_current_collab state ~mailbox
       | Error detail -> Masc_tui_collab_queue.Collab_play.collab_notice state owner ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure detail)
  | Open_link name ->
      (match Masc_tui_types.play_invite_find state name with
       | Some _ -> state.play_invite <- {state.play_invite with shown_name = Some name}; state.play_invite_scroll <- 0
       | None -> Masc_tui_collab_queue.Collab_play.collab_notice state owner ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
           "The one-time link is not retained in this session. Revoke this invite and issue a new one to obtain a link.")
  | Issue (mutation, name, hours) ->
      let sink = Play_collab {owner; mutation} in
      ignore (Masc_tui_collab_queue.Collab_play.launch_play_issue state ~mailbox ~sink ~name ~hours)
  | Revoke (mutation, name) ->
      let sink = Play_collab {owner; mutation} in
      ignore (Masc_tui_collab_queue.Collab_play.launch_play_revoke state ~mailbox ~sink ~name)

(* Where a reference lands, and what it opens when it gets there.

   The surfaces already print [masc://] references beside what they name and
   [Y] already copies the one under the cursor. Reading that same reference
   back is the other half: without it the screen knows where the answer is and
   the operator still walks over by hand.

   Tasks and Goals live under Work. A Task reference opens Work's Tasks detail. *)
let follow_target (kind : Link.kind) (id : string) =
  match kind with
  | Link.Task -> Some (Planning, Some id)
  | Link.Goal -> Some (Planning, Some id)
  | Link.Board_post -> Some (Board, Some id)
  | Link.Schedule -> Some (Schedules, Some id)
  | Link.Fusion_run -> Some (Fusion, Some id)
  | Link.Keeper -> Some (Keepers Keeper_list, Some id)
;;

let approval_row_reference = function
  | Masc_tui_approvals_model.Keeper_tool_row ask -> Some (Link.reference Keeper ask.kta_keeper)
  | Masc_tui_approvals_model.Gate_row pending -> Some (Link.reference Keeper pending.Tui_decode.gp_keeper)
  | Masc_tui_approvals_model.Operator_row item ->
      Option.bind item.ap_target_id (fun target_id ->
          match
            Masc.Operator_action_constants.target_type_of_string
              item.ap_target_type
          with
          | Some Masc.Operator_action_constants.Keeper ->
              Some (Link.reference Keeper target_id)
          | Some Goal -> Some (Link.reference Goal target_id)
          | Some Workspace | None -> None)

let selected_surface_reference state =
  let board () =
    match state.board_mode with
    | Board_read post_id -> Some (Link.reference Board_post post_id)
    | Board_list ->
        Option.map
          (fun post -> Link.reference Board_post post.bp_id)
          (List.nth_opt (board_posts state) state.board_cursor)
    | Board_compose -> None
  in
  let planning () =
    match state.planning_mode with
    | Planning_detail goal_id -> Some (Link.reference Goal goal_id)
    | Planning_list when Masc_tui_overview_tasks.is_focused state.task_focus ->
        (match state.task_detail_id with
         | Some task_id -> Some (Link.reference Task task_id)
         | None ->
             Option.map
               (fun (task : Tui_decode.task) -> Link.reference Task task.id)
               (Masc_tui_overview_tasks.work_selected_task state.tasks
                  ~selected:(Masc_tui_overview_tasks.selection state.task_focus)))
    | Planning_list ->
        Option.bind state.planning (fun snapshot ->
            planning_visible_goals ~filter:state.planning_filter
              ~sort:state.planning_sort snapshot.pl_goals
            |> Fun.flip List.nth_opt state.planning_cursor
            |> Option.map (fun goal -> Link.reference Goal goal.pg_id))
  in
  match state.view with
  | Board -> board ()
  | Planning -> planning ()
  | Schedules ->
      (match Masc_tui_work_actions.Board_schedule_actions.schedule_detail_on_screen state with
       | Some row -> Some (Link.reference Schedule row.sch_schedule_id)
       | None ->
           Option.bind state.schedules (fun snapshot ->
             Option.map (fun row -> Link.reference Schedule row.sch_schedule_id)
               (List.nth_opt snapshot.scs_rows state.schedule_cursor)))
  | Harness ->
      (match state.harness_detail with
       | Some (task_id, _) -> Some (Link.reference Task task_id)
       | None ->
           Option.bind state.harness (fun snapshot ->
               Option.map
                 (fun verdict ->
                    Link.reference Task verdict.Tui_decode.hv_task_id)
                 (List.nth_opt snapshot.Tui_decode.hs_verdicts
                    state.harness_cursor)))
  | Fusion ->
      (match state.fusion_mode, Masc_tui_fusion_model.fusion_snapshot state with
       | Fusion_historical_detail reference, _ -> Some (Link.reference Board_post reference.fhe_post_id)
       | Fusion_detail run_id, _ -> Some (Link.reference Fusion_run run_id)
       | Fusion_list, Some _ ->
           Option.map
             (function
               | Masc.Tui_decode_fusion.Fusion_retained_run run -> Link.reference Fusion_run run.fur_run_id
               | Masc.Tui_decode_fusion.Fusion_historical_evidence evidence ->
                   Link.reference Board_post evidence.fhe_post_id)
             (Masc_tui_fusion_model.selected_fusion_entry state)
       | Fusion_list, None -> None)
  (* Dashboard has no row cursor. Task references belong to Work. *)
  | Overview -> None
  | Keepers _ ->
      Option.map
        (fun (keeper : Tui_decode.keeper) -> Link.reference Keeper keeper.k_name)
        (selected_keeper state)
  | Lanes -> None
  | Clients -> None
  | Verification ->
      (* The task, not the request: a verification request is a question about
         a task, and the task is the thing another surface can open. *)
      Option.bind state.verification (fun snapshot ->
          Option.map
            (fun (request : Tui_decode.verification_request) ->
               Link.reference Task request.vr_task_id)
            (List.nth_opt snapshot.Tui_decode.vs_requests
               state.verification_cursor))
  | Approvals ->
      (* An ask names what it is asking about. A keeper's tool ask names the
         keeper; an operator ask carries a typed target, so the kind is read
         through [target_type_of_string] rather than matched as text. A
         Workspace target, or one this build does not know, points at no
         surface and gets no reference. *)
      Option.bind
        (List.nth_opt (Masc_tui_approvals_model.approval_items state) state.approval_cursor)
        approval_row_reference
  | Acting | Metrics
  | Memory | Repositories | Changes | Connectors | Runtime | Config | Resources | Tools
  | Code | System_logs -> None

let next_board_sort = function
  | Board_hot -> Board_trending
  | Board_trending -> Board_recent
  | Board_recent -> Board_updated
  | Board_updated -> Board_discussed
  | Board_discussed -> Board_hot

(* A filter or sort change can leave the cursor past the end of the new
   list; clamp it so the next j/k has somewhere to move from. *)
let clamp_planning_cursor state =
  let count =
    match state.planning with
    | None -> 0
    | Some planning ->
        List.length
          (planning_visible_goals ~filter:state.planning_filter
             ~sort:state.planning_sort planning.pl_goals)
  in
  if state.planning_cursor >= count then
    state.planning_cursor <- max 0 (count - 1)

(* Put a picture's bytes on the terminal, or say why not. Both doors a
   picture comes through -- a path the conversation named and an attachment
   staged for the next message -- end here, so what the terminal can show is
   answered once. [refuse] is the caller's wording: each door names its own
   key and its own label for the thing it could not show, and [title] is the
   line above the picture -- a path for a named file, the attachment's name
   for a staged one, which has no path.

   Asked before the write, not after: [place] is told not to answer, so a
   format the terminal cannot decode leaves a cleared screen and no word
   about why -- the picture that never arrives looks exactly like the picture
   that did. The sniff is the composer's, so both surfaces read bytes by one
   rule. *)
let inspection_window ~cell_pixels viewport =
  let rows,columns = Masc_tui_ansi.get_terminal_size () in
  Masc_tui_image_viewport.window ~cell_pixels
    ~columns:(max 1 (columns-2)) ~rows:(max 1 (rows-3)) viewport

let pixel_image_footer (state : state) footer =
  match state.image_pixel_source with
  | None -> footer
  | Some source ->
      let source = match image_pixel_source_for_redraw state source with
        | Some current -> current
        | None -> {source with ips_unconfirmed=true} in
      state.image_pixel_source <- Some {source with ips_footer=footer};
      if source.ips_unconfirmed then "! source unconfirmed · " ^ footer else footer

let draw_inspected_image ?(fresh=true) state inspected =
  match state.image_pixel_source with
  | Some source when Option.is_none (image_pixel_source_for_redraw state source) -> ()
  | Some _ | None ->
  withdraw_resource_diagram_pending state;
  match !active_graphics_protocol, !image_cell_pixels with
  | Masc_tui_graphics.Kitty_protocol, Some cell_pixels ->
    let rows,columns = Masc_tui_ansi.get_terminal_size () in
    let window = inspection_window ~cell_pixels inspected.ii_viewport in
    let frame = match inspected.ii_frame with
      | (Raster_image (shown,_) | Raster_unavailable (shown,_)) as frame when shown=window -> frame
      | Original_image | Raster_image _ | Raster_unavailable _ -> Original_image in
    let data,placement = match frame with
      | Raster_image (_,data) ->
        (match Masc.Keeper_image_dimensions.image_dimensions data with
         | Some (width,height) -> data,{window with x=0;y=0;width;height}
         | None -> inspected.ii_data,window)
      | Original_image | Raster_unavailable _ -> inspected.ii_data,window in
    let fresh = fresh || frame != inspected.ii_frame in
    let title = Keeper_chat.terminal_safe_text ~preserve_newlines:false inspected.ii_title in
    let rendering = Option.exists (fun pending -> match pending.sir_purpose with
      | Inspect_image {identity;_} -> identity == inspected.ii_identity
      | Open_image -> false) state.sent_image_read in
    let status = match frame with
      | Raster_unavailable (_,detail) -> " · render failed (r retry): " ^
          Keeper_chat.terminal_safe_text ~preserve_newlines:false detail
      | Original_image | Raster_image _ -> if rendering then " · rendering" else "" in
    let footer = Printf.sprintf "  +/− zoom · arrows/hjkl pan · 0 fit · %sEsc back · %.0f%%%s"
      (if state.view=Resources then "v source · " else "")
      (100.*.Masc_tui_image_viewport.zoom inspected.ii_viewport)
      status in
    let footer = pixel_image_footer state footer in
    Masc_tui_msx.invalidate ();
    let image = if fresh then Masc_tui_graphics.place_viewport ~data placement
      else Masc_tui_graphics.put_viewport placement in
    let retire = if fresh then Ansi.clear ^ Masc_tui_graphics.delete_all
      else Masc_tui_graphics.delete_placement
        ~image_id:(Masc_tui_graphics.image_id Image_inspection) ~placement_id:1 in
    write_to_terminal (retire
      ^ "\027[1;1H\027[2K" ^ Message_layout.fit_width title (max 1 (columns-1))
      ^ "\027[2;1H" ^ image
      ^ Printf.sprintf "\027[%d;1H\027[2K%s" rows
          (Message_layout.fit_width footer (max 1 (columns-1))));
    state.image_cell_view <- None;
    state.image_inspection <- Some {inspected with ii_frame=frame};
    state.image_open <- true
  | (Masc_tui_graphics.Kitty_protocol | ITerm2_protocol | Unsupported_protocol),
    (Some _ | None) -> ()

let draw_image state ?(inspect=false) ?scene ?origin ?(caption = []) ?(footer = "  any key: back") ~refuse ~title data =
  withdraw_resource_diagram_pending state;
  if state.msx_open then refuse "MSX currently owns the terminal; reopen the image after leaving MSX"
  else begin
  state.browser_viewport <- None;
  state.image_inspection <- None;
  state.image_pixel_source <- None;
  browser_image_region := None;
  browser_pointer_press := None;
  match Masc.Keeper_vision_tool.sniff_image_media_type data with
  | Error detail -> refuse detail
  | Ok media when not (String.equal media Masc_tui_graphics.payload_media_type)
    ->
      refuse
        (Printf.sprintf "the terminal draws %s and this is %s"
           Masc_tui_graphics.payload_media_type media)
  | Ok _ ->
      let rows, columns = Masc_tui_ansi.get_terminal_size () in
      (* Header rows -- the title, then one row per caption line (description,
         site, URL). The image starts below the header and the footer sits on
         the last row, so the picture never overlaps the text. With no caption
         this is the old title-only layout. *)
      let header_lines =
        List.map (Keeper_chat.terminal_safe_text ~preserve_newlines:false)
          (title :: caption)
      in
      let header_rows = List.length header_lines in
      let box =
        { Masc_tui_graphics.columns = max 1 (columns - 2)
        ; rows = max 1 (rows - header_rows - 2)
        }
      in
      (* Use the same aspect-preserving placement as the terminal. With no
         measured cell size the image still renders, but coordinates are unknown. *)
      let image_pixels = Masc.Keeper_image_dimensions.image_dimensions data in
      (match !image_cell_pixels, image_pixels with
       | Some (cw,ch), Some (iw,ih) when cw > 0 && ch > 0 && iw > 0 && ih > 0 ->
           let cw = float_of_int cw and ch = float_of_int ch in
           let iw = float_of_int iw and ih = float_of_int ih in
           let height_cells = match !active_graphics_protocol with
             | Masc_tui_graphics.ITerm2_protocol ->
                 min (float_of_int box.rows) (float_of_int box.columns *. cw *. ih /. iw /. ch)
             | Masc_tui_graphics.Kitty_protocol | Masc_tui_graphics.Unsupported_protocol ->
                 float_of_int (Masc_tui_graphics.fit_rows ~cell_pixels:!image_cell_pixels
                   ~image_pixels ~columns:box.columns ~rows:box.rows) in
           browser_image_region := Some {top=header_rows+1;left=1;height_cells;
             width_cells=height_cells *. ch *. iw /. ih /. cw}
       | _ -> ());
      state.image_pixel_source <-
        (match origin with
         | Some origin when origin.sir_view = Memory ->
             Some {ips_workspace=state.workspace_authority;ips_origin=origin;
               ips_unconfirmed=image_cell_source_unconfirmed state origin;ips_footer=footer}
         | Some _ | None -> None);
      let inspection = match inspect, !active_graphics_protocol, !image_cell_pixels, image_pixels with
       | true, Masc_tui_graphics.Kitty_protocol, Some _, Some (width,height) ->
           Masc_tui_image_viewport.create ~width ~height
       | (true | false), (Masc_tui_graphics.Kitty_protocol | ITerm2_protocol | Unsupported_protocol),
         (Some _ | None), (Some _ | None) -> None in
      (match inspection with
       | Some viewport -> draw_inspected_image state
           {ii_identity=ref ();ii_title=title;ii_data=data;ii_viewport=viewport;
            ii_scene=scene;ii_origin=origin;ii_frame=Original_image}
       | None ->
      let img_escape =
        match !active_graphics_protocol with
        | Masc_tui_graphics.ITerm2_protocol ->
            Masc_tui_graphics.iterm2_place ~data box
        | Masc_tui_graphics.Kitty_protocol | Masc_tui_graphics.Unsupported_protocol ->
            (* Kitty derives the width from the row count, so the image keeps
               its shape instead of being stretched into the box. *)
            let rows = Masc_tui_graphics.fit_rows ~cell_pixels:!image_cell_pixels
              ~image_pixels:(Masc.Keeper_image_dimensions.image_dimensions data)
              ~columns:box.columns ~rows:box.rows in
            Masc_tui_graphics.place ~data ~rows
      in
      let header =
        String.concat ""
          (List.mapi
             (fun i line ->
               Printf.sprintf "\x1b[%d;1H%s" (i + 1)
                 (Message_layout.fit_width line (max 1 (columns - 1))))
             header_lines)
      in
      Masc_tui_msx.invalidate ();
      let footer = pixel_image_footer state footer in
      write_to_terminal
        (Ansi.clear ^ Masc_tui_graphics.delete_all ^ header
        ^ Printf.sprintf "\x1b[%d;1H" (header_rows + 1)
        ^ img_escape
        ^ Printf.sprintf "\x1b[%d;1H%s" rows
            (Message_layout.fit_width footer (max 1 (columns - 1))));
      state.image_cell_view <- None;
      state.image_open <- true)
  end

let character_images_available () =
  Masc_tui_theme.colors_enabled
  && match Masc_tui_terminal_palette.stdout_color_level () with
     | Masc_tui_terminal_palette.True_color | Ansi256 -> true
     | Ansi16 | Unknown -> false

(* Use the actual size even when another asynchronous completion has already
   refreshed the shared cache. Its normalized width can exceed a tiny tty. *)
let cell_image_terminal_size () =
  match Masc_tui_ansi.probe_terminal_size () with
  | Some (rows, columns) when rows > 0 && columns > 0 -> Some (rows, columns)
  | Some _ | None -> None

let cell_image_fits (view : image_cell_frame) (rows, columns) =
  view.ic_columns <= columns - 2
  && List.length view.ic_lines + List.length view.ic_caption <= rows - 3

let cell_image_notice ~columns ~short ~long =
  let notice = if columns <= 4 then "!" else if columns <= 9 then "key"
    else if columns <= 20 then short else long in
  "\x1b[1;1H" ^ Message_layout.fit_width notice (columns - 1)

let draw_cell_image state ~terminal_size:(rows, columns) (view : image_cell_frame) =
  let view = match view.ic_copy_path with
    | None -> view
    | Some path ->
        let text = Keeper_chat.terminal_safe_text ~preserve_newlines:false path in
        let lines = Message_layout.wrap_words ~max_cells:(max 1 (columns - 2)) text in
        let width = List.fold_left
          (fun width line -> max width (Message_layout.display_width line)) 0 lines in
        {view with ic_lines=lines;ic_columns=width} in
  let contents =
    if cell_image_fits view (rows, columns) then
      let header_rows = 1 + List.length view.ic_caption in
      let header = List.mapi (fun index line ->
        Printf.sprintf "\x1b[%d;1H%s" (index + 1)
          (Message_layout.fit_width line (columns - 1))) (view.ic_title :: view.ic_caption)
        |> String.concat "" in
      let body = List.mapi (fun index line ->
        Printf.sprintf "\x1b[%d;1H%s" (index + 1 + header_rows) line) view.ic_lines
        |> String.concat "" in
      let footer = match view.ic_copy_path, view.ic_unconfirmed, view.ic_unsaved_remote with
        | Some _, true, (Some _ | None) -> "! source unconfirmed · y:copy path · other key: back"
        | Some _, false, Some _ -> "  s:save original · y:copy link · o:open link · key:back"
        | Some _, false, None -> "  y:copy · o:open link · x:other · key:back"
        | None, true, (Some _ | None) -> "! source unconfirmed · any key: back"
        | None, false, (Some _ | None) -> "  colour-cell preview · any key: back" in
      header ^ body
      ^ Printf.sprintf "\x1b[%d;1H%s" rows
          (Message_layout.fit_width footer (columns - 1))
    else if Option.is_some view.ic_copy_path then
      let hint = match view.ic_unsaved_remote, view.ic_save_cancelled with
        | Some _, true when rows = 2 -> cell_image_notice ~columns ~short:"cancelled"
            ~long:"Save cancelled; s retries"
        | Some _, (true | false) -> cell_image_notice ~columns ~short:"s:save"
            ~long:"Window too small · s:save original · y:copy link · key:close"
        | None, (true | false) -> cell_image_notice ~columns ~short:"y:copy"
            ~long:"Window too small · y:copy · o:open · x:other · key:close" in
      (match view.ic_caption with
       | _ :: status :: cancellation :: _ when rows > 2 ->
           hint ^ "\x1b[2;1H" ^ Message_layout.fit_width status (columns - 1)
           ^ "\x1b[3;1H" ^ Message_layout.fit_width cancellation (columns - 1)
       | _ :: status :: _ when rows > 1 ->
           hint ^ "\x1b[2;1H" ^ Message_layout.fit_width status (columns - 1)
       | _ :: _ | [] -> hint)
    else cell_image_notice ~columns ~short:"key:close"
      ~long:"Window too small · resize larger or press any key to close"
  in
  let retire_pixels = match !active_graphics_protocol, state.image_open, state.image_cell_view with
    | Masc_tui_graphics.Kitty_protocol, true, None -> Masc_tui_graphics.delete_all
    | (Kitty_protocol | ITerm2_protocol | Unsupported_protocol), (true | false), (Some _ | None) -> "" in
  Masc_tui_msx.invalidate ();
  if not (String.equal retire_pixels "") then write_to_terminal retire_pixels;
  write_terminal_text (Ansi.clear ^ contents);
  state.browser_viewport <- None;
  state.image_inspection <- None;
  state.image_pixel_source <- None;
  browser_image_region := None;
  browser_pointer_press := None;
  state.image_cell_view <- Some (Image_cells {view with ic_terminal_size=(rows, columns)});
  state.image_open <- true

let draw_withdrawn_cell_image state ~terminal_size:(_, columns as terminal_size) =
  let notice = cell_image_notice ~columns ~short:"key:close"
    ~long:"Image preview no longer available · press any key to close" in
  write_terminal_text (Ansi.clear ^ notice);
  state.image_cell_view <- Some (Image_cells_withdrawn (Some terminal_size))

let draw_prepared_image ?scene ?(caption=[]) ~origin state ~refuse ~title = function
  | Masc_tui_image_cache.Png png -> draw_image state ~inspect:true ?scene ~origin ~caption ~refuse ~title png
  | Rgba {columns=image_columns;pixel_rows;bytes} ->
    withdraw_resource_diagram_pending state;
    if state.msx_open then
      refuse "MSX currently owns the terminal; reopen the image after leaving MSX"
    else if not (character_images_available ()) then
      refuse "this terminal has no colour image presentation"
    else match cell_image_terminal_size () with
    | None -> refuse "terminal size is unavailable; reopen the image preview"
    | Some (rows, columns) when image_columns > columns - 2
        || pixel_rows / 2 + List.length caption > rows - 3 ->
        refuse "terminal size changed; reopen the image preview"
    | Some _ ->
      let lines = Masc_tui_image_mosaic.render_rgba
        ~project:Masc_tui_terminal_palette.best_color
        ~cols:image_columns ~rows:pixel_rows bytes in
      match lines with
      | [] -> refuse "image preview has no character frame"
      | _ :: _ ->
        let title = Keeper_chat.terminal_safe_text ~preserve_newlines:false title in
        let caption = List.map (Keeper_chat.terminal_safe_text ~preserve_newlines:false) caption in
        match cell_image_terminal_size () with
        | None -> refuse "terminal size is unavailable; reopen the image preview"
        | Some (rows, columns) ->
            draw_cell_image state ~terminal_size:(rows, columns)
              {ic_title=title;ic_caption=caption;ic_lines=lines;ic_columns=image_columns;
               ic_terminal_size=(rows, columns);ic_workspace=state.workspace_authority;
               ic_origin=origin;ic_unconfirmed=image_cell_source_unconfirmed state origin;
               ic_copy_path=None;ic_copy_page=None;ic_alternate_target=None;ic_last_open=None;
               ic_unsaved_remote=None;ic_save_cancelled=false}

let show_image_link_card state ~origin ~page_url ~copy ~unsaved ~last_open =
  let path, title, caption, alternate = match copy, unsaved with
    | None, Some source ->
        page_url, "Captured image", Printf.sprintf "Original held until closed (%d bytes); s saves a temporary copy."
          (String.length source.uri_bytes), page_url
    | None, None -> page_url, "Original image link", "Inline preview unavailable.", page_url
    | Some (path, openable), (Some _ | None) ->
        path, "Temporary image copy", "y keeps and copies the path; move it for long-term storage.",
        (if openable then path else page_url) in
  let view =
    {ic_title=title;ic_caption=[caption];
     ic_lines=[];ic_columns=0;ic_terminal_size=(0, 0);ic_workspace=state.workspace_authority;
     ic_origin=origin;ic_unconfirmed=image_cell_source_unconfirmed state origin;
     ic_copy_path=Some path;ic_copy_page=Some page_url;ic_alternate_target=Some alternate;ic_last_open=last_open;
     ic_unsaved_remote=unsaved;ic_save_cancelled=false} in
  match cell_image_terminal_size () with
  | None ->
      let retire_pixels = match !active_graphics_protocol, state.image_open, state.image_cell_view with
        | Masc_tui_graphics.Kitty_protocol, true, None -> Masc_tui_graphics.delete_all
        | (Kitty_protocol | ITerm2_protocol | Unsupported_protocol), (true | false), (Some _ | None) -> "" in
      if retire_pixels <> "" then write_to_terminal retire_pixels;
      Masc_tui_msx.invalidate ();
      state.browser_viewport <- None;
      state.image_inspection <- None;
      state.image_pixel_source <- None;
      browser_image_region := None;
      browser_pointer_press := None;
      state.image_cell_view <- Some (Image_cells view);
      state.image_open <- true;
      Masc_tui_terminal_out.write (Ansi.clear ^
        (if view.ic_unconfirmed then "! y:copy"
         else if Option.is_some view.ic_unsaved_remote then "s:save y:copy o:open"
         else "y:copy o:open x:other"));
      Masc_tui_terminal_out.flush ()
  | Some (rows, columns) ->
      draw_cell_image state ~terminal_size:(rows, columns) view

let update_image_link_card state ~path status =
  match state.image_cell_view with
  | Some (Image_cells view) when state.image_open && not state.msx_open
      && view.ic_copy_path = Some path ->
      let status = Keeper_chat.terminal_safe_text ~preserve_newlines:false status in
      let caption = match view.ic_caption with first :: _ -> first | [] -> "" in
      let cancellation = if view.ic_save_cancelled then ["Save cancelled; s retries"] else [] in
      let view = {view with ic_caption=caption :: status :: cancellation} in
      (match cell_image_terminal_size () with
       | Some terminal_size -> draw_cell_image state ~terminal_size view
       | None ->
           state.image_cell_view <- Some (Image_cells view);
           Masc_tui_terminal_out.write (Ansi.clear ^
             (if Option.is_some view.ic_unsaved_remote then "s:save y:copy o:open\r\n"
              else "y:copy o:open x:other\r\n") ^ status
             ^ (if view.ic_save_cancelled then "\r\nSave cancelled; s retries" else ""));
           Masc_tui_terminal_out.flush ())
  | Some (Image_cells _ | Image_cells_withdrawn _) | None -> ()

let mark_image_save_cancelled state =
  match state.image_cell_view with
  | Some (Image_cells ({ic_unsaved_remote=Some _;_} as view)) when state.image_open ->
      state.image_cell_view <- Some (Image_cells {view with ic_save_cancelled=true});
      view.ic_copy_path
  | Some (Image_cells _ | Image_cells_withdrawn _) | None -> None

let record_image_link_opener state ~path ~target opener =
  match state.image_cell_view with
  | Some (Image_cells view) when view.ic_copy_path = Some path ->
      state.image_cell_view <- Some (Image_cells {view with ic_last_open=Some (target,opener)})
  | Some (Image_cells _ | Image_cells_withdrawn _) | None -> ()

(* An opener may wait for the image viewer to close. Admit at most one child,
   start it while the input owner is current, and reap it without killing the
   viewer. Create the reaper before starting a process. *)
let remote_image_opener = Masc_tui_board_preview_work.create ()
let image_opener_generation = ref 0

let launch_image_opener ?after ~url ~allow_start ~on_result () =
  match Eio_context.get_switch_opt () with
  | None -> Error "external opening is unavailable"
  | Some _ when not (Masc_tui_board_preview_work.try_acquire remote_image_opener) ->
      Error "another image opener is still running"
  | Some sw ->
      incr image_opener_generation;
      let generation = !image_opener_generation in
      let completed, resolve = Eio.Promise.create () in
      let lock = Mutex.create () and ready = Condition.create () in
      let started = ref None in
      let await_start () =
        Mutex.lock lock;
        Fun.protect ~finally:(fun () -> Mutex.unlock lock) (fun () ->
          while Option.is_none !started do Condition.wait ready lock done;
          Option.get !started) in
      (match Thread.create (fun () ->
        let result = Fun.protect ~finally:(fun () ->
          Masc_tui_board_preview_work.release remote_image_opener) (fun () ->
          match await_start () with
          | Error detail -> Masc_tui_browser.Rejected detail
          | Ok (opener, pid) -> Masc_tui_browser.await_opener ~opener pid) in
        Eio.Promise.resolve resolve result) () with
       | exception exn ->
           Masc_tui_board_preview_work.release remote_image_opener;
           Error (Printexc.to_string exn)
       | _ ->
           let result = try
             if not (allow_start ()) then Error "opening cancelled before start"
             else Masc_tui_browser.spawn_url ?after url
             with exn -> Error (Printexc.to_string exn) in
           Mutex.lock lock;
           started := Some result;
           Condition.signal ready;
           Mutex.unlock lock;
           match result with
           | Error detail -> Error detail
           | Ok (opener, _) ->
               (match
                  Eio.Fiber.fork_daemon ~sw (fun () ->
                     let result = Eio.Promise.await completed in
                     if generation = !image_opener_generation then on_result result;
                     `Stop_daemon)
                with
                | () -> ()
                | exception (Eio.Cancel.Cancelled _ as exn) -> raise exn
                | exception _ -> ());
               Ok opener)

let download_remote_image ?(force_fetch = false) url =
  Masc_tui_image_cache.download ~force_fetch ~run:Masc_tui_image_cache.run_unbounded
    ~cache_dir:(Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir ()) url

(* Put a picture on the terminal, or say why not. The refusal is text for the
   pane: there is nothing to draw, and taking the screen away from the frame
   to say so would hide the only surface that can say it. *)
(* Mosaic preview width, in cells. Only the width is fixed; the height follows
   the image's aspect ratio (see [image_url_to_mosaic]), so the picture is never
   stretched. Bigger = sharper (og:images are high-res; cell count is the cap).
   The modal draws it only when it fits the width (render_modal_card guards), so
   a narrow terminal skips it rather than wrapping. Decode/draw stay a few ms. *)
let mosaic_cols = 120

(* Download a preview image and decode it into half-block mosaic lines, or say
   why not. Refusals remain visible until the operator requests a retry.
   Decoder failures do not establish that the cached input is bad.
   Blocking (curl + ffmpeg through
   Unix.system): the caller runs it off the render loop inside
   run_in_systhread. *)
let image_url_to_mosaic ?(force_fetch = false) ~cols url : Masc_tui_link_preview.mosaic_entry =
  match download_remote_image ~force_fetch url with
  | Error (Masc_tui_image_cache.Fetch_failed failure) ->
      Masc_tui_link_preview.(
        Refused (Fetch_failed { detail = Masc_tui_image_cache.fetch_failure_text failure }))
  | Error Masc_tui_image_cache.Empty_body -> Masc_tui_link_preview.(Refused Empty_body)
  | Error (Masc_tui_image_cache.Cache_unreadable { detail }) ->
      Masc_tui_link_preview.(Refused (Cache_unreadable { detail }))
  | Error (Masc_tui_image_cache.Cached_body_too_large _ as error) ->
      Masc_tui_link_preview.(Refused (Cache_unreadable {
        detail=Masc_tui_image_cache.download_error_text error }))
  | Ok body ->
    let cache_dir = Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir () in
    let decode local_path =
      (* Width is fixed at [cols]; height follows the image's own aspect ratio.
         scale=cols:-2 keeps the ratio and rounds to an even height for the
         half-block pairing, so the picture is never stretched. *)
      let cmd raw =
        Printf.sprintf
          "ffmpeg -y -loglevel error -i %s -vf scale=%d:-2 -frames:v 1 -f rawvideo -pix_fmt \
           rgb24 %s"
          (Filename.quote local_path) cols (Filename.quote raw)
      in
      let refuse failure =
        Masc_tui_link_preview.(
          Refused (Decode_failed { detail = Masc_tui_image_cache.decode_failure_text failure }))
      in
      (* The raw frame is read once, right after the decode, and nothing reuses
         its file. Each decode writes a file of its own, so another TUI
         decoding the same URL and width cannot remove it. *)
      Masc_tui_image_cache.with_decoder_output ~run:Masc_tui_image_cache.run_unbounded ~cache_dir
        ~prefix:"mosaic_" ~suffix:".raw" cmd (function
        | Error failure -> refuse failure
        | Ok data -> (
            let rows = String.length data / (cols * 3) in
            match Masc_tui_image_mosaic.render ~cols ~rows data with
            | [] -> refuse Masc_tui_image_cache.No_frame_written
            | lines -> Masc_tui_link_preview.Mosaic lines))
    in
    match Masc_tui_image_cache.with_download_snapshot ~cache_dir body decode with
    | Ok entry -> entry
    | Error detail -> Masc_tui_link_preview.(Refused (Cache_unreadable { detail }))

let () =
  compute_and_store_mosaic :=
    fun img ->
      (* Claim and decode in the same worker: canceling its waiting fiber must
         not release the URL while the converter still writes its files. *)
      Eio_guard.run_in_systhread ~label:"tui-image-mosaic" (fun () ->
        Masc_tui_link_preview.load_mosaic img ~compute:(fun () ->
          image_url_to_mosaic ~cols:mosaic_cols img))

let retry_image_mosaic img =
  match Eio_context.get_switch_opt () with
  | None -> ()
  | Some sw ->
    Eio.Fiber.fork_daemon ~sw (fun () ->
      Eio_guard.run_in_systhread ~label:"tui-image-mosaic-retry" (fun () ->
        Masc_tui_link_preview.retry_mosaic img ~retry:(fun () ->
          Masc_tui_image_cache.invalidate_download
            ~cache_dir:(Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir ()) img;
          image_url_to_mosaic ~force_fetch:true ~cols:mosaic_cols img));
      `Stop_daemon)

(* The colour-cell pixel-count ceiling equals one UHD image. Its 8-bit RGBA
   equivalent also bounds encoded input, cache reads and each helper output;
   it is not a bound on the decoder's total memory. *)
let remote_cell_image_max_bytes = 3840 * 2160 * 4

(* The existing link mosaic width also bounds the total work of a full-screen
   colour frame, even when a virtual terminal reports an enormous size. *)
let remote_cell_image_max_cells = mosaic_cols * mosaic_cols

(* The bounded path keeps the fetched source bytes so a late native capability
   can use the same one-shot URL response without another download. *)
let prepare_remote_image_bytes url =
  Result.map Masc_tui_image_cache.download_bytes
    (Masc_tui_image_cache.download ~max_bytes:remote_cell_image_max_bytes
      ~run:(Masc_tui_image_cache.run_bounded ~max_file_bytes:remote_cell_image_max_bytes
        ~deadline_seconds:Masc_tui_work_actions.Verification_actions.image_process_deadline_seconds)
      ~cache_dir:(Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir ()) url)
  |> Result.map_error Masc_tui_image_cache.download_error_text

let remote_fetch_worker = Masc_tui_board_preview_work.create ()
let remote_cell_worker = Masc_tui_board_preview_work.create ()
let remote_copy_worker = Masc_tui_board_preview_work.create ()
let remote_copy_cleanup_worker = Masc_tui_board_preview_work.create ()
let pending_image_copy : Masc_tui_image_cache.captured_copy option ref = ref None

let withdraw_remote_image_reservations () =
  ignore (Masc_tui_board_preview_work.withdraw_pending remote_fetch_worker);
  ignore (Masc_tui_board_preview_work.withdraw_pending remote_cell_worker);
  ignore (Masc_tui_board_preview_work.withdraw_pending remote_copy_worker)

let launch_remote_image_result ~mailbox ~request ~title ~caption ~page_url ~image_url work =
  Masc_tui_workspace_result.launch_session ~results:mailbox.Masc_tui_transport.Workspace_admission.workspace_results
    ~boundary_error:Fun.id
    ~deliver:(fun result -> Image_render_ready {request;title;caption;page_url;image_url;result})
    work

let launch_remote_image_worker ?(wait_for_active=false) state ~mailbox ~request ~title ~caption ~page_url ~image_url
    ~worker ~label ~busy ~on_exception work =
  launch_remote_image_result ~mailbox ~request ~title ~caption ~page_url ~image_url (fun () ->
    let current = Option.exists (fun pending -> pending == request) state.sent_image_read
      && request.sir_generation=state.image_request_generation && request.sir_view=state.view
      && not state.msx_open && image_request_keeper_is_current state request
      && image_reading_is_current state request in
    if not current then Ok busy
    else match (if wait_for_active then Masc_tui_board_preview_work.reserve_after_active worker
                else Masc_tui_board_preview_work.reserve worker) with
      | None -> Ok busy
      | Some admission ->
          (match Fun.protect
            ~finally:(fun () -> Masc_tui_board_preview_work.withdraw worker admission)
            (fun () -> Eio_guard.run_in_systhread ~label (fun () ->
              let run = if wait_for_active then Masc_tui_board_preview_work.run_reserved_after_active
                else Masc_tui_board_preview_work.run_reserved in
              match run worker admission work with
              | Some result -> result
              | None -> Ok busy)) with
           | result -> result
           | exception (Eio.Cancel.Cancelled _ as exn) -> raise exn
           | exception exn -> on_exception exn))

let launch_remote_image_fetch state ~mailbox ~request ~title ~caption ~page_url ~image_url ~bounded =
  launch_remote_image_worker state ~mailbox ~request ~title ~caption ~page_url ~image_url
    ~worker:remote_fetch_worker ~label:"tui-remote-image-bytes"
    ~busy:(Masc_tui_image_cache.Remote_busy None)
    ~on_exception:(fun exn -> Error (Printexc.to_string exn)) (fun () ->
      if bounded then
        match prepare_remote_image_bytes image_url with
        | Ok source -> Ok (Masc_tui_image_cache.Remote_bounded_source source)
        | Error reason -> Ok (Masc_tui_image_cache.Remote_bounded_failure reason)
      else
        let cache_dir=Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir () in
        let run command = Masc_tui_image_cache.run_bounded
          ~deadline_seconds:Masc_tui_work_actions.Verification_actions.image_process_deadline_seconds command in
        match Masc_tui_image_cache.download ~run ~cache_dir image_url with
        | Error error -> Error (Masc_tui_image_cache.download_error_text error)
        | Ok body ->
            let source=Masc_tui_image_cache.download_bytes body in
            (match Masc_tui_image_cache.prepare_downloaded_png ~run ~cache_dir ~url:image_url body with
             | Ok png -> Ok (Masc_tui_image_cache.Remote_native {source;png})
             | Error detail -> Ok (Masc_tui_image_cache.Remote_native_failed {source;detail})))

let launch_remote_image_native_source state ~mailbox ~request ~title ~caption ~page_url ~image_url source =
  let failed detail = Masc_tui_image_cache.Remote_native_failed {source;detail} in
  launch_remote_image_worker state ~mailbox ~request ~title ~caption ~page_url ~image_url
    ~worker:remote_fetch_worker ~label:"tui-remote-image-conversion"
    ~busy:(failed "another image is still preparing")
    ~on_exception:(fun exn -> Ok (failed (Printexc.to_string exn))) (fun () ->
      let run command = Masc_tui_image_cache.run_bounded
        ~deadline_seconds:Masc_tui_work_actions.Verification_actions.image_process_deadline_seconds command in
      match Masc_tui_image_cache.prepare_captured_png ~run ~cache_dir:(Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir ()) source with
      | Ok png -> Ok (Masc_tui_image_cache.Remote_native {source;png})
      | Error detail -> Ok (failed detail))

let launch_remote_image_cells state ~mailbox ~request ~title ~caption ~page_url ~image_url ~display source =
  match display with
  | Error detail ->
      launch_remote_image_result ~mailbox ~request ~title ~caption ~page_url ~image_url
        (fun () -> Ok (Masc_tui_image_cache.Remote_cells {source;cells=Error detail}))
  | Ok display ->
      launch_remote_image_worker state ~mailbox ~request ~title ~caption ~page_url ~image_url
        ~worker:remote_cell_worker ~label:"tui-remote-image-cells"
        ~busy:(Masc_tui_image_cache.Remote_busy (Some source))
        ~on_exception:(fun exn ->
          Ok (Masc_tui_image_cache.Remote_cells {source;cells=Error (Printexc.to_string exn)}))
        (fun () ->
          let cells = Masc_tui_image_cache.prepare_presentation
            ~max_bytes:remote_cell_image_max_bytes
            ~max_cells:remote_cell_image_max_cells
            ~run:(Masc_tui_image_cache.run_bounded ~max_file_bytes:remote_cell_image_max_bytes
              ~deadline_seconds:Masc_tui_work_actions.Verification_actions.image_process_deadline_seconds)
            ~cache_dir:(Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir ()) display source in
          Ok (Masc_tui_image_cache.Remote_cells {source;cells}))

let launch_remote_image_copy state ~mailbox ~request ~title ~caption ~page_url ~image_url ~reason ~requested_save source =
  let failed detail = Masc_tui_image_cache.Remote_copy_failed {source;reason;detail;requested_save} in
  launch_remote_image_worker ~wait_for_active:true state ~mailbox ~request ~title ~caption ~page_url ~image_url
    ~worker:remote_copy_worker ~label:"tui-remote-image-copy"
    ~busy:(failed "another image is still preparing")
    ~on_exception:(fun exn -> Ok (failed (Printexc.to_string exn))) (fun () ->
      if not requested_save && String.length source > remote_cell_image_max_bytes then
        Ok (failed "the captured image exceeds the copy limit")
      else match Masc_tui_image_cache.save_captured_copy ~directory:(Filename.get_temp_dir_name ()) source with
        | Ok copy -> Ok (Masc_tui_image_cache.Remote_copy_ready {copy;reason;requested_save})
        | Error detail -> Ok (failed detail))

let schedule_discarded_copy_cleanup () =
  match Eio_context.get_switch_opt (), Masc_tui_board_preview_work.reserve_after_active remote_copy_cleanup_worker with
  | Some sw, Some admission ->
      (match Eio.Fiber.fork_daemon ~sw (fun () ->
        Fun.protect ~finally:(fun () -> Masc_tui_board_preview_work.withdraw remote_copy_cleanup_worker admission)
          (fun () -> Eio_guard.run_in_systhread ~label:"tui-remote-image-cleanup" (fun () ->
            ignore (Masc_tui_board_preview_work.run_reserved_after_active remote_copy_cleanup_worker admission
              Masc_tui_image_cache.cleanup_discarded_copies)));
        `Stop_daemon) with
       | () -> ()
       | exception (Eio.Cancel.Cancelled _ as exn) ->
           Masc_tui_board_preview_work.withdraw remote_copy_cleanup_worker admission;
           raise exn
       | exception _ -> Masc_tui_board_preview_work.withdraw remote_copy_cleanup_worker admission)
  | None, Some admission -> Masc_tui_board_preview_work.withdraw remote_copy_cleanup_worker admission
  | (Some _ | None), None -> ()

let discard_pending_image_copy () =
  match !pending_image_copy with
  | None -> ()
  | Some copy ->
      pending_image_copy := None;
      Masc_tui_image_cache.discard_captured_copy copy;
      schedule_discarded_copy_cleanup ()

let keep_pending_image_copy path =
  match !pending_image_copy with
  | Some copy when String.equal copy.path path ->
      if Masc_tui_image_cache.retain_captured_copy copy then begin
        pending_image_copy := None;
        true
      end else false
  | Some _ | None -> true

(* A remote preview retains one input-cancellable owner across download and,
   when needed, colour-cell conversion.  Each blocking stage runs off the
   render loop; the completion chooses with the latest terminal capability. *)
let launch_image_render state ~mailbox ~notice:_ ~title ~caption ~page_url image_url =
  withdraw_remote_image_reservations ();
  state.image_request_generation <- state.image_request_generation + 1;
  let view = state.view in
  let request = {sir_generation=state.image_request_generation; sir_view=view;
    sir_keeper=(if view = Resources then None else state.msg_target_keeper_name);
    sir_name=title; sir_owner=Remote_url_image_read state.workspace_authority;
    sir_resource=None; sir_memory_activity=None; sir_skill_reference=None;
    sir_purpose=Open_image} in
  state.sent_image_read <- Some request;
  (* Classify already-buffered input and signals before starting a download.
     This first completion has no external side effects and goes through the
     same input barrier as the later download and conversion completions. *)
  launch_remote_image_result ~mailbox ~request ~title ~caption ~page_url ~image_url
    (fun () -> Ok Masc_tui_image_cache.Remote_unfetched)

let image_request_is_active state entry =
  let matches request =
    String.equal request.Keeper_chat.keeper_name entry.me_keeper_name
    && String.equal request.request_id entry.me_request_id
  in
  (match Chat_queue.find state.msg_queued ~request_id:entry.me_request_id with
   | Some item -> matches item.request
   | None -> false)
  || List.exists (fun (inflight : inflight) ->
       matches inflight.sent_request
       && match Masc_tui_keeper_chat_transcript.phase inflight.log.tl_transcript with
          | Waiting | Working -> true
          | Stream_ended | Stream_failed _ -> false)
       state.msg_inflight

(* Local active requests precede historical arrivals even across clock skew.
   A staged draft is superseded only by a new session row or a changed speech
   preview from a source this pane already held at staging. A newly loaded
   journal without such provenance conservatively leaves the draft first. *)
let conversation_image_sources state =
  let session = Masc_tui_chat_input.Message_draft_recall.image_session_rows state in
  let logs = Masc_tui_chat_input.Message_draft_recall.image_log_observations state in
  let candidates = Masc_tui_chat_input.Message_draft_recall.image_preview_candidates ~terminal_size:Masc_tui_render_prim.get_terminal_size state logs in
  let staged = state.msg_attachments <> [] in
  let observation = match state.msg_attachments_since with
    | Some observed when observed.io_reading == state.workspace_read_authority
        && observed.io_keeper = state.msg_target_keeper_name -> Some observed
    | Some _ | None -> None in
  let observed_session =
    if not staged then Some (List.filter (image_request_is_active state) session)
    else Option.bind observation (fun observed ->
      match observed.io_history with
      | None -> Some session
      | Some anchor -> msg_entries_after_anchor session anchor)
  in
  let observed_rows = Option.value observed_session ~default:[] in
  let source_has_new_input source =
    match state.msg_target_keeper_name with
    | None -> false
    | Some keeper_name ->
        let members = chat_execution_member_ids state ~keeper_name ~source in
        List.exists (fun row -> List.mem row.me_request_id members) observed_rows
  in
  let active_source source =
    List.exists (fun (entry : inflight) ->
      turn_log_execution_source entry.log = source
      && match Keeper_chat_transcript.phase entry.log.tl_transcript with
         | Waiting | Working -> true
         | Stream_ended | Stream_failed _ -> false) state.msg_inflight
  in
  let newly_observed anchor = match anchor with
    | Search_history {row_anchor; _} ->
        List.exists (same_msg_anchor row_anchor) observed_rows
    | Search_journal {source; origin; _} ->
        if not staged then active_source source
        else (match observation with
          | None -> false
          | Some observed ->
              match List.assoc_opt source observed.io_logs with
              | None -> source_has_new_input source
              | Some previous ->
                  match List.assoc_opt origin previous with
                  | None -> true
                  | Some old_preview ->
                      let preview = Option.value ~default:[]
                        (Option.bind (List.assoc_opt source logs) (List.assoc_opt origin)) in
                      Masc_tui_image_preview.newest old_preview
                      <> Masc_tui_image_preview.newest preview)
    | Search_child _ | Search_admission _ -> false
  in
  Masc_tui_image_preview.prioritize_sources ~newly_observed candidates

let board_preview_worker = Masc_tui_board_preview_work.create ()
let vector_inspection_worker = Masc_tui_board_preview_work.create ()

let () = at_exit (fun () ->
  Masc_tui_board_preview_work.stop remote_image_opener;
  Masc_tui_board_preview_work.stop remote_fetch_worker;
  Masc_tui_board_preview_work.stop remote_cell_worker;
  Masc_tui_board_preview_work.stop remote_copy_worker;
  Masc_tui_board_preview_work.stop remote_copy_cleanup_worker;
  Masc_tui_board_preview_work.stop board_preview_worker;
  Masc_tui_board_preview_work.stop vector_inspection_worker;
  Masc_tui_board_preview_work.stop resource_diagram_worker;
  Masc_tui_board_preview_work.stop board_image_prepare_worker;
  Masc_tui_image_cache.stop_subprocesses ();
  Masc_tui_board_preview_work.await_stopped remote_fetch_worker;
  Masc_tui_board_preview_work.await_stopped remote_cell_worker;
  Masc_tui_board_preview_work.await_stopped remote_copy_worker;
  Masc_tui_board_preview_work.await_stopped remote_copy_cleanup_worker;
  Masc_tui_image_cache.stop_captured_copies ();
  Masc_tui_board_preview_work.await_stopped board_preview_worker;
  Masc_tui_board_preview_work.await_stopped vector_inspection_worker;
  Masc_tui_board_preview_work.await_stopped resource_diagram_worker;
  Masc_tui_board_preview_work.await_stopped board_image_prepare_worker)

let image_notice (state : state) ~view ~keeper_name ~kind text =
  if view = Resources then report_action state "resources" text
  else if view = Board then state.board_attachment_status <- Some text
  else if view = Tools then
    report_action state (match kind with Masc_tui_collab_queue.Chat_notice.Notice_failure -> "error" | Masc_tui_collab_queue.Chat_notice.Notice_reply -> "system") text
  else Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name ~kind text

let board_image_source_reader state ~message subject =
  match subject with
  | Board_diagram _ -> false
  | Board_attachment_image {post_id;attachment={ba_kind;ba_source;ba_name}} ->
      if ba_kind <> Ak_image then false else
      match ba_source with
      | As_url _ -> false
      | As_artifact {sha256;bytes} ->
          close_board_reader state;
          let key = {Masc_tui_board_reader.post_id;sha256;bytes;name=ba_name} in
          state.board_reader <- Masc_tui_board_reader.offer_image ~key ~message state.board_reader;
          state.board_reader_owner <- Some (state.workspace_authority,state.workspace_read_authority,Ak_image);
          true

let cancel_board_image_read state =
  match state.sent_image_read with
  | Some pending ->
      (match pending.sir_purpose with
       | Inspect_image _ -> ()
       | Open_image ->
           (match pending.sir_owner with
            | Board_image_read (_,_,job) ->
                Masc_tui_workspace_job.cancel_observation state ~key:job;
                state.sent_image_read <- None
            | Local_file_image_read _ | Remote_url_image_read _
            | Draft_image_read _ | Peer_image_read _ -> ()))
  | None -> ()

let withdraw_pending_image_open state =
  if unsaved_remote_save_in_flight state then
    Option.iter (fun path -> update_image_link_card state ~path "s retries")
      (mark_image_save_cancelled state);
  match Masc_tui_types.withdraw_image_open state with
  | Some {sir_owner=Board_image_read (_,_,job);_} ->
      Masc_tui_workspace_job.cancel_observation state ~key:job
  | Some {sir_owner=Remote_url_image_read _;_} -> withdraw_remote_image_reservations ()
  | Some {sir_owner=(Local_file_image_read _
                    | Draft_image_read _ | Peer_image_read _);_}
  | None -> ()

(* Retire the owner as well as its unstarted physical reservations before an
   asynchronous navigation. Returning to the old view must not re-admit its
   delayed result. *)
let retire_remote_image_for_navigation state =
  match state.sent_image_read with
  | Some {sir_owner=Remote_url_image_read _;_} -> withdraw_pending_image_open state
  | Some {sir_owner=(Local_file_image_read _ | Draft_image_read _
                    | Peer_image_read _ | Board_image_read _);_}
  | None -> ()

(* Settle the exact interrupted preview without replacing a newer selection. *)
let settle_retired_sent_image state =
  match state.sent_image_read with
  | Some pending when not (image_reading_is_current state pending) ->
    if Option.is_none (retired_skill_image_notice state) then begin
      (match pending.sir_owner with
       | Remote_url_image_read _ -> withdraw_remote_image_reservations ()
       | Local_file_image_read _ | Draft_image_read _ | Peer_image_read _ | Board_image_read _ -> ());
      cancel_board_image_read state;
      state.sent_image_read <- None;
      if not state.msx_open && pending.sir_generation = state.image_request_generation
         && pending.sir_view = state.view
         && image_request_keeper_is_current state pending then
        image_notice state ~view:pending.sir_view ~keeper_name:pending.sir_keeper ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
          (Printf.sprintf "Image %s: source changed; reopen its preview"
             pending.sir_name)
    end
  | Some _ | None -> ()

let announce_retired_skill_image state =
  match retired_skill_image_notice state with
  | Some pending ->
      state.sent_image_read <- None;
      image_notice state ~view:Tools ~keeper_name:pending.sir_keeper ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
        "Skill image preview interrupted after the workspace reading changed; reopen it";
      true
  | None -> false

(* Draft payloads are local even while disconnected. Peer readings retain
   their original authority envelope; both paths capture the UI generation
   and workspace/draft owner before forking and share completion admission. *)
let board_image_source_matches subject source =
  match subject with
  | Board_diagram subject ->
      let body = match subject with
        | Board_post_diagram {body;_} | Board_comment_diagram {body;_} -> body in
      (match source with
       | Masc_tui_image_requests.Generated (Inline_mermaid diagram) ->
           List.exists (String.equal diagram) (Masc_tui_markdown.mermaid_sources body)
       | Generated (Inline_data _ | Inline_svg _ | Inline_graph _ | Server_path _ | Remote_uri _)
       | Local_file _ | Draft _ | Retained _ | Board_artifact _ -> false)
  | Board_attachment_image {post_id;attachment={ba_kind;ba_source;ba_name}} ->
      if ba_kind <> Ak_image then false else
      (match ba_source with
       | As_url _ -> false
       | As_artifact {sha256;bytes} ->
           match source with
           | Board_artifact key ->
               key.post_id = post_id && key.sha256 = sha256 && key.bytes = bytes && key.name = ba_name
           | Local_file _ | Draft _ | Retained _ | Generated _ -> false)

let open_preview_image ?skill_reference ?board_subject state ~mailbox ~notice ~name source =
  withdraw_remote_image_reservations ();
  cancel_board_image_read state;
  state.image_request_generation <- state.image_request_generation + 1;
  state.sent_image_read <- None;
  let dispatch = match board_subject, source with
    | Some subject, source ->
      if state.view = Board && server_authority_ready state
         && board_preview_subject_is_current state subject
         && board_image_source_matches subject source then
        Some (Masc_tui_transport.Workspace_admission.workspace_enqueue state, Board_image_read (state.workspace_read_authority, subject, ref ()))
      else None
    | None, Masc_tui_image_requests.Board_artifact _ -> None
    | None, Local_file _ ->
      Some (Masc_tui_transport.Workspace_admission.enqueue, Local_file_image_read state.workspace_authority)
    | None, Draft attachment ->
      Some (Masc_tui_transport.Workspace_admission.enqueue, Draft_image_read (state.workspace_authority, attachment))
    | None, (Retained _ | Generated _) ->
      if server_authority_ready state then
        Some (Masc_tui_transport.Workspace_admission.workspace_enqueue state, Peer_image_read state.workspace_read_authority)
      else None in
  match dispatch with
  | None ->
      if Option.is_some board_subject then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "Board image source or workspace is no longer available"
  | Some (enqueue_async, owner) ->
  let rows, columns = Masc_tui_ansi.get_terminal_size () in
  let display = match !active_graphics_protocol with
    | Masc_tui_graphics.Kitty_protocol | ITerm2_protocol -> Some Masc_tui_image_cache.Pixel_graphics
    | Unsupported_protocol ->
      if character_images_available () then Some (Masc_tui_image_cache.Character_cells
        {columns=max 0 (columns - 2);rows=max 0 (rows - 3)})
      else None in
  match display with
  | None ->
      let reason = "image preview requires pixel graphics or 256-colour text" in
      if not (Option.exists (board_image_source_reader state ~message:("Image preview unavailable: " ^ reason)) board_subject) then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure reason
  | Some display ->
    let board_worker = match owner with
      | Board_image_read _ -> Some board_preview_worker
      | Local_file_image_read _ | Remote_url_image_read _ | Draft_image_read _ | Peer_image_read _ -> None in
    let port = state.port in
    let keeper_name = match state.view, skill_reference with
      | Tools, Some _ -> Option.map (fun (keeper : keeper) -> keeper.k_name) (selected_keeper state)
      | (Resources | Board), (Some _ | None) -> None
      | Memory, (Some _ | None) -> state.memory_facts_keeper
      | Tools, None
      | (Overview | Acting | Metrics | Keepers _ | Lanes | Clients | Approvals
        | Planning | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes
        | Connectors | Runtime | Config | System_logs), (Some _ | None) -> state.msg_target_keeper_name in
    let generation = state.image_request_generation in
    let view = state.view in
    let request = {sir_generation=generation; sir_view=view;
      sir_keeper=keeper_name; sir_name=name; sir_owner=owner;
      sir_resource=(if view = Resources then state.resource_content else None);
      sir_memory_activity=(if view = Memory then Option.bind keeper_name (fun keeper ->
        Masc_tui_fetched.value
          (Masc_tui_fetched.view_for ~equal:String.equal state.memory_activity ~key:keeper)) else None);
      sir_skill_reference=skill_reference;
      sir_purpose=Open_image} in
    state.sent_image_read <- Some request;
    let admit_vector () =
      let exact_request = Option.exists (fun pending -> pending == request) state.sent_image_read in
      if not exact_request || state.msx_open || generation <> state.image_request_generation
         || view <> state.view || not (image_request_keeper_is_current state request)
         || not (image_reading_is_current state request) then
        Error "vector image request is no longer current"
      else match Masc_tui_board_preview_work.reserve vector_inspection_worker with
        | None -> Error "Previous vector image is still rendering; retry when it finishes"
        | Some admission -> Ok (vector_inspection_worker,admission) in
    (* When the terminal supplies no pixel geometry, use the half-em advance
       of Pele's 16px default font as a logical layout width. The existing
       image presenter still fits the resulting PNG to the actual cells. *)
    let cell_width = match !image_cell_pixels with
      | Some (width, _) -> width
      | None -> 8 in
    let diagram_width = max 1 (columns - 2) * cell_width in
    let cell_height = match !image_cell_pixels with Some (_,height) -> height | None -> 16 in
    let diagram_height = max 1 (rows-3) * cell_height in
    let diagram_font_size = max 1 (cell_width*2) in
    let palette = Masc_tui_terminal_palette.snapshot () in
    let hex color =
      Printf.sprintf "#%02x%02x%02x"
        (Masc_tui_terminal_palette.red color)
        (Masc_tui_terminal_palette.green color)
        (Masc_tui_terminal_palette.blue color) in
    let diagram_colors = Option.map (fun palette ->
      hex (Masc_tui_terminal_palette.foreground palette),
      hex (Masc_tui_terminal_palette.background palette))
      (Masc_tui_terminal_palette.snapshot_palette palette) in
    let run = match board_worker with
      | Some _ -> (fun command -> Masc_tui_image_cache.run_bounded
          ~deadline_seconds:Masc_tui_work_actions.Verification_actions.image_process_deadline_seconds command)
      | None -> Masc_tui_image_cache.run_unbounded in
    let load () =
      Masc_tui_image_requests.load ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port
        ~cache_dir:Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir ~diagram_width ~diagram_height ~diagram_font_size
        ~diagram_colors ~board_worker ~admit_vector
        ~run ~vector_run:(Masc_tui_image_cache.run_bounded ~deadline_seconds:Masc_tui_work_actions.Verification_actions.image_process_deadline_seconds)
        ~display source in
    let completion result = Sent_image_ready { request; result=Image_prepared result } in
    (match owner, source with
     | Board_image_read (_,_,job), Masc_tui_image_requests.Board_artifact _ ->
         (* The actual binary GET, not a separate health probe, carries the
            captured workspace roots and must return its admission receipt. *)
         Masc_tui_transport.Workspace_admission.launch_json_read ~key:job state ~mailbox
           ~boundary_error:(fun cause -> Request_failed cause)
           ~withdrawn:(fun refusal -> Request_withdrawn refusal)
           ~deliver:(fun result -> Sent_image_ready { request; result = match result with
             | Ok prepared -> Image_prepared (Ok prepared)
             | Error (Request_failed cause) -> Image_prepared (Error cause)
             | Error (Request_withdrawn refusal) -> Image_kept_back refusal })
           (fun () -> Result.map_error (fun cause -> Request_failed cause) (load ()))
     | Board_image_read (_,_,job), Generated _ ->
         Masc_tui_transport.Workspace_admission.launch_result ~key:job ~observation:true state ~mailbox
           ~boundary_error:Fun.id ~deliver:completion load
     | (Local_file_image_read _ | Remote_url_image_read _ | Draft_image_read _ | Peer_image_read _),
       (Local_file _ | Draft _ | Retained _ | Board_artifact _ | Generated _)
     | Board_image_read _, (Local_file _ | Draft _ | Retained _) ->
         match Eio_context.get_switch_opt () with
         | Some sw -> Eio.Fiber.fork_daemon ~sw (fun () ->
             enqueue_async mailbox (completion (load ())); `Stop_daemon)
         | None ->
             state.sent_image_read <- None;
             notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "image preview requires an active background session")

(* Input changes the desired viewport; completion retires the old job and
   the next loop renders only the latest window. A non-Board vector worker
   owns its physical slot until it returns, including after image close.
   All windows use the original full-scene PNG coordinate system. *)
let prepare_inspected_frame state ~mailbox ~worker_geometry_current =
  match state.image_open, state.image_inspection, state.sent_image_read,
      !active_graphics_protocol, !image_cell_pixels, Eio_context.get_switch_opt () with
  | true, Some inspected, None, Masc_tui_graphics.Kitty_protocol,
      Some ((cw,ch) as cell_pixels), Some sw when not state.msx_open ->
    (match inspected.ii_scene, inspected.ii_origin,
        Masc.Keeper_image_dimensions.image_dimensions inspected.ii_data with
     | Some scene, Some origin, Some (width,height)
         when origin.sir_view=state.view
           && image_request_keeper_is_current state origin
           && image_reading_is_current state origin ->
       let geometry = Masc_tui_ansi.get_terminal_size () in
       let window = inspection_window ~cell_pixels inspected.ii_viewport in
       let current_frame = match inspected.ii_frame with
         | Raster_image (shown,_) | Raster_unavailable (shown,_) -> shown=window
         | Original_image -> false in
       let slot_busy = match origin.sir_owner with
         | Board_image_read _ -> false
         | Local_file_image_read _ | Remote_url_image_read _
         | Draft_image_read _ | Peer_image_read _ ->
             Masc_tui_board_preview_work.is_busy vector_inspection_worker in
       if not current_frame && not slot_busy
          && (window.width < window.columns*cw || window.height < window.rows*ch) then begin
         let generation = state.image_request_generation in
         let pending = {origin with sir_generation=generation;
           sir_purpose=Inspect_image {identity=inspected.ii_identity;window}} in
         state.sent_image_read <- Some pending;
         let crop = {Masc_tui_pele.left=float_of_int window.x /. float_of_int width;
           top=float_of_int window.y /. float_of_int height;
           right=float_of_int (window.x+window.width) /. float_of_int width;
           bottom=float_of_int (window.y+window.height) /. float_of_int height} in
         let raster = {Masc_tui_pele.width=window.columns*cw;
           height=window.rows*ch;crop=Some crop} in
         let deliver = match pending.sir_owner with
           | Local_file_image_read _ | Remote_url_image_read _
           | Draft_image_read _ -> Masc_tui_transport.Workspace_admission.enqueue
           | Peer_image_read _ | Board_image_read _ -> Masc_tui_transport.Workspace_admission.workspace_enqueue state in
         draw_inspected_image ~fresh:false state inspected;
         Eio.Fiber.fork_daemon ~sw (fun () ->
           Eio.Fiber.yield ();
           (* Check and admit on this Eio fiber without yielding between them.
              Once admitted, a later close withdraws the result, not the work. *)
           let current = Option.exists (fun request -> request == pending) state.sent_image_read
             && state.image_open && not state.msx_open && pending.sir_view=state.view
             && image_request_keeper_is_current state pending
             && image_reading_is_current state pending
             && (match state.image_inspection, !image_cell_pixels with
                 | Some current, Some pixels -> current.ii_identity == inspected.ii_identity
                     && window = inspection_window ~cell_pixels:pixels current.ii_viewport
                 | (Some _ | None), (Some _ | None) -> false)
             && worker_geometry_current geometry in
           let render () =
             let open Result.Syntax in
             let runner = Masc_tui_pele.command_runner
                 ~run:(Masc_tui_image_cache.run_bounded ~deadline_seconds:Masc_tui_work_actions.Verification_actions.image_process_deadline_seconds) in
             let* png = Masc_tui_pele.render ~cache_dir:(Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir ()) ~raster ~runner scene in
             let* () = match pending.sir_owner with
               | Board_image_read _ when not (Masc_tui_image_cache.has_png_structure png) ->
                   Error "image has an invalid or truncated PNG structure"
               | Board_image_read _ | Local_file_image_read _ | Remote_url_image_read _
               | Draft_image_read _ | Peer_image_read _ -> Ok () in
             let* prepared = Masc_tui_image_cache.prepare_presentation ~run:Masc_tui_image_cache.run_unbounded
               ~cache_dir:(Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir ()) Masc_tui_image_cache.Pixel_graphics png in
             Ok (prepared,Some scene) in
           let result = if not current then None else match pending.sir_owner with
             | Board_image_read _ -> Some (Image_prepared
                 (Eio_guard.run_in_systhread ~label:"tui-vector-window" (fun () ->
                   Masc_tui_board_preview_work.run board_preview_worker render)))
             | Local_file_image_read _ | Remote_url_image_read _
             | Draft_image_read _ | Peer_image_read _ ->
                 (match Masc_tui_board_preview_work.reserve vector_inspection_worker with
                  | None -> None
                  | Some admission ->
                      Some (Fun.protect
                        ~finally:(fun () -> Masc_tui_board_preview_work.withdraw vector_inspection_worker admission)
                        (fun () -> Eio_guard.run_in_systhread ~label:"tui-vector-window" (fun () ->
                          match Masc_tui_board_preview_work.run_reserved vector_inspection_worker admission render with
                          | None -> Image_worker_busy
                          | Some result -> Image_prepared result)))) in
           (match result with
            | Some result -> deliver mailbox (Sent_image_ready {request=pending;result})
            | None -> ignore (Masc_tui_types.take_image_read state pending));
           `Stop_daemon)
       end
     | (Some _ | None), (Some _ | None), (Some _ | None) -> ())
  | (true | false), (Some _ | None), (Some _ | None),
    (Masc_tui_graphics.Kitty_protocol | ITerm2_protocol | Unsupported_protocol),
    (Some _ | None), (Some _ | None) -> ()

(* Only parsed HTTP(S) references use the explicit browser/download path.
   All other selected paths keep their local file meaning. *)
let open_image state ~mailbox ~notice path =
  let uri = Uri.of_string path in
  match Uri.scheme uri, Uri.host uri with
  | Some ("http" | "https"), Some _ ->
      launch_image_render state ~mailbox ~notice ~title:path ~caption:[]
        ~page_url:path path
  | (Some _ | None), (Some _ | None) ->
    open_preview_image state ~mailbox ~notice ~name:path
      (Masc_tui_image_requests.Local_file path)

let current_resource_images (state : state) =
  match state.resource_content, state.resource_pending_key, state.resource_content_error with
  | Some (uri, contents), None, None ->
    let mime_type = Option.bind (visible_resources state) (fun resources ->
      Option.bind (Masc_tui_resource_catalog.entry_for_key resources uri)
        (fun resource -> (Masc_tui_resource_catalog.metadata resource).mime_type)) in
    Masc_tui_resource_images.images ~mime_type contents
  | (Some _ | None), (Some _ | None), (Some _ | None) -> []

let step_resource_image (state : state) ~delta =
  let count = List.length (current_resource_images state) in
  state.resource_image_cursor <- max 0 (min (count - 1) (state.resource_image_cursor + delta))

let resource_surface_visible state =
  if state.image_open || state.msx_open then false
  else
    let terminal_rows,_ = get_terminal_size () in
    match Masc_tui_render.frame_choice state ~terminal_rows
      ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ()))
      ~now:(Unix.gettimeofday ()) with
    | `Surface -> true
    | `Too_small _ | `Play_card _ | `Account_login _ | `Account_server _ | `Palette | `Collab _
    | `Lane_addons _ | `Detail_reading _ | `About | `Context | `Keeper_deletions
    | `Help | `Agenda | `Answering | `Queue _ | `Link | `Client_detail _ -> false

let resource_diagram_frame state ~geometry_stable =
  match state.view, state.resource_focus, server_authority_ready state,
      Masc_tui_portrait_view.current_display () with
  | Resources, Right_pane, true, Masc_tui_portrait_view.Pixels {cell_width;cell_height}
      when resource_surface_visible state
        && Masc_tui_resource_document.diagrams_allowed state && geometry_stable () ->
      (match Masc_tui_resource_document.current state with
       | Some reading when not reading.requested && Option.is_none reading.error
           && reading.presentation = Masc_tui_resource_catalog.Document ->
           Option.map (fun contents ->
             let _,cols = get_terminal_size () in
             let columns = max 1 (framed_inner_width (resource_content_cols state ~cols)-4) in
             let palette = Masc_tui_terminal_palette.snapshot () in
             let hex color = Printf.sprintf "#%02x%02x%02x"
               (Masc_tui_terminal_palette.red color) (Masc_tui_terminal_palette.green color)
               (Masc_tui_terminal_palette.blue color) in
             let palette_colors = Option.map (fun palette ->
               hex (Masc_tui_terminal_palette.foreground palette),
               hex (Masc_tui_terminal_palette.background palette))
               (Masc_tui_terminal_palette.snapshot_palette palette) in
             Masc_tui_resource_diagrams.{
               frame_mime_type=(Masc_tui_resource_catalog.metadata reading.entry).mime_type;
               frame_contents=contents; frame_width=columns*cell_width;
               frame_cell_pixels=(cell_width,cell_height); frame_colors=palette_colors
             }) reading.contents
       | Some _ | None -> None)
  | (Overview | Keepers _ | Planning | Board | Acting | Metrics | Lanes | Clients | Schedules | Harness | Fusion
    | Verification | Approvals | Memory | Repositories | Changes | Connectors | Runtime
    | Config | Resources | Tools | Code | System_logs),
    (Left_pane | Right_pane), (true | false),
    (Masc_tui_portrait_view.Pixels _ | Mosaic | No_picture) -> None

let prepare_resource_diagrams state ~mailbox ~geometry_stable ~worker_geometry_current =
  let module Diagrams = Masc_tui_resource_diagrams in
  let module Work = Masc_tui_board_preview_work in
  let current_frame () = resource_diagram_frame state ~geometry_stable in
  match current_frame (), Eio_context.get_switch_opt () with
  | Some frame, Some sw ->
      let diagrams = match state.resource_diagrams with
        | Some diagrams when Diagrams.matches_frame frame diagrams -> diagrams
        | Some _ | None ->
            withdraw_resource_diagram_pending state;
            let diagrams = Diagrams.create ~mime_type:frame.frame_mime_type ~contents:frame.frame_contents
              ~width:frame.frame_width ~cell_pixels:frame.frame_cell_pixels ~colors:frame.frame_colors in
            state.resource_diagrams <- Some diagrams;
            diagrams in
      if not (Work.is_busy resource_diagram_worker) then
        (match Diagrams.claim_next diagrams with
         | None -> ()
         | Some (source,claim,claimed) ->
             state.resource_diagrams <- Some claimed;
             let request = Diagrams.request diagrams in
             let terminal_size = Masc_tui_ansi.get_terminal_size () in
             let deliver = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
             let abandon () = state.resource_diagrams <- Option.map
               (Diagrams.abandon request ~source claim) state.resource_diagrams in
             Eio.Fiber.fork_daemon ~sw (fun () ->
               Eio.Fiber.yield ();
               (match Diagrams.admission request ~frame:(current_frame ()) state.resource_diagrams with
                | Diagrams.Ignore -> ()
                | Diagrams.Retire -> abandon ()
                | Diagrams.Admit ->
                    if not (geometry_stable ()) then abandon ()
                    else (match Work.reserve resource_diagram_worker with
                     | None -> abandon ()
                     | Some admission ->
                         let delivered = ref false in
                         Fun.protect
                           ~finally:(fun () ->
                             Work.withdraw resource_diagram_worker admission;
                             if not !delivered then abandon ())
                           (fun () ->
                             let result = Eio_guard.run_in_systhread ~label:"tui-artifact-diagram" (fun () ->
                               Work.run_reserved resource_diagram_worker admission (fun () ->
                                 if not (worker_geometry_current terminal_size) then None
                                 else begin
                                   let cell_width,_ = frame.frame_cell_pixels in
                                   let scene = Masc_tui_pele.scene ~format:Mermaid
                                     ~max_width:(Diagrams.width request)
                                     ~font_size:(max 1 (cell_width*2))
                                     ~now_ms:(Int64.of_float (Unix.gettimeofday () *. 1000.))
                                     ~colors:(Diagrams.colors request) source in
                                   let runner = Masc_tui_pele.command_runner
                                     ~run:(Masc_tui_image_cache.run_bounded ~deadline_seconds:Masc_tui_work_actions.Verification_actions.image_process_deadline_seconds) in
                                   Some (Masc_tui_pele.render ~cache_dir:(Masc_tui_work_actions.Verification_actions.ensure_img_cache_dir ()) ~runner scene)
                                 end)) in
                             match result with
                             | Some (Some result) ->
                                 deliver mailbox (Resource_msg (Resource_diagram_ready (request,source,claim,result)));
                                 delivered := true
                             | Some None | None -> ())));
               `Stop_daemon))
  | (Some _ | None), (Some _ | None) -> withdraw_resource_diagram_pending state

let open_resource_image (state : state) ~mailbox =
  let notice = image_notice state ~view:Resources ~keeper_name:state.msg_target_keeper_name in
  let images = current_resource_images state in
  match List.nth_opt images state.resource_image_cursor with
  | Some (_, Masc_tui_image_preview.Output_image {name;source}) ->
    open_preview_image state ~mailbox ~notice ~name (Masc_tui_image_requests.Generated source)
  | Some (_, Unavailable_image {name;reason}) ->
    notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure (name ^ ": " ^ reason)
  | Some (_, (Named_path _ | Staged _ | Stored_attachment _ | No_image))
  | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "No image in the current resource reading"

let open_selected_image state ~mailbox preview =
  let notice = if state.view = Memory then
      image_notice state ~view:Memory ~keeper_name:state.memory_facts_keeper
    else Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:state.msg_target_keeper_name in
  match preview with
  | Masc_tui_image_preview.Named_path path -> open_image state ~mailbox ~notice path
  | Masc_tui_image_preview.Staged attachment ->
      open_preview_image state ~mailbox ~notice
        ~name:attachment.Masc_tui_keeper_chat_projection.name
        (Masc_tui_image_requests.Draft attachment)
  | Masc_tui_image_preview.Stored_attachment { name; reference; format } ->
      open_preview_image state ~mailbox ~notice ~name
        (Masc_tui_image_requests.Retained {reference;format})
  | Masc_tui_image_preview.Output_image { name; source } ->
      open_preview_image state ~mailbox ~notice ~name (Masc_tui_image_requests.Generated source)
  | Masc_tui_image_preview.Unavailable_image { name; reason } ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
        (Printf.sprintf "Ctrl-O %s: %s" name reason)
  | Masc_tui_image_preview.No_image ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "Ctrl-O: no image or closed Mermaid diagram in this conversation or the composer"

let open_named_image state ~mailbox =
  let sources, order = conversation_image_sources state in
  let conversation = List.concat_map snd sources |> Masc_tui_image_preview.newest in
  open_selected_image state ~mailbox
    (Masc_tui_image_preview.choose_preview ~conversation ~staged:state.msg_attachments ~order)

let capture_image_catalog state =
  (* Freeze every source before the first fetch. Numbering is local to the
     currently loaded conversation and never reads labels back as identities. *)
  let sources, order = conversation_image_sources state in
  let conversation = List.concat_map snd sources in
  let candidates = Masc_tui_image_preview.newest_first ~conversation
      ~staged:state.msg_attachments ~order in
  {ic_reading=state.workspace_read_authority;ic_keeper=state.msg_target_keeper_name;
   ic_previews=candidates}

let list_conversation_images state =
  let catalog = capture_image_catalog state in
  state.image_catalog <- Some catalog;
  let label = function
    | Masc_tui_image_preview.Named_path path -> path
    | Staged attachment -> attachment.Masc_tui_keeper_chat_projection.name
    | Stored_attachment {name;_} | Output_image {name;_} -> name
    | Unavailable_image {name;reason} -> name ^ " · unavailable: " ^ reason
    | No_image -> "No image" in
  let rows = List.mapi (fun index preview ->
    Printf.sprintf "%d. %s" (index+1) (label preview)) catalog.ic_previews in
  Masc_tui_message_input.clear state.msg_input;
  let text = match rows with
    | [] -> "/images: no image or closed diagram in the loaded conversation or composer"
    | _ -> "Images / diagrams · /images N opens · /images refreshes this list\n"
        ^ String.concat "\n" rows in
  Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:state.msg_target_keeper_name ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply text

let open_indexed_image state ~mailbox ~index =
  let catalog = match state.image_catalog with
    | Some catalog -> catalog
    | None ->
      let catalog = capture_image_catalog state in
      state.image_catalog <- Some catalog;
      catalog in
  let notice = Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:state.msg_target_keeper_name in
  if catalog.ic_reading != state.workspace_read_authority
     || catalog.ic_keeper <> state.msg_target_keeper_name then
    notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
      (ui_text state
         ~ko:"/images: 대화가 바뀌었습니다 · /images를 다시 실행해 현재 목록을 읽으세요"
         ~en:"/images: conversation changed; run /images to read its current list")
  else match List.nth_opt catalog.ic_previews (index - 1) with
  | Some preview ->
      Masc_tui_message_input.clear state.msg_input;
      open_selected_image state ~mailbox preview
  | None ->
      let count = List.length catalog.ic_previews in
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
        (if state.ui_language = Lang_ko then
           Printf.sprintf "/images: 불러온 대화와 입력창에 이미지·다이어그램 미리보기가 %d개 있습니다" count
         else
           Printf.sprintf "/images: %s in the loaded conversation and composer"
             (Masc_tui_message_layout.count_noun count "image/diagram preview"))

(* The MIDI soundfont read at boot from [tui].midi_soundfont (the same load
   that applies the theme and the saved sort). The numbered attachment keys
   and /listen answer from this snapshot instead of re-reading runtime.toml
   per request. *)
let boot_midi_soundfont : string option ref = ref None

(* /listen: play the newest playable attachment in this conversation — the
   same newest-wins rule Ctrl-O uses for images, extended to audio and MIDI.
   Bytes come from the block itself, our own media store, or a local file;
   playback is the attachment action's job, so a MIDI reports what it is and
   the one-player-at-a-time rule holds here too. *)
let conversation_media state =
  match state.msg_target_keeper_name with
  | None -> []
  | Some keeper_name ->
      let _, cols = get_terminal_size () in
      let projection = keeper_message_projection state ~keeper_name ~chat_cols:cols in
      let logs = selected_source_logs_for_keeper state keeper_name
        |> List.map (fun log -> turn_log_execution_source log,
          Keeper_chat_transcript.drawn log.tl_transcript) in
      let projected = projection.tagged_entries |> List.concat_map (fun (tag, _) ->
        match search_anchor_of_tag tag with
        | Some (Search_history _) ->
            (match message_of_tag tag with Some row -> row.me_media | None -> [])
        | Some (Search_journal {source; origin; _}) ->
            (match List.assoc_opt source logs with
             | None -> []
             | Some items -> items |> List.filter_map (fun (item : Keeper_chat_transcript.drawn_item) ->
                 match item.origin=origin, item.superseded, item.drawn with
                 | true, None, Drawn_media media -> Some (Masc_tui_chat_media.of_generated media)
                 | (false | true), (None | Some _), (Drawn_media _ | Drawn_thinking _
                   | Drawn_skill _ | Drawn_tools _ | Drawn_text _ | Drawn_reply _
                   | Drawn_status _ | Drawn_error _) -> None))
        | Some (Search_child _ | Search_admission _) | None -> []) in
      let queued = Masc_tui_chat_input.Message_draft_recall.image_session_rows state |> List.concat_map (fun row ->
        match Chat_queue.find state.msg_queued ~request_id:row.me_request_id, row.me_role with
        | Some _, Message_user _ ->
            if List.exists (fun (tag, _) -> match message_of_tag tag with
              | Some shown -> msg_anchor shown=msg_anchor row | None -> false) projection.tagged_entries
            then [] else row.me_media
        | None, _ | Some _, (Message_keeper | Message_autonomous | Message_thinking
          | Message_tool | Message_skill _ | Message_status | Message_local
          | Message_error | Message_memory) -> []) in
      projected @ queued

let prepare_listen_media ~host ~port (media : Masc_tui_chat_media.playable) =
  let open Result.Syntax in
  let* bytes = match media.source with
    | `Server_path path ->
        Masc_tui_http.get_workspace_bytes
          ~max_body_bytes:Tool_blob_store.max_served_bytes ~host ~port ~path
    | `Data payload ->
        Eio_guard.run_in_systhread ~label:"tui-listen-decode" (fun () ->
          Masc_tui_image_payload.decode_wire payload)
    | `Local_path path ->
        Eio_guard.run_in_systhread ~label:"tui-listen-file" (fun () ->
          try
            let descriptor = Unix.openfile path [Unix.O_RDONLY; Unix.O_NONBLOCK] 0 in
            let channel = Unix.in_channel_of_descr descriptor in
            Fun.protect ~finally:(fun () -> close_in_noerr channel) (fun () ->
              let stats = Unix.fstat (Unix.descr_of_in_channel channel) in
              if stats.Unix.st_kind <> Unix.S_REG then Error "audio source is not a regular file"
              else if stats.Unix.st_size > Tool_blob_store.max_served_bytes then
                Error "file is larger than the attachment limit"
              else Ok (really_input_string channel stats.Unix.st_size))
          with
          | Sys_error detail -> Error detail
          | End_of_file -> Error "audio source changed while reading"
          | Unix.Unix_error (code, _, _) -> Error (Unix.error_message code)) in
  Eio_guard.run_in_systhread ~label:"tui-listen-prepare" (fun () ->
    let sha256 = Agent_core_sha256.(to_hex (digest_string bytes)) in
    let attachment : board_attachment =
      { ba_kind=(match media.kind with `Audio -> Ak_audio | `Midi -> Ak_midi);
        ba_source=As_artifact {sha256; bytes=String.length bytes}; ba_name=Some media.name } in
    Masc_tui_attachment_action.prepare ~fetch:(fun ~sha256:_ -> Ok bytes) attachment
    |> Result.map_error Masc_tui_attachment_action.describe_outcome)

let listen_newest_media ?(destination=Listen_player) state ~mailbox =
  let notice = Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:state.msg_target_keeper_name in
  let media = match destination with
    | Listen_player -> Masc_tui_chat_media.newest_playable (conversation_media state)
    | Listen_music_editor -> Masc_tui_chat_media.newest_midi (conversation_media state) in
  let command = match destination with
    | Listen_player -> "/listen" | Listen_music_editor -> "/music midi" in
  match state.msg_target_keeper_name, media with
  | None, _ | Some _, None ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply (command ^ ": no readable "
        ^ (match destination with Listen_player -> "audio or MIDI" | Listen_music_editor -> "MIDI")
        ^ " attachment in this conversation")
  | Some keeper, Some media ->
      if not (server_authority_ready state) then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
          (let ko = state.ui_language = Lang_ko in
           kept_back ~ko ~request:(Kept_request.Command command) (workspace_identity_unconfirmed ~ko) Nothing_kept)
      else begin
        let request = begin_chat_listen ~destination state ~keeper media in
        let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply (command ^ ": preparing " ^ media.name);
        Masc_tui_transport.Workspace_admission.launch_json_read state ~mailbox
          ~boundary_error:(fun cause -> Request_failed cause)
          ~withdrawn:(fun refusal -> Request_withdrawn refusal)
          ~deliver:(fun result -> Listen_prepared (request, result))
          (fun () -> Result.map_error (fun cause -> Request_failed cause)
            (prepare_listen_media ~host ~port request.lr_media))
      end

let withdraw_pending_music_editor state =
  withdraw_chat_music_editor state |> Option.iter (fun request ->
    let message =
      "/music midi: opening cancelled while terminal input was pending; run /music midi again when ready" in
    Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:(Some request.lr_keeper) ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
      message;
    report_action state "system" message)

(* Take the picture away and give the frame back. The terminal holds images in
   its own layer, so clearing the screen is not enough to remove one. *)
let close_image state =
  let cell_was_open = Option.is_some state.image_cell_view in
  withdraw_remote_image_reservations ();
  discard_pending_image_copy ();
  state.sent_image_read <- None;
  browser_pointer_press := None;
  browser_image_region := None;
  state.browser_viewport <- None;
  state.image_inspection <- None;
  state.image_cell_view <- None;
  state.image_pixel_source <- None;
  match state.image_open with
  | false -> ()
  | true ->
      state.image_open <- false;
      Masc_tui_msx.invalidate ();
      if not cell_was_open then write_to_terminal Masc_tui_graphics.delete_all

let draw_browser_viewport state (shot : Browser_lane_view.screenshot) bytes =
  let failed = ref false in
  let refuse detail =
    failed := true;
    close_image state;
    state.browser_lane <- Option.map
      (fun (view : Browser_lane_view.t) -> { view with load = Failed detail }) state.browser_lane
  in
  let pointer_hint = match !image_cell_pixels with
    | Some (width, height) when width > 0 && height > 0 ->
        "click: link"
    | _ -> "click unavailable: terminal cell geometry unknown" in
  let wheel_hint = match !image_cell_pixels with
    | Some (width,height) when width > 0 && height > 0 -> "wheel:pane"
    | _ -> "wheel:center" in
  draw_image state ~refuse ~title:("Browser viewport · " ^ shot.title)
    ~caption:[Printf.sprintf "%s · tab %d · %.1f ms"
        (match shot.source, state.browser_lane with
         | Live, Some view ->
             (match Browser_lane_view.screenshot_client view shot with
              | Some client -> Browser_lane_view.browser_identity client
              | None -> "Selected browser")
         | Live, None -> "Selected browser") shot.tab_id shot.elapsed_ms; shot.url]
    ~footer:("  Esc: back  r:refresh  " ^ wheel_hint ^ "  j/k:center  " ^ pointer_hint) bytes;
  if not !failed then state.browser_viewport <- Some (shot, bytes)

(* [/find] and its arg-less repeat, which differ only in where the walk starts.

   Search returns the projected body-row pin together with its scroll. The
   frame and search use the same feedback seam, so arrivals between the command
   and the next frame cannot move the matched row out of view.

   Every outcome says something. A search that silently did nothing and a key
   that did nothing look the same, which is the failure this surface keeps
   having; and running out of older matches is a different fact from having
   none at all, because only one of the two is fixed by starting over. *)
let apply_chat_search_result state ~target ~restart ~needle result =
  let notice=Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target in
  let ko = state.ui_language = Lang_ko in
      let partial=if result.unavailable_entries=0 then "" else
        if ko then
          Printf.sprintf " · 항목 %d건 검색 불가 · 결과가 일부 누락될 수 있습니다" result.unavailable_entries
        else
          Printf.sprintf " · search unavailable for %d %s; results may be incomplete"
            result.unavailable_entries (if result.unavailable_entries = 1 then "entry" else "entries") in
      match result.match_result with
      | Some (position, anchor) ->
          state.msg_find_at <- Some anchor;
          apply_clamped_scroll state (Message_scroll position);
          notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
            ((if ko then
                Printf.sprintf "/find %s \xc2\xb7 %d줄 위로 이동 (/find 반복)" needle position.scroll
              else
                Printf.sprintf "/find %s \xc2\xb7 %s back (/find repeats)"
                  needle (Masc_tui_message_layout.count_noun position.scroll "row"))
             ^ partial)
      | None when result.unavailable_entries>0 ->
          notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ("/find" ^ partial)
      | None ->
          if restart then
            notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
              (if ko then Printf.sprintf "/find %s \xc2\xb7 이 대화에 일치하는 내용이 없습니다" needle
               else Printf.sprintf "/find %s \xc2\xb7 nothing in this conversation" needle)
          else
            (* The walk is over, not empty. Said apart from the case above
               because starting again is what fixes this one and not that
               one. *)
            notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
              (if ko then
                 Printf.sprintf "/find %s \xc2\xb7 이전 일치 항목 없음 · /find %s 로 처음부터 다시 검색"
                   needle needle
               else
                 Printf.sprintf
                   "/find %s \xc2\xb7 no older match; /find %s starts again"
                   needle needle)


let seek_in_chat state ~mailbox ~target ~restart =
  let notice=Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target in
  match target with
  | None ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
        (ui_text state ~ko:"/find: 목록에서 키퍼를 먼저 선택하세요"
           ~en:"/find needs a Keeper selected on the roster")
  | Some keeper_name ->
      let needle=String.trim state.msg_find in
      let older_than=if restart then None else state.msg_find_at in
      retire_keeper_message_search state;
      let generation=Atomic.get state.msg_search_generation in
      (* The plan only reads state. Candidates are rendered after this
         handler returns, so the notice is drawn before that work starts. It
         goes to the action footer, not into [msg_history]: a row appended
         there after the plan froze its projection would make an empty
         search look like a changed conversation, and a later search could
         match the row itself. *)
      let plan=plan_keeper_message_search state ~keeper_name ~needle ~older_than in
      report_action state "system"
        (Terminal_text.single_line ("/find " ^ needle ^ " · searching conversation"));
      launch_keeper_message_search state plan ~deliver:(fun result ->
        Masc_tui_transport.Workspace_admission.enqueue mailbox (Chat_msg (Chat_search_finished (generation,restart,plan,result))))

(* The Activity pane's cycle, narrow to wide to hidden, shared by Ctrl-L
   and [/activity]. Measured
   against the terminal's own width, not the width the surfaces lay out
   against: with the pane showing, that width is already short by the pane,
   and a threshold read from it could refuse to hide the very pane that
   narrowed it. *)
let toggle_acting_pane (state : state) =
  let _rows, cols = Masc_tui_ansi.get_terminal_size () in
  if Masc_tui_render.acting_pane_suppressed state then
    (* The same rule as the width check below, for a surface the pane never
       draws beside: a press here would move narrow to wide unseen, and the
       reader would meet the change on the next surface. *)
    Error "Activity pane is not drawn over this surface; preference unchanged"
  else if Masc_tui_roster_pane.hides_activity state.pane_zoom then begin
    let stored = stored_acting_pane_layout state in
    if Masc_tui_acting_pane.drawn_cols ~layout:Masc_tui_acting_pane.Narrow ~cols = 0 then
      Error
        (Printf.sprintf "Activity pane needs %d columns; preference unchanged"
           Masc_tui_acting_pane.threshold_cols)
    else
      let restored =
        match stored with
        | Masc_tui_acting_pane.Hidden -> Masc_tui_acting_pane.Narrow
        | (Masc_tui_acting_pane.Narrow | Masc_tui_acting_pane.Wide) as layout -> layout
      in
      state.pane_zoom <- Masc_tui_roster_pane.Normal;
      state.acting_pane_preference <- Chosen_acting_pane restored;
      state.acting_pane_scroll <- 0;
      state.acting_pane_cursor <- None;
      Ok restored
  end else
  match
    Masc_tui_acting_pane.next_layout ~layout:(stored_acting_pane_layout state) ~cols
  with
  | None ->
      Error
        (Printf.sprintf "Activity pane needs %d columns; preference unchanged"
           Masc_tui_acting_pane.threshold_cols)
  | Some layout ->
      state.pane_zoom <- Masc_tui_roster_pane.Normal;
      state.acting_pane_preference <- Chosen_acting_pane layout;
      state.acting_pane_scroll <- 0;
      state.acting_pane_cursor <- None;
      Ok layout

(* Show one of the pane's tabs. Where the pane cannot show, the tab is not
   set either: a preference with no visible effect would surprise the
   reader after a later resize, the same rule the toggle follows. *)
let show_acting_pane_tab (state : state) tab =
  let _rows, cols = Masc_tui_ansi.get_terminal_size () in
  if Masc_tui_render.acting_pane_suppressed state then
    Error "Activity pane is not drawn over this surface; preference unchanged"
  else if Masc_tui_acting_pane.drawn_cols ~layout:Masc_tui_acting_pane.Narrow ~cols = 0 then
    Error
      (Printf.sprintf "Activity pane needs %d columns; preference unchanged"
         Masc_tui_acting_pane.threshold_cols)
  else begin
    let layout =
      match state.acting_pane_preference with
      | Chosen_acting_pane
          ((Masc_tui_acting_pane.Narrow | Masc_tui_acting_pane.Wide) as layout) ->
          layout
      | Chosen_acting_pane Masc_tui_acting_pane.Hidden | Default_acting_pane ->
          Masc_tui_acting_pane.Narrow
    in
    state.pane_zoom <- Masc_tui_roster_pane.Normal;
    state.acting_pane_preference <- Chosen_acting_pane layout;
    state.acting_pane_tab <- tab;
    state.acting_pane_scroll <- 0;
    Ok ()
  end

(* Where a mouse report landed, relative to the Activity pane the last frame
   drew. The pane's columns are the render's own answer for that frame
   ([acting_pane_reserved_cols], zero when it drew none); its rows are the
   body rows under the surface strip. Everything else belongs to the surface,
   as it did before the pane existed. *)
type acting_pane_hit =
  | Pane_miss
  | Pane_row of int  (** 0-based line within the pane *)

let acting_pane_hit (state : state) ~row ~column =
  let frame = state.acting_pane_presented in
  let pane_cols = frame.frame_columns in
  if pane_cols <= 0 then Pane_miss
  else
    let _terminal_rows, terminal_cols = Masc_tui_ansi.get_terminal_size () in
    let body_rows = List.length frame.frame_targets in
    let first_col = terminal_cols - pane_cols + 1 in
    (* Row 1 is the surface strip; the body starts on row 2. *)
    let first_row = 2 in
    if column >= first_col && column <= terminal_cols
       && row >= first_row && row < first_row + body_rows
    then Pane_row (row - first_row)
    else Pane_miss

let scroll_acting_pane (state : state) ~delta =
  state.acting_pane_scroll
  <- max 0
       (min
          state.acting_pane_presented.frame_scroll_max
          (state.acting_pane_scroll + delta))

(* A press on the pane is the roster's cursor by another hand: a fleet row
   lands the selection on that keeper, and a press on the keeper already
   selected opens its chat, the way [/keeper <name>] does. The fold line
   scrolls into the full list. Everything else on the pane is read, not
   pressed. *)
let handle_acting_pane_click (state : state) ~base_path ~mailbox ~line =
  match Masc_tui_acting_pane.target_at state.acting_pane_presented ~line with
  | Masc_tui_acting_pane.Target_none -> ()
  | Masc_tui_acting_pane.Target_next_tab ->
      state.acting_pane_tab <- Masc_tui_acting_pane.next_tab state.acting_pane_tab;
      state.acting_pane_scroll <- 0
  | Masc_tui_acting_pane.Target_more -> scroll_acting_pane state ~delta:1
  | Masc_tui_acting_pane.Target_file _ when acting_pane_source_current state -> (
      (* The row indexes the snapshot the pane drew. The Changes surface
         opens on that same snapshot with the row's diff up, then asks for
         a fresh one the way [/changes] does; the loaded handler keeps the
         open row when the fresh answer holds the same change there. *)
      let selected_keeper =
        Option.map (fun (keeper : keeper) -> keeper.k_name) (selected_keeper state)
      in
      match
        presented_acting_pane_file state.acting_pane_presented
          ~scope:(state.workspace_authority, state.workspace_read_authority) ~selected_keeper ~line
      with
      | Some (snapshot, index) ->
              goto_surface state ~mailbox Changes;
              state.changes <- Some snapshot;
              state.changes_error <- None;
              state.changes_cursor <- index;
              state.changes_scroll <- 0;
              state.changes_diff_row <- Some index;
              refresh_recorded_diff_bounds state ~reset:true;
              state.changes_diff_scroll <- 0;
              state.changes_tree_diff <- None;
              state.changes_tree_diff_error <- None;
              state.changes_tree_diff_path <- None
      | None -> ())
  | Masc_tui_acting_pane.Target_call_order ->
      state.acting_pane_call_order
      <- Masc_tui_acting_pane.next_call_order state.acting_pane_call_order
  | Masc_tui_acting_pane.Target_call (keeper_name, key) when acting_pane_source_current state ->
      (* A press on a call opens it: its detail rows draw under it until a
         press on the call or its detail closes it again. What stays open is
         only what the feed still holds -- a key for a call that has left
         the projection is dropped here rather than kept for a call that
         may never come back. *)
      let chunks = Masc_tui_acting.projection_chunks (recent_chunk_projection state) in
      let held (name, opened) =
        List.exists
          (fun (chunk : Masc_tui_acting.chunk) ->
            String.equal chunk.Masc_tui_acting.ck_keeper name
            && List.exists
                 (fun tool ->
                   Masc_tui_acting.call_key_equal (Masc_tui_acting.call_key tool) opened)
                 (Masc_tui_acting.chunk_tools chunk))
          chunks
      in
      let same (name, opened) =
        String.equal name keeper_name && Masc_tui_acting.call_key_equal opened key
      in
      let others =
        List.filter
          (fun entry -> (not (same entry)) && held entry)
          state.acting_pane_expanded
      in
      state.acting_pane_expanded
      <- (if held (keeper_name, key) && not (List.exists same state.acting_pane_expanded)
          then (keeper_name, key) :: others
          else others)
  | Masc_tui_acting_pane.Target_calls keeper_name when acting_pane_source_current state -> (
      (* An earlier turn's row is the keeper's calls surface by another hand,
         the way [t] opens it from the roster: the cursor lands on that
         keeper so the surface names the right one, and the snapshot is asked
         for afresh. *)
      match select_activity_keeper state keeper_name with
      | Activity_keeper_missing -> ()
      | Activity_keeper_selected | Activity_keeper_already_selected ->
          state.keeper_calls <- None;
          state.keeper_calls_error <- None;
          state.keeper_calls_scroll <- 0;
          transition_keeper_view state (Keepers Keeper_calls);
          owe_keeper_calls_read state ~mailbox ~keeper_name)
  | Masc_tui_acting_pane.Target_keeper keeper_name when acting_pane_source_current state -> (
      match select_activity_keeper state keeper_name with
      | Activity_keeper_missing | Activity_keeper_selected -> ()
      | Activity_keeper_already_selected ->
          Masc_tui_chat_input.Message_draft_recall.open_message_for_keeper ~return_to:state.msg_return state keeper_name
            ~drain_queue:(fun () -> Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox);
          state.view <- Keepers Keeper_message;
          launch_keeper_history_load state ~mailbox ~keeper_name)
  | Masc_tui_acting_pane.Target_file _ | Masc_tui_acting_pane.Target_call _
  | Masc_tui_acting_pane.Target_calls _ | Masc_tui_acting_pane.Target_keeper _ -> ()

(* Keyboard focus on the Activity pane (#37672): Ctrl-W puts a cursor on the
   first row a press acts on, [j]/[k] walk those rows and past the frame's
   last one scroll the pane a row, Enter does what a press on the row does
   -- opens or closes a call, turns the order, switches the tab -- and Esc
   or Ctrl-W hands the keys back to the surface. On Board and Resources the
   pane is the last stop of the Ctrl-W cycle after their two panes. The
   cursor is a row of the last frame, the way a press is: what it opens is
   what was on screen. *)
let acting_pane_drawn (state : state) =
  state.acting_pane_presented.frame_columns > 0
  && not (Masc_tui_render.acting_pane_suppressed state)

let acting_pane_frame_targets state =
  let targets = state.acting_pane_presented.frame_targets in
  let targets =
    if acting_pane_source_current state then targets
    else List.map (function
      | Masc_tui_acting_pane.Target_none -> Masc_tui_acting_pane.Target_none
      | Target_next_tab -> Target_next_tab
      | Target_more -> Target_more
      | Target_call_order -> Target_call_order
      | Target_keeper _ | Target_file _ | Target_calls _ | Target_call _ -> Target_none) targets
  in
  Array.of_list targets

(* [true] when the cursor went up; [false] when the frame drew no row a
   press acts on, so there is nothing to focus. *)
let focus_acting_pane (state : state) =
  match
    Masc_tui_acting_pane.next_target_row
      ~targets:(acting_pane_frame_targets state) ~row:(-1) ~step:1
  with
  | Some row ->
      state.acting_pane_cursor <- Some row;
      true
  | None -> false

let leave_acting_pane (state : state) =
  state.acting_pane_cursor <- None;
  (* The cycle closes where it opened: the left pane. *)
  (match state.view with
   | Board ->
       let _, cols = get_terminal_size () in
       state.board_focus <-
         Masc_tui_types.board_focus_on_leaving_acting_pane state ~cols
   | Resources -> state.resource_focus <- Left_pane
   | Overview | Acting | Metrics | Memory | Lanes | Clients | Approvals | Planning | Schedules
   | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors | Runtime | Config
   | Tools | System_logs | Keepers _ -> ())

let move_acting_pane_cursor (state : state) ~row ~step =
  match
    Masc_tui_acting_pane.next_target_row
      ~targets:(acting_pane_frame_targets state) ~row ~step
  with
  | Some next -> state.acting_pane_cursor <- Some next
  | None ->
      (* No further row in this frame: bring the next one in. The cursor
         keeps its row; the pane moves under it. *)
      scroll_acting_pane state ~delta:step

let acting_pane_focus_keys =
  [ "j"; "down"; "k"; "up"; "enter"; "\r"; "\n"; "esc"; "\023" ]

let handle_acting_pane_focus_key (state : state) ~base_path ~mailbox ~row key =
  match key with
  | "j" | "down" -> move_acting_pane_cursor state ~row ~step:1
  | "k" | "up" -> move_acting_pane_cursor state ~row ~step:(-1)
  | "esc" | "\023" -> leave_acting_pane state
  | _ -> handle_acting_pane_click state ~base_path ~mailbox ~line:row

(* Ctrl-W where no pane cycle owns it: the surface and the Activity pane
   take turns. *)
let focus_acting_pane_or_say_why (state : state) =
  if not (focus_acting_pane state) then
    report_action state "system" "Activity pane has no row to open"

(* The main session owns terminal restoration. Commands freeze their source
   before calling this handoff; the child never reads mutable conversation data. *)
let score_terminal_handoff :
  (sources:string list -> index:int -> (unit, string) result) option ref = ref None

let music_terminal_handoff : (unit -> (unit, string) result) option ref = ref None

let music_midi_terminal_handoff : (path:string -> (unit, string) result) option ref = ref None

let open_music_midi ~path =
  match !music_midi_terminal_handoff with
  | None -> Error "MIDI editor requires an active terminal session"
  | Some launch -> launch ~path

let open_music () =
  match !music_terminal_handoff with
  | None -> Error "Music workbench requires an active terminal session"
  | Some launch -> launch ()

let select_keeper_first ~ko =
  if ko then "먼저 키퍼를 고르세요" else "Select a Keeper first"

let send_operator_text ?keeper_name state ~base_path ~mailbox snapshot =
  let text = Masc_tui_message_input.snapshot_text snapshot in
  let spill = message_spill_in_snapshot state snapshot in
  let target =
    match keeper_name with
    | Some _ as named -> named
    | None -> state.msg_target_keeper_name
  in
  let notice = Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target in
  (* A large paste may replace even the slash command with a placeholder.
     Peek only to recognize preset saves; all other commands keep their
     existing spill handling. Materialize the retained input before parsing
     or clearing it so the exact description survives a failed dispatch. *)
  let candidate = Masc_tui_chat_input.Paste_spill.inline_spilled_paste spill text in
  let is_preset_save = match Masc_tui_command.parse candidate with
    | Masc_tui_command.Preset_save _ | Preset_save_missing_name -> true
    | Say _ | Task_for_keeper _ | Task_recover | Task_inspect | Task_missing_title | Help | Features
    | Show_load_errors | About | Lane_addons _ | Play_invites | Play_link _ | Play_invite _
    | Play_revoke _ | Play_invalid _ | Open_metrics | Account_login _ | Open_settings
    | Open_diff | Open_usage | Open_link_preview _ | Open_links_list
    | Copy_latest_reply | Set_embeds _ | Open_changes | Toggle_acting_pane
    | Show_acting_pane_tab _ | Acting_pane_tab_unknown _ | Set_acting_pane_call_order _
    | Acting_pane_call_order_unknown _ | Scroll_acting_pane _ | Acting_pane_scroll_unknown _
    | Switch_keeper _ | Switch_keeper_missing_name | Queue _ | Run_next | Reconcile_held | Priority _
    | Answer_tool_approval _ | Interrupt_turn | Interrupt_keeper_turn _ | Steer_turn _
    | Steer_missing_message | Set_thinking _ | Open_calls | Set_tools _ | Cycle_memory | Memory_status
    | Open_fleet_memory | Find_in_chat _ | Find_next | Open_measurement _ | Measurement_missing_sha
    | Inspect_context | View_image _ | View_image_missing_path | Attach_image _ | Attach_image_missing_path
    | Attach_image_ref _ | Attach_image_ref_missing_value | Preset_list | Preset_restore _
    | Preset_restore_missing_name | Preset_show _ | Preset_show_missing_name | Preset_delete _
    | Preset_delete_missing_name | Listen | Open_artifacts | Open_music | Open_music_midi
    | Music_invalid_arguments | Open_score _ | Score_invalid_index | Open_images _ | List_images
    | Images_invalid_index | Unknown _ -> false in
  let text = if is_preset_save then begin
    let materialized = Masc_tui_chat_input.Paste_spill.materialise_spilled_paste state snapshot in
    if not (String.equal materialized text)
       && String.equal (Masc_tui_message_input.contents state.msg_input) text then begin
      Masc_tui_message_input.clear state.msg_input;
      Masc_tui_message_input.insert state.msg_input materialized
    end;
    materialized
  end else text in
  let command, ranges = Masc_tui_command.parse_with_message_source text in
  let spill = Option.bind ranges (fun ranges ->
      Option.bind spill (fun spill ->
          Option.map (fun view -> { spill with sms_view = view })
            (Masc_tui_message_input.project_owned spill.sms_view ranges))) in
  if
    Option.is_some (current_recall_edit state)
    && match command with
      | Masc_tui_command.Say _ -> false
      | Masc_tui_command.Task_for_keeper _ | Task_recover | Task_inspect | Task_missing_title | Help | Features
      | Show_load_errors | About
      | Lane_addons _ | Play_invites | Play_link _ | Play_invite _ | Play_revoke _ | Play_invalid _
      | Open_metrics | Account_login _ | Open_settings | Open_diff | Open_usage
      | Open_link_preview _ | Open_links_list | Copy_latest_reply | Set_embeds _ | Open_changes
      | Toggle_acting_pane | Show_acting_pane_tab _ | Acting_pane_tab_unknown _
      | Set_acting_pane_call_order _ | Acting_pane_call_order_unknown _ | Scroll_acting_pane _
      | Acting_pane_scroll_unknown _ | Switch_keeper _ | Switch_keeper_missing_name | Queue _
      | Run_next | Reconcile_held | Priority _ | Answer_tool_approval _ | Interrupt_turn | Interrupt_keeper_turn _
      | Steer_turn _ | Steer_missing_message | Set_thinking _ | Open_calls | Set_tools _ | Cycle_memory | Memory_status
      | Open_fleet_memory | Find_in_chat _ | Find_next | Open_measurement _
      | Measurement_missing_sha | Inspect_context | View_image _ | View_image_missing_path
      | Attach_image _ | Attach_image_missing_path | Attach_image_ref _
      | Attach_image_ref_missing_value | Preset_list | Preset_save _ | Preset_save_missing_name
      | Preset_restore _ | Preset_restore_missing_name | Preset_show _ | Preset_show_missing_name
      | Preset_delete _ | Preset_delete_missing_name | Listen
      | Open_artifacts | Open_music | Open_music_midi | Music_invalid_arguments | Open_score _ | Score_invalid_index
      | Open_images _ | List_images | Images_invalid_index | Unknown _ -> true
  then
    notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
      "A queued edit is active; press Enter for its text or Ctrl-U to abandon it"
  else
  match command with
  | Masc_tui_command.Say _ when Masc_tui_chat_input.Paste_spill.recovered_paste_send_locked_for state target ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
        "Recovered draft protected; press Ctrl-G to enable Enter"
  | Masc_tui_command.Say _ ->
      Masc_tui_chat_dispatch.Queue_steer.start_keeper_message ?keeper_name ?spill state ~base_path ~mailbox text
  | Masc_tui_command.Task_missing_title ->
      report_action state "error" "/task needs a title on the same line"
  | Masc_tui_command.View_image_missing_path ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/image needs a path on the same line"
  | Masc_tui_command.Measurement_missing_sha ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/measurement needs a SHA-256 on the same line"
  | Masc_tui_command.Open_measurement sha256 ->
      (match Tool_blob_store.validate_sha256 sha256 with
       | Error error ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure (Tool_blob_store.invalid_sha256_to_string error)
       | Ok () ->
           Masc_tui_message_input.clear state.msg_input;
           goto_surface state ~mailbox Lanes;
           open_measurement_artifact state ~mailbox ~sha256)
  | Masc_tui_command.View_image path ->
      Masc_tui_message_input.clear state.msg_input;
      open_image state ~mailbox ~notice (String.trim path)
  | Masc_tui_command.Attach_image_missing_path ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/attach needs a path on the same line"
  | Masc_tui_command.Attach_image_ref_missing_value ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/ref needs a URL or file_id on the same line"
  | Masc_tui_command.Attach_image_ref value -> (
      Masc_tui_message_input.clear state.msg_input;
      (* A whole-token http(s) URL is a URL reference; anything else non-blank
         is a Files-API id. Both send no bytes — the provider resolves the
         reference or visibly rejects it. *)
      let value = String.trim value in
      let reference =
        if String_util.starts_with_ci ~prefix:"https://" value
           || String_util.starts_with_ci ~prefix:"http://" value
        then Some (Keeper_chat.Ref_url value)
        else if value = "" then None
        else Some (Keeper_chat.Ref_file_id value)
      in
      match reference with
      | None ->
          notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/ref needs a URL or file_id on the same line"
      | Some reference ->
          (Masc_tui_message_input.invalidate_revision state.msg_input; state.msg_references <- state.msg_references @ [ reference ]);
          Masc_tui_chat_input.Message_draft_recall.note_attachment_staged state;
          let kind =
            match reference with
            | Keeper_chat.Ref_url _ -> "url"
            | Keeper_chat.Ref_file_id _ -> "file_id"
          in
          let count = List.length state.msg_references in
          notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
            (if state.ui_language = Lang_ko then
               Printf.sprintf "참조 추가됨 %s (%s) · 제공자가 직접 가져옵니다 · 다음 메시지 참조 %d개 대기 중"
                 value kind count
             else
               Printf.sprintf
                 "referenced %s (%s) · the provider fetches it; %s staged for the next message"
                 value kind (Masc_tui_message_layout.count_noun count "reference")))
  | Masc_tui_command.Attach_image path -> (
      Masc_tui_message_input.clear state.msg_input;
      match Masc_tui_attachment.of_file ~path:(String.trim path) with
      | Error error ->
          notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
            (Masc_tui_attachment.error_to_string error)
      | Ok attachment ->
          (Masc_tui_message_input.invalidate_revision state.msg_input; state.msg_attachments <- state.msg_attachments @ [ attachment ]);
          Masc_tui_chat_input.Message_draft_recall.note_attachment_staged state;
          notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
            (Printf.sprintf
               "attached %s (%s, %d bytes) · %d staged for the next message"
               attachment.Masc_tui_keeper_chat_projection.name
               attachment.Masc_tui_keeper_chat_projection.mime_type
               attachment.Masc_tui_keeper_chat_projection.size
               (List.length state.msg_attachments)))
  | Masc_tui_command.Show_load_errors ->
      Masc_tui_message_input.clear state.msg_input;
      if state.view <> Keepers Keeper_message
         || Option.is_none target
         || target <> state.msg_target_keeper_name then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "Open a Keeper chat to inspect its loading errors"
      else begin
        let errors =
          let ko = state.ui_language = Lang_ko in
          [ Option.map (fun failure -> "Saved history\n"
                ^ request_failure_text ~ko ~request:Kept_request.Keeper_history_read failure)
              state.msg_loaded_error
          ; Option.map (fun failure -> "Older messages\n"
                ^ request_failure_text ~ko ~request:Kept_request.Keeper_older_read failure)
              state.msg_older_error
          ; Option.map (fun failure -> "Memory journal\n"
                ^ request_failure_text ~ko ~request:Kept_request.Keeper_memory_read failure)
              state.msg_memory_error
          ] |> List.filter_map Fun.id
        in
        set_msg_scroll state 0;
        (* A local log entry wraps and scrolls. A failure toast would flatten
           these details back into the one-line truncation being inspected. *)
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
          (match errors with
           | [] -> "No chat loading errors recorded."
           | _ :: _ -> "Chat loading errors\n\n" ^ String.concat "\n\n" errors)
      end
  | Masc_tui_command.Help ->
      Masc_tui_message_input.clear state.msg_input;
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
        (String.concat "\n"
           (Masc_tui_command.help_lines_for ~ko:(state.ui_language = Lang_ko)))
  | Masc_tui_command.Features ->
      Masc_tui_message_input.clear state.msg_input;
      let _, cols = get_terminal_size () in
      let width =
        if cols < Masc_tui_help.two_column_minimum_cols then
          Masc_tui_frame.inner_width ~cols
        else Masc_tui_help.column_width ~cols
      in
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
        (String.concat "\n" (Masc_tui_features.lines_for ~ko:(state.ui_language = Lang_ko) ~width))
  | Masc_tui_command.About ->
      Masc_tui_message_input.clear state.msg_input;
      state.about_open <- true;
      state.emblem_frame <-
        (if state.about_reduce_motion then Masc_tui_emblem_screen.final_frame else 0)
  | Masc_tui_command.Open_diff ->
      Masc_tui_message_input.clear state.msg_input;
      state.repository_changes_return_chat <- true;
      open_repository_changes state ~mailbox
        ~scope:Tui_decode.Repository_change_project
  | Masc_tui_command.Open_usage ->
      Masc_tui_message_input.clear state.msg_input;
      goto_surface state ~mailbox Metrics
  | Masc_tui_command.Open_link_preview url_opt ->
      Masc_tui_message_input.clear state.msg_input;
      let all_urls = Masc_tui_types.conversation_urls state in
      state.link_modal_links <- all_urls;
      let target_url =
        match url_opt with
        | Some u -> Some u
        | None ->
            (match all_urls with
             | first :: _ -> Some first
             | [] -> None)
      in
      (match target_url with
       | Some u ->
           state.link_modal_open <- true;
           state.link_modal_url <- Some u;
           state.link_modal_scroll <- 0;
           let rec find_idx i = function
             | [] -> 0
             | x :: _ when String.equal x u -> i
             | _ :: xs -> find_idx (i + 1) xs
           in
           state.link_modal_cursor <- find_idx 0 all_urls
       | None ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             "No web links found in this conversation to preview. Use /preview <url> to preview any link.")
  | Masc_tui_command.Open_links_list ->
      Masc_tui_message_input.clear state.msg_input;
      let all_urls = Masc_tui_types.conversation_urls state in
      state.link_modal_links <- all_urls;
      (match all_urls with
       | first :: _ ->
           state.link_modal_open <- true;
           state.link_modal_url <- Some first;
           state.link_modal_scroll <- 0;
           state.link_modal_cursor <- 0
       | [] ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "No web links found in this conversation.")
  | Masc_tui_command.Set_embeds mode ->
      Masc_tui_message_input.clear state.msg_input;
      state.link_previews_mode <-
        (match mode with
         | `On -> `Rich
         | `Compact -> `Compact
         | `Off -> `Off);
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
        (Printf.sprintf "Inline link embed cards: %s"
           (match state.link_previews_mode with
            | `Rich -> "Rich (Full Cards)"
            | `Compact -> "Compact (One Line)"
            | `Off -> "Off"))
  | Masc_tui_command.Open_changes ->
      Masc_tui_message_input.clear state.msg_input;
      state.changes_return <- Changes_return_chat;
      goto_surface state ~mailbox Changes
  | Masc_tui_command.Toggle_acting_pane ->
      Masc_tui_message_input.clear state.msg_input;
      (match toggle_acting_pane state with
       | Ok layout ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             (let ko = state.ui_language = Lang_ko in
              (if ko then "활동 창 " else "Activity pane ")
              ^ Masc_tui_acting_pane.layout_label ~ko layout)
       | Error reason -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure reason)
  | Masc_tui_command.Show_acting_pane_tab tab ->
      Masc_tui_message_input.clear state.msg_input;
      let tab =
        match tab with
        | `Fleet -> Masc_tui_acting_pane.Tab_fleet
        | `Changes -> Masc_tui_acting_pane.Tab_changes
      in
      (match show_acting_pane_tab state tab with
       | Ok () ->
           (match tab with
            | Masc_tui_acting_pane.Tab_changes -> refresh_acting_pane_changes state ~mailbox
            | Masc_tui_acting_pane.Tab_fleet -> ());
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             (let ko = state.ui_language = Lang_ko in
              (if ko then "활동 창 탭: " else "Activity pane on ")
              ^ Masc_tui_acting_pane.tab_label ~ko tab)
       | Error reason -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure reason)
  | Masc_tui_command.Acting_pane_tab_unknown word ->
      Masc_tui_message_input.clear state.msg_input;
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
        (Printf.sprintf "/activity takes fleet, changes, order or scroll, not %s" word)
  | Masc_tui_command.Set_acting_pane_call_order which ->
      Masc_tui_message_input.clear state.msg_input;
      (* The calls are drawn on the fleet tab, so the order is set with that
         tab up: turning an order the reader cannot see would surprise them
         after the next switch, the rule [show_acting_pane_tab] keeps for
         the tab itself. *)
      (match show_acting_pane_tab state Masc_tui_acting_pane.Tab_fleet with
       | Ok () ->
           let order =
             match which with
             | `Next -> Masc_tui_acting_pane.next_call_order state.acting_pane_call_order
             | `Newest -> Masc_tui_acting_pane.Newest_first
             | `Oldest -> Masc_tui_acting_pane.Oldest_first
             | `Longest -> Masc_tui_acting_pane.Longest_first
             | `By_tool -> Masc_tui_acting_pane.By_tool
           in
           state.acting_pane_call_order <- order;
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             (let ko = state.ui_language = Lang_ko in
              (if ko then "활동 창 호출 순서: " else "Activity calls ")
              ^ Masc_tui_acting_pane.call_order_label ~ko order)
       | Error reason -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure reason)
  | Masc_tui_command.Acting_pane_call_order_unknown word ->
      Masc_tui_message_input.clear state.msg_input;
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
        (Printf.sprintf
           "/activity order takes newest, oldest, longest or tool, not %s" word)
  | Masc_tui_command.Scroll_acting_pane how ->
      Masc_tui_message_input.clear state.msg_input;
      (* Scrolling a pane the frame does not draw would move it unseen, and
         the reader would meet the change after the next Ctrl-L. The two
         reasons it is not drawn are said the way the toggle says them. *)
      let _rows, cols = Masc_tui_ansi.get_terminal_size () in
      if Masc_tui_render.acting_pane_suppressed state then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
          "Activity pane is not drawn over this surface; nothing to scroll"
      else if
        Masc_tui_acting_pane.drawn_cols ~layout:(acting_pane_layout state) ~cols = 0
      then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
          "Activity pane is not shown; Ctrl-L or /activity shows it"
      else begin
        (match how with
         | `Top -> state.acting_pane_scroll <- 0
         | `Up -> scroll_acting_pane state ~delta:(-wheel_notch_rows)
         | `Down -> scroll_acting_pane state ~delta:wheel_notch_rows
         | `By rows -> scroll_acting_pane state ~delta:rows);
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
          (Printf.sprintf "Activity pane scrolled to row %d of %d"
             (state.acting_pane_scroll + 1)
             (state.acting_pane_presented.frame_scroll_max + 1))
      end
  | Masc_tui_command.Acting_pane_scroll_unknown word ->
      Masc_tui_message_input.clear state.msg_input;
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
        (Printf.sprintf
           "/activity scroll takes up, down, top, +N or -N, not %s" word)
  | Masc_tui_command.Lane_addons input ->
      Masc_tui_message_input.clear state.msg_input;
      (match Masc_tui_lane_addons.parse_request input with
       | Ok request -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox request
       | Error detail ->
           let view = Option.value ~default:state.lane_addons_cached state.lane_addons in
           state.lane_addons <- Some { view with error = Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail })
  | Masc_tui_command.Open_metrics ->
      Masc_tui_message_input.clear state.msg_input;
      goto_surface state ~mailbox Metrics;
      state.usage_telemetry_open <- true
  | Masc_tui_command.Account_login requested ->
      Masc_tui_message_input.clear state.msg_input;
      let module Login = Masc_tui_account_login in
      let restored, retained = Login.take_saved ~requested state.account_login_detached in
      state.account_login_detached <- retained;
      let view = match restored with
        | Some view -> view.ko <- state.ui_language = Lang_ko; view
        | None -> Login.create ~ko:(state.ui_language = Lang_ko) requested in
      state.account_login <- Some view;
      (match restored, view.phase with
       | Some _, (Login.Saving | Login.Failed) -> ()
       | Some _, Login.Finished {activation = Login.Activating; _} -> ()
       | Some _, Login.Finished {saved; activation = (Login.Activation_failed _ | Login.Activation_kept_back _ | Login.Active _); _} ->
         Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view (Login.Refresh_saved saved)
       | Some _, (Login.Loading | Login.Logging | Login.Models | Login.Refreshing_models | Login.Preparing_context _
           | Login.Preparing_context_batch _
           | Login.Removing | Login.Providers _ | Login.Documented_context _ | Login.Removal _)
       | (None, _) -> Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view Login.Inventory)
  | Masc_tui_command.Open_settings ->
      Masc_tui_message_input.clear state.msg_input;
      state.config_pane <- Config_params;
      state.config_scroll <- 0;
      state.runtime_params_cursor <- 0;
      state.runtime_param_edit <- None;
      state.runtime_params_notice <- None;
      goto_surface state ~mailbox Config
  | Masc_tui_command.Open_music_midi ->
      Masc_tui_message_input.clear state.msg_input;
      listen_newest_media ~destination:Listen_music_editor state ~mailbox
  | Masc_tui_command.Listen ->
      Masc_tui_message_input.clear state.msg_input;
      listen_newest_media state ~mailbox
  | Masc_tui_command.Score_invalid_index ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/score [N]: N must be a positive score number, newest first"
  | Masc_tui_command.Images_invalid_index ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/images [N]: N must be a positive image/diagram number, newest first"
  | Masc_tui_command.Open_images index ->
      open_indexed_image state ~mailbox ~index
  | Masc_tui_command.List_images ->
      list_conversation_images state
  | Masc_tui_command.Music_invalid_arguments ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "Use /music for the library, or /music midi to edit the newest MIDI attachment"
  | Masc_tui_command.Open_artifacts ->
      Masc_tui_message_input.clear state.msg_input;
      state.resource_day <- None;
      Masc_tui_resources_updates.select_scope state Masc_tui_resource_catalog.Published_reports;
      state.resource_focus <- Left_pane;
      state.resource_layout <- Masc_tui_resource_catalog.Full_width;
      goto_surface state ~mailbox Resources
  | Masc_tui_command.Open_music ->
      Masc_tui_message_input.clear state.msg_input;
      (match open_music () with
       | Ok () -> ()
       | Error detail -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure detail)
  | Masc_tui_command.Open_score index ->
      let sources = Masc_tui_chat_input.Message_draft_recall.image_conversation_rows state
        |> List.concat_map (fun (entry : msg_entry) -> Masc_tui_markdown.alphatex_sources entry.me_text)
        |> List.rev in
      let count = List.length sources in
      if index > count then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
          (if state.ui_language = Lang_ko then
             Printf.sprintf "/score: 불러온 대화에 닫힌 alphaTex 코드 블록이 %d개 있습니다" count
           else
             Printf.sprintf "/score: this loaded conversation has %s"
               (Masc_tui_message_layout.count_noun count "closed alphaTex block"))
      else
        (match !score_terminal_handoff with
         | None ->
             notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
               (ui_text state ~ko:"alphaTex 악보 보기는 활성 터미널 세션이 필요합니다"
                  ~en:"alphaTex viewer requires an active terminal session")
         | Some launch ->
             Masc_tui_message_input.clear state.msg_input;
             match launch ~sources ~index with
             | Ok () -> ()
             | Error detail -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure detail)
  | Masc_tui_command.Switch_keeper_missing_name ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/keeper needs a name on the same line"
  | Masc_tui_command.Switch_keeper name -> (
      let names =
        List.map (fun (keeper : keeper) -> keeper.k_name) state.keepers
      in
      match Masc_tui_command.resolve_keeper_name ~names name with
      | Masc_tui_command.Keeper_found keeper_name ->
          Masc_tui_message_input.clear state.msg_input;
          Masc_tui_chat_input.Message_draft_recall.open_message_for_keeper ~return_to:state.msg_return state keeper_name
            ~drain_queue:(fun () -> Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox);
          state.view <- Keepers Keeper_message;
          launch_keeper_history_load state ~mailbox ~keeper_name
      | Masc_tui_command.Keeper_ambiguous candidates ->
          notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
            (Printf.sprintf "%S names more than one keeper: %s" name
               (String.concat ", " candidates))
      | Masc_tui_command.Keeper_unknown ->
          notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
            (Printf.sprintf "no keeper named %S on the roster" name))
  | Masc_tui_command.Queue input ->
      Masc_tui_message_input.clear state.msg_input;
      (match state.msg_target_keeper_name, Masc_tui_queue_inspection.parse input with
       | None, _ -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure (select_keeper_first ~ko:(state.ui_language = Lang_ko))
       | _, Error detail -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure detail
       | _, Ok (Masc_tui_queue_inspection.Inspect_peers _) ->
         assert false (* [parse] never creates a roster read. *)
       | Some keeper_name, Ok Masc_tui_queue_inspection.Inspect ->
         Masc_tui_collab_queue.Keeper_queue.open_keeper_queue_panel state ~mailbox ~keeper_name
       | Some keeper_name, Ok Masc_tui_queue_inspection.Clear ->
         (* The part that needs no server. A line that exists only in this
            client is withdrawn here, so it is gone even when the queue request
            below is refused. This row also counts the lines the server holds,
            as a fact about them and not a claim that a cancel was sent: the
            queue request says whether it sends, and each cancel's answer. It
            is made even when this client holds nothing to cancel, because its
            snapshot is the one place a line this client no longer tracks is
            still listed. *)
         let withdrawn, on_server, left =
           List.fold_left (fun (withdrawn, on_server, left) (request, position) ->
             match keeper_queue_clear_treatment position with
             | Drop_from_local_queue ->
               if Masc_tui_chat_input.Message_draft_recall.drop_unsent_request state request then (withdrawn + 1, on_server, left)
               else (withdrawn, on_server, left + 1)
             | Withdraw_before_post ->
               withdraw_undispatched_request state request;
               Masc_tui_chat_input.Message_draft_recall.forget_queued_history state request;
               withdrawn + 1, on_server, left
             | Cancel_on_server -> withdrawn, on_server + 1, left
             | Leave_waiting -> withdrawn, on_server, left + 1)
             (0, 0, 0) (keeper_message_waiting_positions state ~keeper_name) in
         let clause count what =
           if count = 0 then None else Some (Printf.sprintf "%d %s" count what) in
         (match List.filter_map Fun.id
                  [ clause withdrawn "unsent cancelled"
                  ; clause on_server "in the server queue"
                  ; clause left "left waiting (being posted, being rechecked, already started, or already ended)" ] with
          | [] -> ()
          | _ :: _ as clauses ->
            notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply ("/queue clear: " ^ String.concat " · " clauses));
         Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox;
         Masc_tui_collab_queue.Keeper_queue.launch_keeper_queue state ~mailbox ~keeper_name Masc_tui_queue_inspection.Clear
       | Some keeper_name,
         Ok ((Masc_tui_queue_inspection.Pause | Resume | Cancel _
             | Move_to_end _ | Run_next _ | Edit _ | Cancel_event _ | Prioritize_event _) as action) ->
         let local_id = match action with
           | Masc_tui_queue_inspection.Cancel id | Move_to_end id | Run_next id | Edit (id, _) -> Some id
           | Inspect | Inspect_peers _ | Pause | Resume | Clear | Cancel_event _ | Prioritize_event _ -> None in
         match Option.bind local_id (fun id -> Chat_queue.find state.msg_queued ~request_id:id) with
         | Some item when item.request.keeper_name <> keeper_name ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "That message belongs to another Keeper"
         | Some item ->
           (match action with
            | Masc_tui_queue_inspection.Cancel id ->
              if Masc_tui_chat_input.Message_draft_recall.drop_unsent_request state item.request then begin
                notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply ("Cancelled unsent message " ^ id);
                Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox
              end
              else notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "Local queue changed; inspect /queue again"
            | Edit (id, message) ->
              let request = {item.request with Keeper_chat.message = message} in
              let source = Chat_queue.source_for_edit item ~message in
              (match Chat_queue.replace_request ~source state.msg_queued ~request_id:id request with
               | Error detail -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure detail
               | Ok queue -> state.msg_queued <- queue; Masc_tui_chat_dispatch.Queue_steer.update_queued_history_text state request;
                   notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply ("Updated unsent message " ^ id))
            | Move_to_end _ -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "Open the queue panel to reorder local input"
            | Run_next _ -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "Open the queue panel to prioritize local input"
            | Inspect | Inspect_peers _ | Pause | Resume | Clear | Cancel_event _ | Prioritize_event _ -> assert false)
         | None -> Masc_tui_collab_queue.Keeper_queue.launch_keeper_queue state ~mailbox ~keeper_name action)
  | Masc_tui_command.Run_next
    when state.workspace_identity <> Workspace_identity_match ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
        (let ko = state.ui_language = Lang_ko in
         kept_back ~ko ~request:(Kept_request.Command "/run-next") (workspace_identity_unconfirmed ~ko) Queued_input_kept)
  | Masc_tui_command.Reconcile_held ->
      Masc_tui_message_input.clear state.msg_input;
      (match state.msg_target_keeper_name with
       | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure (select_keeper_first ~ko:(state.ui_language = Lang_ko))
       | Some name ->
         let held =
           List.filter (fun (entry : inflight) ->
               String.equal entry.sent_request.Keeper_chat.keeper_name name
               && (match entry.phase with
                   | Turn_reconciling -> true
                   | Turn_preflight _ | Turn_streaming -> false))
             state.msg_inflight
         in
         (match held with
          | [] -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "No request with an unverified outcome is held for this Keeper"
          | _ :: _ ->
            (* The watcher holding the request waits on this Keeper's count;
               moving it sends the next reconcile once (#36205). *)
            Masc_tui_waiting_inventory.keeper_changed state.waiting_inventory name;
            notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
              (Printf.sprintf "Checking %s again"
                 (String.concat ", "
                    (List.map (fun (entry : inflight) -> entry.sent_request.Keeper_chat.request_id) held)))))
  | Masc_tui_command.Run_next ->
      Masc_tui_message_input.clear state.msg_input;
      (match state.msg_target_keeper_name with
       | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure (select_keeper_first ~ko:(state.ui_language = Lang_ko))
       | Some name ->
         if List.mem_assoc name state.keeper_chat_control_pending then
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "Wait for the pending stop or resume before run-next"
         else if not (keeper_available_for_new_message state name) then
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "Keeper is unavailable; queued input retained"
         else if recalling_for_keeper state name then
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "Finish or abandon the queued edit before run-next"
         else if Masc_tui_chat_dispatch.Queue_steer.run_next_busy_for state name then
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "A run-next request is already pending"
         else
         match List.nth_opt (Chat_queue.waiting_for_keeper state.msg_queued ~keeper_name:name) 0 with
         | Some item when keeper_admission_pending state name ->
           (* Keep the request in its queue position until the earlier POST
              has an admission. The priority remains attached to this exact
              item and cancellation or editing updates that intent too. *)
           let request_id = item.request.Keeper_chat.request_id in
           (match Chat_queue.mark_run_next state.msg_queued ~request_id with
            | Error detail -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure detail
            | Ok queue ->
              state.msg_queued <- queue;
              state.keeper_interactive_waiting <-
                (name, request_id, Awaiting_control {
                  generation=keeper_chat_control_generation state name; target=None }) ::
                List.filter (fun (_, id, _) -> id <> request_id) state.keeper_interactive_waiting;
              notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "Run-next retained; waiting for the earlier admission")
         | Some item ->
           (match Chat_queue.take state.msg_queued ~request_id:item.request.request_id with
            | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "Local queue changed; inspect /queue again"
            | Some (taken, rest) ->
              state.msg_queued <- rest;
              let promoted = match taken.intent with
                | Chat_queue.Steer_after_interrupt -> taken
                | Chat_queue.Steer_without_priority ->
                    {taken with intent=Chat_queue.Steer_after_interrupt}
                | Chat_queue.Next | Chat_queue.Next_without_auto_priority | Chat_queue.Run_next _ ->
                    {taken with intent=Chat_queue.Run_next {automatic=false}} in
              Masc_tui_chat_dispatch.Queue_steer.queue_run_next_on_admission state promoted.request;
              Masc_tui_chat_dispatch.Queue_steer.launch_keeper_request ~promoted state ~mailbox promoted.request;
              notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "Submitting queued input; it will be prioritized once the server accepts it")
         | None ->
         match Masc_tui_chat_dispatch.Queue_steer.inflight_for state name, live_for_keeper state name with
         | Some _, Some live when Keeper_chat_transcript.phase live.tl_transcript = Keeper_chat_transcript.Working ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "Your message has already started; no new run was created"
         | Some request, Some live ->
           (match Keeper_chat_transcript.admission live.tl_transcript with
            | Some (Keeper_chat_live.Queued, _) -> Masc_tui_chat_dispatch.Queue_steer.launch_keeper_run_next state ~mailbox request
            | Some (Running, _) -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "Your message has already started; no new run was created"
            | Some (Settled, _) -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "Your message already finished; its result is being replayed"
            | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "Waiting for server admission; /run-next is available once this message is queued")
         | _ -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "No submitted message is waiting; send your message with Enter first")
  | Masc_tui_command.Priority opt ->
      Masc_tui_message_input.clear state.msg_input;
      let new_value =
        match opt with
        | None -> not state.user_input_priority_next
        | Some s ->
          let s = String.lowercase_ascii (String.trim s) in
          if s = "on" || s = "true" || s = "1" || s = "yes" then true
          else if s = "off" || s = "false" || s = "0" || s = "no" then false
          else not state.user_input_priority_next
      in
      state.user_input_priority_next <- new_value;
      note_session_key state Masc.Tui_preference.Key.User_input_priority_next;
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
        (Printf.sprintf "User input auto-next priority: %s (new messages will %sbe promoted to run next)"
           (if new_value then "ON" else "OFF")
           (if new_value then "" else "NOT "))
  | Masc_tui_command.Answer_tool_approval allow ->
      Masc_tui_message_input.clear state.msg_input;
      (match target with
       | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply (select_keeper_first ~ko:(state.ui_language = Lang_ko))
       | Some target ->
         match inflight_for_keeper state target with
         | Some entry ->
           (match Keeper_chat_transcript.awaiting_approval entry.log.tl_transcript with
            | Some awaiting ->
              let current =
                if state.image_open || state.msx_open then None
                else Some
                  { Masc_tui_chat_row_actions.scope =
                      (state.workspace_authority, state.workspace_read_authority)
                  ; keeper = target
                  ; request_id = entry.sent_request.request_id
                  ; tool_call_id = awaiting.call_id
                  ; approval_id = awaiting.approval_id
                  }
              in
              (match Approval_authority.resolve_chat
                 ~presented:state.msg_presented_tool_approval ~current with
               | Some shown ->
                   Masc_tui_work_requests.Approval_gate_requests.launch_keeper_approval state ~mailbox entry.sent_request
                     ~tool_call_id:shown.tool_call_id ~approval_id:shown.approval_id ~allow
               | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
                   "Approval changed; review the updated prompt before deciding")
            | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "No tool approval is waiting for this Keeper")
         | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "No tool approval is waiting for this Keeper")
  | Masc_tui_command.Interrupt_turn -> (
      Masc_tui_message_input.clear state.msg_input;
      match Option.bind state.msg_target_keeper_name (Masc_tui_chat_dispatch.Queue_steer.interrupt_observed_keeper ~explicit:true state ~mailbox) with
      | Some _ -> ()
      | None -> match state.msg_live with
      | Some live
        when Keeper_chat_transcript.interrupt live.tl_transcript
             = Keeper_chat_transcript.Not_requested -> (
          match
            inflight_by_request_id state (turn_log_request_id live)
          with
          | Some request -> Masc_tui_chat_dispatch.Queue_steer.launch_keeper_interrupt state ~mailbox request
          | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "no turn of this pane's to interrupt")
      | Some _ ->
          notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
            "an interrupt is already outstanding for this turn"
      | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "no turn is streaming in this pane")
  | Masc_tui_command.Interrupt_keeper_turn name -> (
      Masc_tui_message_input.clear state.msg_input;
      (* The pane's own turn is [Interrupt_turn]'s business. This arm is for
         the turn the pane only tells the operator about -- the "(also
         sending to X ...)" row -- which nothing else could reach: every
         other way in reads [msg_live], and the key that would put that
         keeper on screen is refused while any request is in flight, which
         is exactly when one is running (#33852).

         Matched by the name the row prints, so what the operator types is
         what they just read. *)
      match Masc_tui_chat_dispatch.Queue_steer.interrupt_observed_keeper ~explicit:true state ~mailbox name with
      | Some _ -> ()
      | None -> match Masc_tui_types.inflight_for_keeper state name with
      | Some entry -> Masc_tui_chat_dispatch.Queue_steer.launch_keeper_interrupt state ~mailbox entry.sent_request
      | None ->
          notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
            (Printf.sprintf "no turn of %S is in flight from this pane" name))
  | Masc_tui_command.Steer_missing_message ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/steer needs replacement text on the same line"
  | Masc_tui_command.Steer_turn message ->
      Masc_tui_chat_dispatch.Queue_steer.start_keeper_steer ?keeper_name ?spill state ~base_path ~mailbox message
  | Masc_tui_command.Set_thinking mode ->
      Masc_tui_message_input.clear state.msg_input;
      state.msg_reasoning_visibility <-
        (match mode with
         | `Hidden -> Reasoning_hidden
         | `Folded -> Reasoning_folded
         | `Full -> Reasoning_full
         | `Cycle -> next_reasoning_visibility state.msg_reasoning_visibility);
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
        ("reasoning "
         ^ reasoning_visibility_to_string state.msg_reasoning_visibility)
  | Masc_tui_command.Open_calls ->
      if state.view <> Keepers Keeper_message then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/calls opens original results in a Keeper chat"
      else (match target with
       | Some keeper_name when server_authority_ready state ->
           Masc_tui_message_input.clear state.msg_input;
           Masc_tui_work_requests.Schedule_call_requests.open_chat_call_reader state ~mailbox keeper_name
       | Some _ | None ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (let ko = state.ui_language = Lang_ko in
              kept_back ~ko ~request:(Kept_request.Command "/calls") (workspace_identity_unconfirmed ~ko) Nothing_kept))
  | Masc_tui_command.Set_tools mode ->
      Masc_tui_message_input.clear state.msg_input;
      state.msg_tool_visibility <-
        (match mode with
         | `Compact -> Tools_compact
         | `Results -> Tools_results
         | `Full -> Tools_full
         | `Toggle -> toggle_tool_visibility state.msg_tool_visibility);
      (match state.msg_tool_visibility, target with
       | (Tools_results | Tools_full), Some keeper_name ->
           launch_keeper_chat_tool_details_load ~force:true state ~mailbox
             ~keeper_name
       | Tools_compact, _ | (Tools_results | Tools_full), None -> ());
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
        ("tool calls " ^ tool_visibility_to_string state.msg_tool_visibility)
  | Masc_tui_command.Cycle_memory ->
      Masc_tui_message_input.clear state.msg_input;
      state.msg_memory_visibility <-
        next_memory_visibility state.msg_memory_visibility;
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
        ("Librarian/Memory timeline: "
         ^ memory_visibility_to_string state.msg_memory_visibility
         ^ " (Ctrl-N or /memory to cycle)")
  | Masc_tui_command.Memory_status ->
      (match target with
       | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure (select_keeper_first ~ko:(state.ui_language = Lang_ko))
       | Some _ when not (server_authority_ready state) ->
         notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
           (let ko = (state.ui_language = Lang_ko) in
            kept_back ~ko ~request:(Kept_request.Command "/memory status") (workspace_identity_unconfirmed ~ko) Draft_kept)
       | Some keeper ->
         Masc_tui_message_input.clear state.msg_input;
         notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
           (keeper ^ ": " ^ ui_text state ~ko:"메모리 처리 상태 조회 중"
              ~en:"loading memory processing status");
         let ticket = ref () in
         state.chat_command_reads <-
           (ticket, state.workspace_read_authority, "/memory status") :: state.chat_command_reads;
         let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
         Masc_tui_transport.Workspace_admission.launch_json_read state ~mailbox
           ~boundary_error:(fun detail -> Request_failed detail)
           ~withdrawn:(fun refusal -> Request_withdrawn refusal)
           ~deliver:(fun result -> Chat_command_read_completed
             (ticket, Memory_msg (Memory_loaded (Command_health_read {keeper; result}))))
           (fun () -> Masc_tui_loader.load_memory_health_row ~host ~port ~keeper
             |> Result.map_error (fun detail -> Request_failed detail)))
  | Masc_tui_command.Open_fleet_memory ->
      Masc_tui_message_input.clear state.msg_input;
      goto_surface state ~mailbox Memory;
      Masc_tui_surface_requests.Memory_repository_requests.open_all_fleet_memory state ~mailbox
  | Masc_tui_command.Find_in_chat query ->
      (* A new query starts at the newest message; [Find_next] below carries on
         from wherever this landed. *)
      Masc_tui_message_input.clear state.msg_input;
      state.msg_find <- String.trim query;
      state.msg_find_at <- None;
      seek_in_chat state ~mailbox ~target ~restart:true
  | Masc_tui_command.Find_next ->
      Masc_tui_message_input.clear state.msg_input;
      if String.equal state.msg_find "" then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
          "/find needs text the first time; /find on its own repeats it"
      else seek_in_chat state ~mailbox ~target ~restart:false
  | Masc_tui_command.Copy_latest_reply ->
      Masc_tui_message_input.clear state.msg_input;
      (match target with
       | Some keeper_name -> Masc_tui_chat_dispatch.Chat_journals.launch_keeper_chat_copy state ~mailbox ~keeper_name
       | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/copy needs a Keeper selected")
  | Masc_tui_command.Inspect_context ->
      (match target with
       | Some keeper_name ->
           Masc_tui_message_input.clear state.msg_input;
           Masc_tui_chat_dispatch.Chat_journals.open_context_inspector state ~mailbox ~keeper_name
       | None ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             "/context needs a Keeper selected on the roster")
  | Masc_tui_command.Preset_list ->
      Masc_tui_message_input.clear state.msg_input;
      Masc_tui_surface_requests.Prompt_preset_requests.launch_chat_command_read state ~mailbox ~label:"/preset"
        ~call:(fun ~host ~port -> Masc_tui_loader.load_presets ~host ~port)
        ~wrap:(fun result -> Preset_msg (Presets_listed (Preset_to_chat target, result)))
  | Masc_tui_command.Preset_save_missing_name ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/preset save needs a name on the same line"
  | Masc_tui_command.Preset_save { name; description } ->
      if not (server_authority_ready state) then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
          (preset_save_needs_workspace_text ~ko:(state.ui_language = Lang_ko))
      else if (state.preset_busy || workspace_preset_save_pending state <> [])
              && not (preset_save_is_pending state name) then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
          (ui_text state ~ko:"진행 중인 프리셋 저장이 끝나면 다시 제출하세요 · 입력 유지"
             ~en:"Wait for the pending preset save · input retained")
      else if preset_save_is_unconfirmed state name && not (preset_save_is_pending state name) then
        (match workspace_input_identity_of_server state.server_identity with
         | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (preset_save_needs_workspace_text ~ko:(state.ui_language = Lang_ko))
         | Some _ when state.preset_busy || Option.is_some state.preset_save_draft ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (ui_text state ~ko:"기존 프리셋 입력을 마친 뒤 다시 제출하세요 · 채팅 입력 유지"
                ~en:"Finish the existing preset draft first · chat input retained")
         | Some workspace ->
           let revision = Masc_tui_message_input.revision state.msg_input in
           let authority = state.workspace_authority in
           state.config_pane <- Config_presets;
           goto_surface state ~mailbox Config;
           state.preset_save_draft <- Some name;
           state.preset_save_draft_description <- description;
           state.preset_save_draft_source <- Preset_form_chat { target; input = text; revision; authority };
           state.preset_save_draft_workspace <- Some workspace;
           state.preset_armed <- Some (Save_armed name);
           state.preset_confirmation_token <- Some (ref ());
           state.preset_confirmation_presented <- None;
           reveal_unconfirmed_preset_save state name;
           state.config_scroll <- 0;
           report_action state "system"
             (ui_text state ~ko:"저장 경고와 채팅 설명을 확인한 뒤 재저장하세요"
                ~en:"Review the save warning and chat description before retrying"))
      else begin
        if not (preset_save_is_pending state name) then
          Masc_tui_message_input.clear state.msg_input;
        Masc_tui_surface_requests.Prompt_preset_requests.launch_preset_save state ~mailbox ~sink:(Preset_to_chat target)
          ~name ~description ~chat_input:(Some text) ~also_pane:false
      end
  | Masc_tui_command.Preset_restore_missing_name ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/preset restore needs a name on the same line"
  | Masc_tui_command.Preset_show_missing_name ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/preset show needs a name on the same line"
  | Masc_tui_command.Preset_show name ->
      (* [/preset] alone lists names and counts; a count cannot be read, so
         this asks the server what that one preset actually holds. *)
      Masc_tui_message_input.clear state.msg_input;
      Masc_tui_surface_requests.Prompt_preset_requests.launch_chat_command_read state ~mailbox ~label:"/preset show"
        ~call:(fun ~host ~port -> Masc_tui_loader.load_preset_detail ~host ~port ~name)
        ~wrap:(fun result -> Preset_msg (Preset_contents_shown (Preset_to_chat target, result)))
  | Masc_tui_command.Preset_restore name ->
      if state.preset_busy || workspace_preset_save_pending state <> [] then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
          (ui_text state ~ko:"진행 중인 프리셋 저장이 끝나면 복원하세요 · 입력 유지"
             ~en:"Wait for the pending preset save before restoring · input retained")
      else begin
      Masc_tui_message_input.clear state.msg_input;
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
        (Printf.sprintf "restoring preset %s · the live state is autosaved first" name);
      Masc_tui_surface_requests.Prompt_preset_requests.launch_preset_call state ~mailbox
        ~call:(fun ~host ~port -> Masc_tui_loader.restore_preset ~host ~port ~name)
        ~wrap:(fun result -> Preset_msg (Preset_restored (Preset_to_chat target, result)))
      end
  | Masc_tui_command.Preset_delete_missing_name ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/preset delete needs a name on the same line"
  | Masc_tui_command.Preset_delete name ->
      (* Typing the name is the confirmation, as for restore. The name need
         not load: a preset listed with ! is deleted the same way. *)
      if state.preset_busy || workspace_preset_save_pending state <> [] then
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
          (ui_text state ~ko:"진행 중인 프리셋 저장이 끝나면 삭제하세요 · 입력 유지"
             ~en:"Wait for the pending preset save before deleting · input retained")
      else begin
      Masc_tui_message_input.clear state.msg_input;
      Masc_tui_surface_requests.Prompt_preset_requests.launch_preset_call state ~mailbox
        ~call:(fun ~host ~port -> Masc_tui_loader.delete_preset ~host ~port ~name)
        ~wrap:(fun result -> Preset_msg (Preset_deleted (Preset_to_chat target, result)))
      end
  | Masc_tui_command.Play_invalid reason ->
      notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure reason
  | Masc_tui_command.Play_invites ->
      Masc_tui_message_input.clear state.msg_input;
      let expected_workspace = state.server_identity in
      Masc_tui_surface_requests.Prompt_preset_requests.launch_chat_command_read state ~mailbox ~label:"/play invites"
        ~call:(Masc_tui_http.list_play_invites ~expected_workspace)
        ~wrap:(fun result ->
          Play_msg (Play_invites_listed (Play_chat_list target,
            Result.bind result (fun json ->
              Result.map_error (fun detail -> Request_failed detail)
                (Tui_decode.decode_play_invites json)))))
  | Masc_tui_command.Play_link requested_name ->
      Masc_tui_message_input.clear state.msg_input;
      (* The cards carry names made safe to draw, so the name typed is
         compared in the same form. *)
      let requested_name =
        Option.map Masc.Tui_terminal_text.sanitize_terminal_text requested_name
      in
      (let card =
         match requested_name with
         | None -> Masc_tui_types.play_invite_latest state
         | Some name -> Masc_tui_types.play_invite_find state name
       in
       match card with
       | None ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             (match requested_name with
              | None -> "No play link has been issued in this TUI session"
              | Some name -> "No local play link for " ^ name)
       | Some card ->
           state.play_invite <-
             { state.play_invite with shown_name = Some (Masc_tui_play_card.name card) };
           state.play_invite_scroll <- 0)
  | Masc_tui_command.Play_invite { name; hours } ->
      if Masc_tui_collab_queue.Collab_play.launch_play_issue state ~mailbox ~sink:(Play_chat target) ~name ~hours then
        Masc_tui_message_input.clear state.msg_input
  | Masc_tui_command.Play_revoke name ->
      if Masc_tui_collab_queue.Collab_play.launch_play_revoke state ~mailbox ~sink:(Play_chat target) ~name then
        Masc_tui_message_input.clear state.msg_input
  | Masc_tui_command.Unknown word ->
      report_action state "error"
        (Printf.sprintf
           "unknown command /%s (text is sent as typed; /help lists commands)"
           word)
  | Masc_tui_command.Task_inspect ->
      (match (match keeper_name with Some _ as named -> named | None -> state.msg_target_keeper_name) with
       | None -> report_action state "error" "/task-inspect needs the original Keeper"
       | Some keeper ->
         Masc_tui_chat_dispatch.Task_dispatch.close_task_inspection_reader state;
         if open_task_creation_inspection state ~keeper then begin
           Masc_tui_message_input.clear state.msg_input;
           Masc_tui_chat_dispatch.Task_dispatch.launch_task_creation_read state ~mailbox
         end else report_action state "error" "No retained Task creation for this Keeper and confirmed original workspace")
  | Masc_tui_command.Task_recover ->
      (match (match keeper_name with Some _ as named -> named | None -> state.msg_target_keeper_name) with
       | None -> report_action state "error" "/task-recover needs the original Keeper"
       | Some keeper ->
         match recover_task_dispatch_input state ~keeper with
         | None -> report_action state "error" "No retained Task command for this Keeper/workspace"
         | Some request ->
           let detail = match Masc_tui_task_dispatch.progress request.tdr_dispatch with
             | Completed {outcome=(Not_sent _ | Kept_back _);_} -> "Original command restored; it has not been sent"
             | Completed {outcome=(Server_error _ | Unconfirmed _);_} ->
                 "Original command restored; inspect Tasks before repeating an unconfirmed creation"
             | Not_started | Reserved | Preparing | Sending | Completed {outcome=Created _;_} ->
                 "Original command restored" in
           report_action state "task" detail)
  | Masc_tui_command.Task_for_keeper { title; body } -> (
      let target =
        match keeper_name with
        | Some _ as named -> named
        | None -> state.msg_target_keeper_name
      in
      match target with
      | None -> report_action state "error" "/task needs a keeper to hand the work to"
      | Some keeper when not (keeper_available_for_new_message state keeper) ->
          report_action state "error"
            "/task cannot create: waiting for the current Keeper roster · command retained"
      | Some keeper ->
          Masc_tui_message_input.clear state.msg_input;
          report_action state "task"
            (Printf.sprintf "creating a task for %s: %s" keeper title);
          Masc_tui_chat_dispatch.Task_dispatch.launch_task_dispatch state ~mailbox ~keeper_name:keeper ~title ~body
            ~original:text)
(* This is a current reading, not a last-known cache. A failed probe makes
   the projection unread; every following refresh asks again, so a same-port
   replacement still moves A -> B as soon as /health succeeds. The local
   workspace follows the reading in the same step: a mismatch clears it, a
   match reloads it, so a screen never shows rows from a workspace the server
   just stopped serving. *)
let withdraw_keeper_workspace_presentation state ~previous ~keep_detail_navigation ~draft =
  state.keeper_list_focus <- None;
  state.keeper_list_folded <- [];
  state.keeper_list_seen_groups <- [];
  state.followed_from <- None;
  withdraw_usage_workspace state;
  withdraw_voice_capture state;
  (* Retire action authority immediately. A missing identity quarantines its
     cards; only a confirmed different workspace discards them. Old replies
     are independently rejected by Workspace_scoped. *)
  state.collab <- None;
  retire_machine_view ();
  Masc_tui_msx.close ~write:write_to_terminal state;
  msx_surface_frame := None;
  Masc_tui_types.withdraw_machine_control state;
  let current = workspace_input_identity_of_server state.server_identity in
  Masc_tui_types.withdraw_play_room_workspace state ~previous ~current;
  Masc_tui_types.withdraw_play_invite_workspace state ~previous ~current;
  state.play_invite_scroll <- 0;
  Masc_tui_types.withdraw_play_changes state;
  (* A decision receipt states what one workspace's Keeper answered; the
     next workspace's screens must not carry it. *)
  state.home_decision_receipt <- None;
  (* Keeper names are local to a workspace. Retire both the selected roster
     and its input request before another workspace can reuse the same name:
     Enter must select a newly read B health row, never A's retained row. The
     next workspace's fleet is owed, so a Memory or Metrics screen left empty
     reads it once that workspace can be read (RFC-0487). *)
  state.memory_input <- Masc_tui_fetched.clear state.memory_input;
  state.memory_input_owed <- Masc_tui_owed_read.settled;
  state.keeper_story_turns <- Masc_tui_fetched.clear state.keeper_story_turns;
  state.memory_activity <- Masc_tui_fetched.clear state.memory_activity;
  state.memory_facts_owed <- Masc_tui_owed_read.settled;
  state.memory_activity_owed <- Masc_tui_owed_read.settled;
  state.memory_changes_cursor <- 0;
  state.memory_return <- None;
  state.memory_page <- Memory_facts;
  state.keeper_story_turns_owed <- Masc_tui_owed_read.settled;
  state.memory_health <- None;
  state.memory_health_error <- None;
  state.memory_health_inflight <- false;
  state.memory_health_owed <- Masc_tui_owed_read.changed Masc_tui_owed_read.settled;
  state.memory_health_rows_owed <- [];
  state.memory_health_cursor <- 0;
  state.memory_health_scroll <- 0;
  (* The ledger and briefing belong to the workspace just left. *)
  state.memory_world <- Masc_tui_memory_world.clear state.memory_world;
  (* A Health line or harness read out under the old authority is refused
     when it answers, and only its answer released the slot. The new
     authority owes its own reads ([resume_reads_after_authority_change]). *)
  state.overview_inflight <- false;
  state.overview_owed <- Masc_tui_owed_read.settled;
  state.harness_inflight <- false;
  state.harness_owed <- Masc_tui_owed_read.settled;
  state.task_detail_id <- None;
  reset_task_detail_scroll state;
  withdraw_detail_histories state;
  state.task_focus <- Masc_tui_overview_tasks.No_task_focus;
  state.exact_activity_open <- None;
  state.exact_activity_sessions <- List.map Masc_tui_exact_activity.suspend state.exact_activity_sessions;
  state.machine_activity_open <- None;
  state.machine_activity_sessions <- List.map Masc_tui_machine_activity.suspend state.machine_activity_sessions;
  state.runtime_config_view <- None;
  state.runtime_config_observed_generation <- None;
  state.runtime_config_generation <- state.runtime_config_generation + 1;
  state.runtime_config_read <- `Idle;
  state.runtime_config_view_error <- None;
  withdraw_config_models state;
  state.runtime_config_jump_section <- None;
  state.runtime_config_status_open <- true;
  state.runtime_config_status_scroll <- 0;
  state.runtime_account_form <- None;
  state.memory_recall_form <- None;
  state.typesafeai_exclusion_form <- None;
  state.runtime_model_jump <- None;

  state.presets_snapshot <- None;
  state.presets_error <- None;
  state.presets_cursor <- 0;
  state.preset_detail <- Masc_tui_fetched.clear state.preset_detail;
  (* The facts browser reads a workspace's keepers. The key names a Keeper,
     so without this clear a held A read's late completion would still match
     B's pending request and populate B's browser with A's facts (#41163). *)
  if state.view = Memory && Option.is_some state.memory_facts_keeper then begin
    state.search <- None;
    state.search_last <- ""
  end;
  state.memory_facts <- Masc_tui_fetched.clear state.memory_facts;
  state.memory_facts_keeper <- None;
  state.memory_fact_detail_open <- false;
  state.memory_fact_detail_scroll <- 0;
  state.memory_facts_cursor <- 0;
  state.memory_facts_scroll <- 0;
  state.memory_fact_claim_wrap <- None;
  state.memory_facts_category <- Category_all;
  state.preset_save_draft <- None;
  state.preset_save_draft_description <- "";
  state.preset_save_draft_source <- Preset_form_local;
  state.preset_save_draft_workspace <- None;
  state.preset_armed <- None;
  state.preset_report <- None;
  state.preset_busy <- false;
  state.preset_save_copy_cursor <- 0;
  Masc_tui_types.withdraw_fusion_workspace state;
  Masc_tui_render_fusion.clear_fusion_trace_projection ();
  state.dos_live <- Masc_tui_machine_live.Unread;
  state.dos_activity <- [];
  state.msx_live_in_flight <- None;
  state.dos_live_in_flight <- None;
  state.board_vote_armed <- None;
  state.board_compose_armed <- false;
  state.board_compose_reply_to <- None;
  state.board_compose_attach_input <- None;
  state.board_write <- Board_idle;
  state.board_listing <- Masc_tui_fetched.Absent;
  state.board_list_reported_error <- None;
  state.board_census <- Masc_tui_fetched.Absent;
  state.board_detail <- Board_detail.clear state.board_detail;
  state.board_mode <- Board_list;
  state.goal_action_pending <- None;
  state.goal_action_errors <- [];
  state.goal_transition_latest <- [];
  state.goal_action_inflight <- [];
  state.planning <- None;
  state.planning_baseline <- None;
  state.planning_error <- None;
  state.planning_mode <- Planning_list;
  state.goal_confirmation <- Goal_confirmation.Inspecting Goal_confirmation_read.initial;
  state.goal_confirmation_identity_refresh <- None;
  state.goals_to_confirm <- Masc_tui_agenda.Not_read;
  state.standalone_lanes_generation <- state.standalone_lanes_generation + 1;
  state.lane_inventory <- None;
  state.lanes_selection <- None;
  state.lanes_cursor <- 0;
  state.lanes_scroll <- 0;
  state.standalone_lanes <- None;
  state.standalone_lanes_error <- None;
  state.standalone_lanes_inflight <- false;
  state.standalone_lanes_reread_pending <- false;
  state.runtime_surface_generation <- state.runtime_surface_generation + 1;
  state.runtime_surface_inflight <- None;
  state.runtime_surface_force_pending <- false;
  state.runtime_surface <- None;
  state.runtime_evidence <- None;
  state.runtime_surface_error <- None;
  state.runtime_detail_target <- None;
  state.runtime_lane_pick <- None;
  state.runtime_lane_name_draft <- None;
  state.runtime_lane_remove_armed <- None;
  state.runtime_lane_cursor_after_write <- None;
  state.runtime_lane_notice <- None;
  state.runtime_lane_write <- Lane_write_idle;
  state.slot_editor <- None;
  state.system_logs <- System_logs_view.clear_server state.system_logs;
  state.lane_addons_generation <- state.lane_addons_generation + 1;
  state.lane_addons <- None;
  state.lane_addons_cached <- Masc_tui_lane_addons.initial;
  state.lane_nested_read_resume <- None;
  withdraw_remote_image_reservations ();
  state.sent_image_read <- None;
  state.msg_copy_pending <- None;
  state.chat_command_reads <- [];
  reset_verification_rows state;
  state.verification <- None;
  state.verification_error <- None;
  state.verification_evidence <- Masc_tui_fetched.clear state.verification_evidence;
  state.verification_evidence_saved <- [];
  state.verification_evidence_request <- None;
  state.verification_inflight <- false;
  state.verification_refresh_after_inflight <- false;
  state.verification_owed <- Masc_tui_owed_read.settled;
  state.verification_offset <- 0;
  (* Tools callbacks use their own generation, independent of Keeper reads.
     Retire that owner before any same-named Keeper can appear on another root. *)
  state.tools_request_generation <- state.tools_request_generation + 1;
  state.tools_read_inflight <- None;
  state.tools_skill_generation <- state.tools_skill_generation + 1;
  state.tools_skill_pending <- [];
  state.tools_inventory <- None;
  state.tools_error <- None;
  state.tools_activations <- None;
  state.tools_activations_error <- None;
  state.tools_keeper_usage <- [];
  state.tools_catalog_owed <- Masc_tui_owed_read.settled;
  state.tools_inventory_owed <- Masc_tui_owed_read.settled;
  state.tools_inventory_keeper <- None;
  state.tools_activations_owed <- Masc_tui_owed_read.settled;
  state.tools_usage_owed <- [];
  state.skills_catalog <- None;
  state.skills_catalog_error <- None;
  state.tools_skill_source_picker <- None;
  state.tools_async_request_generation <- state.tools_async_request_generation + 1;
  state.tools_async_observation_inflight <- false;
  state.tools_async_observation <- None;
  state.tools_async_observation_error <- None;
  withdraw_tools_async_details state;
  state.tools_skill_evidence <- None;
  state.tools_evidence_reference <- None;
  state.tools_evidence_run_id <- None;
  state.browser_lane_read_resume <- None;
  state.tools_skill_cursor <- 0;
  state.tools_skill_focus <- Choosing_skill;
  tools_task_user_scroll state 0;
  state.msg_loaded_pages <- [];
  state.item_account <- None;
  state.item_account_error <- None;
  state.msg_journal_inflight <- [];
  state.msg_native_tasks <- [];
  state.msg_native_tasks_inflight <- [];
  state.msg_native_tasks_audit_pending <- [];
  state.msg_child_content <- [];
  state.msg_child_content_inflight <- [];
  state.msg_child_content_audit_pending <- [];
  state.msg_journal_wanted <- [];
  state.msg_journal_unavailable <- [];
  state.msg_journal_reads_refused <- false;
  (* Save the captured draft before releasing the spill. If an earlier
     withdrawal effect fails, the original composer still owns the paste. *)
  save_message_draft_snapshot ~workspace:previous state ~snapshot:draft;
  state.msg_spill <- None;
  Masc_tui_message_input.clear state.msg_input;
  (Masc_tui_message_input.invalidate_revision state.msg_input; state.msg_attachments <- []);
  (Masc_tui_message_input.invalidate_revision state.msg_input; state.msg_references <- []);
  state.msg_attachments_since <- None;
  Masc_tui_chat_input.Message_draft_recall.forget_recall state;
  Masc_tui_chat_input.Message_draft_recall.clear_keeper_history_projection state;
  Masc_tui_chat_input.Message_draft_recall.reset_message_file_changes state None;
  (* Submitted server work is not undone here. Unsent admissions and automatic
     continuations lose authorization at this boundary. *)
  if not (Chat_queue.is_empty state.msg_queued) then begin
    state.suspended_keeper_inputs <- (previous, suspend_keeper_input state) ::
      List.remove_assoc previous state.suspended_keeper_inputs;
    report_action state "system"
      "Workspace changed: unsent Keeper inputs retained for their original workspace; resume there to send"
  end;
  state.msg_queued <- Chat_queue.empty;
  Masc_tui_types.withdraw_keeper_chat_requests state;
  release_composer_for_browser_reader state;
  close_context_inspector state;
  state.context_inspector_generation <- state.context_inspector_generation + 1;
  state.context_inspector_keeper <- None;
  state.context_inspector_reading <- None;
  state.context_inspector_read_at <- None;
  state.context_inspector_loading <- false;
  (* Withdraw owners as well as callbacks: a stale completion must neither
     retain an old pending slot nor release a successor workspace's slot. *)
  state.keeper_waiting_read <- Keeper_waiting_read.clear state.keeper_waiting_read;
  state.keeper_turns_inflight <- false;
