   | Keepers Keeper_detail when keep_detail_navigation -> ()
   | Keepers (Keeper_message | Keeper_detail | Keeper_runtime_pick) ->
     transition_keeper_view state (Keepers Keeper_list);
     set_msg_scroll state 0
   | Keepers (Keeper_list | (Keeper_logs | Keeper_calls)) | Overview | Acting | Metrics | Memory
   | Lanes | Clients | Board | Approvals | Planning | Schedules | Verification | Harness | Fusion
   | Repositories | Code | Changes | Connectors | Runtime | Config | Resources | Tools | System_logs -> ())

(* Required metadata and optional work are separate jobs, slots and cache
   resources. Both retain the workspace observation cancellation owner. *)
let apply_confirmed_server_identity_reading state ~mailbox reading =
  let previous_server = state.server_identity in
  let previous_input_workspace = workspace_input_identity_of_server previous_server in
  (* A withdrawal invalidates outstanding roster reads even if the same
     workspace becomes ready again before those reads finish. *)
  if not (Masc_tui_refresh_settlement.Workspace_settlement.same_currency_workspace state.server_identity (Result.to_option reading))
  then Masc_tui_refresh_settlement.Workspace_settlement.withdraw_currency_authority state;
  let same_item_authority =
    match state.server_identity, reading with
    | Some previous, Ok current ->
        previous.Tui_decode.sid_state_ready <> Some false
        && current.Tui_decode.sid_state_ready <> Some false
        && Masc_tui_transport.Workspace_admission.same_server_workspace previous current
    | None, _ | Some _, Error _ -> false
  in
  if not same_item_authority then begin
    Masc_tui_types.remember_keeper_detail_focus state;
    Masc_tui_surface_requests.Keeper_surface_requests.withdraw_keeper_items state;
    Masc_tui_refresh_settlement.Workspace_settlement.revoke_detail_readings state
  end;
  Masc_tui_types.reconcile_detail_intent_origins state reading;
  let previous = state.workspace_identity in
  let chat_workspace = chat_input_workspace state in
  Masc_tui_types.store_server_identity_reading state reading;
  state.workspace_identity <-
    Masc_tui_types.workspace_identity_of_refresh
      ~local_paths:state.local_workspace_paths reading;
  if state.workspace_identity <> Workspace_identity_match then begin
    state.goal_action_pending <- None;
    (* Withdraw decision authority even when this refresh did not ask for
       Home. A later matching Metrics read cannot revive foreign/stale tokens. *)
    let reason = "workspace identity is unverified; decisions require a fresh matching read" in
    Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_approvals_load state (Error (Request_failed reason));
    state.board_listing <- Masc_tui_fetched.Failed reason;
    state.board_list_reported_error <- None;
    state.board_census <- Masc_tui_fetched.Absent;
    state.board_detail <- Board_detail.clear state.board_detail;
    state.board_vote_armed <- None;
    state.keeper_roster <- Keeper_control.unobserved_roster;
    state.keeper_roster_error <- Some reason;
    state.msg_history_load_generation <- state.msg_history_load_generation + 1;
    state.msg_history_inflight <- None;
    state.keeper_tool_approvals <- [];
    state.keeper_tool_approvals_observed <- false;
    state.keeper_tool_approvals_error <- Some reason;
    state.keeper_tool_approvals_read <- Snapshot_read.invalidate state.keeper_tool_approvals_read;
    state.gate_pending <- [];
    state.gate_modes <- None;
    state.gate_rules <- [];
    state.gate_queue_unavailable <- Some reason;
    state.gate_rules_unavailable <- Some reason;
    state.gate_error <- Some reason;
    state.gate_snapshot_observed <- false;
    state.gate_snapshot_authority <- None;
    state.gate_snapshot_read <- Snapshot_read.invalidate state.gate_snapshot_read;
    state.asks_snapshot <- None;
    Masc_tui_frame_timing.note_asks_application Masc_tui_frame_timing.Reset;
    Masc_tui_types.retire_asks_read state;
    Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_asks_load state (Error reason);
    Masc_tui_refresh_settlement.Http_dataset_settlement.apply_planning_load state (Error reason);
    Masc_tui_refresh_settlement.Http_dataset_settlement.apply_overview_goals_load state (Error reason);
    state.goals_to_confirm <- Masc_tui_agenda.Not_read;
    (match state.goal_confirmation with
     | Goal_confirmation.Inspecting read ->
         state.goal_confirmation <- Goal_confirmation.Inspecting
           (Goal_confirmation_read.clear read)
     | Goal_confirmation.Submitting _ -> ())
  end;
  let same_workspace =
    Masc_tui_types.server_workspace_matches ~expected:previous_server reading
    && match previous, state.workspace_identity with
    | (Workspace_identity_match | Workspace_identity_match_unconfirmed _)
    , Workspace_identity_match -> true
    | Workspace_identity_mismatch prior, Workspace_identity_mismatch current ->
      String.equal prior.server_base_path current.server_base_path
    | (Workspace_identity_match | Workspace_identity_match_unconfirmed _)
    , (Workspace_identity_unread | Workspace_identity_match_unconfirmed _
      | Workspace_identity_mismatch _)
    | Workspace_identity_mismatch _
    , (Workspace_identity_unread | Workspace_identity_match
      | Workspace_identity_match_unconfirmed _)
    | Workspace_identity_unread
    , (Workspace_identity_unread | Workspace_identity_match
      | Workspace_identity_match_unconfirmed _ | Workspace_identity_mismatch _) -> false
  in
  if not same_workspace then begin
    (* Recover local input before cancellation drops its preflight owner.
       Streaming/reconciling owners may have reached the server. *)
    Masc_tui_types.retain_preflight_inputs state state.msg_inflight;
    Masc_tui_surface_requests.Keeper_surface_requests.withdraw_keeper_items state;
    let Workspace_authority generation = state.workspace_authority in
    state.workspace_authority <- Workspace_authority (generation + 1);
    let cancellations = state.workspace_cancellations in
    state.workspace_cancellations <- [];
    List.iter (fun (_, cancel) -> cancel ()) cancellations;
    state.keeper_action_pending <- None;
    (* A failed local reload may retain only rows from that same authority. *)
    state.keepers <- [];
    state.keepers_error <- None;
    (* An identity that only went unread is not another workspace: the open
       chat, its draft, queue and focus stay, so the operator's typing keeps
       going to the composer instead of the Keeper list's keys (x deletes).
       It comes back to the same workspace's Match, or is put away with the
       rest when the identity reads as another workspace. *)
    let preserve_chat =
      state.view = Keepers Keeper_message
      && Option.is_some state.msg_target_keeper_name
      && match chat_workspace, state.workspace_identity with
         | Some _, (Workspace_identity_unread | Workspace_identity_match_unconfirmed _) -> true
         | Some origin, Workspace_identity_match ->
             Some origin = workspace_input_identity_of_server state.server_identity
         | None, _ | Some _, Workspace_identity_mismatch _ -> false
    in
    let target = state.msg_target_keeper_name in
    let draft = Masc_tui_message_input.snapshot state.msg_input in
    let spill = message_spill_in_snapshot state draft in
    let attachments = state.msg_attachments and references = state.msg_references in
    let since = state.msg_attachments_since and queue = state.msg_queued in
    let recall_walk = state.msg_recall_walk in
    let focused = state.composer_focused in
    let retained = retained_input_markers queue state.keeper_interactive_waiting in
    let withdrawn_workspace = match state.msg_unconfirmed_workspace with
      | Some _ -> chat_workspace
      | None -> previous_input_workspace
    in
    let keep_detail_navigation =
      match previous, state.workspace_identity with
      | Workspace_identity_unread, _ | _, Workspace_identity_unread -> true
      | ( Workspace_identity_match | Workspace_identity_match_unconfirmed _
        | Workspace_identity_mismatch _ )
      , ( Workspace_identity_match | Workspace_identity_match_unconfirmed _
        | Workspace_identity_mismatch _ ) -> false
    in
    (* Keep a name through initial confirmation or a temporary loss of its
       original workspace, but never carry an A-owned name into B. An
       unbound name still requires an explicit workspace confirmation. *)
    let current_preset_workspace = workspace_input_identity_of_server state.server_identity in
    let preserved_preset_draft =
      match state.preset_save_draft, state.preset_save_draft_workspace,
            current_preset_workspace with
      | None, _, _ -> None
      | Some draft, Some origin, Some current when origin <> current ->
        let held = { psd_name = draft; psd_description = state.preset_save_draft_description
                   ; psd_source = state.preset_save_draft_source } in
        state.preset_save_suspended_drafts <- (origin, held) :: state.preset_save_suspended_drafts;
        None
      | Some draft, origin, _ ->
        Some ({ psd_name = draft; psd_description = state.preset_save_draft_description
              ; psd_source = state.preset_save_draft_source }, origin)
    in
    withdraw_keeper_workspace_presentation state ~previous:withdrawn_workspace
      ~keep_detail_navigation ~draft;
    let restore_preset_draft = match preserved_preset_draft, current_preset_workspace with
      | Some _ as kept, _ -> kept
      | None, None -> None
      | None, Some workspace ->
        (match List.assoc_opt workspace state.preset_save_suspended_drafts with
         | None -> None
         | Some draft ->
           state.preset_save_suspended_drafts <-
             List.remove_assoc workspace state.preset_save_suspended_drafts;
           Some (draft, Some workspace)) in
    Option.iter (fun (draft, origin) ->
      state.preset_save_draft <- Some draft.psd_name;
      state.preset_save_draft_description <- draft.psd_description;
      state.preset_save_draft_source <- draft.psd_source;
      state.preset_save_draft_workspace <- origin) restore_preset_draft;
    if preserve_chat then begin
      retarget_message state target;
      state.view <- Keepers Keeper_message;
      state.composer_focused <- focused;
      Masc_tui_message_input.clear state.msg_input;
      Masc_tui_message_input.insert state.msg_input
        (expand_message_draft_spill spill (Masc_tui_message_input.snapshot_text draft));
      (Masc_tui_message_input.invalidate_revision state.msg_input; state.msg_attachments <- attachments);
      (Masc_tui_message_input.invalidate_revision state.msg_input; state.msg_references <- references);
      state.msg_attachments_since <- since;
      state.msg_recall_walk <- recall_walk;
      state.msg_queued <- queue;
      state.keeper_interactive_waiting <- retained;
      List.iter (fun (item : Chat_queue.item) ->
        Masc_tui_chat_dispatch.Chat_watching.append_user_history_once ~submitted_at:item.submitted_at state item.request)
        (Chat_queue.waiting queue);
      (* The presentation withdrawal suspended this chat's input for its
         workspace; it is back on screen, so it is not suspended twice. *)
      state.suspended_keeper_inputs <- List.remove_assoc withdrawn_workspace
        state.suspended_keeper_inputs;
      state.msg_unconfirmed_workspace <-
        (match state.workspace_identity with
         | Workspace_identity_unread | Workspace_identity_match_unconfirmed _ -> chat_workspace
         | Workspace_identity_match | Workspace_identity_mismatch _ -> None)
    end else state.msg_unconfirmed_workspace <- None
  end;
  match state.workspace_identity with
  | Masc_tui_types.Workspace_identity_mismatch _ ->
    let same_remote = same_workspace in
    clear_local_workspace ~keep_keeper_rows:same_remote state;
    clear_keeper_logs state;
    if not same_remote then begin
      state.keeper_roster <- Keeper_control.unobserved_roster;
      state.keeper_roster_error <- None
    end
  | Masc_tui_types.Workspace_identity_match ->
    (* The same workspace read as a match again leaves the keeper rows and
       tasks as the cadence tick last loaded them, a refresh ago. A reload
       here ran the whole directory read on the UI thread a second time for
       the same answer. A workspace that just changed, or one that was not
       a match a moment ago, has had its rows put away above and needs it. *)
    (match previous with
     | Masc_tui_types.Workspace_identity_match when same_workspace -> ()
     | Masc_tui_types.Workspace_identity_match
     | Masc_tui_types.Workspace_identity_unread
     | Masc_tui_types.Workspace_identity_match_unconfirmed _
     | Masc_tui_types.Workspace_identity_mismatch _ ->
         state.local_workspace <- Local_workspace_unread;
         state.local_keepers <- Local_workspace_unread;
         Masc_tui_transport.Local_sources.launch_workspace_read state ~mailbox ~intent:Snapshot_read.Join state.local_base_path);
    let input_workspace = workspace_input_identity_of_server state.server_identity in
    (match List.assoc_opt input_workspace state.suspended_keeper_inputs with
     | None -> ()
     | Some held ->
       state.suspended_keeper_inputs <- List.remove_assoc input_workspace
         state.suspended_keeper_inputs;
       restore_suspended_keeper_input state held;
       List.iter (fun (item : Chat_queue.item) ->
         Masc_tui_chat_dispatch.Chat_watching.append_user_history_once ~submitted_at:item.submitted_at state item.request)
         (Chat_queue.waiting state.msg_queued);
       report_action state "system"
         "Retained inputs restored for this workspace; resume a Keeper to send them")
  | Masc_tui_types.Workspace_identity_unread ->
    state.item_account_error <- Some "Server workspace identity is unavailable";
    clear_local_workspace state;
    state.keeper_roster <- Keeper_control.unobserved_roster;
    clear_keeper_logs state
  | Masc_tui_types.Workspace_identity_match_unconfirmed _ ->
    (* [workspace_identity_of_refresh] answers only the three confirmed
       readings; [apply_server_identity_reading] keeps an unconfirmed match
       before this function runs. *)
    ()

(* The selected Goal id belongs to the Planning detail, regardless of whether
   the latest Goal snapshot has arrived. *)
let selected_planning_goal_id (state : state) =
  match state.view with
  | Planning ->
      (match state.planning_mode with
       | Planning_list -> None
       | Planning_detail goal_id -> Some goal_id)
  | Overview | Acting | Metrics | Keepers _ | Memory | Lanes | Clients | Board
  | Approvals | Schedules | Verification | Harness | Fusion | Repositories
  | Code | Changes | Connectors | Runtime | Config | Resources | Tools
  | System_logs -> None

(* A read that cannot say which workspace the server serves keeps the last
   match unconfirmed ([Masc_tui_types.next_workspace_identity]). The confirmed
   identity and everything it authorized stay; the state is no longer
   [Workspace_identity_match], so decisions and new reads wait for a read that
   matches again. Only a read that names a workspace goes on to compare it. *)
let apply_server_identity_reading ?(withdraw_on_error = false) state ~mailbox reading =
  withdraw_resource_diagram_pending state;
  let previous_identity = state.server_identity in
  let previous_instance = Option.bind state.server_identity (fun identity -> identity.Tui_decode.sid_runtime_instance_id) in
  (match
    (match reading with
     | Error _ when withdraw_on_error -> Workspace_identity_unread
     | Ok _ | Error _ ->
         Masc_tui_types.next_workspace_identity ~previous:state.workspace_identity
           ~local_paths:state.local_workspace_paths reading)
  with
  | Workspace_identity_match_unconfirmed _ as unconfirmed ->
    state.workspace_identity <- unconfirmed;
    suspend_workspace_readings state;
    settle_retired_sent_image state;
    Masc_tui_chat_dispatch.Chat_journals.settle_retired_chat_copy state;
    Masc_tui_collab_queue.Keeper_queue.settle_retired_queue_inspections state;
    Masc_tui_surface_requests.Prompt_preset_requests.settle_retired_chat_command_reads state
  | Workspace_identity_unread | Workspace_identity_match
  | Workspace_identity_mismatch _ as next ->
    (match state.workspace_identity, next with
     | Workspace_identity_match_unconfirmed _, Workspace_identity_match ->
       (* A detail read answered while the identity was unconfirmed was
          dropped. Retiring the receipts still in flight makes the move back
          visible to [resume_reads_after_authority_change], which reads the
          open detail again; the screen keeps what it shows meanwhile. *)
       state.detail_reads <- [];
       state.detail_read_authority <- ref ()
     | ( Workspace_identity_unread | Workspace_identity_match
       | Workspace_identity_match_unconfirmed _ | Workspace_identity_mismatch _ ), _ -> ());
    apply_confirmed_server_identity_reading state ~mailbox reading);
  let current_instance = Option.bind state.server_identity (fun identity -> identity.Tui_decode.sid_runtime_instance_id) in
  if previous_instance <> current_instance then begin
    state.goal_candle <- Masc_tui_fetched.clear state.goal_candle;
    state.goal_confirmation_presented <- None;
    let confirmation_key = (match state.goal_confirmation with
     | Goal_confirmation.Inspecting read ->
       state.goal_confirmation <- Goal_confirmation.Inspecting (Goal_confirmation.suspend_confirmation_read read);
       Goal_confirmation_read.current_key read
     | Goal_confirmation.Submitting _ -> None) in
    state.goal_confirmation_identity_refresh <-
      (match confirmation_key, previous_identity with
       | Some goal_id, Some identity ->
           Some (goal_id, Goal_confirmation.confirmation_workspace_of_identity identity)
       | (None, _ | _, None) -> None);
    match selected_planning_goal_id state with
    | Some goal_id when server_authority_ready state ->
      Masc_tui_work_requests.Tools_task_requests.launch_goal_candle_load state ~mailbox goal_id
    | Some _ | None -> ()
  end

let apply_refused_workspace_identity state ~mailbox ~detail latest =
  withdraw_resource_diagram_pending state;
  let reading = retire_refused_workspace_readings state ~detail latest in
  apply_server_identity_reading state ~mailbox reading

(* Scoped navigation reads carry the final identity of their verified interval.
   A successful older full refresh cannot authorize a same-port replacement. *)
let apply_http_scoped_surfaces state ~mailbox ~currency_authority results =
  if Http_refresh_order.is_current state.http_refresh_order results.http_refresh_ticket then begin
    let admission = Masc_tui_types.collector_admission state results.http_surface_request
      results.http_scoped_server_identity in
    let datasets = take_http_surface_datasets state results.http_surface_request in
    (* Older collectors can still own independent data. Their older probe
       cannot replace identity observed by a newer collector. *)
    (match admission with
     | Admit_identity_and_data | Admit_identity_only ->
         Masc_tui_refresh_settlement.Http_dataset_settlement.note_server_health state ~answered:Masc_tui_refresh_pace.answered_again
           results.http_scoped_server_identity;
         apply_server_identity_reading state ~mailbox results.http_scoped_server_identity
     | Admit_data_only | Admit_nothing -> ());
    match admission with
    | Admit_identity_and_data | Admit_data_only ->
      (* Identity application can withdraw authority even when this response
         has the current ticket. Only the dispatch generation and workspace
         together authorize its roster; other datasets retain their ticket. *)
      let same_workspace =
        currency_authority.car_generation = state.candle_authority_generation
        && Masc_tui_refresh_settlement.Workspace_settlement.same_currency_workspace currency_authority.car_identity state.server_identity
      in
      let results = if same_workspace then results
        else { results with http_keeper_roster = None } in
      Masc_tui_refresh_settlement.Http_dataset_settlement.apply_http_scoped_data ~before_view_change:(fun () -> retire_remote_image_for_navigation state) state ~datasets results
    | Admit_identity_only | Admit_nothing -> false
  end else false

let resume_authorized_input_after_refresh state ~was_unavailable ~base_path ~mailbox =
  if was_unavailable
     && state.workspace_identity = Workspace_identity_match
     && Option.is_none state.keepers_error then begin
    Chat_queue.waiting state.msg_queued
    |> List.map (fun (item : Chat_queue.item) -> item.request.keeper_name)
    |> List.sort_uniq String.compare
    |> List.iter (fun keeper_name ->
         Masc_tui_chat_dispatch.Queue_steer.launch_waiting_keeper_input state ~mailbox ~keeper_name);
    state.keeper_run_next_ready
    |> List.map (fun (request : Keeper_chat.request) -> request.keeper_name)
    |> List.sort_uniq String.compare
    |> List.iter (Masc_tui_chat_dispatch.Queue_steer.dispatch_ready_run_next state ~mailbox);
    Option.iter (fun panel -> Masc_tui_collab_queue.Keeper_queue.refresh_queue_after_priority state ~mailbox ~keeper_name:panel.qp_keeper)
      state.queue_panel;
    Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox
  end

(* A scoped refresh the guard stopped settles as a failed one does; only its
   words differ: the kept-back notice alone, never the read's failure
   (RFC §2). *)
let apply_http_scoped_refresh_failure state ~mailbox ~refresh_ticket ~approval_ticket ~latest failure =
  if Http_refresh_order.is_current state.http_refresh_order refresh_ticket then begin
    let err = request_failure_text ~ko:(state.ui_language = Lang_ko)
        ~request:Kept_request.Surface_read failure in
    (* The last [/health] reading its probes took, the probe's own answer
       whatever stopped the refresh after it. *)
    Option.iter
      (Masc_tui_refresh_settlement.Http_dataset_settlement.note_server_health state ~answered:Masc_tui_refresh_pace.answered_again) latest;
    apply_refused_workspace_identity state ~mailbox ~detail:err latest;
    Option.iter
      (fun ao_ticket ->
         if Masc_tui_refresh_settlement.Approvals_asks_settlement.admit_approval_listing state ao_ticket then
           Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_approvals_read state (Error failure))
      approval_ticket;
    add_event state "error" err
  end

(* A refresh pass settled, and its [/health] probe read [identity]. *)
let note_refresh_settled state identity =
  Masc_tui_refresh_settlement.Http_dataset_settlement.note_read state Masc_tui_read_failure.Refresh_pass (Ok ());
  Masc_tui_refresh_settlement.Http_dataset_settlement.note_server_health state ~answered:Masc_tui_refresh_pace.pass_answered identity

let apply_http_surfaces state ~mailbox results =
  if Http_refresh_order.is_current state.http_refresh_order
       results.http_scoped.http_refresh_ticket then begin
  note_refresh_settled state results.http_server_identity;
  let previous_items = Masc_tui_surface_requests.Keeper_surface_requests.visible_item_revision state in
  let request = results.http_scoped.http_surface_request in
  (* Navigation joins this pass's ticket while it runs, so the ticket alone
     cannot tell whether a newer collector already read the identity. *)
  let admission = Masc_tui_types.collector_admission state request results.http_server_identity in
  let datasets = take_http_surface_datasets state request in
  (match admission with
   | Admit_identity_and_data | Admit_identity_only ->
       apply_server_identity_reading state ~mailbox results.http_server_identity
   | Admit_data_only | Admit_nothing -> ());
  let roster_refreshed = match admission with
    | Admit_identity_and_data | Admit_data_only ->
        if state.workspace_identity = Workspace_identity_match then
          Option.iter (Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_approval_answer_observation state) results.http_approvals;
        Masc_tui_refresh_settlement.Http_dataset_settlement.apply_http_scoped_data ~before_view_change:(fun () -> retire_remote_image_for_navigation state) state ~datasets results.http_scoped
    | Admit_identity_only | Admit_nothing -> false in
  if roster_refreshed || Option.is_none results.http_scoped.http_keeper_roster then
    Masc_tui_surface_requests.Keeper_surface_requests.refresh_changed_keeper_items state ~mailbox ~roster_refreshed previous_items;
  let reached result =
    Result.map (fun _ -> ()) result |> Result.map_error (fun _ -> ())
  in
  let reached_if_asked result = Option.map reached result |> Option.to_list in
  (* Identity is server contact too: failed surface reads must not report
     the process offline when the workspace probe just answered. Only the
     surfaces actually requested contribute their outcomes. *)
  state.connection_status <-
    Masc_tui_types.connection_status_of_refresh
      ~identity:(reached results.http_server_identity)
      ~surfaces:(reached_if_asked (Option.map (fun receipt -> receipt.bpr_result) results.http_scoped.http_board)
       @ reached_if_asked results.http_scoped.http_planning
       @ (Option.map
            (fun observation -> reached observation.ao_result)
            results.http_approvals
          |> Option.to_list))
  end

let apply_server_booting state ~mailbox ~refresh_ticket ~identity ~approval_ticket =
  if Http_refresh_order.is_current state.http_refresh_order refresh_ticket then begin
  note_refresh_settled state identity;
  (* The identity is read the same way a full refresh reads it, so a same-port
     replacement is noticed even while the new process is still booting. No
     surface was asked. The approvals panel is told why its rows are stale,
     as a failed refresh tells it; nothing else changes. *)
  apply_server_identity_reading state ~mailbox identity;
  Masc_tui_refresh_settlement.Http_dataset_settlement.apply_keeper_roster_load ~before_view_change:(fun () -> retire_remote_image_for_navigation state) state
    (Error (Keeper_control.Roster_unreachable "server booting"));
  Option.iter
    (fun ao_ticket ->
       Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_approval_observation state
         { ao_ticket; ao_result = Error "server booting" })
    approval_ticket;
  state.connection_status <- Masc_tui_types.Booting
  end

(* The account server of a multi-account installation serves no workspace,
   and nothing but the probe was asked. The readings in flight are retired as
   for a refused workspace, so a read cut off here says so; then the identity
   is withdrawn, since there is no workspace to wait for. The approvals
   panel, the roster and Candle are told why. *)
let account_server_reason =
  "the address answers as the account server of a multi-account installation, which serves no workspace"

let apply_account_server ~server_contact state ~mailbox ~refresh_ticket ~version ~approval_ticket =
  if Http_refresh_order.is_current state.http_refresh_order refresh_ticket then begin
  (* The probe answered; what answered is the account server. *)
  note_refresh_settled state (Ok ());
  (* The footer's last notice was said on the screen this one covers, such
     as the settings this server could not answer at start. *)
  (match state.connection_status with
   | Masc_tui_types.Account_server _ -> ()
   | Disconnected | Connecting | Booting | Degraded | Connected -> set_last_action state None);
  apply_refused_workspace_identity state ~mailbox ~detail:account_server_reason None;
  apply_server_identity_reading ~withdraw_on_error:true state ~mailbox (Error account_server_reason);
  Masc_tui_transport.Server_contact.spend_auto_start server_contact;
  state.candle_observation <- Some (Error account_server_reason);
  Masc_tui_refresh_settlement.Http_dataset_settlement.apply_keeper_roster_load ~before_view_change:(fun () -> retire_remote_image_for_navigation state) state
    (Error (Keeper_control.Roster_unreachable account_server_reason));
  Option.iter
    (fun ao_ticket ->
       Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_approval_observation state
         { ao_ticket; ao_result = Error account_server_reason })
    approval_ticket;
  state.connection_status <- Masc_tui_types.Account_server { version }
  end

let apply_workspace_unconfirmed state ~mailbox ~detail ~unreachable ~approval_ticket ~latest_identity =
  note_refresh_settled state latest_identity;
  apply_refused_workspace_identity state ~mailbox ~detail (Some latest_identity);
  (* The Candle surface says why it has no reading rather than looking
     unread. *)
  state.candle_observation <- Some (Error detail);
  Option.iter (fun ao_ticket ->
    Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_approval_observation state {ao_ticket; ao_result = Error detail}) approval_ticket;
  state.connection_status <-
    (if unreachable then Masc_tui_types.Disconnected else Masc_tui_types.Degraded);
  add_event state "error" detail

let apply_http_refresh_outcome ~server_contact state ~mailbox = function
  | Refresh_workspace_unconfirmed
      { refresh_ticket; detail; unreachable; approval_ticket; latest_identity } ->
    if Http_refresh_order.is_current state.http_refresh_order refresh_ticket then
      apply_workspace_unconfirmed state ~mailbox ~detail ~unreachable ~approval_ticket ~latest_identity
  | Refresh_surfaces results -> apply_http_surfaces state ~mailbox results
  | Refresh_server_booting { refresh_ticket; identity; approval_ticket } ->
    apply_server_booting state ~mailbox ~refresh_ticket ~identity ~approval_ticket
  | Refresh_account_server { refresh_ticket; version; approval_ticket } ->
    apply_account_server ~server_contact state ~mailbox ~refresh_ticket ~version ~approval_ticket

(* Preserve the existing physical metrics window, shared by every entry path. *)
let keeper_log_window = 200

let log_keeper_log_read ~phase request ~outcome =
  let key = Masc_tui_fetched.request_key request.klr_request in
  Log.Transport.info "tui_keeper_logs=%s" (Yojson.Safe.to_string (`Assoc [
    "phase", `String phase; "keeper", `String key.klk_keeper;
    "base_path", `String key.klk_base_path;
    "request", `Intlit (Int64.to_string (Masc_tui_fetched.request_id request.klr_request));
    "started_ns", `Intlit (Int64.to_string request.klr_started_ns);
    "observed_ns", `Intlit (Int64.to_string (Mtime_clock.elapsed_ns ()));
    "outcome", `String outcome ]))

(* The logs view and the Info tab read the selected Keeper's metrics when they
   open or [r] asks, when [keeper_metrics_appended] names the Keeper, on a
   revalidation, and again after a failed read (RFC-0480 §3.1). *)
let current_logs_owed state ~keeper_name =
  match state.keeper_logs_owed with
  | Some owed
    when String.equal owed.klgo_keeper keeper_name
         && owed.klgo_reading == state.workspace_read_authority ->
      Some owed
  | Some _ | None -> None

let update_logs_owed state ~keeper_name transition =
  let owed =
    match current_logs_owed state ~keeper_name with
    | Some owed -> owed
    | None ->
        { klgo_keeper = keeper_name
        ; klgo_reading = state.workspace_read_authority
        ; klgo_read = Masc_tui_owed_read.settled }
  in
  state.keeper_logs_owed <- Some { owed with klgo_read = transition owed.klgo_read }

let settle_logs_owed state ~keeper_name transition =
  match current_logs_owed state ~keeper_name with
  | Some owed ->
      state.keeper_logs_owed <- Some { owed with klgo_read = transition owed.klgo_read }
  | None -> ()

let launch_keeper_log_read state ~mailbox ~intent keeper =
  match begin_keeper_log_read state ~intent ~limit:keeper_log_window
      ~started_ns:(Mtime_clock.elapsed_ns ()) keeper with
  | None -> false
  | Some request ->
      update_logs_owed state ~keeper_name:keeper.k_name Masc_tui_owed_read.started;
      let key = Masc_tui_fetched.request_key request.klr_request in
      let superseded, supersede = Eio.Promise.create () in
      supersede_keeper_log_read state
        (Some (request.klr_owner, fun () -> ignore (Eio.Promise.try_resolve supersede ())));
      let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
      let deliver result = enqueue_async mailbox (Keeper_msg (Keeper_logs_loaded (request, result))) in
      log_keeper_log_read ~phase:"started" request ~outcome:"pending";
      let run () = Fun.protect
        ~finally:(fun () -> finish_keeper_log_read state request)
        (fun () -> Eio.Fiber.first
          (fun () ->
            let result = try Domain_pool_ref.submit_io_or_inline ~name:__FUNCTION__ (fun () ->
                Metrics_tail.load_keeper ~base_path:key.klk_base_path
                  ~keeper_name:key.klk_keeper ~limit:key.klk_limit)
              with
              | Eio.Cancel.Cancelled _ as exn -> raise exn
              | exn -> Error (Printexc.to_string exn) in
            log_keeper_log_read ~phase:"read_completed" request
              ~outcome:(match result with Ok _ -> "received" | Error _ -> "failed");
            finish_keeper_log_read state request;
            deliver result)
          (fun () ->
            Eio.Promise.await superseded;
            log_keeper_log_read ~phase:"superseded" request ~outcome:"cancel_requested")) in
      (match Eio_context.get_switch_opt () with
       | None ->
           finish_keeper_log_read state request;
           deliver (Error "Eio switch is unavailable for Keeper metrics reading")
       | Some sw ->
           (match Masc_tui_transport.Workspace_admission.fork_job ~observation:true state ~mailbox ~sw run with
            | () -> ()
            | exception (Eio.Cancel.Cancelled _ as exn) -> raise exn
            | exception exn ->
                finish_keeper_log_read state request;
                deliver (Error (Printexc.to_string exn))));
      true

(* The logs view and the Terminal tab follow a Keeper's Execute output over its
   stream, so a row reaches the screen when the server logs it. The job owns
   the connection and the reader, and posts the reader's view to the mailbox;
   the render fiber owns all state. Retriable failures back off; a permanent
   refusal stops until the view is reopened. *)

(* The reader is posted at most this often. A command that prints faster draws
   every row all the same; they arrive together. *)
let keeper_execute_stream_post_interval_s = 0.05

(* The job ends when the workspace withdraws it, [stop] is called, a permanent
   refusal occurs, or an exception is reported as the stream going down. An
   ended job stays registered until the view is left, so a bug does not turn
   into a reconnect loop; leaving the view and coming back opens a new one. *)
let launch_keeper_execute_stream state ~mailbox ~expected_workspace ~key =
  let stream =
    { kxf_key = key; kxf_reading = state.workspace_read_authority; kxf_owner = ref () } in
  let stopped, stop = Eio.Promise.create () in
  state.keeper_execute_stream <-
    Some (stream, fun () -> ignore (Eio.Promise.try_resolve stop ()));
  (match Masc_tui_fetched.refresh ~equal:keeper_log_equal_key state.keeper_execute_output ~key with
   | Masc_tui_fetched.Started (next, _) -> state.keeper_execute_output <- next
   | Masc_tui_fetched.Already_loading -> ());
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  let deliver event = enqueue_async mailbox (Keeper_msg (Keeper_execute_streamed (stream, event))) in
  (* The fiber that launches the job is also the only one that drains the
     mailbox, so a job that cannot start is reported to the state directly:
     queueing it could wait on a full mailbox that only this fiber empties. *)
  let report_unstarted detail =
    ignore (take_keeper_execute_stream state stream
      (Execute_stream_down (Execute_stream_stopped { reason = Unexpected_error; detail })) : bool) in
  let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
  let run () =
    match Eio_context.get_clock_opt () with
    | None -> deliver (Execute_stream_down (Execute_stream_stopped
        { reason = Unexpected_error; detail = "Eio clock is unavailable" }))
    | Some clock ->
        Masc_tui_execute_stream_job.run ~clock
          ~reconnect_s:keeper_execute_stream_reconnect_s
          ~max_reconnect_s:keeper_execute_stream_max_reconnect_s
          ~stable_s:Server_routes_http_routes_dashboard.execute_output_heartbeat_s
          ~monotonic_now:(fun () -> Int64.to_float (Mtime_clock.elapsed_ns ()) /. 1e9)
          ~post_interval_s:keeper_execute_stream_post_interval_s
          ~reader:(Masc_tui_execute_stream.create ~keeper:key.klk_keeper ~capacity:key.klk_limit)
          ~observe:(fun ~on_chunk ->
            match
              Masc_tui_http.observe_execute_output_stream ~clock ~expected_workspace ~host ~port
                ~keeper:key.klk_keeper ~on_chunk
            with
            | Ok () -> Ok ()
            | Error (Masc_tui_http.Execute_http_refused { status; detail }) ->
              Error (Masc_tui_execute_stream_job.Http_refusal { status; detail })
            | Error (Masc_tui_http.Execute_unattested { status; detail }) ->
              Error (Masc_tui_execute_stream_job.Unattested { status; detail })
            | Error (Masc_tui_http.Execute_invalid_response { status; detail }) ->
              Error (Masc_tui_execute_stream_job.Invalid_response { status; detail })
            | Error (Masc_tui_http.Execute_transport_failed detail) ->
              Error (Masc_tui_execute_stream_job.Transport_failure detail))
          ~on_view:(fun view ->
            Option.iter
              (fun (reading, observed_at) ->
                 deliver (Execute_stream_reading (reading, observed_at)))
              (keeper_execute_reading_of_stream ~now:(Eio.Time.now clock) view))
          ~on_ended:(fun ending ->
            let failure = match ending with
              | Masc_tui_execute_stream_job.Retry_after { detail; _ } -> Execute_stream_retrying detail
              | Reopen_required { reason; detail } -> Execute_stream_stopped { reason; detail } in
            let detail = keeper_execute_failure_detail failure in
            Log.Transport.warn "tui_execute_stream_ended keeper=%s detail=%s" key.klk_keeper detail;
            deliver (Execute_stream_down failure))
  in
  match Eio_context.get_switch_opt () with
  | None -> report_unstarted "Eio switch is unavailable"
  | Some sw ->
      (match
         Masc_tui_transport.Workspace_admission.fork_job ~observation:true state ~mailbox ~sw (fun () ->
           try Eio.Fiber.first run (fun () -> Eio.Promise.await stopped) with
           | Eio.Cancel.Cancelled _ as exn -> raise exn
           | exn -> deliver (Execute_stream_down (Execute_stream_stopped
               { reason = Unexpected_error; detail = Printexc.to_string exn })))
       with
       | () -> ()
       | exception (Eio.Cancel.Cancelled _ as exn) -> raise exn
       | exception exn -> report_unstarted (Printexc.to_string exn))

(* Keep the stream running for what the logs view or the Terminal tab shows:
   one for the Keeper under the cursor while either is on screen, none
   otherwise. True when this changed what is running, so the screen is
   redrawn. *)
let reconcile_keeper_execute_stream state ~mailbox =
  match plan_keeper_execute_stream state, state.server_identity with
  | Stream_stays, _ -> false
  | Stream_ends, _ -> stop_keeper_execute_stream state
  | Stream_follows key, Some expected_workspace ->
      ignore (stop_keeper_execute_stream state : bool);
      launch_keeper_execute_stream state ~mailbox ~expected_workspace ~key;
      true
  | Stream_follows _, None -> stop_keeper_execute_stream state

(* The Keeper's metrics. Its Execute output arrives over the stream that
   [reconcile_keeper_logs] opens. *)
let launch_current_keeper_logs state ~mailbox ~intent =
  match keeper_log_target state with
  | Some keeper -> launch_keeper_log_read state ~mailbox ~intent keeper
  | None -> false

(* Runs on every loop iteration; it reads only the Keeper on screen whose
   read is due, once no metrics read is in flight. *)
let launch_owed_keeper_logs state ~mailbox =
  match state.keeper_logs_owed with
  | None ->
      (match keeper_log_target state, state.workspace_identity with
       | Some _, Workspace_identity_match ->
           let reading = Masc_tui_fetched.in_flight state.keeper_logs in
           let read =
             if reading then state.keeper_log_owed
             else Masc_tui_owed_read.abandoned state.keeper_log_owed
           in
           state.keeper_log_owed <- read;
           if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read && not reading then begin
             state.keeper_log_owed <- Masc_tui_owed_read.started read;
             ignore (launch_current_keeper_logs state ~mailbox ~intent:Snapshot_read.Refresh)
           end
       | None, (Workspace_identity_match | Workspace_identity_unread | Workspace_identity_mismatch _
               | Workspace_identity_match_unconfirmed _)
       | Some _, (Workspace_identity_unread | Workspace_identity_mismatch _
                 | Workspace_identity_match_unconfirmed _) ->
           state.keeper_log_owed <- Masc_tui_owed_read.settled)
  | Some owed ->
      if owed.klgo_reading != state.workspace_read_authority
      then state.keeper_logs_owed <- None
      else if
        Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) owed.klgo_read
        && Option.is_none state.keeper_log_cancel
        && (match state.workspace_identity with
            | Workspace_identity_match -> true
            | Workspace_identity_unread | Workspace_identity_mismatch _
            | Workspace_identity_match_unconfirmed _ -> false)
      then
        match keeper_log_target state with
        | Some keeper when String.equal keeper.k_name owed.klgo_keeper ->
            ignore (launch_keeper_log_read state ~mailbox ~intent:Snapshot_read.Join keeper)
        | Some _ | None -> ()

let owe_keeper_logs_read state ~mailbox ~keeper_name =
  update_logs_owed state ~keeper_name Masc_tui_owed_read.changed;
  launch_owed_keeper_logs state ~mailbox

let reconcile_keeper_logs state ~mailbox =
  (* Leaving the Terminal tab, or moving to another Keeper, ends what it held
     still. Coming back opens on the newest output again. *)
  Masc_tui_types.reconcile_keeper_terminal state;
  let metrics = match keeper_log_target state, state.workspace_identity with
  | Some keeper, Workspace_identity_match ->
      let key = keeper_log_key state ~limit:keeper_log_window keeper in
      (match state.keeper_log_read with
       | Some request when request.klr_reading == state.workspace_read_authority
           && keeper_log_equal_key key (Masc_tui_fetched.request_key request.klr_request) -> false
       | Some _ | None -> launch_keeper_log_read state ~mailbox ~intent:Snapshot_read.Join keeper)
  | (Some _ | None), (Workspace_identity_unread | Workspace_identity_mismatch _
      | Workspace_identity_match_unconfirmed _ | Workspace_identity_match) ->
      let held = Option.is_some state.keeper_log_read in
      if held then suspend_keeper_logs state;
      held in
  let stream = reconcile_keeper_execute_stream state ~mailbox in
  metrics || stream
;;

(* What a detail tab reads on the way in, for the Keeper it is opened on.
   Three entry paths -- Enter from the roster, a cursor move with a tab held
   open, and [ / ] between tabs -- each carried a copy of this table, and the
   copies drifted: Automation's copy fetched the fleet list instead of the
   Keeper's schedules until a comment said to mirror the other, and Secrets
   fetched nothing in all three. One table, called from all three. *)
let launch_detail_tab_reading state ~mailbox (keeper : keeper) =
  match state.detail_tab with
  | Detail_info ->
      (* Runtime Stats reads the composite snapshot. Entry and explicit [r]
         both request a current reading, including after a failed refresh;
         the shared launcher retains its single-flight and authority guards. *)
      owe_keeper_composite_read state ~mailbox ~keeper_name:keeper.k_name;
      Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_board_quarantines state ~mailbox keeper.k_name;
      Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_efficiency state ~mailbox
  | Detail_items ->
      Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_items state ~mailbox keeper.k_name
  | Detail_sandbox ->
      state.keeper_sandbox_view <- None;
      Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_sandbox_view state ~mailbox keeper.k_name;
      (* Container logs that were open for this Keeper come back with the
         status they hang under. *)
      let logs_were_open =
        match state.keeper_sandbox_logs, state.keeper_sandbox_logs_error with
        | Some (stamp, _), _ | _, Some (stamp, _) ->
            String.equal stamp keeper.k_name
        | None, None -> Option.equal String.equal state.keeper_sandbox_logs_requested (Some keeper.k_name)
      in
      if logs_were_open then Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_sandbox_logs state ~mailbox keeper.k_name
  | Detail_instructions ->
      state.keeper_config_view <- None;
      state.keeper_config_view_error <- None;
      Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_config_view state ~mailbox keeper.k_name
  | Detail_secrets ->
      (* The projection arrives with the Keeper's composite body. A reading
         taken before the operator went back to the list can be arbitrarily
         old: entry and [r] ask for a current one, as Info does. *)
      owe_keeper_composite_read state ~mailbox ~keeper_name:keeper.k_name
  | Detail_github ->
      state.github_identity_view <- None;
      state.github_identity_view_error <- None;
      Masc_tui_identity_requests.launch_github_view state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state mailbox) keeper.k_name
  | Detail_identity ->
      state.identity_view <- None;
      state.identity_view_error <- None;
      (* The tab opens at the top of its own list rather than at whichever
         row the last Keeper's was left on. *)
      state.identity_cursor <- 0;
      state.identity_attempt_error <- None;
      state.identity_filter <- None;
      Masc_tui_identity_requests.launch_view state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state mailbox) keeper.k_name
  | Detail_channels ->
      owe_connectors_read state;
      Masc_tui_surface_requests.Connector_volume_requests.launch_connectors_load state ~mailbox
  | Detail_automation ->
      (* This Keeper's schedules (state.keeper_schedules, what the tab reads),
         not the fleet list. *)
      (match state.keeper_schedules with
       | Some (name, _) when String.equal name keeper.k_name -> ()
       | Some _ | None -> state.keeper_schedules <- None);
      state.keeper_schedules_error <- None;
      Masc_tui_work_requests.Schedule_call_requests.launch_keeper_schedules_load state ~mailbox ~keeper_name:keeper.k_name
  | Detail_runs ->
      launch_fusion_runs_load ~demand:Masc_tui_fusion_updates.After_change state ~mailbox
  | Detail_terminal ->
      (* The tab follows the Keeper's output over a stream that
         [reconcile_keeper_logs] opens on the next pass of the loop. *)
      ()
;;

(* Authority loss revokes every detail ticket. Resume the pane's current
   reading once authority returns; ordinary roster ticks retain its request. *)
let refresh_visible_detail_after_authority_recovery state ~mailbox ~previous_authority =
  let restored_focus = Masc_tui_types.restore_keeper_detail_focus state in
  if (restored_focus || previous_authority != state.detail_read_authority)
     && server_authority_ready state then begin
    if state.connector_unbind_offer_pending <> [] then Masc_tui_surface_requests.Connector_volume_requests.launch_connectors_load state ~mailbox;
    match state.view, state.detail_tab, selected_keeper state with
    | Keepers Keeper_detail, Detail_items, _ -> ()
    | Keepers Keeper_detail, Detail_identity, Some keeper ->
        (* Recovery refreshes the reading without applying tab-entry resets
           to the operator's filter, cursor or pending attempt diagnostic. *)
        Masc_tui_identity_requests.launch_view state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
          ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state mailbox) keeper.k_name
    | Keepers Keeper_detail, _, Some keeper ->
        launch_detail_tab_reading state ~mailbox keeper
    | Connectors, _, _ -> Masc_tui_surface_requests.Connector_volume_requests.launch_connectors_load state ~mailbox
    (* Fusion's list and nested detail resume together with the surface read
       below. A second change demand here would queue a duplicate reread. *)
    | Fusion, _, _ -> ()
    | (Keepers (Keeper_detail), (Detail_info | (Detail_sandbox | (Detail_instructions | (Detail_secrets | (Detail_github | (Detail_identity | (Detail_channels | (Detail_automation | (Detail_runs | Detail_terminal))))))))), None)
    | (Keepers (Keeper_list | (Keeper_logs | (Keeper_calls | (Keeper_message | Keeper_runtime_pick)))), _, _)
    | ((Overview | (Acting | (Metrics | (Memory | (Lanes | (Clients | (Board | (Approvals | (Planning | (Schedules | (Verification | (Harness | (Repositories | (Code | (Changes | (Runtime | (Config | (Resources | (Tools | System_logs))))))))))))))))))), _, _) -> ()
  end
;;

let current_surface_needs state =
  let needs =
    Masc_tui_types.surface_needs ~about_open:state.about_open
      ~keeper_pane_drawn:(not (Masc_tui_render.acting_pane_suppressed state)) state.view in
  (* Calls is a section of Usage, not a surface, and the Dashboard's line
     shares its series, so what is drawn asks here: opening either reads the
     series, leaving both stops reading. *)
  { needs with needs_tool_series = Masc_tui_types.tool_series_drawn state }

(* The reads a full refresh tick sends beside its surface bundle. They go out
   while the bundle is still on the wire, so a bundle that moves the read
   authority withdraws them; [resume_reads_after_authority_change] sends
   them again from this same list. *)
let launch_owed_ask_followup state ~mailbox =
  match Masc_tui_types.ask_followup_target state with
  | None -> state.ask_followup_owed <- Masc_tui_owed_read.settled
  | Some _ ->
      if state.view = Approvals && server_authority_ready state
         && Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) state.ask_followup_owed
      then Masc_tui_operator_actions.Ask_actions.launch_ask_followup_load state ~mailbox

let launch_tick_side_reads state ~mailbox ~(needs : Masc_tui_types.surface_needs) =
  if server_authority_ready state then begin
  Masc_tui_operator_actions.Ask_actions.launch_ask_followup_load state ~mailbox;
  end
;;


(* Entering a Keeper detail tab, by [ / ] or by a press on its name in the
   title strip: one way in, so a press reads what the key reads. The scroll
   belonged to the tab being left. *)
let enter_keeper_detail_tab state ~mailbox tab =
  state.detail_tab <- tab;
  state.detail_scroll <- 0;
  if tab = Detail_items then begin
    state.item_cursor <- 0;
    state.item_filter <- Masc_tui_keeper_items.All;
    state.item_preview <- true
  end;
  match selected_keeper state with
  | Some keeper -> launch_detail_tab_reading state ~mailbox keeper
  | None -> ()
;;

(* Entering a Config pane, by [p] or by a press on its name in the title
   strip. Everything below is what arriving at a pane asks for; the key and
   the press differ only in which pane they name. *)
let enter_config_pane state ~mailbox pane =
  state.runtime_model_jump <- None;
  state.runtime_config_jump_section <- None;
  let arriving = not (runtime_config_on_screen state) in
  state.config_pane <- pane;
  if pane = Config_runtime then state.runtime_config_status_open <- false;
  (* Moving between panes stays inside the Config view, so
     [launch_surface_reads] never sees it. Arriving on a pane that draws
     runtime.toml owes it a read here instead. *)
  if arriving && runtime_config_on_screen state then owe_runtime_config_read state;
  state.prompts_cursor <- 0;
  state.config_scroll <- 0;
  state.runtime_config_cursor <- 0;
  state.runtime_params_cursor <- 0;
  state.runtime_param_edit <- None;
  state.runtime_params_notice <- None;
  state.prompts_librarian_input_requested <- None;
  state.prompts_librarian_input <- None;
  state.prompts_librarian_input_error <- None;
  state.prompts_librarian_input_loading <- false;
  (* Cycling into a pane is entering it. Without this the params pane
     draws whatever the last load left, which for a first visit is an
     empty list -- and empty reads as "nothing registered". *)
  (* Leaving the themes pane ends the preview the same way Esc does.
     A scheme the reader never picked must not follow them out. *)
  cancel_theme_preview state;
  match state.config_pane with
  | Config_prompts ->
    (* [start] answers Already_loading for a read in flight, so the
       launcher is the one that decides whether to ask. *)
    Masc_tui_surface_requests.Prompt_preset_requests.launch_prompts_load state ~mailbox
  | Config_presets ->
    state.presets_cursor <- 0;
    state.preset_armed <- None;
    (match state.preset_save_draft, workspace_input_identity_of_server state.server_identity with
     | None, Some workspace ->
       (match List.assoc_opt workspace state.preset_save_suspended_drafts with
        | Some draft ->
          state.preset_save_draft <- Some draft.psd_name;
          state.preset_save_draft_description <- draft.psd_description;
          state.preset_save_draft_source <- draft.psd_source;
          state.preset_save_draft_workspace <- Some workspace;
          state.preset_save_suspended_drafts <-
            List.remove_assoc workspace state.preset_save_suspended_drafts
        | None -> ())
     | Some _, _ | None, None -> ());
    if state.presets_snapshot = None
    then Masc_tui_surface_requests.Prompt_preset_requests.launch_presets_load state ~mailbox
  | Config_params -> Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_params_load state ~mailbox
  (* Same first-visit load as the prompts pane. The models table is
     a projection of runtime.toml, so entering it without the file
     would draw "(loading)" with nothing on the way. *)
  | Config_models ->
    if state.runtime_config_view = None
    then Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_config_load state ~mailbox
  | Config_runtime ->
    set_runtime_config_cursor_near state ~direction:1 ~target:0
  (* Re-read rather than move a cursor: this pane has no rows, and
     what an operator wants from it after starting a local server is
     a fresh answer. *)
  | Config_voice -> Masc_tui_work_requests.Voice_requests.launch_voice_config_load state ~mailbox
  | Config_themes -> ()
;;

(* The entries of the in-screen strips. Each is what the strip's key does on
   arrival, shared with a press on the entry's name. *)
let enter_metrics_section state section =
  state.metrics_section <- section;
  reset_metrics_scroll state
;;

(* The scroll belonged to the list that just went away. Carrying it into a
   shorter section opens it part-way down for no reason the reader gave. *)
let enter_tools_pane state pane =
  if pane <> Tools_async then Masc_tui_work_requests.Tools_task_requests.close_tools_async_detail state;
  Masc_tui_list_moves.show_tools_pane state pane;
  tools_task_user_scroll state 0;
  (* From the top, unless the selection a list kept is further down. *)
  follow_tools_selection state;
  (* Opening the Usage pane reads the catalog and every Keeper's usage once,
     and the Activations pane the selected Keeper's ledger (RFC-0483 §4.3).
     The inventory is read on its pushes on every pane but Async, so opening
     Surface or Catalog owes it nothing; a push that came during Async is
     still owed. *)
  match pane with
  | Tools_usage ->
      owe_tools_catalog_read state;
      owe_every_skill_usage_read state
  | Tools_activations -> owe_tools_activations_read state
  (* The cleanup results change with the server's passes, which push
     nothing, so opening the pane reads the envelope again. *)
  | Tools_storage -> owe_tools_inventory_read state
  | Tools_surface | Tools_async
  | Tools_catalog (Tools_catalog_list | Tools_catalog_volumes _) -> ()
;;

(* The cursor restarts because the row under it belongs to the listing being
   replaced. *)
let enter_memory_category state category =
  state.memory_facts_category <- category;
  state.memory_facts_cursor <- 0;
  state.memory_facts_scroll <- 0
;;

(* Lanes and All runtimes are two readings of the Runtime surface, and the
   Standalone lanes surface names both in its strip. Selection and scroll
   belong to the list being left. *)
let enter_runtime_mode state ~mailbox mode =
  if mode <> state.runtime_mode then begin
    (match state.runtime_mode with
     | Masc_tui_types.Runtime_lanes ->
         Masc_tui_types.dismiss_runtime_lane_notice state
     | Masc_tui_types.Runtime_all -> ());
    state.runtime_mode <- mode;
    state.runtime_cursor <- 0;
    state.runtime_surface_scroll <- 0
  end;
  if state.view <> Runtime then goto_surface state ~mailbox Runtime
;;

(* The third stop of the same strip: the standalone service lanes, off the
   ring. The Runtime surface is left on its lane view, which [p] there
   returns to. *)
let enter_standalone_lanes state ~mailbox =
  state.runtime_mode <- Masc_tui_types.Runtime_lanes;
  state.runtime_cursor <- 0;
  state.runtime_surface_scroll <- 0;
  goto_surface state ~mailbox Lanes
;;

let refresh_keeper_detail_selection state ~mailbox =
  state.keeper_run_cursor <- 0;
  match selected_keeper state with
  | None -> ()
  | Some keeper ->
      launch_detail_tab_reading state ~mailbox keeper
;;

let open_keeper_detail state ~mailbox (keeper : keeper) =
  withdraw_resource_diagram_pending state;
  state.detail_focus_recovery <- None;
  state.keeper_run_cursor <- 0;
  state.view <- Keepers Keeper_detail;
  select_keeper_name state keeper.k_name;
  state.keeper_detail_focus <- Right_pane;
  state.detail_scroll <- 0;
  ignore (launch_current_keeper_logs state ~mailbox ~intent:Snapshot_read.Join);
  (* A sticky non-Info tab re-reads for the keeper the cursor now names;
     without this the pane shows "(loading)" forever after a cursor move,
     because the stamped answer names the previous keeper. *)
  launch_detail_tab_reading state ~mailbox keeper
;;

(* What a key does to the Story window under the Keepers list. With no Keeper
   under the cursor -- a group heading, a list with no Keeper -- the window
   leaves Enter and Right to the list. Esc first cancels a settings editor that
   is being prepared: that is the innermost intent it can cancel, and it would
   open the editor behind a window that had just closed. *)
let keeper_story_action state key =
  if String.equal key "esc" && Option.is_some state.keeper_settings_intent then None
  else
    Masc_tui_keeper_story.action_of_key
      ~selection:(match keeper_list_stop state with
        | Some Masc_tui_keeper_list_model.Stop_world -> Masc_tui_keeper_story.World_selected
        | Some (Masc_tui_keeper_list_model.Stop_row _) -> Masc_tui_keeper_story.Keeper_selected
        | Some (Masc_tui_keeper_list_model.Stop_heading _) | None -> Masc_tui_keeper_story.No_selection)
      state.keeper_story key
;;

(* World selects its own row before opening; it never borrows the Keeper
   that was under the cursor. Only [Open_detail] leaves the list. *)
let apply_keeper_story_action state ~mailbox = function
  | Masc_tui_keeper_story.Show page -> state.keeper_story <- Some page
  | Masc_tui_keeper_story.Open_memory destination ->
      (match selected_keeper state with
       | None -> ()
       | Some keeper ->
         let origin = {mr_keeper=keeper.k_name; mr_search=state.search; mr_search_last=state.search_last} in
         state.memory_fact_detail_open <- false;
         state.memory_fact_detail_scroll <- 0;
         state.memory_fact_claim_wrap <- None;
         goto_surface state ~mailbox Memory;
         state.memory_return <- Some origin;
         state.search <- None;
         state.search_last <- "";
         state.memory_facts_keeper <- Some keeper.k_name;
         state.memory_facts_category <- Category_all;
         state.memory_facts_cursor <- 0;
         state.memory_facts_scroll <- 0;
         state.memory_changes_cursor <- 0;
         (match destination with
          | Masc_tui_keeper_story.Memory_recent ->
              state.memory_page <- Memory_facts; state.memory_facts_sort <- Sort_recency
          | Masc_tui_keeper_story.Memory_frequent ->
              state.memory_page <- Memory_facts; state.memory_facts_sort <- Sort_retrieved_count
          | Masc_tui_keeper_story.Memory_changes -> state.memory_page <- Memory_changes
          | Masc_tui_keeper_story.Memory_storage ->
              state.memory_page <- Memory_facts;
              state.memory_facts_keeper <- None;
              let rec index i = function
                | [] -> None
                | (row : Masc.Tui_decode_memory_health.memory_keeper_health) :: rest ->
                    if String.equal row.mkh_keeper_id keeper.k_name then Some i else index (i + 1) rest in
              (match index 0 (visible_memory_keepers state) with
               | Some cursor -> state.memory_health_cursor <- cursor
               | None -> report_action state "info" (keeper.k_name ^ ": memory health not observed; showing the fleet storage view")) ))
  | Masc_tui_keeper_story.Close -> state.keeper_story <- None
  | Masc_tui_keeper_story.Open_world -> open_keeper_world state
  | Masc_tui_keeper_story.Open_detail ->
      state.keeper_story <- None;
      Option.iter (open_keeper_detail state ~mailbox) (selected_keeper state)
;;

(* The answer receipt of an installation's question leads to that
   installation's Results, where its reveal row appears (RFC operator-quiz K6).
   The live worker is found in a fresh inventory read, not in the last one:
   a worker the cached snapshot names may since have been replaced. The jump
   travels with that read and ends with it. *)
(* Opens one installation's Results: Approvals [g] after an answer, and the
   palette's per-installation entries. *)
let open_installation_results state ~mailbox declaration_id =
  let module Addons = Masc_tui_lane_addons in
  let view = Option.value ~default:state.lane_addons_cached state.lane_addons in
  if view.loading then
    report_action state "system" "A Lane request is pending; open the Results again when it finishes"
  else begin
    state.lane_addons <- Some {view with screen=Addons.Overview};
    Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons ~target:(Addons.Read_installation_results declaration_id)
      state ~mailbox Addons.Inspect
  end

let open_answered_installation_results state ~mailbox =
  match Option.map (fun (feedback : Masc_tui_ask_projection.answer_feedback) -> feedback.af_asker)
          (current_ask_answer_feedback state) with
  | Some (Masc.Tui_decode_asks.Ask_installation { ai_declaration_id; _ }) ->
      open_installation_results state ~mailbox ai_declaration_id
  | Some (Masc.Tui_decode_asks.Ask_keeper _) | None ->
      report_action state "system" "The last answer was not to an installation"

let open_lane_inventory_selection state ~mailbox =
  let module Inventory = Masc.Tui_decode_lane_inventory in
  let module Addons = Masc_tui_lane_addons in
  let open_addon open_view =
    let view = Option.value ~default:state.lane_addons_cached state.lane_addons in
    if view.loading then
      state.lane_addons <- Some {view with scroll=0;
        error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure "A Lane request is pending; the current draft and request are retained"}
    else open_view view in
  match selected_inventory_lane state with
  | None -> show_lanes_action_error state "Read the Lane inventory before opening a row"
  | Some row ->
      state.lanes_action_error <- None;
      match row.Inventory.selection with
      | Inventory.Exact _ ->
          (match selected_standalone_lane state with
           | Some lane ->
               let identity = Standalone_lane.run_identity lane.sl_lane in
               if Lane_run_identity.keeps_run_records identity
               then open_lane_run_list state ~mailbox identity
               else show_lanes_action_error state "This Lane keeps no run records"
           | None -> show_lanes_action_error state "The exact Lane detail is absent from this inventory; r reads again")
      | Browser lane ->
          show_browser_lane state;
          state.browser_lane <- Option.map (fun view ->
            if view.Browser_lane_view.source = lane
               && (match view.selection with Bound_automatic | Bound_explicit -> true
                   | Unbound | Live_unbound -> false) then view
            else Browser_lane_view.switch_source lane view) state.browser_lane;
          release_composer_for_browser_reader state;
          Masc_tui_surface_requests.Lane_browser_requests.refresh_browser_lane state ~mailbox
      | Machine Masc.Machine_lane.Msx -> open_msx_spectator state ~mailbox
      | Machine Masc.Machine_lane.Dos -> open_dos_screen state ~mailbox
      | Declaration path -> open_addon (fun view ->
          let view = Addons.open_declaration view path in
          state.lane_addons <- Some view;
          (* Reopen a local draft before issuing another read. Enter inspects;
             E is the explicit external-editor action, s is the only save. *)
          match Masc_tui_lane_declaration.find_for_path ~path view.documents with
          | Ok (Some draft) -> state.lane_addons <- Some (Addons.put_document view draft)
          | Ok None -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_declaration state ~mailbox ~edit:false
              (Masc_tui_lane_declaration.Read path)
          | Error detail -> state.lane_addons <- Some {view with document_key=None;
              error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail})
      | Manual_instance {instance_id;incarnation} -> open_addon (fun view ->
          state.lane_addons <- Some { (Addons.set_presentation view Addons.Summary) with screen=Addons.Detail (instance_id,incarnation);
            focus=Addons.Timeline; row_cursor = -1; scroll=0; selected=[];
            document_key=None; error=None};
          (* Inspect first even for a retained worker: its identity must exist
             in the fresh snapshot before a history slice can join it. *)
          Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons ~target:(Addons.Read_detail (instance_id,incarnation))
            state ~mailbox Addons.Inspect)

(* What a press on marked text does: the same move the key for that place
   makes. A press on the tab or pane already open does nothing -- it is where
   the reader already is, and re-entering would reset its scroll and cursor. A
   ring entry pressed from a surface of its family (Metrics under Overview,
   a Keeper's chat under Keepers) goes to the entry's own surface. *)

(* Apply a UI language pick and store it in the runtime.toml boot reads back
   from, so the choice survives a restart. Said in the language just picked,
   including the failure: the new language is already on the screen by then,
   so silence would let the screen stand as proof it was kept. *)
let invalidate_language_cached_views state =
  state.keeper_config_view <- None;
  state.keeper_config_view_error <- None;
  state.detail_reads <-
    List.filter (fun request -> request.drr_tab <> Detail_instructions) state.detail_reads;
  let ko = state.ui_language = Lang_ko in
  List.iter
    (fun (view : Masc_tui_account_login.t) -> view.ko <- ko)
    (Option.to_list state.account_login @ state.account_login_detached);
  state.chat_call_reader <-
    Option.map
      (fun (origin, reader) -> (origin, Masc_tui_chat_call_reader.set_language ~ko reader))
      state.chat_call_reader

let refresh_keeper_config_view_if_open state ~mailbox =
  if state.view = Keepers Keeper_detail && state.detail_tab = Detail_instructions then
    Option.iter
      (fun (keeper : keeper) ->
        Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_config_view
          state ~mailbox keeper.k_name)
      (selected_keeper state)

let apply_ui_language state ~mailbox lang =
  let changed = state.ui_language <> lang in
  state.ui_language <- lang;
  if changed then begin
    invalidate_language_cached_views state;
    refresh_keeper_config_view_if_open state ~mailbox
  end;
  report_action state "info"
    (ui_text state
       ~ko:("UI 언어: " ^ ui_language_label lang)
       ~en:("UI language: " ^ ui_language_label lang));
  Masc_tui_shell.Preferences.store state (Masc.Tui_preference.Language_chosen lang)

(* The view and its density are saved together, the way [v] and [V] save
   them. *)
let save_keeper_view_preference state =
  let preference = keeper_view_preference state in
  ignore (Masc_tui_config.submit_keeper_preference state.keeper_preference_writer
    ~on_request_id:(fun request_id -> note_keeper_preference_submission state ~request_id preference)
    ~sw:(Eio_context.get_switch_opt ()) ~base_path:state.local_base_path preference)

let press_marked_target state ~mailbox (target : press_target) =
  match target with
  | Press_input_rejection _ | Press_quit_confirmation _ | Press_notice_fragment _ -> ()
  | Press_surface surface ->
      if surface <> state.view then goto_surface state ~mailbox surface
  | Press_ring_edge Ring_before -> cycle_surface state ~mailbox ~backwards:true
  | Press_ring_edge Ring_after -> cycle_surface state ~mailbox ~backwards:false
  | Press_keeper_tab tab ->
      if tab <> state.detail_tab then enter_keeper_detail_tab state ~mailbox tab
  | Press_config_pane pane ->
      if pane <> state.config_pane then enter_config_pane state ~mailbox pane
  | Press_metrics_section section ->
      if section <> state.metrics_section then enter_metrics_section state section
  | Press_tools_pane pane ->
      if pane <> state.tools_pane then enter_tools_pane state pane
  | Press_memory_category category ->
      if category <> state.memory_facts_category then
        enter_memory_category state category
  | Press_theme_filter filter ->
      if filter <> state.theme_filter then enter_theme_filter state filter
  | Press_ui_language ->
      apply_ui_language state ~mailbox (next_ui_language state.ui_language)
  | Press_runtime_mode mode ->
      if (state.view <> Runtime || Option.is_none (Masc_tui_types.runtime_parent state))
         && (mode <> state.runtime_mode || state.view <> Runtime) then
        enter_runtime_mode state ~mailbox mode
  | Press_standalone_lanes ->
      if state.view <> Lanes then enter_standalone_lanes state ~mailbox
  | Press_usage_calls ->
      (* [m] then [V]: Usage, on the section the pressed line summarises. *)
      state.usage_section <- Usage_calls;
      state.usage_telemetry_open <- false;
      reset_metrics_scroll state;
      if state.view <> Metrics then goto_surface state ~mailbox Metrics
  | Press_context_tab tab ->
      if tab <> state.context_inspector_tab then
        enter_context_inspector_tab state tab
  | Press_queue_selected presented ->
      let terminal_rows, _ = get_terminal_size () in
      let panel = match Masc_tui_render.frame_choice state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) with
       | `Queue panel -> Some panel
       | `Play_card _ -> Masc_tui_render.queue_below_play state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ())
       | `Surface | `Too_small _ | `Account_login _ | `Account_server _ | `Palette
       | `Collab _ | `Lane_addons _ | `Detail_reading _ | `About | `Context
       | `Keeper_deletions | `Help | `Agenda | `Answering | `Link
       | `Client_detail _ -> None in
      (match panel with
       | Some panel ->
         (match resolve_queue_selection ~require_action_ready:false ~state ~panel
                  ~items:(queue_panel_items state panel) presented with
          | Some id -> update_queue_panel state ~keeper_name:panel.qp_keeper (fun panel ->
              {panel with qp_detail=Some id; qp_detail_scroll=0})
          | None -> ())
       | None -> ())
  (* The row is found by name in the roster as it is now. A first press
     chooses it and a press on the chosen row opens it, as Enter does; a
     Keeper that left the roster after the frame was drawn is not pressed. *)
  | Press_chat_call (authority,reading,keeper_name,execution_id) ->
      if authority=state.workspace_authority && reading==state.workspace_read_authority then
        Masc_tui_work_requests.Schedule_call_requests.open_chat_call_reader ~execution_id state ~mailbox keeper_name
  | Press_lane_row target ->
      if state.view = Lanes && state.lanes_mode = Lanes_overview
          && Option.is_none state.slot_editor then
        (match Masc_tui_lane_inventory.identity_index target (lane_inventory_rows state) with
         | None -> ()
         | Some _ when Option.is_some (Option.bind (selected_inventory_lane state) (fun row ->
               Masc_tui_lane_inventory.find_identity target [row])) ->
             open_lane_inventory_selection state ~mailbox
         | Some index -> Option.iter (fun list -> list.rl_place index) (row_list state))
  | Press_keeper_world ->
      if state.view = Keepers Keeper_list
         && Masc_tui_keeper_list_model.has_world state.keeper_list_view then
        if keeper_list_stop state = Some Masc_tui_keeper_list_model.Stop_world then
          Option.iter (apply_keeper_story_action state ~mailbox)
            (Masc_tui_keeper_story.action_of_key ~selection:Masc_tui_keeper_story.World_selected
               state.keeper_story "\r")
        else place_keeper_list_stop state Masc_tui_keeper_list_model.Stop_world
  | Press_keeper_row name -> (
      match keeper_index state name with
      (* A press read against a list frame after a key in the same burst
         left the list (Enter opened a Keeper) is not the list's any more. *)
      | Some _ when state.view <> Keepers Keeper_list -> ()
      | None -> ()
      (* On a heading the cursor rests on its group's first row, and a press
         there chooses that row rather than opening it. A press on the Keeper
         the cursor is on is Enter on it, which opens the window, and on an
         open window it is Right, which opens the detail: a press is the
         pointer's only way to either. *)
      | Some index when keeper_list_stop state = Some (Masc_tui_keeper_list_model.Stop_row index) ->
          let key = if Option.is_some state.keeper_story then "right" else "\r" in
          Option.iter (apply_keeper_story_action state ~mailbox)
            (Masc_tui_keeper_story.action_of_key ~selection:Masc_tui_keeper_story.Keeper_selected state.keeper_story key)
      | Some _ -> keeper_list_select_name state name)
  | Press_keeper_view view ->
      if state.view = Keepers Keeper_list && view <> state.keeper_list_view then begin
        set_keeper_list_view state view;
        save_keeper_view_preference state
      end
;;

(* A failed Fusion read is retried with the streams' reconnect backoff; a
   change re-reads on [fusion_run_status] (RFC-0480 L2b). *)
let settle_fusion_retry state reading result =
  Masc_tui_fusion_updates.settle_retry state reading
    ~failure:(match result with
      | Ok _ -> None
      | Error _ ->
          Some (Masc_tui_owed_read.failed ~retry_s:Masc_tui_transport.Event_streams.stream_reconnect_s
                  ~max_retry_s:keeper_execute_stream_max_reconnect_s
                  ~now:(Masc_tui_wake.Mono.now ())))

(* Resolve the saved opening only after an owned roster observation. An
   operator navigation made during startup still takes precedence. *)
let resolve_opening_chat state ~base_path ~mailbox =
  if state.opening_pending
     && state.local_keepers = Local_workspace_read
     && state.workspace_identity = Masc_tui_types.Workspace_identity_match then begin
    state.opening_pending <- false;
    if state.view = Overview then
      let requested = match state.opening_mode with
        | Masc_tui_config.Overview | Masc_tui_config.Last None -> None
        | Masc_tui_config.Last (Some name) | Masc_tui_config.Keeper name ->
            Some (Keeper_id.Keeper_name.to_string name) in
      match requested with
      | None -> ()
      | Some keeper_name ->
          if Option.is_some state.keepers_error then
            state.opening_notice <-
              Some "Could not open chat (Keeper list unavailable). Showing Dashboard."
          else if not (List.exists
              (fun (keeper : Tui_decode.keeper) -> String.equal keeper.k_name keeper_name)
              state.keepers) then
            state.opening_notice <- Some
              ("Could not open chat with " ^ keeper_name
               ^ " (Keeper not found). Showing Dashboard.")
          else begin
            retire_remote_image_for_navigation state;
            Masc_tui_chat_input.Message_draft_recall.open_message_for_keeper ~remember_home_chat:false
              ~return_to:Keeper_chat_return_list state keeper_name
              ~drain_queue:(fun () -> Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox);
            state.view <- Keepers Keeper_message;
            launch_keeper_history_load state ~mailbox ~keeper_name
          end
  end

(* The Keeper roster reads again when the server says a row or every row
   changed, on a resumed authority, and after a failed read (RFC-0481 §3.3).
   A named row is read alone; every row, or two or more rows due at once, is
   read whole. A revalidation reads it whole in its refresh. *)
let owe_whole_keeper_roster_read state =
  state.keeper_roster_owed <- Masc_tui_roster_owed.roster_changed state.keeper_roster_owed

let owe_keeper_roster_change state = function
  | Masc_tui_observer.Keeper_row_changed { keeper } ->
      state.keeper_roster_owed <-
        Masc_tui_roster_owed.row_changed ~keeper_name:keeper state.keeper_roster_owed
  | Masc_tui_observer.Every_row_changed -> owe_whole_keeper_roster_read state

let fail_keeper_roster_read state read =
  state.keeper_roster_owed <-
    Masc_tui_roster_owed.failed ~retry_s:Masc_tui_transport.Event_streams.stream_reconnect_s
      ~max_retry_s:keeper_execute_stream_max_reconnect_s ~now:(Masc_tui_wake.Mono.now ())
      read state.keeper_roster_owed

let launch_keeper_roster_owed_read state ~mailbox ~expected_workspace read =
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
  let launch ~deliver load =
    state.keeper_roster_owed <- Masc_tui_roster_owed.started read state.keeper_roster_owed;
    Masc_tui_transport.Workspace_admission.launch_async_read_with state ~mailbox
      ~boundary_error:(fun cause -> Keeper_control.Roster_unreachable cause)
      ~deliver load
  in
  match read with
  | Masc_tui_roster_owed.Read_roster ->
      Option.iter (fun roster_request ->
        launch
          ~deliver:(fun roster_result ->
            enqueue_async mailbox (Keeper_msg (Keeper_roster_reloaded { roster_request; roster_result })))
          (fun () ->
            Masc_tui_loader.load_keeper_roster ~host ~port ~expected_workspace))
        (Masc_tui_types.begin_keeper_roster_read ~intent:Snapshot_read.Refresh state)
  | Masc_tui_roster_owed.Read_row keeper_name ->
      Option.iter (fun row_request ->
        launch
          ~deliver:(fun row_result ->
            enqueue_async mailbox
              (Keeper_msg (Keeper_row_reloaded { row_request; row_keeper = keeper_name; row_result })))
          (fun () ->
            Masc_tui_loader.load_keeper_row ~host ~port ~expected_workspace ~keeper_name))
        (Masc_tui_types.begin_keeper_row_read state)

(* Runs on every loop iteration. One roster read runs at a time, the
   refresh's whole read included; a read that will not deliver leaves what it
   was reading owed again. Off the surfaces that draw the roster nothing is
   owed: entering one reads the roster whole. *)
let launch_owed_keeper_roster state ~mailbox =
  if not (current_surface_needs state).needs_keeper_roster then
    state.keeper_roster_owed <- Masc_tui_roster_owed.settled
  else begin
    let reading =
      Snapshot_read.in_flight state.keeper_roster_read
      || Snapshot_read.in_flight state.keeper_row_read
    in
    if not reading then
      state.keeper_roster_owed <- Masc_tui_roster_owed.abandoned state.keeper_roster_owed;
    let now = Masc_tui_wake.Mono.now () in
    state.keeper_roster_owed <- Masc_tui_roster_owed.release_scheduled ~now state.keeper_roster_owed;
    match
      reading,
      state.server_identity,
      Masc_tui_roster_owed.next_read ~now state.keeper_roster_owed
    with
    | false, Some expected_workspace, Some read when server_authority_ready state ->
        launch_keeper_roster_owed_read state ~mailbox ~expected_workspace read
    | false, Some _, Some _ | true, _, _ | false, None, _ | false, Some _, None -> ()
  end

let log_http_surface_read_started state ~full_refresh_running context =
  let request=Surface_read_context.current context in
  Log.Transport.info
    "tui_surface_read_started request=%d started_ns=%Ld full_refresh_running=%b navigation_pending=%d context=%s"
    (Surface_read_order.request_id request) (Surface_read_order.started_ns request)
    full_refresh_running (Surface_read_order.navigation_count state.http_surface_reads)
    (Yojson.Safe.to_string (Surface_read_context.to_yojson context))

(* Observed UI cleanup is not proof of worker exit or received data. Keep
   logging outside finalizers so it cannot replace the original failure there. *)
let log_http_surface_read_finished state context =
  let request=Surface_read_context.current context in
  Log.Transport.info
    "tui_surface_read_finished request=%d started_ns=%Ld settled_ns=%Ld navigation_pending=%d context=%s"
    (Surface_read_order.request_id request) (Surface_read_order.started_ns request)
    (Mtime_clock.elapsed_ns ()) (Surface_read_order.navigation_count state.http_surface_reads)
    (Yojson.Safe.to_string (Surface_read_context.to_yojson context))

let start_http_refresh ~server_contact state ~host ~port ~intent ~refresh_inflight
    ~scoped_refresh_inflight ~scoped_refresh_followup ~mailbox =
  (* While [/health] keeps failing, a pass the TUI asks for by itself waits
     for the one the failure owes, which revalidates everything this one
     would, side reads included (RFC tui-one-screen-grammar §2). *)
  let paced =
    Masc_tui_refresh_pace.starts ~now:(Masc_tui_wake.Mono.now ()) intent state.refresh_pace
  in
  (* The chat pane's history comes down its own generation-guarded path, not
     in the surface bundle. A revalidation owes it a read. Owed, so a pane
     scrolled into older rows or a read in flight takes it when it can; the
     owed read brings the tool details with it. *)
  if paced then begin
    Option.iter
         (fun keeper_name ->
           update_history_owed state ~keeper_name Masc_tui_owed_read.changed;
           launch_owed_history state ~mailbox)
         state.msg_target_keeper_name;
       Option.iter
         (fun (keeper : keeper) ->
           owe_keeper_composite_read state ~mailbox ~keeper_name:keeper.k_name;
           owe_keeper_calls_read state ~mailbox ~keeper_name:keeper.k_name)
         (selected_keeper state);
       Option.iter
         (fun (keeper : keeper) -> owe_keeper_logs_read state ~mailbox ~keeper_name:keeper.k_name)
         (keeper_log_target state);
       Option.iter
         (fun post_id -> owe_board_post_read state ~mailbox ~post_id)
         (board_post_on_screen state);
       owe_gate_snapshot_read state;
       owe_held_calls_read state;
       owe_tool_modes_read state;
       owe_keeper_turns_read state;
       owe_verification_read state;
       owe_repositories_read state;
       owe_connectors_read state;
       owe_runtime_config_read state;
       owe_harness_read state;
       owe_clients_read state;
       owe_memory_health_read state;
       owe_memory_world_read state;
       if Option.is_some (observer_browser_scope state) then
         state.browser_observation_owed <- Masc_tui_owed_read.changed state.browser_observation_owed;
       Masc_tui_types.owe_every_identity_login_read state;
       owe_async_requests_read state;
       owe_selected_tools_async_detail_read state;
       owe_tools_async_task_read state;
       owe_tools_reads state;
       owe_schedules_read state;
       owe_keeper_schedules_read state;
       owe_keeper_story_turns_read state;
       owe_chat_journal_reads state;
       owe_overview_read state;
       owe_push_owned_revalidation state
  end;
  scoped_refresh_followup :=
    note_full_refresh_intent ~intent
      ~full_refresh_inflight:!refresh_inflight
      ~scoped_refresh_inflight:!scoped_refresh_inflight
      !scoped_refresh_followup;
  if not !refresh_inflight && paced then begin
    refresh_inflight := true;
    scoped_refresh_followup := No_scoped_followup;
    let refresh_ticket = Http_refresh_order.dispatch state.http_refresh_order in
    Masc_tui_types.begin_http_refresh_state state ~ticket:refresh_ticket
      ~started_ns:(Mtime_clock.elapsed_ns ());
    (* One generation of kept dashboard answers per full pass. A pass reads
       its addresses one after another and can outlive several ticks, and an
       answer read early in it is still kept when the next pass asks. *)
    Masc_tui_http.start_read_generation ();
    let approval_ticket = Masc_tui_refresh_settlement.Approvals_asks_settlement.dispatch_approvals_listing state in
    let ask_request = Masc_tui_types.begin_asks_read state in
    (* Read before the label below moves. While the last probe said the
       server is booting, only the probe goes out this tick: the side loads
       below would each wait out a timeout against a process that has not
       finished replaying its stores. An account server serves none of them:
       each would answer 404. The pass also ends at a probe that fails. *)
    let probe_only =
      match state.connection_status with
      | Booting | Account_server _ -> true
      | Disconnected | Connecting | Degraded | Connected -> false
    in
    state.connection_status <-
      (match state.connection_status with
       | Connected -> Masc_tui_types.Connected
       | Degraded -> Masc_tui_types.Degraded
       | Booting -> Masc_tui_types.Booting
       | Account_server _ as account_server -> account_server
       | Disconnected | Connecting -> Masc_tui_types.Connecting);
    let needs = current_surface_needs state in
    let roster_request = if needs.needs_keeper_roster
      then Masc_tui_types.begin_keeper_roster_read ~intent:Snapshot_read.Refresh state
      else None in
    note_owed_surface_reads_started state needs;
    let reads, surface_request = Surface_read_order.dispatch ~kind:Surface_read_order.Full ~needs
      ~started_ns:(Mtime_clock.elapsed_ns ()) state.http_surface_reads in
    state.http_surface_reads <- reads;
    note_pushed_reads_started state needs;
    let board_query = board_query state in
    let surface_context=Surface_read_context.capture ~needs ~board_query surface_request in
    let provider_history_days = state.provider_history_days in
    let tool_series_days = Masc_tui_types.tool_series_days state in
    log_http_surface_read_started state ~full_refresh_running:true surface_context;
    (* The side reads -- the ask follow-up and the identity logins this TUI
       is waiting on -- start after workspace admission, either the cold
       initial-probe acknowledgement or the terminal refresh. The open
       questions the agenda strip counts read on their own announcement
       ([launch_owed_asks]). *)
    if not probe_only then launch_tick_side_reads state ~mailbox ~needs;

    (* This worker owns the binding. The UI's initial-probe acknowledgement is
       the only replacement, before parallel collection starts. Callbacks never
       read a newer workspace authority out of mutable UI state. *)
    let requests = ref
      { hrr_authority = state.workspace_authority; hrr_approval = approval_ticket;
        hrr_asks = ask_request; hrr_roster = roster_request; hrr_surfaces = surface_context } in
    let cold = state.workspace_identity = Workspace_identity_unread in
    let early_sources = cold || state.workspace_identity = Workspace_identity_match in
    let on_initial_identity = if cold then
      Some (fun hir_identity ->
        let acknowledged, hir_acknowledge = Eio.Promise.create () in
        Masc_tui_transport.Workspace_admission.enqueue mailbox (Http_msg (Http_initial_identity_read
          { hir_ticket = refresh_ticket; hir_authority = (!requests).hrr_authority;
            hir_identity; hir_needs = needs; hir_surface_context=(!requests).hrr_surfaces; hir_acknowledge }));
        let accepted = Eio.Promise.await acknowledged in
        Option.iter (fun admitted -> requests := admitted) accepted;
        accepted)
      else None in
    let progress_events = state.http_refresh_progress_events in
    let on_progress = Some (fun hp_event ->
      Masc_tui_types.publish_http_progress progress_events
        { hp_ticket = refresh_ticket; hp_authority = (!requests).hrr_authority; hp_event };
      Masc_tui_wake.(ring loop Refresh_progress)) in
    let on_dataset = if early_sources then
      Some (fun ed_identity ed_dataset ->
        Masc_tui_transport.Workspace_admission.enqueue mailbox (Http_msg (Http_dataset_loaded
          {ed_ticket=refresh_ticket;ed_authority=(!requests).hrr_authority;
           ed_request=Surface_read_context.current (!requests).hrr_surfaces;ed_identity;ed_dataset})))
      else None in
    let on_asks =
      if early_sources then
        Some (fun ea_identity ea_observation ->
          Masc_tui_transport.Workspace_admission.enqueue mailbox (Http_msg (Http_asks_loaded
            { ea_ticket = refresh_ticket; ea_authority = (!requests).hrr_authority;
              ea_identity; ea_observation })))
      else None
    in
    let on_approvals =
      if early_sources then
        Some (fun eap_identity eap_observation ->
          Masc_tui_transport.Workspace_admission.enqueue mailbox (Http_msg (Http_approvals_loaded
            { eap_ticket = refresh_ticket; eap_authority = (!requests).hrr_authority;
              eap_identity; eap_observation })))
      else None
    in
    let on_roster =
      if early_sources then
        Some (fun er_identity er_observation ->
          Masc_tui_transport.Workspace_admission.enqueue mailbox (Http_msg (Http_keeper_roster_loaded
            {er_ticket=refresh_ticket;er_authority=(!requests).hrr_authority;er_identity;er_observation})))
      else None in
    let run_refresh () =
      let completed = try
          Masc_tui_credential_preparation.await_initial state.credential_preparation;
          Http_msg (Http_refresh_done
             (Masc_tui_transport.Http_surface_collector.load_surfaces ~probe_only ~surface_request ~on_initial_identity ~on_progress ~on_dataset ~on_asks ~on_approvals ~on_roster ~ask_request ~roster_request
                ~refresh_ticket ~host ~port ~approval_ticket
                ~board_query
                ~provider_history_days ~tool_series_days
                ~needs))
      with
      | Eio.Cancel.Cancelled _ as exn -> raise exn
      | exn -> Http_msg (Http_refresh_failed
          (Printf.sprintf "HTTP refresh failed: %s" (Printexc.to_string exn),
           (!requests).hrr_approval, refresh_ticket))
      in
      Masc_tui_transport.Workspace_admission.enqueue mailbox (Http_surface_read_completed ((!requests).hrr_surfaces, completed))
    in
    match Eio_context.get_switch_opt () with
    | Some sw ->
        Eio.Fiber.fork ~sw run_refresh
    | None ->
        Fun.protect
          ~finally:(fun () ->
            refresh_inflight := false;
            Masc_tui_types.finish_http_surface_read state surface_request;
            Masc_tui_transport.Http_surface_collector.finish_observed_refresh state ~ticket:refresh_ticket)
          (fun () ->
             Masc_tui_credential_preparation.await_initial state.credential_preparation;
             apply_http_refresh_outcome ~server_contact state ~mailbox
               (Masc_tui_transport.Http_surface_collector.load_surfaces ~probe_only ~surface_request ~on_initial_identity:None ~on_progress:None ~on_dataset:None ~on_asks:None ~on_approvals:None ~on_roster:None ~ask_request ~roster_request
                  ~refresh_ticket ~host ~port ~approval_ticket
                  ~board_query
                ~provider_history_days ~tool_series_days
                ~needs));
        log_http_surface_read_finished state surface_context
  end

(* The task receipt and its dependent work have different authority. A
   temporary loss of identity holds the latter without replaying the POST. *)
let resume_task_followups ~server_contact state ~mailbox ~refresh_inflight
    ~scoped_refresh_inflight ~scoped_refresh_followup =
  let ready = function
    | Task_handoff _ -> state.local_keepers = Local_workspace_read
        && Option.is_none state.keepers_error
    | Task_cancel_refresh _ -> true in
  let run, withdrawn = take_task_followups state ~ready in
  List.iter (function
    | Task_handoff {task_id; _} -> report_action state "task"
        (Printf.sprintf "%s created in the previous workspace; Keeper handoff withdrawn" task_id)
    | Task_cancel_refresh { task_id; certainty } ->
        let kind, outcome = match certainty with
          | Cancellation_confirmed -> "system", "cancelled"
          | Cancellation_unconfirmed -> "error", "cancellation remains unconfirmed" in
        report_action state kind
          (Printf.sprintf "task %s %s in the previous workspace; current workspace unchanged"
             task_id outcome)) withdrawn;
  List.iter (function
    | Task_handoff {keeper; task_id; _}
      when not (keeper_available_for_new_message state keeper) ->
        report_action state "error"
          (Printf.sprintf "%s created; Keeper %s is no longer registered, handoff not sent" task_id keeper)
    | (Task_handoff {keeper; task_id; title; body; editor} as action) ->
        (* This is an already accepted task, not the operator's current
           composer. Keep any newer draft, attachment or recalled edit intact. *)
        let request = Keeper_chat.create_request ~keeper_name:keeper
            ~message:(Masc_tui_command.task_message ~task_id ~title ~body) () in
        let submitted_at = Unix.gettimeofday () in
        (match Chat_queue.push state.msg_queued ~submitted_at request with
         | Error detail ->
             Option.iter (fun expected_workspace ->
               remember_task_followup state ~expected_workspace action) state.server_identity;
             report_action state "error"
               (Printf.sprintf "%s created; Keeper handoff waiting: %s" task_id detail)
         | Ok (queue, _) ->
             state.msg_queued <- queue;
             Masc_tui_chat_dispatch.Chat_watching.append_user_history_once ~submitted_at state request;
             state.keeper_interactive_waiting <-
               (keeper, request.request_id,
                Awaiting_control {generation = keeper_chat_control_generation state keeper; target = None})
               :: state.keeper_interactive_waiting;
             (* A handoff can complete after the operator starts editing a
                different Keeper. Deliver to its own queue without switching
                that editor (which would retire its recalled draft). *)
             if task_handoff_may_focus state ~keeper editor then begin
               withdraw_resource_diagram_pending state;
               retire_remote_image_for_navigation state;
               close_key_modals state;
               state.palette_open <- false;
               state.palette_mode <- Masc_tui_types.Palette_jump;
               state.palette_query <- "";
               state.palette_cursor <- 0;
               state.search <- None;
               set_msg_scroll state 0;
               state.view <- Keepers Keeper_message;
               if state.msg_target_keeper_name = None then
                 Masc_tui_chat_input.Message_draft_recall.open_message_for_keeper state keeper ~drain_queue:(fun () -> ())
             end;
             Masc_tui_chat_dispatch.Queue_steer.launch_waiting_keeper_input state ~mailbox ~keeper_name:keeper)
    | Task_cancel_refresh { task_id; certainty = _ } ->
        (* Only the detail that is still selected owns this follow-up read. *)
        if state.task_detail_id = Some task_id then begin
          Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size state ~mailbox task_id
        end;
        start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
          ~intent:Revalidate ~refresh_inflight ~scoped_refresh_inflight
          ~scoped_refresh_followup ~mailbox) run


let resume_goal_confirmation_identity_refresh state ~mailbox =
  if server_authority_ready state then begin
    let pending = state.goal_confirmation_identity_refresh in
    state.goal_confirmation_identity_refresh <- None;
    match pending, state.server_identity with
    | Some (goal_id, workspace), Some identity ->
        (match selected_planning_goal_id state, state.goal_confirmation with
         | Some selected, Goal_confirmation.Inspecting read
           when String.equal goal_id selected
                && Goal_confirmation.same_confirmation_workspace workspace
                     (Goal_confirmation.confirmation_workspace_of_identity identity)
                && Goal_confirmation_read.current_key read = Some goal_id ->
             Masc_tui_work_actions.Goal_actions.launch_goal_confirmation_read state ~mailbox ~goal_id
         | (Some _ | None), (Goal_confirmation.Inspecting _ | Goal_confirmation.Submitting _) -> ())
    | None, _ | Some _, None -> ()
  end

let launch_skill_evidence_read ?composition_run_id state ~mailbox reference =
  if server_authority_ready state then begin
    let key = Skill_reference.to_yojson reference |> Yojson.Safe.to_string in
    let request = ref () in
    state.tools_evidence_request <- Some request;
    state.tools_evidence_reference <- Some reference;
    state.tools_evidence_run_id <- composition_run_id;
    let admit = Masc_tui_transport.Workspace_admission.capture_admission state ~mailbox in
    let check () = admit () |> Result.map_error (fun refusal -> Request_withdrawn refusal) in
    let host = Masc_tui_transport.Workspace_admission.server_peer_host and port = state.port in
    Masc_tui_transport.Workspace_admission.launch_guarded_request state ~mailbox ~boundary_error:(fun detail -> Request_failed detail)
      ~withdrawn:(fun refusal -> Request_withdrawn refusal)
      ~deliver:(fun result -> Skill_evidence_loaded (request, key, result))
      (fun () ->
        let open Result.Syntax in
        let* () = check () in
        let* json = Masc_tui_http.post_skill_evidence ?composition_run_id ~host ~port reference
          |> Result.map_error (fun detail -> Request_failed detail) in
        let* () = check ()
          |> Result.map_error (Masc_tui_transport.Request_notice.request_failure_after_read state ~request:Kept_request.Skill_evidence) in
        Ok json)
  end

(* The two tokens a read is admitted under. Applying a server identity
   reading moves the workspace one when the workspace changes (the first
   reading at boot is one) and cancels every read it admitted; it revokes
   the detail one when the item authority changes, as when a booting server
   becomes ready. *)
type read_authority =
  { read_workspace : Masc_tui_types.workspace_authority
  ; read_detail : unit ref
  }

let read_authority state =
  { read_workspace = state.workspace_authority; read_detail = state.detail_read_authority }

(* A read sent under an authority that a refresh then withdrew never lands:
   its completion carries the old authority and is dropped. A full or scoped
   refresh ends here once it is applied, so each read the move withdrew is
   sent again in one place; no periodic read would send it later (2026-10-07,
   under the old 2s cadence: after boot the Answering surface said "not
   loaded yet", an open chat showed no running turn, and Home showed no
   decision cards until the next tick). It
   also runs after an admitted cold probe. Roster-dependent presentation still
   waits for its separately owned roster observation. *)
let resume_reads_after_authority_change ~server_contact state ~mailbox ~refresh_inflight
    ~scoped_refresh_inflight ~scoped_refresh_followup ~(before : read_authority) =
  settle_retired_sent_image state;
  Masc_tui_chat_dispatch.Chat_journals.settle_retired_chat_copy state;
  Masc_tui_collab_queue.Keeper_queue.settle_retired_queue_inspections state;
  Masc_tui_surface_requests.Prompt_preset_requests.settle_retired_chat_command_reads state;
  resume_task_followups ~server_contact state ~mailbox ~refresh_inflight
    ~scoped_refresh_inflight ~scoped_refresh_followup;
  let workspace_moved = before.read_workspace <> state.workspace_authority in
  let moved = workspace_moved || before.read_detail != state.detail_read_authority in
  resume_goal_confirmation_identity_refresh state ~mailbox;
  (* The detail goes first: it restores the remembered Keeper focus and
     marks its identity read pending, so the side reads below neither poll
     the same login again nor ask about the Keeper the cursor fell on. *)
  refresh_visible_detail_after_authority_recovery state ~mailbox
    ~previous_authority:before.read_detail;
  if moved && server_authority_ready state then begin
    (* Read withdrawal also stops the Observer and Fleet streams. A later
       confirmed identity can arrive through a discarded bundle or a scoped
       read, so restore both under that authority without a cadence tick. *)
    Masc_tui_transport.Event_streams.stop_observer_recovery state;
    Masc_tui_transport.Event_streams.open_observer_if_due ~browser_scope:observer_browser_scope state ~retry_closed:false
      ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port ~mailbox;
    Masc_tui_transport.Event_streams.open_fleet_stream_if_due state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port ~mailbox;
    (* Withdrawal dropped the chat's owed read with its old authority, and a
       change while the reading was withdrawn reached nobody. The kept chat
       owes one read under the new authority (RFC-0480 §3.1). *)
    Option.iter
      (fun keeper_name ->
        update_history_owed state ~keeper_name Masc_tui_owed_read.changed;
        launch_owed_history state ~mailbox)
      state.msg_target_keeper_name;
    (* A Gate change while the reading was withdrawn reached nobody, and a
       cold admission has read no Gate yet. The same holds for the questions. *)
    owe_gate_snapshot_read state;
    owe_asks_read state;
    owe_overview_read state;
    owe_harness_read state;
    (* The feed was gone while the authority was withdrawn: every login
       announcement it would have delivered was lost, so each Keeper a kept
       expectation names owes its read again. *)
    owe_clients_read state;
    Masc_tui_types.owe_every_identity_login_read state;
    owe_async_requests_read state;
    owe_selected_tools_async_detail_read state;
    owe_tools_async_task_read state;
    owe_tools_reads state;
    owe_whole_keeper_roster_read state;
    owe_keeper_turns_read state;
    owe_pending_confirms_read state;
    owe_schedules_read state;
    owe_keeper_schedules_read state;
    owe_keeper_story_turns_read state;
    owe_chat_journal_reads state;
    (* Under the same condition the tick sends them: a server that is not
       booting, whether or not its workspace is this checkout's. *)
    launch_tick_side_reads state ~mailbox ~needs:(current_surface_needs state);
    (* An explicit binding-write reread also survives while its surface is
       hidden. Recovery is one authority transition, not a retry timer. A read
       already started (or unable to start) above must not be launched again. *)
    (match Connector_read.view state.connectors_read with
     | Connector_read.Waiting_after_write -> Masc_tui_surface_requests.Connector_volume_requests.launch_connectors_load state ~mailbox
     | Quiet | Reading _ | Failed_to_start -> ());
    let activations = state.account_login_activation_resume in
    state.account_login_activation_resume <- [];
    List.iter (fun ((view : Masc_tui_account_login.t), generation, saved) ->
      if view.generation = generation
         && List.exists (fun current -> current == view)
              (Option.to_list state.account_login @ state.account_login_detached) then
        Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view (Masc_tui_account_login.Activate_saved saved))
      activations;
    let account_reads = state.account_login_read_resume in
    state.account_login_read_resume <- [];
    List.iter (fun ((view : Masc_tui_account_login.t), generation, action) ->
      if view.generation = generation && account_login_action_is_read action
         && List.exists (fun current -> current == view)
              (Option.to_list state.account_login @ state.account_login_detached) then
        Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view action) account_reads;
    if state.msx_open && state.machine_source = Masc.Machine_lane.Msx
       && state.msx_live = Masc_tui_machine_live.Unread
       && Option.is_none state.msx_live_in_flight then
      launch_msx_live_read state ~mailbox;
    if state.msx_open && state.msx_menu_open then
      launch_dos_live_read state ~mailbox;
    (* The surface on view asks again from the list it reads on arrival.
       Its request went out under the old authority, and a surface outside
       the bundle has no tick of its own to recover it. *)
    (* Restore a nested Browser request before a surface's generic refresh
       can replace its scene/screenshot selection with the tab inventory. *)
    let browser_resume = state.browser_lane_read_resume in
    state.browser_lane_read_resume <- None;
    (match browser_resume, state.browser_lane with
     | Some (generation, prior, operation), Some current
       when generation = state.browser_lane_generation
         && prior.source = current.source
         && Browser_lane_view.same_selected_client prior.selected_client current.selected_client
         && prior.selected_tab = current.selected_tab ->
           Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox operation
     | _ -> ());
    if state.runtime_catalog_resume then Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load state ~mailbox;
    launch_surface_reads state ~mailbox state.view;
    refresh_acting_pane_changes state ~mailbox;
    (* Retained nested readers own their selection independently of the list
       underneath. Reissue their observations without resetting navigation. *)
    (match state.view with
     | Changes ->
         Option.iter (fun path ->
           launch_git_diff_load state ~mailbox ~keeper:state.changes_keeper ~path)
           state.changes_tree_diff_path
     | Fusion ->
         (match state.fusion_launch with
          | Some (Fusion_launch_reading_presets _) ->
              launch_fusion_launch_options_load state ~mailbox
          | Some (Fusion_launch_open _ | Fusion_launch_started _) | None -> ())
     | Board ->
         Option.iter (fun post_id -> owe_board_post_read state ~mailbox ~post_id)
           (board_post_on_screen state)
     | Keepers Keeper_message ->
         Option.iter (fun keeper_name ->
           launch_keeper_chat_file_changes_load ~force:true state ~mailbox ~keeper_name;
           if state.msg_tool_visibility <> Tools_compact then
             Masc_tui_work_requests.Schedule_call_requests.launch_keeper_calls_load ~force:true state ~mailbox keeper_name)
           state.msg_target_keeper_name;
         let pending = state.msg_older_resume in
         state.msg_older_resume <- None;
         (match pending with
          | Some (keeper_name, cursor)
            when state.msg_target_keeper_name = Some keeper_name
                 && state.msg_older_cursor = cursor ->
              launch_keeper_older_page state ~mailbox ~keeper_name ~cursor
          | _ -> ())
     | Planning ->
         (match state.planning_mode with
          | Planning_detail goal_id ->
              Masc_tui_work_requests.Tools_task_requests.launch_goal_timeline_load state ~mailbox goal_id;
              (match state.goal_confirmation with
               | Goal_confirmation.Inspecting read
                 when Goal_confirmation_read.current_key read = Some goal_id ->
                   Masc_tui_work_actions.Goal_actions.launch_goal_confirmation_read state ~mailbox ~goal_id
               | Goal_confirmation.Inspecting _ | Goal_confirmation.Submitting _ -> ())
          | Planning_list -> ())
     | Tools ->
         Masc_tui_work_requests.Tools_task_requests.launch_tools_async_detail state ~mailbox;
         Masc_tui_work_requests.Tools_task_requests.launch_tools_async_task ~terminal_size:Masc_tui_render_prim.get_terminal_size ~force:true state ~mailbox;
         (match state.tools_evidence_reference, selected_tools_skill_profile state with
          | Some reference, Some profile when Skill_reference.equal reference profile.esp_reference ->
              launch_skill_evidence_read ?composition_run_id:state.tools_evidence_run_id state ~mailbox reference
          | _ -> state.tools_evidence_reference <- None; state.tools_evidence_run_id <- None)
     | Code ->
         let deliver = Masc_tui_transport.Workspace_admission.deliver_code state mailbox in
         let host = Masc_tui_transport.Workspace_admission.server_peer_host in
         let lsp = Masc_tui_fetched.current_key state.code_lsp_query in
         let intent = state.code_file_resume_intent in
         Option.iter (fun path -> Masc_tui_code_requests.launch_file_load ~intent
           state ~host ~deliver ~path) (Masc_tui_fetched.current_key state.code_file);
         if intent = Refresh_code_file then begin
         (* An overlay can be opened while identity is unread, before its
            first fetch has a key. Its intent belongs to the selected file,
            not the last completed or dispatched overlay request. *)
         let selected_file = Masc_tui_fetched.current_key state.code_file in
         if state.code_history_open then Option.iter (fun path ->
           Masc_tui_code_requests.launch_history_load state ~host ~deliver ~path)
           selected_file;
         if state.code_diff_open then Option.iter (fun path ->
           Masc_tui_code_requests.launch_diff_load state ~host ~deliver
             ~target:(diff_target_for_refresh state
                        ~base_ref:tree_diff_base_ref ~path))
           selected_file;
         Option.iter (fun path -> Masc_tui_code_requests.launch_blame_load state ~host ~deliver ~path)
           (Masc_tui_fetched.current_key state.code_blame);
         Option.iter (fun query ->
           if query.clq_scope = state.code_scope then
             Masc_tui_code_requests.start_lsp_question ~line:query.clq_line state ~host ~deliver
               ~report:(report_action state) ~question:query.clq_question ~symbol:query.clq_symbol) lsp
         end
     | Keepers Keeper_runtime_pick -> Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load state ~mailbox
     | Keepers Keeper_calls -> Option.iter (fun keeper ->
         owe_keeper_calls_read state ~mailbox ~keeper_name:keeper.Tui_decode.k_name) (selected_keeper state)
     | Verification ->
         (match state.verification, state.verification_detail_request_id with
          | Some snapshot, Some request_id ->
              List.find_opt (fun row -> String.equal row.Tui_decode.vr_request_id request_id)
                snapshot.Tui_decode.vs_requests
              |> Option.iter (fun row -> Masc_tui_work_actions.Verification_actions.launch_verification_evidence_load state ~mailbox
                {vek_request_id=row.Tui_decode.vr_request_id;vek_task_id=row.vr_task_id})
          | _ -> ())
     | Schedules -> Option.iter (fun schedule_id ->
         Masc_tui_work_requests.Schedule_call_requests.launch_schedule_wake_history_load state ~mailbox ~schedule_id) state.schedule_detail_id
     | Lanes ->
         (match state.lanes_mode with
          | Lanes_run_list lane -> launch_lane_runs_load state ~mailbox ~lane
          | Lanes_run_detail (_, run_id) -> launch_lane_run_detail_load state ~mailbox ~run_id
          | Lanes_measurement_detail sha256 -> launch_measurement_artifact_load state ~mailbox ~sha256
          | Lanes_overview | Lanes_inventory_detail _ -> ())
     | Memory ->
         (match state.memory_facts_keeper with
          | Some "*" -> Masc_tui_surface_requests.Memory_repository_requests.launch_all_memory_facts_load state ~mailbox
          | Some keeper_name -> Masc_tui_surface_requests.Memory_repository_requests.launch_memory_facts_load state ~mailbox ~keeper_name
          | None -> ())
     | Keepers (Keeper_list | (Keeper_detail | Keeper_logs)) | Overview | Acting | Metrics | Clients
     | Approvals | Harness | Repositories | Connectors | Runtime | Config | Resources | System_logs -> ());
    (match state.view with
     | Resources -> Option.iter (fun uri ->
         launch_resources_read state ~mailbox ~key:uri) state.resource_pending_key
     | Config when state.config_pane = Config_prompts ->
         (match state.prompts_librarian_input_requested, Masc_tui_surface_requests.Prompt_preset_requests.selected_prompt_for_state state with
          | Some prompt_key, Some row when String.equal row.Tui_decode.pr_key prompt_key ->
              Masc_tui_surface_requests.Prompt_preset_requests.launch_librarian_input_load state ~mailbox ~prompt_key
          | _ -> ())
     | Overview | Acting | Metrics | Memory | Lanes | Clients | Board | Approvals | Planning
     | Schedules | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors
     | Runtime | Tools | System_logs | Keepers _ | Config -> ());
    Option.iter (Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size state ~mailbox) state.task_detail_id;
    Option.iter (fun repo_id -> launch_workspace_activity state ~mailbox ~repo_id)
      state.workspace_activity_repo;
    Option.iter (launch_exact_activity_read state ~mailbox) state.exact_activity_open;
    Option.iter (launch_machine_activity_read state ~mailbox) state.machine_activity_open;
    Option.iter (fun session -> Option.iter (fun (kind,api_key_env) ->
      Masc_tui_work_requests.Voice_requests.launch_voice_agent_voices state ~mailbox ~kind ~api_key_env) session.vas_lookup)
      state.voice_agent_voices;
    (match state.lane_addons with
     | None ->
         state.lane_installer_read_resume <- None;
         state.lane_nested_read_resume <- None
     | Some view ->
         let nested = state.lane_nested_read_resume in
         state.lane_nested_read_resume <- None;
         let pending = state.lane_installer_read_resume in
         state.lane_installer_read_resume <- None;
         (match nested, pending with
          | Some (generation, Lane_subscriptions_read), _
            when generation = view.generation && Option.is_some view.subscription_panel ->
              Masc_tui_surface_requests.Lane_browser_requests.launch_lane_subscriptions state ~mailbox Masc_tui_lane_subscriptions.Inspect
          | Some (generation, Lane_declaration_read {path; edit}), _
            when generation = view.generation && view.document_key = Some (Filename.basename path) ->
              Masc_tui_surface_requests.Lane_browser_requests.launch_lane_declaration state ~mailbox ~edit (Masc_tui_lane_declaration.Read path)
          | _, Some (generation, read) when generation = view.generation ->
              (match read with
               | Masc_tui_lane_installer.Read_catalog directory -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_package_catalog state ~mailbox directory
               | Read_preview path -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_package_preview state ~mailbox path)
          | (None | Some (_, (Lane_subscriptions_read | Lane_declaration_read _))), _
            when not view.loading -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox Masc_tui_lane_addons.Inspect
          | (None | Some (_, (Lane_subscriptions_read | Lane_declaration_read _))), _ -> ()));
    if state.context_inspector_open then Option.iter (fun keeper_name ->
      Masc_tui_chat_dispatch.Chat_journals.launch_context_inspector_load state ~mailbox ~keeper_name) state.context_inspector_keeper;
    if state.repository_changes_open then
      (match state.repository_changes_scope, state.repository_changes_diff_path with
       | Some scope, Some path ->
           launch_repository_changes_diff_load state ~mailbox ~scope ~path
       | Some scope, None -> launch_repository_changes_load state ~mailbox ~scope
       | None, _ -> ());
    if state.keeper_deletions_open then Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_deletions state ~mailbox ();
    (match state.browser_history with
     | Some {resume=Some resume; _} -> Masc_tui_surface_requests.Lane_browser_requests.launch_browser_history state ~mailbox
         ~reload:(match resume with Browser_history.Reload_list -> true | Reload_selection -> false)
     | Some _ | None -> ());
    (* The move may retire data that another collector took from this pass.
       A matched workspace also needs a new approval listing. For a mismatch,
       reread only when the open surface still needs an unread observation;
       foreign approval and question results remain subject to their existing
       workspace admission rules. *)
    if revalidate_workspace_surfaces state ~workspace_moved ~needs:(current_surface_needs state) then
      start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
        ~intent:Revalidate ~refresh_inflight ~scoped_refresh_inflight
        ~scoped_refresh_followup ~mailbox
  end
;;

let apply_http_scoped_refresh_success ~server_contact state ~currency_authority ~base_path ~mailbox
    ~refresh_inflight ~scoped_refresh_inflight ~scoped_refresh_followup results =
  if Http_refresh_order.is_current state.http_refresh_order results.http_refresh_ticket then begin
  let was_unavailable =
    state.workspace_identity <> Workspace_identity_match
    || Option.is_some state.keepers_error
  in
  let previous_items = Masc_tui_surface_requests.Keeper_surface_requests.visible_item_revision state in
  let authority = read_authority state in
  let roster_refreshed = apply_http_scoped_surfaces state ~mailbox ~currency_authority results in
  if roster_refreshed || Option.is_none results.http_keeper_roster then
    Masc_tui_surface_requests.Keeper_surface_requests.refresh_changed_keeper_items state ~mailbox ~roster_refreshed previous_items;
  resume_reads_after_authority_change ~server_contact state ~mailbox ~refresh_inflight
    ~scoped_refresh_inflight ~scoped_refresh_followup ~before:authority;
  resume_authorized_input_after_refresh state ~was_unavailable ~base_path ~mailbox
  end

let start_http_scoped_refresh ~server_contact state ~host ~port
    ~(ask : Masc_tui_refresh_pace.screen_ask) ~refresh_inflight
    ~full_refresh_inflight ~scoped_refresh_followup ~mailbox
    ~(needs : Masc_tui_types.surface_needs) =
  (* Entering a surface that draws the roster owes it a whole read rather
     than reading it in this bundle. A newer full bundle drops a navigation
     bundle's answers, and with no cadence roster read nothing else would
     free the roster's read slot. *)
  if needs.needs_keeper_roster then owe_whole_keeper_roster_read state;
  let needs = { needs with needs_keeper_roster = false } in
  let authority = state.workspace_authority in
  (* This bundle probes [/health] first, so while the probe keeps failing a
     read the screen owes by itself waits for the pass the failure owes
     (RFC tui-one-screen-grammar §2). A held read starts nothing and records
     no start, so its debt stays owed and its launcher asks again on a later
     loop. Every caller states its [ask]; none is assumed. *)
  if Masc_tui_types.surface_needs_any needs
     && Masc_tui_refresh_pace.screen_read_starts ~now:(Masc_tui_wake.Mono.now ()) ask
          state.refresh_pace
  then begin
    let collection_inflight = !full_refresh_inflight
      || Surface_read_order.navigation_in_flight state.http_surface_reads in
    refresh_inflight := true;
    let refresh_ticket = Http_refresh_order.for_navigation
      ~collection_inflight state.http_refresh_order in
    state.http_refresh_order <- refresh_ticket;
    note_owed_surface_reads_started state needs;
    let reads, surface_request = Surface_read_order.dispatch ~kind:Surface_read_order.Navigation ~needs
      ~started_ns:(Mtime_clock.elapsed_ns ()) state.http_surface_reads in
    state.http_surface_reads <- reads;
    note_pushed_reads_started state needs;
    let board_query = board_query state in
    let surface_context=Surface_read_context.capture ~needs ~board_query surface_request in
    let provider_history_days = state.provider_history_days in
    let tool_series_days = Masc_tui_types.tool_series_days state in
    log_http_surface_read_started state ~full_refresh_running:!full_refresh_inflight surface_context;
    let approval_ticket =
      if not needs.needs_operator_approvals then None
      else Masc_tui_refresh_settlement.Approvals_asks_settlement.dispatch_approvals_listing state
    in
    let ask_request = if needs.needs_asks then Masc_tui_types.begin_asks_read state else None in
    (* Chat history has its own generation-guarded loader rather than a field
       in the HTTP surface record. It still follows the same delta: entering
       chat asks once; moving among Keeper modes that share the roster does
       not restart it. The read the opening started answers the entry even
       when it landed before this delta ran. *)
    Option.iter (fun keeper_name -> launch_keeper_history_load state ~mailbox ~keeper_name)
      (chat_entry_read_due state ~needs);
    let currency_authority = {
      car_generation = state.candle_authority_generation;
      car_identity = state.server_identity;
    } in
    let latest_identity = ref None in
    let read_refresh () =
      try
        Masc_tui_credential_preparation.await_initial state.credential_preparation;
        let open Result.Syntax in
        let identity = currency_authority.car_identity in
        (* A superseded scoped probe must not enqueue an unticketed identity
           withdrawal. Only its ticketed completion may change authority. The
           guard's stop travels as [Request_withdrawn]; an identity read that
           failed stays that read's own failure (RFC §2). *)
        let probe () =
          if authority <> state.workspace_authority then Error (Request_withdrawn Workspace_authority_withdrawn)
          else
            let reading = load_server_identity ~host ~port in
            latest_identity := Some reading;
            if authority <> state.workspace_authority then Error (Request_withdrawn Workspace_authority_withdrawn)
            else match reading with
              | Error detail -> Error (Request_failed detail)
              | Ok identified when Masc_tui_types.server_workspace_matches ~expected:identity reading ->
                  Ok identified
              | Ok _ -> Error (Request_withdrawn Workspace_identity_changed)
        in
        let* server_identity = probe () in
        let on_dataset ed_identity ed_dataset =
          Masc_tui_transport.Workspace_admission.enqueue mailbox (Http_msg (Http_dataset_loaded
            {ed_ticket=refresh_ticket;ed_authority=authority;ed_request=surface_request;
             ed_identity;ed_dataset})) in
        let readings = Masc_tui_transport.Http_surface_collector.load_scoped_surface_reads ~on_progress:None ~on_dataset:(Some on_dataset) ~surface_request ~ask_request ~refresh_ticket
              ~server_identity:(Ok server_identity) ~host ~port
              ~approval_ticket ~board_query
              ~provider_history_days ~tool_series_days
              ~needs in
        let* confirmed_identity = probe () in
        Ok { readings with http_scoped_server_identity = Ok confirmed_identity }
      with
      | Eio.Cancel.Cancelled _ as exn -> raise exn
      | exn -> Error (Request_failed (Printf.sprintf "HTTP surface refresh failed: %s"
                       (Printexc.to_string exn)))
    in
    let run_refresh () =
      let completed = match read_refresh () with
        | Ok results -> Http_msg (Http_scoped_refresh_done (authority, currency_authority, results))
        | Error err -> Http_msg (Http_scoped_refresh_failed
            (authority, err, approval_ticket, refresh_ticket, !latest_identity, surface_request)) in
      Masc_tui_transport.Workspace_admission.enqueue mailbox (Http_surface_read_completed (surface_context, completed))
    in
    match Eio_context.get_switch_opt () with
    | Some sw -> Eio.Fiber.fork ~sw run_refresh
    | None ->
        Fun.protect
          ~finally:(fun () ->
            Masc_tui_types.finish_http_surface_read state surface_request;
            refresh_inflight := Surface_read_order.navigation_in_flight state.http_surface_reads)
          (fun () ->
             match read_refresh () with
             | Ok results when authority = state.workspace_authority ->
                 apply_http_scoped_refresh_success ~server_contact state ~currency_authority
                   ~base_path:state.local_base_path ~mailbox
                   ~refresh_inflight:full_refresh_inflight
                   ~scoped_refresh_inflight:refresh_inflight ~scoped_refresh_followup
                   results
             | Error err when authority = state.workspace_authority ->
                 let before = read_authority state in
                 apply_http_scoped_refresh_failure state ~mailbox
                   ~refresh_ticket ~approval_ticket ~latest:!latest_identity err;
                 resume_reads_after_authority_change ~server_contact state ~mailbox
                   ~refresh_inflight:full_refresh_inflight
                   ~scoped_refresh_inflight:refresh_inflight ~scoped_refresh_followup
                   ~before
             | Ok _ | Error _ -> ());
        log_http_surface_read_finished state surface_context
  end

(* Runs on every loop iteration. A pushed source off screen owes nothing:
   arriving on its surface reads it. A read of it already in flight is let
   finish first. The due sources go out together in one surface bundle. *)
let launch_owed_pushed_reads ~server_contact state ~refresh_inflight ~full_refresh_inflight
    ~scoped_refresh_followup ~mailbox =
  owe_provider_history_day state ~now:(Unix.gettimeofday ());
  if Masc_tui_types.take_tool_series_due state ~now:(Masc_tui_wake.Mono.now ()) then
    owe_pushed_read state Surface_read_source.Tool_series;
  let wanted = Surface_read_order.sources (current_surface_needs state) in
  let now = Masc_tui_wake.Mono.now () in
  let due =
    List.filter
      (fun source ->
        if not (List.mem source wanted) then begin
          set_pushed_read state source Masc_tui_owed_read.settled;
          false
        end
        else begin
          let reading =
            List.exists
              (Surface_read_order.pending_dataset state.http_surface_reads)
              (Surface_read_order.source_datasets source)
          in
          let read =
            if reading then pushed_read state source
            else Masc_tui_owed_read.abandoned (pushed_read state source)
          in
          set_pushed_read state source read;
          Masc_tui_owed_read.due ~now read && not reading
        end)
      Masc_tui_types.pushed_sources
  in
  if due <> [] && server_authority_ready state then
    start_http_scoped_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
      ~ask:Masc_tui_refresh_pace.Owed_read_due
      ~refresh_inflight ~full_refresh_inflight ~scoped_refresh_followup ~mailbox
      ~needs:
        (List.fold_left
           (fun needs source -> Masc_tui_types.with_source needs source true)
           Masc_tui_types.nothing due)

(* Runs on every loop iteration. A Board read already in flight is let finish
   first; one that ended unanswered waits and reads again
   ([unanswered_read]). The scoped and full refreshes record the start of
   every Board read ([note_owed_surface_reads_started]). Only a matched
   workspace applies the list, so only a matched workspace reads it. *)
let launch_owed_board_list ~server_contact state ~refresh_inflight ~full_refresh_inflight
    ~scoped_refresh_followup ~mailbox =
  if state.view <> Board then state.board_list_owed <- Masc_tui_owed_read.settled
  else begin
    let reading =
      Surface_read_order.pending_dataset state.http_surface_reads Surface_read_order.Board_posts
    in
    let read =
      if reading then state.board_list_owed
      else unanswered_read state.board_list_owed
    in
    state.board_list_owed <- read;
    if Masc_tui_owed_read.due ~now:(Masc_tui_wake.Mono.now ()) read
       && server_authority_ready state
       && state.workspace_identity = Workspace_identity_match
       && not reading
    then
      start_http_scoped_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
        ~ask:Masc_tui_refresh_pace.Owed_read_due
        ~refresh_inflight ~full_refresh_inflight ~scoped_refresh_followup ~mailbox
        ~needs:{ Masc_tui_types.nothing with needs_board = true }
  end

(* Runs on every loop iteration. A dataset already in flight is let finish
   first; one that ended unanswered waits and reads again
   ([unanswered_read]). Only the datasets whose debt is due are read; the
   scoped refresh records their start ([note_owed_surface_reads_started]).
   Only a matched workspace applies them, so only a matched workspace reads
   them. *)
let launch_owed_planning ~server_contact state ~refresh_inflight ~full_refresh_inflight
    ~scoped_refresh_followup ~mailbox =
  if state.view <> Planning then begin
    state.planning_owed <- Masc_tui_owed_read.settled;
    state.overview_goals_owed <- Masc_tui_owed_read.settled
  end else begin
    let pending dataset =
      Surface_read_order.pending_dataset state.http_surface_reads dataset
    in
    let planning_reading = pending Surface_read_order.Planning_data in
    let goals_reading = pending Surface_read_order.Overview_goals_data in
    let planning =
      if planning_reading then state.planning_owed
      else unanswered_read state.planning_owed
    in
    let goals =
      if goals_reading then state.overview_goals_owed
      else unanswered_read state.overview_goals_owed
    in
    state.planning_owed <- planning;
    state.overview_goals_owed <- goals;
    let now = Masc_tui_wake.Mono.now () in
    let planning_due = Masc_tui_owed_read.due ~now planning && not planning_reading in
    let goals_due = Masc_tui_owed_read.due ~now goals && not goals_reading in
    if (planning_due || goals_due) && server_authority_ready state
       && state.workspace_identity = Workspace_identity_match then
      start_http_scoped_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
        ~ask:Masc_tui_refresh_pace.Owed_read_due
        ~refresh_inflight ~full_refresh_inflight ~scoped_refresh_followup ~mailbox
        ~needs:{ Masc_tui_types.nothing with
                 needs_planning = planning_due; needs_overview_goals = goals_due }
  end

let start_scoped_refresh_followup ~server_contact state ~host ~port ~refresh_inflight
    ~scoped_refresh_inflight ~scoped_refresh_followup ~mailbox =
  let next, launch =
    take_scoped_refresh_followup
      ~full_refresh_inflight:!refresh_inflight
      ~scoped_refresh_inflight:!scoped_refresh_inflight
      !scoped_refresh_followup
  in
  scoped_refresh_followup := next;
  if launch then
    start_http_refresh ~server_contact state ~host ~port ~intent:Revalidate ~refresh_inflight
      ~scoped_refresh_inflight ~scoped_refresh_followup ~mailbox

(* Runs on every loop iteration. A failing [/health] probe owes one pass,
   which starts once its wait is over, whether or not anything asked
   (RFC tui-one-screen-grammar §2). Only a full pass in flight holds it: a
   screen read in flight is the same case for this pass as for any other,
   and [start_http_refresh] decides it through [note_full_refresh_intent]. *)
let launch_owed_refresh_pass ~server_contact state ~refresh_inflight ~scoped_refresh_inflight
    ~scoped_refresh_followup ~mailbox =
  if not !refresh_inflight
     && Masc_tui_refresh_pace.due ~now:(Masc_tui_wake.Mono.now ()) state.refresh_pace
  then
    start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port ~intent:Owed_pass
      ~refresh_inflight ~scoped_refresh_inflight ~scoped_refresh_followup ~mailbox

let open_board_post_id state ~mailbox ~focus post_id =
  state.board_mode <- Board_read post_id;
  state.board_detail <- Board_detail.clear state.board_detail;
  state.board_history_post_id <- None;
  state.board_focus <- focus;
  state.board_scroll <- 0;
  state.board_comment_scroll <- 0;
  state.board_comment_landing <- None;
  state.board_comments_focused <- false;
  state.board_attachment_status <- None;
  state.board_image_selection <- None;
  owe_board_post_read state ~mailbox ~post_id

let open_board_post state ~mailbox ~focus (post : board_post) =
  open_board_post_id state ~mailbox ~focus post.bp_id

let move_board_read_scroll state ~by =
  if state.board_comments_focused then
    state.board_comment_scroll <-
      Masc_tui_scroll.step_uncounted ~delta:by state.board_comment_scroll
  else state.board_scroll <- Masc_tui_scroll.step_uncounted ~delta:by state.board_scroll


(* j/k on the reading. With the comments focused they step the cursor one
   comment along the drawn thread; the frame then scrolls the least that
   shows it. PgUp/PgDn keep scrolling by rows, and so does a wheel notch
   that arrives as a key, so a comment longer than the column stays
   readable. *)
let step_board_reading state ~post_id ~by_wheel ~delta =
  if state.board_comments_focused && not by_wheel then
    match Masc_tui_work_actions.Board_schedule_actions.board_read_thread state ~post_id with
    | None -> ()
    | Some (ids, landing) ->
        state.board_comment_cursor <-
          Masc_tui_board_comment_cursor.move ids ~landing
            state.board_comment_cursor ~delta;
        state.board_comment_follow <- true
  else move_board_read_scroll state ~by:delta

let move_board_posts_pane state ~mailbox ~delta =
  let count = List.length (board_posts state) in
  let next = max 0 (min (count - 1) (state.board_cursor + delta)) in
  if count > 0 && next <> state.board_cursor then begin
    state.board_cursor <- next;
    Option.iter
      (open_board_post state ~mailbox ~focus:Left_pane)
      (List.nth_opt (board_posts state) next)
  end

(* The next post without leaving the one being read. Reading a board meant
   Esc, move, Enter for every post, which is three keys to do what one does on
   Changes and on the Keeper detail tabs -- both of which already spell it
   [ / ]. Focus is carried rather than reset: an operator reading in the wide
   detail stays there, and one browsing from the list pane stays in the list. *)
let step_board_read state ~mailbox ~delta =
  match state.board_mode with
  | Board_list | Board_compose -> ()
  | Board_read _ ->
      let count = List.length (board_posts state) in
      let next = max 0 (min (count - 1) (state.board_cursor + delta)) in
      if count > 0 && next <> state.board_cursor then begin
        state.board_cursor <- next;
        Option.iter
          (open_board_post state ~mailbox ~focus:state.board_focus)
          (List.nth_opt (board_posts state) next)
      end

let board_attachment_digit_of_key = function
  | "1" -> Some 1
  | "2" -> Some 2
  | "3" -> Some 3
  | "4" -> Some 4
  | "5" -> Some 5
  | "6" -> Some 6
  | "7" -> Some 7
  | "8" -> Some 8
  | "9" -> Some 9
  | _ -> None

let board_diagram_selection state =
  Option.bind (board_diagram_subject state) (fun subject ->
    let body = match subject with
      | Board_post_diagram {body;_} | Board_comment_diagram {body;_} -> body in
    let diagrams = Masc_tui_markdown.mermaid_sources body in
    match diagrams with
    | [] -> None
    | _ ->
        let index = match state.board_diagram_cursor with
          | Some (owner, index) when owner = subject ->
              max 0 (min (List.length diagrams - 1) index)
          | Some _ | None -> 0 in
        Some (subject, diagrams, index))

let step_board_diagram state ~delta =
  match board_diagram_selection state with
  | None -> state.board_attachment_status <- Some "No closed Mermaid diagram in the selected post or comment"
  | Some (subject, diagrams, index) ->
      let count = List.length diagrams in
      let next = max 0 (min (count - 1) (index + delta)) in
      state.board_diagram_cursor <- Some (subject, next);
      state.board_attachment_status <- Some
        (Printf.sprintf "Mermaid %d/%d · Ctrl-O: preview" (next + 1) count)

let open_board_diagram state ~mailbox =
  let notice = image_notice state ~view:Board ~keeper_name:None in
  match board_diagram_selection state with
  | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "No closed Mermaid diagram in the selected post or comment"
  | Some (subject, diagrams, index) ->
      Option.iter (fun source ->
        open_preview_image ~board_subject:(Board_diagram subject) state ~mailbox ~notice
          ~name:(Printf.sprintf "Mermaid %d/%d" (index + 1) (List.length diagrams))
          (Masc_tui_image_requests.Generated (Masc_tui_image_preview.mermaid_source source)))
        (List.nth_opt diagrams index)

(* The numbered attachment keys: the pane names each entry [1..9] (broken
   entries included), and this resolves the same number to the same entry,
   then lets the action module save/play/open it. What happened, or why it
   could not, lands on the read pane's status line. *)
let open_board_attachment state ~mailbox ~digit ~host ~port =
  match state.board_mode with
  | Board_list | Board_compose -> ()
  | Board_read post_id ->
      let post =
        match Board_detail.view_for state.board_detail ~post_id with
        | Board_detail.Ready (detail_post, _, _) -> Some detail_post
        | Board_detail.Absent | Board_detail.Loading | Board_detail.Failed _ ->
            List.find_opt
              (fun (candidate : board_post) -> String.equal candidate.bp_id post_id)
              (board_posts state)
      in
      (match post with
       | None -> ()
       | Some post ->
           (match Masc_tui_board_attachments.attachment_at_index post.bp_attachments digit with
            | None -> ()
            | Some (Error reason) ->
                state.board_attachment_status <-
                  Some (ui_text state ~ko:"깨진 첨부: " ~en:"Broken attachment: " ^ reason)
            | Some (Ok ({ba_kind=Ak_image;ba_source=As_artifact {sha256;bytes};ba_name} as attachment)) ->
                let notice = image_notice state ~view:Board ~keeper_name:None in
                let key = {Masc_tui_board_reader.post_id;sha256;bytes;name=ba_name} in
                let subject=Board_attachment_image {post_id;attachment} in
                state.board_image_selection <- Some subject;
                state.board_attachment_status <- Some "O: original image";
                open_preview_image ~board_subject:subject
                  state ~mailbox ~notice ~name:(Option.value ba_name ~default:"Board image")
                  (Masc_tui_image_requests.Board_artifact key)
            | Some (Ok ({ba_kind=(Ak_file|Ak_score as kind);ba_source=As_artifact {sha256;bytes};ba_name} : board_attachment)) ->
                launch_board_read state ~mailbox ~kind {Masc_tui_board_reader.post_id;sha256;bytes;name=ba_name}
            | Some (Ok ({ba_kind=(Ak_file|Ak_score);ba_source=As_url _;_} as attachment))
            | Some (Ok ({ba_kind=(Ak_image|Ak_video|Ak_youtube|Ak_external_link|Ak_audio|Ak_midi|Ak_unknown _);_} as attachment)) ->
                let fetch ~sha256 =
                  match
                    Masc_tui_http.http_get_with_body_limit
                      ~max_body_bytes:(Some Masc_tui_board_upload.max_attachment_bytes)
                      ~host ~port
                      ~path:("/api/v1/artifact-bytes/" ^ sha256)
                  with
                  | Error reason -> Error reason
                  | Ok (status_code, body)
                    when Masc.Tui_decode.is_success_http_status status_code ->
                      Ok body
                  | Ok (status_code, body) ->
                      Error (Masc_tui_http.refusal ~status_code ~body)
                in
                let outcome =
                  Masc_tui_attachment_action.run ~fetch attachment
                    ~midi_soundfont:!boot_midi_soundfont
                in
                state.board_attachment_status <-
                  Some (Masc_tui_attachment_action.describe_outcome outcome)))

let apply_approval_decision_result state approval decision approvals result =
  (match state.home_decision_inflight with
   | Some (Home_operator_request token as request) when token = approval.ap_token ->
       let receipt = match result with
         | Ok (Approval.Completed _) -> approval_decision_done decision ^ ": " ^ approval.ap_summary
         | Ok (Approval.Deferred _) -> "Confirmation accepted; action deferred: " ^ approval.ap_summary
         | Ok (Approval.Execution_failed (_, detail)) -> "Confirmation accepted; action failed: " ^ approval.ap_summary ^ " · " ^ detail
         | Error (Request_failed error) -> approval_decision_unverified decision ^ ": " ^ approval.ap_summary ^ " · " ^ error
         | Error (Request_withdrawn refusal) ->
             workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
               ~request:Kept_request.Approval_decision refusal
             ^ " · " ^ approval.ap_summary
       in
       state.home_decision_receipt <- Some (request, receipt)
   | Some (Home_held_call _ | Home_gate_request _ | Home_operator_request _
          | Home_question _ | Home_goal_confirmation _)
   | None -> ());
  state.home_decision_inflight <- None;
  (match result with
   | Ok (Approval.Completed _) ->
       report_action state "system"
         (Printf.sprintf "%s: %s" (approval_decision_done decision)
            approval.ap_summary)
   | Ok (Approval.Deferred _) ->
       report_action state "system"
         (Printf.sprintf "Confirmation accepted; action deferred: %s"
            approval.ap_summary)
   | Ok (Approval.Execution_failed (_, detail)) ->
       report_action state "error"
         (Printf.sprintf "Confirmation accepted; action failed: %s" detail)
   | Error (Request_failed err) ->
       report_action state "error"
         (Printf.sprintf "%s: %s" (approval_decision_unverified decision) err)
   | Error (Request_withdrawn refusal) ->
       Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Approval_decision refusal);
  Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_approvals_load state (Result.map_error (fun detail -> Request_failed detail) approvals)

let apply_approval_decision_completion state generation approval decision result
    approvals =
  state.pending_approval_action <- None;
  let flow, owns_action =
    Approval.Flow.finish_action state.approval_flow generation
  in
  state.approval_flow <- flow;
  if owns_action then
    apply_approval_decision_result state approval decision approvals result

let start_approval_decision state approval decision ~mailbox =
  let enqueue_async = Masc_tui_transport.Workspace_admission.workspace_enqueue state in
  let authority = state.workspace_authority in
  let identity = state.server_identity in
  let reading = Some state.workspace_read_authority in
  if state.workspace_identity <> Workspace_identity_match then
    Masc_tui_transport.Request_notice.report_kept_back state ~request:Kept_request.Approval_decision workspace_identity_unconfirmed Nothing_kept
  else
  match Approval.Flow.begin_action state.approval_flow with
  | Error `Already_inflight ->
      state.pending_approval_action <- None;
      report_action state "system" "Approval action already in progress"
  | Ok (flow, generation) ->
    let () = state.approval_flow <- flow in
    let () = state.pending_approval_action <- None in
    Masc_tui_work_requests.Approval_gate_requests.supersede_home_decision_receipt state;
    state.home_decision_inflight <- state.home_opened_request;
    let host = Masc_tui_transport.Workspace_admission.server_peer_host in
    let port = state.port in
    let confirm () =
      match Masc_tui_transport.Workspace_admission.admit_request state ~mailbox ~authority ~identity ~host ~port () with
      | Error refusal -> Error (Request_withdrawn refusal)
      | Ok () ->
        Result.map_error (fun detail -> Request_failed detail)
          (Masc_tui_http.post_operator_confirm ~host ~port
             ~token:approval.ap_token ~decision)
    in
    let reload () =
      if workspace_reply_admitted state ~authority ~reading ~kind:Workspace_observation
      then load_approvals ~host ~port
      else Error "Approval result retained; workspace identity is unconfirmed"
    in
    let run_action () =
      let result =
        try
          confirm ()
        with
        | Eio.Cancel.Cancelled _ as exn -> raise exn
        | exn -> Error (Request_failed (Printexc.to_string exn))
      in
      let approvals =
        try
          reload () with
        | Eio.Cancel.Cancelled _ as exn -> raise exn
        | exn -> Error ("approvals reload failed: " ^ Printexc.to_string exn)
      in
      enqueue_async mailbox
        (Approvals_msg (Approval_decision_done (approval, decision, result, generation, approvals)))
    in
    match Eio_context.get_switch_opt () with
    | Some sw -> Masc_tui_transport.Workspace_admission.fork_job state ~mailbox ~sw run_action
    | None ->
        let result =
          try
            confirm ()
          with exn -> Error (Request_failed (Printexc.to_string exn))
        in
        let approvals =
          try
          reload () with
          | exn -> Error ("approvals reload failed: " ^ Printexc.to_string exn)
        in
        let result, approvals = workspace_operation_reply state ~authority ~reading (result, approvals) in
        apply_approval_decision_completion state generation approval decision
          result approvals

(* TEL-OK: TUI-local confirmation gate emits user-visible events here; the
   operator confirmation endpoint owns durable approval telemetry. *)
let handle_approval_decision state approval decision ~mailbox =
  match
    Approval.approval_gate_transition
      ~inflight:(Approval.Flow.action_inflight state.approval_flow)
      ~pending:state.pending_approval_action ~token:approval.ap_token ~decision
  with
  | Approval.Gate_blocked_inflight ->
      state.pending_approval_action <- None;
      report_action state "system" "Approval action already in progress"
  | Approval.Gate_submit ->
      start_approval_decision state approval decision ~mailbox
  | Approval.Gate_arm pending ->
      state.pending_approval_action <- Some pending;
      report_action state "system"
        (Printf.sprintf "Press %s again: %s"
           (approval_decision_key decision)
           approval.ap_summary)

let toggle_selected_ask_origin state =
  match current_ask_origin state with
  | Some _ -> state.ask_origin <- None
  | None ->
      let origin = selected_ask_origin state in
      (match origin with
       | None -> report_action state "system" "No Keeper turn asked this question"
       | Some origin ->
           Masc_tui_types.toggle_ask_origin state origin;
           state.ask_question_scroll <- 0;
           Option.iter (fun origin ->
             Log.Transport.info "tui_ask_source=%s"
               (Yojson.Safe.to_string (`Assoc
                 ["opened_ns",`String (Int64.to_string (Mtime_clock.elapsed_ns ()));
                  "origin",Ask.origin_to_json origin]))) (current_ask_origin state))

(* A server action belongs to the Keeper that submitted it even when its
   completion arrives after navigation. Keep offscreen outcomes in the action
   record; they cannot replace the selected Keeper's notice. *)
let present_identity_notice state ~keeper_name (kind, text) =
  match keeper_name with
  | Some name when keeper_detail_target_matches state name ->
      state.identity_attempt_error <- Some (kind, text)
  | Some name -> report_action state "system" (name ^ ": " ^ text)
  | None -> report_action state "system" text

let rec apply_async_message ~server_contact ?(input_pending = fun () -> false) ?(image_input_pending = fun () -> false)
    state ~base_path ~http_refresh_inflight
    ~http_scoped_refresh_inflight ~scoped_refresh_followup ~mailbox =
  fun message ->
    let drawn =
      Masc_tui_types.preserve_keeper_list_selection state (fun () ->
        apply_async_message_body ~server_contact ~input_pending ~image_input_pending state ~base_path ~http_refresh_inflight
          ~http_scoped_refresh_inflight ~scoped_refresh_followup ~mailbox message)
    in
    Masc_tui_transport.Event_streams.reconcile_observer_recovery state ~refresh_inflight:!http_refresh_inflight ~mailbox;
    drawn
and apply_async_message_body ~server_contact ?(input_pending = fun () -> false) ?(image_input_pending = fun () -> false)
    state ~base_path ~http_refresh_inflight
    ~http_scoped_refresh_inflight ~scoped_refresh_followup ~mailbox =
  function
  | Workspace_scoped (authority, reading, message) ->
      if workspace_message_admitted state ~authority ~reading message then begin
        let retry = retired_operation_observation state ~authority ~reading message in
        let message = project_workspace_operation_reply state ~authority ~reading message in
        let drawn =
          apply_async_message ~server_contact ~input_pending ~image_input_pending state ~base_path ~http_refresh_inflight
            ~http_scoped_refresh_inflight ~scoped_refresh_followup ~mailbox message
        in
        match retry with
        | Some retry when retain_operation_observation state retry
            && server_authority_ready state ->
            (match retry with
             | Browser_scene_observation (_, _, operation) ->
                 state.browser_lane_read_resume <- None;
                 Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox operation
             | Lane_subscriptions_observation _ ->
                 state.lane_nested_read_resume <- None;
                 Masc_tui_surface_requests.Lane_browser_requests.launch_lane_subscriptions state ~mailbox Masc_tui_lane_subscriptions.Inspect);
            Drawn_changed
        | Some _ | None -> drawn
      end else begin (match message with
        (* The read answers nothing the screen may use, but it is over: its
           slot is freed, so the roster's owed read starts again once the
           server's authority is back. *)
        | Keeper_msg (Keeper_roster_reloaded observation) ->
          ignore (Masc_tui_types.take_keeper_roster_observation state observation)
        | Keeper_msg (Keeper_row_reloaded observation) ->
          ignore (Masc_tui_types.take_keeper_row_observation state observation)
        | Gate_msg (Gate_snapshot_loaded (request, _, _)) ->
          Log.Transport.debug "discarded Gate snapshot request=%d: workspace authority superseded"
            (Snapshot_read.request_id request)
        | Keeper_msg (Keeper_chat_dispatch_started (_, _, acknowledge)) ->
          ignore (Eio.Promise.try_resolve acknowledge false)
        | Keeper_msg (Keeper_chat_done (_, _, _, acknowledge)) ->
          ignore (Eio.Promise.try_resolve acknowledge ())
        | Workspace_operation (Goal_msg (Goal_transition_done (goal_id, ticket, workspace, result))) ->
          record_goal_action_receipt state ~goal_id ~ticket ~workspace result;
          report_action state "error" ("Goal " ^ goal_id ^ " from " ^ workspace
            ^ ": a request outcome arrived after workspace authority was withdrawn; inspect Work summary")
        | Workspace_operation (Goal_msg (Goal_confirmation_submitted (goal_id, ticket, workspace, authority, result))) ->
          record_goal_action_receipt ~authority state ~goal_id ~ticket ~workspace result;
          report_action state "error" ("Goal " ^ goal_id ^ " from " ^ workspace
            ^ ": a confirmation outcome arrived after workspace authority was withdrawn; inspect Work summary")
        | Workspace_operation (Resource_msg (Resource_saved (request, outcome))) ->
          (* The local write already owns its original tuple. Withdrawal
             removes read authority, not this outcome or its registered slot. *)
          ignore (settle_resource_save state request outcome)
        | Workspace_operation (Resource_msg (Resource_share_changed (request, result))) ->
          if resource_share_is_owned state request then begin
            let read_key = finish_resource_share state request result in
            (match result with
             | Ok (Resource_share_applied shared) -> report_action state "system"
                 ("External sharing request to " ^ (if request.share_target then "enable" else "revoke")
                  ^ " applied in the original workspace for " ^ request.share_report.id
                  ^ (if shared then "; enabled at response" else "; disabled at response"));
                 Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key
             | Ok (Resource_share_conflict shared) -> report_action state "system"
                 ("External sharing request to " ^ (if request.share_target then "enable" else "revoke")
                  ^ " conflicted in the original workspace for " ^ request.share_report.id
                  ^ (if shared then "; enabled at response" else "; disabled at response"));
                 Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key
             | Ok (Resource_share_not_prepared detail) -> report_action state "system"
                 ("The share request for " ^ request.share_report.id ^ " was not recorded or sent: " ^ detail);
                 Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key
             | Ok (Resource_share_not_sent detail) -> report_action state "system"
                 ("The share request for " ^ request.share_report.id ^ " did not send. The recorded operation may still apply; use U to reconcile: " ^ detail);
                 Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key
             | Ok (Resource_share_kept_back refusal) ->
                 report_resource_share_kept_back state request refusal;
                 Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key
             | Error (Resource_share_unknown detail) -> report_action state "error"
                 ("Previous workspace external sharing result unconfirmed for " ^ request.share_report.id
                  ^ "; use U to reconcile the recorded operation: " ^ detail)
             | Error (Resource_share_not_started detail) -> report_action state "system"
                 (if request.share_recovery then
                    "The recovery attempt for " ^ request.share_report.id ^ " did not start; the original operation may still apply: " ^ detail
                  else "The share request for " ^ request.share_report.id ^ " did not start or send: " ^ detail);
                 Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key)
          end
        | Play_msg (Play_invite_issued (request, _, Play_answered (Ok invite))) ->
          (match
             Masc_tui_play_card.make
               ~project:Masc_tui_play_card.project_for_terminal
               ~name:invite.Tui_decode.pii_name
               ~expires_at:invite.pii_expires_at ~link:invite.pii_link
           with
           | Ok card -> Masc_tui_types.retain_withdrawn_play_invite state request card
           | Error _ -> ())
        | Code_msg answer ->
          (match Code_results.answer_kind answer with
           | Code_results.(Read | Save) -> ())
        | Context_msg answer ->
          (match Context_results.answer_kind answer with
           | Context_results.Read -> ())
        | Fleet_msg answer ->
          (match Fleet_results.answer_kind answer with
           | Fleet_results.Read -> ())
        | Original_msg answer ->
          (match Original_results.answer_kind answer with
           | Original_results.Read -> ())
        | Play_msg (Play_invite_issued (_, _, Play_answered (Error _))
        | Play_invite_issued (_, _, (Play_refused _ | Play_not_dispatched _ | Play_unanswered _
                                     | Play_kept_back _)))
        | (Approvals_msg Approvals_listing_superseded) | (Keeper_msg Keeper_composer_released)
        | Chat_msg (Chat_search_finished (_, _, _, _)) | Workspace_scoped (_, _, _) | Workspace_operation _
        | Chat_command_read_completed (_, _) | Workspace_msg (Workspace_identity_unconfirmed _)
        | Schedule_msg (Schedule_form_authority_refused _) | Lane_msg (Lane_package_catalog_loaded (_, _, _)
        | Lane_package_preview_loaded (_, _, _)) | Keeper_msg (Keeper_queue_resume_confirmed (_, _, _, _)
        | Keeper_queue_action_received _
        | Keeper_queue_loaded (_, _, _, _)) | Lane_msg (Lane_addons_loaded (_, _, _)
        | Lane_application_loaded (_, _) | Lane_subscriptions_loaded (_, _)
        | Lane_declaration_loaded (_, _, _, _, _)) | Keeper_msg (Keeper_deletions_loaded (_, _))
        | Keeper_msg (Keeper_deletion_retry_done (_, _)) | Msx_msg (Msx_live_loaded (_, _)) | Dos_live_loaded (_, _)
        | Voice_msg (Voice_wizard_saved (_, _) | Voice_agent_voices_loaded _ | Voice_agent_voice_saved _
        | Voice_wizard_probed (_, _) | Voice_wizard_reread (_, _) | Voice_config_loaded (_, _, _)
        | Voice_calibrated _ | Voice_level _ | Voice_transcribed _ | Voice_silent _ | Voice_discarded _ | Voice_failed _)
        | (Http_msg (Http_keeper_roster_loaded _ | Http_dataset_loaded _) | Http_surface_read_completed _ | Http_msg (Http_initial_identity_read _ | Http_asks_loaded _ | Http_approvals_loaded _) | Ask_msg (Ask_answer_receipt_ready _ | Ask_followup_observed _ | Ask_followup_finished _) | Http_msg (Http_refresh_done _)) | Http_msg (Http_refresh_failed (_, _, _))
        | Approvals_msg (Approvals_summary_loaded (_, _, _, _)) | Http_msg (Http_scoped_refresh_done (_, _, _)
        | Http_scoped_refresh_failed (_, _, _, _, _, _)) | Board_msg (Board_post_refresh_done (_, _))
        | Approvals_msg (Approval_decision_done (_, _, _, _, _)) | Ask_msg (Ask_answer_done (_, _, _))
        | Keeper_msg (Keeper_chat_stream_deltas (_, _) | Keeper_chat_stream_unavailable (_, _)
        | Keeper_run_next_done (_, _) | Keeper_observed_interrupt_done (_, _, _, _)
        | Keeper_chat_interrupt_done (_, _, _)) | (Keeper_msg (Keeper_chat_history_loaded (_, _, _) | Keeper_chat_first_page_loaded (_, _)))
        | Keeper_msg (Keeper_chat_copy_loaded (_, _, _) | Keeper_chat_operation_loaded _
        | Keeper_chat_journal_loaded _ | Keeper_native_tasks_loaded (_, _)
        | Keeper_child_content_loaded (_, _) | Keeper_preparation_loaded (_, _))
        | Keeper_msg (Keeper_chat_older_loaded (_, _, _, _)) | Local_msg (Local_workspace_read (_, _) | Local_keepers_read (_, _)) | Live_context_loaded (_, _, _) | (Keeper_msg (Keeper_logs_loaded _ | Keeper_execute_streamed _)) | Keeper_msg (Keeper_composite_loaded (_, _, _))
        | Lane_msg (Lane_inventory_loaded (_, _)) | Clients_loaded (_, _) | Lane_msg (Lane_runs_loaded (_, _, _, _)
        | Lane_run_detail_loaded (_, _, _)) | Measurement_artifact_loaded (_, _, _)
        | Verification_msg (Verification_loaded _) | Harness_msg (Harness_loaded _) | Overview_loaded _ | Engine_sample_read _ | Fusion_msg (Fusion_runs_loaded (_, _)
        | Fusion_detail_loaded (_, _, _) | Fusion_historical_detail_loaded (_, _, _)
        | Fusion_launch_options_loaded (_, _) | Fusion_launched (_, _))
        | Memory_msg (Memory_recall_standing_loaded (_, _)) | Repository_msg (Repositories_loaded _)
        | Workspace_msg (Workspace_activity_loaded (_, _)) | Memory_msg (Memory_loaded _ | Memory_input_loaded (_, _)
        | Memory_world_loaded (_, _) | Memory_facts_loaded (_, _)) | Repository_msg (Repository_changes_loaded (_, _)
        | Repository_changes_diff_loaded (_, _)) | File_changes_loaded (_, _)
        | Keeper_msg (Keeper_chat_file_changes_loaded (_, _, _)) | Git_diff_loaded (_, _)
        | Browser_msg (Browser_history_list_loaded (_, _) | Browser_history_page_loaded (_, _)
        | Browser_lane_clients_loaded (_, _) | Browser_lane_loaded (_, _)
        | Browser_lane_scene_loaded (_, _)
        | Browser_lane_follow_loaded (_, _) | Browser_lane_screenshot_ready _)
        | Connectors_msg (Connectors_status_loaded (_, _) | Connectors_loaded (_, _) | Connector_unbind_all_done _) | Tools_msg (Tools_volume_gc_reclaimed _) | Runtime_msg (Runtime_surface_loaded (_, _))
        | Tools_msg (Tools_read_loaded _) | Skill_evidence_loaded (_, _, _)
        | (Tools_msg (Tools_async_observation_loaded (_, _)) | ((Tools_msg (Tools_async_detail_loaded _) | Task_msg (Task_document_prepared _)) | Tools_msg (Tools_async_task_body_loaded _ | Tools_async_task_history_loaded _ | Tools_volume_gc_reported _))) | Runtime_msg (Runtime_lane_slots_written (_, _, _)
        | Runtime_catalog_loaded (_, _) | Runtime_assignment_changed (_, _, _))
        | Keeper_msg (Keeper_chat_approval_answered (_, _, _, _) | Keeper_tool_approvals_loaded (_, _, _)) | Ask_msg (Asks_reloaded _)
        | Listen_prepared _ | Sent_image_ready _ | Image_render_ready _ | Keeper_msg (Keeper_turns_loaded _ | Keeper_waiting_loaded _
        | Keeper_chat_control_received (_, _, _)) | Gate_msg (Gate_approval_resolved (_, _, _, _, _)
        | Gate_auto_judge_retried (_, _, _, _) | Gate_mode_set (_, _, _))
        | Keeper_msg (Keeper_tool_approval_answered (_, _, _, _, _, _)
        | Keeper_tool_modes_loaded (_, _) | Keeper_tool_mode_set (_, _, _, _)
        | Keeper_chat_dispatch_blocked (_, _)) | Runtime_msg (Runtime_form_save_changed _) | Keeper_msg (Keeper_settings_save_changed _ | Keeper_creation_changed _
        | Keeper_action_done (_, _, _, _))
        | (Board_msg (Board_publication_done _ | Board_comment_done _)) | (Board_msg (Board_vote_done _) | Artifact_msg (Artifact_check_changed _)) | Goal_msg (Goal_transition_done _
        | Goal_confirmation_submitted _ | Goal_confirmation_loaded (_, _)) | Schedule_msg (Schedules_loaded (_, _)
        | Schedule_wake_history_loaded (_, _)) | Keeper_msg (Keeper_schedules_loaded (_, _) | Keeper_story_turns_loaded (_, _) | Keeper_memory_activity_loaded (_, _))
        | System_log_streamed _ | Schedule_msg (Schedule_cancel_done (_, _)) | Verification_msg (Verification_verdict_done _)
        | Harness_msg (Harness_label_done _) | Board_msg (Board_attachment_loaded _ | Board_attachment_prepared _ | Board_attachment_saved _) | Chat_msg (Chat_call_loaded _) | Keeper_msg (Keeper_calls_loaded (_, _, _)) | Goal_msg (Goal_timeline_loaded (_, _) | Goal_candle_loaded (_, _))
        | Task_msg (Task_history_loaded (_, _) | Task_cancel_done (_, _, _))
        | Verification_msg (Verification_evidence_loaded (_, _) | Verification_evidence_exported _) | Keeper_msg (Keeper_settings_editor_loaded _ | Keeper_config_view_loaded (_, _)
        | Keeper_items_loaded (_, _) | Keeper_sandbox_view_loaded (_, _)
        | Keeper_sandbox_logs_loaded (_, _, _)) | Exact_msg (Exact_activity_read (_, _)
        | Exact_activity_saved (_, _))
        | Machine_msg (Machine_activity_read (_, _) | Machine_activity_saved (_, _))
        | Runtime_msg (Runtime_config_view_loaded (_, _, _, _, _) | Runtime_params_loaded _
        | Runtime_param_written (_, _)) | Prompts_loaded (_, _)
        | Keeper_msg (Keeper_board_quarantines_loaded (_, _) | Keeper_efficiency_loaded (_, _)) | Board_msg (Board_quarantine_requeued (_, _, _)
        | Board_quarantines_bulk_progress (_, _)
        | Board_quarantines_bulk_requeued (_, _)) | Preset_msg (Presets_listed (_, _)
        | Preset_detail_loaded (_, _) | Preset_contents_shown (_, _) | Preset_saved (_, _)
        | Preset_restored (_, _) | Preset_deleted (_, _)) | Play_msg (Play_room_received (_, _)
        | Play_invites_listed (_, _) | Play_invite_revoked (_, _, _, _))
        | Librarian_input_loaded (_, _) | (Resource_msg (Resources_listed _) | Artifact_msg (Artifact_checks_loaded _))
        | Acting_pane_changes_loaded (_, _)
        | Resource_msg (Resource_exported _ | Resource_saved _ | Resource_share_changed _ | Resource_share_recovery_loaded _ | Resource_read (_, _, _) | Resource_diagram_ready _) | Github_msg (Github_identity_view_loaded (_, _))
        | Identity_msg (Identity_providers_loaded (_, _, _) | Identity_switch_set (_, _, _, _)
        | Identity_login_started (_, _) | Identity_refreshed (_, _) | Identity_app_saved (_, _, _)
        | Identity_disconnected (_, _, _))
        | Account_msg (Account_login_event (_, _, _) | Account_login_json (_, _, _, _)
        | Account_login_batch_step (_, _, _, _) | Account_login_removal (_, _, _, _, _)) | Github_msg (Github_login_lines (_, _)
        | Github_login_finished (_, _) | Github_token_saved (_, _)) | Observer_msg (Observer_session_ready _ | Observer_opened _
        | Observer_received (_, _) | Observer_closed _ | Observer_retry_due _ | Observer_recovery_ready _ | Observer_recovery_opened _ | Observer_found_account_server _ | Observer_recovery_identity _) | Task_msg (Task_dispatch_completed _ | Task_creation_read_done _) -> ());
        Drawn_changed
      end
  | Chat_command_read_completed (ticket, message) ->
      if List.exists (fun (pending, _, _) -> pending == ticket) state.chat_command_reads then begin
        state.chat_command_reads <- List.filter (fun (pending, _, _) -> pending != ticket) state.chat_command_reads;
        apply_async_message ~server_contact ~input_pending ~image_input_pending state ~base_path ~http_refresh_inflight
          ~http_scoped_refresh_inflight ~scoped_refresh_followup ~mailbox message
      end else Drawn_changed
  | Workspace_operation message ->
      apply_async_message ~server_contact ~input_pending ~image_input_pending state ~base_path ~http_refresh_inflight
        ~http_scoped_refresh_inflight ~scoped_refresh_followup ~mailbox message
  | Workspace_msg (Workspace_identity_unconfirmed { refusal; latest; prior_contact; refresh_ticket }) ->
      if Http_refresh_order.is_current state.http_refresh_order refresh_ticket then begin
      (* What the guard saw of the identity, in the screen language. The
         request it stopped says its own kept-back notice (RFC §2). *)
      let detail = String.capitalize_ascii
          (workspace_refusal_reason ~ko:(state.ui_language = Lang_ko) refusal) in
      let authority = read_authority state in
      apply_refused_workspace_identity state ~mailbox ~detail (Some latest);
      state.connection_status <-
        (match latest, prior_contact with
         | Ok _, _ | Error _, Masc_tui_server_lifecycle.Server_reached -> Masc_tui_types.Degraded
         | Error _, (Masc_tui_server_lifecycle.Nothing_answered | Undecided) -> Masc_tui_types.Disconnected);
      resume_reads_after_authority_change ~server_contact state ~mailbox
        ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup
        ~before:authority;
      report_action state "error" detail
      end;
      Drawn_changed
  | Schedule_msg (Schedule_form_authority_refused {change; refusal; workspace}) ->
      (* Identity observation is delivered separately under its read epoch. *)
      let form_refusal =
        { sfr_change = change; sfr_reason = Schedule_form_request (Request_withdrawn refusal)
        ; sfr_at = Unix.gettimeofday (); sfr_workspace = workspace } in
      state.schedule_form_refusal <- Some form_refusal;
      report_action state "error"
        (schedule_form_refusal_text ~ko:(state.ui_language = Lang_ko) form_refusal);
      Drawn_changed
  | Lane_msg (Lane_package_catalog_loaded (generation,directory,result)) ->
      Masc_tui_surface_requests.Lane_browser_requests.map_lane_addons state (fun view ->
        if view.generation<>generation then view else
        let receive result =
          let response = Option.bind view.installer
            (Masc_tui_lane_installer.receive_catalog ~request_id:generation ~directory result) in
          match response with
          | None -> view
          | Some (installer,error) ->
              {view with loading=false;installer=Some installer;
                package_directory=Masc_tui_lane_installer.directory installer;
                error=Option.bind error Masc_tui_surface_requests.Lane_browser_requests.lane_addons_detail_failure;scroll=0} in
        match result with
        | Ok json -> receive (Ok json)
        | Error (Request_failed detail) -> receive (Error detail)
        | Error (Request_withdrawn refusal) ->
            Masc_tui_surface_requests.Lane_browser_requests.lane_installer_kept_back state view
              (Masc_tui_lane_installer.Read_catalog directory) refusal);
      Drawn_changed
  | Lane_msg (Lane_package_preview_loaded (generation,path,result)) ->
      Masc_tui_surface_requests.Lane_browser_requests.map_lane_addons state (fun view ->
        if view.generation<>generation then view else
        let receive result =
          let response = Option.bind view.installer
            (Masc_tui_lane_installer.receive_preview ~request_id:generation ~path result) in
          match response with
          | None -> view
          | Some (installer,error) ->
              {view with loading=false;installer=Some installer;
                error=Option.bind error Masc_tui_surface_requests.Lane_browser_requests.lane_addons_detail_failure;scroll=0} in
        match result with
        | Ok json -> receive (Ok json)
        | Error (Request_failed detail) -> receive (Error detail)
        | Error (Request_withdrawn refusal) ->
            Masc_tui_surface_requests.Lane_browser_requests.lane_installer_kept_back state view
              (Masc_tui_lane_installer.Read_preview path) refusal);
      Drawn_changed
  | Keeper_msg (Keeper_queue_resume_confirmed (keeper_name, generation, confirmation, request_ids)) ->
      settle_keeper_priority_control state keeper_name ~generation
        ~outcome:(match confirmation with
          | Owner_resumed -> Priority_superseded
          | Owner_already_active -> Priority_unconfirmed);
      if finish_keeper_chat_control state keeper_name ~generation then begin
        (match confirmation with
         | Owner_resumed -> clear_keeper_priority_requests state keeper_name
         | Owner_already_active ->
           (match state.queue_panel with
            | Some panel when String.equal panel.qp_keeper keeper_name ->
              state.queue_panel <- Some {panel with qp_receipt=Some (Queue_read_receipt "Keeper is active; retained input released")}
            | Some _ | None ->
              Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:(Some keeper_name) ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
                "Keeper is active; retained input released"));
        release_retained_keeper_input state keeper_name ~request_ids;
        Masc_tui_chat_dispatch.Queue_steer.launch_waiting_keeper_input state ~mailbox ~keeper_name;
        Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~change:(Waiting_keepers [keeper_name]) state ~mailbox;
        Masc_tui_chat_dispatch.Queue_steer.dispatch_ready_run_next state ~mailbox keeper_name
      end;
      Drawn_changed
  | Keeper_msg (Keeper_queue_action_received (keeper_name, receipt)) ->
      if not (List.mem keeper_name state.keeper_queue_readings) then
        state.keeper_queue_readings <- keeper_name :: state.keeper_queue_readings;
      (match state.queue_panel with
       | Some panel when String.equal panel.qp_keeper keeper_name ->
         state.queue_panel <- Some
           {panel with qp_receipt=(if receipt = [] then panel.qp_receipt
             else Some (Queue_action_receipt (Queue_info (String.concat " · " receipt))));
             qp_notice=(if server_authority_ready state then
                 Some (Queue_info "Refreshing the queue after the change") else panel.qp_notice)}
       | Some _ | None ->
         if receipt <> [] then Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:(Some keeper_name)
           ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply (String.concat " · " receipt));
      Masc_tui_chat_dispatch.Queue_steer.dispatch_ready_run_next state ~mailbox keeper_name;
      Drawn_changed
  | Keeper_msg (Keeper_queue_loaded (keeper_name, _, Masc_tui_queue_inspection.Inspect_peers (token, _), result)) ->
      let observation = match result with
        | Error failure -> Error failure
        | Ok (_, Error reason) -> Error (Request_failed reason)
        | Ok (_, Ok observation) ->
            (match observation.operations, observation.peer_page with
             | Error reason, _ -> Error (Request_failed reason)
             | Ok _, Some page -> Ok page
             | Ok _, None -> Error (Request_failed "Keeper relationship page is unavailable")) in
      ignore (stage_keeper_peer_reading state ~keeper_name ~token observation);
      Drawn_changed
  | Keeper_msg (Keeper_queue_loaded (keeper_name, control_generation,
      ((Masc_tui_queue_inspection.Inspect | Pause | Resume | Clear | Cancel _ | Move_to_end _
       | Run_next _ | Edit _ | Cancel_event _ | Prioritize_event _) as action), result)) ->
      Option.iter (fun generation -> settle_keeper_priority_control state keeper_name
        ~generation ~outcome:(match result with
          | Ok ([], _) when action = Masc_tui_queue_inspection.Resume -> Priority_unconfirmed
          | Ok _ -> Priority_superseded | Error _ -> Priority_unconfirmed)) control_generation;
      let control_current = Option.exists (fun generation ->
        keeper_chat_control_result_current state keeper_name ~generation) control_generation in
      Option.iter (fun generation ->
        ignore (finish_keeper_chat_control state keeper_name ~generation : bool)) control_generation;
      state.keeper_queue_inflight <- List.filter ((<>) keeper_name) state.keeper_queue_inflight;
      state.keeper_queue_readings <- List.filter ((<>) keeper_name) state.keeper_queue_readings;
      state.keeper_queue_inspections <- List.filter
        (fun (keeper, _) -> keeper <> keeper_name) state.keeper_queue_inspections;
      if control_current then
        Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~change:(Waiting_keepers [keeper_name]) state ~mailbox;
      Masc_tui_chat_dispatch.Chat_watching.launch_keeper_turns_load state ~mailbox;
      (match state.queue_panel with
       | Some panel when String.equal panel.qp_keeper keeper_name ->
         let panel = (match result with
          | Error failure ->
            let detail = request_failure_text ~ko:(state.ui_language = Lang_ko)
              ~request:Kept_request.Keeper_action failure in
            let panel = withdraw_queue_panel_server_selection panel in
            if action = Masc_tui_queue_inspection.Inspect then
              {panel with qp_reading=Queue_unavailable; qp_notice=Some (Queue_error detail)}
            else {panel with qp_reading=Queue_unavailable; qp_notice=None;
              qp_receipt=Some (Queue_action_receipt (Queue_error detail))}
          | Ok (receipt, Error detail) ->
            let panel = withdraw_queue_panel_server_selection panel in
            let receipt = if action = Masc_tui_queue_inspection.Inspect || receipt = [] then panel.qp_receipt
              else Some (Queue_action_receipt (Queue_info (String.concat " · " receipt))) in
            {panel with qp_reading=Queue_unavailable; qp_notice=Some (Queue_error ("Read unavailable: " ^ detail));
              qp_receipt=receipt}
          | Ok (receipt, Ok observation) ->
            let receipt = if action = Masc_tui_queue_inspection.Inspect || receipt = [] then panel.qp_receipt
              else Some (Queue_action_receipt (Queue_info (String.concat " · " receipt))) in
            let panel = {panel with qp_observation=Some observation;
              qp_reading=(if panel.qp_refresh_after_priority then Queue_unavailable else Queue_current);
              qp_notice=(if panel.qp_refresh_after_priority then
                  Some (Queue_info "Priority changed while reading; refreshing after it settles")
                else None);
              qp_receipt=receipt} in
            reconcile_queue_panel_selection ~items:(queue_panel_items state panel) panel) in
         state.queue_panel <- Some panel
       | Some _ | None ->
         if action <> Masc_tui_queue_inspection.Inspect then begin
           let lines = match result with
             | Error failure ->
               [request_failure_text ~ko:(state.ui_language = Lang_ko)
                  ~request:Kept_request.Keeper_action failure]
             | Ok (_, Error detail) -> ["Read unavailable: " ^ detail]
             | Ok (_, Ok observation) ->
               let source = function
                 | Ok _ -> []
                 | Error detail -> ["Read unavailable: " ^ detail] in
               source observation.waiting @ source observation.operations in
           if lines <> [] then
             Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:(Some keeper_name) ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure (String.concat "\n" lines)
         end);
      if List.exists (fun (request : Keeper_chat.request) ->
          String.equal request.keeper_name keeper_name) state.keeper_run_next_ready then begin
        update_queue_panel state ~keeper_name (fun panel ->
          {panel with qp_reading=Queue_unavailable;
            qp_notice=Some (Queue_info "Another priority change may follow; refresh after it finishes")});
        Masc_tui_chat_dispatch.Queue_steer.dispatch_ready_run_next state ~mailbox keeper_name
      end;
      Masc_tui_collab_queue.Keeper_queue.refresh_queue_after_priority state ~mailbox ~keeper_name;
      Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox;
      Drawn_changed
  | Lane_msg (Lane_application_loaded (ticket,result)) ->
      Masc_tui_surface_requests.Lane_browser_requests.map_lane_addons state (fun view ->
        match result with
        | Ok configuration ->
            Masc_tui_lane_addons.finish_application_read view ticket (Ok configuration)
        | Error (Request_failed detail) ->
            Masc_tui_lane_addons.finish_application_read view ticket (Error detail)
        | Error (Request_withdrawn refusal) ->
            Masc_tui_lane_addons.withdraw_application_read view ticket
              (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                 ~request:Kept_request.Addon_read refusal));
      Drawn_changed
  | Lane_msg (Lane_subscriptions_loaded (generation,result)) ->
      (match state.lane_nested_read_resume with
       | Some (pending, _) when pending = generation -> state.lane_nested_read_resume <- None
       | Some _ | None -> ());
      Masc_tui_surface_requests.Lane_browser_requests.map_lane_addons state (fun view ->
        if view.generation<>generation then view else
        match result with
        | Ok snapshot ->
            {view with loading=false;subscription_panel=Option.map
              (fun panel -> Masc_tui_lane_subscriptions.loaded panel (Ok snapshot)) view.subscription_panel}
        | Error (Request_failed detail) ->
            {view with loading=false;subscription_panel=Option.map
              (fun panel -> Masc_tui_lane_subscriptions.loaded panel (Error detail)) view.subscription_panel}
        | Error (Request_withdrawn refusal) ->
            (* The panel keeps what it showed; the notice says the request
               was not sent. *)
            {view with loading=false;
              error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_kept_back state ~request:Kept_request.Addon_request refusal});
      Drawn_changed
  | Lane_msg (Lane_addons_loaded (generation, target, result)) ->
      let showing = Option.is_some state.lane_addons in
      (match target with
       | Masc_tui_lane_addons.Read_detail (owner, epoch) ->
           let owns_answer = Option.exists (fun (view : Masc_tui_lane_addons.t) ->
             view.generation = generation
             && view.screen = Detail (owner, epoch)) state.lane_addons
           in
           if owns_answer then
             state.lane_addons_owed <- Option.map (fun ((owed_owner, owed_epoch), owed) ->
               let next =
                 if not (String.equal owner owed_owner && String.equal epoch owed_epoch) then owed
                 else match result with
                   | Ok reply when Option.is_some reply.lar_snapshot
                       && Option.is_none reply.lar_diagnostic
                       && Option.is_none reply.lar_kept_back
                       && (match reply.lar_inventory_read with
                           | `Read | `Unchanged -> true
                           | `Failed _ -> false) ->
                       Masc_tui_owed_read.succeeded owed
                   | Ok _ | Error _ -> failed_read owed
               in
               ((owed_owner, owed_epoch), next)) state.lane_addons_owed
       | Masc_tui_lane_addons.Read_screen | Masc_tui_lane_addons.Read_installation_results _ -> ());
      Masc_tui_surface_requests.Lane_browser_requests.map_lane_addons state (fun view ->
        if view.generation <> generation then view else
        if not (Masc_tui_lane_addons.read_still_wanted view ~showing target)
        then {view with loading=false} else
        match result with
        | Error (`Inventory detail) ->
            {view with loading=false;error=None;snapshot_read_error=Some detail;
              application_reading=Masc_tui_lane_application.accept (Error detail)}
        | Error (`Detail detail) ->
            let detail_read_error = match target with
              | Masc_tui_lane_addons.Read_detail (id, incarnation) -> Some (id, incarnation, detail)
              | Read_screen | Read_installation_results _ -> view.detail_read_error in
            {view with loading=false;error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_detail_failure detail;detail_read_error}
        | Error (`Request detail) ->
            {view with loading=false;error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_request_failure detail}
        | Error (`Kept_back refusal) ->
            {view with loading=false;
              error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_kept_back state ~request:Kept_request.Addon_request refusal}
        | Ok reply ->
            (* A follow-up read the guard stopped is said as kept back. *)
            let diagnostic = match reply.lar_kept_back with
              | Some refusal -> Masc_tui_surface_requests.Lane_browser_requests.lane_addons_kept_back state ~request:Kept_request.Addon_read refusal
              | None -> reply.lar_diagnostic in
            let view = match reply.lar_snapshot with
              | None -> view
              | Some snapshot -> Masc_tui_lane_addons.reconcile_read_snapshot view
                  ~target ~diagnostic snapshot in
            let view = match reply.lar_receipt with
              | None -> view
              | Some receipt -> Masc_tui_lane_addons.acknowledge_broadcast view receipt in
            let view = match target, reply.lar_snapshot, diagnostic with
              | Masc_tui_lane_addons.Read_detail _, Some _, None when view.row_cursor < 0 ->
                  Masc_tui_lane_addons.select_initial_result view
              | (Masc_tui_lane_addons.Read_screen | Read_detail _ | Read_installation_results _),
                (Some _ | None), (Some _ | None) -> view in
            let snapshot_read_error = match reply.lar_inventory_read with
              | `Unchanged -> view.snapshot_read_error
              | `Read -> None
              | `Failed detail -> Some detail in
            let view = match reply.lar_inventory_read with
              | `Unchanged -> view
              | `Failed detail -> Masc_tui_lane_addons.receive_application_inventory view (Error detail)
              | `Read ->
                  let configuration = Option.bind reply.lar_snapshot (fun snapshot -> snapshot.Masc_tui_lane_addons.configuration) in
                  Masc_tui_lane_addons.receive_application_inventory view
                    (match configuration with Some configuration -> Ok configuration
                     | None -> Error "Configuration observation is unavailable") in
            let view = {view with loading=false;error=diagnostic;
              snapshot_read_error;
              action_receipt=(match reply.lar_action with None -> view.action_receipt | Some _ -> reply.lar_action);
              receipt=(match reply.lar_receipt with None -> view.receipt | Some _ -> reply.lar_receipt)} in
            (match target, reply.lar_snapshot, diagnostic with
             | Masc_tui_lane_addons.Read_installation_results installation_id, Some _, None ->
                 Masc_tui_lane_addons.installation_results view ~installation_id
             | (Masc_tui_lane_addons.Read_screen | Read_detail _ | Read_installation_results _),
               (Some _ | None), (Some _ | None) -> view));
      (match result, state.lane_addons with
       | Ok {lar_action=Some {Masc.Lane_addon_action.state=
           (Confirmed | Failed_before_effect | Outcome_unknown);_};_}, Some view
         when view.generation=generation && not view.loading
              && Option.is_none view.draft && Option.is_none view.document_key
              && Option.is_none view.action_menu && Option.is_none view.installer && Option.is_none view.subscription_panel
              && Option.is_none view.evidence_prompt ->
           Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox Masc_tui_lane_addons.Inspect
       | (Ok { lar_action = Some { Masc.Lane_addon_action.state = (Masc.Lane_addon_action.Confirmed | Masc.Lane_addon_action.Failed_before_effect | Masc.Lane_addon_action.Outcome_unknown);_};_}, None)
       | (Ok { lar_action = Some { state = (Masc.Lane_addon_action.Queued | Masc.Lane_addon_action.Running);_};_}, _)
       | (Ok { lar_action = None;_}, _) | (Error _, _)
       | (Ok {lar_action=Some {state=Confirmed; _ }; _ }, Some _)
       | (Ok {lar_action=Some {state=Failed_before_effect; _ }; _ }, Some _)
       | (Ok {lar_action=Some {state=Outcome_unknown; _ }; _ }, Some _) -> ());
      Drawn_changed
  | Lane_msg (Lane_declaration_loaded (generation, request, edit, create_directory, result)) ->
      (match state.lane_nested_read_resume with
       | Some (pending, _) when pending = generation -> state.lane_nested_read_resume <- None
       | Some _ | None -> ());
      let module Addons = Masc_tui_lane_addons in
      let module Document = Masc_tui_lane_declaration in
      let visible = Option.is_some state.lane_addons in
      Masc_tui_surface_requests.Lane_browser_requests.map_lane_addons state (fun view ->
        if view.generation <> generation then view else
        let view = {view with loading=false} in
        match result with
        | Error (Request_failed detail) ->
            {view with error=(match request with
              | Document.Read _ -> Masc_tui_surface_requests.Lane_browser_requests.lane_addons_detail_failure detail
              | Document.Save _ -> Masc_tui_surface_requests.Lane_browser_requests.lane_addons_request_failure detail)}
        | Error (Request_withdrawn refusal) ->
            {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_kept_back state refusal ~request:(match request with
              | Document.Read _ -> Kept_request.Addon_read
              | Document.Save _ -> Kept_request.Addon_request)}
        | Ok response ->
            let key = match request with Document.Read path -> Filename.basename path
              | Document.Save session -> session.file_name in
            let existing = match request with
              | Document.Read path -> Document.find_for_path ?create_directory ~path view.documents
              | Document.Save _ -> Ok (List.find_opt (fun (s : Document.session) -> s.file_name=key) view.documents) in
            match existing with
            | Error detail -> {view with document_key=None;editor_ready=false;scroll=0;
                error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail}
            | Ok existing ->
            let session = match existing, response with
              | Some session, _ -> Some (Document.after_response session response)
              | None, Document.Read_document document -> Some (Document.from_document document)
              | None, Document.Written receipt -> Some (Document.from_document receipt.document)
              | None, Document.Rejected _ -> None in
            let selected = view.document_key=Some key in
            let view = match session with None -> view | Some session ->
              let updated = Addons.put_document view session in
              {updated with document_key=view.document_key;
                records=(if selected then updated.records else view.records)} in
            match response with
            (* Same reason as the pending note: a rejection is the answer to
               the save, and it is drawn above the draft the reader is in. *)
            | Document.Rejected failure ->
                {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_request_failure failure.message;scroll=0}
            | Document.Read_document _ | Document.Written _ -> {view with error=None;editor_ready=(view.editor_ready || (edit && selected && visible))});
      (match state.lane_addons with
       | Some view when view.generation=generation -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_application state ~mailbox
       | Some _ | None -> ());
      Drawn_changed
  (* The capture messages carry the keeper the capture was started for, and
     each is dropped unless that capture is still the one in flight. The
     wizard's carry the number of the save they answer, dropped the same way
     once the session has closed, saved again, or changed the draft. *)
  | Voice_msg (Voice_wizard_saved (request, reply)) ->
      Option.iter
        (fun session ->
          Option.iter
            (fun (updated : Masc_tui_voice_wizard_session.voice_wizard_session) ->
              state.voice_wizard <- Some updated;
              (match reply with
               (* The pane is one revision behind a write, and possibly behind
                  one that got no answer. *)
               | Masc_tui_voice_wizard_session.Save_written _ | Masc_tui_voice_wizard_session.Save_unanswered_reply _ ->
                   Masc_tui_work_requests.Voice_requests.launch_voice_config_load state ~mailbox
               | Masc_tui_voice_wizard_session.Save_refused _
               | Masc_tui_voice_wizard_session.Save_kept_back _ -> ());
              match updated.vws_save with
              | Masc_tui_voice_wizard_session.Save_probing request ->
                  Masc_tui_work_requests.Voice_requests.launch_voice_wizard_probe state ~mailbox ~request
                    Masc_tui_work_requests.Voice_requests.voice_wizard_probe_sentence
              | Masc_tui_voice_wizard_session.Save_unanswered { request; _ } ->
                  Masc_tui_work_requests.Voice_requests.launch_voice_wizard_reread state ~mailbox ~request
              | Masc_tui_voice_wizard_session.Save_not_sent | Masc_tui_voice_wizard_session.Save_sending _
              | Masc_tui_voice_wizard_session.Save_settled | Masc_tui_voice_wizard_session.Save_needs_reopen _ ->
                  ())
            (Masc_tui_voice_wizard_session.voice_wizard_after_save session ~request reply))
        state.voice_wizard;
      Drawn_changed
  | Voice_msg (Voice_agent_voices_loaded result) ->
      (match state.voice_agent_voices, result with
       (* The screen closed while the endpoint was being asked: its answer is
          about a screen nobody is reading. *)
       | None, (Ok _ | Error _) -> ()
       | Some session, Error message ->
           state.voice_agent_voices
             <- Some { session with vas_loading_voices = false; vas_status = Some message }
       | Some session, Ok json ->
           let voices = Masc_tui_work_requests.Voice_requests.voice_agent_voice_rows json in
           state.voice_agent_voices
             <- Some
                  { session with
                    vas_voices = voices
                  ; vas_voice_cursor = 0
                  ; vas_loading_voices = false
                  ; vas_status =
                      (match voices with
                       | [] -> Some "the endpoint answered with no voices"
                       | _ :: _ -> None)
                  });
      Drawn_changed
  | Voice_msg (Voice_agent_voice_saved result) ->
      (match state.voice_agent_voices, result with
       | None, (Ok _ | Error _) -> ()
       | Some session, Error (Request_failed message) ->
           state.voice_agent_voices
             <- Some { session with vas_saving = false; vas_status = Some message }
       | Some session, Error (Request_withdrawn refusal) ->
           state.voice_agent_voices
             <- Some { session with vas_saving = false
                     ; vas_status = Some (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                         ~request:Kept_request.Agent_voice_save refusal) }
       | Some session, Ok json ->
           (* The write moved the configuration on, so the next assignment
              carries the revision this answer named rather than the one the
              screen opened with. The pane underneath is reloaded for the same
              reason. *)
           let revision =
             match Masc_tui_work_requests.Voice_requests.voice_setup_revision json with
             | Some revision -> revision
             | None -> session.vas_revision
           in
           state.voice_agent_voices
             <- Some
                  { session with
                    vas_saving = false
                  ; vas_revision = revision
                  ; vas_status =
                      Some
                        (match Masc_tui_types.voice_agent_selected session with
                         | Some (agent, voice) ->
                             Printf.sprintf "%s speaks as %s" agent voice
                         | None -> "assigned")
                  };
           Masc_tui_work_requests.Voice_requests.launch_voice_config_load state ~mailbox);
      Drawn_changed
  | Voice_msg (Voice_wizard_probed (request, result)) ->
      Option.iter
        (fun session ->
          Option.iter
            (fun updated -> state.voice_wizard <- Some updated)
            (Masc_tui_voice_wizard_session.voice_wizard_after_probe session ~request
               (Result.map Masc_tui_work_requests.Voice_requests.voice_wizard_probe_lines result
                |> Result.map_error (function
                  | Request_failed message -> message
                  | Request_withdrawn refusal ->
                    Masc_tui_work_requests.Voice_requests.voice_probe_kept_back ~ko:(state.ui_language = Lang_ko) refusal))))
        state.voice_wizard;
      Drawn_changed
  | Voice_msg (Voice_wizard_reread (request, result)) ->
      Option.iter
        (fun session ->
          Option.iter
            (fun updated -> state.voice_wizard <- Some updated)
            (Masc_tui_voice_wizard_session.voice_wizard_after_reread session ~request result))
        state.voice_wizard;
      Drawn_changed
  | Voice_msg (Voice_config_loaded (result, setup, device)) ->
      state.voice_input_device <- device;
      (match result with
       | Ok json ->
           state.voice_config <- Some json;
           state.voice_config_error <- None
       | Error message ->
           state.voice_config <- None;
           state.voice_config_error <- Some message);
      (match setup with
       | Ok json ->
           state.voice_setup <- Some json;
           state.voice_setup_error <- None
       | Error message ->
           state.voice_setup <- None;
           state.voice_setup_error <- Some message);
      Drawn_changed
  | Voice_msg (Voice_calibrated { keeper; floor }) ->
      ignore (observe_voice_calibration state ~keeper ~floor);
      Drawn_changed
  | Voice_msg (Voice_level { keeper; level }) ->
      ignore (observe_voice_level state ~keeper ~level);
      Drawn_changed
  | Voice_msg (Voice_transcribed { keeper; text }) ->
      (match settle_voice_capture state ~keeper with
       | None | Some Voice_withdrawn -> ()
       | Some (Voice_current disposition) ->
        Masc_tui_operator_actions.Voice_actions.rearm_continuous_capture state ~mailbox ~keeper;
        match disposition with
        | Masc.Voice_bridge.Discard -> ()
        | Masc.Voice_bridge.Keep_what_was_heard ->
        state.msg_command_menu <- Masc_tui_command.Menu_idle;
        (* Voice continues the whole draft even if its editing cursor moved
           during capture. Keep the separator and transcript together at the
           end, where send_on_stop will read the completed message. *)
        Masc_tui_message_input.append_separated state.msg_input ~separator:" " text;
        save_message_draft state;
        set_last_action state (Some ("voice: " ^ text, Unix.gettimeofday ()));
        (* [voice.stt].send_on_stop: the operator who says a sentence and
           stops the capture has finished the sentence, and the Enter that
           follows says nothing the stop did not. Off by default, because the
           draft is also where a spoken half-sentence waits for typing, and
           taking the review step away costs an operator who works that way
           more than it saves the one who does not.

           The section is [voice.stt], where the voice setup routes write and
           GET /api/v1/voice/config publishes it.

           Sent the way the surface holding the draft sends it, so a spoken
           draft is not a second kind of draft. The chat pane has its own
           editor and the composer row is never focused there -- handing the
           row the send key from this pane was a key nothing took, and the
           transcript stayed in the draft. Anywhere else the row is the editor,
           and its send key decides what a draft is (a message, a slash
           command, a preset) and which surface comes forward. A capture in
           continuous mode re-arms above before this, so the microphone is
           already listening for the next sentence when this returns. *)
        if state.voice_send_on_stop
        then (
          if state.view = Keepers Keeper_message
          then
            Masc_tui_chat_input.Message_draft_recall.submit_chat_draft state
              ~submit_message:(send_operator_text state ~base_path ~mailbox)
              ~drain_queue:(fun () -> Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox)
          else (
            let (_ : bool) =
              Masc_tui_composer_input.Composer_key.handle_composer_key
                ~terminal_size:Masc_tui_render_prim.get_terminal_size
                ~wheel_notch_rows
                ~withdraw_resource_diagram_pending:(fun () -> withdraw_resource_diagram_pending state)
                ~launch_keeper_history_load:(fun ~keeper_name -> launch_keeper_history_load state ~mailbox ~keeper_name)
                ~send_operator_text:(fun ~keeper_name snapshot -> send_operator_text ~keeper_name state ~base_path ~mailbox snapshot)
                ~paste_clipboard_image:(fun () -> paste_clipboard_image state)
                ~open_named_image:(fun () -> open_named_image state ~mailbox)
                ~launch_keeper_chat_tool_details_load:(fun ~keeper_name -> launch_keeper_chat_tool_details_load ~force:true state ~mailbox ~keeper_name)
                state ~base_path ~mailbox Composer.send_key
            in
            ())));
      Drawn_changed
  | Voice_msg (Voice_silent { keeper; reason }) ->
      (match settle_voice_capture state ~keeper with
       | None | Some Voice_withdrawn -> ()
       | Some (Voice_current _) ->
        (* Silence re-arms too: an operator who paused longer than the
           trailing-silence window has not left the mode. *)
        Masc_tui_operator_actions.Voice_actions.rearm_continuous_capture state ~mailbox ~keeper;
        (* In the transcript, not only the footer. A capture that heard
           nothing leaves the draft exactly as a capture that was never
           transcribed does, and the footer line saying which is gone by the
           time an operator looks away and back. The reason carries the room
           level and the level speech had to clear, so this row answers "is
           the microphone working" rather than only reporting that it is
           not. *)
        Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:(Some keeper) ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
          ("voice: " ^ reason);
        set_last_action state (Some ("voice: " ^ reason, Unix.gettimeofday ())));
      Drawn_changed
  | Voice_msg (Voice_discarded { keeper; reason }) ->
      (match settle_voice_capture state ~keeper with
       | None | Some Voice_withdrawn -> ()
       | Some (Voice_current _) ->
        (* Esc abandons the recording, not the mode: the capture is the
           innermost thing it cancels, and the toggle is the way out of
           continuous mode. So this re-arms like a silence does. *)
        Masc_tui_operator_actions.Voice_actions.rearm_continuous_capture state ~mailbox ~keeper;
        (* In the transcript, like a silence, and worded as what it was. An
           operator who pressed Esc mid-sentence and then read "nothing was
           heard" went looking for a microphone fault that was not there. *)
        Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:(Some keeper) ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
          ("voice: " ^ reason);
        set_last_action state (Some ("voice: " ^ reason, Unix.gettimeofday ())));
      Drawn_changed
  | Voice_msg (Voice_failed { keeper; error }) ->
      (match settle_voice_capture state ~keeper with
       | None | Some Voice_withdrawn -> ()
       | Some (Voice_current _) ->
        (* A failure ends the mode rather than re-arming into it. Whatever
           stopped the recorder — no input device, a missing binary — will stop
           it again, and a loop that re-arms on failure spins. *)
        state.voice_continuous <- None;
        state.voice_floor <- None;
        Masc_tui_operator_actions.Voice_actions.report_voice_failure state ~keeper error);
      Drawn_changed
  | Http_surface_read_completed (context, completed) ->
      let request=Surface_read_context.current context in
      (* Dataset admission and collector completion have different lifetimes.
         A duplicate cannot reapply an identity observation or free another read. *)
      let active = match Surface_read_order.request_kind request with
        | Surface_read_order.Full -> true
        | Surface_read_order.Navigation ->
            Surface_read_order.navigation_active state.http_surface_reads request in
      if active then begin
        (* Finishing the read frees its slot, which the screen draws, so the
           arm is drawn whatever the reading it carried did. *)
        let (_ : drawn_effect) =
          Fun.protect ~finally:(fun () ->
            Masc_tui_types.finish_http_surface_read state request;
            http_scoped_refresh_inflight :=
              Surface_read_order.navigation_in_flight state.http_surface_reads)
            (fun () -> apply_async_message ~server_contact ~input_pending ~image_input_pending state ~base_path ~http_refresh_inflight
              ~http_scoped_refresh_inflight ~scoped_refresh_followup ~mailbox completed)
        in
        log_http_surface_read_finished state context;
        (* The last collector's slot must be released before a retained full
           revalidation can run. Other collectors keep their own slots. *)
        start_scoped_refresh_followup ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
          ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight
          ~scoped_refresh_followup ~mailbox
      end;
      Drawn_changed
  | Http_msg (Http_dataset_loaded early) ->
      let dataset = http_dataset_key early.ed_dataset in
      let source = Surface_read_order.dataset_source dataset in
      if Masc_tui_types.take_early_surface_dataset state
          ~ticket:early.ed_ticket ~authority:early.ed_authority
          ~identity:early.ed_identity ~request:early.ed_request ~dataset then begin
        let kind, full_started_ns = match Surface_read_order.request_kind early.ed_request with
          | Surface_read_order.Full -> "full", state.http_refresh_started_ns
          | Navigation -> "navigation", None in
        let board_posts_log=match Masc_tui_refresh_settlement.Http_dataset_settlement.apply_http_dataset state early.ed_dataset with
          | None -> ""
          | Some application -> " board_posts="
              ^ Yojson.Safe.to_string (board_posts_application_to_yojson application) in
        Log.Transport.info
          "tui_dataset_early request=%d kind=%s started_ns=%Ld full_refresh_started_ns=%s admitted_ns=%Ld source=%s dataset=%s outcome=%s%s"
          (Surface_read_order.request_id early.ed_request)
          kind (Surface_read_order.started_ns early.ed_request)
          (match full_started_ns with Some started -> Int64.to_string started | None -> "unrecorded")
          (Mtime_clock.elapsed_ns ())
          (Surface_read_order.source_name source)
          (Surface_read_order.dataset_name dataset)
          (if http_dataset_received early.ed_dataset then "received" else "failed")
          board_posts_log
      end;
      Drawn_changed
  | Http_msg (Http_initial_identity_read initial) ->
      (* The initial probe is recorded before its acknowledgement message.
         Drain before preserving/rebinding that ledger to the admitted owner. *)
      ignore (Masc_tui_types.drain_http_progress state);
      (* Rejection, cancellation or an exception must also release the worker.
         This receipt does not settle the refresh or its final identity probe. *)
      Fun.protect
        ~finally:(fun () ->
          ignore (Eio.Promise.try_resolve initial.hir_acknowledge None))
        (fun () ->
          if Masc_tui_types.can_admit_initial_http_identity state
               ~ticket:initial.hir_ticket ~authority:initial.hir_authority
               initial.hir_identity then begin
            let before = read_authority state in
            let progress = state.http_refresh_progress in
            apply_server_identity_reading state ~mailbox (Ok initial.hir_identity);
            (* Keep the original pass clock and already observed probe events;
               only subsequent callbacks belong to the new authority. *)
            state.http_refresh_progress <- Option.map
              (fun (_, observed) -> state.workspace_authority, observed) progress;
            let reads, surfaces = Surface_read_order.dispatch ~kind:Surface_read_order.Full ~needs:initial.hir_needs
              ~started_ns:(Mtime_clock.elapsed_ns ()) state.http_surface_reads in
            state.http_surface_reads <- reads;
            let context=Surface_read_context.rebind initial.hir_surface_context surfaces in
            let admitted =
              { hrr_authority = state.workspace_authority;
                hrr_approval = Masc_tui_refresh_settlement.Approvals_asks_settlement.dispatch_approvals_listing state;
                hrr_asks = Masc_tui_types.begin_asks_read state;
                hrr_roster = if initial.hir_needs.needs_keeper_roster
                  then Masc_tui_types.begin_keeper_roster_read ~intent:Snapshot_read.Refresh state
                  else None;
                hrr_surfaces = context } in
            ignore (Eio.Promise.try_resolve initial.hir_acknowledge (Some admitted));
            Log.Transport.info "tui_surface_read_rebound previous_request=%d context=%s"
              (Surface_read_order.request_id (Surface_read_context.current initial.hir_surface_context))
              (Yojson.Safe.to_string (Surface_read_context.to_yojson context));
            Option.iter (fun started_ns ->
              Log.Transport.info
                "tui_initial_identity refresh_started_ns=%Ld admitted_ms=%.3f"
                started_ns
                (Int64.to_float (Int64.sub (Mtime_clock.elapsed_ns ()) started_ns)
                 /. 1_000_000.)) state.http_refresh_started_ns;
            resume_reads_after_authority_change ~server_contact state ~mailbox
              ~refresh_inflight:http_refresh_inflight
              ~scoped_refresh_inflight:http_scoped_refresh_inflight
              ~scoped_refresh_followup ~before
          end);
      Drawn_changed
  | Http_msg (Http_approvals_loaded early) ->
      if Masc_tui_types.can_admit_early_http_read state ~ticket:early.eap_ticket
          ~authority:early.eap_authority early.eap_identity
      then Option.iter (fun result ->
        Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_approvals_answer state (Result.map_error (fun detail -> Request_failed detail) result);
        Option.iter (fun started_ns ->
          Log.Transport.info "tui_approvals_early request=%d refresh_started_ns=%Ld admitted_ms=%.3f outcome=%s"
            (Approval.Listing_order.request_id early.eap_observation.ao_ticket) started_ns
            (Int64.to_float (Int64.sub (Mtime_clock.elapsed_ns ()) started_ns) /. 1_000_000.)
            (match result with Ok _ -> "received" | Error _ -> "failed"))
          state.http_refresh_started_ns)
        (Masc_tui_refresh_settlement.Approvals_asks_settlement.take_approval_observation state early.eap_observation);
      Drawn_changed
  | Ask_msg (Asks_reloaded observation) -> Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_asks_observation state observation; Drawn_changed
  | Keeper_msg (Keeper_roster_reloaded observation) ->
      Option.iter (fun result ->
        let previous_items = Masc_tui_surface_requests.Keeper_surface_requests.visible_item_revision state in
        Masc_tui_refresh_settlement.Http_dataset_settlement.apply_keeper_roster_load ~before_view_change:(fun () -> retire_remote_image_for_navigation state) state result;
        match result with
        | Error _ -> ()
        | Ok _ ->
            state.keeper_roster_owed <-
              Masc_tui_roster_owed.succeeded Masc_tui_roster_owed.Read_roster
                state.keeper_roster_owed;
            Masc_tui_surface_requests.Keeper_surface_requests.refresh_changed_keeper_items state ~mailbox ~roster_refreshed:true previous_items;
            resolve_opening_chat state ~base_path ~mailbox)
        (Masc_tui_types.take_keeper_roster_observation state observation);
      Drawn_changed
  | Keeper_msg (Keeper_row_reloaded observation) ->
      Option.iter (fun result ->
        let keeper_name = observation.row_keeper in
        let read = Masc_tui_roster_owed.Read_row keeper_name in
        match result with
        | Error _ ->
            (* One row that did not answer leaves the other rows standing
               and reads again after a wait. A whole read decides whether
               the roster itself is still readable. *)
            fail_keeper_roster_read state read
        | Ok (reading, candle) ->
            state.keeper_roster_owed <- Masc_tui_roster_owed.succeeded read state.keeper_roster_owed;
            match Keeper_control.replace_row state.keeper_roster ~keeper_name reading with
            | None -> owe_whole_keeper_roster_read state
            | Some roster ->
                (* One row read is not a roster refresh: the open Keeper's
                   Items read again only when its own row moved. *)
                let previous_items = Masc_tui_surface_requests.Keeper_surface_requests.visible_item_revision state in
                Masc_tui_refresh_settlement.Http_dataset_settlement.apply_keeper_roster_load ~before_view_change:(fun () -> retire_remote_image_for_navigation state) state (Ok (roster, candle));
                Masc_tui_surface_requests.Keeper_surface_requests.refresh_changed_keeper_items state ~mailbox ~roster_refreshed:false previous_items)
        (Masc_tui_types.take_keeper_row_observation state observation);
      Drawn_changed
  | Http_msg (Http_asks_loaded early) ->
      Option.iter (fun result ->
        Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_asks_read state result;
        Option.iter (fun started_ns ->
          Log.Transport.info "tui_asks_early request=%d refresh_started_ns=%Ld admitted_ms=%.3f outcome=%s"
            (Snapshot_read.request_id early.ea_observation.asks_request) started_ns
            (Int64.to_float (Int64.sub (Mtime_clock.elapsed_ns ()) started_ns) /. 1_000_000.)
            (match result with Ok _ -> "received" | Error _ -> "failed"))
          state.http_refresh_started_ns)
        (Masc_tui_types.take_early_asks_observation state early);
      Drawn_changed
  | Http_msg (Http_keeper_roster_loaded early) ->
      Option.iter (fun result ->
        let previous_items = Masc_tui_surface_requests.Keeper_surface_requests.visible_item_revision state in
        Masc_tui_refresh_settlement.Http_dataset_settlement.apply_keeper_roster_load ~before_view_change:(fun () -> retire_remote_image_for_navigation state) state result;
        Option.iter (fun started_ns ->
          Log.Transport.info "tui_roster_early request=%d refresh_started_ns=%Ld admitted_ms=%.3f outcome=%s"
            (Snapshot_read.request_id early.er_observation.roster_request) started_ns
            (Int64.to_float (Int64.sub (Mtime_clock.elapsed_ns ()) started_ns) /. 1_000_000.)
            (match result with Ok _ -> "received" | Error _ -> "failed"))
          state.http_refresh_started_ns;
        (match result with
         | Error _ -> ()
         | Ok _ ->
             Masc_tui_surface_requests.Keeper_surface_requests.refresh_changed_keeper_items state ~mailbox ~roster_refreshed:true previous_items;
             resolve_opening_chat state ~base_path ~mailbox))
        (Masc_tui_types.take_early_keeper_roster_observation state early);
      Drawn_changed
  | Http_msg (Http_refresh_done
      (Refresh_workspace_unconfirmed
         { refresh_ticket; detail; unreachable; approval_ticket; latest_identity })) ->
      http_refresh_inflight := false;
      Masc_tui_transport.Http_surface_collector.finish_observed_refresh state ~ticket:refresh_ticket;
      if Http_refresh_order.is_current state.http_refresh_order refresh_ticket then begin
        let authority = read_authority state in
        apply_workspace_unconfirmed state ~mailbox ~detail ~unreachable ~approval_ticket ~latest_identity;
        resume_reads_after_authority_change ~server_contact state ~mailbox
          ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup
          ~before:authority;
      Masc_tui_transport.Server_contact.react_to_contact server_contact state ~base_path
        ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
      end;
      start_scoped_refresh_followup ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
        ~port:state.port ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight
        ~scoped_refresh_followup ~mailbox;
      Drawn_changed
  | Http_msg (Http_refresh_done (Refresh_server_booting { refresh_ticket; identity; approval_ticket })) ->
      http_refresh_inflight := false;
      Masc_tui_transport.Http_surface_collector.finish_observed_refresh state ~ticket:refresh_ticket;
      (* Nothing else was asked of a booting server, so nothing else follows:
         no held-call listing, no observer. The scoped follow-up is left
         queued on purpose -- draining it now would send surface loads to the
         booting server -- and the first non-booting completion drains it. *)
      if Http_refresh_order.is_current state.http_refresh_order refresh_ticket then
        apply_server_booting state ~mailbox ~refresh_ticket ~identity ~approval_ticket
      else start_scoped_refresh_followup ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
        ~port:state.port ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight
        ~scoped_refresh_followup ~mailbox;
      Drawn_changed
  | Http_msg (Http_refresh_done (Refresh_account_server { refresh_ticket; version; approval_ticket })) ->
      http_refresh_inflight := false;
      Masc_tui_transport.Http_surface_collector.finish_observed_refresh state ~ticket:refresh_ticket;
      (* As for a booting server, nothing else was asked and nothing else
         follows here. A queued scoped follow-up runs when this pass releases
         its read slot, and its pass ends at the probe as this one did. *)
      if Http_refresh_order.is_current state.http_refresh_order refresh_ticket then begin
        let authority = read_authority state in
        apply_account_server ~server_contact state ~mailbox ~refresh_ticket ~version ~approval_ticket;
        resume_reads_after_authority_change ~server_contact state ~mailbox
          ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup
          ~before:authority
      end
      else start_scoped_refresh_followup ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
        ~port:state.port ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight
        ~scoped_refresh_followup ~mailbox;
      Drawn_changed
  | Http_msg (Http_refresh_done (Refresh_surfaces results)) ->
      http_refresh_inflight := false;
      Masc_tui_transport.Http_surface_collector.finish_observed_refresh state ~ticket:results.http_scoped.http_refresh_ticket;
      if Http_refresh_order.is_current state.http_refresh_order
           results.http_scoped.http_refresh_ticket then begin
      let dispatch_was_unavailable =
        state.workspace_identity <> Workspace_identity_match
        || Option.is_some state.keepers_error
      in
      (* Recovery, not repair: only a session that has never seen a matching
         identity (cold start, or the server went away and came back) may
         re-read the confirm queue outside the bundle. A workspace that just
         read as another one keeps its count on the failed line it earned --
         an automatic extra read must not be the thing that launders a
         foreign admission. *)
      let identity_recovered =
        state.workspace_identity = Workspace_identity_unread
      in
      let authority = read_authority state in
      apply_http_surfaces state ~mailbox results;
      resume_reads_after_authority_change ~server_contact state ~mailbox
        ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup
        ~before:authority;
      resume_authorized_input_after_refresh state
        ~was_unavailable:dispatch_was_unavailable ~base_path ~mailbox;
      resolve_opening_chat state ~base_path ~mailbox;
      Masc_tui_transport.Server_contact.react_to_contact server_contact state ~base_path
        ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port;
      (* The refresh that confirmed this identity also confirmed its own
         listing request, so its confirm-queue answer was refused as
         superseded before it could ever be drawn. The other approval
         sources relaunch above for the same reason; the count's own source
         re-reads here instead of sitting unread until the next cadence. *)
      if identity_recovered then Masc_tui_transport.Workspace_admission.enqueue mailbox (Approvals_msg Approvals_listing_superseded);
      Masc_tui_transport.Event_streams.open_observer_if_due ~browser_scope:observer_browser_scope state ~retry_closed:false
        ~host:(Masc_tui_transport.Workspace_admission.server_peer_host) ~port:state.port ~mailbox;
      Masc_tui_transport.Event_streams.open_fleet_stream_if_due state
        ~host:(Masc_tui_transport.Workspace_admission.server_peer_host) ~port:state.port ~mailbox;
      end;
      start_scoped_refresh_followup ~server_contact state ~host:(Masc_tui_transport.Workspace_admission.server_peer_host)
        ~port:state.port ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight
        ~scoped_refresh_followup ~mailbox;
      Drawn_changed
  | (Approvals_msg Approvals_listing_superseded) -> Masc_tui_refresh_settlement.Approvals_asks_settlement.launch_approvals_summary_load state ~mailbox; Drawn_changed
  | Approvals_msg (Approvals_summary_loaded (request, listing_ticket, expected_workspace, result)) ->
      Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_approvals_summary_load state ~listing_ticket ~expected_workspace request result;
      Drawn_changed
  | Observer_msg (Observer_session_ready session_id) ->
      state.mcp_session <- Some session_id;
      Drawn_changed
  | Observer_msg (Observer_opened (owner, session_id, handshake))
    when Masc_tui_async_protocol.observer_stream_owned state owner ->
      (* Changes made while no stream was open were not heard. *)
      Masc_tui_waiting_inventory.stream_reopened state.waiting_inventory;
      let scope_replaced =
        match state.workspace_identity, state.observer_scope_binding with
        | Workspace_identity_match, Observer_scope_bound previous ->
            (match handshake with
             | Some current -> not (String.equal previous current.Sse_wire.instance_id)
             | None -> true)
        | Workspace_identity_match, (Observer_scope_unbound | Observer_scope_retired)
        | (Workspace_identity_unread | Workspace_identity_match_unconfirmed _
          | Workspace_identity_mismatch _), _ -> false
      in
      if scope_replaced then begin
        (* A path-matching health response cannot distinguish a replacement
           at that path. Retire its reads and in-flight refresh before asking
           the successor to establish a new authority. *)
        let detail = "Observer generation changed; rechecking workspace" in
        state.http_refresh_order <- Http_refresh_order.dispatch state.http_refresh_order;
        apply_server_identity_reading ~withdraw_on_error:true state ~mailbox (Error detail);
        (* A path-only match cannot authorize automatic delivery of input
           retained from the old generation. Keep it for explicit resume. *)
        let retained = suspend_keeper_input state in
        state.keeper_interactive_waiting <- retained.ski_waiting;
        state.connection_status <- Degraded;
        add_event state "observer" detail;
        start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
          ~intent:Revalidate ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight
          ~scoped_refresh_followup ~mailbox
      end else begin
        state.mcp_session <- Some session_id;
        (match state.workspace_identity with
         | Workspace_identity_match ->
             let scoped = handshake in
             state.observer_scope_binding <- note_observer_scope state.observer_scope_binding scoped
         | Workspace_identity_unread | Workspace_identity_match_unconfirmed _
         | Workspace_identity_mismatch _ -> ());
        (match handshake with
         | Some handshake ->
             (match handshake.replay with
              | Sse_wire.Resumed | Sse_wire.Resumed_after_gap _ -> ()
              | Sse_wire.Fresh | Sse_wire.Reset _ -> state.observer_cursor <- None);
             state.observer_replay <- Observer_replay_scoped handshake
         | None ->
             state.observer_cursor <- None;
             state.observer_replay <- Observer_replay_unavailable "peer does not advertise scoped replay");
        record_observer_opened state ~session_id ~at:(Unix.gettimeofday ());
        (* The feed announces changes only while it is open. Unless this
           connection replays every event since the last applied one, the
           visible surfaces read once more (RFC-0480 §3.3): a change can land
           between the initial read and subscription, or during a
           disconnected interval, and the reads run under the current
           authority. A Resumed replay missed no event, but a read owed by an
           already applied event may still be missing, failed or running.
           Recover only those local observations; successful reads need no
           followup and replayed events owe their own reads. *)
        (* A stream that carried readings owes one revalidate even when this
           reopen replays completely (see [Observer_closed]). Only this branch
           ever sees an owned open, so the debt has to be taken here. *)
        let revalidate_owed = state.observer_revalidate_owed in
        state.observer_revalidate_owed <- false;
        if Masc_tui_types.observer_replay_is_complete handshake then begin
          note_local_source_observer_resume state Local_keepers;
          Masc_tui_transport.Local_sources.launch_followup state ~mailbox Local_keepers;
          (* A Resumed replay can still miss a write no event announced,
             such as a task file another process replaced while the stream
             was down. The resume itself is the "file may have changed
             underneath us" moment, so read the work sources again
             regardless of followup state; a file whose version did not
             move is not decoded again. Keeper metadata keeps
             followup-only recovery. *)
          Masc_tui_transport.Local_sources.launch_work_read state ~mailbox ~intent:Snapshot_read.Refresh
            state.local_base_path;
          (* The closed stream carried readings, so the replay cannot vouch for
             the interval: read the waiting inventory and the agenda once. *)
          if revalidate_owed then begin
            owe_keeper_waiting_read ~change:Waiting_all state;
            owe_agenda_revalidation state
          end
        end else begin
          owe_keeper_waiting_read ~change:Waiting_all state;
          owe_agenda_revalidation state;
          Masc_tui_transport.Local_sources.launch_workspace_read state ~mailbox ~intent:Snapshot_read.Refresh state.local_base_path;
          revalidate_visible_fusion state ~mailbox;
          state.play_room <- Option.map Masc_tui_play_room.revalidate state.play_room;
          if state.view = Memory then owe_memory_health_read state;
          start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
            ~intent:Revalidate ~refresh_inflight:http_refresh_inflight
            ~scoped_refresh_inflight:http_scoped_refresh_inflight
            ~scoped_refresh_followup ~mailbox end
      end;
      Drawn_changed
  | Observer_msg (Observer_received (owner, (instance_id, decoded)))
    when Masc_tui_async_protocol.observer_stream_owned state owner ->
      let received = Unix.gettimeofday () in
      (* One reload per batch, however many turns it carries: the pane
         shows the whole history anyway, and the loader is generation-
         guarded, so the flag only remembers that a reload is due. *)
      let open_chat_gained_turn = ref false in
      let open_chat_memory_grew = ref false in
      let open_chat_skill_ledger_changed = ref false in
      let selected_composite_changed = ref false in
      let shown_metrics_appended = ref false in
      let selected_tool_called = ref false in
      let open_board_post_changed = ref false in
      let board_changed = ref false in
      let goals_changed = ref false in
      let gate_changed = ref false in
      let held_calls_changed = ref false in
      let asks_changed = ref false in
      let async_requests_changed = ref false in
      let async_request_keepers = ref [] in
      let skill_activation_keepers = ref [] in
      let skill_catalog_published = ref false in
      let tools_inventory_changed = ref false in
      let lane_addon_exports_changed = ref false in
      let pending_confirms_changed = ref false in
      let schedules_changed = ref false in
      let runtime_config_changed = ref false in
      let event_queue_keepers = ref [] in
      let runtime_journals = ref [] in
      let tool_modes_changed = ref false in
      (* The chat operations the open pane's keeper streamed a frame for in
         this batch, with the highest journal seq named and the earliest
         frame clock: one follow-up read per operation per batch, decided
         after the loop ([journal_follow_for_source]), however many tokens
         arrived. *)
      let open_chat_stream_frames : (Keeper_chat_log.journal_source * (int option * float)) list ref = ref [] in
      let observe_journal keeper source seq at =
        if state.view = Keepers Keeper_message && state.msg_target_keeper_name = Some keeper then begin
          let highest = match List.assoc_opt source !open_chat_stream_frames, seq with
            | Some (Some held, first_at), Some seq -> Some (max held seq), first_at
            | Some (Some held, first_at), None -> Some held, first_at
            | Some (None, first_at), seq -> seq, first_at
            | None, seq -> seq, at in
          open_chat_stream_frames := (source, highest) :: List.remove_assoc source !open_chat_stream_frames
        end
      in
      (* Retain whether any run changed and whether the open one changed;
         a later unrelated event in this batch must not erase the latter. *)
      let fusion_open_run_id = match state.fusion_mode with
        | Fusion_detail run_id -> Some run_id
        | Fusion_historical_detail reference -> Some reference.fhe_run_id
        | Fusion_list -> None in
      let fusion_status_seen = ref Masc_tui_fusion_updates.no_changed_runs in
      let observer_source_loss_seen = ref false in
      let backlog_changed = ref false in
      (* The local Keeper list reads each Keeper's meta, which a row change
         announces; hand edits to a declaration show on arrival or [r]. *)
      let local_keepers_changed = ref false in
      let waiting_inventory_changed = ref [] in
      let turns_changed = ref false in
      let turn_state_keepers = ref [] in
      let datasets_owed = ref [] in
      let connectors_changed = ref false in
      let transport_measured = ref false in
      let previews_changed = ref [] in
      (* Same shape again for the pane's Changes tab: a tool call the
         selected keeper completed may have written a file, so the tab
         asks once per batch. Agent-core events name their lane; the
         roster's trace ids resolve it. *)
      let pane_changes_keeper = acting_pane_changes_keeper state in
      let pane_keeper_acted = ref false in
      let trace_reading = Tui_decode.keeper_trace_projection state.keepers in
      let traces = trace_reading.bindings in
      let acted_by_pane_keeper event =
        match pane_changes_keeper with
        | None -> false
        | Some name -> (
            match Masc_tui_acting.actor_of_event ~traces event with
            | Masc_tui_acting.Actor_named actor -> String.equal name actor
            | Masc_tui_acting.Actor_unnamed | Masc_tui_acting.Actor_server -> false)
      in
      List.iter
        (fun (delivery : Masc_tui_observer.delivery) ->
          (* SSE publication commits IDs in order. Replaying a committed ID
             must not append the event or retrigger its dependent refreshes. *)
          let already_applied =
            match instance_id, delivery.cursor, state.observer_cursor with
            | Some instance_id, Some cursor, Some applied ->
                String.equal instance_id applied.instance_id && cursor <= applied.event_id
            | (None, _, _) | (_, None, _) | (_, _, None) -> false
          in
          if not already_applied then begin
          (match delivery.decoded with
          | Masc_tui_observer.Event event ->
              (match state.observer with
               | Observer_live live ->
                   state.observer <-
                     Observer_live { live with events = live.events + 1 }
               | Observer_off | Observer_opening
               | Observer_closed_before_answer _ | Observer_closed_after_live _
                 -> ());
              (match Masc_tui_observer.chat_appended_keeper event with
               | Some appended_keeper
                 when state.msg_target_keeper_name = Some appended_keeper ->
                   (* Owed whatever the view: the chat reads it when it is
                      next on screen at its newest row. *)
                   open_chat_gained_turn := true
               | Some _ | None -> ());
              (match Masc_tui_observer.memory_journal_appended_keeper event with
               | Some keeper when state.msg_target_keeper_name = Some keeper ->
                   open_chat_memory_grew := true
               | Some _ | None -> ());
              (* The chat history carries the exact Skill evidence of its
                 turns, read from the Keeper's activation ledger
                 (RFC-0483 L5). *)
              (match Masc_tui_observer.skill_activations_keeper event with
               | Some keeper when state.msg_target_keeper_name = Some keeper ->
                   open_chat_skill_ledger_changed := true
               | Some _ | None -> ());
              (match Masc_tui_observer.composite_changed_keeper event, selected_keeper state with
               | Some keeper, Some (selected : keeper) when String.equal keeper selected.k_name ->
                   selected_composite_changed := true
               | Some _, (Some _ | None) | None, _ -> ());
              (match Masc_tui_observer.metrics_appended_keeper event, keeper_log_target state with
               | Some keeper, Some (shown : keeper) when String.equal keeper shown.k_name ->
                   shown_metrics_appended := true
               | Some _, (Some _ | None) | None, _ -> ());
              (match Masc_tui_observer.tool_call_keeper event, selected_keeper state with
               | Some keeper, Some (selected : keeper) when String.equal keeper selected.k_name ->
                   selected_tool_called := true
               | Some _, (Some _ | None) | None, _ -> ());
              (* A Board event that names no post may still be about the open
                 one (a vote on one of its comments), so it reads too. *)
              if Option.is_some (Masc_tui_observer.board_changed_post event) then
                board_changed := true;
              if Masc_tui_observer.gate_snapshot_changed event then gate_changed := true;
              if Masc_tui_observer.held_calls_changed event then held_calls_changed := true;
              if Masc_tui_observer.asks_changed event then asks_changed := true;
              if Masc_tui_observer.async_requests_changed event then async_requests_changed := true;
              Option.iter (fun keeper -> async_request_keepers := keeper :: !async_request_keepers)
                (Masc_tui_observer.async_requests_keeper event);
              Option.iter (fun keeper -> skill_activation_keepers := keeper :: !skill_activation_keepers)
                (Masc_tui_observer.skill_activations_keeper event);
              if Masc_tui_observer.skill_catalog_published event then skill_catalog_published := true;
              if Masc_tui_observer.lane_addon_exports_changed event then lane_addon_exports_changed := true;
              if Masc_tui_observer.transport_health_measured event then
                transport_measured := true;
              (match Masc_tui_observer.dataset_owed event with
               | Some dataset ->
                   (match Masc.Workspace_dataset_event.kind dataset with
                    | Masc.Workspace_dataset_event.Kind.Backlog -> backlog_changed := true
                    | Masc.Workspace_dataset_event.Kind.(
                        Repositories | Verification_requests | Keeper_metrics | Harness_verdicts
                        | Goals | Runtime_config | Connectors | Keeper_oauth_attempts
                        | Skill_activations | Skill_catalog | Clients | Account_emails
                        | Provider_usage | Provider_standing | Keeper_costs | Workspace_health
                        | Runtime_probe | Runtime_metrics | Lanes | Machine_live | Memory_health
                        | World_memory | Play_seats | Dashboard_observation | Play_room
                        | Lane_addons | Browser_observation) -> ());
                   datasets_owed := dataset :: !datasets_owed
               | None -> ());
              if Masc_tui_observer.gate_connector_changed event then connectors_changed := true;
              if Masc_tui_observer.goal_projection_changed event then goals_changed := true;
              (match Masc_tui_observer.turn_change event with
               | Some (keeper, Masc_tui_observer.Turn_state) ->
                   turns_changed := true;
                   turn_state_keepers := keeper :: !turn_state_keepers
               | Some (keeper, Masc_tui_observer.Turn_preview) ->
                   previews_changed := keeper :: !previews_changed
               | None -> ());
              if Masc_tui_observer.pending_confirms_changed event then pending_confirms_changed := true;
              if Masc_tui_observer.schedules_changed event then schedules_changed := true;
              if Masc_tui_observer.runtime_config_changed event then runtime_config_changed := true;
              Option.iter (fun keeper -> event_queue_keepers := keeper :: !event_queue_keepers)
                (Masc_tui_observer.event_queue_changed event);
              Option.iter (fun appended -> runtime_journals := appended :: !runtime_journals)
                (Masc_tui_observer.runtime_journal_appended event);
              if Masc_tui_observer.tool_modes_changed event then tool_modes_changed := true;
              (match Masc_tui_observer.board_changed_post event, board_post_on_screen state with
               | Some (Some post), Some open_post when String.equal post open_post ->
                   open_board_post_changed := true
               | Some None, Some _ -> open_board_post_changed := true
               | Some (Some _), (Some _ | None) | Some None, None | None, _ -> ());
              (match event with
               | Masc_tui_observer.Keeper_chat_stream_frame { keeper; operation_id; seq; at; _ } ->
                   observe_journal keeper (Keeper_chat_log.Operation operation_id) seq at
               | Masc_tui_observer.Agent_core _
               | Masc_tui_observer.Keeper_heartbeat _
               | Masc_tui_observer.Keeper_tool_call _
               | Masc_tui_observer.Keeper_tool_call_evidence_committed _
               | Masc_tui_observer.Keeper_turn_complete _
               | Masc_tui_observer.Keeper_turn_observation _
               | Masc_tui_observer.Keeper_composite_changed _ | Masc_tui_observer.Keeper_metrics_appended _
               | Masc_tui_observer.Keeper_chat_appended _
               | Masc_tui_observer.Keeper_memory_journal_appended _ | Masc_tui_observer.Keeper_runtime_journal_appended _
               | Masc_tui_observer.Keeper_waiting_inventory_changed _ | Masc_tui_observer.Keeper_roster_change _ | Masc_tui_observer.Keeper_turn_changed _ | Masc_tui_observer.Keeper_async_requests_changed _ | Masc_tui_observer.Keeper_skill_activations_changed _
               | Masc_tui_observer.Fusion_run_status _
               | Masc_tui_observer.Internal_agent_runs_changed _ | Masc_tui_observer.Workspace_store_changed _ | Masc_tui_observer.Dataset_changed _ | Masc_tui_observer.Gate_connector_changed _ | Masc_tui_observer.Keeper_event_queue_changed _ | Masc_tui_observer.Board_changed _ | Masc_tui_observer.Approval_change _
               | Masc_tui_observer.Lane_resource _
               | Masc_tui_observer.Snapshot _ | Masc_tui_observer.Execution_snapshot | Masc_tui_observer.Other _ ->
                   ());
              (match event with
               | Masc_tui_observer.Fusion_run_status { keeper; run_id; _ } ->
                   fusion_status_seen :=
                     Masc_tui_fusion_updates.note_run_changed
                       ~open_run_id:fusion_open_run_id !fusion_status_seen ~run_id;
                   (* A running fusion is an item of its Keeper's waiting list. *)
                   waiting_inventory_changed := keeper :: !waiting_inventory_changed
               | Masc_tui_observer.Keeper_waiting_inventory_changed { keeper; _ } ->
                   Masc_tui_waiting_inventory.keeper_changed state.waiting_inventory keeper;
                   waiting_inventory_changed := keeper :: !waiting_inventory_changed
               | Masc_tui_observer.Keeper_roster_change change ->
                   owe_keeper_roster_change state change;
                   (* The Clients roster lists the registry's Keepers by
                      phase, so a registry row change re-reads it too. *)
                   owe_clients_read state;
                   (match change with
                    | Masc_tui_observer.Every_row_changed -> local_keepers_changed := true
                    | Masc_tui_observer.Keeper_row_changed { keeper } ->
                        if not !local_keepers_changed
                           && Masc_tui_loader.local_keeper_meta_moved
                                 state.local_base_path keeper
                        then local_keepers_changed := true);
                   (* A Keeper's metadata and configuration feed its
                      effective tool surface. *)
                   (match change, selected_keeper state with
                    | Masc_tui_observer.Every_row_changed, (Some _ | None) -> tools_inventory_changed := true
                    | Masc_tui_observer.Keeper_row_changed { keeper }, Some (selected : keeper)
                      when String.equal keeper selected.k_name ->
                        tools_inventory_changed := true
                    | Masc_tui_observer.Keeper_row_changed _, (Some _ | None) -> ())
               | Masc_tui_observer.Approval_change
                   (Masc_tui_observer.Tool_approval_mode_changed { keeper })
                 when Option.exists (fun (selected : keeper) -> String.equal keeper selected.k_name)
                        (selected_keeper state) ->
                   (* The approval mode sets the native tool posture. *)
                   tools_inventory_changed := true
               | Masc_tui_observer.Execution_snapshot ->
                   (* The execution projection is the web's. A task write is
                      announced to the TUI as [Backlog]. *)
                   ()
               | Masc_tui_observer.Agent_core
                   { kind = Masc_tui_observer.Relay_subscription_loss
                       { source_id; sequence; _ }; _ } ->
                   let fresh, sequences =
                     note_observer_source_loss ~source_id ~sequence
                       state.observer_source_loss_sequences in
                   state.observer_source_loss <- true;
                   state.observer_source_loss_sequences <- sequences;
                   if fresh then observer_source_loss_seen := true
               | Masc_tui_observer.Keeper_tool_call _
               | Masc_tui_observer.Agent_core { kind = Masc_tui_observer.Tool_completed; _ }
                 when acted_by_pane_keeper event ->
                   pane_keeper_acted := true
               | Masc_tui_observer.Agent_core
                   { kind =
                       ( Masc_tui_observer.Tool_called | Masc_tui_observer.Tool_completed
                       | Masc_tui_observer.Turn_started | Masc_tui_observer.Turn_ready
                       | Masc_tui_observer.Turn_completed
                       | Masc_tui_observer.Agent_started
                       | Masc_tui_observer.Agent_completed _
                       | Masc_tui_observer.Agent_failed _
                       | Masc_tui_observer.Agent_yielded _
                       | Masc_tui_observer.Agent_input_required _
                       | Masc_tui_observer.Tool_approval_completed
                       | Masc_tui_observer.Telemetry
                       | Masc_tui_observer.Agent_core_other _ );
                     _ }
               | Masc_tui_observer.Keeper_heartbeat _
               | Masc_tui_observer.Keeper_tool_call _
               (* The Changes pane reads again on the skill tool's own
                  return, not on each of its nodes. *)
               | Masc_tui_observer.Keeper_tool_call_evidence_committed _
               | Masc_tui_observer.Keeper_turn_complete _
               | Masc_tui_observer.Keeper_turn_observation _
               | Masc_tui_observer.Keeper_composite_changed _ | Masc_tui_observer.Keeper_metrics_appended _
               | Masc_tui_observer.Keeper_chat_appended _
               | Masc_tui_observer.Keeper_memory_journal_appended _ | Masc_tui_observer.Keeper_runtime_journal_appended _
               | Masc_tui_observer.Keeper_chat_stream_frame _
               | Masc_tui_observer.Keeper_async_requests_changed _ | Masc_tui_observer.Keeper_skill_activations_changed _ | Masc_tui_observer.Keeper_turn_changed _
               | Masc_tui_observer.Internal_agent_runs_changed _ | Masc_tui_observer.Workspace_store_changed _ | Masc_tui_observer.Dataset_changed _ | Masc_tui_observer.Gate_connector_changed _ | Masc_tui_observer.Keeper_event_queue_changed _ | Masc_tui_observer.Board_changed _
               | Masc_tui_observer.Approval_change
                   ( Masc_tui_observer.Approval_queue_changed
                   | Masc_tui_observer.Approval_rules_changed
                   | Masc_tui_observer.Gate_mode_changed
                   | Masc_tui_observer.Tool_approval_waits_changed _
                   | Masc_tui_observer.Tool_approval_mode_changed _
                   | Masc_tui_observer.Keeper_asks_changed _
                   | Masc_tui_observer.Installation_asks_changed _ )
               | Masc_tui_observer.Lane_resource _
               | Masc_tui_observer.Snapshot _ | Masc_tui_observer.Other _ ->
                   ());
              state.acting <-
                { Masc_tui_acting.ae_at = received; ae_event = event }
                :: state.acting;
              (match state.acting_filter with
               | Masc_tui_acting.Turns -> ()
               | Actions | Everything ->
                   if Masc_tui_acting.visible state.acting_filter event
                      && (state.acting_cursor > 0 || Option.is_some state.acting_detail)
                   then state.acting_cursor <- state.acting_cursor + 1);
              (* A row arriving at the top pushes every row down one. An
                 operator scrolled into the past keeps the rows they were
                 reading and a count of what arrived above them. *)
              if state.acting_scroll > 0 then begin
                state.acting_scroll <- Masc_tui_types.scroll_down_from state.acting_scroll ~by:1;
                state.acting_unseen <- state.acting_unseen + 1
              end
          | Masc_tui_observer.Undecodable reason ->
              state.acting_undecodable <- state.acting_undecodable + 1;
              state.acting_undecodable_last <- Some reason);
          (match delivery.decoded, delivery.cursor, instance_id with
           | Masc_tui_observer.Event _, Some event_id, Some instance_id ->
               state.observer_cursor <- Some { instance_id; event_id }
           | Masc_tui_observer.Event _, (None | Some _), _
           | Masc_tui_observer.Undecodable _, _, _ -> ());
          end)
        decoded;
      (* The local work read also lists the Goals waiting for confirmation. *)
      if !backlog_changed || !observer_source_loss_seen || !goals_changed || !local_keepers_changed then
        (* Work reads its own local source. Its agenda says whether a Task's
           assignee is a Keeper, so a Keeper appearing or leaving owes it
           too. A read already in flight queues one newer follow-up. *)
        Masc_tui_transport.Local_sources.launch_work_read state ~mailbox ~intent:Snapshot_read.Refresh state.local_base_path;
      (* The local Keeper list is the metadata files and the Keepers runtime
         config declares without one. While the server or the feed is down
         nothing is announced; the Keepers run in the server, so their files
         hold still, and a CLI write shows on a reopen that missed events or
         on [r]. A clean resume replays the server's own roster events. *)
      if !local_keepers_changed || !observer_source_loss_seen || !runtime_config_changed then
        Masc_tui_transport.Local_sources.launch_keeper_read state ~mailbox ~intent:Snapshot_read.Refresh state.local_base_path;
      if !observer_source_loss_seen then owe_agenda_revalidation state;
      if !observer_source_loss_seen then begin
        state.play_room <- Option.map Masc_tui_play_room.revalidate state.play_room;
        revalidate_visible_fusion state ~mailbox;
        (match acting_pane_changes_keeper state with
         | Some keeper_name when server_authority_ready state ->
             state.acting_pane_changes <-
               Masc_tui_fetched.invalidate ~reason:(Request_failed "Observer events were lost")
                 state.acting_pane_changes;
             let key = { apk_keeper = keeper_name
                       ; apk_scope = state.workspace_authority, state.workspace_read_authority } in
             (match Masc_tui_fetched.current_key state.acting_pane_changes with
              | Some current when same_acting_pane_key current key
                                  && Masc_tui_fetched.in_flight state.acting_pane_changes ->
                  state.acting_pane_changes_loss_followup <- Some key
              | Some _ | None ->
                  launch_acting_pane_changes_load ~force:true state ~mailbox ~keeper_name)
         | Some _ | None ->
             (* A hidden pane must owe a read when it is next shown. Clearing
                also retires any response that was in flight before the loss. *)
             state.acting_pane_changes <- Masc_tui_fetched.clear state.acting_pane_changes;
             state.acting_pane_changes_loss_followup <- None;
             state.acting_pane_changes_at <- None);
        (* The chat owes an audited read whatever the view; it reads when it
           is next on screen at its newest row. *)
        (match state.msg_target_keeper_name with
         | Some keeper_name ->
             update_history_owed ~audit:true state ~keeper_name Masc_tui_owed_read.changed;
             launch_owed_history state ~mailbox;
             if state.view = Keepers Keeper_message then
               launch_keeper_chat_tool_details_load ~force:true state ~mailbox ~keeper_name
         | None -> ());
        Option.iter
          (fun (keeper : keeper) -> owe_keeper_calls_read state ~mailbox ~keeper_name:keeper.k_name)
          (selected_keeper state);
        start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port ~intent:Revalidate
          ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight
          ~scoped_refresh_followup ~mailbox
      end;
      if
        List.length state.acting
        > Masc_tui_types.acting_retained_entries
          + Masc_tui_types.acting_retained_quiet
      then begin
        let kept, dropped =
          Masc_tui_acting.retain
            ~actions:Masc_tui_types.acting_retained_entries
            ~quiet:Masc_tui_types.acting_retained_quiet
            ~event_of:(fun entry -> entry.Masc_tui_acting.ae_event)
            state.acting
        in
        state.acting <- kept;
        state.acting_dropped <- state.acting_dropped + dropped
      end;
      if !pane_keeper_acted then refresh_acting_pane_changes state ~mailbox;
      (* Schedules and confirmations are items of the waiting list that
         announce through their own events and name no Keeper (RFC-0481
         §3.4). They owe the list a read without marking every Keeper
         unverified, which would blank the whole waiting column for a read
         on each of them; a held schedule announces every runner tick. A
         read already in flight is still not taken as current, so its
         Keepers read as unverified until the read that follows. *)
      let waiting_keepers = List.sort_uniq String.compare !waiting_inventory_changed in
      let waiting_unattributed = !pending_confirms_changed || !schedules_changed in
      if waiting_keepers <> [] then
        note_keeper_waiting_change state (Waiting_keepers waiting_keepers);
      if waiting_unattributed then note_keeper_waiting_change state Waiting_unattributed;
      if waiting_keepers <> [] || waiting_unattributed then owe_keeper_waiting_read state;
      (if !turns_changed && not !observer_source_loss_seen then owe_keeper_turns_read state);
      (if !turn_state_keepers <> [] && not !observer_source_loss_seen then
         owe_keeper_story_turns_read_for state ~keepers:!turn_state_keepers);
      (if !backlog_changed && not !observer_source_loss_seen then begin
         owe_verification_read state;
         owe_goal_projection_reads state;
         (* The call scope reads the selected Keeper's current Task. *)
         owe_tools_inventory_read state
       end);
      (if not !observer_source_loss_seen then List.iter (owe_dataset_read state) !datasets_owed);
      (if !connectors_changed && not !observer_source_loss_seen then owe_connectors_read state);
      (if !transport_measured && not !observer_source_loss_seen then
         owe_pushed_read state Surface_read_source.Transport);
      (if !runtime_config_changed && not !observer_source_loss_seen then owe_runtime_config_read state);
      state.keeper_previews_unread <-
        List.sort_uniq String.compare (!previews_changed @ state.keeper_previews_unread);
      (* The pane otherwise reloads only on open and on its own sends — a
         turn appended from anywhere else (API chat, another operator, a
         connector) stayed invisible until the operator left and re-entered.
         The read is owed rather than started here: one in flight, or a pane
         scrolled into the past (which keeps its place), takes the change once
         it can (RFC-0480 §3.1). *)
      (* A loss in this batch already owes the chat an audited read that
         starts after these turns were appended. *)
      (if !shown_metrics_appended && not !observer_source_loss_seen then
         Option.iter
           (fun (keeper : keeper) -> owe_keeper_logs_read state ~mailbox ~keeper_name:keeper.k_name)
           (keeper_log_target state));
      (if !selected_composite_changed && not !observer_source_loss_seen then
         Option.iter
           (fun (keeper : keeper) ->
             owe_keeper_composite_read state ~mailbox ~keeper_name:keeper.k_name)
           (selected_keeper state));
      (if !selected_tool_called && not !observer_source_loss_seen then
         Option.iter
           (fun (keeper : keeper) ->
             owe_keeper_calls_read state ~mailbox ~keeper_name:keeper.k_name)
           (selected_keeper state));
      (if !open_board_post_changed && not !observer_source_loss_seen then
         Option.iter
           (fun post_id -> owe_board_post_read state ~mailbox ~post_id)
           (board_post_on_screen state));
      (if !board_changed && not !observer_source_loss_seen && state.view = Board then
         owe_board_list_read state);
      (* The planning payload carries the task backlog, which a task write
         announces as [Backlog]. *)
      (if (!goals_changed || !backlog_changed) && not !observer_source_loss_seen
          && state.view = Planning then
         owe_planning_reads state);
      (if !gate_changed && not !observer_source_loss_seen then begin
         owe_gate_snapshot_read state;
         (* The Goal tree carries the approvals waiting on each Goal. *)
         owe_goal_projection_reads state
       end);
      (if !held_calls_changed && not !observer_source_loss_seen then owe_held_calls_read state);
      (if !asks_changed && not !observer_source_loss_seen then owe_asks_read state);
      (if !async_requests_changed && not !observer_source_loss_seen then
         owe_async_requests_read state);
      (if not !observer_source_loss_seen then
         List.iter (owe_tools_async_detail_read state) !async_request_keepers);
      (* A Keeper's ledger write owes its Usage answer and, for the selected
         Keeper, its activations. A published catalog owes the catalog and
         every Usage answer, which the server counts against it. *)
      (if not !observer_source_loss_seen then
         List.iter (owe_skill_activations_read state) !skill_activation_keepers);
      (if !skill_catalog_published && not !observer_source_loss_seen then begin
         owe_tools_catalog_read state;
         owe_every_skill_usage_read state
       end);
      (* The selected Keeper's effective tool surface reads its metadata and
         configuration, its approval mode, the skill catalog, the backlog's
         task skills, the runtime catalogue and the Lane Add-on exports. *)
      (if (!tools_inventory_changed || !skill_catalog_published || !runtime_config_changed
           || !backlog_changed
           || !lane_addon_exports_changed)
          && not !observer_source_loss_seen then
         owe_tools_inventory_read state);
      (* An open source Task reads its body from the task backlog, which a
         task write announces as [Backlog]. *)
      (if !backlog_changed && not !observer_source_loss_seen then
         owe_tools_async_task_read state);
      (if !pending_confirms_changed && not !observer_source_loss_seen then
         owe_pending_confirms_read state);
      (if !schedules_changed && not !observer_source_loss_seen then begin
         owe_agenda_revalidation state;
         owe_keeper_schedules_read state
       end);
      (if !event_queue_keepers <> [] && not !observer_source_loss_seen then
         owe_schedule_reads_for_queue_writes state ~keepers:!event_queue_keepers);
      (if not !observer_source_loss_seen then
         List.iter
           (fun (keeper, journal) ->
             if Option.equal String.equal (chat_keeper_on_screen state) (Some keeper) then
               owe_chat_journal_read state ~keeper journal)
           !runtime_journals);
      (if !tool_modes_changed && not !observer_source_loss_seen then owe_tool_modes_read state);
      (if (!open_chat_gained_turn || !open_chat_memory_grew || !open_chat_skill_ledger_changed)
          && not !observer_source_loss_seen then
         match state.msg_target_keeper_name with
         | Some keeper_name ->
             update_history_owed state ~keeper_name Masc_tui_owed_read.changed;
             launch_owed_history state ~mailbox;
             (* A results or full view joins the fresh activities against the
                call snapshot; without a refresh the appended turns sit at
                "no call-log row" until the operator cycles the view. The
                loader is inflight-guarded and a mid-flight load turns force
                into one queued follow-up, so a burst of turns collapses. *)
             (* The calls slot is shared with the Keeper_calls surface, so only
                the chat on screen reads it. *)
             if !open_chat_gained_turn
                && state.view = Keepers Keeper_message
                && state.msg_tool_visibility <> Tools_compact then
               Masc_tui_work_requests.Schedule_call_requests.launch_keeper_calls_load ~force:true state ~mailbox keeper_name
         | None -> ());
      (* A frame of a turn this pane did not open: its journal grew, so read
         it from where the pane's record ends. The frame itself is not
         folded -- see [journal_follow_for_source]. *)
      (match state.msg_target_keeper_name with
       | Some keeper_name ->
           List.iter
             (fun (source, (seq, at)) ->
               let key = keeper_name, source in
               match
                 journal_follow_for_source state ~keeper_name ~source ~seq ~at
               with
               | Follow_nothing -> ()
               | Follow_read_after_inflight ->
                   journal_read_wanted state key seq
               | Follow_read { started_at; since_seq } ->
                   Masc_tui_chat_dispatch.Chat_journals.launch_keeper_chat_journal_loads state ~mailbox ~keeper_name
                     [ (source, started_at, since_seq) ])
             (List.rev !open_chat_stream_frames)
       | None -> ());
      (* The notification is a change signal; the HTTP read remains the
         source of the projection. A signal during a read queues one follow-up. *)
      (if (!fusion_status_seen).any then
         let demand = Masc_tui_fusion_updates.After_change in
         match state.view with
         | Fusion ->
             launch_fusion_runs_load ~demand state ~mailbox;
             if (!fusion_status_seen).open_run then
               (match state.fusion_mode with
                | Fusion_detail run_id ->
                    Masc_tui_work_actions.Detail_navigation.launch_fusion_detail_load ~demand state ~mailbox ~run_id
                | Fusion_historical_detail reference ->
                    Masc_tui_work_actions.Detail_navigation.launch_fusion_historical_detail_load ~demand state ~mailbox ~reference
                | Fusion_list -> ())
         | Keepers Keeper_detail when state.detail_tab = Detail_runs ->
             launch_fusion_runs_load ~demand state ~mailbox
         | Keepers (Keeper_detail | Keeper_list | Keeper_logs | Keeper_calls
                   | Keeper_message | Keeper_runtime_pick)
         | Overview | Acting | Metrics | Memory | Lanes | Clients | Board
         | Approvals | Planning | Schedules | Verification | Harness
         | Repositories | Code | Changes | Connectors | Runtime | Config
         | Resources | Tools | System_logs -> ());
      Drawn_changed
  | Original_msg answer -> Original_results.apply state answer; Drawn_changed
  | Task_msg (Task_creation_read_done (request,result)) ->
      ignore (complete_task_creation_inspection state request result);
      Drawn_changed
  | Task_msg (Task_dispatch_completed request) ->
      (match take_task_dispatch_completion state request with
       | None -> ()
       | Some outcome ->
         let intent = Masc_tui_task_dispatch.intent request.tdr_dispatch in
         (match outcome with
          | Masc_tui_task_dispatch.Created {task_id;workspace} ->
              report_action state "task" (Printf.sprintf "%s created for %s" task_id intent.keeper);
              remember_task_followup state ~expected_workspace:workspace
                (Task_handoff {keeper=intent.keeper;task_id;title=intent.title;body=intent.body;
                  editor=Some {the_authority=request.tdr_authority;the_revision=request.tdr_editor;
                    the_target=request.tdr_editor_keeper}});
              resume_task_followups ~server_contact state ~mailbox ~refresh_inflight:http_refresh_inflight
                ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup
          | Not_sent detail ->
              ignore (restore_task_dispatch_input state request);
              report_action state "error" (Printf.sprintf "task for %s was not sent: %s; /task-recover retains the command"
                intent.keeper detail)
          | Kept_back notice ->
              (* The guard withdrew the creation before it was sent; the
                 command is restored and retained as for [Not_sent]. *)
              ignore (restore_task_dispatch_input state request);
              report_action state "error" (notice ^ " · /task-recover retains the command")
          | Server_error detail ->
              report_action state "error" (Printf.sprintf "task creation for %s returned an error: %s; use /task-inspect before /task-recover"
                intent.keeper detail)
          | Unconfirmed detail ->
              report_action state "error" (Printf.sprintf "task creation outcome for %s is unconfirmed: %s; use /task-inspect before /task-recover"
                intent.keeper detail)));
      Drawn_changed
  | Observer_msg (Observer_closed (owner, workspace, outcome)) ->
      if Masc_tui_async_protocol.observer_stream_owned state owner then begin
      state.observer_stream_owner <- None;
      state.observer_machine <- None;
      state.observer_browser <- None;
      state.observer_play <- None;
      (* The disconnect itself is not agenda staleness: the observer status
         display carries the broken-since time (RFC-0480 §3.3), and the reopen
         settles the question -- a gap revalidates, a Resumed replay redelivers
         the schedules events that changed anything. Marking Refresh_needed
         here made every clean resume owe a read that proved nothing, and the
         "may be out of date" marker then outlived the resume (review, PR
         #50679). A real read debt is flagged where it is incurred. *)
      let was_opening = state.observer = Observer_opening in
      let reason =
        match outcome with
        | Ok () -> "the server closed the stream"
        | Error (Masc_tui_http.Transport_failed detail) -> detail
        | Error (Masc_tui_http.Invalid_handshake detail) ->
            state.observer_replay <- Observer_replay_rejected detail;
            "observer stream handshake rejected: " ^ detail
        | Error (Masc_tui_http.Retry_without_cursor (requested, detail)) ->
            if state.observer_cursor = Some requested then begin
              state.observer_cursor <- None;
              let replay_detail = "cursor discarded; disconnected events were not replayed: " ^ detail in
              state.observer_replay <- Observer_replay_unavailable replay_detail;
              add_event state "observer" ("Replay unavailable: " ^ replay_detail)
            end;
            "observer replay cannot resume; reconnecting: " ^ detail
        | Error (Masc_tui_http.Http_refused { status; detail }) ->
            (* A workspace refusal also uses 409, but it retires the reading,
               not the MCP session. Only a session conflict reinitializes it. *)
            if Masc_tui_http.observer_workspace_refused ~status ~detail then begin
              apply_refused_workspace_identity state ~mailbox ~detail None;
              (* A refused scope must be re-established without waiting for
                 the periodic refresh that this reconnect will replace. *)
              start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
                ~intent:Revalidate ~refresh_inflight:http_refresh_inflight
                ~scoped_refresh_inflight:http_scoped_refresh_inflight
                ~scoped_refresh_followup ~mailbox
            end
            else
              (match status with 404 | 409 -> state.mcp_session <- None | _ -> ());
            Printf.sprintf "observer stream refused with %d: %s" status detail
      in
      record_observer_closed state ~workspace outcome ~reason ~at:(Unix.gettimeofday ());
      (* A stream that carried readings cannot cover its closed interval with
         a replay: file-backed snapshots may have moved without any event.
         The reopen owes one revalidate; a first open that never answered
         does not. *)
      if not was_opening then state.observer_revalidate_owed <- true;
      let owner = ref () in
      state.observer_retry_owner <- Some owner;
      Masc_tui_transport.Event_streams.schedule_observer_retry state ~mailbox owner;
      if was_opening then resume_fusion_after_observer_failure state ~mailbox
      end;
      Drawn_changed
  | Observer_msg (Observer_opened _) ->
      (* The reopen consumes the revalidate owed for its closed interval; a
         first open owes nothing because nothing was carried before it. *)
      if state.observer_revalidate_owed then begin
        state.observer_revalidate_owed <- false;
        start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
          ~intent:Revalidate ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight
          ~scoped_refresh_followup ~mailbox
      end;
      Drawn_changed
  | Observer_msg (Observer_received _) -> Drawn_changed
  | Observer_msg (Observer_retry_due (authority, expected)) ->
      if Masc_tui_async_protocol.observer_retry_owned state ~authority expected then
           (match state.workspace_identity, state.connection_status with
            | (Workspace_identity_match | Workspace_identity_mismatch _), (Connected | Degraded) ->
                if server_authority_ready state then
                  Masc_tui_transport.Event_streams.open_observer_if_due ~browser_scope:observer_browser_scope state ~retry_closed:true ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                    ~port:state.port ~mailbox
                else Masc_tui_transport.Event_streams.schedule_observer_retry state ~mailbox expected
            | (Workspace_identity_unread | Workspace_identity_match_unconfirmed _
              | Workspace_identity_match | Workspace_identity_mismatch _),
              (Disconnected | Connecting | Booting)
            | (Workspace_identity_unread | Workspace_identity_match_unconfirmed _),
              (Connected | Degraded) ->
                Masc_tui_transport.Event_streams.schedule_observer_retry state ~mailbox expected
            (* An account server has no observer to reopen. *)
            | (Workspace_identity_unread | Workspace_identity_match_unconfirmed _
              | Workspace_identity_match | Workspace_identity_mismatch _),
              Account_server _ -> ());
      Drawn_changed
  | Observer_msg (Observer_recovery_opened (authority, owner, opened)) ->
      (* A stream that would not open opening now is the server answering
         again: the owed pass starts now. It is not a [/health] answer, so
         the run of failures goes on (RFC tui-one-screen-grammar §2). *)
      if Masc_tui_async_protocol.observer_recovery_owned state ~authority owner then begin
        let previous = Masc_tui_refresh_pace.next_try state.refresh_pace in
        state.refresh_pace <- Masc_tui_refresh_pace.stream_opened opened state.refresh_pace;
        if previous = Masc_tui_refresh_pace.next_try state.refresh_pace then Drawn_unchanged
        else Drawn_changed
      end else Drawn_unchanged
  | Observer_msg (Observer_recovery_ready (authority, owner, session_id)) ->
      if Masc_tui_async_protocol.observer_recovery_owned state ~authority owner then begin
        Option.iter (fun session_id -> state.mcp_session <- Some session_id) session_id;
        start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port ~intent:Revalidate
          ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup ~mailbox
      end;
      Drawn_changed
  | Observer_msg (Observer_found_account_server (authority, owner)) ->
      (* A recovery that saw the account server has ended, so its owner names
         no loop now. The full refresh reads /health again and applies it. *)
      let from_recovery = match state.observer_recovery_owner with
        | Some current -> current == owner
        | None -> false in
      if from_recovery then state.observer_recovery_owner <- None;
      if authority = state.workspace_authority
         && (from_recovery || Masc_tui_async_protocol.observer_stream_owned state owner) then
        start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port ~intent:Revalidate
          ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup ~mailbox;
      Drawn_changed
  | Observer_msg (Observer_recovery_identity (authority, owner, live, session_id, instance, origin, attested)) ->
      if Masc_tui_async_protocol.observer_recovery_identity_owned state
           ~authority ~owner ~live ~instance ~origin then begin
        (* The response attests the exact requested workspace and readiness;
           build fields come from that response. Unreported health telemetry is
           unknown, not a fresh reading copied from the previous process. *)
        let base_path, masc_root = match origin with
          | Observer_existing_workspace expected -> expected.sid_base_path, expected.sid_masc_root
          | Observer_initial_workspace paths -> paths.lw_base_path, paths.lw_masc_root in
        let identity : Masc.Tui_decode.server_identity =
          { sid_version = attested.Sse_wire.version;
            sid_binary_commit = Option.value attested.binary_commit ~default:"";
            sid_binary_commit_age_s = None;
            sid_runtime_instance_id = None;
            sid_base_path = base_path;
            sid_masc_root = masc_root;
            sid_executable_in_worktree = None;
            sid_state_ready = Some true;
            sid_uptime = None;
            sid_sse_clients = None;
            sid_gc = None;
            sid_scheduler = None; sid_operator_action = None } in
        let before = read_authority state in
        state.connection_status <- Masc_tui_types.Degraded;
        apply_server_identity_reading state ~mailbox (Ok identity);
        state.mcp_session <- Some session_id;
        (match origin with
         | Observer_initial_workspace _ -> state.observer_scope_binding <- Observer_scope_bound instance
         | Observer_existing_workspace _ -> ());
        resume_reads_after_authority_change ~server_contact state ~mailbox
          ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup
          ~before
      end;
      Drawn_changed
  | Fleet_msg answer -> Fleet_results.apply state answer; Drawn_changed
  | Http_msg (Http_refresh_failed (err, approval_ticket, refresh_ticket)) ->
      http_refresh_inflight := false;
      Masc_tui_transport.Http_surface_collector.finish_observed_refresh state ~ticket:refresh_ticket;
      if Http_refresh_order.is_current state.http_refresh_order refresh_ticket then begin
      Option.iter
        (fun ao_ticket ->
           Masc_tui_refresh_settlement.Approvals_asks_settlement.apply_approval_observation state
             { ao_ticket; ao_result = Error err })
      approval_ticket;
      apply_server_identity_reading state ~mailbox (Error err);
      Masc_tui_refresh_settlement.Workspace_settlement.withdraw_currency_authority state;
      state.candle_observation <- Some (Error err);
      state.connection_status <- Masc_tui_types.Disconnected;
      Masc_tui_refresh_settlement.Http_dataset_settlement.note_read state Masc_tui_read_failure.Refresh_pass (Error (Request_failed err));
      Masc_tui_refresh_settlement.Http_dataset_settlement.fail_refresh_pace state;
      add_event state "error" err;
      Masc_tui_transport.Server_contact.react_to_contact server_contact state ~base_path
        ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port;
      end;
      start_scoped_refresh_followup ~server_contact state ~host:(Masc_tui_transport.Workspace_admission.server_peer_host)
        ~port:state.port ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight
        ~scoped_refresh_followup ~mailbox;
      Drawn_changed
  | Chat_msg (Chat_search_finished (generation,restart,plan,result)) ->
      if generation=Atomic.get state.msg_search_generation then begin
        let authority,keeper,needle=keeper_message_search_identity plan in
        if authority=state.workspace_authority && keeper_message_search_owned state plan
           && String.trim state.msg_find=needle then
          let notice=Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:(Some keeper) in
          match result with
          | Error detail -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure detail
          | Ok (work,matched) ->
              (match admit_keeper_message_search state work matched with
               | Some result -> apply_chat_search_result state ~target:(Some keeper) ~restart ~needle result
               | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
                   "/find source changed while searching; repeat /find to search the current conversation")
      end;
      Drawn_changed
  | (Keeper_msg Keeper_composer_released) ->
      Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox;
      Drawn_changed
  | Http_msg (Http_scoped_refresh_done (authority, currency_authority, results)) ->
      if authority = state.workspace_authority
         && Http_refresh_order.is_current state.http_refresh_order results.http_refresh_ticket then begin
      apply_http_scoped_refresh_success ~server_contact state ~currency_authority ~base_path ~mailbox
        ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup
        results
      end;
      start_scoped_refresh_followup ~server_contact state ~host:(Masc_tui_transport.Workspace_admission.server_peer_host)
        ~port:state.port ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight
        ~scoped_refresh_followup ~mailbox;
      Drawn_changed
  | Http_msg (Http_scoped_refresh_failed (authority, err, approval_ticket, refresh_ticket, latest, request)) ->
      let current_authority = authority = state.workspace_authority in
      let current_generation = Http_refresh_order.is_current state.http_refresh_order refresh_ticket in
      let owns_identity = Surface_read_order.owns_identity state.http_surface_reads request in
      Log.Transport.info "tui_surface_read_refused request=%d current_authority=%b current_generation=%b owns_identity=%b"
        (Surface_read_order.request_id request) current_authority current_generation owns_identity;
      if current_authority && current_generation && owns_identity then begin
        let before = read_authority state in
        apply_http_scoped_refresh_failure state ~mailbox ~refresh_ticket ~approval_ticket ~latest err;
        resume_reads_after_authority_change ~server_contact state ~mailbox
          ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup
          ~before
      end else
        Log.Transport.debug "discarded scoped refresh completion: workspace or navigation authority superseded";
      start_scoped_refresh_followup ~server_contact state ~host:(Masc_tui_transport.Workspace_admission.server_peer_host)
        ~port:state.port ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight
        ~scoped_refresh_followup ~mailbox;
      Drawn_changed
  | Board_msg (Board_post_refresh_done (request, result)) ->
      let current = Board_detail.is_current state.board_detail request in
      Masc_tui_board_updates.apply_board_post_load state ~report_error:(add_event state "error") request result;
      if current then begin
        let post_id = Board_detail.request_post_id request in
        (match result with
         | Ok (post, _, _) when String.equal post.bp_id post_id ->
             settle_board_post_owed state ~post_id Masc_tui_owed_read.succeeded
         | Ok _ | Error _ ->
             settle_board_post_owed state ~post_id
               (Masc_tui_owed_read.failed ~retry_s:Masc_tui_transport.Event_streams.stream_reconnect_s
                  ~max_retry_s:keeper_execute_stream_max_reconnect_s ~now:(Masc_tui_wake.Mono.now ())));
        launch_owed_board_post state ~mailbox
      end;
      Drawn_changed
  | Keeper_msg (Keeper_deletion_retry_done (operation_id, result)) ->
      let ko = state.ui_language = Lang_ko in
      let message = match result with
        | Ok () ->
          Printf.sprintf
            (if ko then "삭제 재시도 %s 접수됨 · 목록 다시 조회 중"
             else "Deletion retry %s accepted; refreshing inventory.")
            operation_id
        | Error (Request_failed detail) ->
          Printf.sprintf
            (if ko then "삭제 재시도 %s 확인 안 됨: %s · 목록을 다시 조회한 뒤 재시도"
             else "Deletion retry %s not confirmed: %s. Refresh inventory before retrying.")
            operation_id detail
        (* The retry was not sent: the kept-back notice, then the operation. *)
        | Error (Request_withdrawn refusal) ->
          workspace_refusal_text ~ko ~request:Kept_request.Keeper_deletion refusal
          ^ " · " ^ operation_id in
      state.keeper_deletions_retry_receipt <- Some (state.keeper_deletions_generation, message);
      report_action state (if Result.is_ok result then "system" else "error") message;
      Drawn_changed
  | Keeper_msg (Keeper_deletions_loaded (generation, result)) ->
      apply_keeper_deletions_read state ~generation result;
      if generation = state.keeper_deletions_generation && Result.is_ok result
         && Option.is_some state.keeper_deletions_retry_receipt then
        Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_deletions state ~mailbox ();
      Drawn_changed
  | Keeper_msg (Keeper_settings_save_changed (request,status,observed_ns)) ->
      let key = request.ksv_key in
      let current = keeper_settings_save_current state request in
      if apply_keeper_settings_save state request status then begin
        let phase = keeper_settings_save_phase status in
        Log.Transport.info
          "tui_keeper_settings_save keeper=%s intent=%s started_ns=%Ld observed_ns=%Ld admitted_ns=%Ld phase=%s current_origin=%b"
          key.ksk_keeper (keeper_settings_save_intent_name request)
          request.ksv_started_ns observed_ns (Mtime_clock.elapsed_ns ()) phase current;
        match status with
        | Settings_checking | Settings_reading | Settings_posting _ -> ()
        | Settings_finished (_,outcome) ->
            let severity = match outcome with
              | Settings_applied receipt -> receipt.severity | Settings_unchanged -> "system"
              | Settings_not_sent _ | Settings_kept_back _ | Settings_refused _ | Settings_observation_required _ | Settings_unconfirmed _ -> "error" in
            let origin = if current then "" else " (" ^ key.ksk_base_path ^ ")" in
            let ko = state.ui_language = Lang_ko in
            let message = match request.ksv_input,outcome with
              | Settings_editor_input _,Settings_applied receipt -> receipt.message ^ origin
              (* The kept-back notice leads, alone; the setting follows it. *)
              | (Sandbox_shortcut_input _ | Settings_editor_input _), Settings_kept_back _ ->
                  keeper_settings_save_outcome_detail ~ko outcome ^ " · " ^ keeper_settings_save_label request ^ origin
              | (Sandbox_shortcut_input _ | Settings_editor_input _),
                  (Settings_applied _ | Settings_unchanged | Settings_not_sent _ | Settings_refused _
                   | Settings_observation_required _ | Settings_unconfirmed _) ->
                  keeper_settings_save_label request ^ origin ^ " · " ^ keeper_settings_save_outcome_detail ~ko outcome in
            report_action state severity message;
            if current && state.view = Keepers Keeper_detail
               && Option.exists (fun (keeper : keeper) -> String.equal keeper.k_name key.ksk_keeper) (selected_keeper state)
            then
              match state.detail_tab with
              | Detail_instructions ->
                  state.keeper_config_view <- None; state.keeper_config_view_error <- None;
                  Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_config_view state ~mailbox key.ksk_keeper
              | Detail_sandbox ->
                  state.keeper_sandbox_view <- None;
                  Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_sandbox_view state ~mailbox key.ksk_keeper
              | Detail_info | Detail_items | Detail_secrets | Detail_github | Detail_identity
              | Detail_channels | Detail_automation | Detail_runs | Detail_terminal -> ()
      end;
      Drawn_changed
  | Runtime_msg (Runtime_form_save_changed (request, status, observed_ns)) ->
      let attached = runtime_form_is_attached state request in
      let current = runtime_form_save_current state request in
      if apply_runtime_form_save state request status then begin
        ignore (apply_runtime_document_save state request status);
        let phase = match status with
          | Form_checking -> "checking" | Form_previewing _ -> "previewing"
          | Form_posting _ -> "posting"
          | Form_finished (_, Form_saved _) -> "saved"
          | Form_finished (_, Form_not_sent _) -> "not_sent"
          | Form_finished (_, Form_kept_back _) -> "kept_back"
          | Form_finished (_, Form_invalid_account _) -> "invalid_account"
          | Form_finished (_, Form_refused _) -> "refused"
          | Form_finished (_, Form_conflict _) -> "conflict"
          | Form_finished (_, Form_unconfirmed _) -> "unconfirmed" in
        Log.Transport.info
          "tui_runtime_form_save started_ns=%Ld observed_ns=%Ld admitted_ns=%Ld phase=%s current_origin=%b attached=%b"
          request.rfs_started_ns observed_ns
          (Mtime_clock.elapsed_ns ()) phase current attached;
        match status with
        | Form_checking | Form_previewing _ | Form_posting _ -> ()
        | Form_finished (prepared, outcome) ->
            (match request.rfs_draft with
             | Config_document_draft _ ->
                 if Option.exists (fun token -> token == request.rfs_token) state.runtime_form_save_focus
                 then state.runtime_form_save_focus <- None
             | Model_form_draft _ | Account_form_draft _ -> ());
            if current then begin
              Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_config_load ~force:true state ~mailbox;
              (match outcome with
               | Form_saved _ | Form_unconfirmed _ ->
                   Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load ~intent:Snapshot_read.Refresh state ~mailbox;
                   Masc_tui_surface_requests.Memory_repository_requests.launch_runtime_surface_load state ~mailbox ~force:true;
                   launch_lanes_reread state ~mailbox
               | Form_not_sent _ | Form_kept_back _ | Form_invalid_account _ | Form_refused _ | Form_conflict _ -> ())
            end;
            if attached && current then begin
              match request.rfs_draft, outcome with
              | Config_document_draft _, (Form_saved _ | Form_not_sent _ | Form_kept_back _ | Form_invalid_account _
                  | Form_refused _ | Form_conflict _ | Form_unconfirmed _) -> ()
              | Model_form_draft _, Form_saved _ ->
                  state.runtime_model_form <- None; state.runtime_form_save_focus <- None
              | Account_form_draft form, Form_saved _ ->
                  state.runtime_account_form <- Option.bind prepared (fun draft ->
                    Option.bind draft.rfp_account (fun declaration ->
                      Option.map (Masc_tui_runtime_account_form.saved form ~id:declaration.id)
                        declaration.sign_in));
                  state.runtime_form_save_focus <- None
              | Account_form_draft _, Form_invalid_account form ->
                  state.runtime_account_form <- Some form
              | Model_form_draft form, (Form_not_sent _ | Form_kept_back _ | Form_invalid_account _
                  | Form_refused _ | Form_conflict _ | Form_unconfirmed _) ->
                  state.runtime_model_form <- Some (Masc_tui_model_form.refused form
                    (runtime_form_outcome_detail ~ko:(state.ui_language = Lang_ko) outcome))
              | Account_form_draft form, (Form_not_sent _ | Form_kept_back _ | Form_refused _
                  | Form_conflict _ | Form_unconfirmed _) ->
                  state.runtime_account_form <- Some (Masc_tui_runtime_account_form.refused form
                    (runtime_form_outcome_detail ~ko:(state.ui_language = Lang_ko) outcome))
            end;
            let origin = if current then "" else
                " (" ^ Tui_decode.Canonical_path.to_string request.rfs_workspace.sid_base_path ^ ")" in
            report_action state (match outcome with Form_saved _ -> "system"
              | Form_not_sent _ | Form_kept_back _ | Form_invalid_account _ | Form_refused _
              | Form_conflict _ | Form_unconfirmed _ -> "error")
              (match outcome with
               (* The kept-back notice leads, alone; the workspace follows. *)
               | Form_kept_back _ ->
                   runtime_form_outcome_detail ~ko:(state.ui_language = Lang_ko) outcome ^ origin
               | Form_saved _ | Form_not_sent _ | Form_invalid_account _ | Form_refused _
               | Form_conflict _ | Form_unconfirmed _ ->
                   "Runtime configuration" ^ origin ^ " · "
                   ^ runtime_form_outcome_detail ~ko:(state.ui_language = Lang_ko) outcome);
            (match outcome, prepared with
             | Form_saved _, Some {rfp_account=Some declaration;_} ->
                 Option.iter (fun sign_in ->
                   add_event state "info"
                     (declaration.id ^ origin
                      ^ ui_text state ~ko:" 로그인: " ~en:" sign-in: "
                      ^ Masc_tui_runtime_account_form.command sign_in);
                   Option.iter (fun typed -> add_event state "info"
                     (declaration.id ^ origin
                      ^ ui_text state ~ko:" 그다음 client 안에서: " ~en:" then inside client: "
                      ^ typed))
                     (Masc_tui_runtime_account_form.then_type sign_in)) declaration.sign_in
             | (Form_saved _ | Form_not_sent _ | Form_kept_back _ | Form_invalid_account _ | Form_refused _
                 | Form_conflict _ | Form_unconfirmed _), (None | Some _) -> ())
      end;
      Drawn_changed
  | Keeper_msg (Keeper_creation_changed (request, status)) ->
      if apply_keeper_creation_status state request status then begin
        let phase = match status with
          | Creation_checking -> "checking"
          | Creation_posting -> "posting"
          | Creation_finished Creation_created -> "created"
          | Creation_finished (Creation_not_sent _) -> "not_sent"
          | Creation_finished (Creation_kept_back _) -> "kept_back"
          | Creation_finished (Creation_refused _) -> "refused"
          | Creation_finished (Creation_unconfirmed _) -> "unconfirmed" in
        Log.Transport.info
          "tui_keeper_creation keeper=%s started_ns=%Ld observed_ns=%Ld phase=%s current_origin=%b"
          request.kcr_keeper request.kcr_started_ns (Mtime_clock.elapsed_ns ()) phase
          (keeper_creation_origin_current state request);
        match status with
        | Creation_checking -> ()
        | Creation_posting ->
            if keeper_creation_origin_current state request
               && Option.exists (fun owner -> owner == request.kcr_token) state.keeper_creation_focus then
              report_action state "system" (request.kcr_keeper ^ ": creation request in progress; awaiting confirmation")
        | Creation_finished outcome ->
          let focus = take_keeper_creation_focus state request in
          let current = keeper_creation_origin_current state request in
          let prefix = if current then request.kcr_keeper ^ ": "
            else request.kcr_keeper ^ " ("
              ^ Tui_decode.Canonical_path.to_string request.kcr_workspace.sid_base_path ^ "): " in
          (match outcome with
           | Creation_created ->
               let cleared = clear_created_keeper_draft state request in
               if current then begin
                 Masc_tui_transport.Local_sources.launch_keeper_read state ~mailbox ~intent:Snapshot_read.Refresh base_path;
                 wait_for_created_keeper_metadata state request.kcr_keeper;
                 if focus && cleared && not (input_pending ()) then begin
                   withdraw_resource_diagram_pending state;
                   retire_remote_image_for_navigation state;
                   Masc_tui_chat_input.Message_draft_recall.open_message_for_keeper ~return_to:request.kcr_return state
                     request.kcr_keeper ~drain_queue:(fun () -> ());
                   set_msg_scroll state 0;
                   state.view <- Keepers Keeper_message;
                   launch_keeper_history_load state ~mailbox ~keeper_name:request.kcr_keeper
                 end;
                 start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
                   ~intent:Revalidate ~refresh_inflight:http_refresh_inflight
                   ~scoped_refresh_inflight:http_scoped_refresh_inflight
                   ~scoped_refresh_followup ~mailbox
               end;
               report_action state "system" (prefix ^ (if current
                 then "creation confirmed; refreshing Keeper availability"
                 else "creation confirmed in its original workspace"))
           | Creation_not_sent detail ->
               report_action state "error" (prefix ^ "creation not sent; declaration retained: " ^ detail)
           (* The notice leads, then the Keeper and, outside its workspace,
              where the declaration was written for. *)
           | Creation_kept_back refusal ->
               let ko = state.ui_language = Lang_ko in
               report_action state "error"
                 (kept_back ~ko ~request:Kept_request.Keeper_creation
                    (workspace_refusal_reason ~ko refusal) Draft_kept
                  ^ " · " ^ request.kcr_keeper
                  ^ (if current then ""
                     else " (" ^ Tui_decode.Canonical_path.to_string request.kcr_workspace.sid_base_path ^ ")"))
           | Creation_refused detail ->
               report_action state "error" (prefix ^ "creation refused; declaration retained: " ^ detail)
           | Creation_unconfirmed detail ->
               report_action state "error"
                 (prefix ^ "creation outcome unconfirmed; declaration retained. Inspect the original roster before retrying: " ^ detail))
      end;
      Drawn_changed
  | Keeper_msg (Keeper_action_done (origin, keeper_name, action, result)) ->
      let origin_matches =
        Option.for_all
          (fun expected ->
            Masc_tui_types.server_workspace_matches ~expected:(Some expected)
              (match state.server_identity with
               | Some current -> Ok current
               | None -> Error "workspace unread"))
          origin
      in
      if origin_matches then begin
      Masc_tui_operator_actions.Keeper_actions.apply_keeper_action_result state ~base_path ~mailbox keeper_name action result;
      (* A paused or shut-down Keeper still routes its channels to itself, and
         answers on them the moment it runs again. Read the bindings fresh
         and, if it holds any, offer to remove them; doing nothing is the
         default. *)
      (match action, result with
       | (Keeper_control.Pause | Keeper_control.Shutdown),
         Ok (Keeper_control.Accepted _) ->
           (match origin with
            | None -> ()
            | Some origin ->
                (* Unread identity retains intent only; the loader still
                   requires ready authority before issuing the lookup. *)
                let current_workspace = match state.server_identity with
                  | None -> true
                  | Some current when Tui_decode.Canonical_path.is_empty current.sid_base_path
                                      || Tui_decode.Canonical_path.is_empty current.sid_masc_root -> true
                  | Some current -> Masc_tui_transport.Workspace_admission.same_server_workspace origin current in
                let pending_workspace = match state.connector_unbind_offer_origin with
                  | None -> true
                  | Some pending -> Masc_tui_transport.Workspace_admission.same_server_workspace origin pending in
                if current_workspace && pending_workspace then begin
                  state.connector_unbind_offer_origin <- Some origin;
                  if not (List.mem keeper_name state.connector_unbind_offer_pending) then
                    state.connector_unbind_offer_pending <-
                      keeper_name :: state.connector_unbind_offer_pending;
                  Masc_tui_surface_requests.Connector_volume_requests.launch_connectors_load state ~mailbox
                end)
       | (Keeper_control.Pause | Keeper_control.Shutdown),
         (Ok
            ( Keeper_control.Purge_accepted _
            | Keeper_control.Committed_followup_failed _
            | Keeper_control.Paused_owner_conflict _
            | Keeper_control.Rejected _
            | Keeper_control.Unbound_purge_receipt _ )
         | Error _) ->
           ()
       | (Keeper_control.Resume | Keeper_control.Boot),
         Ok (Keeper_control.Accepted _) ->
           Masc_tui_types.acknowledge_keeper_surface_resume state keeper_name
       | (Keeper_control.Resume | Keeper_control.Boot),
         (Ok
            ( Keeper_control.Purge_accepted _
            | Keeper_control.Committed_followup_failed _
            | Keeper_control.Paused_owner_conflict _
            | Keeper_control.Rejected _
            | Keeper_control.Unbound_purge_receipt _ )
         | Error _)
       | (Keeper_control.Wakeup | Keeper_control.Delete), _ ->
           ());
      (* The roster is the half of the row this refresh cannot read from disk,
         and it is what decides which action the row offers next. Asking for it
         now means the row stops offering the action that just ran without
         waiting out the refresh interval. *)
      start_http_refresh ~server_contact state ~host:(Masc_tui_transport.Workspace_admission.server_peer_host)
        ~port:state.port ~intent:Revalidate
        ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight
        ~scoped_refresh_followup ~mailbox
      end;
      Drawn_changed
  | Board_msg (Board_publication_done outcome) ->
      Masc_tui_board_updates.apply_publication state
        ~report:(report_action state)
        ~refresh:(fun () ->
          start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
            ~port:state.port ~intent:Revalidate
            ~refresh_inflight:http_refresh_inflight
            ~scoped_refresh_inflight:http_scoped_refresh_inflight
            ~scoped_refresh_followup ~mailbox)
        outcome;
      Drawn_changed
  | Board_msg (Board_comment_done { request_id; post_id; sent_draft; result }) ->
      Masc_tui_board_updates.comment_done state ~request_id ~post_id ~sent_draft
        ~report:(report_action state)
        ~refresh:(fun () ->
          start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
            ~port:state.port ~intent:Revalidate
            ~refresh_inflight:http_refresh_inflight
            ~scoped_refresh_inflight:http_scoped_refresh_inflight
            ~scoped_refresh_followup ~mailbox)
        ~refresh_detail:(fun post_id -> owe_board_post_read state ~mailbox ~post_id) result;
      Drawn_changed
  | Board_msg (Board_vote_done (target, result)) ->
      Masc_tui_board_updates.vote_done state ~report:(report_action state)
        ~refresh:(fun () ->
          start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
            ~port:state.port ~intent:Revalidate
            ~refresh_inflight:http_refresh_inflight
            ~scoped_refresh_inflight:http_scoped_refresh_inflight
            ~scoped_refresh_followup ~mailbox)
        ~refresh_detail:(fun post_id -> owe_board_post_read state ~mailbox ~post_id)
        target result;
      Drawn_changed
  | Goal_msg (Goal_transition_done (goal_id, ticket, workspace, result)) ->
      record_goal_action_receipt state ~goal_id ~ticket ~workspace result;
      let current = note_goal_action_result state ~goal_id ~ticket result in
      let label = "Goal " ^ goal_id ^ (if current then "" else " (earlier request)") ^ ": " in
      (match result with
       | Ok message ->
           report_action state "system" (label ^ message);
           (* Even a superseded response may have changed the workspace. *)
           start_http_refresh ~server_contact state ~host:(Masc_tui_transport.Workspace_admission.server_peer_host)
             ~port:state.port ~intent:Revalidate
             ~refresh_inflight:http_refresh_inflight
             ~scoped_refresh_inflight:http_scoped_refresh_inflight
             ~scoped_refresh_followup ~mailbox
       | Error (Request_failed err) ->
           report_action state "error" (label ^ err)
       | Error (Request_withdrawn refusal) ->
           report_action state "error"
             (Masc_tui_work_actions.Goal_actions.goal_kept_back_notice state ~goal_id ~current refusal));
      Drawn_changed
  | Goal_msg (Goal_confirmation_submitted (goal_id, ticket, workspace, authority, result)) ->
      record_goal_action_receipt ~authority state ~goal_id ~ticket ~workspace result;
      (match state.goal_confirmation with
       | Goal_confirmation.Submitting (submitted_goal, read) when String.equal submitted_goal goal_id ->
           state.goal_confirmation <- Goal_confirmation.Inspecting read
       | Goal_confirmation.Submitting _ | Goal_confirmation.Inspecting _ -> ());
      let owned = Masc_tui_http.credential_owner_is_current authority.ra_credential_owner
        && Option.exists (fun identity -> identity.Tui_decode.sid_runtime_instance_id = Some authority.ra_runtime_instance_id) state.server_identity in
      let status = match result with
        | Error (Request_withdrawn _) ->
          (* Kept back before it left: nothing is in the request history to
             point at, and the receipt's authority does not bear on it. *)
          result
        | Ok _ | Error (Request_failed _) ->
          if owned then Result.map_error (fun _ -> Request_failed "Confirmation result is in the request history") result
          else Error (Request_failed "Confirmation outcome belongs to an earlier server or credential; inspect request history") in
      let current = note_goal_action_result state ~goal_id ~ticket status in
      let label = "Goal " ^ goal_id ^ (if current then "" else " (earlier request)") ^ ": " in
      (match owned, result with
       | _, Error (Request_withdrawn refusal) ->
           report_action state "error" (Masc_tui_work_actions.Goal_actions.goal_kept_back_notice state ~goal_id ~current refusal)
       | false, _ ->
           report_action state "system" (label ^ "confirmation result belongs to an earlier server or credential; inspect the original workspace")
       | true, Ok _ ->
           report_action state "system" (label ^ "confirmation response received; inspect the current proof and request history");
           start_http_refresh ~server_contact state ~host:(Masc_tui_transport.Workspace_admission.server_peer_host)
             ~port:state.port ~intent:Revalidate
             ~refresh_inflight:http_refresh_inflight
             ~scoped_refresh_inflight:http_scoped_refresh_inflight
             ~scoped_refresh_followup ~mailbox
       | true, Error (Request_failed _) ->
           report_action state "error" (label ^ "confirmation outcome unconfirmed; inspect the current proof and request history"));
      (match selected_planning_goal_id state with
       | Some selected when String.equal selected goal_id ->
           state.goal_confirmation_identity_refresh <- Some (goal_id, authority.ra_workspace);
           resume_goal_confirmation_identity_refresh state ~mailbox
       | Some _ | None -> ());
      Drawn_changed
  | Goal_msg (Goal_confirmation_loaded (request, result)) ->
      (match state.goal_confirmation with
       | Goal_confirmation.Inspecting read ->
           let current = Goal_confirmation_read.is_current ~equal:String.equal read request in
           let goal_id = Goal_confirmation_read.request_key request in
           if current then begin
             (match state.planning_mode with
              | Planning_detail selected when String.equal goal_id selected ->
                  (match state.planning_scroll with
                   | Planning_scroll_offset _ -> state.planning_scroll <- Planning_scroll_offset 0
                   | Planning_scroll_candle _ -> ())
              | Planning_detail _ | Planning_list -> ());
             state.goal_confirmation_presented <- None
           end;
           let changed_owner = match result with
             | Error (Goal_confirmation.Server_changed owner)
               when current && Masc_tui_http.credential_owner_is_current owner -> Some owner
             | Ok _ | Error (Goal_confirmation.Read_failed _ | Goal_confirmation.Read_http_error _ | Goal_confirmation.Server_changed _
                            | Goal_confirmation.Read_kept_back _) -> None in
           let credential_changed = match result with
             | Ok confirmation -> not (Masc_tui_http.credential_owner_is_current confirmation.credential_owner)
             | Error (Goal_confirmation.Read_failed (Some owner, _) | Goal_confirmation.Read_http_error (owner, _) | Goal_confirmation.Server_changed owner) ->
                 not (Masc_tui_http.credential_owner_is_current owner)
             | Error (Goal_confirmation.Read_failed (None, _) | Goal_confirmation.Read_kept_back _) -> false in
           let result = match result with
             | Ok confirmation when not (Masc_tui_http.credential_owner_is_current confirmation.credential_owner) ->
                 Error (Goal_confirmation.Read_failed (Some confirmation.credential_owner, "Goal confirmation credential changed; read the proof again"))
             | Ok confirmation when not (Option.exists (fun identity ->
                 identity.Tui_decode.sid_runtime_instance_id = Some confirmation.runtime_instance_id) state.server_identity) ->
                 Error (Goal_confirmation.Read_failed (Some confirmation.credential_owner, "Goal confirmation server changed; read the proof again"))
             | Ok confirmation -> Ok confirmation
             | Error failure -> Error failure in
           (match result with Ok _ when current -> clear_goal_confirmation_revalidation state ~goal_id | Ok _ | Error _ -> ());
           state.goal_confirmation <- Goal_confirmation.Inspecting
             (Goal_confirmation_read.complete ~equal:String.equal read request result);
           (match changed_owner, selected_planning_goal_id state with
            | Some owner, Some selected when String.equal goal_id selected
                && take_goal_confirmation_revalidation state ~goal_id ~owner ->
              start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port ~intent:Revalidate
                ~refresh_inflight:http_refresh_inflight ~scoped_refresh_inflight:http_scoped_refresh_inflight
                ~scoped_refresh_followup ~mailbox
            | (Some _ | None), (Some _ | None) -> ());
           (match credential_changed, current, selected_planning_goal_id state with
            | true, true, Some selected when String.equal goal_id selected ->
                Masc_tui_work_actions.Goal_actions.launch_goal_confirmation_read state ~mailbox ~goal_id
            | _, _, (Some _ | None) -> ())
       | Goal_confirmation.Submitting _ -> ());
      Drawn_changed
  | Verification_msg (Verification_evidence_exported (request, result)) ->
      let progress = Atomic.get request.vex_progress in
      let location = match progress with
        | Masc_tui_evidence_file.Not_started -> ""
        | Writing path ->
            ui_text state ~ko:" · 저장 시도 경로(완료 미확인): " ~en:" · write attempted (unconfirmed): " ^ path
        | Saved path ->
            ui_text state ~ko:" · 저장한 사본: " ~en:" · saved copy: " ^ path
        | Aborted path ->
            ui_text state ~ko:" · 저장하지 못한 목적지: " ~en:" · unsaved destination: " ^ path in
      if request.vex_authority = state.workspace_authority
         && request.vex_reading == state.workspace_read_authority then
        (match progress with
         | Masc_tui_evidence_file.Not_started -> ()
         | Writing _ | Saved _ | Aborted _ -> state.verification_evidence_saved <-
             (request.vex_key, request.vex_index, progress) :: state.verification_evidence_saved);
      (match result with
       | Error (Request_failed detail) -> report_action state "error" ("Evidence: " ^ detail ^ location)
       | Error (Request_withdrawn refusal) ->
           report_action state "error"
             (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Evidence_export refusal)
       | Ok path ->
           report_action state "system"
             (ui_text state ~ko:"증거 사본 저장: " ~en:"Saved evidence copy: " ^ path));
      Drawn_changed
  | Verification_msg (Verification_evidence_loaded (request, result)) ->
      let key = Masc_tui_fetched.request_key request.ver_ticket in
      let admitted = state.verification_detail_request_id = Some key.vek_request_id
        && complete_verification_evidence_read state request result in
      Masc_tui_work_actions.Verification_actions.log_verification_evidence_read request
        ~phase:(if admitted then "applied" else "discarded") ~outcome:(Masc_tui_work_actions.Verification_actions.verification_evidence_outcome result);
      Drawn_changed
  | Task_msg (Task_cancel_done (task_id, expected_workspace, result)) ->
      let refresh certainty =
        remember_task_followup state ~expected_workspace (Task_cancel_refresh { task_id; certainty });
        resume_task_followups ~server_contact state ~mailbox ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup
      in
      (match result with
       | Task_cancel_confirmed _ ->
           report_action state "system" (Printf.sprintf "task %s cancelled" task_id);
           refresh Cancellation_confirmed
       | Task_cancel_refused err -> report_action state "error" ("task cancel refused: " ^ err)
       | Task_cancel_kept_back refusal ->
           Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Task_cancel refusal
       | Task_cancel_unconfirmed detail ->
           report_action state "error"
             (Printf.sprintf "task %s cancellation unconfirmed; checking its workspace: %s"
                task_id detail);
           refresh Cancellation_unconfirmed);
      Drawn_changed
  | Goal_msg (Goal_timeline_loaded (request, result)) ->
      complete_goal_timeline_read state request result;
      Drawn_changed
  | Goal_msg (Goal_candle_loaded (request, result)) ->
      let current = Masc_tui_fetched.is_current ~equal:String.equal state.goal_candle request in
      let goal_id = Masc_tui_fetched.request_key request in
      let server_changed = match result with
        | Ok (owner, Error (Goal_candle_authority_changed _))
          when current && Masc_tui_http.credential_owner_is_current owner -> Some owner
        | Ok (_, (Ok _ | Error (Goal_candle_access_denied _ | Goal_candle_authority_changed _ | Goal_candle_http_status _ | Goal_candle_read_failed _)))
        | Error _ -> None in
      let accepted = current && (match result with
        | Ok (owner, Ok (instance, _)) when Masc_tui_http.credential_owner_is_current owner ->
          Option.exists (fun identity -> identity.Tui_decode.sid_runtime_instance_id = Some instance) state.server_identity
        | Ok (_, (Ok _ | Error _)) | Error _ -> false) in
      complete_goal_candle_read state ~credential_is_current:Masc_tui_http.credential_owner_is_current request result;
      if accepted then clear_goal_candle_revalidation state ~goal_id;
      (match server_changed with
       | Some owner when take_goal_candle_revalidation state ~goal_id ~owner ->
         start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port ~intent:Revalidate
           ~refresh_inflight:http_refresh_inflight ~scoped_refresh_inflight:http_scoped_refresh_inflight
           ~scoped_refresh_followup ~mailbox
       | Some _ | None -> ());
      Drawn_changed
  | Task_msg (Task_history_loaded (request, result)) ->
      let task_id=Masc_tui_fetched.request_key request.thr_ticket in
      let followup =
        if task_history_request_in_scope state request
        then task_history_followup state request result else None in
      complete_task_history_read state request result;
      Option.iter (fun limit -> Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size ~older:true ~limit state ~mailbox task_id) followup;
      Drawn_changed
  | Board_msg (Board_attachment_loaded (request,result)) ->
      if Option.is_some (current_board_reader state) then
        state.board_reader <- Masc_tui_board_reader.complete state.board_reader request
          (Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.Attachment_read result);
      Drawn_changed
  | Board_msg (Board_attachment_prepared (request,result)) ->
      if Option.is_some (current_board_reader state) then
        state.board_reader <- Masc_tui_board_reader.complete_preparation state.board_reader request result;
      Drawn_changed
  | Board_msg (Board_attachment_saved (request,result)) ->
      (* The original workspace operation envelope admits this receipt.
         Closing or retiring its read view cannot revoke a completed save. *)
      (match result with
       | Ok (Board_saved_original text) -> report_action state "system" text
       | Ok (Board_image_open_failed (attempt,error)) ->
           if Masc_tui_board_reader.owns_original_open state.board_reader request attempt then begin
             state.board_reader <- Masc_tui_board_reader.finish_original_open state.board_reader request attempt;
             report_action state "error" error
           end
       | Ok (Board_image_open_finished (attempt,text)) ->
           state.board_reader <- Masc_tui_board_reader.finish_original_open state.board_reader request attempt;
           report_action state "system" text
       | Ok ((Board_image_open_ready _ | Board_image_open_retry _) as opening) ->
           let target = match opening with
             | Board_image_open_ready (attempt,prepared) -> Some (attempt,prepared,None)
             | Board_image_open_retry {attempt;prepared;opener} -> Some (attempt,prepared,Some opener)
             | Board_image_open_failed _ | Board_image_open_finished _ | Board_saved_original _ -> None in
           Option.iter (fun (attempt,prepared,after) ->
           let finish () =
             state.board_reader <- Masc_tui_board_reader.finish_original_open state.board_reader request attempt in
           if Option.is_some (current_board_reader state)
              && Masc_tui_board_reader.owns_original_open state.board_reader request attempt
              && Option.exists (fun (_,_,kind) -> kind = Ak_image) state.board_reader_owner then
             (match Masc_tui_attachment_action.external_file prepared, Eio_context.get_switch_opt () with
              | Some (name,path), Some sw ->
                  if not (Masc_tui_board_preview_work.try_acquire board_image_open_worker) then begin
                    finish ();
                    report_action state "system" "An image opener is already running"
                  end else (match Masc_tui_browser.spawn_url ?after path with
                   | Error _ ->
                       Masc_tui_board_preview_work.release board_image_open_worker;
                       finish ();
                       report_action state "system" (Printf.sprintf "saved %s · %s" name path)
                   | Ok (opener,pid) ->
                       let deliver=Masc_tui_transport.Workspace_admission.workspace_enqueue state in
                       let kill_and_reap () =
                         (try Unix.kill pid Sys.sigkill with Unix.Unix_error _ -> ());
                         let rec reap () = match Unix.waitpid [] pid with
                           | _ -> ()
                           | exception Unix.Unix_error (Unix.EINTR,_,_) -> reap ()
                           | exception Unix.Unix_error (Unix.ECHILD,_,_) -> () in
                         reap () in
                       let completed,resolve=Eio.Promise.create () in
                       let cancelled=Atomic.make false in
                       (match Thread.create (fun () ->
                          let status=Fun.protect ~finally:(fun () ->
                            Masc_tui_board_preview_work.release board_image_open_worker) (fun () ->
                            try Ok (Masc_tui_image_cache.wait_bounded
                              ~cancelled:(fun () -> Atomic.get cancelled)
                              ~deadline_seconds:Masc_tui_work_actions.Verification_actions.image_process_deadline_seconds pid)
                            with exn ->
                              (try kill_and_reap () with _ -> ());
                              Error (Printexc.to_string exn)) in
                          Eio.Promise.resolve resolve status) () with
                        | exception exn ->
                            (try kill_and_reap () with _ -> ());
                            Masc_tui_board_preview_work.release board_image_open_worker;
                            finish ();
                            report_action state "error" (Printexc.to_string exn)
                        | thread ->
                            board_image_open_reaper := Some (cancelled,thread);
                            (match Eio.Fiber.fork_daemon ~sw (fun () ->
                               let status=Eio.Promise.await completed in
                               let outcome=match status with
                                 | Ok (Masc_tui_image_cache.Exited (Unix.WEXITED 0)) ->
                                     Some (Board_image_open_finished (attempt,"opened " ^ name))
                                 | Ok (Exited (Unix.WEXITED _ | Unix.WSIGNALED _ | Unix.WSTOPPED _)
                                       | Killed_at_deadline) | Error _ ->
                                     Some (Board_image_open_retry {attempt;prepared;opener})
                                 (* Only the exit hook cancels an opener. The
                                    process is ending, so no next opener starts. *)
                                 | Ok Cancelled -> None in
                               Option.iter (fun outcome ->
                                 deliver mailbox (Board_msg (Board_attachment_saved (request,Ok outcome))))
                                 outcome;
                               `Stop_daemon) with
                             | () -> ()
                             | exception Eio.Cancel.Cancelled _ -> finish ()
                             | exception exn ->
                                 finish ();
                                 report_action state "error" (Printexc.to_string exn))))
              | Some (name,path), None ->
                  finish ();
                  report_action state "system" (Printf.sprintf "saved %s · %s" name path)
              | None, (Some _ | None) ->
                  finish ();
                  let outcome=Masc_tui_attachment_action.perform
                    ~open_url:(fun _ -> Error "external opening is unavailable") prepared ~midi_soundfont:None in
                  report_action state "system" (Masc_tui_attachment_action.describe_outcome outcome))
           else finish ()) target
       | Error error -> report_action state "error" error);
      Drawn_changed
  | Chat_msg (Chat_call_loaded (request, result)) ->
      ignore (complete_chat_call_read state request result);
      Drawn_changed
  | Keeper_msg (Keeper_calls_loaded (generation, keeper_name, result)) -> (
      let still_current =
        generation = state.keeper_calls_generation
        && Option.equal String.equal state.keeper_calls_keeper
             (Some keeper_name)
      in
      if still_current then begin
        let refresh_pending = state.keeper_calls_refresh_pending in
        state.keeper_calls_loading <- false;
        state.keeper_calls_refresh_pending <- false;
        let failed =
          Masc_tui_owed_read.failed ~retry_s:Masc_tui_transport.Event_streams.stream_reconnect_s
            ~max_retry_s:keeper_execute_stream_max_reconnect_s ~now:(Masc_tui_wake.Mono.now ())
        in
        (match result with
         | Ok snapshot when String.equal snapshot.kcs_keeper keeper_name ->
             state.keeper_calls <- Some snapshot;
             state.keeper_calls_error <- None;
             settle_calls_owed state ~keeper_name Masc_tui_owed_read.succeeded
         | Ok snapshot ->
             state.keeper_calls_error <-
               Some
                 (Request_failed (Printf.sprintf
                    "tool-call response named keeper %s, expected %s"
                    snapshot.kcs_keeper keeper_name));
             settle_calls_owed state ~keeper_name failed
         | Error failure ->
             state.keeper_calls_error <- Some failure;
             settle_calls_owed state ~keeper_name failed);
        let still_visible =
          match state.view with
          | Keepers Keeper_message ->
              state.msg_tool_visibility <> Tools_compact
              && Option.equal String.equal state.msg_target_keeper_name
                   (Some keeper_name)
          | Keepers Keeper_calls ->
              Option.exists
                (fun (keeper : keeper) -> String.equal keeper.k_name keeper_name)
                (selected_keeper state)
          | Keepers (Keeper_list | (Keeper_detail | (Keeper_logs | Keeper_runtime_pick))) | Overview
          | Acting | Metrics | Memory | Lanes | Clients | Board | Approvals | Planning | Schedules
          | Verification | Harness | Fusion | Repositories | Code | Changes | Connectors | Runtime
          | Config | Resources | Tools | System_logs -> false
        in
        if refresh_pending && still_visible then
          Masc_tui_work_requests.Schedule_call_requests.launch_keeper_calls_load ~force:true state ~mailbox keeper_name;
        launch_owed_keeper_calls state ~mailbox
      end);
      Drawn_changed
  | Keeper_msg (Keeper_settings_editor_loaded (request, result)) ->
      if Masc_tui_types.take_keeper_settings_editor_read state request result then begin
        Masc_tui_surface_requests.Keeper_surface_requests.log_keeper_settings_read ~phase:"admitted" request
          ~outcome:(match result with Ok _ -> "ready" | Error _ -> "failed");
        match result with
        | Ok _ -> ()
        | Error (Request_failed detail) -> report_action state "error" detail
        | Error (Request_withdrawn refusal) ->
            Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Keeper_settings_read refusal
      end;
      Drawn_changed
  | Keeper_msg (Keeper_config_view_loaded (request, result)) -> (
      let keeper_name = request.drr_keeper in
      let current = Masc_tui_types.finish_detail_read state request in
      let still_selected =
        match List.nth_opt state.keepers state.keeper_cursor with
        | Some keeper -> String.equal keeper.k_name keeper_name
        | None -> false
      in
      if current && still_selected && server_authority_ready state then
        match result with
        | Ok lines ->
            state.keeper_config_view <- Some (keeper_name, lines);
            state.keeper_config_view_error <- None
        | Error detail ->
            state.keeper_config_view_error <- Some detail);
      Drawn_changed
  | Keeper_msg (Keeper_items_loaded (request, result)) -> (
      let current = Masc_tui_types.finish_detail_read state request in
      let still_selected =
        match selected_keeper state with
        | Some keeper -> String.equal keeper.k_name request.drr_keeper
        | None -> false
      in
      if current && still_selected
         && state.workspace_identity = Masc_tui_types.Workspace_identity_match
         && server_authority_ready state
         && Keeper_control.roster_view state.keeper_roster <> Keeper_control.Roster_unobserved
         (* The same reading the dispatch guard makes: a partial roster's
            silence is not absence, so a read this TUI legitimately launched
            for an Unobserved Keeper is accepted here too. A complete
            roster's Absent and this Keeper's own decode failure still
            refuse their answers. *)
         && (match Keeper_control.liveness_of_roster state.keeper_roster request.drr_keeper with
             | Present _ | Unobserved -> true
             | Invalid _ | Absent -> false) then
        match result with
        | Ok account ->
            let selected = selected_browser_item state in
            state.item_account <- Some (request.drr_keeper, account);
            state.item_account_error <- None;
            retain_item_browser_selection state selected
        | Error detail ->
            state.item_account <- None;
            state.item_account_error <- Some detail);
      Drawn_changed
  | Keeper_msg (Keeper_sandbox_view_loaded (request, result)) -> (
      let selected_keeper = List.nth_opt state.keepers state.keeper_cursor
        |> Option.map (fun (keeper : keeper) -> keeper.k_name) in
      Masc_tui_types.apply_keeper_sandbox_result state ~selected_keeper
        ~authority_ready:(server_authority_ready state) request result);
      Drawn_changed
  | Keeper_msg (Keeper_sandbox_logs_loaded (keeper_name, generation, result)) -> (
      let is_current =
        match state.keeper_sandbox_logs_inflight with
        | Some request ->
            String.equal request.slr_keeper keeper_name
            && request.slr_generation = generation
        | None -> false
      in
      if is_current && server_authority_ready state then begin
        state.keeper_sandbox_logs_inflight <- None;
        match result with
        | Ok logs ->
          state.keeper_sandbox_logs <- Some (keeper_name, logs);
          state.keeper_sandbox_logs_error <- None
        | Error detail ->
          state.keeper_sandbox_logs_error <- Some (keeper_name, detail)
      end);
      Drawn_changed
  | Prompts_loaded (request, result) ->
      state.prompts <-
        Masc_tui_fetched.complete ~equal:Unit.equal state.prompts request result;
      state.prompts_cursor <-
        max 0 (min state.prompts_cursor (Masc_tui_surface_requests.Prompt_preset_requests.prompt_catalog_count_for_state state - 1));
      Drawn_changed
  | Preset_msg (Presets_listed (sink, result)) ->
      (match sink, result with
       | Preset_to_chat target, Ok snapshot ->
           Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             (String.concat "\n"
                (Masc_tui_preset_text.listing_lines ~ko:(state.ui_language = Lang_ko) snapshot))
       | Preset_to_chat target, Error failure ->
           Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (request_failure_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Preset_list_read failure)
       | Preset_to_pane, Ok snapshot ->
           let selected_name = Masc_tui_surface_requests.Prompt_preset_requests.selected_preset_for_state state
               |> Option.map (fun row -> row.Tui_decode.pm_name) in
           let cursor = match Option.bind selected_name (fun name ->
               List.find_mapi (fun index row ->
                 if String.equal row.Tui_decode.pm_name name then Some index else None)
                 snapshot.Tui_decode.pss_presets) with
             | Some index -> index
             | None -> max 0 (min state.presets_cursor
                 (List.length snapshot.Tui_decode.pss_presets - 1))
           in
           let next_name = List.nth_opt snapshot.Tui_decode.pss_presets cursor
               |> Option.map (fun row -> row.Tui_decode.pm_name) in
           if not (Option.equal String.equal selected_name next_name) then begin
             match state.preset_armed with
             | Some (Save_armed _ | Save_workspace_armed _) -> ()
             | Some (Restore_armed _ | Delete_armed _) | None ->
               if state.view = Config && state.config_pane = Config_presets then
                 state.config_scroll <- 0;
               state.preset_armed <- None
           end;
           state.presets_snapshot <- Some snapshot;
           state.presets_error <- None;
           state.presets_cursor <- cursor;
           (* Ask again while retaining the keyed reading. Clearing it first
              shortens the document to its loading rows and clamps a reader
              at its end to a different place before the answer arrives. *)
           Masc_tui_surface_requests.Prompt_preset_requests.ensure_preset_detail state ~mailbox
       | Preset_to_pane, Error failure -> state.presets_error <- Some failure);
      Drawn_changed
  | Preset_msg (Preset_contents_shown (sink, result)) ->
      (match sink, result with
       | Preset_to_chat target, Ok detail ->
           Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             (String.concat "\n" (Masc_tui_preset_text.contents_lines
                ~ko:(state.ui_language = Lang_ko) detail))
       | Preset_to_chat target, Error failure ->
           Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (request_failure_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Preset_read failure)
       (* The pane reads its own detail through [Preset_detail_loaded], keyed
          by the cursor, so a pane sink here would be a second answer to a
          question nobody asked. *)
       | Preset_to_pane, Ok _ -> ()
       | Preset_to_pane, Error failure -> state.presets_error <- Some failure);
      Drawn_changed
  | Preset_msg (Preset_detail_loaded (request, result)) ->
      (* Dropping an answer the cursor has moved past is [complete]'s job
         now, so this arm no longer has to remember to do it. *)
      state.preset_detail <-
        Masc_tui_fetched.complete ~equal:String.equal state.preset_detail request result;
      Drawn_changed
  | Keeper_msg (Keeper_board_quarantines_loaded (request, result)) ->
      state.keeper_board_quarantines <-
        Masc_tui_fetched.complete ~equal:String.equal
          state.keeper_board_quarantines request result;
      Drawn_changed
  | Keeper_msg (Keeper_efficiency_loaded (request, result)) ->
      state.keeper_efficiency <-
        Masc_tui_fetched.complete ~equal:String.equal state.keeper_efficiency request
          (Result.map_error (function
             | Request_failed detail -> Masc_tui_keeper_efficiency.Read_failed detail
             | Request_withdrawn refusal ->
                 Masc_tui_keeper_efficiency.Read_kept_back
                   (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                      ~request:Kept_request.Efficiency_read refusal)) result);
      Drawn_changed
  | Board_msg (Board_quarantine_requeued (keeper_name, partition_id, outcome)) ->
      state.board_quarantine_requeue_inflight <- None;
      let partition = Terminal_text.single_line partition_id in
      (match outcome with
       | Ok (Masc_tui_http.Post_answered _) ->
           report_action state "system"
             ("Board partition requeued: " ^ partition)
       | Ok (Masc_tui_http.Post_refused detail) ->
           report_action state "error"
             ("Board requeue refused for " ^ partition ^ ": "
              ^ Terminal_text.single_line detail)
       | Ok (Masc_tui_http.Post_unanswered detail) ->
           report_action state "error"
             ("Board requeue for " ^ partition
              ^ " may or may not have landed: "
              ^ Terminal_text.single_line detail)
       | Error refusal ->
           (* Not sent: the kept-back notice alone, with the partition after
              it (RFC §2). *)
           report_action state "error"
             (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Board_requeue refusal
              ^ " · " ^ partition));
      (* Read the rows again whatever the answer: a refusal usually means the
         row moved, and an unanswered press may have committed. The slot holds
         one keeper, so only while that keeper is still the one on screen --
         reading the pressed one after the operator moved on would replace the
         rows of the keeper now drawn. *)
      (match selected_keeper state with
       | Some keeper when String.equal keeper.k_name keeper_name ->
           Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_board_quarantines state ~mailbox keeper_name
       | Some _ | None -> ());
      Drawn_changed
  | Board_msg (Board_quarantines_bulk_progress
      (keeper_name, { attempted; total; accepted; refused; uncertain = unanswered; kept_back })) ->
      if state.board_quarantine_requeue_inflight <> None then
        report_action state
          (if refused > 0 || unanswered > 0 || kept_back > 0 then "error" else "system")
          (Printf.sprintf
             "Board requeue %s: %d/%d attempted · %d accepted, %d refused, %d uncertain"
             (Terminal_text.single_line keeper_name) attempted total accepted
             refused unanswered
           ^ Masc_tui_surface_requests.Keeper_surface_requests.board_requeue_kept_back_count ~ko:(state.ui_language = Lang_ko) kept_back);
      Drawn_changed
  | Board_msg (Board_quarantines_bulk_requeued (keeper_name, outcomes)) ->
      state.board_quarantine_requeue_inflight <- None;
      let ko = state.ui_language = Lang_ko in
      let accepted, refused, unanswered, kept_back =
        List.fold_left
          (fun (accepted, refused, unanswered, kept_back) (_, outcome) ->
             match outcome with
             | Ok (Masc_tui_http.Post_answered _) -> accepted + 1, refused, unanswered, kept_back
             | Ok (Masc_tui_http.Post_refused _) -> accepted, refused + 1, unanswered, kept_back
             | Ok (Masc_tui_http.Post_unanswered _) -> accepted, refused, unanswered + 1, kept_back
             | Error _ -> accepted, refused, unanswered, kept_back + 1)
          (0, 0, 0, 0)
          outcomes
      in
      let summary =
        Printf.sprintf
          "Board requeue batch: %d accepted, %d refused, %d uncertain (%d requested)"
          accepted
          refused
          unanswered
          (List.length outcomes)
        ^ Masc_tui_surface_requests.Keeper_surface_requests.board_requeue_kept_back_count ~ko kept_back
      in
      (* A row the guard stopped was not sent, so it is said as kept back, in
         its own words, and never as the first refused or uncertain row
         (RFC §2). *)
      let first_issue =
        List.find_map
          (fun (partition_id, outcome) ->
             match outcome with
             | Ok (Masc_tui_http.Post_answered _) -> None
             | Ok (Masc_tui_http.Post_refused detail) ->
               Some ("first refused: " ^ Terminal_text.single_line partition_id ^ ": "
                     ^ Terminal_text.single_line detail)
             | Ok (Masc_tui_http.Post_unanswered detail) ->
               Some ("first uncertain: " ^ Terminal_text.single_line partition_id ^ ": "
                     ^ Terminal_text.single_line detail)
             | Error refusal ->
               Some (workspace_refusal_text ~ko ~request:Kept_request.Board_requeue refusal
                     ^ " · " ^ Terminal_text.single_line partition_id))
          outcomes
      in
      let summary =
        match first_issue with
        | None -> summary
        | Some issue -> summary ^ " · " ^ issue
      in
      report_action state
        (if refused > 0 || unanswered > 0 || kept_back > 0 then "error" else "system")
        summary;
      (match selected_keeper state with
       | Some keeper when String.equal keeper.k_name keeper_name ->
           Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_board_quarantines state ~mailbox keeper_name
       | Some _ | None -> ());
      Drawn_changed
  | Preset_msg (Preset_saved (original, result)) ->
      let pending = Option.value ~default:original
          (List.find_opt (fun request -> request.psp_token == original.psp_token)
             state.preset_save_pending) in
      state.preset_save_pending <- List.filter (fun request -> request.psp_token != original.psp_token)
          state.preset_save_pending;
      let workspace = pending.psp_workspace in
      let receipt = { psr_request = pending; psr_result = result; psr_visible = true } in
      state.preset_save_receipts <- receipt :: state.preset_save_receipts;
      let current_workspace =
        workspace = workspace_input_identity_of_server state.server_identity in
      if current_workspace then state.preset_save_copy_cursor <- 0;
      if state.view = Config && state.config_pane = Config_presets
         && current_workspace then
        state.config_scroll <- 0;
      List.iter (fun (authority, target, observation) ->
          if current_workspace && authority = state.workspace_authority then
            match result with
            | Ok manifest ->
              let saved =
                Masc_tui_preset_text.saved_line ~ko:(state.ui_language = Lang_ko) manifest
              in
              Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
                ((if observation = Preset_save_shared then ui_text state
                    ~ko:"먼저 시작한 저장 결과 · 새 저장은 미전송\n"
                    ~en:"Earlier save result · no new save was sent\n" else "")
                 ^ saved)
            | Error failure ->
              let summary = match failure with
                | Preset_save_not_sent _ ->
                  ui_text state ~ko:"프리셋 저장 미전송 · 프리셋 알림 확인"
                    ~en:"Preset save not sent · check Presets"
                | Preset_save_kept_back refusal ->
                  workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                    ~request:Kept_request.Preset_save refusal
                | Preset_save_refused _ ->
                  ui_text state ~ko:"프리셋 저장 거절 · 프리셋 알림 확인"
                    ~en:"Preset save refused · check Presets"
                | Preset_save_auth_retry_not_sent _ ->
                  ui_text state ~ko:"인증 거절 · 재시도 미전송"
                    ~en:"Authentication refused · retry not sent"
                | Preset_save_unconfirmed _ ->
                  ui_text state ~ko:"프리셋 저장 미확인 · 프리셋 알림 확인"
                    ~en:"Preset save unconfirmed · check Presets"
              in
              let shared = observation = Preset_save_shared in
              Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
                ((if shared then ui_text state ~ko:"기존 저장 결과 · 새 요청 미전송 · "
                    ~en:"Earlier save · no new request sent · " else "") ^ summary);
              Option.iter (fun keeper ->
                let lines = Masc_tui_render_config.preset_save_receipt_lines
                    ~ko:(state.ui_language = Lang_ko) receipt in
                let prefix = if shared then [ui_text state
                    ~ko:"먼저 시작한 저장 결과 · 새 저장은 보내지 않았습니다"
                    ~en:"Earlier save result · no new save was sent"] else [] in
                Masc_tui_collab_queue.Chat_notice.append_chat_local_message state ~keeper (String.concat "\n" (prefix @ lines))) target)
        pending.psp_chat_observers;
        if current_workspace && Option.fold ~none:false
            ~some:(fun (authority, _) -> authority = state.workspace_authority)
            pending.psp_pane_observer then begin
          state.preset_busy <- false;
          (match result with
           | Ok manifest ->
             let shared = match pending.psp_pane_observer with
               | Some (_, Preset_save_shared) -> true
               | Some (_, Preset_save_original) | None -> false in
             report_action state "system"
               ((if shared then ui_text state ~ko:"기존 저장 결과 · "
                   ~en:"Earlier save result · " else "")
                ^ Printf.sprintf (if state.ui_language = Lang_ko then "%s 저장됨" else "%s saved")
                    manifest.Tui_decode.pm_name)
           | Error _ ->
             report_action state "error"
               (ui_text state ~ko:"프리셋 저장 알림을 확인하세요" ~en:"Check the preset save notice"));
          Masc_tui_surface_requests.Prompt_preset_requests.launch_presets_load state ~mailbox
        end;
      Drawn_changed
  | Preset_msg (Preset_restored (sink, result)) ->
      (match sink, result with
       | Preset_to_chat target, Ok report ->
           (* What was applied and what was skipped, line by line, is the
              answer to the restore even when a part failed: the lines say
              which, and a footer line could not hold them. *)
           state.preset_report <- Some report;
           Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             (String.concat "\n" (Masc_tui_preset_text.restore_lines
                ~ko:(state.ui_language = Lang_ko) report));
           if not (Masc_tui_preset_text.restore_is_clean report) then
             report_action state "error"
               (ui_text state ~ko:"프리셋 복원 결과에 확인할 항목이 있습니다 · 상세 보고서를 확인하세요"
                  ~en:"The restore needs attention · check the detailed report")
       | Preset_to_chat target, Error failure ->
           Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (request_failure_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Preset_restore failure)
       | Preset_to_pane, Ok report ->
           state.preset_busy <- false;
           state.preset_report <- Some report;
           report_action state
             (if Masc_tui_preset_text.restore_is_clean report then "system" else "error")
             (Printf.sprintf (if state.ui_language = Lang_ko then "%s 복원 결과 · 이전 상태는 %s" else "%s restore result · previous settings: %s")
                report.Tui_decode.prr_restored report.Tui_decode.prr_autosave);
           Masc_tui_surface_requests.Prompt_preset_requests.launch_presets_load state ~mailbox
       | Preset_to_pane, Error (Request_failed detail) ->
           state.preset_busy <- false;
           report_action state "error" (ui_text state ~ko:"프리셋 복원: " ~en:"Preset restore: " ^ detail)
       | Preset_to_pane, Error (Request_withdrawn refusal) ->
           state.preset_busy <- false;
           Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Preset_restore refusal);
      Drawn_changed
  | Preset_msg (Preset_deleted (sink, result)) ->
      (* The list is read again after a failure too: a refusal says the
         list was stale, and an unanswered delete may have landed. *)
      (match sink, result with
       | Preset_to_chat target, Ok name ->
           Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             ("deleted preset " ^ name)
       | Preset_to_chat target, Error failure ->
           Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (request_failure_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Preset_delete failure)
       | Preset_to_pane, Ok name ->
           state.preset_busy <- false;
           report_action state "system" (name ^ ui_text state ~ko:" 삭제됨" ~en:" deleted");
           Masc_tui_surface_requests.Prompt_preset_requests.launch_presets_load state ~mailbox
       | Preset_to_pane, Error (Request_failed detail) ->
           state.preset_busy <- false;
           report_action state "error" (ui_text state ~ko:"프리셋 삭제: " ~en:"Preset delete: " ^ detail);
           Masc_tui_surface_requests.Prompt_preset_requests.launch_presets_load state ~mailbox
       | Preset_to_pane, Error (Request_withdrawn refusal) ->
           state.preset_busy <- false;
           Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Preset_delete refusal;
           Masc_tui_surface_requests.Prompt_preset_requests.launch_presets_load state ~mailbox);
      Drawn_changed
  | Play_msg (Play_room_received (request, result)) ->
      state.play_room <- Option.map (fun room ->
        let now = Masc_tui_wake.Mono.now () in
        let ko = state.ui_language = Lang_ko in
        match result with
        | Ok (viewer, snapshot) -> Masc_tui_play_room.receive ~ko ~viewer room request ~now (Ok snapshot)
        | Error (Request_failed detail) -> Masc_tui_play_room.receive ~ko room request ~now (Error detail)
        | Error (Request_withdrawn refusal) ->
            (* A read or a message keeps the draft, as the room's own
               failure notice says; leaving has nothing to keep. *)
            let named, kept = match Masc_tui_play_room.request_kind request with
              | `Read -> Kept_request.Play_room_read, Draft_kept
              | `Say -> Kept_request.Play_room_message, Draft_kept
              | `Leave -> Kept_request.Play_room_leave, Nothing_kept in
            let ko = state.ui_language = Lang_ko in
            Masc_tui_play_room.kept_back room request ~now
              (kept_back ~ko ~request:named (workspace_refusal_reason ~ko refusal) kept)) state.play_room;
      if state.msx_open && not state.msx_menu_open then render_spectator state;
      Drawn_changed
  | Play_msg (Play_invites_listed (target, result)) ->
      (match target with
       | Play_collab_list read ->
           state.collab <- Option.map (fun view -> match result with
             | Ok listed -> Masc_tui_collab.listed view read (Ok listed)
             | Error (Request_failed detail) -> Masc_tui_collab.listed view read (Error detail)
             | Error (Request_withdrawn refusal) ->
                 Masc_tui_collab.kept_back view read
                   (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                      ~request:Kept_request.Play_invite_list_read refusal)) state.collab
       | Play_chat_list keeper ->
         let target = Play_chat keeper in
         (match result with
       | Error (Request_failed detail) ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             ("play invites: " ^ detail)
       | Error (Request_withdrawn refusal) ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Play_invite_list_read refusal)
       | Ok { Tui_decode.pis_rows = []; pis_controller } ->
           let ko = state.ui_language = Lang_ko in
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             (String.concat "\n"
                ((if ko then "공유 DOS 플레이 초대가 없습니다" else "No shared DOS play invites")
                 :: Masc_tui_collab.controller_summary ~ko pis_controller))
       | Ok { Tui_decode.pis_rows = invites; pis_controller } ->
           let ko = state.ui_language = Lang_ko in
           let row invite =
             let expires_at =
               match invite.Tui_decode.pi_expires_at with
               | Some value -> value
               | None -> if ko then "미기록" else "not recorded"
             in
             invite.pi_name
             ^ (if ko then " · 만료 " else " · expires ") ^ expires_at
             ^ (if invite.pi_expired then (if ko then " · 만료됨" else " · expired") else "")
             ^ Masc_tui_collab.controller_note ~ko pis_controller invite.pi_name
           in
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             (String.concat "\n"
                (((if ko then "공유 DOS 플레이 초대:" else "Shared DOS play invites:")
                  :: Masc_tui_collab.controller_summary ~ko pis_controller)
                 @ List.map row invites))));
      Drawn_changed
  | Play_msg (Play_invite_issued (request, target, result)) ->
      let outcome = match result with
        | Play_answered (Ok _) | Play_refused _ | Play_not_dispatched _ | Play_kept_back _ ->
            Change_confirmed
        | Play_answered (Error _) | Play_unanswered _ -> Change_unknown in
      if Masc_tui_types.finish_play_change state request outcome then begin
      Masc_tui_collab_queue.Collab_play.settle_play_mutation state target;
      (match result with
       | Play_answered (Ok invite) ->
           (* The link is a credential the server will not show again. It goes
              to the card and, on [y], the clipboard: not to the chat row,
              the footer or the session log. *)
           (match
              Masc_tui_play_card.make_for
                ~ko:(state.ui_language = Lang_ko)
                ~project:Masc_tui_play_card.project_for_terminal
                ~name:invite.Tui_decode.pii_name
                ~expires_at:invite.pii_expires_at ~link:invite.pii_link
            with
            | Ok card ->
                withdraw_resource_diagram_pending state;
                let stored = Masc_tui_types.play_invite_store state.play_invite card in
                state.play_invite <- stored;
                state.play_invite_scroll <- 0;
                Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
                  (Masc_tui_play_card.issued_notice ~ko:(state.ui_language = Lang_ko) card
                     ~retained:(Masc_tui_types.play_invite_holds_earlier stored))
            | Error reason ->
                (* The link is the server's public base URL and a hex token,
                   so a link the card refuses names the base URL. The reason is
                   the card's own sentence and carries no part of the link. *)
                Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
                  ("play invite may exist, but its link cannot be shown: " ^ reason
                   ^ "; check MASC_HTTP_BASE_URL, then list and revoke it before retrying"))
       | Play_answered (Error _) ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             ("Play invite response unreadable. " ^ Masc_tui_types.play_change_unknown_notice request)
       | Play_refused detail ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             ("play invite refused: " ^ detail)
       | Play_not_dispatched detail ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             ("play invite was not sent: " ^ detail)
       | Play_kept_back refusal ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Play_invite_issue refusal)
       | Play_unanswered detail ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (detail ^ ". " ^ Masc_tui_types.play_change_unknown_notice request));
      Masc_tui_collab_queue.Collab_play.sync_collab_access state;
      Masc_tui_collab_queue.Collab_play.refresh_current_collab state ~mailbox
      end;
      Drawn_changed
  | Play_msg (Play_invite_revoked (request, target, requested_name, result)) ->
      let outcome = match result with
        | Play_revoke_absent | Play_revoke_release_failed _
        | Play_revoke_result (Play_answered (Ok _) | Play_refused _ | Play_not_dispatched _
                              | Play_kept_back _) -> Change_confirmed
        | Play_revoke_result (Play_answered (Error _) | Play_unanswered _) -> Change_unknown in
      if Masc_tui_types.finish_play_change state request outcome then begin
      Masc_tui_collab_queue.Collab_play.settle_play_mutation state target;
      let retry reason =
        Printf.sprintf "retry /play revoke %s · %s" requested_name reason
      in
      (match result with
       | Play_revoke_absent ->
           Masc_tui_surface_requests.Prompt_preset_requests.forget_play_invite state ~name:requested_name;
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
             ("Play invite " ^ requested_name ^ " is absent (no invite has that name)")
       | Play_revoke_release_failed detail ->
           Masc_tui_surface_requests.Prompt_preset_requests.forget_play_invite state ~name:requested_name;
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (retry (detail ^ " (invite already absent; controller release failed)"))
       | Play_revoke_result (Play_answered (Ok revoked)) ->
           Masc_tui_surface_requests.Prompt_preset_requests.forget_play_invite state ~name:revoked.Tui_decode.pir_name;
           (match revoked.pir_release_error with
            | Some detail ->
                Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
                  (retry
                     (detail
                      ^ (if revoked.pir_revoked then
                           " (invite revoked; controller release failed)"
                         else
                           " (invite already absent; controller release failed)")))
            | None ->
                Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
                  (Printf.sprintf "Play invite %s: %s%s"
                     revoked.pir_name
                     (if revoked.pir_revoked then "revoked" else "already absent")
                     (if revoked.pir_released_controller then "; controller released" else "")))
       | Play_revoke_result (Play_answered (Error detail)) ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (detail ^ ". " ^ Masc_tui_types.play_change_unknown_notice request)
       | Play_revoke_result (Play_refused detail) ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             ("play revoke refused: " ^ detail)
       | Play_revoke_result (Play_not_dispatched detail) ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             ("play revoke was not sent: " ^ detail)
       | Play_revoke_result (Play_kept_back refusal) ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Play_invite_revoke refusal)
       | Play_revoke_result (Play_unanswered detail) ->
           Masc_tui_collab_queue.Collab_play.play_notice state ~sink:target ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (detail ^ ". " ^ Masc_tui_types.play_change_unknown_notice request));
      Masc_tui_collab_queue.Collab_play.sync_collab_access state;
      Masc_tui_collab_queue.Collab_play.refresh_current_collab state ~mailbox
      end;
      Drawn_changed
  | Librarian_input_loaded (prompt_key, result) ->
      if state.prompts_librarian_input_requested = Some prompt_key then
        state.prompts_librarian_input_requested <- None;
      let still_selected =
        match Masc_tui_surface_requests.Prompt_preset_requests.selected_prompt_for_state state with
        | Some row -> String.equal row.Tui_decode.pr_key prompt_key
        | None -> false
      in
      if still_selected then begin
        state.prompts_librarian_input_loading <- false;
        (match state.prompts_librarian_input with
         | Some (key, _) when String.equal key prompt_key -> ()
         | Some _ | None ->
           if state.view = Config && state.config_pane = Config_prompts
              && not state.prompts_show_runtime_assets then
             state.config_scroll <- 0);
        match result with
        | Ok lines ->
            state.prompts_librarian_input <- Some (prompt_key, lines);
            state.prompts_librarian_input_error <- None
        | Error detail ->
            state.prompts_librarian_input <- None;
            state.prompts_librarian_input_error <- Some detail
      end;
      Drawn_changed
  | Runtime_msg (Runtime_params_loaded result) -> (
      state.runtime_params_loading <- false;
      match result with
      | Ok rows ->
          let selected_key =
            Option.bind state.runtime_params (fun rows ->
              List.nth_opt rows state.runtime_params_cursor)
            |> Option.map (fun (row : Tui_decode.runtime_param_row) -> row.rpr_key)
          in
          let cursor =
            Option.bind selected_key (fun key ->
              List.find_mapi (fun index (row : Tui_decode.runtime_param_row) ->
                if String.equal row.rpr_key key then Some index else None) rows)
            |> Option.value
                 ~default:(max 0 (min state.runtime_params_cursor (List.length rows - 1)))
          in
          let next_key =
            List.nth_opt rows cursor
            |> Option.map (fun (row : Tui_decode.runtime_param_row) -> row.rpr_key)
          in
          if state.view = Config && state.config_pane = Config_params
             && not (Option.equal String.equal selected_key next_key)
          then state.config_scroll <- 0;
          state.runtime_params <- Some rows;
          state.runtime_params_cursor <- cursor;
          state.runtime_params_error <- None
      | Error failure ->
          (* Reported, not swallowed into an empty list: empty means nothing is
             registered, which is a working state. *)
          state.runtime_params_error <- Some failure);
      Drawn_changed
  | Runtime_msg (Runtime_param_written (edit, result)) ->
      state.runtime_params_loading <- false;
      (match result with
       | Error (Request_failed detail) -> state.runtime_params_notice <- Some (Params_said (false, detail))
       | Error (Request_withdrawn refusal) -> state.runtime_params_notice <- Some (Params_kept_back refusal)
       | Ok notice ->
           if state.runtime_param_edit = edit then state.runtime_param_edit <- None;
           state.runtime_params_notice <- Some (Params_said (true, notice));
           Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_params_load state ~mailbox);
      Drawn_changed
  | Machine_msg (Machine_activity_read (request,result)) ->
      Option.iter (fun session ->
        Masc_tui_types.put_machine_activity state (match result with
          | Ok reading -> Masc_tui_machine_activity.finish_read request (Ok reading) session
          | Error (Request_failed detail) ->
              Masc_tui_machine_activity.finish_read request (Error detail) session
          | Error (Request_withdrawn refusal) ->
              Masc_tui_machine_activity.withdraw_read request
                (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                   ~request:Kept_request.Machine_activity_read refusal) session))
        (Masc_tui_types.machine_activity_session state (Masc_tui_machine_activity.request_owner request));
      Drawn_changed
  | Machine_msg (Machine_activity_saved (request,result)) ->
      let module Activity = Masc_tui_machine_activity in
      let result = match result with
        | Ok result -> result
        | Error refusal ->
            Activity.Kept_back (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
              ~request:Kept_request.Machine_activity_save refusal) in
      let owner = Activity.request_owner request in
      (match Masc_tui_types.machine_activity_session state owner with
       | Some session when Activity.matches request session ->
         Masc_tui_types.put_machine_activity state (Activity.finish_save request result session);
         (match result with
          | Activity.Saved _ | Activity.Unconfirmed _ ->
            launch_machine_activity_read state ~mailbox owner;
            launch_lanes_reread state ~mailbox
          | Activity.Conflict _ | Activity.Refused _ | Activity.Kept_back _ -> ())
       | None | Some _ -> ());
      Drawn_changed
  | Exact_msg (Exact_activity_read (request,result)) ->
      Option.iter (fun session ->
        Masc_tui_types.put_exact_activity state (match result with
          | Ok document -> Masc_tui_exact_activity.finish_read request (Ok document) session
          | Error (Request_failed detail) ->
              Masc_tui_exact_activity.finish_read request (Error detail) session
          | Error (Request_withdrawn refusal) ->
              Masc_tui_exact_activity.withdraw_read request
                (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                   ~request:Kept_request.Exact_activity_read refusal) session))
        (Masc_tui_types.exact_activity_session state (Masc_tui_exact_activity.request_owner request));
      Drawn_changed
  | Exact_msg (Exact_activity_saved (request,result)) ->
      let module Activity = Masc_tui_exact_activity in
      let result = match result with
        | Ok result -> result
        | Error refusal ->
            Activity.Kept_back (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
              ~request:Kept_request.Exact_activity_save refusal) in
      let owner = Activity.request_owner request in
      (match Masc_tui_types.exact_activity_session state owner with
       | Some session when Activity.matches request session ->
         Masc_tui_types.put_exact_activity state (Activity.finish_save request result session);
         (match result with
          | Activity.Saved _ ->
            launch_exact_activity_read state ~mailbox owner;
            launch_lanes_reread state ~mailbox
          | Activity.Conflict _ | Activity.Refused _ | Activity.Unconfirmed _
          | Activity.Kept_back _ -> ())
       | None | Some _ -> ());
      Drawn_changed
  | Runtime_msg (Runtime_config_view_loaded (generation, requested_model, started_ns, ready_ns, result)) -> (
      let disposition = if generation <> state.runtime_config_generation then "superseded"
        else match state.runtime_config_read with `Loading true -> "followup" | `Loading false | `Idle -> "admitted" in
      Log.Transport.info
        "tui_runtime_config_read generation=%d started_ns=%Ld ready_ns=%Ld observed_ns=%Ld phase=%s outcome=%s"
        generation started_ns ready_ns (Mtime_clock.elapsed_ns ()) disposition
        (match result with Ok _ -> "source_loaded" | Error _ -> "read_failed");
      if generation = state.runtime_config_generation then
      let pending = match state.runtime_config_read with
        | `Loading pending -> pending
        | `Idle -> false in
      state.runtime_config_read <- `Idle;
      if pending then Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_config_load state ~mailbox else
      match result with
      | Ok (snapshot : Masc_tui_runtime_config_snapshot.t) ->
          state.runtime_config_owed <- Masc_tui_owed_read.succeeded state.runtime_config_owed;
          let reading = snapshot.reading in
          let path = reading.path in
          let metadata = reading.metadata in
          let rows = snapshot.rows in
          state.runtime_config_observed_generation <- Some generation;
          state.runtime_config_view <- Some
             { rcv_path = path; rcv_source_text = reading.source_text; rcv_rows = rows; rcv_metadata = metadata;
               rcv_account_emails = reading.account_emails };
          state.runtime_config_view_error <- None;
          (* The worker projected these models from this exact source and
             server-owned account groups; admission reads no fresh catalogue. *)
          (match snapshot.models with
           | Ok rows ->
             state.config_models_rows <- rows;
             state.config_models_cursor <- min state.config_models_cursor (max 0 (List.length rows - 1));
             state.config_models_error <- None;
             (match requested_model with
              | Some runtime_id when state.runtime_model_jump = requested_model
                    && state.view = Config && state.config_pane = Config_models ->
                (match Masc_tui_model_runtime_table.find_runtime ~runtime_id rows with
                 | Some (index, row) ->
                   state.config_models_cursor <- index;
                   state.config_scroll <- 0;
                   state.runtime_form_save_focus <- None;
                   state.runtime_model_form <- Some
                     (Masc_tui_model_form.create ~source_revision:metadata.source_revision Edit row)
                 | None ->
                   open_runtime_model_source state runtime_id;
                   report_action state "info"
                     ("Binding unavailable; edit runtime.toml for " ^ Terminal_text.single_line runtime_id))
              | Some _ | None -> ());
             state.runtime_model_jump <- None
           | Error detail ->
             state.config_models_rows <- [];
             state.config_models_error <- Some detail;
             (match requested_model with
              | Some runtime_id when state.runtime_model_jump = requested_model
                    && state.view = Config && state.config_pane = Config_models ->
                  open_runtime_model_source state runtime_id;
                  report_action state "error" ("Model settings unreadable; edit runtime.toml: " ^ detail)
              | Some _ | None -> ());
             state.runtime_model_jump <- None);
          set_runtime_config_cursor_near
            ~keep_scroll:(state.view <> Config || state.config_pane <> Config_runtime)
            state ~direction:1
            ~target:state.runtime_config_cursor;
          (match Masc_tui_types.runtime_config_edit_session state with
           | None -> ()
           | Some edit ->
             let current = { Masc_tui_runtime_config_edit.path;
               source_text = reading.source_text; source_revision = metadata.source_revision } in
             (match Masc_tui_runtime_config_edit.observe ~read_generation:generation current edit.rce_session with
              | Ok session -> Masc_tui_types.put_runtime_config_edit ~preserve_view:true ~snapshot state ~workspace:edit.rce_workspace session
              | Error _ -> ()));

          (match apply_runtime_config_jump state with
           | None -> ()
           | Some (section, true) ->
             add_event state "info"
               (Printf.sprintf "runtime.toml at [%s] - e to edit" section)
           | Some (section, false) ->
             report_action state "error"
               (Printf.sprintf "runtime.toml has no [%s] section" section))
      | Error failure ->
          state.runtime_config_owed <- failed_read state.runtime_config_owed;
          state.runtime_model_jump <- None;
          state.runtime_config_jump_section <- None;
          state.runtime_config_view_error <- Some failure);
      Drawn_changed
  | Code_msg answer -> (
      (* The save settles inside [apply]. With input queued, the reread waits
         for [Code_results.saved_refresh_path]. *)
      match Code_results.apply state answer with
      | Code_results.No_answer_followup -> ()
      | Code_results.Reload_saved_file path ->
          if not (input_pending ()) then
            Masc_tui_code_requests.launch_file_load ~intent:Refresh_code_file state
              ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state mailbox) ~path);
      Drawn_changed
  | Resource_msg (Resources_listed (owner, result)) ->
      withdraw_resource_diagram_pending state;
      Masc_tui_resources_updates.listed state ~owner
        (Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.Resource_list_read result);
      Drawn_changed
  | Artifact_msg (Artifact_checks_loaded (request, result)) ->
      (* A read the guard stopped keeps its notice apart, so the confirmation
         it leaves unknown is said as kept back, alone (RFC §2). *)
      Masc_tui_resources_updates.checks_loaded state request
        (Result.map_error (function
           | Request_failed detail -> Masc_tui_artifact_checks.Read_failed detail
           | Request_withdrawn refusal ->
               Masc_tui_artifact_checks.Read_kept_back
                 (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                    ~request:Kept_request.Report_checks_read refusal)) result);
      Drawn_changed
  | Artifact_msg (Artifact_check_changed (request, result)) ->
      if Masc_tui_resources_updates.check_changed state request then begin
        (match result with
         | Ok _ -> report_action state "system" "Confirmation saved; reading shared state"
         | Error (Request_failed detail) -> report_action state "error"
             ("Confirmation result requires refresh: " ^ detail)
         | Error (Request_withdrawn refusal) ->
             Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Report_check refusal);
        launch_artifact_checks_load state ~mailbox
      end;
      Drawn_changed
  | Resource_msg (Resource_saved (request, outcome)) ->
      if settle_resource_save state request outcome then begin
        match outcome with
        | Resource_save_kept_back refusal ->
            Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Original_save refusal
        | Resource_save_result _ | Resource_save_not_started _
        | Resource_save_unconfirmed _ | Resource_save_interrupted _ ->
        let category = match outcome with
          | Resource_save_result (Ok ()) | Resource_save_not_started _ -> "system"
          | Resource_save_result (Error _) | Resource_save_unconfirmed _
          | Resource_save_interrupted _ | Resource_save_kept_back _ -> "error" in
        report_action state category
          (resource_save_document_title request.save_document ^ " · "
           ^ resource_save_summary state (Resource_save_settled outcome)
           ^ " · " ^ request.save_path)
      end;
      Drawn_changed
  | Resource_msg (Resource_exported (label, result)) ->
      (match result with
       | Ok detail ->
           report_action state "system" detail;
           (match state.resource_content with
            | Some ((Masc_tui_resource_catalog.Report_revision current as key), _)
              when String.equal current.id label ->
                launch_resources_read state ~mailbox ~key
            | Some ((Masc_tui_resource_catalog.Report_revision _
                    | Masc_tui_resource_catalog.Mcp_uri _), _) | None -> ())
       | Error (Request_failed detail) -> report_action state "error" (label ^ ": " ^ detail)
       | Error (Request_withdrawn refusal) ->
           Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Report_open refusal);
      Drawn_changed
  | Resource_msg (Resource_share_changed (request, result)) ->
      if resource_share_is_owned state request then begin
        let read_key = finish_resource_share state request result in
        (match result with
         | Ok (Resource_share_applied shared) ->
             report_action state "system"
               ("External sharing request to " ^ (if request.share_target then "enable" else "revoke")
                ^ " applied for " ^ request.share_report.id
                ^ (if shared then "; enabled at response" else "; disabled at response"));
             Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key
         | Ok (Resource_share_conflict shared) ->
             report_action state "system"
               ("External sharing request to " ^ (if request.share_target then "enable" else "revoke")
                ^ " conflicted for " ^ request.share_report.id
                ^ (if shared then "; enabled at response" else "; disabled at response")
                ^ "; refresh before retrying");
             Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key
         | Ok (Resource_share_not_prepared detail) ->
             report_action state "system" ("The share request for " ^ request.share_report.id ^ " was not recorded or sent: " ^ detail);
             Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key
         | Ok (Resource_share_not_sent detail) ->
             report_action state "error" ("The share request for " ^ request.share_report.id ^ " did not send. The recorded operation may still apply; use U to reconcile: " ^ detail);
             Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key
         | Ok (Resource_share_kept_back refusal) ->
             report_resource_share_kept_back state request refusal;
             Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key
         | Error (Resource_share_unknown detail) ->
             report_action state "error"
               ("External sharing result unconfirmed for " ^ request.share_report.id
                ^ "; use U to reconcile the recorded operation: " ^ detail)
         | Error (Resource_share_not_started detail) ->
             report_action state "error" (if request.share_recovery then
               "The recovery attempt for " ^ request.share_report.id ^ " did not start; the original operation may still apply: " ^ detail
               else "The share request for " ^ request.share_report.id ^ " did not start or send: " ^ detail);
             Option.iter (fun key -> launch_resources_read state ~mailbox ~key) read_key)
      end;
      Drawn_changed
  | Resource_msg (Resource_share_recovery_loaded (request, result)) ->
      (match state.resource_share_recovery_lookup with
       | Some current when current.recovery_lookup_owner == request.recovery_lookup_owner ->
         state.resource_share_recovery_lookup <- None;
         let selected = match open_resource_report state with
           | Ok report -> Masc_tui_resource_catalog.equal_key (Report_revision report) request.recovery_lookup_key
           | Error _ -> false in
         if selected && state.view = Resources && state.resource_focus = Right_pane
            && state.workspace_authority = request.recovery_lookup_workspace
            && workspace_change_origin state = Ok request.recovery_lookup_origin then
           (match request.recovery_lookup_key with
            | Masc_tui_resource_catalog.Mcp_uri _ -> ()
            | Report_revision report ->
              let key = request.recovery_lookup_origin, report.id in
              let show_recovery entry ~missing_journal =
                observe_resource_share state entry;
                let collision = resource_share_identity_conflict state entry in
                if collision then begin
                  state.resource_share_recovery_prompt <- None;
                  report_action state "error" "Conflicting details were observed for this operation ID. Sharing remains blocked; verify the server receipt before recovery."
                end else begin
                  withdraw_resource_diagram_pending state;
                  state.resource_share_recovery_prompt <- Some
                    {recovery_entry=entry;recovery_workspace=state.workspace_authority;
                     recovery_key=request.recovery_lookup_key;
                     recovery_confirmation=Masc_tui_artifact_share_confirmation.create ()};
                  state.resource_scroll <- Masc_tui_scroll.Position.first;
                  state.resource_search_position <- Masc_tui_resource_reading.first;
                  let original = entry.request in
                  report_action state "system" (Printf.sprintf
                    "%s! confirms %s all revisions (share v%d, publication v%d); may apply. Operation %s; SHA-256 %s"
                    (if missing_journal then "Original record missing; confirmation will restore it. " else "")
                    (if original.requested then "ENABLE" else "REVOKE") original.expected_version
                    original.expected_artifact_revision original.operation_id original.expected_artifact_sha256)
                end in
              (match result with
               | Error detail ->
                 if not (List.mem key state.resource_share_uncertain_ids) then
                   state.resource_share_uncertain_ids <- key :: state.resource_share_uncertain_ids;
                 state.resource_share_recovery_prompt <- None;
                 report_action state "error" ("Share recovery storage is unavailable: " ^ detail)
               | Ok None ->
                 let known =
                   match known_resource_share_entries state
                           ~origin:request.recovery_lookup_origin ~artifact_id:report.id with
                   | [] -> None
                   | entry :: _ -> Some entry in
                 (match known with
                  | Some entry -> show_recovery entry ~missing_journal:true
                  | None ->
                    state.resource_share_uncertain_ids <- List.filter ((<>) key) state.resource_share_uncertain_ids;
                    state.resource_share_recovery_prompt <- None;
                    report_action state "system" "No recorded share operation; rereading the report";
                    launch_resources_read state ~mailbox ~key:request.recovery_lookup_key)
               | Ok (Some entry) ->
                 if not (List.mem key state.resource_share_uncertain_ids) then
                   state.resource_share_uncertain_ids <- key :: state.resource_share_uncertain_ids;
                 show_recovery entry ~missing_journal:false))
       | Some _ | None -> ());
      Drawn_changed
  | Resource_msg (Resource_read (request, result, journal)) ->
      withdraw_resource_diagram_pending state;
      let admitted = match state.resource_read_owner with
        | Some owner -> owner == request.Masc_tui_resource_catalog.owner
        | None -> false in
      let copy = match state.resource_copy_pending with
        | Some pending -> pending.owner == request.owner
            && Masc_tui_resource_catalog.equal_key pending.key request.key
        | None -> false in
      (match journal with
       | Share_journal_checked observation -> List.iter (observe_resource_share state) observation.journal_observed
       | Share_journal_unavailable (_, observed) -> List.iter (observe_resource_share state) observed
       | Share_journal_not_needed -> ());
      if admitted then (match request.key, journal with
        | Masc_tui_resource_catalog.Report_revision report, Share_journal_checked observation
          when workspace_input_identity_of_server state.server_identity = Some observation.journal_workspace ->
          let key = observation.journal_workspace, report.id in
          state.resource_share_uncertain_ids <- List.filter ((<>) key) state.resource_share_uncertain_ids;
          if Option.is_some observation.journal_pending then
            state.resource_share_uncertain_ids <- key :: state.resource_share_uncertain_ids;
          (match state.resource_share_recovery_prompt with
           | Some prompt when prompt.recovery_entry.artifact_id = report.id
               && Some prompt.recovery_entry <> observation.journal_pending ->
             state.resource_share_recovery_prompt <- None
           | Some _ | None -> ())
        | Report_revision report, (Share_journal_unavailable _ | Share_journal_not_needed) ->
          Option.iter (fun origin -> let key = origin, report.id in
            if not (List.mem key state.resource_share_uncertain_ids) then
              state.resource_share_uncertain_ids <- key :: state.resource_share_uncertain_ids)
            (workspace_input_identity_of_server state.server_identity)
        | (Report_revision _ | Mcp_uri _), (Share_journal_checked _ | Share_journal_unavailable _ | Share_journal_not_needed) -> ());
      Masc_tui_resources_updates.read_done state ~request result;
      if admitted && copy then begin
        state.resource_copy_pending <- None;
        match Masc_tui_resource_document.copy_public_url state with
        | Error detail -> report_action state "error" ("Public link was not copied: " ^ detail)
        | Ok url ->
          (match workspace_change_origin state with
           | Error detail -> report_action state "error" ("Public link was not copied: " ^ detail)
           | Ok origin -> state.resource_copy_ready <- Some {
               public_copy_url=url; public_copy_workspace=state.workspace_authority;
               public_copy_read_authority=state.workspace_read_authority;
               public_copy_origin=origin; public_copy_key=request.key })
      end;
      Drawn_changed
  | Resource_msg (Resource_diagram_ready (request,source,claim,result)) ->
      let _,cols = get_terminal_size () in
      let _,height = Masc_tui_render_resources.document_viewport state
        ~rows:(surface_rows state) ~cols in
      Masc_tui_resource_document.settle_diagram ~claim
        ~cols:(resource_content_cols state ~cols) ~height state ~request ~source result;
      Drawn_changed
  | Github_msg (Github_identity_view_loaded (request, result)) ->
      Masc_tui_identity_updates.github_view_loaded state request result;
      Drawn_changed
  | Identity_msg (Identity_switch_set (keeper_name, provider_id, enabled, result)) ->
      Masc_tui_identity_updates.switch_set state ~keeper_name ~provider_id ~enabled
        ~report:(report_action state) ~notice:(present_identity_notice state)
        ~refresh:(fun keeper -> Masc_tui_identity_requests.launch_view state
          ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state mailbox) keeper) result;
      Drawn_changed
  | Identity_msg (Identity_providers_loaded (request, result, attempts)) ->
      Masc_tui_identity_updates.providers_loaded state request
        ~report:(report_action state "error") ~now:(Masc_tui_wake.Mono.now ())
        ~wall_now:(Unix.gettimeofday ()) ~attempts result;
      Drawn_changed
  | Identity_msg (Identity_login_started (request, result)) ->
      Masc_tui_identity_updates.login_started state request ~now:(Unix.gettimeofday ())
        ~report:(report_action state) ~notice:(present_identity_notice state) result;
      Drawn_changed
  | Identity_msg (Identity_app_saved (keeper_name, provider_id, result)) ->
      Masc_tui_identity_updates.app_saved ~ko:(state.ui_language = Lang_ko) ~keeper_name ~provider_id
        ~notice:(present_identity_notice state) result;
      Drawn_changed
  | Identity_msg (Identity_disconnected (keeper_name, provider_id, result)) ->
      Masc_tui_identity_updates.disconnected state ~keeper_name ~provider_id
        ~notice:(present_identity_notice state)
        ~refresh:(fun keeper -> Masc_tui_identity_requests.launch_view state
          ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state mailbox) keeper)
        (Result.map (Masc_tui_identity_model.disconnect_receipt_text ~provider_id) result);
      Drawn_changed
  | Identity_msg (Identity_refreshed (keeper_name, result)) ->
      Masc_tui_identity_updates.refreshed state ~keeper_name
        ~report:(report_action state)
        ~refresh:(fun keeper -> Masc_tui_identity_requests.launch_view state
          ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state mailbox) keeper) result;
      Drawn_changed
  | Account_msg (Account_login_event (view, generation, event)) ->
      (match state.account_login with
       | Some current when current == view && view.generation = generation ->
         view.Masc_tui_account_login.ko <- state.ui_language = Lang_ko;
         let action = Masc_tui_account_login.event ~generation view event in
         (match event with
           | Masc_tui_account_login.Started _ | Login_failed _ -> Masc_tui_surface_requests.Account_requests.remember_account_login state view
           | Masc_tui_account_login.Output _ | Screen _ | Input_ready | Complete _ | Login_error -> ());
         Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view action
       | Some _ | None -> ());
      Drawn_changed
  | Account_msg (Account_login_batch_step (view, generation, batch, outcome)) ->
      (match List.find_opt (fun current -> current == view)
          (Option.to_list state.account_login @ state.account_login_detached) with
       | Some current when current == view && view.generation = generation ->
         let module Login = Masc_tui_account_login in
         view.ko <- state.ui_language = Lang_ko;
         (match outcome with
          | Error refusal ->
            let notice = workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Account_login refusal in
            Login.prepare_interrupted view notice
          | Ok (Masc_tui_http.Setup_transport_error detail) ->
            let notice =
              if state.ui_language = Lang_ko then
                detail ^ " · 연결을 확인한 뒤 a로 이어서 확인하세요."
              else
                detail ^ " · check the connection and press a to continue."
            in
            Login.prepare_interrupted view notice
          | Ok (Masc_tui_http.Setup_answered json) ->
            (match Login.prepared_batch_step view batch (Ok json) with
             | Some next_batch ->
               Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view (Login.Prepare_batch next_batch)
             | None -> ())
          | Ok (Masc_tui_http.Setup_http_error detail) ->
            (match Login.prepared_batch_step view batch (Error detail) with
             | Some next_batch ->
               Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view (Login.Prepare_batch next_batch)
             | None -> ()))
       | Some _ | None -> ());
      Drawn_changed
  | Account_msg (Account_login_json (view, generation, action, result)) ->
      state.account_login_readings <- List.filter
        (fun (held, gen, _) -> held != view || gen <> generation) state.account_login_readings;
      (* A closed model save or activation still owns its receipt and refresh. Workspace
         withdrawal cancels and drops both the open and detached views. *)
      (match List.find_opt (fun current -> current == view)
          (Option.to_list state.account_login @ state.account_login_detached) with
       | Some current when current == view && view.generation = generation ->
         let module Login = Masc_tui_account_login in
         view.ko <- state.ui_language = Lang_ko;
         (match (match result with
                 | Ok json -> Either.Right (Ok json)
                 | Error (Request_failed detail) -> Either.Right (Error detail)
                 | Error (Request_withdrawn refusal) -> Either.Left refusal) with
          | Either.Left refusal ->
            (* Not sent: the panel says the kept-back notice and settles as it
               does for a failed request of the same action (RFC §2). *)
            let notice = workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Account_login refusal in
            (match action with
             | Login.Input (sequence, _) ->
               if sequence = view.input_sequence && view.input_pending then begin
                 view.input_pending <- false; view.activity_started_at <- None; view.notice <- notice end
             | Login.Activate_saved saved ->
               Login.activation_kept_back view saved notice;
               Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view (Login.Refresh_saved saved)
             | Login.Refresh_saved saved -> Login.refresh_saved_kept_back view saved notice
             | Login.Refresh_retry -> Login.refresh_retry view (Error notice); view.notice <- notice
             | Login.Refresh_models -> Login.models_refresh_failed view notice
             | Login.Prepare _ | Login.Prepare_batch _ -> Login.prepare_interrupted view notice
             | Login.Save _ -> view.input_pending<-false; view.draft<-""; Login.save_failed view notice
             | Login.Inventory | Login.Cancel | Login.Cancel_prepare | Login.Recover | Login.Discover | Login.Close | Login.Nothing
             | Login.Select_existing _ | Login.Start _ | Login.Preview_removal _
             | Login.Remove _ | Login.Refresh_removed _ | Login.Refresh_list _ ->
               view.input_pending<-false; view.draft<-""; view.activity_started_at<-None;
               view.recovery<-Login.Login_status; view.phase<-Login.Failed; view.notice<-notice)
          | Either.Right result ->
         let applied = match action, result with
           | Login.Input (sequence, _), result -> Login.input_response ~sequence view result; Ok ()
           | Login.Activate_saved saved, result ->
             let active = Login.activated view saved result in
             if active then (
               Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_config_load ~force:true state ~mailbox;
               Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load ~intent:Snapshot_read.Refresh state ~mailbox;
               Masc_tui_surface_requests.Memory_repository_requests.launch_runtime_surface_load state ~mailbox ~force:true);
             Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view (Login.Refresh_saved saved);
             Ok ()
           | Login.Refresh_saved saved, result -> Login.refresh_saved view saved result; Ok ()
           | Login.Refresh_retry, result -> Login.refresh_retry view result; Ok ()
           | Login.Prepare_batch batch, result ->
             (match Login.prepared_batch_step view batch result with
              | Some next_batch ->
                Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view (Login.Prepare_batch next_batch)
              | None -> ());
             Ok ()
           (* The request's own error is the reason: the server's sentence for a
              refusal ("HTTP 502: Runtime ... did not pass ... verification"),
              the transport's for a dropped connection. A fixed sentence here
              hid which runtime a save's verification refused. A context
              failure returns to the same model instead of refreshing the list. *)
           | (Login.Save _ | Login.Prepare _ | Login.Refresh_models), Error detail -> Error detail
           | (Login.Inventory, Error detail) | (Login.Select_existing _, Error detail)
           | (Login.Start _, Error detail) | (Login.Cancel, Error detail) | (Login.Cancel_prepare, Error detail)
           | (Login.Recover, Error detail) | (Login.Discover, Error detail)
           | (Login.Close, Error detail)
           | (Login.Nothing, Error detail) | (Login.Preview_removal _, Error detail)
           | (Login.Remove _, Error detail) | (Login.Refresh_removed _, Error detail)
           | (Login.Refresh_list _, Error detail) ->
               Error (detail ^ ui_text state ~ko:" · r로 다시 확인하세요." ~en:" · Press r to check again.")
           | (Login.Inventory, Ok json) | (Login.Select_existing _, Ok json)
           | (Login.Start _, Ok json) | (Login.Cancel, Ok json) | (Login.Cancel_prepare, Ok json) | (Login.Recover, Ok json)
           | (Login.Discover, Ok json) | (Login.Refresh_models, Ok json) | (Login.Prepare _, Ok json) | (Login.Save _, Ok json)
           | (Login.Close, Ok json) | (Login.Nothing, Ok json) | (Login.Preview_removal _, Ok json)
           | (Login.Remove _, Ok json) | (Login.Refresh_removed _, Ok json)
           | (Login.Refresh_list _, Ok json) -> (match action with
             | Login.Inventory ->
               (match Login.inventory view json with
                | Ok () -> Masc_tui_surface_requests.Account_requests.restore_account_login state view; Ok () | Error _ as error -> error)
             | Refresh_saved saved -> Login.refresh_saved view saved (Ok json); Ok ()
             | Refresh_retry -> Login.refresh_retry view (Ok json); Ok ()
             | Select_existing provider ->
               (match Login.selected_account view provider json with
                | Ok () -> Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view Discover; Ok ()
                | Error _ as error -> error)
             | Discover -> Login.models view json
             | Refresh_models -> Login.refreshed_models view json
             | Prepare model -> Login.prepared view model json
             | Prepare_batch _ -> Ok ()
             | Recover -> (match Login.receipt view json with
               | Ok true -> Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view Discover; Ok ()
               | Ok false -> Ok () | Error _ as error -> error)
             | Save _ -> (match Login.saved view json with
               | Ok saved -> Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view (Login.Activate_saved saved); Ok ()
               | Error message -> Error message)
             | Input _ -> Ok ()
             | Preview_removal {provider; refused} -> Login.removal_preview view provider ~refused json
             | Refresh_list list_view ->
               (match Login.inventory ~view:list_view view json with
                | Ok () -> Masc_tui_surface_requests.Account_requests.restore_account_login state view; Ok () | Error _ as error -> error)
             | Refresh_removed {client; notice} ->
               (match Login.inventory ~view:(Login.Accounts client) view json with
                | Ok () -> Masc_tui_surface_requests.Account_requests.restore_account_login state view; view.notice<-notice; Ok () | Error _ as error -> error)
             (* A removal answers through [Account_login_removal]. *)
             | Remove _ -> Ok ()
             | Activate_saved _ | Start _ | Cancel | Cancel_prepare | Close | Nothing -> Ok ()) in
         (match applied with
          | Ok () -> ()
          | Error message -> view.input_pending<-false; view.draft<-"";
            (match action with
             | Login.Save _ -> Login.save_failed view message
             | Login.Prepare _ | Login.Prepare_batch _ -> Login.prepare_failed view message
             | Login.Refresh_models -> Login.models_refresh_failed view message
             | Login.Input _ -> view.activity_started_at<-None; view.notice<-message
             | Login.Inventory | Login.Refresh_retry | Login.Cancel | Login.Cancel_prepare | Login.Recover | Login.Discover
             | Login.Close | Login.Nothing | Login.Activate_saved _ | Login.Refresh_saved _
             | Login.Select_existing _ | Login.Start _ | Login.Preview_removal _
             | Login.Remove _ | Login.Refresh_removed _ | Login.Refresh_list _ ->
               view.recovery<-Login.Login_status; view.phase<-Login.Failed; view.activity_started_at<-None; view.notice<-message)))
       | Some _ | None -> ());
      Drawn_changed
  | Account_msg (Account_login_removal (view, generation, provider, login_store, outcome)) ->
      (match state.account_login with
       | Some current when current == view && view.generation = generation ->
         let module Login = Masc_tui_account_login in
         let ko = state.ui_language = Lang_ko in
         view.ko <- ko;
         (match outcome with
          | Masc_tui_http.Post_answered _ ->
            Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view
              (Login.Refresh_removed {client = provider.client; notice = Login.removed_notice ~ko provider login_store})
          (* The server's refusal is about the file as it is now -- it moved,
             or the account can no longer go -- so the preview is read again
             under it rather than left standing. *)
          | Masc_tui_http.Post_refused message ->
            Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox view (Login.Preview_removal {provider; refused = Some message})
          | Masc_tui_http.Post_unanswered detail ->
            view.recovery<-Login.Login_status; view.phase<-Login.Failed; view.activity_started_at<-None;
            view.notice <-
              ui_text state
                ~ko:"계정을 지웠는지 확인하지 못했습니다. r로 목록을 다시 읽으세요. "
                ~en:"Could not confirm account removal. Press r to reload the list. "
              ^ detail)
       | Some _ | None -> ());
      Drawn_changed
  | Github_msg (Github_login_lines (keeper_name, lines)) ->
      Masc_tui_github_ui.login_lines state ~keeper_name lines;
      Drawn_changed
  | Github_msg (Github_login_finished (keeper_name, result)) ->
      Masc_tui_github_ui.login_finished state ~keeper_name
        ~report:(fun level detail -> report_action state level detail)
        ~refresh:(fun keeper -> Masc_tui_identity_requests.launch_github_view state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state mailbox) keeper) result;
      Drawn_changed
  | Github_msg (Github_token_saved (keeper_name, result)) ->
      Masc_tui_github_ui.token_saved state ~keeper_name
        ~report:(fun level detail -> report_action state level detail)
        ~refresh:(fun keeper -> Masc_tui_identity_requests.launch_github_view state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state mailbox) keeper) result;
      Drawn_changed
  | System_log_streamed (stream, event) -> Masc_tui_refresh_settlement.System_log_stream.take_system_log_stream state stream event; Drawn_changed
  | Schedule_msg (Schedules_loaded (Schedule_agenda_read ticket, result)) ->
      let result = Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.Schedule_read result in
      let current = Snapshot_read.is_current state.schedules_agenda_read ticket in
      apply_schedule_agenda_read state ticket result;
      if current then
        state.schedules_agenda_owed <- settled_schedule_read state.schedules_agenda_owed result;
      Drawn_changed
  | Schedule_msg (Schedules_loaded (Schedule_page_read request, result)) ->
      let result = Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.Schedule_read result in
      let current_agenda =
        Option.exists (Snapshot_read.is_current state.schedules_agenda_read)
          request.spr_agenda_ticket in
      let current_page = Snapshot_read.is_current state.schedules_read request.spr_ticket in
      apply_schedule_page_read state request result;
      if current_page then
        state.schedules_page_owed <- settled_schedule_read state.schedules_page_owed result;
      if current_agenda then
        state.schedules_agenda_owed <- settled_schedule_read state.schedules_agenda_owed result;
      Drawn_changed
  | Schedule_msg (Schedule_wake_history_loaded (schedule_id, result)) ->
      (* A history that arrived for a row the reader has left is not this
         pane's answer; dropping it is what keeps one schedule's attempts from
         being read as another's. *)
      if
        Option.equal String.equal state.schedule_detail_id (Some schedule_id)
      then begin
        (match state.schedule_wake_history_inflight with
         | Some inflight when String.equal inflight schedule_id ->
             state.schedule_wake_history_inflight <- None
         | Some _ | None -> ());
        match result with
        | Ok history ->
            state.schedule_wake_history <- Some history;
            state.schedule_wake_history_error <- None
        | Error failure ->
            state.schedule_wake_history <- None;
            state.schedule_wake_history_error <- Some (schedule_id,
              request_failure_text ~ko:(state.ui_language = Lang_ko)
                ~request:Kept_request.Wake_history_read failure)
      end
      else if
        Option.equal String.equal state.schedule_wake_history_inflight
          (Some schedule_id)
      then state.schedule_wake_history_inflight <- None;
      Drawn_changed
  | Keeper_msg (Keeper_schedules_loaded (request, result)) ->
      let current = keeper_schedules_answer_current state request in
      (* Asked before the answer is applied, which retires its request. *)
      let settles = keeper_schedules_answer_settles state request in
      apply_keeper_schedules_read state request result;
      if current then
        settle_keeper_schedules_read state ~keeper:request.kspr_detail.drr_keeper ~settles
          result;
      Drawn_changed
  | Keeper_msg (Keeper_story_turns_loaded (request, result)) ->
      (* An answer for a Keeper the cursor has left settles nothing; the read
         of the Keeper it stands on does. *)
      if Masc_tui_fetched.is_current ~equal:String.equal state.keeper_story_turns request then
        state.keeper_story_turns_owed <-
          (match result with
           | Ok _ -> Masc_tui_owed_read.succeeded state.keeper_story_turns_owed
           | Error _ -> failed_read state.keeper_story_turns_owed);
      state.keeper_story_turns <-
        Masc_tui_fetched.complete ~equal:String.equal state.keeper_story_turns request result;
      Drawn_changed
  | Keeper_msg (Keeper_memory_activity_loaded (request, result)) ->
      if Masc_tui_fetched.is_current ~equal:String.equal state.memory_activity request then
        state.memory_activity_owed <-
          (match result with Ok _ -> Masc_tui_owed_read.succeeded state.memory_activity_owed
           | Error _ -> failed_read state.memory_activity_owed);
      state.memory_activity <-
        Masc_tui_fetched.complete ~equal:String.equal state.memory_activity request
          (Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.Memory_activity_read result);
      Drawn_changed
  | Schedule_msg (Schedule_cancel_done (schedule_id, result)) -> (
      match result with
      | Ok message ->
          state.schedule_cancel_armed <- None;
          state.schedule_cancel_error <- None;
          report_action state "system"
            (ui_text state ~ko:"일정: " ~en:"Schedule: " ^ message);
          (* The row shown still carries the old status until a read lands; a
             cancelled row that reads "scheduled" invites a second cancel. The
             server announces [schedule_store_invalidated] for this write too, so the
             read is owed and both land on the one the loop launches. *)
          owe_schedules_read state
      | Error err ->
          state.schedule_cancel_armed <- None;
          state.schedule_cancel_error <- Some (schedule_id, err);
          (* A refusal is new evidence for the operator's action. Reveal its
             first row even when the request was sent from the document end. *)
          if state.schedule_detail_id = Some schedule_id then state.schedule_scroll <- 0);
      Drawn_changed
  | Verification_msg (Verification_verdict_done result) -> (
      state.verification_verdict_inflight <- None;
      match result with
      | Ok (message, noop) ->
          state.verification_verdict_armed <- None;
          state.verification_verdict_error <- None;
          report_action state "system"
            (if noop then
               Printf.sprintf "Verification: %s (already recorded)" message
             else "Verification: " ^ message);
          (* The row shown still says awaiting until this lands; a judged row
             that stays listed invites a second verdict. A GET already in
             flight began before this POST committed, so its result cannot
             restore the old queue; it must be followed by a fresh read. *)
          state.verification <- None;
          state.verification_error <- None;
          if state.verification_inflight then
            state.verification_refresh_after_inflight <- true
          else launch_verification_load state ~mailbox
      | Error err ->
          state.verification_verdict_armed <- None;
          state.verification_verdict_error <- Some err);
      Drawn_changed
  | Harness_msg (Harness_label_done result) -> (
      match result with
      | Ok message ->
          report_action state "system" ("Harness: " ^ message);
          (* The server announces the label before it answers, so this owed
             read usually follows the announced one; it is the read when the
             feed is down. *)
          owe_harness_read state
      | Error (Request_failed err) -> report_action state "error" ("Harness label: " ^ err)
      | Error (Request_withdrawn refusal) ->
          Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Harness_label refusal);
      Drawn_changed
  | Approvals_msg (Approval_decision_done (approval, decision, result, generation, approvals)) ->
      apply_approval_decision_completion state generation approval decision
        result approvals;
      Drawn_changed
  | Ask_msg (Ask_followup_observed (read, event, received_ns)) ->
      let request=read.afr_request and submission=read.afr_submission in
      Option.iter (fun result ->
        Ask_followup_observation.emit read ~sources:(Masc_tui_types.current_ask_followup state)
          (Ask_followup_observation.Followup_source_applied (event,received_ns,Result.is_ok result)))
        (Masc_tui_types.take_ask_followup_event state request submission event);
      Drawn_changed
  | Ask_msg (Ask_followup_finished (read, result)) ->
      let request=read.afr_request and submission=read.afr_submission in
      Option.iter (fun result ->
        state.ask_followup_owed <- (match result with
          | Ok () -> Masc_tui_owed_read.succeeded state.ask_followup_owed
          | Error (Ask.Followup_cancelled | Ask.Followup_not_started _ | Ask.Followup_withdrawn) ->
              Masc_tui_owed_read.abandoned state.ask_followup_owed
          | Error (Ask.Followup_read_failed _) -> failed_read state.ask_followup_owed);
        Ask_followup_observation.emit read ~sources:(Masc_tui_types.current_ask_followup state)
          (Ask_followup_observation.Followup_ui_settled result))
        (Masc_tui_types.finish_ask_followup_read state request submission result);
      Drawn_changed
  | Ask_msg (Ask_answer_receipt_ready submission) ->
      Masc_tui_operator_actions.Ask_actions.apply_ask_answer_receipt state submission ~mailbox;
      Drawn_changed
  | Ask_msg (Ask_answer_done (submission, result, asks)) ->
      if ask_submission_inflight state submission then begin
        Masc_tui_operator_actions.Ask_actions.apply_ask_answer_receipt state submission ~mailbox;
        Masc_tui_operator_actions.Ask_actions.apply_ask_answer_completion ~settle_asks:Masc_tui_refresh_settlement.Approvals_asks_settlement.settle_asks state submission result asks;
        if Option.is_none (Masc_tui_types.current_ask_followup state)
           && Option.is_none state.ask_followup_error then
          Masc_tui_operator_actions.Ask_actions.launch_ask_followup_load state ~mailbox
      end;
      Drawn_changed
  | Keeper_msg (Keeper_chat_dispatch_started (request, was_replay, acknowledge)) ->
      let proceed = ref false in
      Fun.protect
        ~finally:(fun () -> Eio.Promise.resolve acknowledge !proceed)
        (fun () ->
          match
            inflight_entry_by_request_id state request.Keeper_chat.request_id
          with
          | Some entry
            when keeper_preflight_dispatch_allowed state request ->
              (* The first POST may happen once this acknowledgement leaves.
                 A later checkpoint/reconnect must never restore a draft. *)
              entry.phase <- Turn_streaming;
              Masc_tui_chat_dispatch.Chat_watching.append_user_history_once ~submitted_at:entry.submitted_at state
                request;
              (* Staging already consumed this request's composer. A late
                 dispatch owns only its promoted request, never a newer draft,
                 even when the operator types the same words again. *)
              add_event state "message"
                (Printf.sprintf "%s Keeper request: %s"
                   (if was_replay then "Replaying exact" else "Dispatching")
                   request.request_id);
              if
                Option.exists
                  (String.equal request.Keeper_chat.keeper_name)
                  state.msg_target_keeper_name
              then state.msg_live <- Some entry.log;
              proceed := true
          | Some _ | None -> ());
      Drawn_changed
  | Keeper_msg (Keeper_chat_done (request, _was_replay, Keeper_chat_kept_back refusal, acknowledge)) ->
      (* Settles as the unsent request it is: the input is retained where the
         preflight put it back, or, beside another preflight for the same
         Keeper, held as an error of the request would hold it. *)
      Fun.protect
        ~finally:(fun () -> Eio.Promise.resolve acknowledge ())
        (fun () ->
          let ko = state.ui_language = Lang_ko in
          let notice kept =
            kept_back ~ko ~request:Kept_request.Message (workspace_refusal_reason ~ko refusal) kept
            ^ " · " ^ request.Keeper_chat.request_id in
          if recover_failed_keeper_preflight state request then begin
            let queued = List.exists (fun (_, id, intervention) ->
                String.equal id request.Keeper_chat.request_id && match intervention with
                | Retained_before_dispatch -> true
                | Retained_after_stop | Awaiting_control _ -> false)
                state.keeper_interactive_waiting in
            report_action state "system"
              (notice (if queued then Queued_input_kept else Draft_kept))
          end else
            match inflight_by_request_id state request.Keeper_chat.request_id with
            | Some current when Keeper_chat.same_request_identity current request ->
                Masc_tui_chat_dispatch.Chat_watching.append_chat_history state request Message_status (notice Nothing_kept);
                report_action state "error" (notice Nothing_kept)
            | Some _ | None -> ());
      Drawn_changed
  | Keeper_msg (Keeper_chat_done (request, _was_replay, Keeper_chat_answered result, acknowledge)) ->
      let applied =
        Fun.protect
          ~finally:(fun () -> Eio.Promise.resolve acknowledge ())
          (fun () ->
            match result with
            | Error _ when recover_failed_keeper_preflight state request ->
                report_action state "system"
                  (Printf.sprintf "Keeper request %s was not sent; input retained"
                     request.request_id);
                false
            | Ok _ | Error _ ->
                let terminal = match result with
                  | Ok _ -> true
                  | Error error ->
                      Keeper_chat.error_certainty ~was_unverified:false error
                      <> Keeper_chat.Outcome_unverified in
                if terminal then
                  settle_live_turn state request
                    ~record:(Keeper_chat.operation_record_of_result result);
                Masc_tui_refresh_settlement.Workspace_settlement.apply_keeper_chat_result state request result)
      in
      if applied then begin
        (* A terminal operation has persisted the user row, reply and tool
           calls. Only this boundary may replace the live projection or hand
           the Keeper slot to NEXT. *)
        if
          Option.exists
            (String.equal request.Keeper_chat.keeper_name)
            state.msg_target_keeper_name
        then begin
          launch_keeper_history_load ~load_file_changes:false state ~mailbox
            ~keeper_name:request.Keeper_chat.keeper_name;
          if state.view = Keepers Keeper_message then
            launch_keeper_chat_tool_details_load ~force:true state ~mailbox
              ~keeper_name:request.Keeper_chat.keeper_name
        end;
        Masc_tui_transport.Local_sources.launch_workspace_read state ~mailbox ~intent:Snapshot_read.Refresh base_path;
        Masc_tui_chat_dispatch.Queue_steer.launch_waiting_keeper_input state ~mailbox
          ~keeper_name:request.Keeper_chat.keeper_name;
        Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox
      end;
      Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~change:(Waiting_keepers [request.Keeper_chat.keeper_name]) state ~mailbox;
      Drawn_changed
  | Keeper_msg (Keeper_chat_stream_deltas (request, deltas)) ->
      (* Each Keeper can stream independently. Looking up the request keeps a
         background turn from replacing the selected Keeper's transcript and
         keeps its tool rows available when that turn settles. *)
      (match
         inflight_entry_by_request_id state request.Keeper_chat.request_id
       with
       | Some entry
         when Keeper_chat.same_request_identity entry.sent_request request ->
           entry.phase <- Turn_streaming;
           let now = Unix.gettimeofday () in
           List.iter
             (fun (item : Keeper_chat_live.observed_delta) ->
               turn_log_add ~now:(Option.value item.at ~default:now) entry.log ~seq:item.seq item.delta)
             deltas;
           (* The durable call row is committed before a result delta is
              published. Refresh once per delivered batch while this chat
              displays call output; the loader coalesces overlapping reads. *)
           if state.view = Keepers Keeper_message
              && state.msg_tool_visibility <> Tools_compact
              && state.msg_target_keeper_name
                 = Some request.Keeper_chat.keeper_name
              && List.exists
                   (function
                     | {Keeper_chat_live.delta=Keeper_chat_live.Tool_result _; _} -> true
                     | {Keeper_chat_live.delta=
                          ( Keeper_chat_live.Run_started | Keeper_chat_live.Checkpoint
                          | Keeper_chat_live.External_effect_completed
                          | Keeper_chat_live.Run_finished
                          | Keeper_chat_live.Batch_bound _
                          | Keeper_chat_live.Runtime_attempt_started _
                          | Keeper_chat_live.Provider_retry_observed _
                          | Keeper_chat_live.Stream_model_started _
                          | Keeper_chat_live.Model_content_activity _
                          | Keeper_chat_live.Stream_model_stopped _
                          | Keeper_chat_live.Stream_details _ | Keeper_chat_live.Text _ | Keeper_chat_live.Media _
                          | (Keeper_chat_live.Thinking _ | Keeper_chat_live.Thinking_snapshot _)
                          | Keeper_chat_live.Native_tool_started _
                          | Keeper_chat_live.Native_tool_progress _
                          | Keeper_chat_live.Native_tool_ended _
                          | Keeper_chat_live.Tool_started _ | Keeper_chat_live.Tool_admitted _ | Keeper_chat_live.Tool_args _
                          | Keeper_chat_live.Tool_ended _
                          | Keeper_chat_live.Stream_protocol_error _
                          | Keeper_chat_live.Approval_requested _
                          | Keeper_chat_live.Approval_settled _
                          | Keeper_chat_live.Accepted _ | Keeper_chat_live.Reply_details _
                          | Keeper_chat_live.Run_failed _ | Keeper_chat_live.Undecodable _ ); _} -> false)
                   deltas
           then
             Masc_tui_work_requests.Schedule_call_requests.launch_keeper_calls_load ~force:true state ~mailbox
               request.Keeper_chat.keeper_name;
           List.iter (fun (item : Keeper_chat_live.observed_delta) -> match item.delta with
             | Keeper_chat_live.Accepted {interactive=None;_} ->
               Masc_tui_chat_dispatch.Chat_watching.launch_keeper_turns_load state ~mailbox
             | Keeper_chat_live.Accepted {interactive=Some _;_} -> ()
             | Keeper_chat_live.Run_started | Keeper_chat_live.Checkpoint
             | Keeper_chat_live.External_effect_completed | Keeper_chat_live.Run_finished
             | Keeper_chat_live.Batch_bound _ | Keeper_chat_live.Runtime_attempt_started _
             | Keeper_chat_live.Provider_retry_observed _ | Keeper_chat_live.Stream_model_started _
             | Keeper_chat_live.Model_content_activity _ | Keeper_chat_live.Stream_model_stopped _
             | Keeper_chat_live.Stream_details _ | Keeper_chat_live.Text _ | Keeper_chat_live.Media _
             | (Keeper_chat_live.Thinking _ | Keeper_chat_live.Thinking_snapshot _) | Keeper_chat_live.Native_tool_started _
             | Keeper_chat_live.Native_tool_progress _ | Keeper_chat_live.Native_tool_ended _
             | Keeper_chat_live.Tool_started _ | Keeper_chat_live.Tool_admitted _ | Keeper_chat_live.Tool_args _
             | Keeper_chat_live.Tool_ended _ | Keeper_chat_live.Tool_result _
             | Keeper_chat_live.Stream_protocol_error _ | Keeper_chat_live.Approval_requested _
             | Keeper_chat_live.Approval_settled _ | Keeper_chat_live.Reply_details _
             | Keeper_chat_live.Run_failed _ | Keeper_chat_live.Undecodable _ -> ()) deltas;
           if List.exists (Keeper_chat.same_request_identity request)
                state.keeper_run_next_pending then begin
              let acceptance = List.find_map (fun (item : Keeper_chat_live.observed_delta) -> match item.delta with
                | Keeper_chat_live.Accepted {admission; interactive; _} ->
                  Some (admission, interactive)
                | Keeper_chat_live.Run_started | Keeper_chat_live.Checkpoint
                | Keeper_chat_live.External_effect_completed | Keeper_chat_live.Run_finished
                | Keeper_chat_live.Batch_bound _ | Keeper_chat_live.Runtime_attempt_started _
                | Keeper_chat_live.Provider_retry_observed _
                | Keeper_chat_live.Stream_model_started _
                | Keeper_chat_live.Model_content_activity _
                | Keeper_chat_live.Stream_model_stopped _ | Keeper_chat_live.Stream_details _
                | Keeper_chat_live.Text _ | Keeper_chat_live.Media _ | (Keeper_chat_live.Thinking _ | Keeper_chat_live.Thinking_snapshot _)
                | Keeper_chat_live.Native_tool_started _ | Keeper_chat_live.Native_tool_progress _
                | Keeper_chat_live.Native_tool_ended _ | Keeper_chat_live.Tool_started _ | Keeper_chat_live.Tool_admitted _
                | Keeper_chat_live.Tool_args _ | Keeper_chat_live.Tool_ended _
                | Keeper_chat_live.Tool_result _ | Keeper_chat_live.Stream_protocol_error _
                | Keeper_chat_live.Approval_requested _ | Keeper_chat_live.Approval_settled _
                | Keeper_chat_live.Reply_details _ | Keeper_chat_live.Run_failed _
                | Keeper_chat_live.Undecodable _ -> None) deltas in
              (match acceptance with
               | Some (Keeper_chat_live.Queued, interactive) ->
                 state.keeper_run_next_pending <- List.filter
                   (fun pending -> not (Keeper_chat.same_request_identity pending request))
                   state.keeper_run_next_pending;
                 let automatic = List.mem
                   (request.Keeper_chat.keeper_name, request.request_id)
                   state.keeper_auto_priority_pending in
                 state.keeper_auto_priority_pending <- List.filter
                   (fun (name, id) ->
                     not (String.equal name request.keeper_name
                          && String.equal id request.request_id))
                   state.keeper_auto_priority_pending;
                 let keeper_name = request.Keeper_chat.keeper_name in
                 let control_current =
                   entry.control_generation = keeper_chat_control_generation state keeper_name
                   && not (List.mem_assoc keeper_name state.keeper_chat_control_pending)
                 in
                 let admission_applied = match interactive with
                   | None -> true
                   | Some receipt ->
                     (match receipt.outcome with
                      (* Reconnection keeps this request's priority intent.
                         control_current separately rejects superseded control. *)
                      | Keeper_chat.Applied | Keeper_chat.Replayed -> true
                      | Keeper_chat.Stale_control | Keeper_chat.Paused -> false)
                 in
                 if control_current && admission_applied then begin
                   if automatic then Masc_tui_chat_dispatch.Queue_steer.add_auto_priority_request state request;
                   state.keeper_run_next_ready <- state.keeper_run_next_ready @ [request];
                   Masc_tui_chat_dispatch.Queue_steer.dispatch_ready_run_next state ~mailbox keeper_name
                 end
               | Some (Keeper_chat_live.Running, _)
               | Some (Keeper_chat_live.Settled, _) ->
                 state.keeper_run_next_pending <- List.filter
                   (fun pending -> not (Keeper_chat.same_request_identity pending request))
                   state.keeper_run_next_pending;
                 state.keeper_auto_priority_pending <- List.filter
                   (fun (name, id) ->
                     not (String.equal name request.keeper_name
                          && String.equal id request.request_id))
                   state.keeper_auto_priority_pending;
                 turn_log_note_priority_unavailable entry.log
               | None -> ())
           end;
           if List.exists (fun (item : Keeper_chat_live.observed_delta) -> match item.delta with
             | Keeper_chat_live.Accepted _ -> true | Keeper_chat_live.Run_started
                                                   | Keeper_chat_live.Checkpoint
                                                   | Keeper_chat_live.External_effect_completed
                                                   | Keeper_chat_live.Run_finished
                                                   | Keeper_chat_live.Batch_bound _
                                                   | Keeper_chat_live.Runtime_attempt_started _
                                                   | Keeper_chat_live.Provider_retry_observed _
                                                   | Keeper_chat_live.Stream_model_started _
                                                   | Keeper_chat_live.Model_content_activity _
                                                   | Keeper_chat_live.Stream_model_stopped _
                                                   | Keeper_chat_live.Stream_details _
                                                   | Keeper_chat_live.Text _
                                                   | Keeper_chat_live.Media _
                                                   | (Keeper_chat_live.Thinking _ | Keeper_chat_live.Thinking_snapshot _)
                                                   | Keeper_chat_live.Native_tool_started _
                                                   | Keeper_chat_live.Native_tool_progress _
                                                   | Keeper_chat_live.Native_tool_ended _
                                                   | Keeper_chat_live.Tool_started _ | Keeper_chat_live.Tool_admitted _
                                                   | Keeper_chat_live.Tool_args _
                                                   | Keeper_chat_live.Tool_ended _
                                                   | Keeper_chat_live.Tool_result _
                                                   | Keeper_chat_live.Stream_protocol_error _
                                                   | Keeper_chat_live.Approval_requested _
                                                   | Keeper_chat_live.Approval_settled _
                                                   | Keeper_chat_live.Reply_details _
                                                   | Keeper_chat_live.Run_failed _
                                                   | Keeper_chat_live.Undecodable _ -> false) deltas then
             Masc_tui_chat_dispatch.Queue_steer.launch_waiting_keeper_input state ~mailbox
               ~keeper_name:request.Keeper_chat.keeper_name;
           if Keeper_chat_transcript.awaiting_continuation entry.log.tl_transcript
           then Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox
       | Some _ | None -> ());
      Drawn_changed
  | Keeper_msg (Keeper_chat_stream_unavailable (request, detail)) ->
      (match
         inflight_entry_by_request_id state request.Keeper_chat.request_id
       with
       | Some entry
         when Keeper_chat.same_request_identity entry.sent_request request ->
           entry.phase <- Turn_reconciling
       | Some _ | None -> ());
      Masc_tui_chat_dispatch.Chat_watching.append_chat_history state request Message_status detail;
      Drawn_changed
  | Keeper_msg (Keeper_chat_approval_answered (request, tool_call_id, allow, result)) ->
      (* The operator answered a question that named a tool; echoing the call
         id back tells them nothing they can act on and nothing they can
         match to what they read. The live transcript still holds the call, so
         the answer is said in the same words the question used. *)
      let call_label =
        let by_id =
          match state.msg_live with
          | None -> None
          | Some live ->
            Keeper_chat_transcript.tool_calls live.tl_transcript
            |> List.find_opt (fun (activity : Keeper_chat_transcript.tool_activity) ->
                 Option.equal String.equal activity.call_id (Some tool_call_id))
            |> Option.map (fun (activity : Keeper_chat_transcript.tool_activity) ->
                 activity.tool_name)
        in
        match by_id with
        | Some name when String.trim name <> "" -> Keeper_chat.terminal_safe_text name
        | Some _ | None -> Keeper_chat.compact_request_id tool_call_id
      in
      let text =
        match result with
        | Ok { Masc_tui_http.settled = true; _ } ->
            Printf.sprintf "%s %s" (if allow then "allowed" else "denied") call_label
        | Ok { Masc_tui_http.settled = false; remembered = true } ->
            (* The wait was gone, but the server kept the answer for the
               identical retried call -- said so plainly, or an operator reads
               "too late" as their decision having been thrown away. *)
            Printf.sprintf
              "too late for %s, but the answer is remembered -- the next \
               identical call is %s without asking"
              call_label
              (if allow then "allowed" else "denied")
        | Ok { Masc_tui_http.settled = false; remembered = false } ->
            (* The wait was gone and nothing this keeper asked matches: it
               was answered already, or never held. Said plainly rather than
               shown as taken, so an operator is not told a call was allowed
               when nothing was listening. *)
            Printf.sprintf "too late for %s; the call was no longer waiting"
              call_label
        | Error (Request_failed detail) -> "could not answer the held call: " ^ detail
        | Error (Request_withdrawn refusal) ->
            (* Not sent: the kept-back notice alone (RFC §2). *)
            workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
              ~request:Kept_request.Tool_approval refusal
      in
      Masc_tui_work_requests.Approval_gate_requests.launch_keeper_tool_approvals_load ~intent:Snapshot_read.Refresh state ~mailbox;
      Masc_tui_chat_dispatch.Chat_watching.append_chat_history state request
        (match result with
         | Ok { Masc_tui_http.settled = true; _ }
         | Ok { Masc_tui_http.remembered = true; _ } ->
             Message_status
         | Ok { remembered = false; settled = false } | Error _ -> Message_error)
        text;
      Drawn_changed
  | Keeper_msg (Keeper_tool_approvals_loaded (request, expected_workspace, result)) ->
      (match Snapshot_read.settle state.keeper_tool_approvals_read request with
       | None -> ()
       | Some read ->
       state.keeper_tool_approvals_read <- read;
       if state.workspace_identity = Workspace_identity_match
          && Option.exists (Masc_tui_transport.Workspace_admission.same_server_workspace expected_workspace) state.server_identity then
       match result with
       | Ok held ->
           state.held_calls_owed <- Masc_tui_owed_read.succeeded state.held_calls_owed;
           state.keeper_tool_approvals <- held;
           state.keeper_tool_approvals_error <- None;
           state.keeper_tool_approvals_observed <- true;
           let count = List.length (Masc_tui_approvals_model.approval_items state) in
           if state.approval_cursor >= count then
             state.approval_cursor <- max 0 (count - 1)
       | Error detail ->
           state.held_calls_owed <- failed_read state.held_calls_owed;
           state.keeper_tool_approvals_error <- Some detail);
      Drawn_changed
  | Listen_prepared (request, result) ->
      if input_pending () || Option.is_some state.quit_armed then
        withdraw_pending_music_editor state;
      if take_chat_listen state request then begin
        let notice = Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:(Some request.lr_keeper) in
        let command = match request.lr_destination with
          | Listen_player -> "/listen" | Listen_music_editor -> "/music midi" in
        match result with
        | Error (Request_failed detail) ->
            notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure (command ^ ": " ^ detail)
        | Error (Request_withdrawn refusal) ->
            notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
              (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                 ~request:(Kept_request.Command command) refusal)
        | Ok prepared ->
            match request.lr_destination with
            | Listen_player ->
                let outcome = Masc_tui_attachment_action.perform prepared
                  ~midi_soundfont:!boot_midi_soundfont in
                notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
                  ("/listen: " ^ Masc_tui_attachment_action.describe_outcome outcome)
            | Listen_music_editor ->
                (match Masc_tui_attachment_action.midi_path prepared with
                 | None -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure "/music midi: prepared source is not MIDI"
                 | Some path ->
                     if input_pending () || Option.is_some state.quit_armed then
                       notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
                         "/music midi: opening cancelled while terminal input was pending; run /music midi again when ready"
                     else match open_music_midi ~path with
                       | Ok () -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply "/music midi: returned from the MIDI editor"
                       | Error detail -> notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ("/music midi: " ^ detail))
      end;
      Drawn_changed
  | Sent_image_ready { request; result } ->
      let {sir_generation=generation; sir_view=view; sir_keeper=keeper_name;
           sir_name=name;_} = request in
      let request_was_pending = Option.exists (fun pending -> pending == request) state.sent_image_read in
      let pending = Masc_tui_types.take_image_read state request in
      (match result with
       | Image_worker_busy -> ()
       | Image_kept_back refusal -> (match pending with
         | Some ({sir_purpose=Open_image;_} as origin)
             when not state.msx_open && generation = state.image_request_generation
               && view = state.view && image_request_keeper_is_current state request ->
             (* The guard did not send this read: the notice is drawn alone,
                never as the image's failure (RFC §2). *)
             let said = workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
               ~request:Kept_request.Image_read refusal in
             let opened_original = match origin.sir_owner with
               | Board_image_read (_, subject, _) -> board_image_source_reader state ~message:said subject
               | Local_file_image_read _ | Remote_url_image_read _ | Draft_image_read _ | Peer_image_read _ -> false in
             if not opened_original then
               image_notice state ~view ~keeper_name ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure said
         | Some {sir_purpose=(Open_image | Inspect_image _);_} | None -> ())
       | Image_prepared result -> match pending with
       | Some {sir_purpose=Inspect_image {identity;window};_}
           when state.image_open && not state.msx_open && view=state.view
             && image_request_keeper_is_current state request ->
         (match state.image_inspection, !image_cell_pixels with
          | Some inspected, Some cell_pixels
              when identity == inspected.ii_identity
                && window=inspection_window ~cell_pixels inspected.ii_viewport ->
            let frame = match result with
              | Ok (Masc_tui_image_cache.Png png,_) ->
                (match Masc.Keeper_vision_tool.sniff_image_media_type png,
                    Masc.Keeper_image_dimensions.image_dimensions png with
                 | Ok "image/png", Some (width,height) when width>0 && height>0 ->
                     Raster_image (window,png)
                 | (Ok _ | Error _), (Some _ | None) ->
                     Raster_unavailable (window,"renderer did not return PNG"))
              | Ok (Rgba _,_) -> Raster_unavailable (window,"renderer did not return pixel graphics")
              | Error detail -> Raster_unavailable (window,detail) in
            draw_inspected_image state {inspected with ii_frame=frame}
          | (Some _ | None), (Some _ | None) -> ())
       | Some ({sir_purpose=Open_image;_} as origin)
           when not state.msx_open && generation = state.image_request_generation
         && view = state.view && image_request_keeper_is_current state request -> begin
        let notice = image_notice state ~view ~keeper_name in
        let refuse reason =
          let opened_original = match origin.sir_owner with
            | Board_image_read (_, subject, _) ->
                board_image_source_reader state ~message:("Image preview unavailable: " ^ reason) subject
            | Local_file_image_read _ | Remote_url_image_read _ | Draft_image_read _ | Peer_image_read _ -> false in
          if not opened_original then
            notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure (Printf.sprintf "image %s: %s" name reason)
        in
        match result with
        | Error reason -> refuse reason
        | Ok (presentation,scene) -> draw_prepared_image ?scene ~origin state ~refuse ~title:name presentation
      end
       | (Some {sir_purpose=Open_image;_} | None)
           when request_was_pending && view=Tools && view=state.view && not state.msx_open
             && generation=state.image_request_generation && Option.is_some request.sir_skill_reference
             && (match request.sir_purpose with Open_image -> true | Inspect_image _ -> false) ->
           image_notice state ~view ~keeper_name ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             "Keeper or Skill source is unconfirmed or changed; reopen the image preview"
       | Some {sir_purpose=(Open_image | Inspect_image _);_} | None -> ());
      Drawn_changed
  | Image_render_ready { request; title; caption; page_url; image_url; result } ->
      let current = match Masc_tui_types.take_image_read state request with
        | Some _ ->
          not state.msx_open && request.sir_generation = state.image_request_generation
          && request.sir_view = state.view
          && image_keeper_is_current state ~view:request.sir_view ~keeper_name:request.sir_keeper
        | None -> false in
      if current then begin
      let notice = image_notice state ~view:request.sir_view ~keeper_name:request.sir_keeper in
      let last_open_of_unsaved () = match state.image_cell_view with
        | Some (Image_cells view) when state.image_open && view.ic_workspace=state.workspace_authority
            && view.ic_origin.sir_owner == request.sir_owner
            && Option.is_some view.ic_unsaved_remote -> view.ic_last_open
        | Some (Image_cells _ | Image_cells_withdrawn _) | None -> None in
      let open_page ?unsaved ?last_open ?(open_after=true) e =
           let url =
             Masc_tui_browser.browser_url { Masc_tui_browser.title; page_url; image_url }
           in
           discard_pending_image_copy ();
           show_image_link_card state ~origin:request ~page_url:url ~copy:None ~unsaved ~last_open;
           let report ~kind ~status message =
             notice ~kind message;
             if not (unsaved_remote_save_in_flight state) then
               update_image_link_card state ~path:url status in
           let authority = state.workspace_authority in
           let current () = state.image_open && not state.msx_open && state.workspace_authority = authority
             && request.sir_view = state.view
             && image_keeper_is_current state ~view:request.sir_view ~keeper_name:request.sir_keeper
             && (match state.image_cell_view with
                | Some (Image_cells view) -> view.ic_copy_path = Some url
                    && view.ic_origin.sir_generation = request.sir_generation
                    && Option.is_some (image_cell_origin_for_redraw state
                      ~workspace:view.ic_workspace view.ic_origin)
                    && not (image_cell_source_unconfirmed state view.ic_origin)
                | Some (Image_cells_withdrawn _) | None -> false) in
           let on_result result = if current () then match result with
             | Masc_tui_browser.Opened opener ->
                 report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply ~status:"Opener accepted the link"
                   (Printf.sprintf "Could not draw inline (%s). %s accepted: %s" e opener url)
             | Rejected detail -> report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:detail
                 (Printf.sprintf "image %s: %s; browser: %s" title e detail)
             | Uncertain detail -> report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:"Opener result unknown"
                 (Printf.sprintf "image %s: %s; browser outcome unknown: %s" title e detail) in
           if open_after then begin
             report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply ~status:"Opening requested"
               (Printf.sprintf "Could not draw inline (%s). Opening requested: %s" e url);
             match launch_image_opener ~url
               ~allow_start:(fun () -> current () && not (image_input_pending ())) ~on_result () with
             | Ok opener -> record_image_link_opener state ~path:url ~target:url opener
             | Error detail -> report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:detail
                 (Printf.sprintf "image %s: %s; browser: %s" title e detail)
           end else
             report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:"Original held; s saves it"
               (Printf.sprintf "image %s: %s" title e) in
      let refuse reason =
        notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure (Printf.sprintf "image %s: %s" title reason) in
      let defer_page ~source reason =
        (* A size change can refuse a cell frame after the worker completes.
           Let pending terminal input withdraw the request before opening the
           browser, just as it can for an ordinary worker failure. *)
        state.sent_image_read <- Some request;
        launch_remote_image_result ~mailbox ~request ~title ~caption ~page_url ~image_url
          (fun () -> Ok (Masc_tui_image_cache.Remote_cells {source;cells=Error reason})) in
      (match result with
       | Error e -> open_page e
       | Ok prepared ->
           match Masc_tui_image_cache.decide_remote ~graphics:!terminal_draws_images
               ~colour:(character_images_available ()) prepared with
           | Fetch_remote ->
               state.sent_image_read <- Some request;
               notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply (Printf.sprintf "Loading image: %s" image_url);
               launch_remote_image_fetch state ~mailbox ~request ~title ~caption ~page_url ~image_url
                 ~bounded:(!terminal_draws_images = Some false)
           | Prepare_native_source source ->
               state.sent_image_read <- Some request;
               launch_remote_image_native_source state ~mailbox ~request ~title ~caption ~page_url ~image_url source
           | Prepare_remote_cells source ->
               let display = match cell_image_terminal_size () with
                 | None -> Error "terminal size is unavailable"
                 | Some (rows, columns) -> Ok (Masc_tui_image_cache.Character_cells {
                     columns=max 0 (columns - 2);rows=max 0 (rows - 3 - List.length caption)}) in
               state.sent_image_read <- Some request;
               launch_remote_image_cells state ~mailbox ~request ~title ~caption ~page_url ~image_url ~display source
           | Draw_remote_png png -> draw_image state ~caption ~refuse ~title png
           | Draw_remote_cells {source;cells} ->
               draw_prepared_image ~caption ~origin:request state ~refuse:(defer_page ~source) ~title cells
           | Open_remote_page {reason;source} ->
               (match source with
                | Some source ->
                    state.sent_image_read <- Some request;
                    launch_remote_image_copy state ~mailbox ~request ~title ~caption
                      ~page_url ~image_url ~reason ~requested_save:false source
                | None -> open_page reason)
           | Hold_remote_source {source;reason;detail;requested_save} ->
               let unsaved = {uri_bytes=source;uri_image_url=image_url;uri_reason=reason} in
               let last_open = if requested_save then last_open_of_unsaved () else None in
               open_page ~unsaved ?last_open ~open_after:(not requested_save && not (String.equal page_url image_url))
                 (reason ^ "; could not save the captured image: " ^ detail)
           | Open_remote_copy {copy;reason;requested_save} ->
               let path = Keeper_chat.terminal_safe_text ~preserve_newlines:false copy.path in
               begin
                 let last_open = if requested_save then last_open_of_unsaved () else None in
                 discard_pending_image_copy ();
                 pending_image_copy := Some copy;
                 let card_current = if not requested_save then false else
                   match state.image_cell_view with
                     | Some (Image_cells view) when state.image_open && not state.msx_open
                         && view.ic_workspace=state.workspace_authority
                         && view.ic_origin.sir_owner == request.sir_owner
                         && Option.is_some view.ic_unsaved_remote ->
                         Option.is_some (image_cell_origin_for_redraw state
                           ~workspace:view.ic_workspace view.ic_origin)
                         && not (image_cell_source_unconfirmed state view.ic_origin)
                     | Some (Image_cells _ | Image_cells_withdrawn _) | None -> false in
                 let interrupted = card_current && image_input_pending () in
                 let retain_requested = card_current && not interrupted && keep_pending_image_copy copy.path in
                 if requested_save && not retain_requested then begin
                   discard_pending_image_copy ();
                   if interrupted then
                     Option.iter (fun path -> update_image_link_card state ~path "s retries")
                       (mark_image_save_cancelled state)
                   else if card_current then
                     (match state.image_cell_view with
                      | Some (Image_cells {ic_copy_path=Some path;_}) ->
                          update_image_link_card state ~path "Save could not be retained; s retries"
                      | Some (Image_cells _ | Image_cells_withdrawn _) | None -> ())
                 end
                 else begin
                 show_image_link_card state ~origin:request ~page_url
                   ~copy:(Some (copy.path,copy.openable)) ~unsaved:None ~last_open;
                 let report ~kind ~status message =
                   notice ~kind message;
                   update_image_link_card state ~path:copy.path status in
                 let current_copy () = match state.image_cell_view with
                   | Some (Image_cells view) when state.image_open && not state.msx_open
                       && view.ic_copy_path = Some copy.path
                       && view.ic_origin.sir_generation = request.sir_generation ->
                       Option.is_some (image_cell_origin_for_redraw state
                         ~workspace:view.ic_workspace view.ic_origin)
                   | Some (Image_cells _ | Image_cells_withdrawn _) | None -> false in
                 let open_target ~image url =
                   let on_result result =
                     if current_copy () then match result with
                     | Masc_tui_browser.Opened opener ->
                         report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply ~status:"Opener accepted the request"
                           (Printf.sprintf "Saved copy: %s. %s accepted the %s"
                             path opener (if image then "image" else "original link"))
                     | Rejected detail ->
                         report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:"Opener could not start"
                           (Printf.sprintf "Saved copy: %s. Opener: %s" path detail)
                     | Uncertain detail ->
                         report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:"Opener result unknown"
                           (Printf.sprintf "Saved copy: %s. Opener outcome is unknown: %s" path detail) in
                   match launch_image_opener ~url
                     ~allow_start:(fun () -> current_copy ()
                       && not (image_cell_source_unconfirmed state request)
                       && not (image_input_pending ())) ~on_result () with
                   | Ok opener ->
                       record_image_link_opener state ~path:copy.path ~target:url opener;
                       if image then ignore (keep_pending_image_copy copy.path)
                   | Error detail ->
                       report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:detail
                         (Printf.sprintf "Saved copy: %s. Opener: %s" path detail) in
                 if requested_save then begin
                   report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply ~status:"Original saved; y copies its path"
                     (Printf.sprintf "Saved copy: %s" path)
                 end else begin
                   report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply ~status:"Opening requested"
                     (Printf.sprintf "Saved copy: %s. Opening requested; preview: %s" path reason);
                   let open_copy = copy.openable && String.equal page_url image_url in
                   open_target ~image:open_copy (if open_copy then copy.path else page_url)
                 end
                 end
               end)
      end else
        (match result with
         | Ok (Masc_tui_image_cache.Remote_copy_ready {copy;_}) ->
             Masc_tui_image_cache.discard_captured_copy copy;
             schedule_discarded_copy_cleanup ()
         | Ok (Remote_unfetched | Remote_native _ | Remote_bounded_source _ | Remote_cells _
              | Remote_busy _ | Remote_bounded_failure _ | Remote_native_failed _ | Remote_copy_failed _) | Error _ -> ());
      Drawn_changed
  | Msx_msg (Msx_live_loaded (request, result)) ->
      (match state.msx_live_in_flight with
       | Some pending when pending == request ->
           state.msx_live_in_flight <- None;
           if request.live_view == !machine_view && request.live_port = state.port
              && state.msx_open && not state.msx_menu_open
              && state.machine_source = Masc.Machine_lane.Msx then begin
             state.msx_live_owed <- (match result with
               | Ok _ -> Masc_tui_owed_read.succeeded state.msx_live_owed
               | Error _ -> failed_read state.msx_live_owed);
             (* [advance] answers [None] when the read changes nothing on
                screen, and MSX carries no activity feed beside the picture,
                so an unchanged read repaints nothing -- the DOS branch below
                already reads it that way. Owed-read bookkeeping still runs:
                liveness is not paint. *)
             let picture_changed =
               match advance_machine_live state ~request:Kept_request.Msx_screen_read
                       state.msx_live (Result.map fst result) with
               | None -> false
               | Some live ->
                   let live, frame = msx_frame_of_live ~previous_live:state.msx_live
                     ~previous_frame:state.msx_frame live in
                   state.msx_live <- live;
                   state.msx_frame <- frame;
                   msx_surface_frame := frame;
                   true in
                        if picture_changed then render_spectator state
           end
       | Some _ | None -> ());
      Drawn_changed
  | Dos_live_loaded (request, result) ->
      (match state.dos_live_in_flight with
       | Some pending when pending == request ->
           state.dos_live_in_flight <- None;
           let watching_dos =
             match state.machine_source with
             | Masc.Machine_lane.Dos -> true
             | Masc.Machine_lane.Msx -> false
           in
           if request.live_view == !machine_view && request.live_port = state.port
              && state.msx_open && (state.msx_menu_open || watching_dos) then begin
             let result =
               match result with
               | Ok (answer, Masc_tui_machine_live.Activity activity) -> Ok (answer, activity)
               | Ok (_, Masc_tui_machine_live.No_activity_feed) ->
                   Error (Request_failed "live: a DOS read answered without an activity feed")
               | Error _ as error -> error
             in
             state.dos_live_owed <- (match result with
               | Ok _ -> Masc_tui_owed_read.succeeded state.dos_live_owed
               | Error _ -> failed_read state.dos_live_owed);
             (* A failed read leaves [dos_activity] as it was -- the sidebar
                keeps showing the last activity it had rather than flashing
                empty on a read that did not answer at all. *)
             let activity_changed =
               match result with
               | Ok (_, activity) ->
                   let changed = activity <> state.dos_activity in
                   state.dos_activity <- activity;
                   changed
               | Error _ -> false
             in
             (* An unchanged picture decodes no pixels. A changed activity
                feed still repaints the spectator sidebar; an identical feed
                remains silent. The read also discovers the DOS watch row
                while the menu is open. *)
             (match advance_machine_live state ~request:Kept_request.Dos_screen_read
                      state.dos_live (Result.map fst result) with
              | None ->
                  if activity_changed && not state.msx_menu_open then
                    render_spectator state
              | Some view ->
                  state.dos_live <- view;
                  if state.msx_menu_open then
                    Masc_tui_msx.render_menu ~write:write_to_terminal state
                  else render_spectator state)
           end
           else if state.msx_open && state.msx_menu_open then
             launch_dos_live_read state ~mailbox
       | Some _ | None -> ());
      Drawn_changed
  | Keeper_msg (Keeper_chat_control_received (keeper_name, generation, token)) ->
      if generation = keeper_chat_control_generation state keeper_name then begin
        (* [false] means no control was pending for this generation and
           the function changed nothing; the token is recorded either way
           so the waiting interactive turn can pick it up. *)
        (* See finish_keeper_chat_control in masc_tui_types.ml. *)
        let control_finished = finish_keeper_chat_control state keeper_name ~generation in
        state.keeper_chat_control_tokens <- (keeper_name, token) ::
          List.remove_assoc keeper_name state.keeper_chat_control_tokens;
        Masc_tui_chat_dispatch.Queue_steer.launch_waiting_keeper_input state ~mailbox ~keeper_name;
        if control_finished then
          Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~change:(Waiting_keepers [keeper_name]) state ~mailbox
      end else Masc_tui_chat_dispatch.Chat_watching.launch_keeper_turns_load state ~mailbox;
      Drawn_changed
  | Keeper_msg (Keeper_preparation_loaded (request, result)) ->
      let details = state.msg_preparation_details in
      state.msg_preparation_details <- (match result with
        | Ok snapshot -> Masc_tui_preparation_details.receive request (Ok snapshot) details
        | Error (Request_failed detail) ->
            Masc_tui_preparation_details.receive request (Error detail) details
        | Error (Request_withdrawn refusal) ->
            Masc_tui_preparation_details.withdraw request
              (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                 ~request:Kept_request.Preparation_read refusal) details);
      Drawn_changed
  | Keeper_msg (Keeper_waiting_loaded (request, snapshot, result)) ->
      let usable = Keeper_waiting_read.accepts_event state.keeper_waiting_read request in
      let reconcile = Keeper_waiting_read.event_needs_reconciliation state.keeper_waiting_read request in
      let current = keeper_waiting_row_current state snapshot in
      let current_name = keeper_waiting_name_current state snapshot in
      let unverified = keeper_waiting_unverified_after state ~current ~current_name result in
      let complete = not usable ||
        (unverified = [] && keeper_turns_projection_complete ~current result) in
      (match Keeper_waiting_read.finish state.keeper_waiting_read request
               ~observed:(not usable || Result.is_ok result) ~success:complete with
       | None -> ()
       | Some (reading, follow_up) ->
           state.keeper_waiting_read <-
             Keeper_waiting_read.publish_event reading ~observed:(usable && Result.is_ok result);
           state.keeper_waiting_owed <-
             (if complete then Masc_tui_owed_read.succeeded state.keeper_waiting_owed
              else failed_read state.keeper_waiting_owed);
           if usable then (match result with
             | Ok { rows; waiting } ->
                 state.keeper_waiting_unverified <- unverified;
                 state.keeper_waiting_error <- None;
                 let fresh, stale = List.partition current rows in
                 let waiting = select_keeper_waiting_observation ~fresh ~stale
                   ~previous_failure:state.keeper_waiting_failure waiting in
                 accept_keeper_waiting_observation state ~rows ~waiting
             | Error detail -> state.keeper_waiting_error <- Some detail);
           if follow_up then begin
             if not usable && reconcile && Result.is_ok result then
               Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~change:Waiting_all ~exclusive:true state ~mailbox
             else Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~exclusive:(not usable && reconcile) state ~mailbox
           end
           else if not usable && reconcile && Result.is_ok result then
             Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~change:Waiting_all ~exclusive:true state ~mailbox);
      Masc_tui_types.keeper_waiting_effect state
  | Keeper_msg (Keeper_turns_loaded (generation, waiting_snapshot, waiting_receipt, result)) ->
      state.keeper_turns_inflight <- false;
      (match result with
       | Ok { rows; waiting } ->
           state.keeper_turns_owed <- Masc_tui_owed_read.succeeded state.keeper_turns_owed;
           let waiting_current = keeper_waiting_row_current state waiting_snapshot in
           let waiting_name_current = keeper_waiting_name_current state waiting_snapshot in
           let waiting_fresh, waiting_stale = List.partition waiting_current rows in
           let accept_waiting =
             Keeper_waiting_read.accepts_poll state.keeper_waiting_read waiting_receipt in
           let reconcile_waiting = not accept_waiting &&
             Keeper_waiting_read.poll_needs_reconciliation state.keeper_waiting_read waiting_receipt in
           if accept_waiting then begin
             let unverified = keeper_waiting_unverified_after state ~current:waiting_current
               ~current_name:waiting_name_current result in
             let complete = unverified = [] &&
               keeper_turns_projection_complete ~current:waiting_current result in
             state.keeper_waiting_read <- Keeper_waiting_read.settle_poll state.keeper_waiting_read ~success:complete;
             (* A waiting list the turns answer could not complete is not a
                write, so nothing announces when it becomes readable. It is
                read again after a wait, unless a waiting read is running. *)
             if not complete && not (Keeper_waiting_read.in_flight state.keeper_waiting_read) then
               state.keeper_waiting_owed <- failed_read state.keeper_waiting_owed;
             state.keeper_waiting_unverified <- unverified;
             state.keeper_waiting_error <- None
           end;
           let current row =
             Option.value ~default:0 (List.assoc_opt row.Tui_decode.ktr_keeper_name generation)
             = keeper_chat_control_generation state row.Tui_decode.ktr_keeper_name
             && not (List.mem_assoc row.Tui_decode.ktr_keeper_name state.keeper_chat_control_pending) in
           let fresh, stale = List.partition current rows in
           List.iter (fun row ->
             state.keeper_chat_control_tokens <- List.remove_assoc row.Tui_decode.ktr_keeper_name
               state.keeper_chat_control_tokens;
             Option.iter (fun token -> state.keeper_chat_control_tokens <-
               (row.Tui_decode.ktr_keeper_name, token) :: state.keeper_chat_control_tokens)
               row.Tui_decode.ktr_chat_control_token) fresh;
           let rows = fresh @ List.filter (fun previous -> List.exists (fun row ->
             String.equal row.Tui_decode.ktr_keeper_name previous.Tui_decode.ktr_keeper_name) stale)
             state.keeper_turns in
           let waiting =
             select_keeper_waiting_observation
               ~fresh:waiting_fresh ~stale:waiting_stale
               ~previous_failure:state.keeper_waiting_failure waiting
           in
           if List.exists (fun row -> not (List.mem_assoc row.Tui_decode.ktr_keeper_name
             state.keeper_chat_control_pending)) stale then Masc_tui_chat_dispatch.Chat_watching.launch_keeper_turns_load state ~mailbox;
           let observed_at = Unix.gettimeofday () in
           (* Two consecutive polls are what "just finished" is made of:
              running in the previous, idle in this one. The glow list is
              advanced before the rows are replaced, or the transition is
              gone. *)
           state.keeper_turn_finishes <-
             Masc_tui_answering.advance_finishes
               ~now:observed_at
               ~previous_rows:state.keeper_turns ~current_rows:rows
               state.keeper_turn_finishes;
           accept_keeper_turn_observation
             ~accept_waiting
             state ~rows ~waiting ~observed_at;
           (match state.view, state.msg_target_keeper_name with
            | Keepers Keeper_message, Some keeper_name ->
                Masc_tui_chat_dispatch.Chat_journals.launch_current_autonomous_journals state ~mailbox ~keeper_name;
                Masc_tui_chat_dispatch.Chat_journals.launch_selected_preparation_operation_read state ~mailbox
            | (Keepers (Keeper_message), None)
            | (Keepers (Keeper_list | (Keeper_detail | (Keeper_logs | (Keeper_calls | Keeper_runtime_pick)))), _)
            | ((Overview | (Acting | (Metrics | (Memory | (Lanes | (Clients | (Board | (Approvals | (Planning | (Schedules | (Verification | (Harness | (Fusion | (Repositories | (Code | (Changes | (Connectors | (Runtime | (Config | (Resources | (Tools | System_logs))))))))))))))))))))), _) -> ());
           let dispatched =
             List.fold_left (fun drawn row ->
               Masc_tui_types.either_drawn_changed drawn
                 (Masc_tui_chat_dispatch.Queue_steer.dispatch_waiting_keeper_input state ~mailbox
                    ~keeper_name:row.Tui_decode.ktr_keeper_name))
               Drawn_unchanged fresh in
           if reconcile_waiting then
             Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~change:Waiting_all ~exclusive:true state ~mailbox;
           (* A queued input handed to the server leaves the chat's queue,
              which no view holds (RFC tui-one-screen-grammar §8). *)
           Masc_tui_types.either_drawn_changed dispatched (Masc_tui_types.keeper_turns_effect state)
       | Error detail ->
           state.keeper_turns_owed <- failed_read state.keeper_turns_owed;
           refuse_keeper_turn_observation state detail;
           Masc_tui_types.keeper_turns_effect state)
  | Gate_msg (Gate_snapshot_loaded (request, expected_workspace, result)) ->
      (match Snapshot_read.settle state.gate_snapshot_read request with
       | None -> ()
       | Some read ->
       state.gate_snapshot_read <- read;
       if state.workspace_identity = Workspace_identity_match
          && Option.exists (Masc_tui_transport.Workspace_admission.same_server_workspace expected_workspace) state.server_identity then
       begin
       match result with
       | Ok snapshot ->
           state.gate_snapshot_owed <- Masc_tui_owed_read.succeeded state.gate_snapshot_owed;
           Masc_tui_approvals_model.accept_gate_snapshot state snapshot;
           let count = List.length (Masc_tui_approvals_model.approval_items state) in
           if state.approval_cursor >= count then
             state.approval_cursor <- max 0 (count - 1)
       | Error detail ->
           fail_gate_snapshot_read state;
           state.gate_pending <- [];
           state.gate_snapshot_observed <- false;
           state.gate_snapshot_authority <- None;
           state.gate_error <- Some detail
       end);
      Drawn_changed
  | Gate_msg (Gate_approval_resolved (approval_id, approve, expected_workspace, result, generation)) ->
      (* Release the single-action slot [launch_gate_resolve] took, whatever the
         outcome, so the header stops drawing [submitting] and the next decision
         is admitted. [begin_action] serialises decisions, so this completion
         owns its slot; the durable server result applies either way. *)
      let flow, owns_action =
        Approval.Flow.finish_action state.approval_flow generation
      in
      state.approval_flow <- flow;
      if owns_action then (match result with
       | Ok () when Masc_tui_work_requests.Approval_gate_requests.retains_receipt_workspace state expected_workspace ->
           report_action state "system"
             (Printf.sprintf "Gate %s %s"
                (if approve then "approved" else "rejected")
                approval_id);
           (* Durably resolved on the server; the row leaves now rather than
              waiting out the next refresh, and the refresh confirms. *)
           state.gate_pending <-
             List.filter
               (fun (pending : Tui_decode.gate_pending) ->
                 not (String.equal pending.Tui_decode.gp_id approval_id))
               state.gate_pending;
           let count = List.length (Masc_tui_approvals_model.approval_items state) in
           if state.approval_cursor >= count then
             state.approval_cursor <- max 0 (count - 1);
           Masc_tui_work_requests.Approval_gate_requests.launch_gate_snapshot_load ~intent:Snapshot_read.Refresh state ~mailbox
       | Ok () -> ()
       | Error (Request_failed detail) ->
           report_action state "error"
             (Printf.sprintf "Gate decision for %s failed: %s" approval_id
                detail)
       | Error (Request_withdrawn refusal) ->
           Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Gate_decision refusal);
      Drawn_changed
  | Gate_msg (Gate_auto_judge_retried (approval_id, expected_workspace, result, generation)) ->
      let flow, owns_action =
        Approval.Flow.finish_action state.approval_flow generation
      in
      state.approval_flow <- flow;
      if owns_action then (match result with
       | Ok () when Masc_tui_work_requests.Approval_gate_requests.retains_receipt_workspace state expected_workspace ->
           report_action state "system"
             (Printf.sprintf "Auto Judge retry started for %s" approval_id);
           Masc_tui_work_requests.Approval_gate_requests.launch_gate_snapshot_load ~intent:Snapshot_read.Refresh state ~mailbox
       | Ok () -> ()
       | Error (Request_failed detail) ->
           report_action state "error"
             (Printf.sprintf "Auto Judge retry for %s failed: %s" approval_id
                detail)
       | Error (Request_withdrawn refusal) ->
           Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Auto_judge_retry refusal);
      Drawn_changed
  | Gate_msg (Gate_mode_set (lane, mode, result)) ->
      (match result with
       | Ok () ->
           report_action state "system"
             (Printf.sprintf "%s Gate set to %s" (Masc_tui_palette.gate_lane_label lane) mode);
           Masc_tui_work_requests.Approval_gate_requests.launch_gate_snapshot_load ~intent:Snapshot_read.Refresh state ~mailbox
       | Error (Request_failed detail) ->
           report_action state "error"
             (Printf.sprintf "%s Gate change failed: %s" (Masc_tui_palette.gate_lane_label lane) detail)
       | Error (Request_withdrawn refusal) ->
           Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Gate_mode_change refusal);
      Drawn_changed
  | Keeper_msg (Keeper_tool_modes_loaded (result, ticket)) ->
      (* Dropped when a press has opened since the fetch went out -- it
         describes the stance from before that press, including a press that
         opened and closed in between (#37609 review) -- and when a later
         fetch of the stance listing already landed, since the older answer
         would put a stance back that the screen had moved past (task-1672). *)
      let order, admitted =
        Approval.Listing_order.admit state.tool_modes_order state.approval_flow
          ticket
      in
      state.tool_modes_order <- order;
      if not admitted then
        state.tool_modes_owed <- Masc_tui_owed_read.abandoned state.tool_modes_owed
      else
        (match result with
         | Ok overrides ->
             state.tool_modes_owed <- Masc_tui_owed_read.succeeded state.tool_modes_owed;
             state.keeper_tool_modes_observed <- true;
             state.keeper_tool_modes_error <- None;
             state.keeper_yolo_names <-
               List.filter_map
                 (fun (keeper, mode) ->
                   match mode with
                   | Masc.Keeper_tool_approval_mode.Yolo -> Some keeper
                   | Masc.Keeper_tool_approval_mode.Auto -> None)
                 overrides
         | Error failure ->
             state.tool_modes_owed <- failed_read state.tool_modes_owed;
             state.keeper_tool_modes_error <- Some (request_failure_text
               ~ko:(state.ui_language = Lang_ko) ~request:Kept_request.Tool_modes_read failure));
      Drawn_changed
  | Keeper_msg (Keeper_tool_mode_set (keeper_name, mode, result, generation)) ->
      let flow, owned = Approval.Flow.finish_action state.approval_flow generation in
      state.approval_flow <- flow;
      if not owned then ()
      else
      (match result with
       | Ok () ->
           state.keeper_yolo_names <-
             (let without =
                List.filter
                  (fun name -> not (String.equal name keeper_name))
                  state.keeper_yolo_names
              in
              match mode with
              | Masc.Keeper_tool_approval_mode.Yolo -> keeper_name :: without
              | Masc.Keeper_tool_approval_mode.Auto -> without);
           report_action state "system"
             (match mode with
              | Masc.Keeper_tool_approval_mode.Yolo ->
                  Printf.sprintf
                    "%s runs every tool call unasked (%s) until set back to \
                     auto"
                    keeper_name
                    (Masc_tui_types.tool_mode_word Masc.Keeper_tool_approval_mode.Yolo)
              | Masc.Keeper_tool_approval_mode.Auto ->
                  Printf.sprintf "%s is back on the approval policy (%s)"
                    keeper_name
                    (Masc_tui_types.tool_mode_word Masc.Keeper_tool_approval_mode.Auto))
       | Error (Request_failed detail) ->
           report_action state "error"
             (Printf.sprintf "could not set %s's gate: %s" keeper_name detail)
       | Error (Request_withdrawn refusal) ->
           Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Tool_mode_change refusal);
      Drawn_changed
  | Keeper_msg (Keeper_tool_approval_answered
      (keeper_name, tool_call_id, approval_id, allow, result, generation)) ->
      (* Release the single-action slot [launch_surface_tool_approval] took, so
         the header clears [submitting] and the next decision is admitted. *)
      let flow, _owns_action =
        Approval.Flow.finish_action state.approval_flow generation
      in
      state.approval_flow <- flow;
      state.keeper_tool_approvals <-
        Approval_authority.after_answer ~keeper_name ~tool_call_id ~approval_id
          ~result state.keeper_tool_approvals;
      let count = List.length (Masc_tui_approvals_model.approval_items state) in
      if state.approval_cursor >= count then
        state.approval_cursor <- max 0 (count - 1);
      report_action state
        (match result with
         | Ok { Masc_tui_http.settled = true; _ }
         | Ok { Masc_tui_http.remembered = true; _ } ->
             "system"
         | Ok { remembered = false; settled = false } | Error _ -> "error")
        (match result with
         | Error (Request_withdrawn refusal) ->
             (* Not sent: the kept-back notice alone (RFC §2). *)
             workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
               ~request:Kept_request.Tool_approval refusal
         | Ok { Masc_tui_http.settled = true; _ } ->
             Printf.sprintf "%s %s's held call %s"
               (if allow then "allowed" else "denied")
               keeper_name
               (Keeper_chat.compact_request_id tool_call_id)
         | Ok { Masc_tui_http.settled = false; remembered = true } ->
             Printf.sprintf
               "too late for %s's call %s, but the answer is remembered -- \
                the next identical call is %s without asking"
               keeper_name
               (Keeper_chat.compact_request_id tool_call_id)
               (if allow then "allowed" else "denied")
         | Ok { Masc_tui_http.settled = false; remembered = false } ->
             Printf.sprintf
               "too late for %s's call %s; it was no longer waiting"
               keeper_name
               (Keeper_chat.compact_request_id tool_call_id)
         | Error (Request_failed detail) -> "could not answer the held call: " ^ detail);
      Masc_tui_work_requests.Approval_gate_requests.launch_keeper_tool_approvals_load ~intent:Snapshot_read.Refresh state ~mailbox;
      Drawn_changed
  | Keeper_msg (Keeper_run_next_done (request, result)) ->
      (match settle_keeper_run_next state request result with
       | Run_next_untracked -> ()
       | (Run_next_received | Run_next_retired) as completion ->
           (match completion, result with
            | Run_next_received, Error (Request_failed detail) ->
                Masc_tui_chat_dispatch.Chat_watching.append_chat_history state request Message_error
                  (ui_text state ~ko:"다음 순서 확인 불가: " ~en:"Could not confirm next turn: " ^ detail)
            | Run_next_received, Error (Request_withdrawn refusal) ->
                (* Not sent: the kept-back notice alone (RFC §2). *)
                Masc_tui_chat_dispatch.Chat_watching.append_chat_history state request Message_error
                  (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                     ~request:Kept_request.Run_next refusal)
            | (Run_next_untracked | Run_next_retired), _
            | Run_next_received, Ok _ -> ());
           Masc_tui_chat_dispatch.Queue_steer.dispatch_ready_run_next state ~mailbox request.Keeper_chat.keeper_name;
           Masc_tui_collab_queue.Keeper_queue.refresh_queue_after_priority state ~mailbox ~keeper_name:request.keeper_name);
      Drawn_changed
  | Keeper_msg (Keeper_observed_interrupt_done (keeper_name, interrupt_token, generation, result)) ->
      settle_keeper_priority_control state keeper_name ~generation ~outcome:(match result with
        | Ok (Masc_tui_interrupt_signal.Signalled _ | Pending_admission_paused) -> Priority_superseded
        | Ok (Not_signalled _) | Error _ -> Priority_unconfirmed);
      let current = keeper_chat_control_result_current state keeper_name ~generation in
      if finish_keeper_chat_control state keeper_name ~generation then begin
        Masc_tui_chat_dispatch.Chat_watching.launch_keeper_turns_load state ~mailbox
      end;
      if current then
        Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~change:(Waiting_keepers [keeper_name]) state ~mailbox;
      if current then state.keeper_observed_interrupts <- List.map (fun item ->
        if item.oi_keeper <> keeper_name || item.oi_token <> interrupt_token then item
        else { item with oi_status = match result with
          | Ok (Masc_tui_interrupt_signal.Signalled _) -> Interrupt_signalled
          | Ok Pending_admission_paused -> Interrupt_declined "Pending input paused; no active turn signalled"
          | Ok (Not_signalled { reason; detail }) ->
            Interrupt_declined (Option.value ~default:reason detail)
          | Error (Request_failed detail) -> Interrupt_failed detail
          | Error (Request_withdrawn refusal) -> Interrupt_kept_back refusal }) state.keeper_observed_interrupts;
      Drawn_changed
  | Keeper_msg (Keeper_chat_interrupt_done (request, generation, result)) ->
      let keeper_name = request.Keeper_chat.keeper_name in
      settle_keeper_priority_control state keeper_name ~generation ~outcome:(match result with
        | Ok (Masc_tui_interrupt_signal.Signalled _ | Pending_admission_paused) -> Priority_superseded
        | Ok (Not_signalled _) | Error _ -> Priority_unconfirmed);
      let current = keeper_chat_control_result_current state keeper_name ~generation in
      if finish_keeper_chat_control state keeper_name ~generation then begin
        Masc_tui_chat_dispatch.Chat_watching.launch_keeper_turns_load state ~mailbox
      end;
      if current then
        Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~change:(Waiting_keepers [keeper_name]) state ~mailbox;
      if current then (match
         inflight_entry_by_request_id state request.Keeper_chat.request_id
       with
       | Some entry
         when Keeper_chat.same_request_identity entry.sent_request request ->
           let live = entry.log.tl_transcript in
           let noted =
             match result with
             | Ok (Masc_tui_interrupt_signal.Signalled { turn_id }) ->
                 Keeper_chat_transcript.Signal_sent
                   { turn_id; signalled_at_ns = Mtime_clock.elapsed_ns () }
             | Ok Masc_tui_interrupt_signal.Pending_admission_paused -> Keeper_chat_transcript.Admission_paused
             | Ok (Masc_tui_interrupt_signal.Not_signalled { reason; detail }) ->
                 Keeper_chat_transcript.Signal_declined
                   (match detail with
                    | None -> reason
                    | Some detail -> reason ^ ": " ^ detail)
             | Error (Request_failed detail) -> Keeper_chat_transcript.Signal_error detail
             | Error (Request_withdrawn refusal) ->
                 (* Not sent: the kept-back notice alone (RFC §2). *)
                 Keeper_chat_transcript.Signal_kept_back
                   (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                      ~request:Kept_request.Keeper_interrupt refusal)
           in
           Keeper_chat_transcript.note_interrupt live noted
       | Some _ | None ->
           (* The turn settled before the answer came back. Nothing to mark,
              and the outcome the transcript already recorded is the one that
              counts. *)
           ());
      Drawn_changed
  | Keeper_msg (Keeper_chat_dispatch_blocked (request, detail)) ->
      (* The POST never left. Nothing durable was written for it, so there is
         nothing to reconcile: say what happened and let the operator send
         again if they want to. *)
      if recover_failed_keeper_preflight state request then begin
        report_action state "error"
          (Printf.sprintf "Keeper request %s was not dispatched: %s"
             request.request_id detail);
        Masc_tui_chat_dispatch.Chat_watching.launch_keeper_waiting_load ~change:(Waiting_keepers [request.Keeper_chat.keeper_name]) state ~mailbox
      end;
      Drawn_changed
  | Context_msg answer -> Context_results.apply state answer; Drawn_changed
  | Keeper_msg (Keeper_chat_copy_loaded (generation, _, _)) when generation <> state.msg_copy_generation -> Drawn_changed
  | Keeper_msg (Keeper_chat_copy_loaded (_, keeper_name, result)) ->
      state.msg_copy_pending <- None;
      let notice = Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:(Some keeper_name) in
      (match result with
       | Error detail ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ("/copy could not read chat history: " ^ detail)
       | Ok { Keeper_chat_history.rows; dropped } ->
           (* Direct and autonomous rows arrive from separate stores. Their
              turn sequence orders two recorded turns; otherwise use the
              display clock and keep append order on an exact tie. Unreadable
              rows arrive only as [dropped]: the newest readable reply may not
              be the newest reply, so the notice says what the history pane's
              banner says rather than reporting a partial read as the latest. *)
           let newer (row : Keeper_chat_history.row) prior =
             match row.turn_sequence, prior.Keeper_chat_history.turn_sequence with
             | Some current, Some previous when current <> previous ->
                 current > previous
             | _ -> row.at >= prior.at
           in
           let newest =
             List.fold_left
               (fun selected (row : Keeper_chat_history.row) ->
                 match row.kind with
                 | Keeper_chat_history.Said_by_keeper
                 | Keeper_chat_history.Autonomous_reply
                   when row.text <> "" ->
                     (match selected with
                      | None -> Some row
                      | Some prior when newer row prior -> Some row
                      | Some _ -> selected)
                 | Keeper_chat_history.Addressed_to_keeper _
                 | Keeper_chat_history.Delivery_failed _
                 | Keeper_chat_history.Tool_calls _
                 | Keeper_chat_history.Skill_activity _
                 | Keeper_chat_history.Reasoning _
                 | Keeper_chat_history.Gate_activity _
                 | Keeper_chat_history.Memory_activity _
                 | Keeper_chat_history.Fusion_conclusion _
                 | Keeper_chat_history.Said_by_keeper
                 | Keeper_chat_history.Autonomous_reply -> selected)
               None rows
           in
           (match newest with
            | None ->
                let ko = state.ui_language = Lang_ko in
                notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
                  (if dropped > 0 then
                     if ko then
                       Printf.sprintf "/copy: 완료된 응답이 없어요 (저장 기록 %d건 읽기 불가)" dropped
                     else
                       Printf.sprintf "/copy found no completed reply (%s could not be read)"
                         (Masc_tui_message_layout.count_noun dropped "saved row")
                   else
                     if ko then "/copy: 완료된 응답이 없어요"
                     else "/copy found no completed reply")
            | Some row ->
                let ko = state.ui_language = Lang_ko in
                let characters = Masc_tui_message_layout.grapheme_count row.text in
                let outcome = copy_text_out row.text in
                let msg =
                  if ko then
                    let assessment = if dropped > 0 then "최근 읽힌 응답" else "최근 응답" in
                    let unreadable =
                      if dropped > 0 then Printf.sprintf "; 저장 기록 %d건 읽기 불가" dropped
                      else ""
                    in
                    Printf.sprintf "%s의 %s (%d자, %d바이트)을 %s%s"
                      keeper_name assessment characters (String.length row.text)
                      (Masc_tui_clipboard.copy_outcome_text_korean outcome) unreadable
                  else
                    let assessment =
                      if dropped > 0 then "latest readable reply" else "latest reply"
                    in
                    let unreadable =
                      if dropped > 0 then
                        Printf.sprintf "; %s could not be read"
                          (Masc_tui_message_layout.count_noun dropped "saved row")
                      else ""
                    in
                    Printf.sprintf "%s's %s (%d characters, %d bytes): %s%s"
                      keeper_name assessment characters (String.length row.text)
                      (Masc_tui_clipboard.copy_outcome_text outcome) unreadable
                in
                notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply msg));
      Drawn_changed
  | Keeper_msg (Keeper_chat_history_loaded (request, source, result)) ->
      (* The current refresh owns its slots until each has been admitted.
         A collected old result cannot settle a replacement request. *)
      let owned = match state.msg_history_inflight with
        | Some current when current == request -> Keeper_history_read.settle request source
        | Some _ | None -> false in
      if owned then begin
        let generation = Keeper_history_read.generation request in
        let keeper_name = Keeper_history_read.keeper request in
        if generation = state.msg_history_load_generation
           && Option.exists (String.equal keeper_name) state.msg_target_keeper_name then begin
          let prior_sources = match state.msg_loaded_keeper with
            | Some loaded when String.equal loaded keeper_name -> state.msg_loaded_sources
            | Some _ | None -> empty_keeper_chat_sources in
          let prior_history = keeper_chat_history_rows prior_sources.kcs_history in
          state.msg_loaded_keeper <- Some keeper_name;
          (match source with
           | Keeper_history_read.History ->
             let journal_targets = ref [] in
             let history_entries = match result with
              | Ok { Keeper_chat_history.rows; dropped } ->
                 Keeper_history_read.retire_initial_reply request;
                 state.msg_loaded_error <- None;
                 state.msg_loaded_dropped <- dropped;
                 (* The turns this page names that the session does not hold as
                    logs are rebuilt from their journals, reasoning included
                    (RFC-0412 §3.3): the v1 rows carry trace reasoning
                    content-withheld by design. *)
                 if not state.msg_journal_reads_refused then
                   journal_targets :=
                     journal_source_fetch_targets ~keeper_name
                       ~held:(journal_held_keys state keeper_name)
                       ~unavailable:state.msg_journal_unavailable
                       (List.filter_map
                          (fun (row : Keeper_chat_history.row) ->
                            Option.map
                              (fun source -> (source, row.at))
                              (journal_source_of_history row))
                          rows)
                     |> List.map (fun (source, at) ->
                            ( source
                            , at
                            , journal_resume_position state ~keeper_name source ));
                 let fresh = Masc_tui_chat_dispatch.Chat_history_rows.msg_entries_of_history_rows state keeper_name rows in
                 (* The durable outcome and duration of a held turn's calls reach
                    its block through its log's transcript, not through the rows
                    the block replaces. *)
                 enrich_held_logs_from_rows state ~keeper_name fresh;
                 let kept = merge_paged_history ~paged:prior_history ~fresh in
                 (* The first explicit older read asks the server for an exact
                    newest page and its cursor. Display clocks do not locate a
                    file position; a refresh preserves already-issued authority. *)
                 if not (keeper_chat_history_received prior_sources.kcs_history) then (
                   state.msg_older_cursor <- None;
                   state.msg_older_exist <- true);
                 (* Aggregate success does not settle a physical-page failure.
                    Only a successful page read can clear that source error. *)
                 Masc_tui_chat_dispatch.Chat_history_rows.forget_session_rows_the_transcript_holds state keeper_name rows ~fresh;
                 kept
              | Error failure ->
                 (* The transcript is left as it was and the session rows stay: a
                    failed load must not be the reason the pane goes blank. *)
                 state.msg_loaded_error <- Some failure;
                 prior_history
             in
             let history = match result with
               | Ok _ -> Chat_history_received history_entries
               | Error _ -> prior_sources.kcs_history in
             set_keeper_chat_sources state {prior_sources with kcs_history=history};
             Masc_tui_chat_dispatch.Chat_journals.launch_keeper_chat_journal_loads state ~mailbox ~keeper_name !journal_targets;
             Masc_tui_chat_dispatch.Chat_journals.launch_current_autonomous_journals state ~mailbox ~keeper_name;
             Masc_tui_chat_dispatch.Chat_journals.launch_unavailable_journal_operations state ~mailbox ~keeper_name
           | Keeper_history_read.Initial_reply ->
             (match result with
              | Ok { Keeper_chat_history.rows; dropped=_ } ->
                let initial = Masc_tui_chat_dispatch.Chat_history_rows.msg_entries_of_history_rows state keeper_name rows in
                let history = prepend_older_history_page ~older:initial ~held:prior_history in
                (* This is only a partial reply. The full source and physical
                   page retain their own pending/error/cursor authority. *)
                if initial <> [] then
                  let kcs_history = match prior_sources.kcs_history with
                    | Chat_history_received _ -> Chat_history_received history
                    | Chat_history_unread | Chat_history_partial _ -> Chat_history_partial history in
                  set_keeper_chat_sources state {prior_sources with kcs_history}
              | Error failure ->
                Log.Transport.debug "keeper initial reply unavailable for %s: %s" keeper_name
                  (request_failure_text ~ko:false ~request:Kept_request.Keeper_reply_read failure))
           | Keeper_history_read.Memory ->
             let memory_entries = match result with
               | Ok { Keeper_chat_history.rows; dropped } ->
                   state.msg_memory_error <- None;
                   state.msg_memory_dropped <- dropped;
                   Masc_tui_chat_dispatch.Chat_history_rows.msg_entries_of_history_rows state keeper_name rows
               | Error failure ->
                   state.msg_memory_error <- Some failure;
                   prior_sources.kcs_memory in
             set_keeper_chat_sources state {prior_sources with kcs_memory=memory_entries});
          (* Once both answers of this read are applied, the owed record
             moves: a failure of either is retried with the streams'
             reconnect backoff, since nothing else reads this pane again
             (RFC-0480 §3.1). *)
          if not (Keeper_history_read.sources_pending request) then
            update_history_owed state ~keeper_name
              (match state.msg_loaded_error, state.msg_memory_error with
               | None, None -> Masc_tui_owed_read.succeeded
               | Some _, (Some _ | None) | None, Some _ ->
                   Masc_tui_owed_read.failed ~retry_s:Masc_tui_transport.Event_streams.stream_reconnect_s
                     ~max_retry_s:keeper_execute_stream_max_reconnect_s
                     ~now:(Masc_tui_wake.Mono.now ()))
        end;
        (* Full-history admission can retire the optional slot above. Check
           after admission so an unneeded late reply cannot strand this read. *)
        if not (Keeper_history_read.pending request) then
          match state.msg_history_inflight with
          | Some current when current == request -> state.msg_history_inflight <- None
          | Some _ | None -> ()
      end;
      Drawn_changed
  | Keeper_msg (Keeper_chat_first_page_loaded (request, result)) ->
      let owned = match state.msg_history_inflight with
        | Some current when current == request -> Keeper_history_read.settle_page request
        | Some _ | None -> false in
      if owned then begin
        if not (Keeper_history_read.pending request) then state.msg_history_inflight <- None;
        let keeper_name = Keeper_history_read.keeper request in
        if Keeper_history_read.generation request = state.msg_history_load_generation
           && Option.exists (String.equal keeper_name) state.msg_target_keeper_name then begin
          state.msg_older_loading <- false;
          match result with
          | Error failure ->
              state.msg_older_error <- Some failure
          | Ok page ->
              let sources = if state.msg_loaded_keeper = Some keeper_name
                then state.msg_loaded_sources else empty_keeper_chat_sources in
              let rows = Masc_tui_chat_dispatch.Chat_history_rows.msg_entries_of_history_rows state keeper_name page.Keeper_chat_history.decoded.rows in
              let held = keeper_chat_history_rows sources.kcs_history in
              (* Keep the aggregate's copy if it arrived first. Physical-page
                 and role-filtered windows can contain different identities. *)
              let history = prepend_older_history_page ~older:rows ~held in
              set_keeper_chat_sources state {sources with kcs_history=Chat_history_received history};
              state.msg_loaded_keeper <- Some keeper_name;
              state.msg_older_cursor <- page.Keeper_chat_history.next_cursor;
              state.msg_older_exist <- page.Keeper_chat_history.has_more
                && Option.is_some page.Keeper_chat_history.next_cursor;
              state.msg_older_error <- None;
              enrich_held_logs_from_rows state ~keeper_name rows;
              let journal_targets = if state.msg_journal_reads_refused then []
                else journal_source_fetch_targets ~keeper_name
                  ~held:(journal_held_keys state keeper_name)
                  ~unavailable:state.msg_journal_unavailable
                  (List.filter_map (fun (row : Keeper_chat_history.row) ->
                    Option.map (fun source -> source, row.at) (journal_source_of_history row))
                    page.Keeper_chat_history.decoded.rows)
                  |> List.map (fun (source, at) -> source, at,
                      journal_resume_position state ~keeper_name source) in
              Masc_tui_chat_dispatch.Chat_journals.launch_keeper_chat_journal_loads state ~mailbox ~keeper_name journal_targets;
              Masc_tui_chat_dispatch.Chat_journals.launch_current_autonomous_journals state ~mailbox ~keeper_name;
              Masc_tui_chat_dispatch.Chat_journals.launch_unavailable_journal_operations state ~mailbox ~keeper_name
        end
      end;
      Drawn_changed
  | Keeper_msg (Keeper_chat_operation_loaded {keeper_name; operation_id; operation_state}) ->
      journal_read_finished state (keeper_name, Keeper_chat_log.Operation operation_id);
      Option.iter (fun log ->
        Masc_tui_chat_dispatch.Chat_journals.apply_keeper_chat_operation_state state ~journal_id:operation_id log
          (Result.map Option.some operation_state))
        (settled_log_for_request state ~keeper_name operation_id);
      Drawn_changed
  | Keeper_msg (Keeper_native_tasks_loaded (keeper_name,result)) ->
      state.msg_native_tasks_inflight <- List.filter (fun (name,_) -> name <> keeper_name) state.msg_native_tasks_inflight;
      state.chat_native_tasks_owed <-
        settle_chat_journal state.chat_native_tasks_owed ~keeper:keeper_name
          ~succeeded:(Result.is_ok result);
      let previous = Option.value ~default:Masc_tui_native_tasks.empty
          (List.assoc_opt keeper_name state.msg_native_tasks) in
      let tasks = match result with
        | Ok tasks -> tasks
        | Error error -> Masc_tui_native_tasks.failed previous error in
      state.msg_native_tasks <- (keeper_name,tasks) :: List.remove_assoc keeper_name state.msg_native_tasks;
      if List.mem keeper_name state.msg_native_tasks_audit_pending then
        launch_keeper_native_tasks_load ~mode:Masc_tui_native_tasks.Audit state ~mailbox ~keeper_name;
      Drawn_changed
  | Keeper_msg (Keeper_child_content_loaded (keeper_name,result)) ->
      state.msg_child_content_inflight <- List.remove_assoc keeper_name state.msg_child_content_inflight;
      state.chat_child_content_owed <-
        settle_chat_journal state.chat_child_content_owed ~keeper:keeper_name
          ~succeeded:(Result.is_ok result);
      let previous = Option.value ~default:Masc_tui_child_content.empty
          (List.assoc_opt keeper_name state.msg_child_content) in
      let snapshots = match result with
        | Ok snapshots -> snapshots
        | Error error -> Masc_tui_child_content.failed previous error in
      state.msg_child_content <- (keeper_name,snapshots) :: List.remove_assoc keeper_name state.msg_child_content;
      if List.mem keeper_name state.msg_child_content_audit_pending then
        launch_keeper_child_content_load ~mode:Masc_tui_child_content.Audit state ~mailbox ~keeper_name;
      Drawn_changed
  | Keeper_msg (Keeper_chat_journal_loaded { keeper_name; source; started_at; turn_state; journal; operation_state; terminal_replay }) -> (
      let journal_id = Keeper_chat_log.source_key source in
      (* Not generation-guarded: a journal is the turn's record whichever
         keeper the pane shows now, and the log is kept per keeper. *)
      (* A stream frame arrived while this read was in flight: the read may
         have stopped short of the line it announced. Decided after the
         result below is folded, so the next read starts past it and a turn
         that just ended asks for nothing. *)
      let read_again () =
        match take_journal_wanted state (keeper_name, source) with
        | Not_wanted -> ()
        | Wanted { highest_seq } -> (
            (* Against the highest seq the frames named: a read that reached
               it has answered them, and the chain ends here rather than with
               one more empty read. *)
            match
              journal_follow_for_source state ~keeper_name ~source
                ~seq:highest_seq ~at:started_at
            with
            | Follow_nothing | Follow_read_after_inflight -> ()
            | Follow_read { started_at; since_seq } ->
                Masc_tui_chat_dispatch.Chat_journals.launch_keeper_chat_journal_loads state ~mailbox ~keeper_name
                  [ (source, started_at, since_seq) ])
      in
      let reconcile_operation log =
        Masc_tui_chat_dispatch.Chat_journals.apply_keeper_chat_operation_state state ~journal_id log operation_state
      in
      (* The operation record remains authoritative when its journal cannot
         be read. Settle the retained transcript before classifying the
         independent journal failure below. *)
      (match journal with
       | Ok _ -> ()
       | Error _ -> Option.iter reconcile_operation
           (settled_log_for_source state ~keeper_name source));
      (match receive_journal_result state ~keeper_name ~source ~started_at journal with
      | Ok (log, accepted) ->
          reconcile_operation log;
          record_terminal_replay state log terminal_replay;
          (* An observer-followed turn has no pane-owned delta delivery.
             Refresh its durable results after the journal accepts them;
             replayed seqs and text-only reads do not request another load. *)
          if state.view = Keepers Keeper_message
             && state.msg_tool_visibility <> Tools_compact
             && state.msg_target_keeper_name = Some keeper_name
             && List.exists
                  (function
                    | _, Keeper_chat_live.Tool_result _ -> true
                    | _, ( Keeper_chat_live.Run_started | Keeper_chat_live.Batch_bound _
                         | Keeper_chat_live.Runtime_attempt_started _
                         | Keeper_chat_live.Provider_retry_observed _
                         | Keeper_chat_live.Stream_model_started _
                         | Keeper_chat_live.Model_content_activity _
                         | Keeper_chat_live.Stream_model_stopped _
                         | Keeper_chat_live.Stream_details _ | Keeper_chat_live.Text _ | Keeper_chat_live.Media _
                         | (Keeper_chat_live.Thinking _ | Keeper_chat_live.Thinking_snapshot _)
                         | Keeper_chat_live.Native_tool_started _
                         | Keeper_chat_live.Native_tool_progress _
                         | Keeper_chat_live.Native_tool_ended _
                         | Keeper_chat_live.Tool_started _ | Keeper_chat_live.Tool_admitted _ | Keeper_chat_live.Tool_args _
                         | Keeper_chat_live.Tool_ended _
                         | Keeper_chat_live.Stream_protocol_error _
                         | Keeper_chat_live.Approval_requested _
                         | Keeper_chat_live.Approval_settled _
                         | Keeper_chat_live.Accepted _ | Keeper_chat_live.Checkpoint
                         | Keeper_chat_live.External_effect_completed
                         | Keeper_chat_live.Reply_details _
                         | Keeper_chat_live.Run_failed _ | Keeper_chat_live.Run_finished
                         | Keeper_chat_live.Undecodable _ ) -> false)
                  accepted
          then Masc_tui_work_requests.Schedule_call_requests.launch_keeper_calls_load ~force:true state ~mailbox keeper_name;
          (match state.msg_loaded_keeper with
            | Some loaded_keeper when String.equal loaded_keeper keeper_name ->
                enrich_held_logs_from_rows ~only:log state ~keeper_name state.msg_loaded
            | Some _ | None -> ())
      | Error (Keeper_chat_log.Unknown_operation | Keeper_chat_log.Journal_pruned | Keeper_chat_log.Journal_missing) ->
          (* Nothing to reload, now or later this session: the v1 rows are
             the turn. *)
          ()
      | Error (Keeper_chat_log.Journal_unsupported_version detail) ->
          add_event state "error"
            (Printf.sprintf "journal for %s has an unsupported version: %s"
               (Keeper_chat.compact_request_id journal_id)
               (Keeper_chat.terminal_safe_text detail))
      | Error (Keeper_chat_log.Journal_unavailable detail) ->
          add_event state "error"
            (Printf.sprintf "journal for %s unavailable: %s"
               (Keeper_chat.compact_request_id journal_id)
               (Keeper_chat.terminal_safe_text detail))
      | Error (Keeper_chat_log.Events_denied detail) ->
          (* The server refused this operation's journal and said why; asking
             again this session gets the same answer. *)
          add_event state "error"
            (Printf.sprintf "journal for %s refused: %s"
               (Keeper_chat.compact_request_id journal_id)
               (Keeper_chat.terminal_safe_text detail))
      | Error (Keeper_chat_log.Events_undecodable detail) ->
          (* A body this build cannot read will not read differently next
             time; the v1 rows stay and this operation is not asked again. *)
          add_event state "error"
            (Printf.sprintf "journal for %s not readable: %s"
               (Keeper_chat.compact_request_id journal_id)
               (Keeper_chat.terminal_safe_text detail))
      | Error (Keeper_chat_log.Cursor_refused _ as refusal) ->
          (* The positions this read held no longer place in the journal: it
             was replaced or shortened while its pages were read. Not
             remembered — the next load starts from the first row, which holds
             no cursor to refuse. *)
          add_event state "error"
            (Printf.sprintf "journal for %s: %s"
               (Keeper_chat.compact_request_id journal_id)
               (Keeper_chat.terminal_safe_text
                  (Keeper_chat_log.events_error_to_string refusal)))
      | Error (Keeper_chat_log.Events_refused detail) ->
          (* This client's credential, not this journal: said once, and no
             journal is asked for again this session. *)
          if not state.msg_journal_reads_refused then begin
            state.msg_journal_reads_refused <- true;
            add_event state "error"
              (Printf.sprintf "journals are not readable with this credential: %s"
                 (Keeper_chat.terminal_safe_text detail))
          end
      | Error (Keeper_chat_log.Events_transport detail) ->
          (* Not remembered: the next load asks again. *)
          add_event state "error"
            (Printf.sprintf "journal for %s not loaded: %s"
               (Keeper_chat.compact_request_id journal_id)
               (Keeper_chat.terminal_safe_text detail))
      | Error (Keeper_chat_log.Events_kept_back notice) ->
          (* Not sent, so not remembered either: the next load asks again. *)
          add_event state "error"
            (notice ^ " · " ^ Keeper_chat.compact_request_id journal_id));
      read_again ();
      (* The chat on screen follows its Keeper's running turn: an answer that
         says the turn still runs asks again, waiting on the server for the
         next row (RFC an-idle-tui-receives-only-changes-it-draws T2). A
         failed read is not chained here; the next turns read on this
         screen starts the journal again. *)
      (match source, turn_state, journal with
       | Keeper_chat_log.Autonomous_turn _, Some Keeper_chat_log.Turn_running, Ok _
         when state.view = Keepers Keeper_message
              && Option.equal String.equal state.msg_target_keeper_name (Some keeper_name) ->
           (match journal_follow_for_source state ~keeper_name ~source ~seq:None ~at:started_at with
            | Follow_nothing | Follow_read_after_inflight -> ()
            | Follow_read { started_at; since_seq } ->
                Masc_tui_chat_dispatch.Chat_journals.launch_keeper_chat_journal_loads ~follow:true state ~mailbox ~keeper_name
                  [ (source, started_at, since_seq) ])
       | Keeper_chat_log.Autonomous_turn _, Some Keeper_chat_log.Turn_running, Ok _
       | Keeper_chat_log.Autonomous_turn _, (Some Keeper_chat_log.Turn_ended | None), Ok _
       | Keeper_chat_log.Autonomous_turn _, _, Error _
       | Keeper_chat_log.Operation _, _, (Ok _ | Error _) -> ()));
      Drawn_changed
  | Tools_msg (Tools_read_loaded (Tools_inventory_loaded { generation; keeper = keeper_name; result })) ->
      let current = Masc_tui_work_requests.Tools_task_requests.settle_tools_read state ~generation Tools_inventory_read in
      let selected_name = Option.map (fun (row : keeper) -> row.k_name) (selected_keeper state) in
      (* An answer for a Keeper no longer selected is dropped below, and the
         Keeper now selected is still owed its read. *)
      if current then
        state.tools_inventory_owed <-
          tools_inventory_owed ~failed:failed_read ~warming:placeholder_read
            (tools_inventory_answer ~selected:selected_name ~answered_for:keeper_name result)
            state.tools_inventory_owed;
      if generation = state.tools_request_generation
         && Option.equal String.equal keeper_name selected_name then (
      match result with
      | Ok snapshot ->
          let selected = tools_skill_reference_for_refresh state ~keeper_name in
          let previous_cursor = state.tools_skill_cursor in
          state.tools_inventory <- Some snapshot;
          state.tools_inventory_keeper <- keeper_name;
          state.tools_error <- None;
          let kept =
            match selected with
            | None -> false
            | Some reference -> (
                match
                  List.find_index (fun profile -> Skill_reference.equal profile.Masc.Tui_decode_tools.esp_reference reference)
                    (tools_skill_profiles state)
                with
                | Some index ->
                    state.tools_skill_cursor <- index;
                    true
                | None -> false)
          in
          Masc_tui_work_requests.Tools_task_requests.normalize_tools_skill_cursor state;
          (* A page read about a Skill the new inventory no longer holds is
             not the page of the Skill now selected. *)
          if not kept then state.tools_skill_focus <- Choosing_skill;
          (* The selection moved under the reader: to another row, or to
             another Skill. Only the Skill list on screen follows; a page
             being read keeps its scroll. *)
          let moved =
            match selected with
            | None -> false
            | Some _ -> (not kept) || state.tools_skill_cursor <> previous_cursor
          in
          if moved && state.view = Tools then
            (match Masc_tui_list_moves.tools_list state with
             | Some Masc_tui_list_moves.Tools_skills ->
                 follow_tools_list state Masc_tui_list_moves.Tools_skills
             | Some Masc_tui_list_moves.Tools_async_requests | None -> ())
      | Error detail ->
          (* The failure is this Keeper's, like a reading. *)
          state.tools_inventory_keeper <- keeper_name;
          state.tools_error <- Some detail);
      Masc_tui_types.tools_inventory_effect state
  | Skill_evidence_loaded (request, key, result) ->
      if Option.exists (fun held -> held == request) state.tools_evidence_request then (
        state.tools_evidence_request <- None;
        state.tools_evidence_reference <- None;
        state.tools_evidence_run_id <- None;
        match result with
        | Error (Request_failed detail) -> report_action state "error" ("Skill evidence lookup failed: " ^ detail)
        | Error (Request_withdrawn refusal) ->
            Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Skill_evidence refusal
        | Ok json -> state.tools_skill_evidence <- Some (key, json));
      Drawn_changed
  | Tools_msg (Tools_read_loaded (Tools_activations_loaded { generation; keeper; result })) ->
      let (_ : bool) = Masc_tui_work_requests.Tools_task_requests.settle_tools_read state ~generation Tools_activations_read in
      let selected_name = Option.map (fun (row : keeper) -> row.k_name) (selected_keeper state) in
      if generation = state.tools_request_generation
         && Option.equal String.equal (Some keeper) selected_name then (
      match result with
      | Ok projection ->
          state.tools_activations <- Some (Activations_read projection);
          state.tools_activations_error <- None;
          state.tools_activations_owed <- Masc_tui_owed_read.succeeded state.tools_activations_owed
      | Error detail ->
          state.tools_activations_error <- Some { taf_keeper = keeper; taf_detail = detail };
          state.tools_activations_owed <- failed_read state.tools_activations_owed);
      Drawn_changed
  | Tools_msg (Tools_read_loaded (Tools_usage_loaded { generation; keeper; result })) ->
      Masc_tui_work_requests.Tools_task_requests.settle_tools_skill_read state ~generation (Tools_usage_read keeper);
      if generation = state.tools_skill_generation then begin
        record_keeper_skill_usage state ~keeper result;
        set_keeper_skill_usage_owed state keeper
          (match result with
           | Ok _ -> Masc_tui_owed_read.succeeded (keeper_skill_usage_owed state keeper)
           | Error _ -> failed_read (keeper_skill_usage_owed state keeper))
      end;
      Drawn_changed
  | Tools_msg (Tools_read_loaded (Tools_catalog_loaded { generation; result })) ->
      Masc_tui_work_requests.Tools_task_requests.settle_tools_skill_read state ~generation Tools_catalog_read;
      if generation = state.tools_skill_generation then (
      match result with
      | Ok catalog ->
          state.skills_catalog <- Some catalog;
          state.skills_catalog_error <- None;
          state.tools_catalog_owed <- Masc_tui_owed_read.succeeded state.tools_catalog_owed
      | Error detail ->
          state.skills_catalog_error <- Some detail;
          state.tools_catalog_owed <- failed_read state.tools_catalog_owed);
      Drawn_changed
  | Tools_msg (Tools_async_detail_loaded (request,result)) ->
      let current = tools_async_detail_current state request in
      complete_tools_async_detail state request result;
      (* A nested manifest the read could not fetch comes back inside an
         [Ok] reading; it is retried like a failed read. *)
      if current then
        state.tools_async_detail_owed <-
          (match result with
           | Ok Masc.Tui_decode_async_request.Absent
           | Ok
               (Masc.Tui_decode_async_request.Observed
                 { Masc.Tui_decode_async_request.nested =
                     ( Masc.Keeper_composition_observation.Absent
                     | Masc.Keeper_composition_observation.Observed _
                     | Masc.Keeper_composition_observation.Stored _ )
                 ; _ }) ->
               Masc_tui_owed_read.succeeded state.tools_async_detail_owed
           | Ok
               (Masc.Tui_decode_async_request.Observed
                 { Masc.Tui_decode_async_request.nested = Masc.Keeper_composition_observation.Invalid _; _ })
           | Error _ -> failed_read state.tools_async_detail_owed);
      Drawn_changed
  | Task_msg (Task_document_prepared (request,result)) ->
      let _,terminal_cols=get_terminal_size () in
      complete_task_document state ~cols:(task_document_columns state ~terminal_cols) request result;
      Drawn_changed
  | Tools_msg (Tools_async_task_body_loaded (request,result)) ->
      let current =
        tools_async_task_request_current state request state.tools_async_task_body_request
          state.tools_async_task_body
      in
      complete_tools_async_task_body state request result;
      if current then
        state.tools_async_task_owed <-
          (match result with
           | Ok _ -> Masc_tui_owed_read.succeeded state.tools_async_task_owed
           | Error _ -> failed_read state.tools_async_task_owed);
      Drawn_changed
  | Tools_msg (Tools_async_task_history_loaded (request,result)) ->
      complete_tools_async_task_history state request result;
      Drawn_changed
  | Tools_msg (Tools_async_observation_loaded (generation, result)) ->
      if apply_tools_async_observation_result state ~generation result then
        state.async_requests_owed <-
          (match result with
           | Ok (Tui_decode.Async_ready _) -> Masc_tui_owed_read.succeeded state.async_requests_owed
           | Ok (Tui_decode.Async_unavailable _) | Error _ -> failed_read state.async_requests_owed);
      Drawn_changed
  | Runtime_msg (Runtime_lane_slots_written (written, replacement_selection, result)) ->
      (* Re-read the list the write changed rather than patching the local
         snapshot: a hand-applied edit and a rejected write look the same on
         screen. Lane edits wait for that re-read
         ([Masc_tui_types.settle_runtime_lane_write]). *)
      let cursor_after = state.runtime_lane_cursor_after_write in
      state.runtime_lane_cursor_after_write <- None;
      Masc_tui_types.settle_runtime_lane_write state ~written result;
      (match result with
       | Ok _receipt ->
           state.runtime_lane_pick <- None;
           state.runtime_lane_replacement_selection <- replacement_selection;
           Option.iter
             (fun row ->
                match written, state.slot_editor with
                | Masc_tui_types.Standalone_lanes_list, _ -> ()
                | Masc_tui_types.Runtime_surface_list, _ ->
                    state.runtime_cursor <- row)
             cursor_after;
           (match written with
            | Masc_tui_types.Runtime_surface_list ->
                Masc_tui_surface_requests.Memory_repository_requests.launch_runtime_surface_load state ~mailbox ~force:true
            | Masc_tui_types.Standalone_lanes_list -> launch_lanes_reread state ~mailbox)
       | Error _ -> ());
      Drawn_changed
  | Runtime_msg (Runtime_catalog_loaded (request,result)) ->
      let admitted = take_runtime_catalog_read state request result in
      Log.Transport.info "tui_runtime_catalog request=%d started_ns=%Ld admitted_ns=%Ld admitted=%b followup=%b"
        (Local_read_order.request_id request.rcr_request) request.rcr_started_ns (Mtime_clock.elapsed_ns ())
        admitted (Local_read_order.has_followup state.runtime_catalog_order);
      if admitted && Local_read_order.has_followup state.runtime_catalog_order then
        Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load state ~mailbox;
      Drawn_changed
  | Runtime_msg (Runtime_assignment_changed (request,status,observed_ns)) ->
      let current = runtime_assignment_current state request in
      if apply_runtime_assignment state request status then begin
        Log.Transport.info "tui_runtime_assignment keeper=%s started_ns=%Ld observed_ns=%Ld admitted_ns=%Ld phase=%s current_origin=%b"
          request.ras_key.ksk_keeper request.ras_started_ns observed_ns (Mtime_clock.elapsed_ns ())
          (runtime_assignment_phase status) current;
        match status with
        | Assignment_checking | Assignment_reading | Assignment_posting _ -> ()
        | Assignment_finished (_,outcome) ->
            let origin = if current then "" else " (" ^ request.ras_key.ksk_base_path ^ ")" in
            report_action state (if runtime_assignment_needs_attention outcome then "error" else "system")
              (request.ras_key.ksk_keeper ^ origin ^ runtime_assignment_transition status request
                ^ " · " ^ runtime_assignment_outcome_detail outcome);
            if current then match outcome with
              | Assignment_answered _ | Assignment_conflict _ | Assignment_unconfirmed _ ->
                  Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load ~intent:Snapshot_read.Refresh state ~mailbox
              | Assignment_not_sent _ | Assignment_refused _ -> ()
      end;
      Drawn_changed
  | Browser_msg (Browser_history_list_loaded (generation, result)) ->
      (match state.browser_history with
       | Some history when generation=state.browser_history_generation ->
         (match result with
          | Error (Request_failed detail) -> state.browser_history <- Some {history with content=List_failed detail}
          | Error (Request_withdrawn refusal) ->
              state.browser_history <- Some {history with content=List_kept_back
                (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                   ~request:Kept_request.Browser_history_read refusal)}
          | Ok snapshot when snapshot.kcs_keeper <> history.keeper_name || snapshot.kcs_mismatched <> 0 ->
              state.browser_history <- Some {history with content=List_failed "Keeper history identity mismatch"}
          | Ok snapshot ->
              let entries = Browser_history.entries snapshot in
              state.browser_history <- Some (Browser_history.select 0 entries history);
              Masc_tui_surface_requests.Lane_browser_requests.launch_browser_history state ~mailbox ~reload:false)
       | _ -> ());
      Drawn_changed
  | Browser_msg (Browser_history_page_loaded (generation, result)) ->
      (match state.browser_history with
       | Some history when generation=state.browser_history_generation ->
           state.browser_history <- Some (Browser_history.accept result history)
       | _ -> ());
      Drawn_changed
  | Browser_msg (Browser_lane_clients_loaded (generation, result)) ->
      (match state.browser_lane with
       | None -> ()
       | Some view ->
           let next, read = match view.load with
             | Loading (_, Discover _) -> Browser_lane_view.accept_clients ~generation result view
             | Idle | No_browser
             | Loading (_, (Read | Screenshot _ | Read_refresh
                 | Scene_read _ | Scene_regions _ | Scene_refresh _ | Scene_scroll _ | Scene_focus _
                 | Scene_click _ | Scene_follow _ | Scene_follow_refresh _
                 | Viewport_refresh _ | Viewport_observed _ | Viewport_pointer _)) | Failed _ ->
               (if generation=state.browser_lane_generation
                then Browser_lane_view.accept_activity result view else view),false in
           state.browser_lane <- Some next;
           if read then Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox Browser_lane_view.Read);
      Drawn_changed
  | Browser_msg (Browser_lane_loaded (generation, result)) ->
      state.browser_lane <- Option.map
        (Browser_lane_view.accept ~generation result) state.browser_lane;
      Drawn_changed
  | Browser_msg (Browser_lane_scene_loaded (generation, result)) ->
      state.browser_lane <- Option.map
        (Browser_lane_view.accept_scene ~generation result) state.browser_lane;
      Drawn_changed
  | Browser_msg (Browser_lane_follow_loaded (generation, result)) ->
      state.browser_lane <- Option.map
        (fun view ->
           match result with
           | Error detail ->
               Browser_lane_view.accept_scene ~generation (Error detail) view
           | Ok (receipt, scene_result) ->
               let guard : Browser_lane_view.navigation_guard = {
                 expected_url = receipt.destination_url;
                 navigation_source = receipt.navigation_source;
               } in
               Browser_lane_view.accept_follow ~generation ~guard scene_result view)
        state.browser_lane;
      Drawn_changed
  | Browser_msg (Browser_lane_screenshot_ready { generation; image_generation; result }) ->
      (match state.browser_lane with
       | None -> ()
       | Some view ->
           let settled, screenshot = Browser_lane_view.accept_screenshot ~generation
               (Result.map fst result) view in
           state.browser_lane <- Some settled;
           (* Any deliberate input cancels the overlay.
              It must not leave the matching browser operation busy forever. *)
           if image_generation = state.image_request_generation
              && Option.is_none state.browser_history
              && Option.is_some (browser_lane_on_screen state) then
             match screenshot, result with
             | Some shot, Ok (_, bytes) ->
                 (* A cadence tick on a static page replays the same pixels.
                    Bytes plus chrome metadata decide sameness, so a mere
                    re-read redraws nothing; [state.browser_viewport] keeps
                    describing exactly what is on screen. *)
                 let unchanged =
                   match state.browser_viewport with
                   | Some (previous, previous_bytes) ->
                       Browser_lane_view.viewport_redraw_is_redundant
                         ~previous ~previous_bytes ~shot ~bytes
                   | None -> false in
                 if unchanged then ()
                 else begin
                   let refuse detail =
                     state.browser_lane <- Some { settled with load = Failed detail }
                   in
                   (match !terminal_draws_images with
                    | Some false -> refuse terminal_draws_no_images
                    | Some true | None ->
                        draw_browser_viewport state shot bytes)
                 end
             | None, (Ok _ | Error _) | Some _, Error _ ->
                 if Option.is_some state.browser_viewport then close_image state);
      Drawn_changed
  | Tools_msg (Tools_volume_gc_reported result) ->
      Masc_tui_surface_requests.Connector_volume_requests.settle_volume_gc state Masc_tui_volume_gc.Report_request result;
      Drawn_changed
  | Tools_msg (Tools_volume_gc_reclaimed (names, result)) ->
      Masc_tui_surface_requests.Connector_volume_requests.settle_volume_gc state (Masc_tui_volume_gc.Reclaim_request names) result;
      Drawn_changed
  | Connectors_msg (Connector_unbind_all_done { keeper_name; results }) ->
      state.connector_unbind_all_inflight <- false;
      List.iter
        (fun ((_, outcome) as result) ->
           let kind =
             match outcome with
             | Masc_tui_connector_unbind.Failed _ | Kept_back _ -> "error"
             | Removed | Rebound | Not_found _ -> "system"
           in
           add_event state kind (Masc_tui_connector_unbind.outcome_line result))
        (Masc_tui_connector_unbind.report_order results);
      report_action state
        (if Masc_tui_connector_unbind.any_failed results
            || Masc_tui_connector_unbind.any_kept_back results then "error"
         else "system")
        (Masc_tui_connector_unbind.summary ~keeper_name results);
      Masc_tui_surface_requests.Connector_volume_requests.reload_connectors_after_write state ~mailbox;
      Drawn_changed
  | Connectors_msg (Connectors_status_loaded (request, snapshot)) ->
      (match receive_connectors_status state request snapshot with
       | None -> ()
       | Some retirement ->
           Masc_tui_surface_requests.Connector_volume_requests.settle_connector_unbind_offers state snapshot;
           Masc_tui_surface_requests.Connector_volume_requests.retire_connector_read state retirement;
           (match retirement with
            | Connector_read.No_retirement -> ()
            | Retire _ -> Masc_tui_surface_requests.Connector_volume_requests.launch_connectors_load state ~mailbox));
      Drawn_changed
  | Connectors_msg (Connectors_loaded (request, read)) ->
      let result = Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.Connector_list_read read in
      (match complete_connectors_read state request result with
       | None -> ()
       | Some completion -> begin
        state.connectors_owed <-
          (match result with
           | Ok _ -> Masc_tui_owed_read.succeeded state.connectors_owed
           | Error _ -> failed_read state.connectors_owed);
        (match completion.Connector_read.follow_up with
         | Connector_read.No_follow_up -> ()
         | Read_after_write -> Masc_tui_surface_requests.Connector_volume_requests.launch_connectors_load state ~mailbox);
        (match result with
        | Ok snapshot -> Masc_tui_surface_requests.Connector_volume_requests.settle_connector_unbind_offers state snapshot
        | Error detail ->
            state.connectors_error <- Some detail;
            let pending = List.rev state.connector_unbind_offer_pending in
            state.connector_unbind_offer_pending <- [];
            state.connector_unbind_offer_origin <- None;
            (* A read the guard stopped is said by its kept-back notice
               alone, never as the offer's failure (RFC §2). *)
            let line keeper_name = match read with
              | Error (Request_withdrawn _) ->
                  Masc_tui_connector_unbind.offer_read_kept_back ~keeper_name ~notice:detail
              | Ok _ | Error (Request_failed _) ->
                  Masc_tui_connector_unbind.offer_read_failed ~keeper_name ~detail in
            List.iter
              (fun keeper_name -> report_action state "error" (line keeper_name))
              pending)
      end);
      Drawn_changed
  | Runtime_msg (Runtime_surface_loaded (generation, result)) ->
      let is_current = generation = state.runtime_surface_generation in
      (match state.runtime_surface_inflight with
       | Some inflight when inflight = generation ->
           state.runtime_surface_inflight <- None
       | Some _ | None -> ());
      if is_current then
        (match result with
         | Ok load ->
             state.runtime_evidence <- Some load.Masc_tui_loader.rsl_evidence;
             let previous_probe =
               Option.bind state.runtime_surface (fun snapshot ->
                   snapshot.Tui_decode.rss_probe)
             in
             let probe, probe_error =
               match load.Masc_tui_loader.rsl_probe with
               | Ok current -> Some current, None
               | Error detail -> previous_probe, Some detail
             in
             (match
                Tui_decode.join_runtime_surface ~probe ~probe_error
                  ~resolved:load.rsl_resolved
              with
              | Ok snapshot ->
                  state.runtime_surface <- Some snapshot;
                  Masc_tui_types.reconcile_slot_editor_selection state;
                  state.runtime_surface_error <- probe_error;
                  Masc_tui_types.runtime_lane_list_reread state
                    ~list:Masc_tui_types.Runtime_surface_list ~generation (Ok ())
              | Error detail ->
                  state.runtime_surface_error <- Some detail;
                  Masc_tui_types.runtime_lane_list_reread state
                    ~list:Masc_tui_types.Runtime_surface_list ~generation
                    (Error (Request_failed detail)))
         | Error (Request_failed detail) ->
             (* The last joined reading remains visible. An authority read or
                decode failure is not an empty lane inventory. *)
             state.runtime_evidence <- Some (Error "runtime history not refreshed; runtime identity read failed");
             state.runtime_surface_error <- Some detail;
             Masc_tui_types.runtime_lane_list_reread state
               ~list:Masc_tui_types.Runtime_surface_list ~generation (Error (Request_failed detail))
         | Error (Request_withdrawn refusal) ->
             (* The read was not sent, so no history was refreshed either;
                both say it was kept back. *)
             let notice = workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                 ~request:Kept_request.Runtime_surface_read refusal in
             state.runtime_evidence <- Some (Error notice);
             state.runtime_surface_error <- Some notice;
             Masc_tui_types.runtime_lane_list_reread state
               ~list:Masc_tui_types.Runtime_surface_list ~generation
               (Error (Request_withdrawn refusal)));
      if is_current && state.runtime_surface_force_pending then begin
        state.runtime_surface_force_pending <- false;
        Masc_tui_surface_requests.Memory_repository_requests.launch_runtime_surface_load state ~mailbox ~force:true
      end;
      Drawn_changed
  | Workspace_msg (Workspace_activity_loaded (request, result)) ->
      apply_workspace_activity_read state request result;
      Drawn_changed
  | Repository_msg (Repositories_loaded result) ->
      state.repositories_inflight <- false;
      (match result with
      | Ok snapshot ->
          state.repositories_owed <- Masc_tui_owed_read.succeeded state.repositories_owed;
          state.repositories <- Some snapshot;
          state.repositories_error <- None
      | Error detail ->
          state.repositories_owed <- failed_read state.repositories_owed;
          state.repositories_error <- Some detail);
      Drawn_changed
  | Memory_msg (Memory_loaded (Fleet_health_read result)) ->
      state.memory_health_inflight <- false;
      state.memory_health_owed <-
        (match result with
         | Ok _ -> Masc_tui_owed_read.succeeded state.memory_health_owed
         | Error _ -> failed_read state.memory_health_owed);
      (match result, state.memory_health with
       (* An answer observed before the one held, rows merged since included,
          says nothing newer and does not replace it. *)
       | Ok snapshot, Some held
         when snapshot.Masc.Tui_decode_memory_health.mhs_generated_at
              < held.Masc.Tui_decode_memory_health.mhs_generated_at -> ()
       | Ok snapshot, (Some _ | None) -> apply_memory_health_snapshot state snapshot
       | Error failure, (Some _ | None) -> state.memory_health_error <- Some failure);
      owe_memory_input_read state;
      Drawn_changed
  | Memory_msg (Memory_loaded ((Row_health_read { keeper; result }
      | Command_health_read { keeper; result }) as reading)) ->
      (match reading with
       | Row_health_read _ -> state.memory_health_inflight <- false
       | Command_health_read _ | Fleet_health_read _ -> ());
      (match reading with
       | Row_health_read _ | Fleet_health_read _ -> ()
       | Command_health_read _ ->
         let notice = Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:(Some keeper) in
         let ko = state.ui_language = Lang_ko in
         let say korean english = if ko then korean else english in
         match result with
         | Error (Request_failed detail) ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (keeper ^ ": " ^ say "상태 " "status " ^ field_failed ~ko ^ " · " ^ detail)
         | Error (Request_withdrawn refusal) ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (workspace_refusal_text ~ko ~request:(Kept_request.Command "/memory status") refusal
              ^ " · " ^ keeper)
         | Ok {mhr_keeper = Row_absent; _} ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (keeper ^ ": " ^ say "메모리 관측 없음" "no memory observation")
         | Ok {mhr_keeper = Row_refused refusal; _} ->
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure
             (keeper ^ ": " ^ say "상태 조회 거절" "status refused" ^ " · " ^ refusal.mkr_reason)
         | Ok {mhr_keeper = Row_present row; mhr_generated_at} ->
           let librarian = row.mkh_librarian in
           let pass = match librarian.mlh_state with
             | None -> say "이번 서버에서 처리 결과 미관측" "no pass observed on this server"
             | Some ending -> memory_pass_text ~ko ending in
           let lag = match Masc_tui_keeper_memory_reading.unread_lag librarian with
             | None -> say "미처리 턴 미관측" "unprocessed turns not observed"
             | Some count ->
               if ko then Printf.sprintf "미처리 %d턴" count
               else Printf.sprintf "%d turns unprocessed" count in
           let measured = match librarian.mlh_measured_at with
             | None -> say "처리 관측 시각 없음" "no pass time observed"
             | Some at ->
               say "처리 관측 " "pass observed "
               ^ span_ago ~ko
                   (Masc_tui_value.Ongoing.since ~now:(Unix.gettimeofday ()) at) in
           let cause = Option.bind librarian.mlh_state
             Masc.Tui_decode_memory_health.memory_librarian_pass_end_cause in
           let admission = Option.map (fun admission ->
             say "명시적 메모리 후보: " "explicit memory candidate: "
             ^ Masc.Keeper_librarian_pending.admission_description admission)
             librarian.mlh_admission_wait in
           let reading_age =
             say "상태 조회 " "status loaded "
             ^ span_ago ~ko
                 (Masc_tui_value.Ongoing.since ~now:(Unix.gettimeofday ()) mhr_generated_at) in
           notice ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply (String.concat " · "
             ([keeper; pass; lag; measured; reading_age] @ Option.to_list cause @ Option.to_list admission)));
      (* The row replaces the Keeper's row in the fleet answer, or removes it
         when the Keeper has none, and the totals are counted again
         (RFC-0487). A row that cannot be merged -- no fleet answer yet, a
         refused row, or a failed read -- owes the fleet. *)
      let merged =
        match state.memory_health, result with
        | Some snapshot,
          Ok { Masc.Tui_decode_memory_health.mhr_generated_at;
               mhr_keeper = Masc.Tui_decode_memory_health.Row_present row } ->
            Masc.Tui_decode_memory_health.with_keeper_row snapshot
              ~generated_at:mhr_generated_at ~keeper_id:keeper (Some row)
        | Some snapshot,
          Ok { Masc.Tui_decode_memory_health.mhr_generated_at;
               mhr_keeper = Masc.Tui_decode_memory_health.Row_absent } ->
            Masc.Tui_decode_memory_health.with_keeper_row snapshot
              ~generated_at:mhr_generated_at ~keeper_id:keeper None
        | Some _,
          Ok { Masc.Tui_decode_memory_health.mhr_keeper = Masc.Tui_decode_memory_health.Row_refused _; _ }
        | None, Ok _
        | (Some _ | None), Error _ -> None
      in
      (match merged, result with
       | Some snapshot, (Ok _ | Error _) ->
           apply_memory_health_snapshot state snapshot;
           (* The input pane shows the selected Keeper's turn records, which
              its push may have been about. *)
           (match selected_memory_keeper state with
            | Some selected
              when String.equal selected.Masc.Tui_decode_memory_health.mkh_keeper_id keeper ->
                owe_memory_input_read state
            | Some _ | None -> ())
       | None, Error failure ->
           state.memory_health_error <- Some failure;
           state.memory_health_owed <- failed_read state.memory_health_owed
       | None, Ok _ -> owe_memory_health_read state);
      Drawn_changed
  | Memory_msg (Memory_input_loaded (request, result)) ->
      (* An answer for a selection already left settles nothing; the read
         of the current selection does. *)
      if Masc_tui_fetched.is_current ~equal:String.equal state.memory_input request then
        state.memory_input_owed <-
          (match result with
           | Ok _ -> Masc_tui_owed_read.succeeded state.memory_input_owed
           | Error _ -> failed_read state.memory_input_owed);
      state.memory_input <-
        Masc_tui_fetched.complete ~equal:String.equal state.memory_input request result;
      Drawn_changed
  | Memory_msg (Memory_world_loaded (request, result)) ->
      (* An answer for a read the workspace has moved past is dropped whole by
         [complete]; a failed refresh keeps the inventory held. *)
      let retry_s = Masc_tui_transport.Event_streams.stream_reconnect_s
      and max_retry_s = keeper_execute_stream_max_reconnect_s
      and now = Masc_tui_wake.Mono.now () in
      state.memory_world <- (match result with
        | Ok inventory ->
            Masc_tui_memory_world.complete ~retry_s ~max_retry_s ~now state.memory_world request
              (Ok inventory)
        | Error (Request_failed detail) ->
            Masc_tui_memory_world.complete ~retry_s ~max_retry_s ~now state.memory_world request
              (Error detail)
        | Error (Request_withdrawn refusal) ->
            Masc_tui_memory_world.withdraw ~retry_s ~max_retry_s ~now state.memory_world request
              (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                 ~request:Kept_request.Memory_world_read refusal));
      Drawn_changed
  | Memory_msg (Memory_facts_loaded (request, result)) ->
      (* A late answer for a browser that closed, or for the keeper the reader
         already left, is dropped whole by [complete]. A failed refresh keeps
         the facts on screen and marks them stale. *)
      if Masc_tui_fetched.is_current ~equal:String.equal state.memory_facts request then
        state.memory_facts_owed <-
          (match result with Ok _ -> Masc_tui_owed_read.succeeded state.memory_facts_owed
           | Error _ -> failed_read state.memory_facts_owed);
      state.memory_facts <-
        Masc_tui_fetched.complete ~equal:String.equal state.memory_facts request result;
      Drawn_changed
  | Repository_msg (Repository_changes_loaded (scope, result)) ->
      if
        state.repository_changes_open
        && Option.equal repository_change_scope_equal
             state.repository_changes_scope (Some scope)
      then
        (match result with
         | Ok snapshot when repository_change_scope_equal snapshot.rcs_scope scope ->
             (* A re-read can shorten or reorder the list under the cursor.
                The cursor follows the path it was on; when that path is gone
                it stays inside the rows read, so the selected row and the
                position in the here row name a row that is drawn. *)
             let paths (rows : Masc.Tui_decode.repository_change list) =
               List.map (fun row -> row.Masc.Tui_decode.rc_path) rows
             in
             state.repository_changes_cursor <-
               Masc_tui_board_selection.reconcile_cursor
                 ~current_ids:
                   (match state.repository_changes with
                    | Some previous -> paths previous.rcs_changes
                    | None -> [])
                 ~cursor:state.repository_changes_cursor
                 ~source:Masc_tui_board_selection.List_cursor
                 ~next_ids:(paths snapshot.rcs_changes);
             state.repository_changes <- Some snapshot;
             state.repository_changes_error <- None
         | Ok _ ->
             state.repository_changes_error <-
               Some "Git changes response belongs to a different workspace"
         | Error detail -> state.repository_changes_error <- Some detail);
      Drawn_changed
  | Repository_msg (Repository_changes_diff_loaded (request, result)) ->
      (* Each response belongs to one request incarnation, not to every open
         pane that happens to name the same relative path. *)
      if state.repository_changes_open
         && request.rdr_generation = state.repository_changes_diff_generation
         && Option.equal repository_change_scope_equal
              state.repository_changes_scope (Some request.rdr_scope)
         && Option.equal String.equal state.repository_changes_diff_path
              (Some request.rdr_path)
      then
        (match result with
         | Ok diff ->
             state.repository_changes_diff <- Some (request.rdr_path, diff);
             state.repository_changes_diff_max_width <- git_diff_body_max_width diff;
             state.repository_changes_diff_hscroll <-
               min state.repository_changes_diff_hscroll
                 (max 0 (state.repository_changes_diff_max_width - 1));
             state.repository_changes_diff_error <- None
         | Error detail -> state.repository_changes_diff_error <- Some detail);
      Drawn_changed
  | Keeper_msg (Keeper_chat_file_changes_loaded (generation, keeper_name, read)) ->
      let result = Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.File_changes_read read in
      let still_current =
        generation = state.msg_file_changes_generation
        && Option.equal String.equal state.msg_file_changes_keeper
             (Some keeper_name)
        && Option.equal String.equal state.msg_target_keeper_name
             (Some keeper_name)
      in
      if still_current then begin
        let refresh_pending = state.msg_file_changes_refresh_pending in
        state.msg_file_changes_loading <- false;
        state.msg_file_changes_refresh_pending <- false;
        (* A read the guard stopped is said by its kept-back notice alone,
           never as the changes being unavailable (RFC §2). *)
        let store_error detail =
          state.msg_file_changes_error <- Some detail;
          add_event state "error" (match read with
            | Error (Request_withdrawn _) -> detail
            | Ok _ | Error (Request_failed _) -> "chat recorded changes unavailable: " ^ detail)
        in
        (match result with
         | Ok snapshot
           when String.equal snapshot.Masc.Tui_decode.fcs_keeper keeper_name ->
             state.msg_file_changes <- Some (keeper_chat_file_changes
               ~scope:(state.workspace_authority, state.workspace_read_authority) snapshot);
             state.msg_file_changes_error <- None
         | Ok snapshot ->
             store_error
               (Printf.sprintf
                  "file-change response named keeper %s, expected %s"
                  snapshot.Masc.Tui_decode.fcs_keeper keeper_name)
        | Error detail -> store_error detail);
        if refresh_pending && state.view = Keepers Keeper_message then
          launch_keeper_chat_file_changes_load ~force:true state ~mailbox
            ~keeper_name
      end;
      Drawn_changed
  | Acting_pane_changes_loaded (request, result) ->
      (* An answer for a keeper the cursor has left is not this tab's
         answer and [complete] drops it. The stamp belongs to an answer
         that landed. *)
      let key = Masc_tui_fetched.request_key request in
      if same_acting_pane_scope key.apk_scope
           (state.workspace_authority, state.workspace_read_authority) then begin
        let result = match result with
          | Ok snapshot when not (String.equal snapshot.Masc.Tui_decode.fcs_keeper key.apk_keeper) ->
              Error (Request_failed (Printf.sprintf "file-change response named keeper %s, expected %s"
                snapshot.fcs_keeper key.apk_keeper))
          | Ok _ | Error _ -> result
        in
        let current =
          Masc_tui_fetched.is_current ~equal:same_acting_pane_key state.acting_pane_changes
            request in
        let followup = current && Option.exists (same_acting_pane_key key)
            state.acting_pane_changes_loss_followup in
        let landed = current && Result.is_ok result
        in
        let result = Result.map (fun snapshot ->
          let snapshot =
            if landed then
              let previous =
                Masc_tui_fetched.view_for ~equal:same_acting_pane_keeper state.acting_pane_changes ~key
              in
              retain_unchanged_acting_pane_changes ~scope:key.apk_scope ~previous snapshot
            else snapshot
          in
          { apr_scope = key.apk_scope; apr_snapshot = snapshot }) result
        in
        state.acting_pane_changes <-
          Masc_tui_fetched.complete ~equal:same_acting_pane_key state.acting_pane_changes
            request result;
        if landed then state.acting_pane_changes_at <- Some (Unix.gettimeofday ());
        if followup then begin
          state.acting_pane_changes_loss_followup <- None;
          match acting_pane_changes_keeper state with
          | Some keeper_name when String.equal keeper_name key.apk_keeper
                                  && server_authority_ready state ->
              state.acting_pane_changes <-
                Masc_tui_fetched.invalidate ~reason:(Request_failed "Observer events were lost")
                  state.acting_pane_changes;
              launch_acting_pane_changes_load ~force:true state ~mailbox ~keeper_name
          | Some _ | None ->
              state.acting_pane_changes <- Masc_tui_fetched.clear state.acting_pane_changes;
              state.acting_pane_changes_at <- None
        end
      end;
      Drawn_changed
  | File_changes_loaded (keeper_name, result) ->
      let result = Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.File_changes_read result in
      (* An answer for a keeper the surface has since left is not this
         surface's answer. Dropping it keeps one keeper's files from being
         drawn under another's name. *)
      if Option.equal String.equal state.changes_keeper (Some keeper_name) then (
        state.changes_inflight <- false;
        match result with
        | Ok snapshot ->
            (* The open row indexes the snapshot it was opened against. A new
               snapshot can hold a different change at the same index, so the
               diff stays open only when the same change still sits there,
               and closes rather than silently changing what it shows. *)
            let same_change_at index =
              match state.changes with
              | None -> false
              | Some _ when index < 0 -> false
              | Some (before : Masc.Tui_decode.file_change_snapshot) -> (
                  match
                    ( List.nth_opt before.fcs_changes index
                    , List.nth_opt snapshot.Masc.Tui_decode.fcs_changes index )
                  with
                  | Some (was : Masc.Tui_decode.file_change), Some (now : Masc.Tui_decode.file_change) ->
                      Float.equal was.fc_at now.fc_at
                      && String.equal was.fc_keeper now.fc_keeper
                      && Option.equal String.equal was.fc_execution_id
                           now.fc_execution_id
                      && was.fc_location = now.fc_location
                  | Some _, None | None, Some _ | None, None -> false)
            in
            let kept_row =
              match state.changes_diff_row with
              | Some index when same_change_at index -> Some index
              | Some _ | None -> None
            in
            state.changes <- Some snapshot;
            state.changes_error <- None;
            (match kept_row with
             | Some index -> state.changes_cursor <- index
             | None ->
                 state.changes_cursor <- 0;
                 state.changes_scroll <- 0;
                 if Option.is_none state.changes_tree_diff_path then
                   state.changes_diff_scroll <- 0);
            state.changes_diff_row <- kept_row;
            (* The tree diff owns its path independently of recorded rows.
               A refreshed list cannot close or reset that retained reader. *)
            if Option.is_none state.changes_tree_diff_path then
              refresh_recorded_diff_bounds state ~reset:(Option.is_none kept_row)
        | Error detail -> state.changes_error <- Some detail);
      Drawn_changed
  | Git_diff_loaded (path, result) ->
      (* An answer for a file the view has since left is not this view's
         answer, and drawing it would put one file's diff under another's
         name. *)
      if Option.equal String.equal state.changes_tree_diff_path (Some path) then (
        match result with
        | Ok diff ->
            state.changes_tree_diff <- Some diff;
            state.changes_diff_max_width <- git_diff_body_max_width diff;
            state.changes_diff_hscroll <-
              min state.changes_diff_hscroll (max 0 (state.changes_diff_max_width - 1));
            state.changes_tree_diff_error <- None
        | Error detail -> state.changes_tree_diff_error <- Some detail);
      Drawn_changed
  | Keeper_msg (Keeper_composite_loaded (authority, keeper_name, result)) ->
      if authority == state.detail_read_authority && server_authority_ready state then begin
        state.keeper_composite_inflight <- None;
        (match result with
        | Ok (lane, secret) ->
            state.keeper_composite <-
              Some { kcr_keeper = keeper_name; kcr_lane = lane; kcr_secret = secret };
            state.keeper_composite_error <- None;
            settle_composite_owed state ~keeper_name Masc_tui_owed_read.succeeded
        | Error detail ->
            (* Keep the previous reading visible. The error says that it is
               stale; clearing it would turn a failed refresh into an empty
               reading. *)
            state.keeper_composite_error <- Some (keeper_name, detail);
            settle_composite_owed state ~keeper_name
              (Masc_tui_owed_read.failed ~retry_s:Masc_tui_transport.Event_streams.stream_reconnect_s
                 ~max_retry_s:keeper_execute_stream_max_reconnect_s
                 ~now:(Masc_tui_wake.Mono.now ())));
        launch_owed_keeper_composite state ~mailbox
      end;
      Drawn_changed
  | Lane_msg (Lane_inventory_loaded (generation, result)) ->
      state.standalone_lanes_inflight <- false;
      state.lanes_owed <-
        (match result with
         | Ok _ -> Masc_tui_owed_read.succeeded state.lanes_owed
         | Error _ -> failed_read state.lanes_owed);
      if generation = state.standalone_lanes_generation then (
        match result with
        | Ok snapshot ->
            replace_lane_inventory state snapshot;
            (match state.runtime_lane_write with
             | Masc_tui_types.Lane_write_rereading (Masc_tui_types.Standalone_lanes_list, answered_at, _receipt)
               when generation > answered_at ->
                 (match state.runtime_lane_replacement_selection, state.slot_editor with
                  | Some (target, previous, next), Some editor
                    when editor.se_target = target && editor.se_selection = Some previous ->
                      state.slot_editor <- Some { editor with se_selection = Some next }
                  | _ -> ());
                 state.runtime_lane_replacement_selection <- None
             | Lane_write_rereading (Runtime_surface_list, _, _) | Lane_write_idle
             | Lane_write_posting | Lane_write_rereading (Standalone_lanes_list, _, _) -> ());
            Masc_tui_types.reconcile_slot_editor_selection state;
            state.standalone_lanes_error <- None;
            (* Reuse the same geometry as key movement after identity retention. *)
            (match selected_inventory_lane state,row_list state with
             | Some _,Some list when state.view = Lanes && state.lanes_mode = Lanes_overview -> list.rl_place state.lanes_cursor
             | None,_ | Some _,(Some _ | None) -> ());
            Masc_tui_types.runtime_lane_list_reread state
              ~list:Masc_tui_types.Standalone_lanes_list ~generation (Ok ())
        | Error failure ->
            state.standalone_lanes_error <- Some (request_failure_text
              ~ko:(state.ui_language = Lang_ko) ~request:Kept_request.Lanes_read failure);
            Masc_tui_types.runtime_lane_list_reread state
              ~list:Masc_tui_types.Standalone_lanes_list ~generation (Error failure));
      if state.standalone_lanes_reread_pending then begin
        state.standalone_lanes_reread_pending <- false;
        launch_lanes_load state ~mailbox
      end;
      Drawn_changed
  | Clients_loaded (generation, result) ->
      state.clients_surface_inflight <- false;
      Masc_tui_types.settle_clients_read state ~now:(Masc_tui_wake.Mono.now ()) result;
      if generation = state.clients_surface_generation then (
        match result with
        | Ok snapshot ->
            state.clients_surface <- Some snapshot;
            state.clients_surface_error <- None;
            (* A refresh may shrink the roster; the cursor has to stay a
               valid row of the snapshot now in state. *)
            state.clients_surface_cursor <-
              max
                0
                (min state.clients_surface_cursor
                   (List.length snapshot.Masc.Tui_decode.cls_clients - 1))
        | Error detail -> state.clients_surface_error <- Some detail);
      Drawn_changed
  | Lane_msg (Lane_runs_loaded (lane, generation, before, result)) ->
      (match state.lanes_mode with
       | Lanes_run_list open_lane | Lanes_run_detail (open_lane, _)
         when Lane_run_identity.equal open_lane lane
           && generation = state.lane_runs_generation
           && state.lane_runs_loading ->
           state.lane_runs_loading <- false;
           (match result with
            | Ok page ->
                let previous = Option.value state.lane_runs ~default:[] in
                let runs = match before with
                  | None -> page.Masc.Tui_decode.lrpg_runs
                  | Some _ -> previous @ page.Masc.Tui_decode.lrpg_runs in
                state.lane_runs <- Some runs;
                state.lane_runs_next <- page.lrpg_next;
                state.lane_runs_total <- page.lrpg_total;
                state.lane_runs_error <- None;
                (match before, state.lanes_mode, page.lrpg_runs with
                 | Some _, Lanes_run_list _, _ :: _ ->
                   state.lane_runs_cursor <- List.length previous;
                   state.lane_runs_scroll <- List.length previous
                 | (Some _, Lanes_run_list _, [])
                 | (Some _, (Lanes_overview | (Lanes_run_detail (_, _) | (Lanes_measurement_detail _ | Lanes_inventory_detail _))), _)
                 | (None, _, _) -> state.lane_runs_cursor <-
                   max 0 (min state.lane_runs_cursor (List.length runs - 1)))
            | Error detail ->
                (* A failed page retains both the rows and its retry cursor.
                   Refresh supersedes every older response by generation. *)
                state.lane_runs_error <- Some detail)
       | Lanes_run_list _ | Lanes_overview | Lanes_run_detail _ | Lanes_measurement_detail _ | Lanes_inventory_detail _ -> ());
      Drawn_changed
  | Lane_msg (Lane_run_detail_loaded (run_id, generation, result)) ->
      (match state.lanes_mode with
       | Lanes_run_detail (_, open_run)
         when generation = state.lane_run_detail_generation
              && String.equal open_run run_id ->
           (match result with
            | Ok detail when String.equal detail.Tui_decode.lrd_run_id run_id ->
                state.lane_run_detail <- Some detail;
                state.lane_run_detail_error <- None
            | Ok _ ->
                state.lane_run_detail_error <-
                  Some "lane run detail response does not match the requested run"
            | Error detail -> state.lane_run_detail_error <- Some detail)
       | Lanes_run_detail _ | Lanes_measurement_detail _ | Lanes_inventory_detail _ | Lanes_overview | Lanes_run_list _ -> ());
      Drawn_changed
  | Measurement_artifact_loaded (sha256, generation, result) ->
      accept_measurement_artifact state ~sha256 ~generation result;
      Drawn_changed
  | Engine_sample_read reading ->
      (* A sample answer is not compared with what is drawn, so it asks for a
         frame like an answer that did change it. *)
      let samples, (_ : Masc_tui_engine_samples.step), report =
        Masc_tui_engine_samples.answered state.engine_samples ~now:(Masc_tui_wake.Mono.now ()) reading
      in
      state.engine_samples <- samples;
      (match report with
       | Masc_tui_engine_samples.Quiet -> ()
       | Masc_tui_engine_samples.Failure_began detail ->
         add_event state "error" (Terminal_text.single_line detail));
      Drawn_changed
  | Overview_loaded result ->
      state.overview_inflight <- false;
      state.overview_owed <-
        (match result with
         | Ok _ -> Masc_tui_owed_read.succeeded state.overview_owed
         | Error _ -> failed_read state.overview_owed);
      Masc_tui_refresh_settlement.Http_dataset_settlement.apply_overview_load state result;
      Drawn_changed
  | Harness_msg (Harness_loaded result) ->
      state.harness_inflight <- false;
      (match result with
      | Ok snapshot ->
          state.harness_owed <- Masc_tui_owed_read.succeeded state.harness_owed;
          state.harness_stale_at <-
            Masc_tui_owed_read.stale_at_to_schedule ~wall_now:(Unix.gettimeofday ())
              (Option.bind snapshot.Masc.Tui_decode.hs_overview (fun overview ->
                 overview.Masc.Tui_decode.hov_stale_at));
          state.harness <- Some snapshot;
          state.harness_error <- None;
          (match state.harness_detail with
           | None -> ()
           | Some (task_id, at) ->
               if not
                    (List.exists
                       (fun verdict ->
                          String.equal verdict.Masc.Tui_decode.hv_task_id task_id
                          && Float.equal verdict.hv_at at)
                       snapshot.Masc.Tui_decode.hs_verdicts)
               then begin
                 state.harness_detail <- None;
                 state.harness_detail_scroll <- 0
               end)
      | Error detail ->
          state.harness_owed <- failed_read state.harness_owed;
          state.harness_error <- Some detail);
      Drawn_changed
  | Fusion_msg (Fusion_runs_loaded (request, result)) ->
      let result = Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.Fusion_read result in
      (match Masc_tui_fusion_updates.runs_loaded state request result with
       | Reread when state.view = Fusion
                     || (state.view = Keepers Keeper_detail && state.detail_tab = Detail_runs) ->
           launch_fusion_runs_load state ~mailbox
       | Applied -> settle_fusion_retry state Masc_tui_fusion_updates.Runs result
       | Reread | Await_observer | Obsolete -> ());
      Drawn_changed
  | Fusion_msg (Fusion_detail_loaded (generation, run_id, result)) ->
      let result = Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.Fusion_read result in
      (match Masc_tui_fusion_updates.detail_loaded state ~generation ~run_id result with
       | Reread when state.view = Fusion ->
           Masc_tui_work_actions.Detail_navigation.launch_fusion_detail_load state ~mailbox ~run_id
       | Applied -> settle_fusion_retry state Masc_tui_fusion_updates.Detail result
       | Reread | Await_observer | Obsolete -> ());
      Drawn_changed
  | Fusion_msg (Fusion_historical_detail_loaded (generation, reference, result)) ->
      let result = Masc_tui_transport.Request_notice.said_read_result state ~request:Kept_request.Fusion_read result in
      (match Masc_tui_fusion_updates.historical_detail_loaded state ~generation ~reference result with
       | Reread when state.view = Fusion ->
           Masc_tui_work_actions.Detail_navigation.launch_fusion_historical_detail_load state ~mailbox ~reference
       | Applied -> settle_fusion_retry state Masc_tui_fusion_updates.Historical result
       | Reread | Await_observer | Obsolete -> ());
      Drawn_changed
  | Fusion_msg (Fusion_launch_options_loaded (generation, result)) ->
      Masc_tui_fusion_updates.launch_options_loaded state ~generation
        ~report:(report_action state "system") result;
      Drawn_changed
  | Fusion_msg (Fusion_launched (generation, result)) ->
      Masc_tui_fusion_updates.launched state ~generation
        ~report:(report_action state "system")
        ~refresh:(fun () -> launch_fusion_runs_load
          ~demand:Masc_tui_fusion_updates.After_change state ~mailbox) result;
      Drawn_changed
  | Memory_msg (Memory_recall_standing_loaded (generation, result)) ->
      Masc_tui_types.finish_memory_recall_standing_read state ~generation
        (match result with
         | Ok reading -> Masc_tui_memory_recall_form.Server_read reading
         | Error detail -> Masc_tui_memory_recall_form.Server_unavailable detail);
      Drawn_changed
  | Verification_msg (Verification_loaded result) ->
      state.verification_inflight <- false;
      if state.verification_refresh_after_inflight then begin
        state.verification_refresh_after_inflight <- false;
        launch_verification_load state ~mailbox
      end else (match result with
      | Ok snapshot ->
          state.verification_owed <- Masc_tui_owed_read.succeeded state.verification_owed;
          state.verification <- Some snapshot;
          state.verification_error <- None;
          let requests = snapshot.Masc.Tui_decode.vs_requests in
          let count = List.length requests in
          if state.verification_cursor >= count then
            state.verification_cursor <- max 0 (count - 1);
          (match state.verification_verdict_armed with
           | Some (task_id, request_id)
             when not
                    (List.exists
                       (fun (row : Masc.Tui_decode.verification_request) ->
                          String.equal row.vr_task_id task_id
                          && String.equal row.vr_request_id request_id)
                       requests) ->
               state.verification_verdict_armed <- None;
               state.verification_verdict_error <-
                 Some (Request_failed (Printf.sprintf
                   "%s: request %s changed or closed; review the refreshed queue"
                   task_id request_id))
           | Some _ | None -> ());
          (match state.verification_detail_request_id with
           | Some request_id
             when not
                    (List.exists
                       (fun row ->
                          String.equal row.Masc.Tui_decode.vr_request_id
                            request_id)
                       requests) ->
               Masc_tui_work_actions.Verification_actions.cancel_verification_evidence_load state
                 ~reason:(Verification_evidence_read.Interrupted "The original verification detail was closed.");
               state.verification_detail_request_id <- None;
               state.verification_detail_scroll <- 0
           | Some _ | None -> ())
      | Error failure ->
          (* The previous list stays: a failed reload must not make the queue
             look empty, which reads as "nothing is waiting". *)
          state.verification_owed <- failed_read state.verification_owed;
          state.verification_error <- Some failure);
      Drawn_changed
  | Local_msg (Local_workspace_read (request, result)) ->
      (match Masc_tui_transport.Local_sources.observe_source state ~source:Local_work
          ~is_observed:Masc_tui_loader.local_workspace_observed request result with
       | None -> ()
       | Some result ->
           (match result with
            | Error detail -> report_action state "error" ("Local work read failed: " ^ detail)
            | Ok reading -> Local_read_observation.apply request.lwr_observation
                (Masc_tui_loader.apply_local_workspace state) reading);
           Masc_tui_transport.Local_sources.launch_followup state ~mailbox Local_work);
      Drawn_changed
  | Local_msg (Local_keepers_read (request, result)) ->
      (match Masc_tui_transport.Local_sources.observe_source state ~source:Local_keepers
          ~is_observed:Masc_tui_loader.local_keepers_observed request result with
       | None -> ()
       | Some result ->
           (match result with
            | Error detail -> report_action state "error" ("Keeper metadata read failed: " ^ detail)
            | Ok reading ->
                Local_read_observation.apply request.lwr_observation
                  (Masc_tui_loader.apply_local_keepers
                     ~before_view_change:(fun () -> retire_remote_image_for_navigation state) state) reading;
                refresh_visible_detail_after_authority_recovery state ~mailbox
                  ~previous_authority:state.detail_read_authority;
                resume_task_followups ~server_contact state ~mailbox ~refresh_inflight:http_refresh_inflight
                  ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup;
                resolve_opening_chat state ~base_path ~mailbox;
                (* Metadata owns this wake; optional work cannot replay it. *)
                Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox;
                ignore (Masc_tui_transport.Local_sources.launch_current_live_context state ~mailbox));
           Masc_tui_transport.Local_sources.launch_followup state ~mailbox Local_keepers);
      Drawn_changed
  | Keeper_msg (Keeper_logs_loaded (request, result)) ->
      let admission = take_keeper_log_read state request result in
      let keeper_name = (Masc_tui_fetched.request_key request.klr_request).klk_keeper in
      (match admission, result with
       | Some _, Ok _ -> settle_logs_owed state ~keeper_name Masc_tui_owed_read.succeeded
       | Some _, Error _ ->
           settle_logs_owed state ~keeper_name
             (Masc_tui_owed_read.failed ~retry_s:Masc_tui_transport.Event_streams.stream_reconnect_s
                ~max_retry_s:keeper_execute_stream_max_reconnect_s ~now:(Masc_tui_wake.Mono.now ()))
       | None, (Ok _ | Error _) ->
           (* A newer read owns the slot and settles the debt itself. When the
              view dropped this one and none replaced it, what it was to read
              is owed again. *)
           if Option.is_none state.keeper_log_read then
             settle_logs_owed state ~keeper_name Masc_tui_owed_read.abandoned);
      log_keeper_log_read ~phase:"observed" request
        ~outcome:(if Option.is_none admission then "discarded" else
          match result with Ok _ -> "received" | Error _ -> "failed");
      Option.iter (fun admitted ->
        let _, cols = Masc_tui_render_prim.get_terminal_size () in
        state.log_scroll <- min state.log_scroll (max 0 (List.length (keeper_log_rows state ~cols) - 1));
        if admitted.kla_followup then ignore (launch_current_keeper_logs state ~mailbox ~intent:Snapshot_read.Join)) admission;
      launch_owed_keeper_logs state ~mailbox;
      Drawn_changed
  | Keeper_msg (Keeper_execute_streamed (stream, event)) ->
      ignore (take_keeper_execute_stream state stream event);
      Drawn_changed
  | Live_context_loaded (request, started_ns, result) ->
      let admitted = take_live_context_observation state request result in
      Masc_tui_transport.Local_sources.log_live_context_read ~phase:"observed" request ~started_ns
        ~outcome:(if not admitted then "discarded" else
          match result with Ok _ -> "received" | Error _ -> "failed");
      Drawn_changed
  | Keeper_msg (Keeper_chat_older_loaded (generation, keeper_name, cursor, result)) ->
      Masc_tui_frame_timing.time_stage ~name:"chat.older.apply" (fun () ->
      (* A page that arrived for a keeper the pane has since left, or after a
         reload moved the cursor, is dropped: prepending it would put rows
         above a transcript they do not belong to. *)
      let still_current =
        generation = state.msg_history_load_generation
        && (match state.msg_loaded_keeper with
            | Some loaded -> String.equal loaded keeper_name
            | None -> false)
        && state.msg_older_cursor = cursor
      in
      if still_current then (
        state.msg_older_loading <- false;
        match result with
        | Ok page ->
            let observation =
              if Masc_tui_frame_timing.enabled then
                Some (Masc_tui_message_input.revision state.msg_input,
                  state.msg_scroll, state.msg_scroll_pin,
                  List.length (keeper_chat_history_rows state.msg_loaded_sources.kcs_history))
              else None
            in
            let journal_targets =
              if state.msg_journal_reads_refused then []
              else journal_source_fetch_targets ~keeper_name
                ~held:(journal_held_keys state keeper_name)
                ~unavailable:state.msg_journal_unavailable
                (List.filter_map (fun (row : Keeper_chat_history.row) ->
                  Option.map (fun source -> source, row.at) (journal_source_of_history row))
                  page.Keeper_chat_history.decoded.rows)
                |> List.map (fun (source, at) -> source, at,
                    journal_resume_position state ~keeper_name source)
            in
            let rows = Masc_tui_frame_timing.time_stage ~name:"chat.older.rows" (fun () ->
              Masc_tui_chat_dispatch.Chat_history_rows.msg_entries_of_history_rows state keeper_name
                page.Keeper_chat_history.decoded.Keeper_chat_history.rows
              )
            in
            (* The paging cursor owns the raw storage window, so an older page
               is prepended here. [chat_timeline] then recomputes the one
               displayed-time projection across that complete window; scroll
               pins retain row identity rather than this cache position. *)
            let held = keeper_chat_history_rows state.msg_loaded_sources.kcs_history in
            let history = Masc_tui_frame_timing.time_stage ~name:"chat.older.merge" (fun () ->
              prepend_older_history_page ~older:rows ~held) in
            set_keeper_chat_sources state {state.msg_loaded_sources with kcs_history=Chat_history_received history};
            (* Loaded rows arrive here too: a held turn whose rows only an
               older page carries gets its calls' outcome and duration the
               same way a refreshed page gives them. *)
            Masc_tui_frame_timing.time_stage ~name:"chat.older.enrich" (fun () ->
              enrich_held_logs_from_rows state ~keeper_name rows);
            state.msg_loaded_dropped <-
              state.msg_loaded_dropped
              + page.Keeper_chat_history.decoded.Keeper_chat_history.dropped;
            state.msg_older_cursor <- page.Keeper_chat_history.next_cursor;
            (* A page with no cursor cannot be paged past even if the server
               says more exist, so both have to hold for the pane to offer
               another. *)
            state.msg_older_exist <-
              page.Keeper_chat_history.has_more
              && Option.is_some page.Keeper_chat_history.next_cursor;
            state.msg_older_error <- None;
            Option.iter (fun (revision, scroll, pin, before_rows) ->
              Masc_tui_frame_timing.note_chat_page_application
                { keeper=keeper_name; generation; page_rows=List.length rows;
                  before_rows; after_rows=List.length history;
                  draft_preserved=Masc_tui_message_input.has_revision state.msg_input revision;
                  scroll_preserved=state.msg_scroll = scroll;
                  pin_preserved=state.msg_scroll_pin == pin }) observation;
            Masc_tui_chat_dispatch.Chat_journals.launch_keeper_chat_journal_loads state ~mailbox ~keeper_name journal_targets;
            Masc_tui_chat_dispatch.Chat_journals.launch_unavailable_journal_operations state ~mailbox ~keeper_name
        | Error Keeper_chat_history.Page_stale ->
            retire_keeper_chat_history state keeper_name;
            launch_keeper_history_load ~load_file_changes:false ~force:true state
              ~mailbox ~keeper_name;
            state.msg_older_error <- Some (Request_failed
              (Keeper_chat_history.page_error_to_string Keeper_chat_history.Page_stale))
        | Error (Keeper_chat_history.Page_read_failed detail) ->
            (* A failed read retains its exact cursor for retry. *)
            state.msg_older_error <- Some (Request_failed detail)));
      Drawn_changed
(* How long one pass of the loop applies queued results before it goes back
   to read a key. Results arrive in bursts (a history page, then a journal
   read for each turn on it), and applying all of them in one pass held a
   keypress behind 30-60ms of work. The rest stay in the mailbox in order and
   are applied on the next pass. About one frame, so the loop comes back to
   the keyboard at frame rate. *)
let async_drain_budget_ns = 4_000_000L

(* The pass computes one deadline from [async_drain_budget_ns] and both drains
   in the pass share it, so the two calls together apply at most one frame of
   queued work. No item starts past the deadline — not even the first — so a
   spent pass retains its delivery round for the next pass. An item that
   starts in budget still runs whole. Collecting the owned results is not an
   item: it moves what is already settled into the round, and the deadline
   is checked again before each collected result is applied. *)
let drain_async_messages ~server_contact ?deadline_ns ?(input_pending = fun () -> false) ?(share_input_pending = fun () -> false) state ~delivery_round ~deferred_share_messages ~deferred_share_sweep ~resource_copy_sweep ~base_path ~http_refresh_inflight
    ~http_scoped_refresh_inflight ~scoped_refresh_followup
    ~frame_presenter ~render_schedule mailbox =
  let progress_changed = Masc_tui_types.drain_http_progress state in
  let server_start_changed =
    Masc_tui_transport.Server_contact.apply_settled_starts server_contact state
      ~on_server_ready:(fun ~host ~port ->
        start_http_refresh ~server_contact state ~host ~port ~intent:Revalidate
          ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight
          ~scoped_refresh_followup ~mailbox)
  in
  (* Asked only with an item in hand, after whatever says one is ready, so
     a spent budget always leaves work behind. That work waits for the next
     pass, which comes at once. Asked with nothing to take, a pass that ran
     past the budget bought one more pass with nothing in it. *)
  let over_budget () =
    match deadline_ns with
    | None -> false
    | Some deadline ->
      let now_ns = Mtime_clock.elapsed_ns () in
      let spent = Int64.compare now_ns deadline >= 0 in
      if spent then
        Masc_tui_wake.Pass.note
          { Masc_tui_wake.reason = Masc_tui_wake.Monotonic Masc_tui_wake.Drain_budget_spent; at_ns = now_ns };
      spent
  in
  let chat_changed = Masc_tui_shell.Preferences.drain_completions state
      ~can_take:(fun () -> not (over_budget ()) && not (input_pending ())) in
  let keeper_preferences_changed = Masc_tui_shell.Preferences.drain_keeper_completions state
      ~can_take:(fun () -> not (over_budget ()) && not (input_pending ())) in
  let settings_reread_changed =
    match state.settings_reread with
    | Reread_due | Reread_settled -> false
    | Reread_running promise ->
        (match Eio.Promise.peek promise with
         | None -> false
         | Some _ when over_budget () -> false
         | Some outcome ->
             state.settings_reread <- Reread_settled;
             (match outcome with
              | Ok (Ok settings) ->
                  let board_sort_before = state.board_sort in
                  let language_before = state.ui_language in
                  Masc_tui_shell.Preferences.apply_stored_picks
                    ~on_midi_soundfont:(fun v -> boot_midi_soundfont := v)
                    ~on_audio_input_device:(fun v -> state.boot_audio_input_device <- v)
                    ~set_table_frame state settings;
                  (* The start-up apply runs before the terminal is taken,
                     and main sends the page then; here it is sent now. *)
                  sync_theme_page state;
                  if state.ui_language <> language_before then begin
                    invalidate_language_cached_views state;
                    refresh_keeper_config_view_if_open state ~mailbox
                  end;
                  (* The server sorts the Board, so an order read here is
                     asked for the way a pick asks for it. *)
                  if state.board_sort <> board_sort_before then
                    start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                      ~port:state.port ~intent:Revalidate
                      ~refresh_inflight:http_refresh_inflight
                      ~scoped_refresh_inflight:http_scoped_refresh_inflight
                      ~scoped_refresh_followup ~mailbox
              | Ok (Error reason) ->
                  report_action state "error"
                    (ui_text state ~ko:("화면 설정을 다시 읽지 못했어요. 이번 세션은 기본값이에요: " ^ reason)
                       ~en:("Screen settings could not be read again; this session stays on the defaults: " ^ reason))
              | Error exn ->
                  report_action state "error"
                    (ui_text state ~ko:("화면 설정을 다시 읽다가 멈췄어요: " ^ Printexc.to_string exn)
                       ~en:("Reading the screen settings again stopped: " ^ Printexc.to_string exn)));
             true)
  in
  let credential_changed =
    let module Preparation = Masc_tui_credential_preparation in
    match Preparation.status state.credential_preparation with
    | Preparation.Not_requested | Preparation.Preparing _ | Preparation.Settled -> false
    | Preparation.Awaiting_ui _ when over_budget () -> false
    | Preparation.Awaiting_ui _ ->
    match Preparation.take_completed state.credential_preparation with
    | None -> false
    | Some completion ->
        (match completion.outcome with
         | Observed outcome ->
             let retry = Masc_tui_credential.outcome_needs_retry outcome in
             Masc_tui_transport.Server_contact.set_credential_retry_pending server_contact retry;
             let announce = match completion.request.purpose with
               | Initial -> true | Workspace_retry -> not retry in
             if announce then Option.iter
               (add_event state (Masc_tui_credential.outcome_level outcome))
               (Masc_tui_credential.outcome_notice outcome)
         | Not_started reason | Unobserved reason ->
             Masc_tui_transport.Server_contact.set_credential_retry_pending server_contact false;
             add_event state "error" reason);
        Log.Transport.routine_lazy (fun () -> Printf.sprintf
          "tui_credential_preparation_applied purpose=%s started_ns=%Ld worker_started_ns=%s observed_ns=%Ld applied_ns=%Ld outcome=%s"
          (match completion.request.purpose with Initial -> "initial" | Workspace_retry -> "workspace_retry")
          completion.request.started_ns
          (match completion.worker_started_ns with None -> "unavailable" | Some ns -> Int64.to_string ns)
          completion.observed_ns (Mtime_clock.elapsed_ns ())
          (match completion.outcome with
           | Observed _ -> "observed" | Not_started _ -> "not_started" | Unobserved _ -> "unobserved"));
        true
  in
  let share_input_sensitive message = message_waits_for_input
    ~resource_read:(fun request ->
      Option.exists (fun pending -> pending.Masc_tui_resource_catalog.owner == request.Masc_tui_resource_catalog.owner)
        state.resource_copy_pending)
    ~recovery_loaded:(fun request ->
      Option.exists (fun pending -> pending.recovery_lookup_owner == request.recovery_lookup_owner)
        state.resource_share_recovery_lookup) message in
  let copy_sweep_complete = ref false in
  let reset_input_sensitive_sweeps () =
    if share_input_pending () then begin
      (match !deferred_share_messages with
       | item :: _ when share_input_sensitive item.message -> deferred_share_sweep := None
       | _ :: _ | [] -> ());
      resource_copy_sweep := None
    end in
  reset_input_sensitive_sweeps ();
  let deferred_is_ready () = match !deferred_share_messages with
    | item :: _ -> not (share_input_sensitive item.message) || not (share_input_pending ())
    | [] -> false in
  let rec loop changed =
    (* The session retains the round across both drains and later passes.
       Identity changes queued when the round starts stay ahead of owned
       facts; later arrivals cannot keep extending that prefix. Collecting the
       finite owned set rechecks the same deadline before its first result. *)
    let ready, next = Delivery_round.take !delivery_round
      ~can_take:(fun () -> not (over_budget ()))
      ~queued:(fun () -> Eio.Stream.length mailbox.Masc_tui_transport.Workspace_admission.notifications)
      ~take_shared:(fun () -> Eio.Stream.take_nonblocking mailbox.Masc_tui_transport.Workspace_admission.notifications)
      ~collect_owned:(fun () ->
        collect_owned_results state @ List.map
          (fun (ready : async_msg Masc_tui_workspace_result.ready) ->
            {ready_at_ns=ready.ready_at_ns;message=ready.message})
          (Masc_tui_workspace_result.take_ready mailbox.Masc_tui_transport.Workspace_admission.workspace_results)) in
    delivery_round := next;
    match ready with
    | None when deferred_is_ready ()
        && (match !deferred_share_messages, !deferred_share_sweep with
            | item :: _, Some held -> item != held
            | _ :: _, None -> true | [], _ -> false)
        && not (over_budget ()) ->
        (* Capture a new finite round before consuming a delayed result so
           already-queued workspace authority is applied first. *)
        deferred_share_sweep := (match !deferred_share_messages with item :: _ -> Some item | [] -> None);
        loop changed
    | None when deferred_is_ready () && not (over_budget ()) ->
        deferred_share_sweep := None;
        (match !deferred_share_messages with
         | item :: rest -> deferred_share_messages := rest; apply_item changed item
         | [] -> loop changed)
    | None when (match state.resource_copy_ready, !resource_copy_sweep with
            | Some copy, Some held -> copy != held
            | Some _, None -> true | None, _ -> false)
        && not (share_input_pending ()) && not (over_budget ()) ->
        (* A fresh finite round also precedes the clipboard side effect. *)
        resource_copy_sweep := state.resource_copy_ready; loop changed
    | None ->
        if (match state.resource_copy_ready, !resource_copy_sweep with
            | Some copy, Some held -> copy == held | None, _ | Some _, None -> false)
           && not (share_input_pending ()) && not (over_budget ())
        then copy_sweep_complete := true;
        state.keeper_creation_waits <- List.filter
          (fun wait -> not (keeper_available_for_new_message state wait.kcw_keeper))
          state.keeper_creation_waits;
        Masc_tui_home.reconcile_home_request_detail state;
        let preparation_changed = Masc_tui_chat_dispatch.Chat_watching.launch_keeper_preparation_load state ~mailbox in
        changed || preparation_changed
    | Some item -> apply_item changed item
  and apply_item changed = function
    | ({ message = msg; _ } as item) when share_input_sensitive msg && share_input_pending () ->
        (* Other workspace observations and operation receipts can progress
           while a share or Board preview waits for input to be classified. *)
        deferred_share_messages := !deferred_share_messages @ [item];
        loop changed
    | { ready_at_ns; message = msg } ->
        let waited_ns = Int64.sub (Mtime_clock.elapsed_ns ()) ready_at_ns in
        if Int64.compare waited_ns Masc_tui_http.slow_report_ns >= 0 then
          Log.Transport.info
            "async result waited %.0f ms before UI application"
            (Masc_tui_http.ms_of_ns waited_ns);
        let image_was_open = state.image_open in
        let machine_was_open = state.msx_open in
        let previous_copy = state.resource_copy_ready in
        let drawn =
          apply_async_message ~server_contact ~input_pending ~image_input_pending:share_input_pending state ~base_path ~http_refresh_inflight
            ~http_scoped_refresh_inflight ~scoped_refresh_followup ~mailbox msg
        in
        if previous_copy != state.resource_copy_ready then begin
          resource_copy_sweep := None; copy_sweep_complete := false
        end;
        (* The image renderer cleared the text screen outside the presenter.
           If an async failure dismisses it, cached unchanged rows must also
           be restored, just as they are after a keyboard dismissal. *)
        if (image_was_open && not state.image_open)
           || (machine_was_open && not state.msx_open) then (
          Frame_presenter.invalidate frame_presenter;
          Render_schedule.request render_schedule Render_schedule.Force);
        (* Only an answer that changed what the screen draws asks for a
           frame (RFC tui-one-screen-grammar §8). *)
        loop (match drawn with Drawn_changed -> true | Drawn_unchanged -> changed)
  in
  let changed = loop (progress_changed || server_start_changed || chat_changed || keeper_preferences_changed || settings_reread_changed || credential_changed) in
  reset_input_sensitive_sweeps ();
  (* One already-retired notice is bounded work.  Do not starve it behind a
     busy mailbox, but let an operator gesture cancel its marker first. *)
  let retired_image_changed =
    if not (share_input_pending ()) then
      announce_retired_skill_image state
    else false in
  let changed = changed || retired_image_changed in
  match state.resource_copy_ready with
  | Some copy when !copy_sweep_complete && not (share_input_pending ()) && not (over_budget ()) ->
    if not (resource_public_copy_is_current state copy) then begin
      state.resource_copy_ready <- None;
      resource_copy_sweep := None;
      report_action state "system" "Public link copy was retired after the report or workspace changed.";
      true
    end else if share_input_pending () then changed
    else begin
      state.resource_copy_ready <- None;
      resource_copy_sweep := None;
      let outcome = copy_text_out copy.public_copy_url in
      Terminal_write_repair.request_repaint render_schedule;
      report_action state "system"
        (if state.ui_language = Lang_ko then
           "공개 링크를 " ^ Masc_tui_clipboard.copy_outcome_text_korean outcome ^ " · 원본 연결은 미확인"
         else
           "Public link " ^ Masc_tui_clipboard.copy_outcome_text outcome
           ^ "; origin reachability unconfirmed");
      true
    end
  | Some _ | None -> changed

let copy_reference render_schedule reference =
  let outcome = copy_text_out reference in
  Masc_tui_shell.Terminal_session.request_console_write_repair render_schedule;
  outcome

(** Main loop *)
let main
    ({ Masc_tui_shell.Bootstrap.base_path; workspace; port;
       reasoning_visibility; tool_visibility }) () =
  (* The provider layer reports through [Llm_provider.Diag], whose default sink
     writes to stderr -- which here is the terminal this draws on. One INFO line
     about the embedded model catalog lands between two frames and the screen is
     no longer what the frame presenter believes it wrote. The server routes
     these into the structured log at boot; this surface has the same terminal
     to protect, so it routes them the same way and before anything can ask the
     catalog a question. *)
  Provider_diag_log_sink.install ();
  (* Publish the path selected by this process before any workspace-backed
     store opens. Otherwise inherited path variables can make the screen read
     local Keeper metadata from a different workspace than its server. *)
  Unix.putenv Env_config_core.base_path_env_key base_path;
  Workspace_utils_backend_setup.cache_resolved_base_path base_path;
  Masc_tui_shell.Bootstrap.require_interactive_terminal ();
  (* stderr is this terminal -- [lsof] on a running surface shows fd 1 and fd 2
     on the same [/dev/ttys*]. Everything that writes there writes into the
     drawn screen: the console mirror behind every [Log] record, this binary's
     own decode reports ([Masc_tui_loader.report]), and anything a library
     prints without asking. Raising the level to Warn narrowed that to fewer
     lines; it did not stop them, and it bought the narrowing by dropping Info
     records from the ring the System logs surface reads.

     So the terminal is taken away from stderr instead. The console is a
     mirror by its own contract -- {!Console_sink} names the file sink and the
     ring authoritative -- and a mirror pointed at a file is still a mirror,
     while one pointed here is a corruption. This runs after
     [require_interactive_terminal] so its refusal still reaches a person, and
     before anything can log. *)
  Masc_tui_shell.Bootstrap.redirect_stderr_off_terminal ~base_path;
  Log.init_from_env ();
  (* The client ring is process-local. Its structured details need their own
     file sink; the server's dashboard and this stderr mirror cannot persist
     them. Keep initialization failure diagnostic and let the surface open. *)
  let observation_store=Masc_tui_observation_store.initialize ~base_path in
  let own_paths = local_workspace_paths_of_base_path base_path in
  (* RFC-0482 §3.1: picks go to the server that also answers them at start.
     Both carry this terminal's own workspace paths, so another workspace's
     server on the port refuses instead of reading or storing its own. *)
  let preference_send change =
    match own_paths with
    | None -> Error (Masc_tui_preference_writer.Not_started "No workspace is open")
    | Some paths ->
        Masc_tui_http.post_tui_preference ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port
          ~base_path:paths.lw_base_path ~masc_root:paths.lw_masc_root change
  in
  let read_settings () =
    match own_paths with
    | None -> Error "No workspace is open"
    | Some paths ->
        Masc_tui_http.fetch_tui_preferences ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port
          ~base_path:paths.lw_base_path ~masc_root:paths.lw_masc_root
  in
  let state =
    create_state ~reasoning_visibility ~tool_visibility ~workspace
      ~local_base_path:base_path ~preference_send ~preference_read:read_settings ~port ()
  in
  state.observation_store <- Result.to_option observation_store;
  state.keeper_outside_reading <- Masc_tui_keeper_axis.outside;
  state.view <- Overview;

  (* Bind the bearer to the workspace actually opened, before any request is
     built -- the settings read below is the first. HTTP workers await this
     original installer, independently of input and UI consumption, so the
     settings read waits for it and the terminal setup does not. *)
  Masc_tui_http.install_credential_preparation state.credential_preparation;
  Masc_tui_transport.Server_contact.launch_credential_preparation state
    ~purpose:Masc_tui_credential_preparation.Initial ~base_path ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port;
  let tui_settings_read = Masc_tui_config.prepare_startup_read
      ~sw:(Eio_context.get_switch_opt ()) ~base_path ~read_settings in

  (* Setup terminal *)
  let terminal_session = Masc_tui_shell.Terminal_session.create () in
  let server_contact = Masc_tui_transport.Server_contact.create () in
  let frame_presenter = Masc_tui_shell.Terminal_session.presenter terminal_session in
  let exit_signals = Masc_tui_shell.Terminal_session.exit_signals terminal_session in
  (* Off unless MASC_TUI_NAV_TRACE names a file (RFC-0485). *)
  let nav_trace = Masc_tui_nav_trace_log.from_environment ~clock:Unix.gettimeofday in
  (* All interaction evidence is committed together after terminal output. *)
  let presented = ref (Presented.initial ~approval:None
      ~presses:Masc_tui_hit.no_zones ~panes:Masc_tui_pane_selection.no_panes
      ~reader:None ~panel_owner:None) in
  let presented_approval_detail reader =
    Option.map (fun viewport -> viewport.adv_presentation)
      (approval_detail_viewport_of_reader reader) in
  let current_approval_detail () =
    let terminal_rows, _ = get_terminal_size () in
    let _, terminal_cols = Masc_tui_ansi.get_terminal_size () in
    match Masc_tui_render.frame_choice state ~terminal_rows ~terminal_cols ~now:(Unix.gettimeofday ()) with
    | `Surface -> Masc_tui_approvals_model.detail_presentation state
    | `Too_small _ | `Play_card _ | `Account_login _ | `Account_server _ | `Palette | `Collab _
    | `Lane_addons _ | `Detail_reading _ | `Keeper_deletions | `Help | `About
    | `Context | `Queue _ | `Agenda | `Answering | `Link | `Client_detail _ -> None in
  let approval_detail_changed () =
    let shown = presented_approval_detail (!presented).reader in
    let current = current_approval_detail () in
    Masc_tui_approvals_model.detail_presentation_changed ~presented:shown ~current
    || (Option.is_some shown && Option.is_some current
        && Approval_authority.authority_changed ~presented:(!presented).approval
             ~candidate:(List.nth_opt (Masc_tui_approvals_model.approval_items state)
               state.approval_cursor)) in
  let move_task_detail offset =
    if not (task_detail_relative_scroll state offset) then
      report_action state "system" "Wait for the Task to appear before scrolling" in
  let move_tools_task offset =
    if not (tools_task_relative_scroll state offset) then
      report_action state "system" "Wait for the Task to appear before scrolling" in
  let presented_peer_owner = ref None in
  let presented_peer_target = ref None in
  let presented_chat_row_actions :
      (workspace_authority * unit ref) Masc_tui_chat_row_actions.t ref =
    ref Masc_tui_chat_row_actions.empty
  in
  let presented_change_authority = ref None in
  let repository_change_context_visible state =
    let terminal_rows, cols = get_terminal_size () in
    let surface_key = match state.repository_changes_diff_path with
      | None -> "repository-changes"
      | Some _ -> "repository-changes-diff" in
    let current = Masc_tui_render_repositories.repository_changes_authority state
        ~surface_key ~terminal_rows ~cols in
    Option.is_some (Frame_presenter.presented_rows frame_presenter)
    && Option.is_some current
    && Option.equal Masc_tui_render_repositories.same_repository_change_authority
         !presented_change_authority current
  in
  (* The left button's gesture from press to release. *)
  let pointer_gesture = ref Masc_tui_pane_selection.Idle in
  (* The snapshot is still applied before terminal ownership, setting-dependent
     output and ordinary key processing. Only independent initialization overlaps
     the original read; a late saved value cannot replace an operator choice. *)
  let snapshot = Eio.Promise.await_exn tui_settings_read.result in
  Masc_tui_shell.Preferences.apply_startup_settings
    ~on_midi_soundfont:(fun v -> boot_midi_soundfont := v)
    ~on_audio_input_device:(fun v -> state.boot_audio_input_device <- v)
    ~set_table_frame state snapshot.settings;
  Log.Transport.routine_lazy (fun () -> Printf.sprintf
    "tui_startup_settings phase=ui_applied started_ns=%Ld reader_entered_ns=%Ld reader_returned_ns=%Ld at_ns=%Ld"
    tui_settings_read.started_ns snapshot.reader_entered_ns snapshot.reader_returned_ns
    (Mtime_clock.elapsed_ns ()));
  Masc_tui_shell.Terminal_session.enter terminal_session;
  let render_schedule = Masc_tui_shell.Terminal_session.create_render_schedule () in
  Masc_tui_shell.Terminal_session.setup_screen terminal_session;
  (* The pick, written to the runtime.toml boot reads it back from. Only a
     commit comes here: a preview is a look at a scheme, not a choice of one,
     and storing every row the cursor passes would make Esc a lie.

     A failure is said out loud. The scheme is already on the screen by the
     time this runs, so silence would let the screen stand as proof it was
     kept, and the reader would find the old one back after a restart with
     nothing having told them. *)
  let store_theme_choice choice =
    Masc_tui_shell.Preferences.store state (Masc.Tui_preference.Theme_chosen choice)
  in

  (* Initial load *)
  (* Local workspace state is loaded only after /health proves that this TUI
     and the server resolve the same canonical base path. *)
  let host = Masc_tui_transport.Workspace_admission.server_peer_host in
  let port = state.port in
  let http_refresh_inflight = ref false in
  let http_scoped_refresh_inflight = ref false in
  let scoped_refresh_followup = ref No_scoped_followup in
  let workspace_results = Masc_tui_workspace_result.create () in
  Option.iter (fun sw -> Eio.Switch.on_release sw (fun () ->
    Masc_tui_workspace_result.close workspace_results)) (Eio_context.get_switch_opt ());
  let async_messages =
    { Masc_tui_transport.Workspace_admission.notifications = Eio.Stream.create 32
    ; workspace_results
    }
  in
  let async_delivery_round = ref Delivery_round.empty in
  let deferred_share_messages = ref [] in
  let deferred_share_sweep = ref None and resource_copy_sweep = ref None in
  let resource_share_dispatch_allowed () =
    let signal_generation = Masc_tui_exit_signals.generation exit_signals in
    let terminal_generation = Masc_tui_shell.Terminal_session.resize_generation terminal_session in
    let admitted = not (Masc_tui_exit_signals.pending_signal exit_signals)
      && not (Masc_tui_shell.Terminal_session.resize_requested terminal_session) in
    fun () -> admitted && not (Masc_tui_exit_signals.pending_signal exit_signals)
      && signal_generation = Masc_tui_exit_signals.generation exit_signals
      && terminal_generation = Masc_tui_shell.Terminal_session.resize_generation terminal_session in
  (* When the last wait for input ended: the pass's own work runs from here
     to the next wait. *)
  let pass_started_ns = ref (Mtime_clock.elapsed_ns ()) in
  (* A frame went out this pass. Launchers that read what it drew run after
     the next wait, so that wait ends at once (RFC tui-idle-wait §3.4). *)
  let frame_drawn = ref false in
  (* One drain deadline for the work between two waits: the post-input drain
     after one wait and the pre-input drain before the next share it, so the
     two apply at most one budget of queued work and the wait itself is never
     counted against it. A key is handled before either drain runs. *)
  let drain_deadline_ns = ref (Int64.add !pass_started_ns async_drain_budget_ns) in
  let presented_surface_reference () =
    match state.view with
    | Approvals -> Option.bind (!presented).approval approval_row_reference
    | Overview | Acting | Metrics | Keepers _ | Lanes | Clients | Board | Planning
    | Schedules
    | Memory | Verification | Harness | Fusion | Repositories | Changes | Connectors
    | Runtime | Config | Resources | Code | Tools | System_logs ->
        selected_surface_reference state
  in
  let edit_code_draft () =
    match Code_results.prepare_draft state with
    | Error detail -> report_action state "error" detail
    | Ok draft ->
      let suffix = Filename.extension (Masc_tui_code_draft.address draft).path in
      let suffix = if String.equal suffix "" then ".txt" else suffix in
      (match Masc_tui_editor.roundtrip ~restore:(fun () -> Masc_tui_shell.Terminal_session.hand_off terminal_session) ~reenter:(fun () -> Masc_tui_shell.Terminal_session.take_back terminal_session)
          ~suffix (Masc_tui_code_draft.text draft) with
       | Error abort -> Masc_tui_shell.Editor_notice.report_abort state ~form:Masc_tui_shell.Editor_notice.Code_draft abort
       | Ok text -> match Code_results.edit_draft state draft text with
         | Ok () -> report_action state "system" "Draft retained in this session; S explicitly saves to the server"
         | Error detail -> report_action state "error" detail)
  in
  let reject_gate_approval (pending : Tui_decode.gate_pending) =
    match Masc_tui_editor.editor_command () with
    | None -> Masc_tui_shell.Editor_notice.report_unset state ~form:Masc_tui_shell.Editor_notice.Gate_rejection
    | Some _ -> (
      let stem = "{\n  \"reason\": \"\"\n}\n" in
      match
        Masc_tui_editor.roundtrip ~restore:(fun () -> Masc_tui_shell.Terminal_session.hand_off terminal_session)
          ~reenter:(fun () -> Masc_tui_shell.Terminal_session.take_back terminal_session) stem
      with
      | Error abort -> Masc_tui_shell.Editor_notice.report_abort state ~form:Masc_tui_shell.Editor_notice.Gate_rejection abort
      | Ok body -> (
        match Yojson.Safe.from_string body with
        | exception Yojson.Json_error error ->
          report_action state "error"
            ("Gate rejection: body is not JSON: " ^ error)
        | `Assoc fields -> (
          match List.assoc_opt "reason" fields with
          | Some (`String reason) when String.trim reason <> "" ->
            Masc_tui_work_requests.Approval_gate_requests.launch_gate_resolve state ~mailbox:async_messages
              ~approval_id:pending.gp_id ~approve:false
              ~reason:(Some (String.trim reason))
          | Some (`String _) | Some _ | None ->
            report_action state "system" "Gate rejection cancelled (empty reason)" )
        | _ ->
          report_action state "error" "Gate rejection: body must be a JSON object"))
  in
  let answer_presented_approval decision =
    match
      Approval_authority.resolve ~presented:(!presented).approval
        ~current:(Masc_tui_approvals_model.approval_items state) decision
    with
    | Approval_authority.Listed { Approval_authority.row = Masc_tui_approvals_model.Operator_row approval; decision } ->
        handle_approval_decision state approval decision
          ~mailbox:async_messages
    | Approval_authority.Listed { Approval_authority.row = Masc_tui_approvals_model.Keeper_tool_row held; decision } ->
        Masc_tui_work_requests.Approval_gate_requests.launch_surface_tool_approval state ~mailbox:async_messages
          ~keeper_name:held.kta_keeper
          ~tool_call_id:held.kta_tool_call_id
          ~approval_id:held.kta_approval_id
          ~allow:(match decision with Confirm -> true | Deny -> false)
    | Approval_authority.Listed { Approval_authority.row = Masc_tui_approvals_model.Gate_row pending; decision = Confirm } ->
        Masc_tui_work_requests.Approval_gate_requests.launch_gate_resolve state ~mailbox:async_messages
          ~approval_id:pending.Tui_decode.gp_id ~approve:true ~reason:None
    | Approval_authority.Listed { Approval_authority.row = Masc_tui_approvals_model.Gate_row pending; decision = Deny } ->
        reject_gate_approval pending
    | Approval_authority.No_row_presented ->
        report_action state "system"
          (ui_text state ~ko:"화면에 결정할 행 없음"
             ~en:"No approval row on screen to decide")
    | Approval_authority.Presented_row_gone ->
        report_action state "system"
          "Approval list changed; review the updated row before deciding"
  in
  let last_visible_rejection ~presented_rows () =
    match state.image_open || state.msx_open, presented_rows with
    | true, (Some _ | None) -> None
    | false, None -> None
    | false, Some rows -> (
        match Masc_tui_ansi.probe_terminal_size () with
        | Some (physical_rows, physical_cols)
          when not (Terminal_write_repair.damage_pending ())
               && not (Masc_tui_shell.Terminal_session.resize_requested terminal_session)
               && (physical_rows, physical_cols) = Masc_tui_ansi.get_terminal_size () ->
            presented_input_rejection ~rows:(List.length rows)
              ~cols:physical_cols (!presented).presses
        | (Some _ | None) -> None)
  in
  let last_visible_quit ~presented_rows () =
    (* The probe runs only past the guards that make it moot: it is a fresh
       ioctl per descriptor, and neither a fullscreen surface nor a missing
       frame leaves anything for it to validate. The probe itself is a pure
       read -- the size cache moves only through [refresh_terminal_size] --
       so skipping the call changes neither cache. *)
    match state.image_open || state.msx_open, presented_rows with
    | true, (Some _ | None) -> None
    | false, None -> None
    | false, Some rows -> (
        match Masc_tui_ansi.probe_terminal_size () with
        | Some (physical_rows, physical_cols)
          when not (Terminal_write_repair.damage_pending ())
               && not (Masc_tui_shell.Terminal_session.resize_requested terminal_session)
               && (physical_rows, physical_cols) = Masc_tui_ansi.get_terminal_size () ->
            presented_quit_confirmation ~rows:(List.length rows)
              ~cols:physical_cols (!presented).presses
        | (Some _ | None) -> None)
  in
  let context_search_owner () =
    let Workspace_authority workspace = state.workspace_authority in
    Option.map (fun keeper -> Presented.{ workspace;
        inspector = state.context_inspector_generation; keeper }) state.context_inspector_keeper
  in
  let panel_owner_matches current_owner =
    Presented.panel_owner_matches !presented ~current_owner
      ~context_search_owner:(context_search_owner ())
  in
  let peer_frame_owner_on_screen ~terminal_rows =
    match Masc_tui_render.frame_choice state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) with
    | `Detail_reading reading -> keeper_peer_frame_owner state reading
    | `Too_small _ | `Play_card _ | `Account_login _ | `Account_server _ | `Palette | `Collab _
    | `Lane_addons _ | `About | `Context | `Keeper_deletions | `Help | `Agenda
    | `Answering | `Queue _ | `Link | `Client_detail _ | `Surface -> None
  in
  let peer_target_on_screen ~terminal_rows ~terminal_cols =
    (* Target identity uses the physical terminal geometry. The reader uses
       the separately reserved content viewport, just as [render] does. *)
    let content_rows, content_cols = Masc_tui_render_prim.get_terminal_size () in
    if state.image_open || state.msx_open
       || (terminal_rows, terminal_cols) <> Masc_tui_ansi.get_terminal_size () then None
    else match Masc_tui_render.frame_choice state ~terminal_rows:content_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) with
    | `Detail_reading reading ->
        (match keeper_peer_target state reading ~terminal_rows ~terminal_cols with
         | None -> None
         | Some target ->
             let _, height = Masc_tui_render_overlays.detail_reading_viewport_at
                 state reading ~terminal_rows:content_rows ~cols:content_cols in
             let width = Masc_tui_render_overlays.detail_reading_action_width content_cols in
             if Masc_tui_detail_reading.section_fully_visible ~width ~height ~index:0 reading
             then Some target else None)
    | `Too_small _ | `Play_card _ | `Account_login _ | `Account_server _ | `Palette | `Collab _
    | `Lane_addons _ | `About | `Context | `Keeper_deletions | `Help | `Agenda
    | `Answering | `Queue _ | `Link | `Client_detail _ | `Surface -> None
  in
  let present_frame frame approval presses panes acting_pane chat_row_actions change_authority
      ~drawn_detail_reading ~drawn_tools_task ~input_pending ~write ~flush reader =
    (* Read once: each call copies the whole screen into a fresh list. *)
    let presented_rows = Frame_presenter.presented_rows frame_presenter in
    let panel_owner =
      if frame.Frame_presenter.compact_frame then None
      else Masc_tui_render.panel_input_owner state
          ~terminal_rows:frame.Frame_presenter.terminal_rows
          ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) in
    let candidate_peer_owner = keeper_peer_drawn_owner state
        ~compact:frame.Frame_presenter.compact_frame ~drawn_reading:drawn_detail_reading in
    let candidate_peer_target = Option.bind candidate_peer_owner (fun _ ->
      peer_target_on_screen ~terminal_rows:frame.Frame_presenter.terminal_rows
        ~terminal_cols:frame.Frame_presenter.terminal_cols) in
    let damaged = Terminal_write_repair.consume_damage () in
    let candidate_rejection = presented_input_rejection
        ~rows:(max 1 frame.Frame_presenter.terminal_rows)
        ~cols:(max 1 frame.Frame_presenter.terminal_cols) presses in
    let rejection_changed = not (Option.equal Masc_tui_action_notice.same_rejection
        (last_visible_rejection ~presented_rows ()) candidate_rejection) in
    let previous_quit =
      if damaged then None else last_visible_quit ~presented_rows ()
    in
    let candidate_quit = presented_quit_confirmation
        ~rows:(max 1 frame.Frame_presenter.terminal_rows)
        ~cols:(max 1 frame.Frame_presenter.terminal_cols) presses in
    let quit_changed = not (Option.equal Masc_tui_action_notice.same_quit
        previous_quit candidate_quit) in
    let owned_reader reader =
      Option.is_some (queue_owner_of_reader reader)
      || Option.is_some (play_card_of_reader reader)
      || Option.is_some (approval_detail_viewport_of_reader reader)
      || Option.is_some panel_owner in
    let owner_changed =
      queue_selection_authority_changed ~presented:(!presented).presses ~candidate:presses
      || queue_owner_authority_changed ~presented:(queue_owner_of_reader (!presented).reader)
           ~candidate:(queue_owner_of_reader reader)
      || ((Option.is_some (queue_owner_of_reader (!presented).reader)
           || Option.is_some (queue_owner_of_reader reader)) && (!presented).panes <> panes)
      || play_owner_authority_changed ~presented:(play_card_of_reader (!presented).reader)
           ~candidate:(play_card_of_reader reader)
      || keeper_peer_frame_owner_changed ~presented:!presented_peer_owner
           ~candidate:candidate_peer_owner
      || not (Option.equal same_keeper_peer_target !presented_peer_target candidate_peer_target)
      || not (Option.equal ( = )
           (approval_detail_viewport_of_reader (!presented).reader)
           (approval_detail_viewport_of_reader reader))
      || Presented.panel_presentation_changed !presented ~current_owner:panel_owner
      || ((damaged || Option.is_none presented_rows)
          && (Option.is_some (!presented).panel_owner
              || Option.is_some !presented_peer_owner || Option.is_some candidate_peer_owner
              || owned_reader (!presented).reader || owned_reader reader))
    in
    let frame =
      match !pointer_gesture with
      | Masc_tui_pane_selection.Selecting selection when not owner_changed ->
          { frame with
            Frame_presenter.lines =
              Masc_tui_pane_selection.highlight selection frame.Frame_presenter.lines }
      | Masc_tui_pane_selection.Selecting _ | Masc_tui_pane_selection.Idle
      | Masc_tui_pane_selection.Pressed _ | Masc_tui_pane_selection.Drag_without_pane -> frame
    in
    let chat_approval =
      if frame.Frame_presenter.compact_frame then None
      else Masc_tui_chat_row_actions.approval chat_row_actions
    in
    let approval_changed =
      Approval_authority.authority_changed
        ~presented:(!presented).approval ~candidate:approval
      || not (Option.equal
          (Masc_tui_chat_row_actions.same_approval ~same_scope:same_acting_pane_scope)
          state.msg_presented_tool_approval chat_approval)
    in
    let presentation_changed = owner_changed || rejection_changed in
    let authority_changed = presentation_changed || quit_changed ||
      approval_changed
      || Option.exists (fun prompt ->
        not (Masc_tui_artifact_share_confirmation.ready prompt.recovery_confirmation))
        state.resource_share_recovery_prompt
    in
    let preset_confirmation_changed = match reader with
      | Some (Preset_detail_scroll { confirmation = Some confirmation; _ }) ->
        preset_confirmation_needs_present state confirmation
      | None | Some (Task_detail _ | Board_read _ | Message_scroll _
        | Schedule_detail_scroll _ | Keeper_detail _ | Keeper_terminal_scroll _ | Keeper_calls _
        | Keeper_logs_scroll _ | Acting _ | Acting_selection _ | Acting_detail_scroll _ | Memory_fact_detail_scroll _
        | Client_detail_scroll _ | Verification_detail_scroll _ | Harness_detail_scroll _
        | Fusion_detail_scroll _ | Runtime_detail_scroll _ | Runtime_params_scroll _
        | System_log_detail_scroll _ | Planning_confirmation_scroll _ | Planning_detail_scroll _
        | Lane_run_detail_scroll _ | Changes_diff_scroll _ | Repository_changes_diff_scroll _
        | Resource_scroll _ | Metrics_scroll _ | Approval_detail_scroll _
        | Link_modal_scroll _ | Play_invite_scroll _ | Voice_scroll _
        | Preset_detail_scroll { confirmation = None; _ } | Keeper_list_scroll _
        | Context_inspector_scroll _
        | Context_inspector_response_scroll _ | Queue_panel_presented _ | Help_presented) -> false in
    let activity_authority_changed =
      not (same_acting_pane_authority state.acting_pane_presented acting_pane)
    in
    let chat_actions_changed =
      not (Masc_tui_chat_row_actions.equal ~same_scope:same_acting_pane_scope
             !presented_chat_row_actions chat_row_actions)
    in
    let change_authority_changed =
      not (Option.equal Masc_tui_render_repositories.same_repository_change_authority
        !presented_change_authority change_authority) in
    let task_detail_needs_present =
      String.equal frame.Frame_presenter.surface_key "task-detail"
      && ((match task_detail_of_reader reader with
           | Some (_, Some (count, height)) ->
             task_detail_viewport_changed state ~count ~height
           | Some (_, None) | None -> Option.is_none (current_task_detail_presented state))
          || (task_detail_following_end state
              && match state.task_detail_id with
                 | None -> false
                 | Some task_id ->
                   let _, terminal_cols = Masc_tui_render_prim.get_terminal_size () in
                   let cols = task_document_columns state ~terminal_cols in
                   not (task_detail_waiting state ~task_id ~cols))) in
    let tools_task_needs_present =
      String.equal frame.Frame_presenter.surface_key "tools"
      && match drawn_tools_task with
         | Some drawn ->
           tools_task_viewport_changed state drawn
           || (tools_task_following_end state
               && not (tools_task_waiting state ~source:drawn.ttf_owner.tto_source
                         ~cols:drawn.ttf_cols))
         | None -> Option.is_some state.tools_task_presented in
    (* Approval, Help, Queue, Play and relationship page ownership can change
       while clipped terminal text stays byte-identical. Those changes force
       presentation. Activity, chat row action and repository change authority
       changes force a full presentation only if a differential draw would
       otherwise do nothing; ordinary async updates stay differential. *)
    let result =
      Frame_presenter.present frame_presenter
        ~invalidate_before:(damaged || authority_changed || preset_confirmation_changed)
        ~force_present:(activity_authority_changed || chat_actions_changed || change_authority_changed
                        || task_detail_needs_present || tools_task_needs_present)
        ~write ~flush frame
    in
    Masc_tui_nav_trace_log.note_screen nav_trace frame;
    Masc_tui_nav_trace_log.note_frame nav_trace
      ~surface:frame.Frame_presenter.surface_key ~result;
    match result with
    | Frame_presenter.Presented _ as frame_result ->
        state.frames_presented <- state.frames_presented + 1;
        Masc_tui_frame_timing.note_presented ~surface:frame.Frame_presenter.surface_key;
        (match task_detail_of_reader reader, state.task_detail_id with
         | Some (offset, Some (count, height)), Some task_id
           when String.equal frame.surface_key "task-detail"
                && not frame.compact_frame ->
           let _, terminal_cols = Masc_tui_render_prim.get_terminal_size () in
           let cols = task_document_columns state ~terminal_cols in
           task_detail_presented_frame state ~task_id ~count ~height ~offset ~cols
         | (Some _ | None), (Some _ | None) -> task_detail_forget_frame state);
        (match drawn_tools_task with
         | Some drawn when String.equal frame.surface_key "tools" && not frame.compact_frame ->
           tools_task_presented_frame state drawn
         | Some _ | None -> tools_task_forget_frame state);
        (match Option.bind reader resource_scroll_position, state.resource_share_recovery_prompt with
         | Some position, Some prompt
           when not frame.Frame_presenter.compact_frame
                && String.equal frame.surface_key "resources"
                && state.view = Resources && state.resource_focus = Right_pane ->
           let terminal_rows, terminal_cols = Masc_tui_render_prim.get_terminal_size () in
           let rows = Masc_tui_types.surface_body_rows state ~terminal_rows in
           let count, height = Masc_tui_render_resources.document_viewport state
             ~rows ~cols:terminal_cols in
           let cols = resource_content_cols state ~cols:terminal_cols in
           let visible = Masc_tui_scroll.Position.offset ~count ~height position = 0
             && Option.exists (Masc_tui_resource_document.recovery_preview_fits ~cols ~height
                  ~requested:prompt.recovery_entry.request.requested)
                  (Masc_tui_resource_document.current state) in
           Masc_tui_artifact_share_confirmation.observe_frame prompt.recovery_confirmation
             ~visible
             ~input_pending:(input_pending ()
               || Masc_tui_shell.Terminal_session.resize_requested terminal_session
               || Masc_tui_exit_signals.pending_signal exit_signals)
         | (Some _ | None), Some prompt ->
           Masc_tui_artifact_share_confirmation.withdraw prompt.recovery_confirmation
         | (Some _ | None), None -> ());
        (match reader with
         | Some (Planning_confirmation_scroll (_, Some confirmation)) ->
             state.goal_confirmation_presented <- Some confirmation
         | Some (Preset_detail_scroll { confirmation = Some confirmation; _ }) ->
             let was_ready = Masc_tui_render_config.preset_confirmation_ready state in
             record_preset_confirmation_frame state confirmation;
             if not was_ready && Masc_tui_render_config.preset_confirmation_ready state then
               Render_schedule.request render_schedule Render_schedule.Input
         | Some (Task_detail _) | None | Some (Board_read _) | Some (Message_scroll _)
         | Some (Schedule_detail_scroll _) | Some (Keeper_detail _) | Some (Keeper_terminal_scroll _)
         | Some (Keeper_calls _)
         | Some (Keeper_logs_scroll _) | Some (Acting _) | Some (Acting_selection (_, _))
         | Some (Acting_detail_scroll _) | Some (Memory_fact_detail_scroll _)
         | Some (Client_detail_scroll _) | Some (Verification_detail_scroll _)
         | Some (Harness_detail_scroll _) | Some (Fusion_detail_scroll _)
         | Some (Runtime_detail_scroll _) | Some (Runtime_params_scroll _)
         | Some (System_log_detail_scroll _) | Some (Planning_confirmation_scroll (_, _))
         | Some (Planning_detail_scroll _) | Some (Lane_run_detail_scroll _)
         | Some (Changes_diff_scroll _) | Some (Repository_changes_diff_scroll _)
         | Some (Resource_scroll _) | Some (Metrics_scroll _) | Some (Approval_detail_scroll _)
         | Some (Link_modal_scroll _)
         | Some (Play_invite_scroll _) | Some (Voice_scroll _) | Some (Preset_detail_scroll _)
         | Some (Keeper_list_scroll _) | Some (Context_inspector_scroll _)
         | Some (Context_inspector_response_scroll _) | Some (Queue_panel_presented _)
         | Some Help_presented -> ());
        (* Include picture writes in the post-output input observation. *)
        Masc_tui_portrait_view.flush frame_result ~write:write_to_terminal;
        if owner_changed then pointer_gesture := Masc_tui_pane_selection.Idle;
        let input_pending = input_pending () in
        presented := Presented.presented !presented ~approval ~presses ~panes ~reader
            ~panel_owner ~owner_changed:(owner_changed || approval_changed) ~input_pending;
        presented_peer_owner := candidate_peer_owner;
        presented_peer_target := candidate_peer_target;
        state.acting_pane_presented <- acting_pane;
        presented_chat_row_actions := chat_row_actions;
        state.msg_presented_tool_approval <- chat_approval;
        presented_change_authority := change_authority;
        state.quit_armed <- Option.map (fun arm ->
            let was_visible = Option.exists (fun previous ->
                Masc_tui_action_notice.same_quit previous arm.qa_confirmation) previous_quit in
            { arm with qa_confirmation =
                Masc_tui_action_notice.quit_presented arm.qa_confirmation
                  ~visible:candidate_quit ~was_visible
                  ~input_pending:(input_pending || Masc_tui_exit_signals.interrupt_pending exit_signals) })
            state.quit_armed;
        Option.iter (fun notice ->
          state.last_action <- Masc_tui_action_notice.presented state.last_action notice
              ~at:(Unix.gettimeofday ()) ~input_pending) candidate_rejection
    | Frame_presenter.Unchanged as unchanged ->
        (* Same text, but a picture may have moved on a step. *)
        Masc_tui_portrait_view.flush unchanged ~write:write_to_terminal
  in
  (* The credential preparation started before the settings read, above. A
     process with no bearer still sees the cause ahead of the symptom: a
     tokenless process cannot dispatch, and cannot reconcile a dispatch an
     authenticated predecessor left behind. *)
  start_http_refresh ~server_contact state ~host ~port ~intent:Revalidate
    ~refresh_inflight:http_refresh_inflight
    ~scoped_refresh_inflight:http_scoped_refresh_inflight
    ~scoped_refresh_followup ~mailbox:async_messages;
  add_event state "system" "TUI started";

  (* Main loop *)
  (* The wall-clock second at which the time text of the last built frame
     next reads differently, [None] when that frame drew none. *)
  let time_redraw_due = ref None in
  let emblem_last_step = ref (Masc_tui_wake.Mono.now ()) in
  (* A datum that is fetched only while its surface is open has nothing to draw
     the moment that surface opens, and waiting out the refresh interval would
     read as "there is nothing here". What is watched is the set of data the
     open surface needs rather than the surface itself, so moving between two
     surfaces that read the same things -- a keeper list and a keeper's detail --
     costs no request. Watching from the loop catches every way the surface can
     change, rather than asking each of the places that change it to remember. *)
  let drawn_needs =
    ref
      (current_surface_needs state)
  in
  let input_reader = create_input_reader () in
  at_exit (fun () -> report_startup_observations input_reader);
  let paste_pause_notified = ref false in
  let paste_quiet_notified = ref false in
  (* The notice this loop last set for a held sequence, kept as the exact
     [last_action] value so clearing it can tell it apart, by identity, from
     any notice set after it. *)
  let csi_pause_notice = ref None in
  let paste_guard_idle_notified = ref false in
  (* The Latin keys a composed Hangul syllable still owes the dispatch. A
     terminal that composes before committing delivers [과] as one key event;
     the command reading below replays each key the operator pressed, one per
     loop turn, so the sequence reaches the dispatch in the order it was
     typed. *)
  let hangul_latin_queue : string Queue.t = Queue.create () in
  let input_unsettled () =
    not (Queue.is_empty hangul_latin_queue)
    || input_reader_has_unsettled_input input_reader
  in
  (* Palette and graphics share one bounded startup probe because both replies
     arrive on the key stream. The probe removes only replies to these exact
     questions and puts every other consumed byte back into this same reader.
     NO_COLOR omits OSC 10/11; the independent graphics query still runs. *)
  let palette_requested = Masc_tui_theme.colors_enabled in
  write_to_terminal (Masc_tui_terminal_probe.query ~palette:palette_requested);
  (* Push any startup theme AFTER sending the palette query so the terminal
     answers OSC 10/11/4 with its own unmodified colors before the startup
     scheme overrides them. Pressing [x] ("Follow terminal") later can then
     restore that genuine observed terminal palette. *)
  sync_theme_page state;
  (* The original child owns stdin/buffer while collecting. The loop may draw
     meanwhile; it installs this exact decoder before ordinary input consumes
     replay or the unread terminal-buffer tail. No finish at early handoff. *)
  prepare_terminal_probe ~sw:(Eio_context.get_switch_opt ())
    ~clock:(Eio_context.get_clock_opt ()) input_reader ~palette_requested;
  let fallback_graphics_protocol = match Sys.getenv_opt "TERM_PROGRAM" with
    | Some "iTerm.app" -> Masc_tui_graphics.ITerm2_protocol
    | Some _ | None -> Masc_tui_graphics.Unsupported_protocol in
  let apply_terminal_observation (observation : Masc_tui_terminal_probe.observation) =
    withdraw_resource_diagram_pending state;
    Masc_tui_theme_choice.record_terminal_palette observation.palette;
    let proto = match observation.graphics with
      | Some Masc_tui_graphics.Supported -> Masc_tui_graphics.Kitty_protocol
      | Some (Masc_tui_graphics.Refused _) | None -> fallback_graphics_protocol in
    if !active_graphics_protocol <> proto then begin
      active_graphics_protocol := proto;
      Masc_tui_msx.set_graphics_protocol proto
    end;
    Masc_tui_msx.set_cell_pixels observation.cell_pixels;
    image_cell_pixels := observation.cell_pixels;
    Masc_tui_portrait_view.set_display
      (Masc_tui_portrait_view.display_of
         ~kitty:(proto = Masc_tui_graphics.Kitty_protocol)
         ~cell_pixels:observation.cell_pixels
         ~colors_enabled:Masc_tui_theme.colors_enabled
         ~projects_colour:
           (match Masc_tui_terminal_palette.stdout_color_level () with
            | Masc_tui_terminal_palette.True_color | Masc_tui_terminal_palette.Ansi256 -> true
            | Masc_tui_terminal_palette.Ansi16 | Masc_tui_terminal_palette.Unknown -> false));
    terminal_draws_images := Some (match proto with
      | Masc_tui_graphics.Kitty_protocol | Masc_tui_graphics.ITerm2_protocol -> true
      | Masc_tui_graphics.Unsupported_protocol -> false);
    Masc_tui_shell.Terminal_session.request_full_repaint terminal_session;
    observe_capabilities_applied input_reader observation in
  (* One original observation owner survives early key handoff and byte-filter
     completion. Late replies update every existing terminal capability consumer. *)
  install_terminal_probe_publisher input_reader ~publish:apply_terminal_observation;

  music_terminal_handoff := Some (fun () ->
    let root = Filename.concat
      (Common.masc_dir_from_base_path ~base_path:state.local_base_path) Common.tui_music_dirname in
    Masc_tui_score.launch_music ~restore:(fun () -> Masc_tui_shell.Terminal_session.restore_for_music terminal_session) ~reenter:(fun () -> Masc_tui_shell.Terminal_session.reenter_from_music terminal_session)
      ~project_root:(Filename.concat root "projects") ~session_root:(Filename.concat root "sessions")
      ~soundfont:!boot_midi_soundfont);
  music_midi_terminal_handoff := Some (fun ~path ->
    let root = Filename.concat
      (Common.masc_dir_from_base_path ~base_path:state.local_base_path) Common.tui_music_dirname in
    Masc_tui_score.launch_midi ~restore:(fun () -> Masc_tui_shell.Terminal_session.restore_for_music terminal_session) ~reenter:(fun () -> Masc_tui_shell.Terminal_session.reenter_from_music terminal_session)
      ~project_root:(Filename.concat root "projects") ~session_root:(Filename.concat root "sessions")
      ~soundfont:!boot_midi_soundfont ~path);
  score_terminal_handoff := Some (fun ~sources ~index ->
    match !active_graphics_protocol, !image_cell_pixels with
    | Masc_tui_graphics.Kitty_protocol, Some ((width, height) as cell_pixels)
      when width > 0 && height > 0 ->
        Masc_tui_score.launch ~restore:(fun () -> Masc_tui_shell.Terminal_session.restore_for_music terminal_session) ~reenter:(fun () -> Masc_tui_shell.Terminal_session.reenter_from_music terminal_session) ~sources ~index ~cell_pixels
          ~soundfont:!boot_midi_soundfont
    | (Masc_tui_graphics.Kitty_protocol, (Some _ | None))
    | (Masc_tui_graphics.ITerm2_protocol | Masc_tui_graphics.Unsupported_protocol), _ ->
        Error "/score requires Kitty graphics and measured terminal cell dimensions (Ghostty, Kitty or WezTerm)");

  (* ── Keeper settings over $EDITOR (#29684) ─────────────────────
     The editor itself is the confirmation step: an exit other than 0
     leaves the settings untouched, so these flows skip Keeper_control's
     arming gate. The terminal handshake around the child is
     [hand_off_terminal] and [take_back_terminal], the pair [suspend] runs
     around Ctrl-Z. *)
  (* An empty object is the honest starting point for a partial patch: the
     config route applies only the fields present in the body, and the TUI
     has no view of the current settings to prefill from -- showing a
     guessed stem would invite an operator to "keep" a value that is not
     the one on disk. *)
  (* runtime.toml edit: $EDITOR over the text the Config surface shows,
     then the server's preview validation; only a preview that passes is
     written. A failed preview keeps the operator's text out of the file
     and puts the validator's words in the session log. *)
  (* From a table row to the line that declares it. The header the source
     pane needs is [models.NAME], quoted when the name carries a dot -- the
     same two spellings the table parser accepts, kept together here so a
     name that parses cannot fail to be found. *)
  let config_models_source_line ~(row : Masc_tui_model_runtime_table.row) rows =
    let bare = "[" ^ Runtime_toml_namespace.(path Models) row.Masc_tui_model_runtime_table.model ^ "]" in
    let quoted = "[" ^ Runtime_toml_namespace.(path Models) ("\"" ^ row.Masc_tui_model_runtime_table.model ^ "\"") ^ "]" in
    let rec scan i = function
      | [] -> None
      | segments :: rest ->
        let text = String.trim (String.concat "" (List.map fst segments)) in
        if String.equal text bare || String.equal text quoted
        then Some i
        else scan (i + 1) rest
    in
    scan 0 rows
  in
  let handle_config_models_open_source () =
    if Option.is_some state.runtime_model_jump then
      report_action state "info" "Loading the selected binding; Esc cancels"
    else match List.nth_opt state.config_models_rows state.config_models_cursor with
    | None -> report_action state "error" "no model row is selected"
    | Some row -> (
      match state.runtime_config_view with
      | None -> report_action state "error" "config not loaded yet; r to reload"
      | Some _ ->
        let source_rows = Masc_tui_types.runtime_config_active_rows state in
        state.config_pane <- Config_runtime;
        state.runtime_config_status_open <- false;
        (* Land a few rows above the header so the section reads as a block
           rather than starting at the top edge. *)
        (match config_models_source_line ~row source_rows with
         | Some i ->
             set_runtime_config_cursor_near state ~direction:1 ~target:i;
             state.config_scroll <- max 0 (i - 3)
         | None -> ());
        add_event state "info"
          (Printf.sprintf "runtime.toml at [models.%s] - e to edit"
             row.Masc_tui_model_runtime_table.model))
  in
  let handle_skill_diagram () =
    if not (tools_keeper_observation_confirmed state) then
      report_action state "error" "Keeper roster is unconfirmed; refresh before opening the Skill diagram"
    else if not (tools_skill_inventory_matches_keeper state
      (Option.map (fun (keeper : keeper) -> keeper.k_name) (selected_keeper state))) then
      report_action state "error" "Skill inventory is not confirmed for the selected Keeper; refresh before opening the diagram"
    else match selected_tools_skill_profile state with
    | None -> report_action state "error" "No published Skill selected"
    | Some profile ->
        (* Split on the declared kind, not on whether a flow arrived: the
           answer to a Normal Skill is where the graphs are. The Skills list
           opens on the Normal group, so Ctrl-O there was the first try and
           used to end on one English line. [f] is the key that moves to a
           Composition. *)
        (match profile.esp_io, profile.esp_flow with
         | Model_orchestrated, (None | Some _) ->
             let compositions =
               List.length
                 (List.filter
                    (fun (candidate : Masc.Tui_decode_tools.effective_skill_profile) ->
                       match candidate.esp_io with
                       | Model_orchestrated -> false
                       | Composition_io _ -> true)
                    (tools_skill_profiles state))
             in
             report_action state "system"
               (if compositions = 0 then
                  ui_text state
                    ~ko:"이 Keeper 에는 Composition Skill 이 없어 Skill 그래프가 없습니다"
                    ~en:"This Keeper has no Composition Skill, so there is no Skill graph"
                else
                  ui_text state
                    ~ko:(Printf.sprintf
                           "Skill 그래프는 Composition Skill %d개에만 있습니다 · f: Composition 선택"
                           compositions)
                    ~en:(Printf.sprintf "Skill graphs exist only for %s · f selects one"
                           (Masc_tui_message_layout.count_noun compositions "Composition Skill")))
         | Composition_io _, None ->
             report_action state "error"
               (ui_text state
                  ~ko:"이 Composition Skill 응답에 실행 그래프가 없습니다; 새로 읽은 뒤 다시 여세요"
                  ~en:"This Composition Skill reading has no execution graph; refresh and open it again")
         | Composition_io _, Some flow ->
             match Masc.Tui_decode_tools.skill_flow_mermaid flow with
             | Error detail -> report_action state "error" detail
             | Ok source ->
                 let notice ~kind text = report_action state
                   (match kind with Masc_tui_collab_queue.Chat_notice.Notice_failure -> "error" | Masc_tui_collab_queue.Chat_notice.Notice_reply -> "system") text in
                 open_preview_image ~skill_reference:profile.esp_reference state ~mailbox:async_messages
                   ~notice ~name:("Declared composition: " ^ profile.esp_name)
                   (Masc_tui_image_requests.Generated (Masc_tui_image_preview.mermaid_source source)))
  in
  let handle_skill_evidence () =
    if not (server_authority_ready state) then
      Masc_tui_transport.Request_notice.report_kept_back state ~request:Kept_request.Skill_evidence workspace_identity_unconfirmed Nothing_kept
    else match selected_tools_skill_profile state with
    | None -> report_action state "error" "no published Skill selected"
    | Some profile ->
        launch_skill_evidence_read state ~mailbox:async_messages profile.esp_reference
  in
  let handle_skill_run delta =
    match selected_tools_skill_profile state, state.tools_skill_evidence with
    | Some profile, Some (key, json)
      when String.equal key (Skill_reference.to_yojson profile.esp_reference |> Yojson.Safe.to_string) ->
      (match Masc.Tui_decode_skill_evidence.decode_skill_evidence json with
       | Error detail -> report_action state "error" detail
       | Ok evidence ->
         (match adjacent_skill_evidence_run state ~reference:profile.esp_reference
            ~selection:evidence.se_composition_selection ~runs:evidence.se_composition_runs ~delta with
          | None -> report_action state "system" "No adjacent original run in retained coverage"
          | Some composition_run_id -> launch_skill_evidence_read ~composition_run_id
              state ~mailbox:async_messages profile.esp_reference))
    | _ -> report_action state "system" "Load this Skill revision's retained evidence first"
  in
  let reconcile_chat_focus () =
    if state.view <> Overview && state.view <> Keepers Keeper_message then
      state.keeper_navigation_open <- false;
    let _, terminal_cols = Masc_tui_ansi.get_terminal_size () in
    let cols = max 1 (terminal_cols - acting_pane_columns state ~terminal_cols) in
    reconcile_keeper_message_focus state ~cols
  in
  let cell_image_redraw_pending = ref false in
  let consume_resize_request () =
    if Masc_tui_shell.Terminal_session.take_resize_request terminal_session then begin
      cell_image_redraw_pending := true;
      withdraw_resource_diagram_pending state;
      state.resource_copy_pending <- None;
      state.resource_copy_ready <- None;
      state.resource_share_recovery_lookup <- None;
      Option.iter (fun prompt -> Masc_tui_artifact_share_confirmation.withdraw prompt.recovery_confirmation)
        state.resource_share_recovery_prompt;
      Masc_tui_shell.Terminal_session.invalidate_frame_for_resize frame_presenter render_schedule
    end
  in
  let make_worker_geometry_current () =
    let module Size = Render_schedule.Terminal_size_cache in
    let generation = Masc_tui_shell.Terminal_session.resize_generation terminal_session in
    fun cached ->
      match Size.verify_for_work ~cached
          ~resize_changed:(fun () -> Masc_tui_shell.Terminal_session.resize_requested terminal_session
            || Masc_tui_shell.Terminal_session.resize_generation terminal_session <> generation)
          ~probe:Masc_tui_ansi.probe_terminal_size with
      | Size.Current -> true
      | Size.Resize_interrupted | Size.Resize_detected -> false
  in
  let share_interrupt_barrier = ref false in
  let run_loop () =
    while true do
      (match poll_terminal_probe input_reader with
       | Probe_installed -> Render_schedule.request render_schedule Render_schedule.Background
       | Probe_pending | Probe_unchanged -> ());
      Masc_tui_shell.Terminal_session.request_console_write_repair render_schedule;
      consume_resize_request ();
      (* A second Ctrl-C while the first still stands ends the session; a lone
         one only says so. The notice is an event rather than a footer line
         because it has to survive the frame the operator is looking at, and
         because the answer to "why did nothing happen" belongs in the log
         they can scroll back to. A terminate signal ends the session
         outright. Both leave through [Break], the exit q takes, so the
         switch release that stops a server this TUI started runs for every
         way out. *)
      let skip_input_after_interrupt = ref false in
      let interrupted_paste =
        match Masc_tui_exit_signals.poll exit_signals with
       | Masc_tui_exit_signals.Quit ->
           Masc_tui_shell.Exit_journal.note
             (match Masc_tui_exit_signals.terminate_signal exit_signals with
              | Some signal -> Masc_tui_exit_reason.Terminate signal
              | None -> Masc_tui_exit_reason.Interrupt);
           raise Masc_tui_shell.Exit_journal.Break
       | (Masc_tui_exit_signals.Interrupt_armed
         | Masc_tui_exit_signals.Interrupt_again) as interrupt ->
           (* A pending MIDI handoff yields to this gesture before the quit
              notice is armed: its cancellation reports its own notice. *)
           withdraw_pending_music_editor state;
           withdraw_pending_image_open state;
           state.board_reader <- Masc_tui_board_reader.withdraw_original_open state.board_reader;
           share_interrupt_barrier := true;
           state.resource_copy_pending <- None;
           state.resource_copy_ready <- None;
           state.resource_share_recovery_lookup <- None;
           Option.iter (fun prompt -> Masc_tui_artifact_share_confirmation.withdraw prompt.recovery_confirmation)
             state.resource_share_recovery_prompt;
           (match paste_phase input_reader, input_holds_incomplete_sequence input_reader with
            | No_paste, false -> ()
            | No_paste, true | Pasting _, (true | false) | Draining_tail _, (true | false) ->
                Masc_tui_shell.Quit_guard.withdraw state);
           (match paste_phase input_reader,
                  input_holds_incomplete_sequence input_reader with
            | Draining_tail tail, _
              when not (paste_can_recover input_reader tail) ->
                Masc_tui_exit_signals.withdraw_interrupt exit_signals;
                report_action state "system" "Paste tail still arriving; waiting for end marker";
                Render_schedule.request render_schedule Render_schedule.Background;
                None
            | Draining_tail _, _ ->
                (* Once the terminal loses its closing marker, stdin has no
                   provenance bit: a later pasted BEL is indistinguishable
                   from the operator's Ctrl-G. This is a force unlock for a
                   stream the operator has observed stop, not an automatic
                   declaration that all paste bytes have arrived. *)
                let recovery_was_rejected =
                  (!presented).recovery = Presented.Rejected_recovery in
                abandon_draining input_reader;
                presented := Presented.clear_recovery !presented;
                Masc_tui_exit_signals.withdraw_interrupt exit_signals;
                skip_input_after_interrupt := true;
                report_action state "system"
                  (if recovery_was_rejected then
                     "Paste input unlocked; recovered paste was not applied"
                   else "Paste input unlocked; confirm only after the terminal stops");
                Render_schedule.request render_schedule Render_schedule.Background;
                None
            | Pasting paste, _ when not (cancel_armed paste) ->
                arm_cancel paste;
                Masc_tui_exit_signals.withdraw_interrupt exit_signals;
                report_action state "system"
                  "Paste end awaited; press Ctrl-C again after bytes stop if the marker is missing";
                Render_schedule.request render_schedule Render_schedule.Background;
                None
            | Pasting paste, _
              when not (paste_can_recover input_reader paste) ->
                Masc_tui_exit_signals.withdraw_interrupt exit_signals;
                report_action state "system"
                  "Paste still arriving; waiting for end marker";
                Render_schedule.request render_schedule Render_schedule.Background;
                None
            | Pasting _, _ ->
                let recovered =
                  recover_paste input_reader
                in
                Masc_tui_exit_signals.withdraw_interrupt exit_signals;
                recovered
            (* Bytes already waiting may finish the held head: a split
               [ESC \[ 2] whose [0 0 ~ first CR second] tail arrived just
               before this Ctrl-C. Cancelling first would type that tail as
               keys, and its CR is Enter. [input_byte_ready] pulls them
               through the probe without waiting; while any are there the
               Ctrl-C only waits, as the paste arms do, and the loop reads
               them now. *)
            | No_paste, true when input_byte_ready input_reader ->
                Masc_tui_exit_signals.withdraw_interrupt exit_signals;
                report_action state "system"
                  "Terminal sequence still arriving; Ctrl-C again after it stops";
                Render_schedule.request render_schedule Render_schedule.Background;
                None
            | No_paste, true ->
                cancel_incomplete_sequence input_reader;
                Masc_tui_exit_signals.withdraw_interrupt exit_signals;
                skip_input_after_interrupt := true;
                report_action state "system" "Incomplete terminal sequence cancelled";
                Render_schedule.request render_schedule Render_schedule.Background;
                None
            | No_paste, false ->
                let chat_pane_active =
                  state.view = Keepers Keeper_message
                  && state.keeper_message_focus = Right_pane
                  && not state.keeper_navigation_open
                  && not (modal_owns_keys state)
                  && not state.palette_open
                  && not state.answering_open
                  && not state.image_open
                  && not state.msx_open
                  && Option.is_none state.lane_addons
                  && Option.is_none state.account_login
                  && Option.is_none state.voice_agent_voices
                in
                let account_login_interrupt_action =
                  match state.account_login with
                  | Some view when Option.is_none state.quit_armed ->
                      (match view.Masc_tui_account_login.phase with
                       | Masc_tui_account_login.Logging -> Some (view, Masc_tui_account_login.Cancel)
                       | Masc_tui_account_login.Preparing_context _
                       | Masc_tui_account_login.Preparing_context_batch _ ->
                           Some (view, Masc_tui_account_login.Cancel_prepare)
                       | Masc_tui_account_login.Loading | Providers _ | Models
                       | Refreshing_models | Documented_context _ | Saving | Removing
                       | Finished _ | Failed | Removal _ -> None)
                  | Some _ | None -> None
                in
                match account_login_interrupt_action with
                | Some (view, action) ->
                  Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox:async_messages view action;
                  Masc_tui_exit_signals.withdraw_interrupt exit_signals;
                  Render_schedule.request render_schedule Render_schedule.Background;
                  None
                | None ->
                if chat_pane_active
                   && Option.is_none state.quit_armed
                   && Masc_tui_chat_dispatch.Queue_steer.interrupt_active_chat_turn state ~mailbox:async_messages
                then begin
                  Masc_tui_exit_signals.withdraw_interrupt exit_signals;
                  Render_schedule.request render_schedule Render_schedule.Background;
                  None
                end else begin
                let confirmed = match interrupt, state.quit_armed,
                    current_quit_confirmation state ~now:(Unix.gettimeofday ()) with
                  | Masc_tui_exit_signals.Interrupt_again, Some arm, Some current ->
                      Masc_tui_action_notice.same_quit arm.qa_confirmation current
                      && quit_arm_matches state arm
                      && not (input_unsettled ())
                      && Masc_tui_action_notice.quit_authorized current
                           ~kind:Masc_tui_action_notice.Interrupt
                           ~currently_visible:(last_visible_quit
                             ~presented_rows:(Frame_presenter.presented_rows frame_presenter) ())
                           ~ordinary_before:(Masc_tui_action_notice.ordinary state.last_action)
                           ~now:(Unix.gettimeofday ()) ~window:last_action_window_s
                  | (Masc_tui_exit_signals.Interrupt_armed | Masc_tui_exit_signals.Interrupt_again),
                    (Some _ | None), (Some _ | None) -> false
                  | (Masc_tui_exit_signals.Continue | Masc_tui_exit_signals.Quit),
                    (Some _ | None), (Some _ | None) -> false in
                if confirmed then begin
                  Masc_tui_shell.Exit_journal.note Masc_tui_exit_reason.Interrupt;
                  raise Masc_tui_shell.Exit_journal.Break
                end;
                Masc_tui_shell.Quit_guard.arm state ~kind:Masc_tui_action_notice.Interrupt ~key:"Ctrl-C";
                if Option.is_none state.quit_armed then
                  Masc_tui_exit_signals.withdraw_interrupt exit_signals;
                Render_schedule.request render_schedule Render_schedule.Background;
                None
                end)
       | Masc_tui_exit_signals.Continue -> None
      in
      (* Input may cancel a pending MIDI handoff even when it will later be
         rejected; this lets the existing editor owner yield without replay. *)
      if not (input_unsettled ()) && Option.is_none interrupted_paste then
        presented := Presented.after_input !presented ~input_pending:false;
      let input_barrier_held () = match (!presented).barrier with
        | Presented.Open -> false | Presented.Held _ -> true in
      let frame_unavailable () =
        not state.image_open && not state.msx_open
        && Option.is_none (Frame_presenter.presented_rows frame_presenter) in
      let panel_owner_current () =
        let terminal_rows, _ = get_terminal_size () in
        Masc_tui_render.panel_input_owner state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) in
      let input_not_yet_admissible () =
        input_barrier_held () || frame_unavailable ()
        || (not state.image_open && not state.msx_open
            && (not (panel_owner_matches (panel_owner_current ()))
                || approval_detail_changed ())) in
      (* A rejected event cancels any signal confirmation above. MIDI
         withdrawal and async results after this point produce newer notices. *)
      let ordinary_before_input = Masc_tui_action_notice.ordinary state.last_action in
      let retire_music_editor_for_input () =
        if Option.is_some state.quit_armed || Masc_tui_exit_signals.pending_signal exit_signals
           || Option.is_some interrupted_paste || input_reader_has_started_input input_reader then
          withdraw_pending_music_editor state
      in
      let asynchronous_input_pending () =
        Masc_tui_exit_signals.pending_signal exit_signals
        || Masc_tui_shell.Terminal_session.resize_requested terminal_session
        || Option.is_some interrupted_paste
        || input_reader_has_unsettled_input input_reader
        || not (Queue.is_empty hangul_latin_queue)
        || match paste_phase input_reader with No_paste -> false | Pasting _ | Draining_tail _ -> true
      in
      retire_music_editor_for_input ();
      if
        drain_async_messages ~server_contact ~delivery_round:async_delivery_round ~deferred_share_messages ~deferred_share_sweep ~resource_copy_sweep ~deadline_ns:!drain_deadline_ns
          ~input_pending:(fun () -> input_reader_has_ready_input input_reader
              || Masc_tui_exit_signals.pending_signal exit_signals
              || Option.is_some state.quit_armed
              || Frame_presenter.last_frame_is_compact frame_presenter)
          ~share_input_pending:asynchronous_input_pending state ~base_path
          ~http_refresh_inflight
          ~http_scoped_refresh_inflight ~scoped_refresh_followup
          ~frame_presenter ~render_schedule async_messages
      then Render_schedule.request render_schedule Render_schedule.Background;
      let worker_geometry_current = make_worker_geometry_current () in
      let diagram_geometry_stable () =
        worker_geometry_current (Masc_tui_ansi.get_terminal_size ()) in
      prepare_resource_diagrams state ~mailbox:async_messages
        ~geometry_stable:diagram_geometry_stable
        ~worker_geometry_current;
      prepare_inspected_frame state ~mailbox:async_messages ~worker_geometry_current;
      (* A prepared editor may not replace a quit or recovery notice before
         the covered surface has actually returned to the terminal. *)
      let editor_waits_for_frame =
        let terminal_rows, _ = get_terminal_size () in
        let _, terminal_cols = Masc_tui_ansi.get_terminal_size () in
        Option.is_some state.quit_armed
        || Frame_presenter.last_frame_is_compact frame_presenter
        || Masc_tui_render.compact_frame_required state ~terminal_rows ~terminal_cols
             ~now:(Unix.gettimeofday ()) in
      (match state.lane_addons with
       | Some view when view.editor_ready && not editor_waits_for_frame
                        && not (input_not_yet_admissible ()) -> Masc_tui_editor_forms.Runtime_config_forms.handle_lane_document_editor state ~terminal_session
       | Some _ | None -> ());
      Masc_tui_editor_forms.Skill_prompt_forms.continue_keeper_settings_editor state ~mailbox:async_messages ~terminal_session ~input_pending:(
        editor_waits_for_frame || input_not_yet_admissible () || Option.is_some interrupted_paste
        || input_reader_has_ready_input input_reader
        || input_holds_incomplete_sequence input_reader
        || match paste_phase input_reader with No_paste -> false | Pasting _ | Draining_tail _ -> true);
      let code_navigation_input_pending =
        input_not_yet_admissible () || Option.is_some interrupted_paste
        || input_reader_has_ready_input input_reader
        || input_holds_incomplete_sequence input_reader
        || match paste_phase input_reader with No_paste -> false | Pasting _ | Draining_tail _ -> true
      in
      (match Code_results.take_ready_lsp_locations state
               ~input_pending:code_navigation_input_pending with
       | Code_results.No_followup -> ()
       | Code_results.Choose_location ->
           Render_schedule.request render_schedule Render_schedule.Background
       | Code_results.Reveal_cursor ->
           state.code_file_scroll <- Masc_tui_scroll.ensure_visible
             ~cursor:state.code_file_cursor
             ~height:(Masc_tui_render_code.code_pane_content_height state)
             state.code_file_scroll;
           Render_schedule.request render_schedule Render_schedule.Background
       | Code_results.Read_location_file (owner, request) ->
           Masc_tui_code_requests.launch_navigation_read state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
             ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) owner request;
           Render_schedule.request render_schedule Render_schedule.Background);
      let found_file = Code_results.take_ready_found_file state
          ~input_pending:code_navigation_input_pending in
      let navigated_file = Code_results.take_ready_navigation_file state
          ~input_pending:code_navigation_input_pending in
      if found_file || navigated_file then begin
        Masc_tui_code_requests.launch_entries_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
          ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages);
        Render_schedule.request render_schedule Render_schedule.Background
      end;
      Option.iter (fun path ->
        Masc_tui_code_requests.launch_file_load ~intent:Refresh_code_file state
          ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~path)
        (Code_results.saved_refresh_path state ~input_pending:code_navigation_input_pending);
      (* The load menu owns the terminal while it is up. *)
      (* Console writes damage whichever surface owns the terminal, including
         the spectator whose output bypasses the ordinary frame presenter. *)
      if Terminal_write_repair.consume_damage () then begin
        cell_image_redraw_pending := true;
        Masc_tui_msx.invalidate ();
        Frame_presenter.invalidate frame_presenter;
        Render_schedule.request render_schedule Render_schedule.Force;
        if state.msx_open then
          if state.msx_menu_open then
            Masc_tui_msx.render_menu ~write:write_to_terminal state
          else
            render_spectator state
      end;
      poll_play_room state ~mailbox:async_messages;
      (* Check for input. The read sleeps until a byte arrives, a writer
         rings the loop's bell, or the earliest moment this pass's decisions
         noted (RFC tui-idle-wait §3). *)
      let input_wait =
        let now_ns = Mtime_clock.elapsed_ns () in
        let work_ns = Int64.sub now_ns !pass_started_ns in
        if Int64.compare work_ns Masc_tui_http.slow_report_ns >= 0 then
          Log.Transport.info "main loop: %.0f ms of work in one pass"
            (Masc_tui_http.ms_of_ns work_ns);
        Masc_tui_wake.until ~now_ns Masc_tui_wake.loop
          (Masc_tui_wake.next_deadline ~now_ns
             { frame_due_ns = Render_schedule.frame_due_ns render_schedule ~now_ns;
               frame_drawn = !frame_drawn;
               machine_view = state.msx_open && not state.msx_menu_open })
      in
      let guarding_before_read =
        match paste_phase input_reader with
        | Draining_tail _ -> true
        | No_paste | Pasting _ -> false
      in
      let barrier_before_read = (!presented).barrier in
      let input =
        match interrupted_paste with
        | Some paste -> Some (Pasted paste)
        | None when !skip_input_after_interrupt -> None
        | None -> (
          (* A replayed key never went through the reader, so it skips the
             startup observation the terminal's own input feeds, and it waits
             for the interrupt arms above to clear the same way a key the
             operator pressed after them would. *)
          match Queue.take_opt hangul_latin_queue with
          | Some latin_key -> Some (Key latin_key)
          | None ->
            let input = read_input ~wait:input_wait input_reader () in
            Option.iter (observe_input_received input_reader) input;
            input)
      in
      (* The wait is over: what rang before now is seen by this pass, and
         every decision notes its moment again. *)
      ignore (Masc_tui_wake.take Masc_tui_wake.loop);
      Masc_tui_wake.Pass.begin_pass ();
      frame_drawn := false;
      pass_started_ns := Mtime_clock.elapsed_ns ();
      drain_deadline_ns := Int64.add !pass_started_ns async_drain_budget_ns;
      Masc_tui_nav_trace_log.note_input nav_trace
        (match input with
         | Some (Key name) -> Masc_tui_nav_trace_log.Key name
         | Some (Pasted _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _
                | Mouse_wheel _) -> Masc_tui_nav_trace_log.Other_input
         | Some (Graphics_reply _) | None -> Masc_tui_nav_trace_log.No_input);
      (* Retire the old preview before a frame barrier or paste recovery can
         consume the event. Protocol replies do not represent operator input. *)
      let duplicate_image_save = match input with
        | Some (Key ("s" | "S")) -> unsaved_remote_save_in_flight state
        | Some (Key _ | Pasted _ | Graphics_reply _ | Mouse_left_press _ | Mouse_left_drag _
                | Mouse_left_release _ | Mouse_wheel _) | None -> false in
      if Option.exists is_operator_input input && not duplicate_image_save then begin
        withdraw_pending_image_open state;
        withdraw_resource_diagram_pending state
      end;
      (* SIGWINCH can arrive while [read_input] is waiting. Consume it before
         this input sees the old frame; the next loop would be one key too
         late. *)
      consume_resize_request ();
      (* One direct ioctl snapshot owns both this interaction's bounds and its
         eventual frame. This also observes resizes from terminals that omit
         SIGWINCH, without allowing nested renderers to disagree mid-frame. *)
      let resized = match refresh_terminal_size () with
       | Render_schedule.Terminal_size_cache.Changed _ ->
           withdraw_resource_diagram_pending state;
           Masc_tui_shell.Terminal_session.bump_resize_generation terminal_session;
           state.resource_copy_pending <- None;
           state.resource_copy_ready <- None;
           state.resource_share_recovery_lookup <- None;
           Option.iter (fun prompt -> Masc_tui_artifact_share_confirmation.withdraw prompt.recovery_confirmation)
             state.resource_share_recovery_prompt;
           Masc_tui_shell.Terminal_session.discard_frame_for_new_size frame_presenter render_schedule;
           (* The panes a held gesture was placed in are not where they were. *)
           pointer_gesture := Masc_tui_pane_selection.Idle;
           (* Geometry changes redraw the cached snapshot immediately; an
              in-flight tick must not own resize presentation either. *)
           if state.msx_open then begin
             if state.msx_menu_open then
               Masc_tui_msx.render_menu ~write:write_to_terminal state
             else
               render_spectator state
           end;
           (match state.browser_viewport with
            | Some (shot, bytes) -> draw_browser_viewport state shot bytes
            | None -> ());
           if state.image_open && not state.msx_open then
             Option.iter (draw_inspected_image state) state.image_inspection;
           true
       | Render_schedule.Terminal_size_cache.Unchanged _ -> false in
      (match state.image_pixel_source with
       | Some source when state.image_open && not state.msx_open ->
           (match image_pixel_source_for_redraw state source with
            | None ->
                close_image state;
                Masc_tui_shell.Terminal_session.invalidate_frame_for_resize frame_presenter render_schedule
            | Some current ->
                state.image_pixel_source <- Some current;
                if resized || current.ips_unconfirmed <> source.ips_unconfirmed then begin
                  let rows, columns = Masc_tui_ansi.get_terminal_size () in
                  let footer = pixel_image_footer state current.ips_footer in
                  write_to_terminal (Printf.sprintf "\027[%d;1H\027[2K%s" rows
                    (Message_layout.fit_width footer (max 1 (columns-1))))
                end)
       | Some _ | None -> ());
      (match state.image_cell_view with
       | Some (Image_cells view) when state.image_open && not state.msx_open ->
           (match image_cell_origin_for_redraw state ~workspace:view.ic_workspace view.ic_origin with
           | None ->
             discard_pending_image_copy ();
             (match cell_image_terminal_size () with
              | Some terminal_size ->
                  draw_withdrawn_cell_image state ~terminal_size;
                  cell_image_redraw_pending := false
              | None ->
                  write_terminal_text Ansi.clear;
                  state.image_cell_view <- Some (Image_cells_withdrawn None);
                  cell_image_redraw_pending := true)
           | Some origin ->
             let view = if origin == view.ic_origin then view else {view with ic_origin=origin} in
             state.image_cell_view <- Some (Image_cells view);
             let unconfirmed = image_cell_source_unconfirmed state origin in
             (match cell_image_terminal_size () with
              | Some terminal_size ->
                  if !cell_image_redraw_pending || resized || terminal_size <> view.ic_terminal_size
                     || unconfirmed <> view.ic_unconfirmed then
                    draw_cell_image state ~terminal_size {view with ic_unconfirmed=unconfirmed};
                  cell_image_redraw_pending := false
              | None ->
                  if unconfirmed && not view.ic_unconfirmed then begin
                    (* Do not leave a confirmed-looking footer on screen when
                       the source became uncertain and geometry is unknown. *)
                    write_terminal_text Ansi.clear;
                    state.image_cell_view <- Some (Image_cells {view with ic_unconfirmed=true});
                    cell_image_redraw_pending := true
                  end))
       | Some (Image_cells_withdrawn last_size) when state.image_open && not state.msx_open ->
           (match cell_image_terminal_size () with
            | Some terminal_size ->
                if !cell_image_redraw_pending || resized || last_size <> Some terminal_size then
                  draw_withdrawn_cell_image state ~terminal_size;
                cell_image_redraw_pending := false
            | None -> ())
       | Some (Image_cells _ | Image_cells_withdrawn _) | None -> cell_image_redraw_pending := false);
      (* Decide from the hold captured before reading: the final event is
         rejected even when reading it emptied the last input buffer. *)
      let rejected, rejected_paste, was_reported, paste_was_reported =
        match barrier_before_read, input with
        | Presented.Held flags, Some event when is_operator_input event ->
            let paste = match event with
              | Pasted _ -> true
              | Key _ | Graphics_reply _ | Mouse_left_press _ | Mouse_left_drag _
              | Mouse_left_release _ | Mouse_wheel _ -> false in
            true, paste, flags.rejected_input, flags.rejected_paste
        | (Presented.Open | Presented.Held _), (Some _ | None) -> false, false, false, false
      in
      if rejected then begin
        presented := Presented.reject !presented ~paste:rejected_paste;
        if rejected_paste && Option.is_some interrupted_paste then
          presented := Presented.reject_recovery !presented;
        if rejected_paste && not paste_was_reported then
          report_input_rejection state Masc_tui_action_notice.Paste_rejected
            "Paste was not applied during the screen transition; paste it again"
        else if not was_reported then
          report_input_rejection state Masc_tui_action_notice.Input_rejected
            "Input was not applied during the screen transition; review and retry";
        Render_schedule.request render_schedule Render_schedule.Background
      end;
      let input = if rejected then None else input in
      presented := Presented.after_input !presented ~input_pending:(input_unsettled ());
      (* A resize or invalidation can leave no accepted frame even when no
         transition barrier is active. Reject that operator input before any
         hidden handler can consume it; protocol replies still reach their owner. *)
      let unpresented_decision = match input with
        | None -> Presented.Accept_input
        | Some event ->
            let kind = match event with
              | Key _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _
              | Mouse_wheel _ -> Presented.Action
              | Pasted _ -> Presented.Paste
              | Graphics_reply _ -> Presented.Protocol in
            Presented.decide_unpresented_input
              ~frame_presented:(Option.is_some (Frame_presenter.presented_rows frame_presenter))
              ~external_surface:(state.image_open || state.msx_open) kind in
      (match unpresented_decision with
       | Presented.Reject_paste when Option.is_some interrupted_paste ->
           presented := Presented.reject_recovery !presented
       | Presented.Accept_input | Presented.Reject_action | Presented.Reject_paste -> ());
      let input = match unpresented_decision with
        | Presented.Accept_input -> input
        | Presented.Reject_action | Presented.Reject_paste ->
            pointer_gesture := Masc_tui_pane_selection.Idle;
            None in
      (* Panels and their search editors use the actual frame choice. Neither
         a transition nor nontext paste may reach a covered text owner. *)
      let current_panel = panel_owner_current () in
      let panel_decision = match input with
        | None -> Presented.Accept_input
        | Some event ->
            let kind = match event with
              | Key _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _
              | Mouse_wheel _ -> Presented.Action
              | Pasted _ -> Presented.Paste
              | Graphics_reply _ -> Presented.Protocol in
            Presented.decide_snapshot_input !presented
              ~external_surface:(state.image_open || state.msx_open)
              ~context_search_owner:(context_search_owner ()) ~current_owner:current_panel kind in
      (match panel_decision with
       | Presented.Reject_paste when Option.is_some interrupted_paste ->
           presented := Presented.reject_recovery !presented
       | Presented.Accept_input | Presented.Reject_action | Presented.Reject_paste -> ());
      let input = match panel_decision with
        | Presented.Accept_input -> input
        | Presented.Reject_action | Presented.Reject_paste ->
            pointer_gesture := Masc_tui_pane_selection.Idle;
            None in
      (* A detail, or its byte view, cannot take keys from the previously
         displayed frame while the replacement is still waiting to render. *)
      let approval_detail_decision = match input with
        | None -> Presented.Accept_input
        | Some event ->
            let kind = match event with
              | Pasted _ -> Presented.Paste
              | Graphics_reply _ -> Presented.Protocol
              | Key _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _
              | Mouse_wheel _ -> Presented.Action in
            Presented.decide_unpresented_input
              ~frame_presented:(not (approval_detail_changed ()))
              ~external_surface:(state.image_open || state.msx_open) kind in
      (match approval_detail_decision with
       | Presented.Reject_paste when Option.is_some interrupted_paste ->
           presented := Presented.reject_recovery !presented
       | Presented.Accept_input | Presented.Reject_action | Presented.Reject_paste -> ());
      let input = match approval_detail_decision with
        | Presented.Accept_input -> input
        | Presented.Reject_action | Presented.Reject_paste ->
            pointer_gesture := Masc_tui_pane_selection.Idle;
            None in
      (* A reader can be opened or replaced before the next frame. Keys from
         the previously presented owner cannot navigate that unseen reader. *)
      let peer_owner_decision =
        let terminal_rows, _ = get_terminal_size () in
        let candidate = peer_frame_owner_on_screen ~terminal_rows in
        match input with
        | None -> Presented.Accept_input
        | Some event ->
            let kind = match event with
              | Pasted _ -> Presented.Paste
              | Graphics_reply _ -> Presented.Protocol
              | Key _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _
              | Mouse_wheel _ -> Presented.Action in
            Presented.decide_unpresented_input
              ~frame_presented:(not (keeper_peer_frame_owner_changed
                ~presented:!presented_peer_owner ~candidate))
              ~external_surface:(state.image_open || state.msx_open) kind in
      (match peer_owner_decision with
       | Presented.Reject_paste when Option.is_some interrupted_paste ->
           presented := Presented.reject_recovery !presented
       | Presented.Accept_input | Presented.Reject_action | Presented.Reject_paste -> ());
      let input = match peer_owner_decision with
        | Presented.Accept_input -> input
        | Presented.Reject_action | Presented.Reject_paste ->
            pointer_gesture := Masc_tui_pane_selection.Idle;
            None in
      (* A Queue refresh can change its placement or page boundary before
         the replacement frame. Refuse that input before it can acknowledge
         an earlier rejection or begin a gesture against changing content. *)
      let queue_viewport_decision =
        let terminal_rows, _ = get_terminal_size () in
        match input, queue_owner_of_reader (!presented).reader,
              Masc_tui_render.queue_below_play state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) with
        | Some event, Some owner, Some panel
          when not state.image_open && not state.msx_open
               && not (queue_owner_matches state panel
                 ~viewport:(Masc_tui_render_overlays.queue_panel_viewport state panel) owner) ->
            (match event with
             | Pasted _ -> Presented.Reject_paste
             | Graphics_reply _ -> Presented.Accept_input
             | Key _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _
             | Mouse_wheel _ -> Presented.Reject_action)
        | (Some _ | None), (Some _ | None), (Some _ | None) -> Presented.Accept_input in
      (match queue_viewport_decision with
       | Presented.Reject_paste when Option.is_some interrupted_paste ->
           presented := Presented.reject_recovery !presented
       | Presented.Accept_input | Presented.Reject_action | Presented.Reject_paste -> ());
      let input = match queue_viewport_decision with
        | Presented.Accept_input -> input
        | Presented.Reject_action | Presented.Reject_paste ->
            pointer_gesture := Masc_tui_pane_selection.Idle;
            None in
      (* A backlog refresh can withdraw the visible Task before the list that
         replaces it is emitted. No action belongs to that unseen list yet. *)
      let task_reader_decision = match input with
        | None -> Presented.Accept_input
        | Some event ->
            let kind = match event with
              | Pasted _ -> Presented.Paste
              | Graphics_reply _ -> Presented.Protocol
              | Key _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _
              | Mouse_wheel _ -> Presented.Action in
            Presented.decide_unpresented_input
              ~frame_presented:(not (task_detail_reader_withdrawn state (!presented).reader
                                     || tools_task_reader_withdrawn state))
              ~external_surface:(state.image_open || state.msx_open) kind in
      (match task_reader_decision with
       | Presented.Reject_paste when Option.is_some interrupted_paste ->
           presented := Presented.reject_recovery !presented
       | Presented.Accept_input | Presented.Reject_action | Presented.Reject_paste -> ());
      let input = match task_reader_decision with
        | Presented.Accept_input -> input
        | Presented.Reject_action | Presented.Reject_paste ->
            pointer_gesture := Masc_tui_pane_selection.Idle;
            None in
      (* A rejected press may be followed by motion/release after the replacement
         frame. Without an accepted press there is no gesture to complete;
         that tail must not acknowledge the displayed rejection either. *)
      let orphan_pointer_tail =
        not state.image_open && not state.msx_open
        && (match !pointer_gesture with
            | Masc_tui_pane_selection.Idle ->
                (match input with
                 | Some (Mouse_left_drag _ | Mouse_left_release _) -> true
                 | Some (Key _ | Pasted _ | Graphics_reply _ | Mouse_left_press _
                     | Mouse_wheel _) | None -> false)
            | Pressed _ | Selecting _ | Drag_without_pane -> false) in
      let input = if orphan_pointer_tail then None else input in
      if orphan_pointer_tail then
        Render_schedule.request render_schedule Render_schedule.Background;
      (* A rejected gesture has no target, but it still interrupts any armed
         confirmation. Never send its key or payload to another surface. *)
      let decision_rejected = function
        | Presented.Accept_input -> false
        | Presented.Reject_action | Presented.Reject_paste -> true in
      let rejected_operator_input = rejected || decision_rejected unpresented_decision
        || decision_rejected panel_decision || decision_rejected approval_detail_decision
        || decision_rejected peer_owner_decision
        || decision_rejected queue_viewport_decision || decision_rejected task_reader_decision
        || orphan_pointer_tail in
      let panel_owns_input = Option.is_some current_panel
        && panel_owner_matches current_panel
        && not state.image_open && not state.msx_open in
      let help_owns_input = panel_owns_input && current_panel = Some Presented.Help in
      let panel_owns_commands = panel_owns_input && (match current_panel with
            | Some (Presented.Help | About | Context | Agenda | Answering | Account_server) -> true
            | Some Context_search | None -> false) in
      if rejected_operator_input then begin
        Masc_tui_exit_signals.withdraw_interrupt exit_signals;
        (* The read may have consumed its final byte, so neither the pre- nor
           post-drain readiness check can witness this rejected gesture. *)
        withdraw_pending_music_editor state
      end;
      let input = match input with
        | Some (Mouse_wheel (direction, _, _))
            when not panel_owns_input && Option.is_some (current_code_hover state) ->
            Some (Key (match direction with
              | Masc.Tui_mouse_protocol.Wheel_up -> "up"
              | Masc.Tui_mouse_protocol.Wheel_down -> "down"))
        | Some (Mouse_left_press _ | Key ("tab" | "shift-tab" | "\t"))
            when not panel_owns_input && Option.is_some (current_code_hover state) ->
            state.code_hover <- None; input
        | Some (Key _ | Pasted _ | Graphics_reply _ | Mouse_left_press _
               | Mouse_left_drag _ | Mouse_left_release _ | Mouse_wheel _)
        | None -> input in
      (* A queued action retires a deferred return before any handler changes
         its reading. Repeated B shares its pending request; protocol replies
         and idle cadence are observations rather than operator actions. *)
      (match input with
       | Some (Key _ | Pasted _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _ | Mouse_wheel _) ->
           Code_results.retire_lsp_input state
       | Some (Graphics_reply _) | None -> ());
      (match input with
       | Some (Key "B") when state.view = Code -> ()
       | Some (Key _ | Pasted _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _ | Mouse_wheel _) ->
           state.code_navigation <- None
       | Some (Graphics_reply _) | None -> ());
      let input =
        if not panel_owns_input && Masc_tui_chat_input.Paste_spill.recovered_paste_send_locked state then
          match input with
          | Some (Key "\007")
            when paste_phase input_reader = No_paste
                 && (state.view = Keepers Keeper_message || state.composer_focused) ->
              Masc_tui_chat_input.Paste_spill.discard_recovered_paste_lock state;
              report_action state "system" "Recovered draft confirmed; Enter may send";
              (* The key is consumed here, so the [Input] request that follows
                 every other key never fires. Without this the lock is gone
                 but nothing is drawn: the operator sees no answer to Ctrl-G. *)
              Render_schedule.request render_schedule Render_schedule.Input;
              None
          | (Some (Key _ | Pasted _ | Graphics_reply _ | Mouse_left_press _
                  | Mouse_left_drag _ | Mouse_left_release _ | Mouse_wheel _)
            | None) as other -> other
        else input
      in
      (* The footer's notice answers the last key. The next input is a new
         key, so the notice goes before anything handles it: it takes the
         room the key hints need, and a notice left standing after the
         operator moved on hid the hints of the screen they moved to. A key
         that has something to say sets its own. A rejected gesture cancels
         ordinary confirmations too, but cannot acknowledge a rejection. *)
      let quit_before_input =
        match current_quit_confirmation state ~now:(Unix.gettimeofday ()) with
        | Some confirmation
          when Masc_tui_action_notice.quit_authorized confirmation
              ~kind:Masc_tui_action_notice.Quit_key
              ~currently_visible:(last_visible_quit
                ~presented_rows:(Frame_presenter.presented_rows frame_presenter) ())
              ~ordinary_before:(Masc_tui_action_notice.ordinary state.last_action)
              ~now:(Unix.gettimeofday ()) ~window:last_action_window_s -> Some confirmation
        | Some _ | None -> None in
      state.last_action <-
        if rejected_operator_input then
          Masc_tui_action_notice.after_rejected_input state.last_action
            ~ordinary_before:ordinary_before_input
            ~currently_visible:(last_visible_rejection
              ~presented_rows:(Frame_presenter.presented_rows frame_presenter) ())
            ~now:(Unix.gettimeofday ()) ~window:last_action_window_s
        else
          Masc_tui_action_notice.after_input state.last_action
            ~input_seen:(Option.is_some input)
            ~operator_input:(Option.exists is_operator_input input)
            ~currently_visible:(last_visible_rejection
              ~presented_rows:(Frame_presenter.presented_rows frame_presenter) ())
            ~now:(Unix.gettimeofday ()) ~window:last_action_window_s;
      state.last_action <- Masc_tui_action_notice.after_drain state.last_action
          ~at:(Unix.gettimeofday ()) ~input_pending:(input_unsettled ())
          ~currently_visible:(last_visible_rejection
            ~presented_rows:(Frame_presenter.presented_rows frame_presenter) ());
      (* Further operator input owns focus. A pending creation may finish and
         refresh its metadata, but cannot jump over the next gesture/draft. *)
      (match input with
       | Some (Key _ | Pasted _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _ | Mouse_wheel _) ->
           state.keeper_creation_focus <- None;
           withdraw_pending_music_editor state
       | Some (Graphics_reply _) | None -> ());
      (match input with
       | Some (Key _ | Pasted _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _ | Mouse_wheel _) ->
           state.resource_copy_pending <- None;
           state.resource_copy_ready <- None
       | Some (Graphics_reply _) | None -> ());
      (match input with
       | Some (Key "U") when state.view = Resources && state.resource_focus = Right_pane -> ()
       | Some (Key "!") when state.view = Resources && state.resource_focus = Right_pane ->
           state.resource_share_recovery_lookup <- None
       | Some (Key ("j" | "k" | "J" | "K" | "up" | "down" | "pageup" | "pagedown" | "home" | "end") | Mouse_wheel _)
           when state.view = Resources && state.resource_focus = Right_pane ->
           state.resource_share_recovery_lookup <- None;
           Option.iter (fun prompt -> Masc_tui_artifact_share_confirmation.withdraw prompt.recovery_confirmation)
             state.resource_share_recovery_prompt
       | Some (Key _ | Pasted _ | Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _ | Mouse_wheel _) ->
           state.resource_share_recovery_lookup <- None;
           state.resource_share_recovery_prompt <- None
       | Some (Graphics_reply _) | None -> ());
      Option.iter
        (fun _ ->
          if not rejected_operator_input
             && Option.is_none state.queue_panel && Option.is_none (play_card_shown state)
             && Option.is_none (queue_owner_of_reader (!presented).reader)
             && Option.is_none (play_card_of_reader (!presented).reader)
             && not (Frame_presenter.last_frame_is_compact frame_presenter) then
            report_action state "system"
              "Recovered paste received; check its destination and wait for marker or Ctrl-C")
        interrupted_paste;
      if guarding_before_read && paste_phase input_reader = No_paste then begin
        let recovery_was_rejected =
          (!presented).recovery = Presented.Rejected_recovery in
        presented := Presented.clear_recovery !presented;
        report_action state "system"
          (if recovery_was_rejected then "Paste tail ended; the recovered paste was not applied"
           else "Paste tail ended; check its destination before continuing");
        (* The tail's end marker is swallowed and returns no input, so no
           [Input] request draws this; ask for the frame as the other
           recovery notices do. *)
        Render_schedule.request render_schedule Render_schedule.Background
      end;
      (match paste_phase input_reader with
       | Pasting _ when not !paste_pause_notified ->
           paste_pause_notified := true;
           report_action state "system"
             (if input_barrier_held () then
                "Paste in progress during a screen transition; Ctrl-C can cancel if stuck"
              else "Paste in progress; Ctrl-C twice recovers, third unlocks if stuck");
           Render_schedule.request render_schedule Render_schedule.Background
       | Pasting _ -> ()
       | No_paste | Draining_tail _ -> paste_pause_notified := false);
      (match paste_phase input_reader with
       | Pasting paste when cancel_armed paste
                     && paste_can_recover input_reader paste
                     && not !paste_quiet_notified ->
           paste_quiet_notified := true;
           report_action state "system"
             (if input_barrier_held () then
                "Paste quiet; Ctrl-C again recovers it, but it will not be applied on this screen"
              else "Paste quiet; Ctrl-C again recovers it if the end marker was lost");
           Render_schedule.request render_schedule Render_schedule.Background
       | Pasting paste when not (paste_can_recover input_reader paste) ->
           paste_quiet_notified := false
       | Pasting _ -> ()
       | No_paste | Draining_tail _ -> paste_quiet_notified := false);
      (match input_holds_incomplete_sequence input_reader, !csi_pause_notice with
       | true, None ->
           report_action state "system"
             "Terminal sequence incomplete; Ctrl-C cancels it";
           csi_pause_notice := Masc_tui_action_notice.ordinary state.last_action;
           state.last_action <- Masc_tui_action_notice.start_csi state.last_action;
           Render_schedule.request render_schedule Render_schedule.Background
       | true, Some _ | false, None -> ()
       | false, Some shown ->
           (* The hold is over, so its notice is no longer true. Only that
              notice is taken down: one set since (the Ctrl-C outcome, a key's
              answer) stays for its own window. *)
           state.last_action <- Masc_tui_action_notice.end_csi state.last_action;
           (match Masc_tui_action_notice.ordinary state.last_action with
            | Some current when current == shown ->
                set_last_action state None;
                Render_schedule.request render_schedule Render_schedule.Background
            | Some _ | None -> ());
           csi_pause_notice := None);
      (match paste_phase input_reader with
       | Draining_tail tail when paste_can_recover input_reader tail
                     && not !paste_guard_idle_notified ->
           paste_guard_idle_notified := true;
           report_action state "system"
             "Paste tail quiet; Ctrl-C unlocks input if the end marker was lost";
           Render_schedule.request render_schedule Render_schedule.Background
       | Draining_tail tail when not (paste_can_recover input_reader tail) ->
           paste_guard_idle_notified := false
       | Draining_tail _ -> ()
       | No_paste | Pasting _ -> paste_guard_idle_notified := false);
      (match unpresented_decision with
       | Presented.Accept_input -> ()
       | Presented.Reject_action ->
           report_input_rejection state Masc_tui_action_notice.Input_rejected
             "Screen not yet displayed; input was not applied, review and retry";
           Render_schedule.request render_schedule Render_schedule.Background
       | Presented.Reject_paste ->
           report_input_rejection state Masc_tui_action_notice.Paste_rejected
             "Screen not yet displayed; paste was not applied, paste it again";
           Render_schedule.request render_schedule Render_schedule.Background);
      (match panel_decision with
       | Presented.Accept_input -> ()
       | Presented.Reject_action ->
           report_input_rejection state Masc_tui_action_notice.Input_rejected
             "Screen transition: input was not applied; review and retry";
           Render_schedule.request render_schedule Render_schedule.Background
       | Presented.Reject_paste ->
           report_input_rejection state Masc_tui_action_notice.Paste_rejected
             "Paste was not applied on this screen; retry in a text field";
           Render_schedule.request render_schedule Render_schedule.Background);
      (match approval_detail_decision with
       | Presented.Accept_input -> ()
       | Presented.Reject_action ->
           report_input_rejection state Masc_tui_action_notice.Input_rejected
             "Approval view changed: input was not applied; review and retry";
           Render_schedule.request render_schedule Render_schedule.Background
       | Presented.Reject_paste ->
           report_input_rejection state Masc_tui_action_notice.Paste_rejected
             "Approval view changed: paste was not applied; retry";
           Render_schedule.request render_schedule Render_schedule.Background);
      (match peer_owner_decision with
       | Presented.Accept_input -> ()
       | Presented.Reject_action ->
           report_input_rejection state Masc_tui_action_notice.Input_rejected
             "Relationship reader changed: input was not applied; review and retry";
           Render_schedule.request render_schedule Render_schedule.Background
       | Presented.Reject_paste ->
           report_input_rejection state Masc_tui_action_notice.Paste_rejected
             "Relationship reader changed: paste was not applied; retry";
           Render_schedule.request render_schedule Render_schedule.Background);
      (match queue_viewport_decision with
       | Presented.Accept_input -> ()
       | Presented.Reject_action ->
           report_input_rejection state Masc_tui_action_notice.Input_rejected
             "Queue changed: input was not applied; review the new frame and retry";
           Render_schedule.request render_schedule Render_schedule.Background
       | Presented.Reject_paste ->
           report_input_rejection state Masc_tui_action_notice.Paste_rejected
             "Queue changed: paste was not applied; retry in a text field";
           Render_schedule.request render_schedule Render_schedule.Background);
      (match task_reader_decision with
       | Presented.Accept_input -> ()
       | Presented.Reject_action ->
           report_input_rejection state Masc_tui_action_notice.Input_rejected
             "Task view changed: input was not applied; review and retry";
           Render_schedule.request render_schedule Render_schedule.Background
       | Presented.Reject_paste ->
           report_input_rejection state Masc_tui_action_notice.Paste_rejected
             "Task view changed: paste was not applied; review and retry";
           Render_schedule.request render_schedule Render_schedule.Background);
      reconcile_chat_focus ();
      (* Any deliberate input withdraws a standing Ctrl-C. Without this the
         armed state outlives the moment it was meant for, and a Ctrl-C typed
         minutes apart from another would read as a double press. *)
      if Option.exists Masc_tui_input_reader.is_operator_input input then begin
        Masc_tui_exit_signals.withdraw_interrupt exit_signals;
        cancel_board_image_read state;
        (* A refused gesture stays on screen until the next input. The input
           that is refused sets it below, after this. *)
        state.browser_lane <-
          Option.map Browser_lane_view.withdraw_unserved_gesture state.browser_lane;
        if not duplicate_image_save then
        if Option.is_none state.browser_viewport then
          state.image_request_generation <- state.image_request_generation + 1
        else match state.browser_lane with
          | Some ({load = Browser_lane_view.Loading (_, Viewport_observed _);_} as view) ->
              (* A background image read yields to the gesture on the image
                 already displayed. Its late response cannot redraw between
                 press and release or reopen a dismissed viewport. *)
              state.image_request_generation <- state.image_request_generation + 1;
              state.browser_lane <- Some (Browser_lane_view.yield_refresh_to_input view)
          | Some { load = Browser_lane_view.Loading (_, (Browser_lane_view.Read | Browser_lane_view.Read_refresh | Browser_lane_view.Discover _ | Browser_lane_view.Screenshot _ | Browser_lane_view.Scene_read _ | Browser_lane_view.Scene_regions _ | Browser_lane_view.Scene_refresh _ | Browser_lane_view.Scene_scroll _ | Browser_lane_view.Scene_focus _ | Browser_lane_view.Scene_click _ | Browser_lane_view.Scene_follow _ | Browser_lane_view.Scene_follow_refresh _ | Browser_lane_view.Viewport_refresh _ | Browser_lane_view.Viewport_pointer _));_}
          | Some { load = (Browser_lane_view.Idle | (Browser_lane_view.No_browser | Browser_lane_view.Failed _));_}
          | None -> ()
      end;
      (* The key channel stays exactly what it was: every surface below reads
         [key] the way it always has, and a paste is simply not one. Splitting
         here rather than inside the surfaces is what keeps a paste from
         needing a name in the key vocabulary. *)
      (* A picture is showing, which means the terminal is not showing this
         program's frame. The next key is the one that takes the picture away
         and is not also a keystroke for the surface underneath -- an operator
         pressing j to dismiss a screenshot did not mean to move a cursor. *)
      let viewport_owned_input = state.image_open && Option.is_some state.browser_viewport
        && Option.is_some input in
      (match state.browser_viewport, input with
       | Some (shot, _), Some event ->
           let close () =
             state.image_request_generation <- state.image_request_generation + 1;
             close_image state;
             Masc_tui_shell.Terminal_session.invalidate_frame_for_resize frame_presenter render_schedule
           in
           (* Inputs during an in-flight request are consumed, never queued or
              replayed after a possible browser side effect. A gesture the
              screenshot's connection does not serve is not sent: the
              screenshot closes so the reason and the next step are on screen. *)
           let pointer action = match state.browser_lane with
             | None -> ()
             | Some view ->
                 (match Browser_lane_view.pointer_decision view shot action with
                  | Browser_lane_view.Pointer_consumed -> ()
                  | Browser_lane_view.Pointer_send operation ->
                      Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages operation
                  | Browser_lane_view.Pointer_unserved unserved ->
                      close ();
                      state.browser_lane <-
                        Some (Browser_lane_view.refuse_gesture unserved view)) in
           (* Viewport keys and wheel notches move by 120 CSS pixels. *)
           let scroll_at point y =
             pointer (Browser_lane.Scroll_at {point;viewport=shot.viewport;x=0;y}) in
           let wheel row column y = match !browser_image_region with
             | Some region -> (match Masc_tui_graphics.image_point region ~row ~column with
                 | Some (x,y_point) -> scroll_at {x;y=y_point} y
                 | None -> ())
             | None -> scroll_at {x=0.5;y=0.5} y in
           (match event with
            | Mouse_left_press (row,column) ->
                browser_pointer_press := None;
                (match state.browser_lane, !browser_image_region with
                 | Some view, Some region when not (Browser_lane_view.busy view) ->
                     (match Masc_tui_graphics.image_point region ~row ~column with
                      | Some (x,y) -> browser_pointer_press := Some (row,column,{x;y})
                      | None -> ())
                 | _ -> ())
            | Mouse_left_release (row,column) ->
                let pressed = !browser_pointer_press in
                browser_pointer_press := None;
                (match pressed, !browser_image_region with
                 | Some (start_row,start_column,from), Some region ->
                     (match Masc_tui_graphics.image_point region ~row ~column with
                      | Some _ when row=start_row && column=start_column ->
                          pointer (Browser_lane.Click_at {point=from;viewport=shot.viewport;
                            button=Browser_lane.Pointer.Primary})
                      | Some _ | None -> ())
                 | _ -> ())
            (* A press and release on one cell is a click. A release on
               another cell sends nothing: no connection takes a drag from
               point to point. *)
            | Mouse_left_drag _ -> ()
            | Key ("esc" | "q") -> close ()
            | Key "r" -> Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages (Viewport_refresh {tab_id=shot.tab_id; expected_url=shot.url})
            | Key ("j" | "down") -> scroll_at {x=0.5;y=0.5} 120
            | Key ("k" | "up") -> scroll_at {x=0.5;y=0.5} (-120)
            | Mouse_wheel (Masc.Tui_mouse_protocol.Wheel_down,row,column) -> wheel row column 120
            | Mouse_wheel (Masc.Tui_mouse_protocol.Wheel_up,row,column) -> wheel row column (-120)
            | Key _ | Pasted _ | Graphics_reply _ -> ())
       | _ -> ());
      let input = if viewport_owned_input then None else input in
      let inspection_owned_input = state.image_open && Option.is_some state.image_inspection
        && Option.is_some input in
      (match state.image_inspection, input, !image_cell_pixels with
       | Some inspected, Some event, Some cell_pixels
           when state.image_open && not state.msx_open ->
         let close () = close_image state;
           Masc_tui_shell.Terminal_session.invalidate_frame_for_resize frame_presenter render_schedule in
         let action = match event with
           | Key ("+" | "=") -> Some Masc_tui_image_viewport.Zoom_in
           | Key "-" -> Some Zoom_out
           | Key "0" -> Some Fit
           | Key "r" ->
               draw_inspected_image state {inspected with ii_frame=Original_image}; None
           | Key ("h" | "left") -> Some Left
           | Key ("l" | "right") -> Some Right
           | Key ("k" | "up") | Mouse_wheel (Masc.Tui_mouse_protocol.Wheel_up,_,_) -> Some Up
           | Key ("j" | "down") | Mouse_wheel (Masc.Tui_mouse_protocol.Wheel_down,_,_) -> Some Down
           | Key ("esc" | "q") -> close (); None
           | Key "v" when state.view=Resources ->
               state.resource_presentation <- Masc_tui_resource_catalog.Source;
               state.resource_scroll <- Masc_tui_scroll.Position.first;
               state.resource_search_position <- Masc_tui_resource_reading.first;
               close (); None
           | Key _ | Pasted _ | Graphics_reply _ | Mouse_left_press _
           | Mouse_left_drag _ | Mouse_left_release _ -> None in
         Option.iter (fun action ->
           let rows,columns = Masc_tui_ansi.get_terminal_size () in
           let viewport = Masc_tui_image_viewport.apply ~cell_pixels
             ~columns:(max 1 (columns-2)) ~rows:(max 1 (rows-3)) action inspected.ii_viewport in
           let fresh = match inspected.ii_frame with Raster_image _ -> true
             | Original_image | Raster_unavailable _ -> false in
           draw_inspected_image ~fresh state
             {inspected with ii_viewport=viewport;ii_frame=Original_image}) action
       | (Some _ | None), (Some _ | None), (Some _ | None) -> ());
      let input = if inspection_owned_input then None else input in
      let handled_image_copy = match state.image_cell_view, input with
        | Some (Image_cells ({ic_unsaved_remote=Some captured;ic_copy_path=Some path;
                              ic_copy_page=Some page_url;_} as shown)),
          Some (Key ("s" | "S")) when state.image_open && not state.msx_open ->
            let origin = shown.ic_origin in
            let report status = update_image_link_card state ~path status in
            if Option.is_some state.sent_image_read || Masc_tui_board_preview_work.is_busy remote_copy_worker then
              report "An image save is still in progress"
            else if Option.is_none (image_cell_origin_for_redraw state
              ~workspace:shown.ic_workspace origin)
              || image_cell_source_unconfirmed state origin then
              report "Source unconfirmed; reopen the preview"
            else if asynchronous_input_pending () then report "Save cancelled while input was pending"
            else begin
              (* Operator input has advanced the generation. This save owns a
                 fresh request while the displayed card keeps the source. *)
              state.image_cell_view <- Some (Image_cells {shown with ic_save_cancelled=false});
              let request = {origin with sir_generation=state.image_request_generation} in
              state.sent_image_read <- Some request;
              report "Saving the captured original";
              launch_remote_image_copy state ~mailbox:async_messages ~request
                ~title:origin.sir_name ~caption:[] ~page_url ~image_url:captured.uri_image_url
                ~reason:captured.uri_reason ~requested_save:true captured.uri_bytes
            end;
            true
        | Some (Image_cells {ic_copy_path=Some path;_}), Some (Key ("y" | "Y"))
            when state.image_open && not state.msx_open ->
            if keep_pending_image_copy path then
              let outcome = copy_reference render_schedule path in
              report_action state "system"
                (if state.ui_language = Lang_ko then
                   "저장한 이미지 경로를 " ^ Masc_tui_clipboard.copy_outcome_text_korean outcome
                 else
                   "Saved image path " ^ Masc_tui_clipboard.copy_outcome_text outcome)
            else update_image_link_card state ~path "The saved copy is no longer available";
            true
        | Some (Image_cells ({ic_copy_path=Some path;ic_copy_page=Some url;
                              ic_alternate_target=Some alternate;_} as shown)),
          Some (Key (("o" | "O" | "x" | "X") as key)) when state.image_open && not state.msx_open ->
            (* Do not retain the whole frame in a long-lived opener callback:
               it can contain the captured bytes awaiting an explicit save. *)
            let origin = shown.ic_origin and last_open = shown.ic_last_open in
            let notice = image_notice state ~view:origin.sir_view
              ~keeper_name:origin.sir_keeper in
            let report ~kind ~status message =
              notice ~kind message;
              if not (unsaved_remote_save_in_flight state) then begin
                update_image_link_card state ~path status
              end in
            let still_current () = match state.image_cell_view with
              | Some (Image_cells view) when state.image_open && not state.msx_open
                  && view.ic_copy_path = Some path
                  && view.ic_origin.sir_generation = origin.sir_generation ->
                  Option.is_some (image_cell_origin_for_redraw state
                    ~workspace:view.ic_workspace view.ic_origin)
              | Some (Image_cells _ | Image_cells_withdrawn _) | None -> false in
            if not (still_current ()) || image_cell_source_unconfirmed state origin then
              report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:"Source unconfirmed"
                "Source is unconfirmed; reopen the image to open its link"
            else if asynchronous_input_pending () then
              report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:"Opening cancelled"
                "Opening cancelled while terminal input was pending"
            else begin
              let on_result result = if still_current () then match result with
                | Masc_tui_browser.Opened opener ->
                    report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply ~status:"Opener accepted the request"
                      (opener ^ " accepted the image request")
                | Rejected detail -> report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:"Opener could not start" ("Opener: " ^ detail)
                | Uncertain detail -> report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:"Opener result unknown"
                    ("Opener outcome is unknown: " ^ detail) in
              let use_alternate = key = "x" || key = "X" in
              let target = if use_alternate then alternate else url in
              let after = match use_alternate, last_open with
                | true, Some (previous_target,opener) when String.equal previous_target target -> Some opener
                | (true | false), (Some _ | None) -> None in
              report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply ~status:"Opening requested" "Opening the image target was requested";
              match launch_image_opener ?after ~url:target
                ~allow_start:(fun () -> still_current ()
                  && not (image_cell_source_unconfirmed state origin)
                  && not (asynchronous_input_pending ())) ~on_result () with
              | Ok opener ->
                  record_image_link_opener state ~path ~target opener;
                  if String.equal target path then ignore (keep_pending_image_copy path)
              | Error detail -> report ~kind:Masc_tui_collab_queue.Chat_notice.Notice_failure ~status:detail ("Opener: " ^ detail)
            end;
            true
        | (Some (Image_cells _ | Image_cells_withdrawn _) | None),
          (Some (Key _ | Pasted _ | Graphics_reply _ | Mouse_left_press _ | Mouse_left_drag _
                | Mouse_left_release _ | Mouse_wheel _) | None) -> false in
      let input = if handled_image_copy then None else input in
      let dismissed_image =
        state.image_open && Option.exists Masc_tui_input_reader.is_operator_input input
      in
      if dismissed_image then begin
        close_image state;
        Masc_tui_shell.Terminal_session.invalidate_frame_for_resize frame_presenter render_schedule
      end;
      (* The MSX screen owns the keyboard the same way a showing picture
         does, except it answers keys instead of ending on the first one:
         each is injected into the machine and steps a frame, and only [esc]
         hands the terminal back. Intercepted before [key] is computed, so
         no surface underneath ever sees an emulator's keystroke. *)
      let msx_key =
        if dismissed_image then None
        else if state.msx_open then
          match input with
          | Some (Key name) -> Some name
          | Some (Pasted _) | Some (Graphics_reply _) | Some (Mouse_left_press (_, _))
          | Some (Mouse_left_release (_, _)) | Some (Mouse_wheel (_, _, _)) -> Some ""  (* deliberate non-key input: step, own it *)
          (* The motion between a press and its release is no input of its
             own: the press already stepped, and a drag would repaint the
             machine on every cell it crossed. Nothing under the screen
             reads it either. *)
          | Some (Mouse_left_drag (_, _)) -> None
          | None -> None
        else None
      in
      let room_focused = not state.msx_menu_open
        && Option.fold ~none:false ~some:Masc_tui_play_room.focused state.play_room in
      let room_visible =
        let rows, cols = Masc_tui_ansi.get_terminal_size () in rows >= 8 && cols >= 20 in
      (* Menu decisions, game input and closing own a new view. Pure size or
         non-game input keeps the snapshot current; completion renders using
         the geometry the UI owns at that later instant. *)
      (* On the DOS screen only Esc closes the view; every other key is a
         repaint, and disowning the DOS read in flight there would drop its
         answer, so keys typed steadily would freeze the picture. *)
      (match msx_key, state.machine_source with
       | Some _, _ when room_focused -> ()
       | Some _, (Masc.Machine_lane.Msx | Masc.Machine_lane.Dos)
         when state.msx_menu_open -> retire_machine_view ()
       | Some "esc", (Masc.Machine_lane.Msx | Masc.Machine_lane.Dos) ->
           retire_machine_view ()
       | Some "f5", Masc.Machine_lane.Msx -> retire_machine_view ()
       | Some ("f6" | "f7" | "f8"), Masc.Machine_lane.Msx
         when state.machine_interaction = Control_machine -> retire_machine_view ()
       | Some name, Masc.Machine_lane.Msx
         when state.machine_interaction = Control_machine
              && Option.is_some (Masc_tui_msx.server_key name) ->
           retire_machine_view ()
       | Some _, (Masc.Machine_lane.Msx | Masc.Machine_lane.Dos)
       | None, (Masc.Machine_lane.Msx | Masc.Machine_lane.Dos) -> ());
      (match msx_key with
      | None -> ()
      | Some ("f5" | "f6" | "f7") when state.machine_source = Masc.Machine_lane.Msx
          && Option.is_some (checkpoint_for_workspace state) ->
          Option.iter (inspect_pending_msx_checkpoint state) (checkpoint_for_workspace state);
          state.machine_interaction <- Observe_machine;
          render_spectator state
      (* Switching the observed machine belongs to the whole spectator,
         including its focused conversation. The room keeps its draft/focus. *)
      | Some "f4" when not state.msx_menu_open ->
          (match state.machine_source with
           | Masc.Machine_lane.Msx -> open_dos_screen state ~mailbox:async_messages
           | Masc.Machine_lane.Dos -> open_msx_spectator state ~mailbox:async_messages)
      | Some name when room_focused ->
          Option.iter (fun room ->
            let ko = state.ui_language = Lang_ko in
            let room, intent =
              if not room_visible && not (List.mem name ["esc"; "tab"; "\t"]) then room, Masc_tui_play_room.Repaint
              else match input with
                | Some (Pasted paste) -> Masc_tui_play_room.paste ~ko room paste.Masc_tui_paste.text, Masc_tui_play_room.Repaint
                | Some (Key _ | (Graphics_reply _ | (Mouse_left_press (_, _) | (Mouse_left_drag (_, _) | (Mouse_left_release (_, _) | Mouse_wheel (_, _, _))))))
                | None -> Masc_tui_play_room.key ~ko room name in
            state.play_room <- Some room;
            (match intent with Repaint -> () | Send -> send_play_room state ~mailbox:async_messages)) state.play_room;
          render_spectator state
      | Some ("tab" | "\t") when not state.msx_menu_open ->
          if room_visible then state.play_room <- Option.map (fun room -> Masc_tui_play_room.focus room true) state.play_room;
          render_spectator state
      | Some name when state.msx_menu_open -> (
          (* The load menu owns the keyboard: the lib navigates the picker and
             names the choice, and the I/O it cannot reach -- the load POST, the
             frame fetch -- is done here before handing off to the spectator. *)
          match Masc_tui_msx.menu_consume ~write:write_to_terminal state name with
          | Masc_tui_msx.Stay -> ()
          | Closed ->
              state.msx_menu_open <- false;
              let loaded =
                match state.machine_source, state.dos_live with
                | Masc.Machine_lane.Msx, _ -> Option.is_some state.msx_frame
                | Masc.Machine_lane.Dos, Masc_tui_machine_live.Showing _ -> true
                | Masc.Machine_lane.Dos,
                  (Masc_tui_machine_live.Unread | Masc_tui_machine_live.Not_loaded
                  | Masc_tui_machine_live.Failed _ | Masc_tui_machine_live.Kept_back _) -> false
              in
              if loaded then begin
                (* A game is loaded underneath: fall back to watching it
                   (parity with the Watch arm). *)
                render_spectator state
              end
              else begin
                state.msx_open <- false;
                Masc_tui_shell.Terminal_session.invalidate_frame_for_resize frame_presenter render_schedule
              end
          | Watch source ->
              state.msx_menu_open <- false;
              state.machine_interaction <- Observe_machine;
              state.machine_source <- source;
              render_spectator state
          | (Load cart | Swap_disk cart) as choice ->
              let swapping = match choice with
                | Swap_disk _ -> true
                | Load _ | Stay | Closed | Watch _ -> false
              in
              let request = if swapping then Kept_request.Msx_disk_change else Kept_request.Msx_load in
              run_machine_change state ~mailbox:async_messages ~refused:Fun.id ~unknown:Fun.id
                ~withdrawn:(fun refusal ->
                  Masc_tui_msx.render_menu ~write:write_to_terminal
                    ~status:(workspace_refusal_text ~ko:(state.ui_language = Lang_ko) ~request refusal) state)
                ~deliver:(fun expected_workspace -> function
                  | Ok () ->
                      state.msx_notice <- (if swapping
                        then Some "Disk changed; backup: before-disk-change" else None);
                      state.machine_interaction <- Control_machine;
                      state.msx_menu_open <- false;
                      state.machine_source <- Masc.Machine_lane.Msx;
                      observe_msx_frame ?expected_workspace state ~mailbox:async_messages;
                                          render_spectator state
                  | Error message ->
                      Masc_tui_msx.render_menu ~write:write_to_terminal
                        ~status:((if swapping then "disk change failed: " else "load failed: ")
                          ^ message) state)
                (fun ~port ~expected_workspace ->
                  if swapping then Masc_tui_http.post_msx_change_disk
                    ~expected_workspace ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port ~disk:cart
                  else Masc_tui_http.post_msx_load ~expected_workspace
                    ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port ~cart))
      | Some name when state.machine_source = Masc.Machine_lane.Msx
          && not (machine_changes_allowed state)
          && (List.mem name ["f5"; "f6"; "f7"; "f8"]
              || (state.machine_interaction = Control_machine
                  && Option.is_some (Masc_tui_msx.server_key name))) ->
          state.machine_interaction <- Observe_machine;
          state.msx_notice <- Some machine_change_refusal;
          render_spectator state
      (* A watched machine has no key of its own, so [r] is the operator's
         manual refresh: it owes the visible machine one more read instead of
         only repainting. A machine under Control keeps [r] for the game. *)
      | Some "r"
        when (match state.machine_source with
              | Masc.Machine_lane.Dos -> true
              | Masc.Machine_lane.Msx -> state.machine_interaction = Observe_machine) ->
          owe_machine_live_read state state.machine_source;
          launch_owed_machine_live state ~mailbox:async_messages;
          render_spectator state
      | Some name
        when (match state.machine_source with
              | Masc.Machine_lane.Dos -> true
              | Masc.Machine_lane.Msx ->
                  state.machine_interaction = Observe_machine && name <> "f5")
             && not (List.mem name [ "esc"; "+"; "="; "-"; "_" ]) ->
          (* The DOS screen is watched, not driven: a key that is not the
             spectator's own (leave, size) repaints and never reaches the MSX
             machine -- not as a game key, a checkpoint or a disk change. *)
          render_spectator state
      | Some "f5" ->
          (match state.machine_interaction with
           | Control_machine ->
               state.machine_interaction <- Observe_machine;
               render_spectator state
           | Observe_machine ->
               run_machine_change state ~mailbox:async_messages ~refused:Fun.id ~unknown:Fun.id
                 ~withdrawn:(fun refusal ->
                   state.msx_notice <- Some (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                     ~request:Kept_request.Msx_control refusal);
                   render_spectator state)
                 ~deliver:(fun _expected_workspace result ->
                   (match result with
                    | Ok () -> state.machine_interaction <- Control_machine
                    | Error detail -> state.msx_notice <- Some detail);
                   render_spectator state)
                 (fun ~port:_ ~expected_workspace:_ -> Ok ()))
      | Some "f8" ->
          observe_msx_carts state ~mailbox:async_messages;
          Masc_tui_msx.open_menu ~write:write_to_terminal ~mode:Masc_tui_types.Change_disk state
      | Some (("f6" | "f7") as name) ->
          state.machine_interaction <- Observe_machine;
          Masc_tui_transport.Event_streams.reconcile_observer_machine ~browser_scope:observer_browser_scope state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
            ~mailbox:async_messages;
          launch_owed_machine_live state ~mailbox:async_messages;
          (let restore = name="f7" in
               let requested = ref None in
               run_machine_change ~checkpoint_boundary:true state ~mailbox:async_messages
                 ~refused:(fun detail -> Masc_tui_http.Checkpoint_refused detail)
                 ~unknown:(fun detail -> Masc_tui_http.Checkpoint_outcome_unknown detail)
                 (* Nothing was asked of the server: no intent is retained, so
                    there is no pending checkpoint to forget or inspect. *)
                 ~withdrawn:(fun refusal ->
                   state.msx_notice <- Some (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                     ~request:(if restore then Kept_request.Msx_restore else Kept_request.Msx_checkpoint)
                     refusal);
                                    render_spectator state)
                 ~deliver:(fun _expected_workspace result ->
                   state.msx_notice <- Some (match result with
                     | Ok () -> if restore then "Restore completed; inspecting current workspace screen." else "Saved quick checkpoint."
                     | Error (Masc_tui_http.Checkpoint_refused detail) -> "Checkpoint refused: " ^ detail
                     | Error (Masc_tui_http.Checkpoint_outcome_unknown detail) -> "Checkpoint outcome unknown: " ^ detail);
                   (match !requested with
                    | None -> ()
                    | Some pending ->
                        (match result with
                         | Error (Checkpoint_refused _) -> forget_checkpoint pending
                         | Ok () when not restore -> forget_checkpoint pending
                         | Ok () | Error (Checkpoint_outcome_unknown _) ->
                             state.machine_interaction <- Observe_machine;
                             inspect_pending_msx_checkpoint state pending));
                                    render_spectator state)
                 (fun ~port ~expected_workspace ->
                   let pending = {checkpoint_operation_id=Random_id.uuid_v7 ();
                     checkpoint_restore=restore;checkpoint_slot="quick";
                     checkpoint_workspace=expected_workspace} in
                   match remember_checkpoint pending with
                   | Error detail -> Error (Masc_tui_http.Checkpoint_refused
                       ("Cannot durably retain checkpoint intent: " ^ detail))
                   | Ok () ->
                   requested := Some pending;
                   let result = Masc_tui_http.post_msx_checkpoint ~expected_workspace
                     ~operation_id:pending.checkpoint_operation_id ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port ~restore ~slot:"quick" in
                   (* Knowledge of this operation survives a presentation scope
                      change; never strand a proven refusal behind an old view. *)
                   (match result with
                    | Error (Checkpoint_refused _) -> forget_checkpoint pending
                    | Ok () when not restore -> forget_checkpoint pending
                    | Ok () | Error (Checkpoint_outcome_unknown _) -> ());
                   result))
      | Some "esc" ->
          (* esc closes the spectator; consume returns false and owes a repaint. *)
          if not (Masc_tui_msx.consume ~write:write_to_terminal state "esc")
          then Masc_tui_shell.Terminal_session.invalidate_frame_for_resize frame_presenter render_schedule
      | Some (("+" | "=" | "-" | "_") as size_key) -> (
          (* Local size controls are handled before mapped game keys. The
             observation/control and room-focus branches above have already
             filtered input: + and - resize only this terminal's cached frame
             and never reach the shared machine (RFC-0439 3.3). *)
          Masc_tui_msx.adjust_size
            (if String.equal size_key "-" || String.equal size_key "_" then -1.0 else 1.0);
          render_spectator state)
      | Some name -> (
          (* A game key: send it to the shared server machine (RFC-0439 §3.3),
             then re-fetch so the human sees the result of their own press
             without waiting for the next poll. A key with no server mapping
             (e.g. deliberate non-key input) just repaints the cache. *)
          match Masc_tui_msx.server_key name with
          | Some server_key ->
              run_machine_change state ~mailbox:async_messages ~refused:Fun.id ~unknown:Fun.id
                ~withdrawn:(fun refusal ->
                  state.msx_notice <- Some (workspace_refusal_text ~ko:(state.ui_language = Lang_ko)
                    ~request:Kept_request.Msx_key refusal);
                                  render_spectator state)
                ~deliver:(fun expected_workspace result ->
                  (match result with
                   | Ok _ -> observe_msx_frame ?expected_workspace state ~mailbox:async_messages
                   | Error detail -> state.msx_notice <- Some detail);
                                  render_spectator state)
                (fun ~port ~expected_workspace -> Masc_tui_http.post_msx_press
                  ~expected_workspace ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port ~keys:[ server_key ])
          | None -> render_spectator state));
      (* Async agenda state can change the usable row budget after the last
         paint. Read the compact marker from that paint, not from the newer
         state. An invalidated or not-yet-painted frame stays compact until
         presentation succeeds, so its hidden surface cannot consume input.
         Read once here: the wheel below and the keys after it judge the same
         paint. *)
      let compact_viewport =
        Frame_presenter.last_frame_is_compact frame_presenter
      in
      (* The left button's press, the motion after it and its release are one
         gesture ([Masc_tui_pane_selection]). A release on the cell the press
         landed on is a click, and the press handlers below take it there; a
         drag selects inside the pane the press landed in and is copied when
         the button comes up. Only a frame this program drew can be clicked or
         selected from: while a picture or the machine screen is up it owns
         the pointer, and a gesture under way ends. *)
      let pointer_on_frame =
        (not dismissed_image) && (not compact_viewport)
        && (not state.image_open) && (not state.msx_open)
        && Option.is_none msx_key
      in
      let pointer_outcome =
        match input with
        | Some (Mouse_left_press (row, column)) when pointer_on_frame ->
            pointer_gesture :=
              Masc_tui_pane_selection.press (!presented).panes ~row ~column;
            Masc_tui_pane_selection.Nothing
        | Some (Mouse_left_drag (row, column)) when pointer_on_frame ->
            pointer_gesture :=
              Masc_tui_pane_selection.drag !pointer_gesture ~row ~column;
            Masc_tui_pane_selection.Nothing
        | Some (Mouse_left_release (row, column)) when pointer_on_frame ->
            let outcome =
              Masc_tui_pane_selection.release !pointer_gesture ~row ~column
            in
            pointer_gesture := Masc_tui_pane_selection.Idle;
            outcome
        | Some (Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _) ->
            pointer_gesture := Masc_tui_pane_selection.Idle;
            Masc_tui_pane_selection.Nothing
        | Some (Key _ | Pasted _ | Graphics_reply _ | Mouse_wheel _) | None ->
            Masc_tui_pane_selection.Nothing
      in
      (* Escape lets go of a gesture still held and does nothing else: the
         operator meant the selection, not the surface under it. *)
      let gesture_cancelled =
        match input with
        | Some (Key "esc")
          when Masc_tui_pane_selection.in_progress !pointer_gesture ->
            pointer_gesture := Masc_tui_pane_selection.Idle;
            true
        | Some (Key _ | Pasted _ | Graphics_reply _ | Mouse_left_press _
               | Mouse_left_drag _ | Mouse_left_release _ | Mouse_wheel _)
        | None -> false
      in
      let click =
        match pointer_outcome with
        | Masc_tui_pane_selection.Click { row; column } -> Some (row, column)
        | Masc_tui_pane_selection.Copy _ | Masc_tui_pane_selection.Nothing -> None
      in
      (match pointer_outcome with
       | Masc_tui_pane_selection.Copy selection -> (
           (* The text is read from the rows the terminal shows: what the
              operator selected is what was on screen. *)
           match
             Option.bind
               (Frame_presenter.presented_rows frame_presenter)
               (Masc_tui_pane_selection.text selection)
           with
           | Some text ->
               let outcome = copy_reference render_schedule text in
               let line_count = List.length (Masc_tui_pane_selection.spans selection) in
               report_action state "system"
                 (if state.ui_language = Lang_ko then
                    Printf.sprintf "선택한 %d줄을 %s" line_count
                      (Masc_tui_clipboard.copy_outcome_text_korean outcome)
                  else
                    Printf.sprintf "Selection of %s %s"
                      (Masc_tui_message_layout.count_noun line_count "line")
                      (Masc_tui_clipboard.copy_outcome_text outcome))
           | None -> ())
       | Masc_tui_pane_selection.Click _ | Masc_tui_pane_selection.Nothing -> ());
      let presented_play = play_card_of_reader (!presented).reader in
      let presented_queue = queue_owner_of_reader (!presented).reader in
      let play_was_presented = Option.is_some presented_play in
      let play_wheel_available =
        if not play_was_presented then true
        else play_card_matches ~presented:presented_play ~current:(play_card_shown state) in
      let task_detail_wheel_withdrawn =
        Option.is_some (task_detail_of_reader (!presented).reader)
        && match input with
           | Some (Mouse_wheel (_, row, column)) ->
             acting_pane_hit state ~row ~column = Pane_miss
             && Option.is_none (current_task_detail_presented state)
           | Some (Key _ | Pasted _ | Graphics_reply _ | Mouse_left_press _
                  | Mouse_left_drag _ | Mouse_left_release _) | None -> false in
      (* Where a notch leaves the reader on screen, when it is the reader's:
         not over the Activity pane, which keeps the wheel it had. The frame
         names the reader; the notch moves it from where it is now. *)
      let wheel_reader =
        match input with
        | Some (Mouse_wheel (direction, row, column))
          when (not dismissed_image)
               && (not state.image_open) && (not state.msx_open)
               && Option.is_none msx_key
               && (not compact_viewport)
               && not task_detail_wheel_withdrawn
               && play_wheel_available
               && acting_pane_hit state ~row ~column = Pane_miss ->
            Option.bind (!presented).reader (fun reader ->
                reader_after_wheel (clamped_scroll_now state reader) direction)
        | Some (Key _ | Pasted _ | Graphics_reply _ | Mouse_left_press _
               | Mouse_left_drag _ | Mouse_left_release _ | Mouse_wheel _)
        | None -> None
      in
      let preset_confirmation_wheel = match wheel_reader with
        | Some (Preset_detail_scroll _) -> true
        | None | Some (Task_detail _ | Board_read _ | Message_scroll _
          | Schedule_detail_scroll _ | Keeper_detail _ | Keeper_terminal_scroll _ | Keeper_calls _
          | Keeper_logs_scroll _ | Acting _ | Acting_selection _ | Acting_detail_scroll _ | Memory_fact_detail_scroll _
          | Client_detail_scroll _ | Verification_detail_scroll _ | Harness_detail_scroll _
          | Fusion_detail_scroll _ | Runtime_detail_scroll _ | Runtime_params_scroll _
          | System_log_detail_scroll _ | Planning_confirmation_scroll _ | Planning_detail_scroll _
          | Lane_run_detail_scroll _ | Changes_diff_scroll _ | Repository_changes_diff_scroll _
          | Resource_scroll _ | Metrics_scroll _ | Approval_detail_scroll _
          | Link_modal_scroll _ | Play_invite_scroll _ | Voice_scroll _ | Keeper_list_scroll _
          | Context_inspector_scroll _ | Context_inspector_response_scroll _
          | Queue_panel_presented _ | Help_presented) -> false in
      let key =
        if dismissed_image || Option.is_some msx_key || gesture_cancelled then None
        else
          match input with
          | Some (Key name) -> Some name
          | Some (Mouse_wheel _) when task_detail_wheel_withdrawn -> None
          | Some (Mouse_wheel (direction, _, _)) when help_owns_input ->
              Some (match direction with
                | Masc.Tui_mouse_protocol.Wheel_up -> "up"
                | Masc.Tui_mouse_protocol.Wheel_down -> "down")
          (* A notch over the pane is the pane's and never becomes a key; a
             notch that moves the reader on screen is not one either; a notch
             anywhere else is the key it always was. *)
          | Some (Mouse_wheel (direction, row, column)) -> (
              match acting_pane_hit state ~row ~column with
              | Pane_row _ -> None
              | Pane_miss ->
                  if Option.is_some wheel_reader then None
                  else Some (Masc.Tui_mouse_protocol.wheel_key direction))
          | Some (Pasted _) | Some (Graphics_reply _)
          | Some (Mouse_left_press _) | Some (Mouse_left_drag _)
          | Some (Mouse_left_release _) | None -> None
      in
      (* The field a typed character would land in, read once for the paste
         below. A paste is the characters the operator would have typed, so
         it goes where they would have gone; the exhaustive match is what
         keeps a field added to [text_input_target] from silently dropping
         pasted text the way the palette, row search and the preset name
         each did. *)
      Masc_tui_approvals_model.reconcile_value_reading state;
      reconcile_detail_reading state;
      let _,board_reader_cols=get_terminal_size () in
      prepare_board_read state ~mailbox:async_messages ~cols:board_reader_cols;
      if Option.is_none (current_chat_call_reader state) then Masc_tui_work_requests.Schedule_call_requests.close_chat_call_reader state;
      if Option.is_none (current_task_inspector state) then Masc_tui_chat_dispatch.Task_dispatch.close_task_inspection_reader state;
      let reading_search_editing =
        let editing=Masc_tui_detail_reading.search_editing in
        match current_board_reader state with
        | Some reader -> editing (Masc_tui_board_reader.document reader)
        | None -> match current_chat_call_reader state with
          | Some reader -> editing (Masc_tui_chat_call_reader.document reader)
          | None -> match current_task_inspector state with
            | Some reader -> editing (Masc_tui_original_task_read.document
                (task_inspection_source reader.tci_original))
            | None -> Option.fold ~none:false ~some:editing (current_detail_reading state) in
      let text_target =
        if panel_owns_commands then None
        else if panel_owns_input && current_panel = Some Presented.Context_search then
          Some Text_row_search
        else if not compact_viewport && reading_search_editing then Some Text_row_search
        else text_input_target state ~compact_viewport in
      let play_shown = play_card_shown state in
      let rows, _ = get_terminal_size () in
      let beneath = Masc_tui_render.queue_below_play state ~terminal_rows:rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) in
      let queue_play_owner = queue_play_input_owner ~play_presented:presented_play
          ~play_shown ~compact:compact_viewport ~state ~beneath
          ~viewport:(Option.map (Masc_tui_render_overlays.queue_panel_viewport state) beneath)
          ~presented_queue in
      let presented_queue_input = match queue_play_owner with
        | Queue_input panel -> Some panel
        | Play_input | Wait_for_frame | Other_input -> None in
      let key =
        (* The terminal hands this loop the character an input method produced,
           not the key the operator pressed. In Korean mode a [j] arrives as
           [ㅓ] and matches no spelling below, while control keys and escape
           sequences pass the input method untouched and keep working: every
           letter shortcut was silently dead in Korean mode. The two-set
           layout is reversible, so a context that reads the key as a command
           reads the Latin keys back, replayed exactly as typed. What takes
           characters as text keeps the Hangul: the open field [text_target]
           names, the chat surface's own composer (it takes every printable as
           draft), the roster composer while it holds focus, and the lane
           Add-ons screens typing into a draft, a form or the installer.
           Shift does not survive the input method ([ㅓ] is both [j] and [J]),
           so an uppercase shortcut stays out of reach in Korean mode -- a
           limit of every terminal program, not a spelling this can add.
           A compact viewport is not special here: the compact fallback
           further down owns every key the quit check leaves, so a
           translated letter lands where the English one lands, and an arm
           placed above that fallback has to guard a hidden field for
           English letters exactly as for translated ones. *)
        let command_reading =
          Option.is_none text_target
          && not state.composer_focused
          && not (view_is_chat state.view)
          && Option.for_all
               (fun view -> not (Masc_tui_lane_addons.text_entry_open view))
               state.lane_addons
        in
        (* These panels own the visible keys even when a chat composer is
           underneath them. Translate only a single two-set key here: replaying
           a composed syllable could submit several queue priority changes. *)
        let single_panel_command =
          Option.is_none text_target && not compact_viewport
          && (match key with
              | Some name when String.length name > 1 ->
                  let rows, _ = get_terminal_size () in
                  if panel_owns_commands || Option.is_some presented_queue_input then true
                  else (match Masc_tui_render.frame_choice state ~terminal_rows:rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) with
                   | `Queue _ | `Account_login _ | `Collab _
                   | `Detail_reading _ | `Keeper_deletions | `Link -> true
                   | `Lane_addons view -> not (Masc_tui_lane_addons.text_entry_open view)
                   | `Agenda | `Answering | `Help -> not command_reading
                   | `Too_small _ | `Play_card _ | `Account_server _ | `Palette
                   | `About | `Context | `Client_detail _ | `Surface -> false)
              | Some _ | None -> false)
        in
        match queue_play_owner, key with
        | Wait_for_frame, _ -> key
        | (Queue_input _ | Play_input | Other_input), Some name when single_panel_command ->
            Some (Option.value ~default:name (Masc_tui_key_ime.single_latin_key name))
        | (Queue_input _ | Play_input | Other_input), Some name when command_reading -> (
            match Masc_tui_key_ime.latin_keys name with
            | Some (first :: rest) ->
                List.iter (fun latin_key -> Queue.add latin_key hangul_latin_queue) rest;
                Some first
            | Some [] | None -> Some name)
        | (Queue_input _ | Play_input | Other_input), (Some _ | None) -> key
      in
      let insert_reading_search document insert text =
        if not compact_viewport then begin
          let _,cols=get_terminal_size () in
          let _,height=Masc_tui_render_overlays.detail_reading_viewport state document in
          insert ~width:(Masc_tui_render_overlays.detail_reading_width cols) ~height
            ~text:(Masc_tui_identity_model.identity_field_paste text)
        end in
      let recovered_paste = Option.is_some interrupted_paste in
      let machine_activity_on_screen () =
        state.view = Lanes && Option.is_some state.machine_activity_open
        && not state.help_open
        && (let terminal_rows, _ = get_terminal_size () in
            match Masc_tui_render.frame_choice state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) with
            | `Surface -> true
            | _ -> false)
      in
      let exact_activity_on_screen () =
        state.view = Lanes && Option.is_some state.exact_activity_open
        && not state.help_open
        && (let terminal_rows, _ = get_terminal_size () in
            match Masc_tui_render.frame_choice state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) with
            | `Surface -> true
            | _ -> false)
      in
      (* What a click lands on in the frame on screen. Only marks the
         terminal was shown can answer, and for a frame drawn over a surface
         [render] keeps only the presses that act inside the overlay, so a
         modal's press never changes the surface under it. A field taking keys holds the press too: moving away from
         it would leave the next keys typed into a field no longer drawn.
         While the picture or the machine screen is up nothing is drawn, so
         the last frame's marks are not what the terminal shows; [click] is
         only ever read off a frame this program drew. A click acts when the
         button comes up, so a press that becomes a drag acts on nothing. *)
      let pressed =
        match click with
        | Some (row, column) when Option.is_none text_target ->
            Masc_tui_hit.filter press_is_interactive (!presented).presses
            |> Masc_tui_hit.target_at ~row ~column
        | Some _ | None -> None
      in
      (* The Activity pane row a click landed on. *)
      let acting_pane_click =
        match click with
        | Some (row, column) -> (
            match acting_pane_hit state ~row ~column with
            | Pane_row line -> Some line
            | Pane_miss -> None)
        | None -> None
      in
      let reject_recovered_paste () =
        presented := Presented.reject_recovery !presented;
        report_input_rejection state Masc_tui_action_notice.Paste_rejected
          "Recovered paste was not applied; paste it again after the screen transition"
      in
      (match input with
       (* A paste belongs to the frame the terminal actually accepted. The
          invite response can arrive before that card is painted: in that
          interval a visible reader must keep its input. Once the card was
          presented, its scroll report identifies it above the reader. *)
       | Some (Pasted _) when play_was_presented || Option.is_some presented_queue ->
           if recovered_paste then reject_recovered_paste ()
           else report_input_rejection state Masc_tui_action_notice.Paste_rejected "Paste was not applied on this screen; retry in a text field"
       | Some (Pasted _) when compact_viewport ->
           if recovered_paste then reject_recovered_paste ()
           else report_input_rejection state Masc_tui_action_notice.Paste_rejected "Paste was not applied on this screen; retry in a text field"
       | Some (Pasted _) when Option.is_some beneath && Option.is_none presented_queue
           && queue_play_owner = Wait_for_frame ->
           if recovered_paste then reject_recovered_paste ()
           else report_input_rejection state Masc_tui_action_notice.Paste_rejected "Screen transition: paste was not applied; retry"
       | Some (Pasted paste) when Option.is_some (current_board_reader state) ->
           let reader=state.board_reader in
           insert_reading_search (Masc_tui_board_reader.document reader)
             (fun ~width ~height ~text -> state.board_reader <-
               Masc_tui_board_reader.search_insert ~width ~height ~text reader) paste.Masc_tui_paste.text
       | Some (Pasted paste) when Option.is_some (current_chat_call_reader state) ->
           (match state.chat_call_reader with
            | Some (origin,reader) ->
              insert_reading_search (Masc_tui_chat_call_reader.document reader)
                (fun ~width ~height ~text -> state.chat_call_reader <- Some (origin,
                  Masc_tui_chat_call_reader.search_insert ~width ~height ~text reader)) paste.Masc_tui_paste.text
            | None -> ())
       | Some (Pasted paste) when Option.is_some (current_task_inspector state) ->
           Option.iter (fun reader ->
             let original=reader.tci_original in
             let source=task_inspection_source original in
             insert_reading_search (Masc_tui_original_task_read.document source)
               (fun ~width ~height ~text -> set_task_inspection_source original
                 (Masc_tui_original_task_read.search_insert ~width ~height ~text source))
               paste.Masc_tui_paste.text) (current_task_inspector state)
       | Some (Pasted paste) when Option.is_some (current_detail_reading state) ->
           Option.iter (fun reading ->
             insert_reading_search reading
               (fun ~width ~height ~text -> update_detail_reading state
                 (Masc_tui_detail_reading.search_insert ~width ~height ~text reading)) paste.Masc_tui_paste.text)
             (current_detail_reading state)
       | Some (Pasted _) when state.msx_open -> ()
       | Some (Pasted paste) when Option.is_some state.collab ->
           (* The whole Collab overlay owns paste. Only its visible form may
              receive text; browsing, confirmation and compact frames never
              forward it to a draft or attachment handler underneath. *)
           if text_target = Some Text_collab_form then
             state.collab <- Option.map (fun view ->
               Masc_tui_collab.paste view
                 (Masc_tui_identity_model.identity_field_paste paste.Masc_tui_paste.text))
               state.collab
       | Some (Pasted _) when exact_activity_on_screen () || machine_activity_on_screen () -> ()
       | Some (Pasted paste) when Option.is_some state.lane_addons && not state.palette_open ->
           (match state.lane_addons with
            | Some ({installer=Some installer;_} as view) ->
                state.lane_addons <- Some {view with installer=Some
                  (Masc_tui_lane_installer.paste ~text:paste.Masc_tui_paste.text installer);scroll=0}
            | Some ({ records=Some _;_ } as view) ->
                state.lane_addons <- Some (Masc_tui_lane_addons.paste_records
                  ~text:paste.Masc_tui_paste.text view)
            | Some ({ action_menu=Some {form=Some _;_};_ } as view) ->
                state.lane_addons <- Some (Masc_tui_lane_addons.paste_action
                  ~text:paste.Masc_tui_paste.text view)
            | Some ({ draft = Some draft; _ } as view) ->
                state.lane_addons <- Some { view with draft = Some (draft ^ Masc_tui_identity_model.identity_field_paste paste.Masc_tui_paste.text) }
            | Some _ | None -> ())
       | Some (Mouse_wheel _) | Some (Mouse_left_press _) | Some (Mouse_left_drag _)
       | Some (Mouse_left_release _)
         when Option.is_some state.account_login -> ()
       | Some (Mouse_wheel _) | Some (Mouse_left_press _) | Some (Mouse_left_drag _)
       | Some (Mouse_left_release _)
         when Option.is_some state.lane_addons -> ()
       (* A paste into a one-line field is the text, on one line: no dropped
          file to classify and no spill to disk, both of which are the
          composer's and mean nothing in a field a single row high. A copied
          secret carries the newline that ended it, and a field is not a
          place for one. *)
       | Some (Mouse_wheel _) | Some (Mouse_left_press _) | Some (Mouse_left_drag _)
       | Some (Mouse_left_release _)
         when Option.is_some state.account_login -> ()
       | Some (Pasted _) when state.keeper_deletions_open -> ()
       | Some (Pasted _) when state.about_open -> ()
       | Some (Pasted paste) when Option.is_some state.account_login ->
           if text_target = Some Text_account_login then
             Option.iter (fun view ->
               view.Masc_tui_account_login.ko <- state.ui_language = Lang_ko;
               if paste.Masc_tui_paste.dropped > 0 then
                 view.Masc_tui_account_login.notice <-
                   ui_text state
                     ~ko:"붙여넣기 크기를 초과했습니다. 입력을 나눠 다시 전달하세요."
                     ~en:"Paste exceeded size limit. Split the input and send it again."
               else Masc_tui_account_login.paste view paste.Masc_tui_paste.text)
               state.account_login
       | Some (Pasted paste) when Option.is_some text_target ->
           let text =
             Masc_tui_identity_model.identity_field_paste paste.Masc_tui_paste.text
           in
           (match text_target with
            | None -> ()
            | Some Text_collab_form | Some Text_account_login -> ()
            | Some Text_ask_answer ->
                Masc_tui_operator_actions.Ask_actions.edit_ask_text state (fun draft ->
                  draft ^ Keeper_chat.terminal_safe_text ~preserve_newlines:true
                    paste.Masc_tui_paste.text)
            | Some Text_resource_save ->
                (match Masc_tui_resource_export.path_input paste.Masc_tui_paste.text with
                 | Error detail -> Option.iter (fun prompt -> prompt.rsp_error <- Some detail)
                     state.resource_save_prompt
                 | Ok path -> Option.iter
                     (fun prompt -> prompt.rsp_error <- None;
                       Masc_tui_message_input.insert prompt.rsp_path path)
                     state.resource_save_prompt)
            | Some Text_preset_name ->
                (match state.preset_save_draft_source with
                 | Preset_form_local ->
                   state.preset_save_draft <-
                     Some (Option.value state.preset_save_draft ~default:"" ^ text)
                 | Preset_form_chat _ -> report_action state "system"
                     (ui_text state ~ko:"Esc로 닫고 채팅에서 명령을 수정하세요"
                        ~en:"Press Esc, then edit the command in chat"))
            | Some Text_goal_drop_reason ->
                (match state.goal_action_pending with
                 | Some (Goal_drop_reason entry) ->
                     state.goal_action_pending <-
                       Some (Goal_drop_reason { entry with reason = entry.reason ^ text })
                 | Some (Goal_action_armed _) | None -> ())
            | Some Text_runtime_lane_name ->
                state.runtime_lane_name_draft <-
                  Option.map
                    (fun entry ->
                      Masc_tui_types.lane_name_entry_with_draft entry
                        (Masc_tui_types.lane_name_entry_draft entry ^ text))
                    state.runtime_lane_name_draft
            (* The first paste replaces the selected current value; later
               pastes append, matching typed input. *)
            | Some Text_runtime_param ->
                Option.iter
                  (fun edit ->
                    state.runtime_param_edit <-
                      Some (Masc_tui_types.runtime_param_edit_append edit text);
                    state.runtime_params_notice <- None)
                  state.runtime_param_edit
            | Some Text_runtime_model_form ->
                if not (runtime_form_input_locked state) then begin
                  release_runtime_form_recovery state;
                  state.runtime_model_form <- Option.map (fun form -> Masc_tui_model_form.paste form text) state.runtime_model_form
                end
            | Some Text_runtime_account_form ->
                if not (runtime_form_input_locked state) then begin
                  release_runtime_form_recovery state;
                  state.runtime_account_form <-
                    Option.map (fun form -> Masc_tui_runtime_account_form.paste form text)
                      state.runtime_account_form
                end
            (* The recall and exclusion forms have no text field: a paste is
               dropped, not read as keys. *)
            | Some (Text_memory_recall_form | Text_typesafeai_exclusion_form) -> ()
            | Some Text_voice_wizard ->
                Option.iter
                  (fun session ->
                    state.voice_wizard <-
                      Some (Masc_tui_voice_wizard_session.voice_wizard_append session text))
                  state.voice_wizard
            | Some Text_palette ->
                state.code_finder_file <- Masc_tui_fetched.clear state.code_finder_file;
                state.palette_query <- state.palette_query ^ text;
                state.palette_cursor <- 0
            (* Typing in row search moves the cursor to the first match as
               each character lands, so a paste has to jump the same way or
               the query on screen and the row under it disagree. *)
            (* A pasted runtime id narrows the picker the way typing it
               would. *)
            | Some Text_runtime_picker_filter ->
                state.runtime_lane_pick <-
                  Option.map
                    (fun (pick, list) -> (pick, Masc_tui_pick_list.type_text list text))
                    state.runtime_lane_pick
            | Some Text_keeper_runtime_picker_filter ->
                state.runtime_pick_list <-
                  Masc_tui_pick_list.type_text state.runtime_pick_list text
            | Some Text_skill_source_filter ->
                state.tools_skill_source_picker <- Option.map (fun picker ->
                  { picker with ssp_list = Masc_tui_pick_list.type_text picker.ssp_list text })
                  state.tools_skill_source_picker
            | Some Text_row_search ->
                let longer =
                  Option.value state.search ~default:"" ^ text
                in
                state.search <- Some longer;
                search_jump state ~query:longer ~after:(-1)
            (* A client secret is exactly the thing an operator pastes, and
               the composer path would put it in a chat draft -- a credential
               in a message nobody meant to write. *)
            | Some Text_identity_app_form ->
           Masc_tui_identity_input.paste_form state text
            | Some Text_identity_filter ->
           Masc_tui_identity_input.paste_filter state text
            | Some Text_github_token ->
                Masc_tui_github_ui.paste_token state text
            (* A board post holds many lines, so this one takes the paste
               whole rather than on one line. It does not spill to a file the
               way the chat draft does: that file is written into the keeper's
               workspace for the keeper to read, and a board post has no
               keeper and nowhere to put it. *)
            | Some Text_board_draft ->
                Buffer.add_string state.board_draft
                  (Keeper_chat.terminal_safe_text ~preserve_newlines:true
                     paste.Masc_tui_paste.text)
            (* A path is what an operator pastes, or drops onto the terminal.
               It belongs to the input that is open, not to the post under
               it, where it would be published as text. *)
            | Some Text_board_attach_path ->
                Option.iter
                  (fun input -> Buffer.add_string input text)
                  state.board_compose_attach_input
            (* A prompt holds many lines, like a board post; the form puts
               the text into whichever field its cursor is on. *)
            | Some Text_fusion_launch ->
                (match state.fusion_launch with
                 | Some (Fusion_launch_open launch) ->
                     state.fusion_launch <-
                       Some
                         (Fusion_launch_open
                            (Masc_tui_fusion_launch.paste
                               ~text:
                                 (Keeper_chat.terminal_safe_text ~preserve_newlines:true
                                    paste.Masc_tui_paste.text)
                               launch));
                     state.fusion_scroll <- 0
                 | Some (Fusion_launch_reading_presets _ | Fusion_launch_started _) | None -> ()))
       (* Both sides of this arm are wanted: the guard decides whether a paste
          is handled at all, and the rewrite decides what text it carries. *)
       | Some (Pasted _) when state.view = Approvals && Option.is_some state.ask_text_entry ->
           (* An obscured answer editor cannot redirect its paste to chat. *)
           ()
       | Some (Pasted _) when Option.is_some (browser_lane_on_screen state) ->
           (* The URL field above owns paste while open; a page reader has
              no hidden Keeper composer or attachment destination. *)
           ()
       | Some (Pasted _) when state.keeper_navigation_open ->
           (* Fields above keep their paste. The Keeper list itself has no
              editor, so text and dropped images cannot change the draft
              behind it. *)
           ()
       (* The queue panel, Git Changes, a client detail and every other
          overlay that holds the keys: the draft under it takes no paste. *)
       | Some (Pasted _) when unclaimed_paste state = Paste_held_by_overlay ->
           if recovered_paste then reject_recovered_paste ()
           else report_input_rejection state Masc_tui_action_notice.Paste_rejected "Paste was not applied on this screen; retry in a text field"
       | Some (Pasted _)
         when state.view = Keepers Keeper_message
              && not (Masc_tui_chat_input.Message_keymap.keeper_message_input_supported ~terminal_size:Masc_tui_render_prim.get_terminal_size state) ->
           (* The chat resize notice hides its composer without marking the
              entire frame compact. Match ordinary typing admission before
              classifying a dropped file or changing the hidden draft. *)
           ()
       | Some (Pasted paste)
         when not dismissed_image && not compact_viewport ->
           (* A dropped or Finder-copied file arrives shell-escaped. The
              filesystem is the check that keeps this from touching text that
              merely looks like a path: an existing file is what the operator
              dropped, and anything else is left byte-for-byte as pasted. *)
           (match Masc_tui_paste.unescaped_path paste.Masc_tui_paste.text with
            | Some path when Sys.file_exists path -> (
                match Masc_tui_attachment.classify_drop ~path with
                | Masc_tui_attachment.Attach attachment ->
                    Masc_tui_composer_input.Paste_drop.attach_dropped_image ~protect_recovered:recovered_paste
                      state ~base_path
                      ~mailbox:async_messages attachment
                | Masc_tui_attachment.Keep_path ->
                    Masc_tui_composer_input.Paste_drop.handle_paste ~protect_recovered:recovered_paste state
                      ~base_path ~mailbox:async_messages
                      ~paste:{ paste with Masc_tui_paste.text = path }
                | Masc_tui_attachment.Refuse error ->
                    report_action state "error"
                      (Masc_tui_attachment.error_to_string error))
            | Some _ | None ->
                Masc_tui_composer_input.Paste_drop.handle_paste ~protect_recovered:recovered_paste state
                  ~base_path ~mailbox:async_messages ~paste)
       | Some (Mouse_left_release _ | Mouse_wheel _) when help_owns_input -> ()
       | Some (Mouse_wheel (direction, _, _))
         when state.view = Tools && Option.is_some state.tools_skill_source_picker ->
           if not compact_viewport then Masc_tui_editor_forms.Skill_prompt_forms.handle_skill_source_key state ~mailbox:async_messages ~terminal_session ~page:(Masc_tui_render_tools.skill_source_picker_page state ~terminal_rows:(fst (get_terminal_size ())))
             (match direction with
              | Masc.Tui_mouse_protocol.Wheel_up -> "wheel-up"
              | Wheel_down -> "wheel-down")
       | Some (Mouse_left_release _)
         when state.view = Tools && Option.is_some state.tools_skill_source_picker -> ()
       | Some (Mouse_left_release _) when (play_was_presented || Option.is_some presented_queue)
           && queue_play_owner = Wait_for_frame -> ()
       | Some (Mouse_left_release _) when Option.is_some presented_queue ->
           Option.iter (press_marked_target state ~mailbox:async_messages) pressed
       | Some (Mouse_left_release _) when Option.is_some pressed ->
           Option.iter
             (press_marked_target state ~mailbox:async_messages)
             pressed
       | Some (Mouse_wheel _) when Option.is_some wheel_reader ->
           Option.iter (fun reader ->
             match task_detail_of_reader (Some reader) with
             | Some (offset, _) -> move_task_detail offset
             | None -> apply_clamped_scroll state reader) wheel_reader
       | Some (Mouse_wheel _) when task_detail_wheel_withdrawn -> ()
       | Some (Mouse_wheel _) when queue_play_owner = Wait_for_frame -> ()
       (* Marked panel controls and its reader wheel were handled above.
          Unmarked gestures cannot use stale geometry from a covered view. *)
       | Some (Mouse_left_release _ | Mouse_wheel _) when panel_owns_input -> ()
       (* The wheel over the Activity pane scrolls the pane. The pane is drawn
          under no modal (render reserves it no columns while one is up), so
          the hit test alone says whether the notch is the pane's. *)
       | Some (Mouse_wheel (direction, row, column))
         when (not dismissed_image) && (not compact_viewport)
              && acting_pane_hit state ~row ~column <> Pane_miss ->
           scroll_acting_pane state
             ~delta:
               (match direction with
                | Masc.Tui_mouse_protocol.Wheel_up -> -wheel_notch_rows
                | Masc.Tui_mouse_protocol.Wheel_down -> wheel_notch_rows)
       (* A left click on the Activity pane picks the keeper under it. Same
          modal guards as the Lanes press below, for the same reason. *)
       | Some (Mouse_left_release _)
         when (not (modal_owns_keys state))
              && (not state.palette_open)
              && Option.is_none state.search
              && Option.is_some acting_pane_click ->
           Option.iter
             (fun line ->
               handle_acting_pane_click state ~base_path ~mailbox:async_messages
                 ~line)
             acting_pane_click
       (* A press on a folded Gate row opens what the fold is holding. The
          fold lives on the tool-detail axis, so this selects its full state
          directly even when the keyboard cycle passes through results. Only
          folded rows carry the action, so a press on an open row is not a
          press that quietly did nothing -- there was nothing to open. *)
       | Some (Mouse_left_release _)
         when state.view = Keepers Keeper_message
              && (not (modal_owns_keys state))
              && (not state.palette_open)
              && Option.is_none state.search
              && (match click with
                  | Some (row, column) ->
                      (match Masc_tui_pane_selection.pane_at (!presented).panes ~row ~column with
                       | Some { kind = Masc_tui_pane_selection.Main; _ } -> true
                       | Some { kind = Masc_tui_pane_selection.Roster
                                     | Masc_tui_pane_selection.Activity; _ }
                       | None -> false)
                      && Masc_tui_chat_row_actions.contains
                           ~same_scope:same_acting_pane_scope
                           ~scope:(state.workspace_authority, state.workspace_read_authority)
                           ~keeper:state.msg_target_keeper_name ~row !presented_chat_row_actions
                  | None -> false) ->
           state.msg_tool_visibility <- Tools_full;
           Option.iter
             (fun keeper_name ->
               launch_keeper_chat_tool_details_load ~force:true state
                 ~mailbox:async_messages ~keeper_name)
             state.msg_target_keeper_name
       (* A graphics reply is read and dropped. Nothing asks for one outside
          the capability probe, which does its own reading before the loop
          starts; what matters here is that it does not become keys. *)
       | Some (Pasted _) | Some (Graphics_reply _) | Some (Key _)
       | Some (Mouse_left_press _) | Some (Mouse_left_drag _)
       | Some (Mouse_left_release _) | Some (Mouse_wheel _) | None -> ());
      if Option.is_some input then
        Render_schedule.request render_schedule Render_schedule.Input;
      let reads_before = Masc_tui_refresh_settlement.System_log_stream.reads_in_flight state in
      reconcile_chat_listen state;
      ensure_acting_pane_changes state ~mailbox:async_messages;
      launch_owed_history state ~mailbox:async_messages;
      launch_owed_fusion state ~mailbox:async_messages;
      launch_owed_keeper_composite state ~mailbox:async_messages;
      launch_owed_keeper_logs state ~mailbox:async_messages;
      launch_owed_keeper_calls state ~mailbox:async_messages;
      launch_owed_board_post state ~mailbox:async_messages;
      launch_owed_gate_snapshot state ~mailbox:async_messages;
      launch_owed_held_calls state ~mailbox:async_messages;
      launch_owed_keeper_turns state ~mailbox:async_messages;
      launch_owed_verification state ~mailbox:async_messages;
      launch_owed_repositories state ~mailbox:async_messages;
      launch_owed_memory_health state ~mailbox:async_messages;
      launch_owed_memory_world state ~mailbox:async_messages;
      launch_owed_runtime_surface state ~mailbox:async_messages;
      launch_owed_overview state ~mailbox:async_messages;
      launch_owed_runtime_config state ~mailbox:async_messages;
      launch_owed_connectors state ~mailbox:async_messages;
      launch_owed_harness state ~mailbox:async_messages;
      launch_owed_overview state ~mailbox:async_messages;
      launch_owed_clients state ~mailbox:async_messages;
      step_engine_samples state ~mailbox:async_messages ~render_schedule;
      Masc_tui_refresh_settlement.System_log_stream.reconcile_system_log_stream state ~mailbox:async_messages;
      launch_owed_identity_logins state ~mailbox:async_messages;
      launch_owed_ask_followup state ~mailbox:async_messages;
      launch_owed_keeper_waiting state ~mailbox:async_messages;
      launch_owed_tool_modes state ~mailbox:async_messages;
      launch_owed_asks state ~mailbox:async_messages;
      launch_owed_async_requests state ~mailbox:async_messages;
      launch_owed_tools_async_detail state ~mailbox:async_messages;
      launch_owed_tools_async_task state ~mailbox:async_messages;
      launch_owed_tools state ~mailbox:async_messages;
      launch_owed_keeper_roster state ~mailbox:async_messages;
      Masc_tui_refresh_settlement.Approvals_asks_settlement.launch_owed_pending_confirms state ~mailbox:async_messages;
      launch_owed_schedules state ~mailbox:async_messages;
      launch_owed_keeper_schedules state ~mailbox:async_messages;
      launch_owed_keeper_story_turns state ~mailbox:async_messages;
      launch_owed_memory state ~mailbox:async_messages;
      launch_owed_chat_journals state ~mailbox:async_messages;
      launch_owed_refresh_pass ~server_contact state ~refresh_inflight:http_refresh_inflight
        ~scoped_refresh_inflight:http_scoped_refresh_inflight ~scoped_refresh_followup
        ~mailbox:async_messages;
      launch_owed_board_list ~server_contact state ~refresh_inflight:http_scoped_refresh_inflight
        ~full_refresh_inflight:http_refresh_inflight ~scoped_refresh_followup
        ~mailbox:async_messages;
      launch_owed_planning ~server_contact state ~refresh_inflight:http_scoped_refresh_inflight
        ~full_refresh_inflight:http_refresh_inflight ~scoped_refresh_followup
        ~mailbox:async_messages;
      launch_owed_pushed_reads ~server_contact state ~refresh_inflight:http_scoped_refresh_inflight
        ~full_refresh_inflight:http_refresh_inflight ~scoped_refresh_followup
        ~mailbox:async_messages;
      (* The Fusion launch form outlives nothing: whatever moved the surface
         -- a key, the Activity pane's mouse handler, or an async message
         that jumps to a Keeper chat -- it is gone before this iteration
         dispatches anything. *)
      if Masc_tui_types.reconcile_fusion_launch state then
        report_action state "system"
          "Fusion launch left while its answer was out; the run may have started - r refreshes the list";
      Masc_tui_types.reconcile_keeper_story state;
      let _terminal_rows, terminal_columns = get_terminal_size () in
      let message_mode =
        (not compact_viewport) && view_is_chat state.view
        && not state.repository_changes_open
      in
      (* An unrelated key disarms lane removal below, but must not then be
         handed to the listing that the parent covered. *)
      let runtime_parent_before_input =
        if state.view = Runtime then Masc_tui_types.runtime_parent state else None
      in
      (* The opening screen's help-door line retires on the first input of
         any kind: the reader is driving now, and the doors it named -- the
         footer item, the sheet -- stay on every screen without it. A paste
         counts too; a wheel notch does not, because it can be a scroll
         that never looked at the line. The write goes to the same
         [tui] table the other one-time choices do, and a write that
         cannot complete says so in the action slot rather than failing
         the input it interrupted. *)
      (match input with
       | Some (Key _ | Pasted _) when not state.help_hint_shown ->
           state.help_hint_shown <- true;
           Masc_tui_shell.Preferences.store state Masc.Tui_preference.Help_hint_retired
       | Some (Key _ | Pasted _)
       | Some (Graphics_reply _)
       | Some (Mouse_left_press _ | Mouse_left_drag _ | Mouse_left_release _)
       | Some (Mouse_wheel _)
       | None -> ());
      (* Panel input cannot confirm an action belonging to the covered
         surface. Global quit keeps its existing, separate key policy. *)
      let confirmation_key = if panel_owns_input then None else key in
      let quit_input_key = if help_owns_input then None else key in
      let quit_key =
        match quit_input_key with
        (* The account server screen's own rule, not the covered surface's:
           a chat underneath would read q as text, and an About, collab or
           queue panel left in state would withhold it. The arm below and the
           withdrawal of an armed quit read this same answer. *)
        | Some k when panel_owns_input && current_panel = Some Presented.Account_server ->
            Render_schedule.Input_shortcut.is_quit ~message_mode:false k
        | Some k ->
            (* On a viewport too small to draw them, no field is taking keys:
               the compact fallback further down owns every remaining one, so
               yielding there would leave the operator on a terminal they
               cannot read with no way out but Ctrl-C. *)
            (compact_viewport || not state.about_open)
            && (compact_viewport || Option.is_none state.collab)
            && (compact_viewport || Option.is_none state.account_login)
            && (compact_viewport || Option.is_none state.queue_panel)
            && (compact_viewport
               || quit_key_allowed_for text_target)
            && Render_schedule.Input_shortcut.is_quit ~message_mode k
        | None -> false
      in
      let handle_quit_key () =
        let confirmed = match quit_before_input, state.quit_armed with
          | Some before, Some arm ->
              Masc_tui_action_notice.same_quit before arm.qa_confirmation
              && quit_arm_matches state arm
              && Option.exists (Masc_tui_action_notice.same_quit before)
                   (last_visible_quit
                      ~presented_rows:(Frame_presenter.presented_rows frame_presenter) ())
              && (match Masc_tui_action_notice.ordinary state.last_action with
                  | None -> true
                  | Some ordinary -> ordinary == Masc_tui_action_notice.quit_ordinary before)
              && Unix.gettimeofday () -. snd (Masc_tui_action_notice.quit_ordinary before)
                 <= last_action_window_s
              && not (Masc_tui_exit_signals.interrupt_pending exit_signals)
          | (Some _ | None), (Some _ | None) -> false in
        if confirmed then begin
          Masc_tui_shell.Exit_journal.note Masc_tui_exit_reason.Quit_key;
          raise Masc_tui_shell.Exit_journal.Break
        end else begin
          Masc_tui_shell.Quit_guard.arm state ~kind:Masc_tui_action_notice.Quit_key ~key:"q"
        end in
      let input_seen = Option.is_some input || rejected_operator_input in
      (* Exit confirmation belongs only to two consecutive quit keys. A paste,
         a mouse report, or any other key means the operator stayed. *)
      if input_seen && not quit_key then Masc_tui_shell.Quit_guard.withdraw state;
      (* An armed shutdown expires on the next unrelated input. Otherwise it
         waits indefinitely and a later press of the same key -- after the
         cursor has moved, after a refresh -- submits work the operator armed
         minutes ago for something else. Same rule for every other armed
         action here, and the same one the quit confirmation above already
         uses: deliberate input that is not the second press ends it.

         One predicate rather than one restatement per field. The connector
         unbind used to spell the rule itself and read a loop turn that
         fetched no input as an unrelated key, so its arm survived a single
         iteration. The viewport is not part of the rule: an armed
         destructive action must not outlive the moment it was armed in,
         least of all across a resize the operator cannot see it through. *)
      let cancelled second_press =
        Masc_tui_keys.cancels_two_press
          ~input_seen ~key:confirmation_key ~second_press
      in
      (* A view change that no key caused, such as a dispatched task opening
         its surface, leaves the presets pane without passing through the
         Config arm below. A delete cannot be put back, so the first input
         seen anywhere else ends the arm. *)
      if state.view <> Config && input_seen then state.preset_armed <- None;
      (* Same rule for the Skills list: a surface change with no key, such as
         a dispatched task opening its view, must not keep a delete armed. *)
      if state.view <> Tools && input_seen then begin
        state.tools_skill_delete_armed <- None;
        state.volume_gc <- Masc_tui_volume_gc.disarm state.volume_gc;
        (* What [goto_surface] ends on leaving Tools, for the views a send
           or a browser lane opens without it: the next visit starts on the
           Skill list, and an open request does not outlive the screen. *)
        state.tools_skill_focus <- Choosing_skill;
        if state.tools_async_detail_open then Masc_tui_work_requests.Tools_task_requests.close_tools_async_detail state
      end;
      (match state.view with
       | Approvals ->
           if cancelled [ "y"; "Y"; "n"; "N" ] then
             state.pending_approval_action <- None
       | Keepers _ ->
           (match state.keeper_action_pending with
            | None -> ()
            | Some pending ->
              let confirm = Keeper_control.action_key pending.pending_action in
              if cancelled [confirm; String.uppercase_ascii confirm]
              then state.keeper_action_pending <- None)
       | Board -> if cancelled [ "v"; "V" ] then state.board_vote_armed <- None
       | Planning ->
           (* A drop reason is a field, not an armed key: its own Esc and
              Enter end it, and every other key is a letter of the reason.
              A compact frame does not draw the field, so there the reason
              ends on the next key like any armed action. *)
           (match state.goal_action_pending with
            | Some (Goal_drop_reason _) when not compact_viewport -> ()
            | Some (Goal_action_armed armed) ->
                let current = Option.exists (fun goal ->
                  String.equal goal.pg_id armed.goal_id
                  && planning_goal_retains_arm goal ~action:armed.action
                       ~phase:armed.phase ~retry_binding:armed.retry_binding)
                    (Masc_tui_work_actions.Goal_actions.goal_detail_on_screen state) in
                if not current || cancelled (planning_action_confirmation_keys armed.action) then
                  state.goal_action_pending <- None
            | Some (Goal_drop_reason _) ->
                if input_seen then state.goal_action_pending <- None
            | None -> ());
           (* Scrolling reads the exact proof; leaving it invalidates pending
              reads as well as an already displayed confirmation binding. *)
           if cancelled [ "a"; "A"; "j"; "k"; "up"; "down";
                          "pageup"; "pagedown"; "home"; "end";
                          "wheel-up"; "wheel-down" ] then
             (match state.goal_confirmation with
              | Goal_confirmation.Inspecting read ->
                  state.goal_confirmation <- Goal_confirmation.Inspecting
                    (Goal_confirmation_read.clear read)
              (* Leaving the proof cancels a read, but cannot unsend a POST. *)
              | Goal_confirmation.Submitting _ -> ())
       | Schedules ->
           if cancelled [ "x"; "X" ] then state.schedule_cancel_armed <- None
       | Verification ->
           if cancelled [ "a"; "A" ] then
         state.verification_verdict_armed <- None
       | Config ->
           (* A restore rewrites three surfaces and a delete removes a preset;
              an arm must not outlive the keypress that set it, and only its
              own key confirms it. *)
           (match state.preset_armed with
            | None -> ()
            | Some (Restore_armed _) ->
                if cancelled [ "u"; "U" ] then state.preset_armed <- None
            | Some (Delete_armed _) ->
                if cancelled [ "D" ] then state.preset_armed <- None
            | Some (Save_armed _ | Save_workspace_armed _) ->
                if not preset_confirmation_wheel
                   && cancelled [ "\r"; "\n"; "enter"; "pageup"; "pagedown"; "home"; "end" ]
                then state.preset_armed <- None)
       | Runtime ->
           if cancelled [ "D" ] then state.runtime_lane_remove_armed <- None
       | Tools ->
           (* A Skill deletion arm ends the same way every armed destructive
              action here does: any input that is not its own second press. *)
           if cancelled [ "d"; "D" ] then state.tools_skill_delete_armed <- None;
           if cancelled [ Masc_tui_volume_gc.key ] then
             state.volume_gc <- Masc_tui_volume_gc.disarm state.volume_gc
       | Overview | Acting | Metrics | Lanes | Clients | Harness | Memory | Fusion
       | Repositories
       | Changes | Connectors | Resources
       | System_logs | Code -> ());
      (* Destructive binding removal deliberately requires two consecutive
         [u] presses. Any intervening action invalidates the ownership
         snapshot; the server also compares that owner inside the store lock.
         Not scoped to the Channels tab: an arm the operator left behind on
         another surface is exactly the stale confirmation this cancels. *)
      if cancelled [ "u" ] then state.connector_unbind_armed <- None;
      if cancelled [ "U" ] then state.connector_unbind_all_armed <- None;
      (* The pause offer takes one key. Anything else -- or any key read
         before the offer reached the screen, typed for something else --
         drops it, and that key keeps its own meaning. *)
      let accepted_unbind_offer =
        match state.connector_unbind_offer with
        | None -> None
        | Some offer -> (
            match
              Masc_tui_connector_unbind.read_offer_input offer
                ~frames_presented:state.frames_presented
                ~input_seen ~key:confirmation_key
            with
            | Masc_tui_connector_unbind.Offer_waits -> None
            | Masc_tui_connector_unbind.Offer_accepted -> Some offer
            | Masc_tui_connector_unbind.Offer_dropped ->
                state.connector_unbind_offer <- None;
                None)
      in
      (* The composer sees the key first, and takes it only when it has one to
         take: unfocused it claims a single key, and only with somewhere to
         send. Everything it does not claim reaches the surface with its
         meaning unchanged, so no existing binding moved when the row
         appeared. The chat surface is excluded — it draws its own composer. *)
      (* A cursor left over a pane this frame did not draw would come back
         on a stale row when the pane returns; it goes down here, before
         any key reads it. *)
      if Option.is_some state.acting_pane_cursor && not (acting_pane_drawn state)
      then state.acting_pane_cursor <- None;
      let composer_claimed =
        Option.is_none state.account_login && Option.is_none state.lane_addons &&
        not panel_owns_input &&
        (not compact_viewport)
        && (match queue_play_owner with Wait_for_frame -> false
            | Queue_input _ | Play_input | Other_input -> true)
        (* Surface inspection and Dashboard Keeper selection precede an
           unfocused composer's entry key. A focused composer still owns
           every typed character, including i. *)
        && not ((not state.composer_focused)
          && (match state.view with
              | Overview -> key = Some "i"
              | Resources ->
                  key = Some "i" && state.resource_focus = Right_pane
              | Config ->
                  key = Some "i" && state.config_pane = Config_prompts
              | Lanes ->
                  (key = Some "d" || key = Some "i")
                  && state.lanes_mode = Lanes_overview
                  && Option.is_none state.slot_editor
                  && Option.is_none state.runtime_lane_pick
              | Keepers (Keeper_list | Keeper_detail | Keeper_logs
                        | Keeper_calls | Keeper_message | Keeper_runtime_pick)
              | Acting | Metrics | Memory | Clients | Board | Approvals
              | Planning | Schedules | Verification | Harness | Fusion
              | Repositories | Code | Changes | Connectors | Runtime
              | Tools | System_logs -> false))
        && (not (modal_owns_keys state))
        (* Any open field takes the key before the composer does. This was six
           conditions naming six fields, and the ones added later were not in
           it: typing an endpoint name containing [i] in the voice wizard put
           the [i] into a keeper message and sent the rest of the word after
           it. Asking whether a field is open at all is the same question the
           six were circling, and it cannot fall behind a new field. *)
        && Option.is_none (text_input_target state ~compact_viewport)
        && not (view_is_chat state.view)
        && not state.keeper_navigation_open
        && key <> Some Masc_tui_shell.Terminal_session.toggle_mouse_tracking_key
        && key <> Some Masc_tui_shell.Terminal_session.toggle_roster_pane_key
        && key <> Some Masc_tui_shell.Terminal_session.toggle_acting_pane_key
        && key <> Some Masc_tui_shell.Terminal_session.toggle_browser_lane_key
        &&
        match key with
        | Some k -> Masc_tui_composer_input.Composer_key.handle_composer_key
              ~terminal_size:Masc_tui_render_prim.get_terminal_size
              ~wheel_notch_rows
              ~withdraw_resource_diagram_pending:(fun () -> withdraw_resource_diagram_pending state)
              ~launch_keeper_history_load:(fun ~keeper_name -> launch_keeper_history_load state ~mailbox:async_messages ~keeper_name)
              ~send_operator_text:(fun ~keeper_name snapshot -> send_operator_text ~keeper_name state ~base_path ~mailbox:async_messages snapshot)
              ~paste_clipboard_image:(fun () -> paste_clipboard_image state)
              ~open_named_image:(fun () -> open_named_image state ~mailbox:async_messages)
              ~launch_keeper_chat_tool_details_load:(fun ~keeper_name -> launch_keeper_chat_tool_details_load ~force:true state ~mailbox:async_messages ~keeper_name)
              state ~base_path ~mailbox:async_messages k
        | None -> false
      in
      (* What [r] refreshes on every surface, the Git-changes overlay
         included. The overlay's arm and the surface arm below both start
         here; only the reload that follows differs. *)
      let refresh_shared_sources () =
        state.pending_approval_action <- None;
        Masc_tui_theme_choice.invalidate_cache ();
        Masc_tui_transport.Local_sources.launch_workspace_read state ~mailbox:async_messages ~intent:Snapshot_read.Refresh base_path;
        let host = Masc_tui_transport.Workspace_admission.server_peer_host in
        let port = state.port in
        start_http_refresh ~server_contact state ~host ~port ~intent:Operator_key
          ~refresh_inflight:http_refresh_inflight
          ~scoped_refresh_inflight:http_scoped_refresh_inflight
          ~scoped_refresh_followup
          ~mailbox:async_messages;
        (* Each source owns its read even while the whole-surface refresh
           is busy. Cadence reads share these requests rather than
           superseding them before their responses can arrive. They start
           after the revalidation owes them a read, so each answers that
           debt instead of being overtaken by it. *)
        (match state.connection_status with
         | Booting | Account_server _ -> ()
         | Disconnected | Connecting | Degraded | Connected ->
           Masc_tui_work_requests.Approval_gate_requests.launch_keeper_tool_approvals_load ~intent:Snapshot_read.Refresh
             state ~mailbox:async_messages;
           Masc_tui_work_requests.Approval_gate_requests.launch_gate_snapshot_load ~intent:Snapshot_read.Refresh
             state ~mailbox:async_messages;
           (* Off Schedules only the agenda strip is drawn, so a later page
              the operator left is not read. *)
           if state.view = Schedules then
             Masc_tui_work_requests.Schedule_call_requests.launch_schedules_load ~intent:Snapshot_read.Refresh
               state ~mailbox:async_messages
           else
             Masc_tui_work_requests.Schedule_call_requests.launch_schedule_agenda_load ~intent:Snapshot_read.Refresh
               state ~mailbox:async_messages)
      in
      (match key, browser_lane_on_screen state with
       | Some _, Some view ->
           state.browser_lane <- Some (Browser_lane_view.yield_refresh_to_input view)
       | None, _ | Some _, None -> ());
      let handle_row_search_key k =
           let query = Option.value state.search ~default:"" in
           (match k with
            | "esc" -> state.search <- None
            | "\r" ->
                state.search <- None;
                state.search_last <- query
            | "\127" | "\b" ->
                let shorter =
                  Masc_tui_message_layout.drop_last_utf8_scalar query
                in
                state.search <- Some shorter;
                search_jump state ~query:shorter ~after:(-1)
            | s
              when (String.length s = 1 && Char.code s.[0] >= 32)
                   || (String.length s > 1 && Char.code s.[0] >= 0x80) ->
                let longer = query ^ s in
                state.search <- Some longer;
                search_jump state ~query:longer ~after:(-1)
            | _ -> ())
      in
      (* The cheat sheet's keys. [Masc_tui_help.step] says what a key does in
         the filter's current state; this applies it to the sheet. *)
      let handle_help_key k =
           (match
              Masc_tui_help.step state.help_filter ~scope:state.help_scope
                ~key:k
            with
            | Masc_tui_help.Set_filter { filter; scroll_to_top } ->
                state.help_filter <- filter;
                if scroll_to_top then state.help_scroll <- 0
            | Masc_tui_help.Widen ->
                state.help_scope <- Masc_tui_help.Everything;
                state.help_scroll <- 0
            | Masc_tui_help.Close ->
                state.help_open <- false;
                state.help_scroll <- 0;
                state.help_filter <- Masc_tui_help.Off;
                state.help_scope <- Masc_tui_help.Here
            | Masc_tui_help.Toggle_hints ->
                (* Session toggle; the persistent form is [tui].hints_visible in
                   runtime.toml, named on the help sheet itself. *)
                state.hints_visible <- not state.hints_visible;
                note_session_key state Masc.Tui_preference.Key.Hints_visible
            | Masc_tui_help.Scroll move ->
                (* Bounded against the sheet the frame draws, which folds to
                   two columns on a wide terminal and so holds half the rows
                   the lines were written as. *)
                let count, height = Masc_tui_render.help_viewport state in
                state.help_scroll <-
                  Masc_tui_scroll.apply_move ~count ~height move
                    state.help_scroll
            | Masc_tui_help.Ignore -> ())
      in
      let toggle_roster_chrome () =
           if state.keeper_navigation_open then begin
             state.keeper_navigation_open <- false;
             state.keeper_message_focus <- Right_pane;
             if terminal_columns >= Masc_tui_roster_pane.threshold_cols then
               state.roster_pane_preference <- Masc_tui_roster_pane.Hidden
           end else if Masc_tui_roster_pane.hides_roster state.pane_zoom then begin
             if terminal_columns >= Masc_tui_roster_pane.threshold_cols then begin
               (* Step Full -> Half rather than Normal so the right Activity
                  pane stays collapsed and the checked [terminal_columns] width
                  remains available for the roster on 158..183-col terminals. *)
               state.pane_zoom <- Masc_tui_roster_pane.Half;
               state.roster_pane_preference <- Masc_tui_roster_pane.Shown;
               reconcile_chat_focus ();
               Render_schedule.request render_schedule Render_schedule.Force
             end else
               report_action state "system"
                 (Printf.sprintf
                    "Keeper roster needs %d columns; preference unchanged"
                    Masc_tui_roster_pane.threshold_cols)
           end else (match
              Masc_tui_roster_pane.toggle_preference state.roster_pane_preference
                ~cols:terminal_columns
            with
            | None ->
                report_action state "system"
                  (Printf.sprintf
                     "Keeper roster needs %d columns; preference unchanged"
                     Masc_tui_roster_pane.threshold_cols)
            | Some preference ->
                state.roster_pane_preference <- preference;
                reconcile_chat_focus ();
                Render_schedule.request render_schedule Render_schedule.Force)
      in
      let toggle_activity_chrome () =
           (match toggle_acting_pane state with
            | Error reason -> report_action state "system" reason
            | Ok _ -> Render_schedule.request render_schedule Render_schedule.Force)
      in
      (match key with
       (* Above the modals on purpose: the reason to reach for this is to copy
          something already on the screen, and the help overlay is one of the
          screens worth copying from. *)
       | Some k when String.equal k Masc_tui_shell.Terminal_session.toggle_mouse_tracking_key ->
           Masc_tui_shell.Terminal_session.toggle_mouse_tracking terminal_session;
           (* Handed to the terminal, the button's release never comes here. *)
           pointer_gesture := Masc_tui_pane_selection.Idle;
           Render_schedule.request render_schedule Render_schedule.Force
       (* The compact fallback, including after invalidation, owns keys before
          every hidden modal. Its advertised quit key remains available. *)
       | Some _ when compact_viewport ->
           if quit_key && Option.is_some (Frame_presenter.presented_rows frame_presenter)
           then handle_quit_key ()
       | Some k when help_owns_input -> handle_help_key k
       (* The account server screen takes every key: r reads /health again, q
          quits, and no operator binding fires under it. *)
       | Some k when panel_owns_input && current_panel = Some Presented.Account_server ->
           if quit_key then handle_quit_key ()
           else (match k with
             | "r" ->
                 start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
                   ~intent:Operator_key ~refresh_inflight:http_refresh_inflight
                   ~scoped_refresh_inflight:http_scoped_refresh_inflight
                   ~scoped_refresh_followup ~mailbox:async_messages
             | _ -> ())
       | Some "?" when Option.is_some current_panel
                       && current_panel <> Some Presented.Context_search ->
           state.help_open <- true;
           state.help_scroll <- 0
       | Some "esc" when panel_owns_input && current_panel = Some Presented.About ->
           state.about_open <- false;
           state.emblem_frame <- -1;
           state.quit_armed <- None
       | Some _ when panel_owns_input && current_panel = Some Presented.About
                     && Masc_tui_emblem_screen.drawn () = Masc_tui_emblem_screen.Moving
                     && state.emblem_frame < Masc_tui_emblem_screen.final_frame ->
           state.emblem_frame <- Masc_tui_emblem_screen.final_frame;
           state.quit_armed <- None;
           Render_schedule.request render_schedule Render_schedule.Force
       | Some _ when panel_owns_input && quit_key -> handle_quit_key ()
       | Some k when panel_owns_input && String.equal k Masc_tui_shell.Terminal_session.toggle_roster_pane_key ->
           toggle_roster_chrome ()
       | Some k when panel_owns_input && String.equal k Masc_tui_shell.Terminal_session.toggle_acting_pane_key ->
           toggle_activity_chrome ()
       | Some k when panel_owns_input && current_panel = Some Presented.Context_search ->
           handle_row_search_key k

       | Some k
         when panel_owns_input && current_panel = Some Presented.Context ->
           let exact_input_items () =
             match state.context_inspector_reading with
             | None -> []
             | Some (_, reading) ->
                 Option.fold ~none:[] ~some:Masc_tui_context_inspector.exact_input_items
                   (Masc_tui_context_inspector.observed_input reading)
           in
           let input_map_rows () =
             match state.context_inspector_reading with
             | None -> []
             | Some (_, reading) ->
                 (match Masc_tui_context_inspector.inspected_record
                          ~target:state.context_inspector_target reading with
                  | None -> []
                  | Some record ->
                      Masc_tui_context_inspector.input_map_rows record
                        (Masc_tui_context_inspector.observed_input reading))
           in
           let scroll_plain_body = match state.context_inspector_reading with
             | Some (_, reading) ->
                 Masc_tui_context_inspector.scroll_plain_body
                   ~tab:state.context_inspector_tab
                   ~target:state.context_inspector_target reading
             | None -> false in
           let close () = close_context_inspector state in
           (match k with
            | "esc" when state.context_inspector_tab = Masc_tui_context_inspector.Response ->
                enter_context_inspector_tab state state.context_inspector_response_return
            | "esc" ->
                (match state.context_inspector_exact with
                 | Some _ ->
                     state.context_inspector_exact <- None;
                     state.context_inspector_scroll <- 0
                 | None -> close ())
            | "[" | "]" ->
                (* Turn navigation: [ steps back through the page's rows, ]
                   steps forward, and the fetch re-reads the exact provider
                   input for the row they name. The keys work on every tab;
                   a row without a snapshot says so on the request tab. *)
                let count =
                  match state.context_inspector_reading with
                  | Some
                      ( _
                      , Masc_tui_context_inspector.Turn_read
                          { selection = { Masc_tui_context_inspector.rows; _ }
                        ; _ } ) ->
                      List.length rows
                  | Some (_, (Masc_tui_context_inspector.Request_failed _ | Masc_tui_context_inspector.Turn_read_failed _ | Masc_tui_context_inspector.Exact_read _))
                  | None -> 0
                in
                (match Masc_tui_context_inspector.step_recent state.context_inspector_target
                         ~older:(String.equal k "[") ~count with
                 | None -> ()
                 | Some target ->
                     let forecast =
                       match state.context_inspector_reading, state.context_inspector_keeper with
                       | Some (reading_keeper, reading), Some keeper_name
                         when String.equal reading_keeper keeper_name ->
                           Masc_tui_context_inspector.retained_forecast reading
                       | Some _, _ | None, _ -> None
                     in
                     state.context_inspector_target <- target;
                     state.context_inspector_reading <- None;
                     state.context_inspector_read_at <- None;
                     state.context_inspector_cursor <- 0;
                     state.context_inspector_exact <- None;
                     state.context_inspector_scroll <- 0;
                     state.context_inspector_detail_scroll <- 0;
                     state.context_inspector_response_scroll <- 0;
                     supersede_context_inspector_part_load state None;
                     state.context_inspector_part <- Masc_tui_fetched.clear state.context_inspector_part;
                     Option.iter
                       (fun keeper_name -> Masc_tui_chat_dispatch.Chat_journals.launch_context_inspector_load ?forecast state
                          ~mailbox:async_messages ~keeper_name)
                       state.context_inspector_keeper)
            | "/" when
                state.context_inspector_tab
                = Masc_tui_context_inspector.Exact_input
                && Option.is_none state.context_inspector_exact
                && Option.is_some state.context_inspector_reading ->
                (* The inspector owns this editor even if an asynchronous
                   surface form arrived underneath it. *)
                state.search <- Some "";
                Option.iter (fun owner ->
                    presented := Presented.begin_context_search !presented owner)
                  (context_search_owner ())
            | ("n" | "N") when state.search_last <> "" ->
                let after = Option.value (search_row_cursor state) ~default:0 in
                search_jump state ~query:state.search_last ~after
                  ~backwards:(String.equal k "N")
            | "r" ->
                Option.iter
                  (fun keeper_name ->
                     (* Historical sources have no dependency on today's catalogue. *)
                     (match state.context_inspector_target, state.context_inspector_tab with
                      | Masc_tui_context_inspector.Recent _, Masc_tui_context_inspector.Composition ->
                          Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load ~intent:Snapshot_read.Refresh state ~mailbox:async_messages
                      | Masc_tui_context_inspector.Recent _,
                        (Masc_tui_context_inspector.Exact_input | Input_map | Response)
                      | Masc_tui_context_inspector.Pinned _,
                        (Masc_tui_context_inspector.Composition | Exact_input | Input_map | Response) -> ());
                     Masc_tui_chat_dispatch.Chat_journals.launch_context_inspector_load state
                       ~mailbox:async_messages ~keeper_name)
                  state.context_inspector_keeper
            | "1" ->
                enter_context_inspector_tab state
                  Masc_tui_context_inspector.Composition
            | "2" ->
                enter_context_inspector_tab state
                  Masc_tui_context_inspector.Exact_input
            | "3" ->
                enter_context_inspector_tab state
                  Masc_tui_context_inspector.Input_map
            | "4" ->
                enter_context_inspector_tab state Masc_tui_context_inspector.Response
            | "\t" | "left" | "right"
              when Option.is_none state.context_inspector_exact
                   || state.context_inspector_tab = Masc_tui_context_inspector.Response ->
                enter_context_inspector_tab state
                  (match state.context_inspector_tab with
                   | Masc_tui_context_inspector.Composition ->
                       Masc_tui_context_inspector.Exact_input
                   | Masc_tui_context_inspector.Exact_input ->
                       Masc_tui_context_inspector.Input_map
                   | Masc_tui_context_inspector.Input_map ->
                       Masc_tui_context_inspector.Response
                   | Masc_tui_context_inspector.Response ->
                       Masc_tui_context_inspector.Composition)
            | "h" | "l"
              when Option.is_none state.context_inspector_exact
                   && terminal_columns >= keeper_split_threshold_cols
                   && (state.context_inspector_tab = Masc_tui_context_inspector.Exact_input
                       || state.context_inspector_tab = Masc_tui_context_inspector.Input_map) ->
                (* The same caret the roster and the board carry: which pane
                   hears j/k is a question the reader answers, not the
                   layout. *)
                state.context_inspector_focus <-
                  (if k = "h" then Left_pane else Right_pane)
            | ("j" | "down" | "k" | "up" | "pageup" | "pagedown"
              | "home" | "end" | "wheel-up" | "wheel-down")
              when state.context_inspector_tab = Masc_tui_context_inspector.Response ->
                let count, height = Masc_tui_render.context_inspector_viewport state in
                let move = match k with
                  | "j" | "down" | "wheel-down" -> Masc_tui_scroll.down ~count ~height
                  | "k" | "up" | "wheel-up" -> Masc_tui_scroll.up ~count ~height
                  | "pageup" -> Masc_tui_scroll.page_up ~count ~height
                  | "pagedown" -> Masc_tui_scroll.page_down ~count ~height
                  | "home" -> (fun _ -> 0)
                  | _ -> (fun _ -> Masc_tui_scroll.maximum ~count ~height) in
                state.context_inspector_response_scroll <- move state.context_inspector_response_scroll
            | ("j" | "down" | "k" | "up")
              when Option.is_some state.context_inspector_exact
                   || state.context_inspector_tab
                      = Masc_tui_context_inspector.Composition
                   || scroll_plain_body ->
                let count, height =
                  Masc_tui_render.context_inspector_viewport state
                in
                let move =
                  match k with
                  | "j" | "down" -> Masc_tui_scroll.down
                  | _ -> Masc_tui_scroll.up
                in
                state.context_inspector_scroll <-
                  move ~count ~height state.context_inspector_scroll
            | ("j" | "down" | "k" | "up")
              when state.context_inspector_focus = Right_pane
                   && terminal_columns >= keeper_split_threshold_cols ->
                (* The width condition mirrors the h/l arm that set the
                   focus. A terminal narrowed under the threshold keeps the
                   stored focus but renders no split, and without this guard
                   j/k would reach for a detail window that does not exist --
                   while the cursor arms below, which do work, sat
                   shadowed. *)
                let count, height =
                  Masc_tui_render.context_inspector_detail_viewport state
                in
                let move =
                  match k with
                  | "j" | "down" -> Masc_tui_scroll.down
                  | _ -> Masc_tui_scroll.up
                in
                state.context_inspector_detail_scroll <-
                  move ~count ~height state.context_inspector_detail_scroll
            | "j" | "down" ->
                let count =
                  match state.context_inspector_tab with
                  | Masc_tui_context_inspector.Exact_input ->
                      List.length (exact_input_items ())
                  | Masc_tui_context_inspector.Input_map ->
                      List.length (input_map_rows ())
                  | Masc_tui_context_inspector.Composition
                  | Masc_tui_context_inspector.Response -> 0
                in
                let last = max 0 (count - 1) in
                state.context_inspector_cursor <-
                  min last (state.context_inspector_cursor + 1);
                (* A new item is a new document; its reader starts at its
                   top, not at the window the previous one was left in. *)
                state.context_inspector_detail_scroll <- 0
            | "k" | "up" ->
                state.context_inspector_cursor <-
                  max 0 (state.context_inspector_cursor - 1);
                state.context_inspector_detail_scroll <- 0
            | "\r" ->
                if
                  state.context_inspector_tab
                  = Masc_tui_context_inspector.Exact_input
                then begin
                  let items = exact_input_items () in
                  let cursor =
                    Masc_tui_context_inspector.normalized_cursor
                      ~count:(List.length items)
                      state.context_inspector_cursor
                  in
                  (match List.nth_opt items cursor with
                   | Some _ ->
                       state.context_inspector_cursor <- cursor;
                       state.context_inspector_exact <- Some cursor;
                       state.context_inspector_scroll <- 0
                   | None -> ())
                end
                else if
                  state.context_inspector_tab
                  = Masc_tui_context_inspector.Input_map
                then begin
                  let rows = input_map_rows () in
                  let cursor =
                    Masc_tui_context_inspector.normalized_cursor
                      ~count:(List.length rows)
                      state.context_inspector_cursor
                  in
                  (match List.nth_opt rows cursor with
                   | Some { Masc_tui_context_inspector.verified_item = Some _; _ } ->
                       state.context_inspector_cursor <- cursor;
                       state.context_inspector_exact <- Some cursor;
                       state.context_inspector_scroll <- 0
                   | Some _ | None -> ())
                end
            | _ -> ())
       (* /about is modal for the help sheet's reason: Esc closes it, c turns
          the candle to its other style, and everything else is swallowed so
          no surface binding or global quit fires under it. *)
       | Some k when panel_owns_input && current_panel = Some Presented.About ->
           (match k with
            | "esc" -> state.about_open <- false
            | "c" ->
                let style = Masc_tui_emblem_screen.next_style (Masc_tui_emblem_screen.style ()) in
                Masc_tui_emblem_screen.set_style style;
                (* The candle on screen already changed, so a write that
                   failed is said out loud when the writer answers, or a
                   restart would bring the old one back with nothing having
                   told the reader. *)
                Masc_tui_shell.Preferences.store state (Masc.Tui_preference.Candle_chosen style)
            | _ -> ())
       | Some k when panel_owns_input && current_panel = Some Presented.Agenda ->
           let close () = close_agenda state in
           (match k with
            | ";" | "esc" -> close ()
            | "?" ->
                state.help_open <- true;
                state.help_scroll <- 0
            | "pageup" | "pagedown" | "home" | "end" | "g" | "G" ->
                let count, height = Masc_tui_render.agenda_viewport state in
                let scroll = Masc_tui_render.agenda_scroll_position state in
                state.agenda_navigation <- Agenda_read_rows;
                state.agenda_scroll <-
                  (match k with
                   | "pageup" -> Masc_tui_scroll.page_up ~count ~height scroll
                   | "pagedown" -> Masc_tui_scroll.page_down ~count ~height scroll
                   | "home" | "g" -> 0
                   | "end" | "G" -> Masc_tui_scroll.maximum ~count ~height
                   | _ -> scroll)
            | "j" | "down" | "k" | "up" ->
                let lines = Masc_tui_render.agenda_lines state in
                (match Masc_tui_agenda.target_indexes lines with
                 | [] ->
                     (* Nothing here can be opened, so the keys keep the
                        meaning they had: a panel of prose is still read. *)
                     let count, height =
                       Masc_tui_render.agenda_viewport state
                     in
                     let move =
                       match k with
                       | "j" | "down" -> Masc_tui_scroll.down
                       | _ -> Masc_tui_scroll.up
                     in
                     state.agenda_scroll <-
                       move ~count ~height state.agenda_scroll
                 | _ :: _ ->
                     state.agenda_navigation <- Agenda_follow_selection;
                     let direction =
                       match k with
                       | "j" | "down" -> Masc_tui_agenda.Next
                       | _ -> Masc_tui_agenda.Previous
                     in
                     state.agenda_selected <-
                       Masc_tui_agenda.step lines
                         ~selected:state.agenda_selected direction;
                     let _, height = Masc_tui_render.agenda_viewport state in
                     Option.iter
                       (fun cursor ->
                          state.agenda_scroll <-
                            Masc_tui_scroll.ensure_visible ~cursor ~height
                              state.agenda_scroll)
                       (Masc_tui_agenda.selected_index lines
                          ~selected:state.agenda_selected))
            | "\r" ->
                let lines = Masc_tui_render.agenda_lines state in
                let _, height = Masc_tui_render.agenda_viewport state in
                let scroll = Masc_tui_render.agenda_scroll_position state in
                let selected =
                  match Masc_tui_agenda.selected_index lines
                          ~selected:state.agenda_selected with
                  | Some index when index >= scroll && index < scroll + height ->
                      Masc_tui_agenda.selected_line lines
                        ~selected:state.agenda_selected
                  | Some _ | None -> None
                in
                (match selected with
                 | Some { Masc_tui_agenda.goes_to = Masc_tui_agenda.Nowhere; _ }
                 | None -> ()
                 | Some
                     { Masc_tui_agenda.goes_to = Masc_tui_agenda.Keeper_holding _
                     ; _
                     } ->
                     (* The held call is answered on the Approvals surface,
                        which is where every held call is answered. *)
                     close ();
                     goto_surface state ~mailbox:async_messages Approvals
                 | Some
                     { Masc_tui_agenda.goes_to =
                         Masc_tui_agenda.Ask_to_answer ask
                     ; _
                     } ->
                     (* Opened the way Home's Question row opens it: on
                        Approvals, with this ask under the cursor and its
                        questions in front of the operator. *)
                     close ();
                     (match
                        List.find_index
                          (fun row -> Masc.Tui_decode_asks.(equal_ask_key ask (ask_key row)))
                          (open_ask_rows state)
                      with
                      | None ->
                          report_action state "system"
                            "Question changed; choose again"
                      | Some cursor ->
                          goto_surface state ~mailbox:async_messages Approvals;
                          (* The reader follows the ask it was opened on,
                             not the cursor, so a reader left open on
                             another ask would come back instead of this
                             one. *)
                          (match state.ask_answer_mode with
                           | Ask_answering { aam_ask }
                             when not (Masc.Tui_decode_asks.equal_ask_key aam_ask ask) ->
                               Masc_tui_operator_actions.Ask_actions.leave_ask_answering state
                           | Ask_answering _ | Ask_browsing -> ());
                          state.ask_cursor <- Ask.On cursor;
                          Masc_tui_operator_actions.Ask_actions.enter_ask_answering state)
                 | Some
                     { Masc_tui_agenda.goes_to =
                         Masc_tui_agenda.Goal_to_confirm goal_id
                     ; _
                     } ->
                     (* The Goal's detail is where its proof is read and
                        confirmed, the same landing a followed goal link
                        gives. *)
                     close ();
                     (* The detail is reconciled against the filtered list on
                        the next planning load, so a filter that hides Goals
                        awaiting confirmation would send the operator back to
                        the list. Only such a filter is widened. *)
                     (match state.planning_filter with
                      | Planning_filter_all | Planning_filter_active -> ()
                      | Planning_filter_completed | Planning_filter_dropped ->
                          state.planning_filter <- Planning_filter_active);
                     goto_surface state ~mailbox:async_messages Planning;
                     state.planning_mode <- Planning_detail goal_id;
                     state.planning_scroll <- Planning_scroll_offset 0;
                     state.goal_timeline <- Masc_tui_fetched.clear state.goal_timeline;
                     Masc_tui_work_requests.Tools_task_requests.launch_goal_timeline_load state ~mailbox:async_messages
                       goal_id
                 | Some
                     { Masc_tui_agenda.goes_to =
                         Masc_tui_agenda.Stuck_task task_id
                     ; _
                     } ->
                     (* Inspect the exact Task whose owner route was observed. *)
                     close ();
                     goto_surface state ~mailbox:async_messages Planning;
                     state.planning_mode <- Planning_list;
                     state.task_detail_id <- Some task_id;
                     reset_task_detail_scroll state;
                     prepare_task_history_for_open state ~task_id;
                     state.task_focus <-
                       Masc_tui_overview_tasks.land_on state.tasks ~task_id;
                     Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size state ~mailbox:async_messages
                       task_id)
            | _ -> ())
       | Some k when panel_owns_input && current_panel = Some Presented.Answering ->
           let close () =
             state.answering_open <- false;
             state.answering_scroll <- 0;
             state.answering_cursor <- 0
           in
           (match k with
            | "@" | "esc" -> close ()
            (* The footer stamps the help door on this row, so the key has
               to answer; the sheet is read-only and may cover the overlay,
               the way the activity overlays allow it to. *)
            | "?" ->
                state.help_open <- true;
                state.help_scroll <- 0
            | "j" | "down" | "k" | "up" ->
                let lines = Masc_tui_render_prim.answering_lines state in
                let targets = Masc_tui_answering.target_indexes lines in
                (match targets with
                 | [] ->
                     let count, height = Masc_tui_render.answering_viewport state in
                     let move = match k with
                       | "j" | "down" -> Masc_tui_scroll.down
                       | _ -> Masc_tui_scroll.up
                     in
                     state.answering_scroll <- move ~count ~height state.answering_scroll
                 | _ ->
                     let position =
                       let rec find i = function
                         | [] -> 0
                         | index :: rest ->
                             if index = state.answering_cursor then i
                             else find (i + 1) rest
                       in
                       find 0 targets
                     in
                     let next_position =
                       match k with
                       | "j" | "down" ->
                           min (List.length targets - 1) (position + 1)
                       | _ -> max 0 (position - 1)
                     in
                     let cursor = List.nth targets next_position in
                     state.answering_cursor <- cursor;
                     let _, height =
                       Masc_tui_render.answering_viewport state
                     in
                     (* Keep the cursor row on screen: scroll only as far as
                        needed, in either direction. *)
                     if cursor < state.answering_scroll then
                       state.answering_scroll <- cursor
                     else if cursor >= state.answering_scroll + height then
                       state.answering_scroll <- cursor - height + 1)
            | "pageup" | "pagedown" | "home" | "end" ->
                let count, height = Masc_tui_render.answering_viewport state in
                state.answering_scroll <-
                  (match k with
                   | "pageup" -> Masc_tui_scroll.page_up ~count ~height state.answering_scroll
                   | "pagedown" -> Masc_tui_scroll.page_down ~count ~height state.answering_scroll
                   | "home" -> 0
                   | _ -> Masc_tui_scroll.maximum ~count ~height)
            | "\r" ->
                let lines = Masc_tui_render_prim.answering_lines state in
                (match Masc_tui_render.answering_selected_target state ~lines with
                 | Some keeper_name ->
                     close ();
                     Masc_tui_chat_dispatch.Chat_journals.enter_keeper_chat ~return_to:Keeper_chat_return_list state
                       ~keeper_name ~drain_queue:(fun () ->
                         Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox:async_messages)
                       ~load_history:(fun keeper_name ->
                         launch_keeper_history_load state ~mailbox:async_messages ~keeper_name)
                 | None -> ())
            | _ -> ())
       (* A Play card can arrive after the last Queue frame, or close before
          its replacement frame. The last accepted owner keeps the keys until
          the terminal accepts the next frame. *)
       | Some _ when queue_play_owner = Wait_for_frame ->
           report_input_rejection state Masc_tui_action_notice.Input_rejected "Screen transition: input was not applied; review and retry"
       | Some k when Option.is_some presented_queue_input ->
           Option.iter (fun panel ->
             handle_queue_panel_key state ~base_path ~mailbox:async_messages
               ~presented_presses:(!presented).presses panel k) presented_queue_input
       (* The invite card holds the only copy of a link, so it takes every key and
          closes on the operator's own: Esc or q, after which /play link brings
          it back. Enter does not close it, so a second Enter, pressed while
          the answer was on its way, cannot close the card it opens. [y] copies
          the link to the terminal clipboard and says so without naming it.
          F2 is handled by the earlier global arm: a terminal that ignores OSC 52 has
          only the mouse to copy the link with, and this is a screen worth
          copying from. *)
       | Some k
         when not compact_viewport && Option.is_some (Masc_tui_types.play_card_shown state)
              && not (String.equal k Masc_tui_shell.Terminal_session.toggle_mouse_tracking_key) ->
           (match k, Masc_tui_types.play_card_shown state with
            | ("esc" | "q" | "Q"), Some _ ->
                state.quit_armed <- None;
                state.play_invite <- { state.play_invite with shown_name = None }
            | ("y" | "Y"), Some card ->
                let outcome =
                  copy_reference render_schedule (Masc_tui_play_card.link card) in
                report_action state "system"
                  (if state.ui_language = Lang_ko then
                     "초대 링크를 " ^ Masc_tui_clipboard.copy_outcome_text_korean outcome
                   else
                     "Invite link " ^ Masc_tui_clipboard.copy_outcome_text outcome)
            | ("j" | "down"), Some _ ->
                state.play_invite_scroll <- Masc_tui_types.scroll_down_from state.play_invite_scroll ~by:1
            | ("k" | "up"), Some _ ->
                state.play_invite_scroll <- max 0 (state.play_invite_scroll - 1)
            | "g", Some _ -> state.play_invite_scroll <- 0
            | "G", Some _ -> state.play_invite_scroll <- Masc_tui_types.clamped_scroll_end
            | _, _ -> ())
       | Some key when Option.is_some state.collab ->
           (match state.collab with
            | Some view when not compact_viewport || key = "esc" ->
                let view = Masc_tui_collab.write_access view (Masc_tui_types.play_change_access state) in
                let view, action = Masc_tui_collab.key view key in
                state.collab <- Some view;
                handle_collab_action state ~mailbox:async_messages view action
            | Some _ | None -> ())
       | Some key when Option.is_some state.account_login ->
           (match state.account_login with
            | Some view ->
              view.Masc_tui_account_login.ko <- state.ui_language = Lang_ko;
              if not compact_viewport || key="esc" then
                Masc_tui_surface_requests.Account_requests.launch_account_login_action state ~mailbox:async_messages view (Masc_tui_account_login.key view key)
            | None -> ())
       | Some key when machine_activity_on_screen () ->
           (match Masc_tui_types.shown_machine_activity state with
            | None -> state.machine_activity_open <- None
            | Some session ->
              let set session = Masc_tui_types.put_machine_activity state session in
              (match key with
               | "esc" | "q" | "Q" -> state.machine_activity_open <- None; state.quit_armed <- None
               | "?" -> state.help_open <- true; state.help_scroll <- 0
               | " " | "space" -> if not compact_viewport then set (Masc_tui_machine_activity.toggle session)
               | "s" | "S" -> if not compact_viewport then launch_machine_activity_save state ~mailbox:async_messages session
               | "r" -> launch_machine_activity_read state ~mailbox:async_messages (Masc_tui_machine_activity.owner session)
               | "u" -> if not compact_viewport then set (Masc_tui_machine_activity.reapply session)
               | "x" -> if not compact_viewport then set (Masc_tui_machine_activity.discard session)
               | "j" | "down" | "wheel-down" -> state.lane_run_detail_scroll <- Masc_tui_types.scroll_down_from state.lane_run_detail_scroll ~by:1
               | "k" | "up" | "wheel-up" -> state.lane_run_detail_scroll <- max 0 (state.lane_run_detail_scroll-1)
               | "pageup" -> state.lane_run_detail_scroll <- max 0 (state.lane_run_detail_scroll - Masc_tui_scroll.page_step ~height:state.lane_run_detail_content_height)
               | "pagedown" -> state.lane_run_detail_scroll <- Masc_tui_types.scroll_down_from state.lane_run_detail_scroll ~by:(Masc_tui_scroll.page_step ~height:state.lane_run_detail_content_height)
               | "g" | "home" -> state.lane_run_detail_scroll <- 0
               | "G" | "end" -> state.lane_run_detail_scroll <- Masc_tui_types.clamped_scroll_end
               | _ -> ()))
       | Some key when exact_activity_on_screen () ->
           (match Masc_tui_types.shown_exact_activity state with
            | None -> state.exact_activity_open <- None
            | Some session ->
              let set session = Masc_tui_types.put_exact_activity state session in
              (match key with
               | "esc" | "q" | "Q" -> state.exact_activity_open <- None; state.quit_armed <- None
               | "?" -> state.help_open <- true; state.help_scroll <- 0
               | " " | "space" -> if not compact_viewport then set (Masc_tui_exact_activity.toggle session)
               | "s" | "S" -> if not compact_viewport then launch_exact_activity_save state ~mailbox:async_messages session
               | "r" -> launch_exact_activity_read state ~mailbox:async_messages (Masc_tui_exact_activity.owner session)
               | "u" -> if not compact_viewport then set (Masc_tui_exact_activity.reapply session)
               | "x" -> if not compact_viewport then set (Masc_tui_exact_activity.discard session)
               | "j" | "down" | "wheel-down" -> state.lane_run_detail_scroll <- Masc_tui_types.scroll_down_from state.lane_run_detail_scroll ~by:1
               | "k" | "up" | "wheel-up" -> state.lane_run_detail_scroll <- max 0 (state.lane_run_detail_scroll-1)
               | "pageup" -> state.lane_run_detail_scroll <- max 0 (state.lane_run_detail_scroll - Masc_tui_scroll.page_step ~height:state.lane_run_detail_content_height)
               | "pagedown" -> state.lane_run_detail_scroll <- Masc_tui_types.scroll_down_from state.lane_run_detail_scroll ~by:(Masc_tui_scroll.page_step ~height:state.lane_run_detail_content_height)
               | "g" | "home" -> state.lane_run_detail_scroll <- 0
               | "G" | "end" -> state.lane_run_detail_scroll <- Masc_tui_types.clamped_scroll_end
               | _ -> ()))
       | Some _ when composer_claimed -> ()
       | Some _ when Option.is_some accepted_unbind_offer ->
           Option.iter (Masc_tui_editor_forms.Connector_forms.handle_connector_unbind_offer_accept state ~mailbox:async_messages) accepted_unbind_offer
       (* The keeper-voice screen owns every key while it is open: it is drawn
          instead of the pane, so a key that fell through would act on a
          surface nobody is looking at. *)
       | Some key
         when state.view = Config && state.config_pane = Config_voice
              && Option.is_some state.voice_agent_voices && not state.help_open ->
           (match state.voice_agent_voices with
            | None -> ()
            | Some session ->
              let set updated = state.voice_agent_voices <- Some updated in
              (* Help is read-only and may cover an in-flight save. *)
              if (compact_viewport && not (String.equal key "esc")) || (session.vas_saving && not (String.equal key "esc" || String.equal key "?"))
              then ()
              else (
                match key with
                | "?" -> state.help_open <- true; state.help_scroll <- 0
                | "esc" ->
                    state.voice_agent_voices <- None;
                    Masc_tui_types.clear_progress_clock state ~slot:"voice-agent";
                    state.config_scroll <- 0
                | "j" | "down" ->
                    set (Masc_tui_types.voice_agent_walk_agents session ~ahead:true)
                | "k" | "up" ->
                    set (Masc_tui_types.voice_agent_walk_agents session ~ahead:false)
                | "right" ->
                    set (Masc_tui_types.voice_agent_walk_voices session ~ahead:true)
                | "left" ->
                    set (Masc_tui_types.voice_agent_walk_voices session ~ahead:false)
                | "pageup" ->
                    state.config_scroll
                      <- max 0 (state.config_scroll - surface_page_rows state)
                | "pagedown" ->
                    state.config_scroll
                      <- Masc_tui_types.scroll_down_from state.config_scroll
                           ~by:(surface_page_rows state)
                | "home" -> state.config_scroll <- 0
                | "end" -> state.config_scroll <- Masc_tui_types.clamped_scroll_end
                | "\r" | "\n" | "enter" ->
                    Masc_tui_work_requests.Voice_requests.launch_voice_agent_voice_save state ~mailbox:async_messages session
                | _ -> ()))
       (* Hidden Add-ons actions keep their draft and receipts, but cannot
          dispatch while the resize fallback is the only painted frame. *)
       | Some "esc" when compact_viewport && Option.is_some state.lane_addons ->
           (match state.lane_addons with
            | None -> ()
            | Some view ->
                state.lane_addons_cached <- view;
                state.lane_addons <- None)
       | Some _ when compact_viewport && Option.is_some state.lane_addons
                     && not quit_key -> ()
       | Some key when Option.is_some state.lane_addons && not state.palette_open
                       && not (compact_viewport && quit_key) ->
           let module Addons = Masc_tui_lane_addons in
           (match state.lane_addons with
            | None -> ()
            | Some view ->
                let update next = state.lane_addons <- Some next in
                let invalidate next =
                  state.lane_addons_generation <- state.lane_addons_generation + 1;
                  update {next with generation=state.lane_addons_generation} in
                let selected action = match Addons.selected_instance view with
                  | None -> update { view with error = Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure "Choose an attached instance first" }
                  | Some instance -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox:async_messages (action instance.id) in
                let scroll_lane_addons ~page ~down =
                  let terminal_rows, cols = get_terminal_size () in
                  let height = Masc_tui_render_prim.surface_chrome_budget state ~terminal_rows in
                  let ({ Addons.total_list_rows = count; list_budget; scroll = current; _ }
                        : Addons.viewport_frame) =
                    Addons.viewport_frame ~ko:(state.ui_language = Lang_ko) ~height
                      ~width:(framed_inner_width cols) view
                  in
                  let page_height = max 1 list_budget in
                  let distance = if page then page_height else 1 in
                  let delta = if down then distance else -distance in
                  update { view with scroll = Masc_tui_scroll.normalize ~count ~height:page_height (current + delta) }
                in
                (match view.installer with
                 | Some installer ->
                     if key="pageup" || key="pagedown" then
                       scroll_lane_addons ~page:false ~down:(key = "pagedown")
                     else if view.loading then (
                       if key="esc" then invalidate {view with installer=None;loading=false;error=None;scroll=0})
                     else (match Masc_tui_lane_installer.handle ~key installer with
                       | Error detail -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail}
                       | Ok (Updated installer) -> update {view with installer=Some installer;error=None;scroll=0}
                       | Ok Cancel -> invalidate {view with installer=None;error=None;scroll=0}
                       | Ok Declare -> invalidate {view with installer=None;draft=Some "";naming=true;document_key=None;error=None;scroll=0}
                       | Ok (Browse directory) -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_package_catalog state ~mailbox:async_messages directory
                       | Ok (Preview path) -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_package_preview state ~mailbox:async_messages path
                       | Ok (Draft session) ->
                           if List.exists (fun (existing : Masc_tui_lane_declaration.session) -> existing.file_name=session.file_name) view.documents
                           then update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure "A draft with this installation name is already open; choose another name or edit the existing draft."}
                           else update (Addons.put_document {view with installer=None;error=None;scroll=0} session))
                 | None -> match view.evidence_prompt with
                 | Some _ ->
                     (match key with
                      | "esc" | "q" -> update {view with evidence_prompt=None;scroll=0}
                      | "j" | "down" -> update (Addons.move_evidence view 1)
                      | "k" | "up" -> update (Addons.move_evidence view (-1))
                      | "\r" | "\n" | "enter" ->
                          (match Addons.submit_evidence view with
                           | Ok (next, request) -> update next; Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox:async_messages request
                           | Error detail -> update {view with evidence_prompt=None;error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail})
                      | _ -> ())
                 | None when Option.is_some view.records ->
                     if key="pageup" || key="pagedown" then
                       scroll_lane_addons ~page:true ~down:(key="pagedown")
                     else (match Addons.edit_records ~key view with
                      | Ok next -> update next
                      | Error detail -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail;scroll=0})
                 | None -> match view.subscription_panel,view.action_menu,view.draft with
                 | Some panel,_,_ ->
                     let module Subs = Masc_tui_lane_subscriptions in
                     let set panel = update {view with subscription_panel=Some panel;scroll=0} in
                     (match key with
                      | "esc" | "q" -> update {view with subscription_panel=Subs.back panel;scroll=0}
                      | "J" | "K" -> scroll_lane_addons ~page:false ~down:(key = "J")
                      | _ when view.loading -> ()
                      | "j" | "down" -> set (Subs.move panel 1)
                      | "k" | "up" -> set (Subs.move panel (-1))
                      | "a" -> set (Subs.add panel)
                      | "d" -> set (Subs.remove panel)
                      | "r" when not (Subs.is_confirming_save panel) ->
                          Masc_tui_surface_requests.Lane_browser_requests.launch_lane_subscriptions state ~mailbox:async_messages Subs.Inspect
                      | "\r" | "\n" | "enter" ->
                          let keepers=List.map (fun (keeper:keeper) -> keeper.k_name) state.keepers in
                          let panel,request=Subs.enter ~keepers ~targets:(Addons.subscription_targets view) panel in
                          set panel;
                          Option.iter (Masc_tui_surface_requests.Lane_browser_requests.launch_lane_subscriptions state ~mailbox:async_messages) request
                      | _ -> ())
                 | None,Some {form=Some _;_}, _ ->
                     if key="pageup" || key="pagedown" then
                       scroll_lane_addons ~page:false ~down:(key = "pagedown")
                     else (match Addons.edit_action ~key view with
                      | Ok (next,None) -> update next
                      | Ok (_,Some action) -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox:async_messages (Addons.Act action)
                      | Error detail -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail})
                 | None,Some _, _ ->
                     (match key with
                      | "esc" -> update {view with action_menu=None;scroll=0}
                      | "j" | "down" -> update (Addons.move_action view 1)
                      | "k" | "up" -> update (Addons.move_action view (-1))
                      | "J" | "K" -> scroll_lane_addons ~page:false ~down:(key = "J")
                      | "\r" | "\n" | "enter" ->
                          (match Addons.enter_action view with
                           | Ok (next,None) -> update next
                           | Ok (_,Some action) -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox:async_messages (Addons.Act action)
                           | Error detail -> update {view with action_menu=None;error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail})
                      | _ -> ())
                 (* A line that takes letters owns them. This branch answered
                    "3", "q", "r" and "s" as surface commands first, so typing
                    a file name with one of those letters in it lost the letter
                    and ran the command: "terminal.toml" refreshed the surface
                    at its "r" and arrived as "al.toml". Esc closes the line and
                    every one of those keys is there. *)
                 | None,None, Some draft ->
                     (match key with
                      | "esc" -> update { view with draft = None }
                      | "\r" | "\n" | "enter" ->
                          if view.naming then
                            (match Masc_tui_lane_declaration.create draft with
                             | Error detail -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail}
                             | Ok fresh ->
                                 let session = Option.value ~default:fresh
                                   (List.find_opt (fun (s : Masc_tui_lane_declaration.session) -> s.file_name=fresh.file_name) view.documents) in
                                 update (Addons.put_document {view with draft=None;naming=false;editor_ready=true;scroll=0;error=None} session))
                          else
                            (match Addons.parse_request draft with
                             | Ok request -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox:async_messages request
                             | Error detail -> update { view with error = Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail })
                      | "\127" | "\b" | "backspace" -> update { view with draft = Some (Masc_tui_message_layout.drop_last_utf8_scalar draft) }
                      | "\021" -> update { view with draft = Some "" }
                      | text when (String.length text = 1 && Char.code text.[0] >= 32) || (String.length text > 1 && Char.code text.[0] >= 0x80) -> update { view with draft = Some (draft ^ text) }
                      | _ -> ())
                 | None,None, None ->
                     match key with
                     | "esc" when view.help_open -> update {view with help_open=false;scroll=0}
                     | "?" -> update {view with help_open=not view.help_open;scroll=0}
                     | ("j" | "down" | "J" | "k" | "up" | "K" | "pageup" | "pagedown") when view.help_open ->
                         scroll_lane_addons ~page:(key="pageup" || key="pagedown")
                           ~down:(key="j" || key="down" || key="J" || key="pagedown")
                     | _ when view.help_open -> ()
                     | "r" when Option.is_some view.document_key ->
                         Masc_tui_surface_requests.Lane_browser_requests.launch_lane_application state ~mailbox:async_messages
                     | "esc" when Option.is_some view.document_key -> update {view with document_key=None;scroll=0}
                     | "esc" when view.presentation<>Addons.Summary -> update { (Addons.set_presentation view Addons.Summary) with
                         focus=(if view.screen=Addons.Overview then Addons.Instances else view.focus);scroll=0}
                     | "esc" | "q" when view.screen<>Addons.Overview -> update {view with screen=Addons.Overview;focus=Addons.Instances;scroll=0}
                     | "esc" | "q" -> state.lane_addons_cached <- view; state.lane_addons <- None
                     | ("\r" | "\n" | "enter") when view.screen=Addons.Overview ->
                         if view.loading then update {view with scroll=0;
                           error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure "Wait for the current Lane read before opening a worker."}
                         else (
                         let next = Addons.open_selected_instance view in
                         update next;
                         (match next.screen, Addons.selected_instance next with
                          | Addons.Detail _, Some item ->
                              let request = match view.overview_mode with
                                | Addons.Retained_runs -> Addons.Slice ["run_id",item.run_id]
                                | Addons.Current_installations -> Addons.Inspect in
                              Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons ~target:(Addons.Read_detail (item.id,item.incarnation))
                                state ~mailbox:async_messages request
                          | Addons.Overview, (Some _ | None) | Addons.Detail _, None -> ()))
                     | "i" ->
                         if view.loading then update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure "Wait for the current Lane request before opening installation."}
                         else (
                           let installer = Masc_tui_lane_installer.browse ?directory:view.package_directory () in
                           invalidate {view with installer=Some installer;document_key=None;error=None;scroll=0};
                           Masc_tui_surface_requests.Lane_browser_requests.launch_lane_package_catalog state ~mailbox:async_messages view.package_directory)
                     | "n" -> update {view with draft=Some "";naming=true;document_key=None;scroll=0}
                     | ":" ->
                         state.palette_open <- true;
                         state.palette_mode <- Palette_jump;
                         state.palette_query <- "";
                         state.palette_cursor <- 0
                     | "A" -> update { view with draft = Some ""; naming=false; scroll = 0 }
                     | "R" ->
                         (match Addons.open_records view with
                          | Ok next -> update next
                          | Error detail -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail})
                     | "E" ->
                         (match Addons.selected_document view with
                          | Some _ -> update {view with editor_ready=true}
                          | None -> Masc_tui_editor_forms.Runtime_config_forms.select_lane_document state ~mailbox:async_messages view)
                     | " " when Option.is_some (Addons.selected_document view) ->
                         if view.loading then update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure
                           "Wait for the current document request; the draft is retained"}
                         else (match Addons.selected_document view with
                           | None -> ()
                           | Some session ->
                               match Masc_tui_lane_declaration.toggle_enabled session with
                               | Error detail -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail}
                               | Ok session -> update (Addons.put_document {view with error=None;scroll=0} session))
                     | "s" ->
                         (match Addons.selected_document view with
                          | None -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure "Open a TOML draft with n or E first"}
                          | Some session -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_declaration state ~mailbox:async_messages ~edit:false (Masc_tui_lane_declaration.Save session))
                     | "l" ->
                         (match Addons.selected_document view with
                          | None -> ()
                          | Some session ->
                              let path = match session.base, session.current with
                                | Some base, _ | None, Some base -> Some base.source_path
                                | None, None -> Option.bind view.snapshot (fun snapshot ->
                                    Option.map (fun (config : Addons.configuration) -> Filename.concat config.directory session.file_name) snapshot.configuration) in
                              (match path with None -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure "Configuration directory unknown; r inspects it"}
                               | Some path -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_declaration state ~mailbox:async_messages ~edit:false (Masc_tui_lane_declaration.Read path)))
                     | "u" | "U" ->
                         (match Addons.selected_document view with
                          | None -> ()
                          | Some session ->
                              let apply = if key="u" then Masc_tui_lane_declaration.use_current_revision else Masc_tui_lane_declaration.replace_with_current in
                              (match apply session with Ok session -> update (Addons.put_document {view with error=None} session)
                               | Error detail -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail}))
                     | "r" ->
                         let request = match view.screen, view.overview_mode, Addons.selected_instance view with
                           | Addons.Detail _, Addons.Retained_runs, Some item ->
                               Addons.Slice ["run_id",item.run_id]
                           | Addons.Overview, _, _
                           | Addons.Detail _, Addons.Current_installations, _
                           | Addons.Detail _, Addons.Retained_runs, None -> Addons.Inspect in
                         Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox:async_messages request
                     | "h" when view.screen=Addons.Overview -> update (Addons.toggle_history view)
                     | "S" ->
                         if not view.loading then (
                           let keepers=List.map (fun (keeper:keeper) -> keeper.k_name) state.keepers in
                           let panel=Masc_tui_lane_subscriptions.initial ~keepers
                             ~targets:(Addons.subscription_targets view) in
                           update {view with subscription_panel=Some panel;document_key=None;scroll=0};
                           Masc_tui_surface_requests.Lane_browser_requests.launch_lane_subscriptions state ~mailbox:async_messages Masc_tui_lane_subscriptions.Inspect)
                     | "D" -> update { (Addons.set_presentation view
                         (if view.presentation=Addons.Technical then Addons.Summary else Addons.Technical)) with
                         focus=(if view.screen=Addons.Overview then Addons.Instances else view.focus);scroll=0}
                     | "f" -> update (Addons.toggle_flow view)
                     | "a" ->
                         if view.loading || Option.is_some (Addons.pending_action view)
                         then update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure "An action or read is pending; t checks its status."}
                         else (match Addons.open_actions ~request_id:(Random_id.uuid_v7 ()) view with
                           | Ok next -> update next
                           | Error detail -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail})
                     | "t" ->
                         (match view.last_action with None -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure "No action request yet; A opens a command, then act submits one"}
                          | Some request -> Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox:async_messages (Addons.Action_status request))
                     | "o" ->
                         (match Addons.selected_instance view with
                          | Some instance when Addons.can_observe instance -> selected (fun id -> Addons.Observe id)
                          | Some _ | None -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure "Select an active worker to observe; D shows retained state."})
                     | "d" ->
                         (match Addons.selected_instance view with
                          | Some item -> (match Addons.removal_block_reason view item with
                              | Some reason -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure reason}
                              | None -> selected (fun id -> Addons.Detach id))
                          | None -> selected (fun id -> Addons.Detach id))
                     | "1" when view.screen<>Addons.Overview -> update {view with focus=Addons.Timeline;scroll=0}
                     | "2" when view.screen<>Addons.Overview -> update {view with focus=Addons.Connections;scroll=0}
                     | "3" when view.screen<>Addons.Overview -> update {view with focus=Addons.Configurations;scroll=0}
                     | "4" when view.screen<>Addons.Overview -> update {view with focus=Addons.Rows;scroll=0}
                     | "\t" | "tab" when view.screen<>Addons.Overview ->
                         update {view with scroll=0;focus = (match view.focus with
                           | Addons.Timeline | Addons.Instances -> Addons.Connections
                           | Addons.Connections -> Addons.Configurations
                           | Addons.Configurations -> Addons.Rows
                           | Addons.Rows -> Addons.Timeline) }
                     | "J" | "K" -> scroll_lane_addons ~page:false ~down:(key = "J")
                     | "left" | "right" when (match view.focus with
                       | Addons.Timeline | Addons.Connections -> true
                       | Addons.Configurations | Instances | Rows -> false) ->
                         let delta = if key = "right" then 1 else -1 in
                         update (Addons.move_lane view delta)
                     | "j" | "down" | "k" | "up" ->
                         let delta = if key = "j" || key = "down" then 1 else -1 in
                         (match view.snapshot, view.screen, view.focus with
                          | Some snapshot, Addons.Overview, Addons.Configurations ->
                              (match snapshot.configuration with
                               | None -> ()
                               | Some configuration -> update {view with configuration_cursor=max 0
                                   (min (List.length configuration.declarations - 1) (view.configuration_cursor + delta))})
                          | Some _, Addons.Overview, _ ->
                              (* Flow draws only workers; moving among the
                                 declarations it hides left the action target
                                 on a row nobody could see. *)
                              let next = Addons.move_instance view delta in
                              if next.instance_cursor <> view.instance_cursor then update next
                          | Some _, Addons.Detail _, (Addons.Configurations | Addons.Instances | Addons.Connections) -> ()
                          | Some _, Addons.Detail _, Addons.Rows ->
                              update (Addons.move_record view delta)
                          | Some _, Addons.Detail _, Addons.Timeline -> update (Addons.move_observation view delta)
                          | None, _, _ -> ())
                     | " " ->
                         (match Addons.selected_row view with None -> () | Some row ->
                           update { view with selected = if List.mem row.id view.selected then List.filter ((<>) row.id) view.selected else row.id :: view.selected })
                     | "e" when view.selected <> [] ->
                         let keepers = List.map (fun (keeper : keeper) -> keeper.k_name) state.keepers in
                         (match Addons.open_evidence ~request_id:(Random_id.uuid_v7 ()) ~keepers view with
                          | Ok next -> update next
                          | Error detail -> update {view with error=Masc_tui_surface_requests.Lane_browser_requests.lane_addons_input_failure detail})
                     | _ -> ()))
       (* A retained form owns its paste target, but a frame showing only the
          resize prompt cannot accept hidden edits or submit writes. Keep
          these key guards separate from text_input_target so a paste never
          falls through into a different draft. *)
       (* Inline Runtime_params editing is modal: printable keys, including q,
          belong to the value.  Friendly mode turns the registry's declared
          type into a bool/number/string control; capital E is the explicit
          raw-JSON escape hatch.  The server remains the final authority. *)
       | Some k when not compact_viewport
           && text_input_target state ~compact_viewport = Some Text_resource_save ->
           (match state.resource_save_prompt with
            | None -> ()
            | Some prompt ->
              let input = prompt.rsp_path in
              (match k with
               | "esc" -> state.resource_save_prompt <- None
               | "\r" | "\n" | "enter" -> save_resource_source state ~mailbox:async_messages prompt
               | "\127" | "\b" | "backspace" ->
                   prompt.rsp_error <- None;
                   Masc_tui_message_input.backspace input
               | "left" -> Masc_tui_message_input.move_left input
               | "right" -> Masc_tui_message_input.move_right input
               | "\021" -> prompt.rsp_error <- None; Masc_tui_message_input.clear input
               | "pageup" -> page_resource_document state (-1)
               | "pagedown" -> page_resource_document state 1
               | text when Masc_tui_message_layout.is_printable_utf8_scalar text ->
                   prompt.rsp_error <- None;
                   Masc_tui_message_input.insert input text
               | _ -> ()))
       (* Typing a preset name. The pane owns every printable key while a
          draft is open, so a name with an s or an r in it does not fire the
          save and restore keys under it. *)
       | Some k
         when not compact_viewport
              && text_input_target state ~compact_viewport
                 = Some Text_preset_name ->
           (match state.preset_save_draft with
            | None -> ()
            | Some draft ->
              (match k with
               | "esc" ->
                 state.preset_save_draft <- None;
                 state.preset_save_draft_description <- "";
                 state.preset_save_draft_source <- Preset_form_local;
                 state.preset_save_draft_workspace <- None;
                 state.preset_armed <- None;
                 report_action state "system"
                   (if state.preset_busy then
                      ui_text state ~ko:"이름 입력 닫음 · 진행 중인 저장은 계속됩니다"
                        ~en:"Name entry closed · the pending save continues"
                    else ui_text state ~ko:"프리셋 저장 취소" ~en:"Preset save cancelled")
               | ("pageup" | "pagedown" | "home" | "end") as move ->
                 let count, height = Masc_tui_render_config.presets_viewport state in
                 state.config_scroll <- (match move with
                   | "home" -> 0
                   | "end" -> Masc_tui_scroll.maximum ~count ~height
                   | "pageup" -> Masc_tui_scroll.page_up ~count ~height state.config_scroll
                   | "pagedown" -> Masc_tui_scroll.page_down ~count ~height state.config_scroll
                   | _ -> state.config_scroll)
               | "\r" | "\n" | "enter" ->
                 let name = String.trim draft in
                 if String.equal name "" then
                   report_action state "error" (ui_text state ~ko:"프리셋 이름이 필요합니다" ~en:"A preset name is required")
                 else if state.preset_busy then
                   report_action state "system"
                     (ui_text state ~ko:"프리셋 작업 완료 후 저장하세요 · 입력은 유지됩니다"
                        ~en:"Wait for the preset operation to finish · input retained")
                 else if workspace_preset_save_pending state <> []
                         && not (preset_save_is_pending state name) then
                   report_action state "system"
                     (ui_text state ~ko:"진행 중인 프리셋 저장을 기다리세요 · 입력 유지"
                        ~en:"Wait for the pending preset save · input retained")
                 else if not (server_authority_ready state) then
                   report_action state "error"
                     (preset_save_needs_workspace_text ~ko:(state.ui_language = Lang_ko))
                 else (match workspace_input_identity_of_server state.server_identity with
                   | None -> report_action state "error"
                       (preset_save_needs_workspace_text ~ko:(state.ui_language = Lang_ko))
                   | Some workspace ->
                     if state.preset_save_draft_workspace = None
                        && state.preset_armed <> Some (Save_workspace_armed (name, workspace)) then begin
                       state.preset_armed <- Some (Save_workspace_armed (name, workspace));
                       state.preset_confirmation_token <- Some (ref ());
                       state.preset_confirmation_presented <- None;
                       state.config_scroll <- 0;
                       report_action state "system"
                         (ui_text state ~ko:"저장할 워크스페이스를 확인하고 Enter를 다시 누르세요"
                            ~en:"Check the save workspace and press Enter again")
                     end else if Option.fold ~none:false
                         ~some:(fun origin -> origin <> workspace) state.preset_save_draft_workspace then
                       report_action state "error"
                         (ui_text state ~ko:"다른 워크스페이스의 이름 초안입니다"
                            ~en:"This name draft belongs to a different workspace")
                     else if state.preset_armed = Some (Save_workspace_armed (name, workspace))
                             && not (Masc_tui_render_config.preset_confirmation_ready state) then
                       report_action state "system"
                         (ui_text state ~ko:"Home 후 PgDn으로 워크스페이스를 처음부터 확인하세요"
                            ~en:"Use Home then PgDn to review the complete workspace confirmation")
                     else begin
                       if state.preset_save_draft_workspace = None then begin
                         state.preset_save_draft_workspace <- Some workspace;
                         state.preset_armed <- None
                       end;
                       if preset_save_is_unconfirmed state name
                          && not (preset_save_is_pending state name)
                          && state.preset_armed <> Some (Save_armed name) then begin
                         state.preset_armed <- Some (Save_armed name);
                         state.preset_confirmation_token <- Some (ref ());
                         state.preset_confirmation_presented <- None;
                         reveal_unconfirmed_preset_save state name;
                         state.config_scroll <- 0;
                         report_action state "error"
                           (ui_text state
                              ~ko:"저장 미확인 · Enter를 다시 누르면 같은 이름을 덮어씁니다"
                              ~en:"Save unconfirmed · press Enter again to overwrite this name")
                       end else if state.preset_armed = Some (Save_armed name)
                                   && not (Masc_tui_render_config.preset_confirmation_ready state) then
                         report_action state "system"
                           (ui_text state ~ko:"Home 후 PgDn으로 저장 경고를 처음부터 확인하세요"
                              ~en:"Use Home then PgDn to review the complete save warning")
                       else begin
                         state.preset_armed <- None;
                         let description = state.preset_save_draft_description in
                         let source = state.preset_save_draft_source in
                         let sharing = preset_save_is_pending state name in
                         if not sharing then begin
                           state.preset_save_draft <- None;
                           state.preset_save_draft_description <- "";
                           state.preset_save_draft_source <- Preset_form_local;
                           state.preset_save_draft_workspace <- None;
                           (match source with
                            | Preset_form_chat { target; input; revision; authority }
                              when authority = state.workspace_authority
                                   && state.msg_target_keeper_name = target
                                   && chat_input_workspace state = Some workspace
                                   && Masc_tui_message_input.has_revision state.msg_input revision
                                   && String.equal (Masc_tui_message_input.contents state.msg_input) input ->
                              Masc_tui_message_input.clear state.msg_input;
                              save_message_draft state
                            | Preset_form_chat _ | Preset_form_local -> ())
                         end;
                         state.preset_busy <- true;
                         report_action state "system"
                           (name ^ ui_text state ~ko:" 저장 중" ~en:" saving");
                         (match source with
                          | Preset_form_local ->
                            Masc_tui_surface_requests.Prompt_preset_requests.launch_preset_save state ~mailbox:async_messages
                              ~sink:Preset_to_pane ~name ~description ~chat_input:None ~also_pane:false
                          | Preset_form_chat { target; input; revision = _; authority = _ } ->
                            Masc_tui_surface_requests.Prompt_preset_requests.launch_preset_save state ~mailbox:async_messages
                              ~sink:(Preset_to_chat target) ~name ~description
                              ~chat_input:(Some input) ~also_pane:true)
                       end
                     end)
               | "\127" | "\b" | "backspace" ->
                 (match state.preset_save_draft_source with
                  | Preset_form_local ->
                    state.preset_save_draft <-
                      Some (Masc_tui_message_layout.drop_last_utf8_scalar draft)
                  | Preset_form_chat _ -> report_action state "system"
                      (ui_text state ~ko:"Esc로 닫고 채팅에서 명령을 수정하세요"
                         ~en:"Press Esc, then edit the command in chat"))
               | s when Masc_tui_message_layout.is_printable_utf8_scalar s ->
                 (match state.preset_save_draft_source with
                  | Preset_form_local -> state.preset_save_draft <- Some (draft ^ s)
                  | Preset_form_chat _ -> report_action state "system"
                      (ui_text state ~ko:"Esc로 닫고 채팅에서 명령을 수정하세요"
                         ~en:"Press Esc, then edit the command in chat"))
               | _ -> ()))
       (* Typing why a goal is dropped. Enter sends the drop with that
          reason; a blank reason stays open with the refusal on it, because
          the Server refuses a drop that does not say why. A sent reason stays
          open too, until a reading shows the goal no longer takes a drop
          ({!goal_action_pending_after_reading}): a drop kept back or failed
          keeps the sentence. *)
       | Some k
         when text_input_target state ~compact_viewport
              = Some Text_goal_drop_reason ->
           (match state.goal_action_pending with
            | Some (Goal_drop_reason entry) ->
              let set reason =
                state.goal_action_pending <- Some (Goal_drop_reason { entry with reason })
              in
              (match k with
               | "esc" ->
                 state.goal_action_pending <- None;
                 clear_goal_action_error state ~goal_id:entry.goal_id
               | "\r" | "\n" | "enter" ->
                 let reason = String.trim entry.reason in
                 if String.equal reason "" then
                   set_goal_action_error state ~goal_id:entry.goal_id "A drop needs a reason; type why, or Esc to cancel"
                 else if Result.is_error (Goal_store.validate_goal_id entry.goal_id) then
                   set_goal_action_error state ~goal_id:entry.goal_id "Cannot send this Goal ID; the drop reason is retained"
                 else if List.mem_assoc entry.goal_id state.goal_action_inflight then
                   set_goal_action_error state ~goal_id:entry.goal_id "A request is still in progress; the drop reason is retained"
                 else begin
                   clear_goal_action_error state ~goal_id:entry.goal_id;
                   Masc_tui_work_actions.Goal_actions.start_goal_transition state ~mailbox:async_messages ~note:reason
                     ~goal_id:entry.goal_id ~action:Goal_phase.Public_action.Drop
                 end
               | "\127" | "\b" | "backspace" ->
                 set (Masc_tui_message_layout.drop_last_utf8_scalar entry.reason)
               | s when Masc_tui_message_layout.is_printable_utf8_scalar s -> set (entry.reason ^ s)
               | _ -> ())
            | Some (Goal_action_armed _) | None -> ())
       (* Typing a new lane's name. Enter opens the failover picker on the
          name, and the first runtime picked there declares the lane: a lane
          is its candidates, so it comes to exist with one rather than empty.
          Every printable key is the field's while it is open, so a name with
          an x or a D in it does not fire the lane keys under it. *)
       | Some k
         when not compact_viewport
              && text_input_target state ~compact_viewport
                 = Some Text_runtime_lane_name ->
           (match state.runtime_lane_name_draft with
            | None -> ()
            | Some entry ->
              let draft = Masc_tui_types.lane_name_entry_draft entry in
              let set text =
                state.runtime_lane_name_draft <-
                  Some (Masc_tui_types.lane_name_entry_with_draft entry text)
              in
              (match k with
               | "esc" -> state.runtime_lane_name_draft <- None
               | "pageup" ->
                   (* Read the complete draft, original target and diagnostics
                      above this field. Esc returns without submitting it. *)
                   state.runtime_detail_target <- Some Runtime_routes;
                   state.runtime_detail_scroll <- 0
               | "\r" | "\n" | "enter" ->
                 let name = String.trim draft in
                 if not (String.equal name "") then begin
                   match entry with
                   | Masc_tui_types.Renaming_lane _
                     when Masc_tui_types.runtime_lane_write_busy state ->
                       state.runtime_lane_notice <- Some Masc_tui_types.Lane_write_pending
                   | Masc_tui_types.Naming_new_lane _ | Masc_tui_types.Renaming_lane _ ->
                     state.runtime_lane_name_draft <- None;
                     Masc_tui_types.dismiss_runtime_lane_notice state;
                     match entry with
                     | Masc_tui_types.Naming_new_lane _ ->
                       (* A lane is its candidates, so it comes to exist with
                          one: the picker that opens here declares it. *)
                       Masc_tui_types.open_runtime_lane_pick state
                         (Masc_tui_types.Pick_new_lane name)
                     | Masc_tui_types.Renaming_lane { lane; _ } ->
                       (* The rename lands in one write, references and all, so
                          there is nothing to pick and nothing to follow. *)
                       Masc_tui_chat_dispatch.Runtime_picker.launch_runtime_lane_write state ~mailbox:async_messages
                         ~written:Masc_tui_types.Runtime_surface_list (fun ~host ~port ->
                         Masc_tui_http.rename_runtime_lane ~host ~port ~lane ~new_lane:name)
                 end
               | "\127" | "\b" | "backspace" ->
                 set (Masc_tui_message_layout.drop_last_utf8_scalar draft)
               | s when Masc_tui_message_layout.is_printable_utf8_scalar s -> set (draft ^ s)
               | _ -> ()))
       (* Pending and unknown commits freeze their immutable submitted input.
          Esc leaves the operation running/retained; Ctrl-X deliberately ends
          recovery only after a terminal receipt. Neither key sends a retry. *)
       | Some k when (text_input_target state ~compact_viewport = Some Text_runtime_model_form
                     || text_input_target state ~compact_viewport = Some Text_runtime_account_form)
           && (runtime_form_input_locked state
               || ((k = "ctrl-x" || k = "\024") && Option.is_some (runtime_form_focused_attempt state))) ->
           let close () =
             state.runtime_model_form <- None; state.runtime_account_form <- None;
             state.runtime_form_save_focus <- None in
           (match k, runtime_form_focused_attempt state with
            | "esc", _ -> close ()
            | ("ctrl-x" | "\024"), Some {rfa_status=Form_finished _;_} ->
                release_runtime_form_recovery state; close ();
                Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_config_load ~force:true state ~mailbox:async_messages
            | _, None
            | _, Some {rfa_status=(Form_checking | Form_previewing _
                | Form_posting _ | Form_finished _);_} -> ())
       | Some k
         when text_input_target state ~compact_viewport = Some Text_runtime_model_form ->
           (match state.runtime_model_form with
            | None -> ()
            | Some form -> match Masc_tui_model_form.key form k with
              | Editing form -> release_runtime_form_recovery state;
                  state.runtime_model_form <- Some form
              | Cancelled -> state.runtime_model_form <- None; state.runtime_form_save_focus <- None
              | Submit form ->
                  (match begin_runtime_form_save state ~draft:(Model_form_draft form)
                      ~started_ns:(Mtime_clock.elapsed_ns ()) with
                   | Ok request -> Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_form_save state ~mailbox:async_messages request
                   | Error detail -> state.runtime_model_form <- Some (Masc_tui_model_form.refused form detail)))
       | Some k
         when text_input_target state ~compact_viewport = Some Text_memory_recall_form ->
           (match state.memory_recall_form with
            | None -> ()
            | Some form -> match Masc_tui_memory_recall_form.key form k with
              | Masc_tui_memory_recall_form.Editing form -> state.memory_recall_form <- Some form
              | Masc_tui_memory_recall_form.Cancelled -> state.memory_recall_form <- None
              | Masc_tui_memory_recall_form.Submitted form -> Masc_tui_editor_forms.Runtime_config_forms.submit_memory_recall_form state ~mailbox:async_messages form)
       | Some k
         when text_input_target state ~compact_viewport = Some Text_typesafeai_exclusion_form ->
           (match state.typesafeai_exclusion_form with
            | None -> ()
            | Some form -> match Masc_tui_typesafeai_exclusion_form.key form k with
              | Masc_tui_typesafeai_exclusion_form.Editing form ->
                state.typesafeai_exclusion_form <- Some form
              | Masc_tui_typesafeai_exclusion_form.Cancelled -> state.typesafeai_exclusion_form <- None
              | Masc_tui_typesafeai_exclusion_form.Submitted form ->
                Masc_tui_editor_forms.Runtime_config_forms.submit_typesafeai_exclusion_form state ~mailbox:async_messages form)
       | Some k
         when text_input_target state ~compact_viewport = Some Text_runtime_account_form ->
           (match state.runtime_account_form with
            | None -> ()
            | Some form -> match Masc_tui_runtime_account_form.key form k with
              | Masc_tui_runtime_account_form.Editing form ->
                  release_runtime_form_recovery state; state.runtime_account_form <- Some form
              | Masc_tui_runtime_account_form.Cancelled ->
                  state.runtime_account_form <- None; state.runtime_form_save_focus <- None
              | Masc_tui_runtime_account_form.Copy (form, command) ->
                  state.runtime_account_form <- Some form;
                  let outcome = copy_reference render_schedule command in
                  report_action state "system"
                    (if state.ui_language = Lang_ko then
                       "로그인 명령을 " ^ Masc_tui_clipboard.copy_outcome_text_korean outcome
                     else
                       "Login command " ^ Masc_tui_clipboard.copy_outcome_text outcome)
              | Masc_tui_runtime_account_form.Submitted form ->
                  (match begin_runtime_form_save state ~draft:(Account_form_draft form)
                      ~started_ns:(Mtime_clock.elapsed_ns ()) with
                   | Ok request -> Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_form_save state ~mailbox:async_messages request
                   | Error detail -> state.runtime_account_form <- Some
                       (Masc_tui_runtime_account_form.refused form detail)))
       | Some k
         when not compact_viewport
              && text_input_target state ~compact_viewport
                 = Some Text_runtime_param ->
           (match state.runtime_param_edit with
            | None -> ()
            | Some edit ->
              let set value = state.runtime_param_edit <- Some value in
              (match k with
               | "esc" ->
                 state.runtime_param_edit <- None;
                 state.runtime_params_notice <-
                   Some (Params_said (true, edit.rpe_key ^ ": edit cancelled"))
               | "home" | "end" ->
                 state.config_scroll <-
                   (if String.equal k "home" then 0 else Masc_tui_types.clamped_scroll_end)
               | "pageup" | "pagedown" ->
                 let terminal_rows, _ = get_terminal_size () in
                 let _, detail_height =
                   Masc_tui_types.runtime_params_viewport state ~terminal_rows in
                 let page = max 1 (detail_height - 1) in
                 state.config_scroll <-
                   Masc_tui_scroll.step_uncounted
                     ~delta:(if String.equal k "pagedown" then page else -page)
                     state.config_scroll
               | "\r" | "\n" | "enter" -> Masc_tui_editor_forms.Runtime_config_forms.handle_runtime_param_edit_apply state ~mailbox:async_messages
               | "\127" | "\b" | "backspace" ->
                 set (Masc_tui_types.runtime_param_edit_backspace edit);
                 state.runtime_params_notice <- None
               | s when String.length s = 1 && Char.code s.[0] = 21 ->
                 set (Masc_tui_types.runtime_param_edit_clear edit);
                 state.runtime_params_notice <- None
               | "left" | "right" | " "
                 when edit.rpe_mode = Masc_tui_types.Friendly_value
                      && List.mem
                           (Masc_tui_types.runtime_param_type_name
                              edit.rpe_value_type)
                           [ "bool"; "boolean" ] ->
                 set (Masc_tui_types.runtime_param_edit_toggle_bool edit);
                 state.runtime_params_notice <- None
               (* A closed set walks under the same keys a bool toggles under:
                  the reader is picking either way, and Left/Right reading as
                  "the other value" for two choices and "the next value" for
                  three is the same gesture. Ordered after the bool arm so a
                  bool with choices — none today — keeps toggling. *)
               | "left" | " "
                 when edit.rpe_mode = Masc_tui_types.Friendly_value
                      && edit.rpe_choices <> [] ->
                 set
                   (Masc_tui_types.runtime_param_edit_cycle_choice edit
                      ~step:(if String.equal k "left" then -1 else 1));
                 state.runtime_params_notice <- None
               | "right"
                 when edit.rpe_mode = Masc_tui_types.Friendly_value
                      && edit.rpe_choices <> [] ->
                 set (Masc_tui_types.runtime_param_edit_cycle_choice edit ~step:1);
                 state.runtime_params_notice <- None
               | s
                 when (String.length s = 1 && Char.code s.[0] >= 32)
                      || (String.length s > 1 && Char.code s.[0] >= 0x80) ->
                 set (Masc_tui_types.runtime_param_edit_append edit s);
                 state.runtime_params_notice <- None
               | _ -> ()))
       | Some k
         when text_input_target state ~compact_viewport = Some Text_voice_wizard ->
           (match state.voice_wizard with
            | None -> ()
            | Some session ->
              let set value = state.voice_wizard <- Some value in
              (* A save in flight ignores everything but the key that leaves:
                 the draft it is writing is already on its way. *)
              if Masc_tui_voice_wizard_session.voice_wizard_is_sending session && not (String.equal k "esc")
              then ()
              else (
                match k with
                | "esc" ->
                  state.voice_wizard <- None;
                  state.config_scroll <- 0
                (* Up and down are the steps, so reading a probe report that
                   runs past the frame takes the page keys. The frame clamps
                   and reports the offset back. *)
                | "pageup" ->
                  state.config_scroll <- max 0 (state.config_scroll - surface_page_rows state)
                | "pagedown" ->
                  state.config_scroll <-
                    Masc_tui_types.scroll_down_from state.config_scroll
                      ~by:(surface_page_rows state)
                | "home" -> state.config_scroll <- 0
                | "end" -> state.config_scroll <- Masc_tui_types.clamped_scroll_end
                | "\r" | "\n" | "enter" ->
                  (match session.vws_step with
                   | Voice_wizard.Review ->
                     Masc_tui_work_requests.Voice_requests.launch_voice_wizard_save state ~mailbox:async_messages
                       (Masc_tui_voice_wizard_session.voice_wizard_commit session)
                   | Voice_wizard.Section
                   | Voice_wizard.Provider
                   | Voice_wizard.Name
                   | Voice_wizard.Address
                   | Voice_wizard.Credential
                   | Voice_wizard.Model
                   | Voice_wizard.Voice -> set (Masc_tui_voice_wizard_session.voice_wizard_next session))
                | "up" -> set (Masc_tui_voice_wizard_session.voice_wizard_previous session)
                | "down" -> set (Masc_tui_voice_wizard_session.voice_wizard_next session)
                (* The provider is a closed set, so it walks under the same keys
                   a bool toggles under elsewhere in this pane. *)
                | "left" | "right" | " "
                  when session.vws_step = Voice_wizard.Section ->
                  set (Masc_tui_voice_wizard_session.voice_wizard_cycle_section session)
                | "left" | "right" | " "
                  when session.vws_step = Voice_wizard.Provider ->
                  set (Masc_tui_voice_wizard_session.voice_wizard_cycle_provider session)
                | "\127" | "\b" | "backspace" ->
                  set (Masc_tui_voice_wizard_session.voice_wizard_backspace session)
                | s when String.length s = 1 && Char.code s.[0] = 21 ->
                  set (Masc_tui_voice_wizard_session.voice_wizard_clear session)
                | s
                  when (String.length s = 1 && Char.code s.[0] >= 32)
                       || (String.length s > 1 && Char.code s.[0] >= 0x80) ->
                  set (Masc_tui_voice_wizard_session.voice_wizard_append session s)
                | _ -> ()))
       (* The launch form owns every key while it is up, above the quit key
          the way the Lane Add-ons form is: a prompt with a q in it is a
          prompt. Its paste arrives through [Text_fusion_launch], which is
          claimed under the same viewport condition -- a frame too small to
          draw the form must not feed it keys either. *)
       | Some key
         when state.view = Fusion && not compact_viewport
              && (match state.fusion_launch with
                  | Some (Fusion_launch_reading_presets _ | Fusion_launch_open _) -> true
                  | Some (Fusion_launch_started _) | None -> false) ->
           (match state.fusion_launch with
            | Some (Fusion_launch_reading_presets _) ->
                (* Leaving bumps the generation, so the read's answer finds
                   no form to open. *)
                if String.equal key "esc" then begin
                  state.fusion_launch_generation <- state.fusion_launch_generation + 1;
                  state.fusion_launch <- None
                end
            | Some (Fusion_launch_open launch) ->
                (match key with
                 | "pageup" ->
                     state.fusion_scroll
                       <- max 0 (state.fusion_scroll - surface_page_rows state)
                 | "pagedown" ->
                     state.fusion_scroll
                       <- Masc_tui_types.scroll_down_from state.fusion_scroll
                            ~by:(surface_page_rows state)
                 | _ ->
                     (match Masc_tui_fusion_launch.edit ~key launch with
                      | Masc_tui_fusion_launch.Closed ->
                          (* The operator stays on Fusion, so this is the
                             drop itself rather than a surface jump. Its
                             answer is whether a submit was still out. *)
                          if Masc_tui_types.abandon_fusion_launch state then
                            report_action state "system"
                              "Fusion launch left while its answer was out; the run may have \
                               started - r refreshes the list";
                          state.fusion_scroll <- 0
                      | Masc_tui_fusion_launch.Editing next ->
                          state.fusion_launch <- Some (Fusion_launch_open next);
                          state.fusion_scroll <- 0
                      | Masc_tui_fusion_launch.Submitted (next, request) ->
                          state.fusion_launch <- Some (Fusion_launch_open next);
                          state.fusion_scroll <- 0;
                          start_fusion_run state ~mailbox:async_messages ~request))
            | Some (Fusion_launch_started _) | None -> ())
       (* A visible arrival consumes its first key. Esc leaves the overlay; every
          other key reaches the final frame without also activating a shortcut
          below it. In particular q cannot arm quit while skipping motion. *)
       (* [quit_key] is already false while anything is taking typed text, the
          row search and the Board draft among them, so this asks nothing more
          than that. It used to restate those two by hand and let a compact
          viewport override them, which is how a [q] typed into a narrow
          screen's row search armed the exit. *)
       | Some _ when quit_key ->
           handle_quit_key ()
       (* Also above the modals: the roster is chrome around whatever is
          showing, and reclaiming its columns should not depend on which
          surface is up. *)
       | Some k when String.equal k Masc_tui_shell.Terminal_session.toggle_roster_pane_key -> toggle_roster_chrome ()
       | Some k when String.equal k Masc_tui_shell.Terminal_session.toggle_acting_pane_key -> toggle_activity_chrome ()
       | Some k when (let terminal_rows, _ = get_terminal_size () in
             match Masc_tui_render.frame_choice state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) with
             | `Queue _ -> true | _ -> false) ->
           Option.iter (fun panel ->
             handle_queue_panel_key state ~base_path ~mailbox:async_messages
               ~presented_presses:(!presented).presses panel k) state.queue_panel
       (* The Activity pane holds these keys while its cursor is up. Above
          the surfaces on purpose: a [j] here must not also move the list
          beside the pane. Any other key reaches the surface unchanged. *)
       | Some k
         when Option.is_some state.acting_pane_cursor
              && not state.keeper_navigation_open
              && acting_pane_drawn state
              && Option.is_none (text_input_target state ~compact_viewport)
              && List.mem k acting_pane_focus_keys ->
           let row = Option.value state.acting_pane_cursor ~default:0 in
           handle_acting_pane_focus_key state ~base_path ~mailbox:async_messages
             ~row k;
           Render_schedule.request render_schedule Render_schedule.Force
       (* Ctrl-W on a surface without a pane cycle of its own goes straight
          to the Activity pane. Board and Resources keep their cycles below,
          with the pane as the last stop; the chat keeps Ctrl-W for the word
          in its draft and gives it up only when the draft is empty. *)
       | Some "\023"
         when Option.is_none state.acting_pane_cursor
              && not state.keeper_navigation_open
              && acting_pane_drawn state
              && Option.is_none (text_input_target state ~compact_viewport)
              && state.view <> Board && state.view <> Resources
              && (state.view <> Keepers Keeper_message
                  || Masc_tui_message_input.length state.msg_input = 0) ->
           focus_acting_pane_or_say_why state;
           Render_schedule.request render_schedule Render_schedule.Force
       (* lazygit-style +/- screen zoom: '+' steps Normal -> Half -> Full
          (hiding the right Activity pane at Half and both side panes at Full),
          '_' steps back without overwriting stored Ctrl-B/Ctrl-L choices.
          Excluded from chat ([message_mode]), composer focus, Browser Lane,
          modals, and all text inputs so '+' and '_' always type normally. *)
       | Some (("+" | "_") as zoom_key)
         when not message_mode
              && not state.composer_focused
              && Option.is_none (browser_lane_on_screen state)
              && not state.palette_open && not (modal_owns_keys state)
              && not state.answering_open
              && not state.link_modal_open
              && not state.memory_fact_detail_open
              && not state.keeper_navigation_open
              && Option.is_none state.ask_text_entry
              && (match state.ask_answer_mode with Ask_browsing -> true | Ask_answering _ -> false)
              && Option.is_none (text_input_target state ~compact_viewport) ->
           let _raw_rows, raw_cols = Masc_tui_ansi.get_terminal_size () in
           let activity_available =
             not (Masc_tui_render.acting_pane_suppressed state)
             && Masc_tui_acting_pane.drawn_cols
                  ~layout:(stored_acting_pane_layout state) ~cols:raw_cols
                > 0
           in
           let roster_available =
             not (Masc_tui_roster_pane.effective_hidden state.roster_pane_preference)
             && Masc_tui_roster_pane.shown ~hidden:false ~cols:raw_cols
           in
           let direction = if String.equal zoom_key "+" then `In else `Out in
           let ko = state.ui_language = Lang_ko in
           (match
              Masc_tui_roster_pane.step_zoom ~zoom:state.pane_zoom ~direction
                ~activity_available ~roster_available
            with
            | None ->
                report_action state "view"
                  (if ko then "접을 수 있는 사이드 패널이 없어 줌을 변경하지 않았습니다"
                   else "No side pane is drawn on this screen/width; zoom unchanged")
            | Some next ->
                if next <> state.pane_zoom then begin
                  state.pane_zoom <- next;
                  if Masc_tui_roster_pane.hides_activity next then
                    state.acting_pane_cursor <- None;
                  if Masc_tui_roster_pane.hides_roster next then
                    state.keeper_detail_focus <- Right_pane;
                  reconcile_chat_focus ()
                end;
                report_action state "view"
                  (Masc_tui_roster_pane.zoom_label ~ko state.pane_zoom));
           Render_schedule.request render_schedule Render_schedule.Force
       | Some k
         when String.equal k Masc_tui_shell.Terminal_session.toggle_browser_lane_key
              && not state.palette_open && not (modal_owns_keys state)
              && not state.answering_open
              && not state.link_modal_open
              && Option.is_none state.ask_text_entry
              && (match state.ask_answer_mode with Ask_browsing -> true | Ask_answering _ -> false)
              && Option.is_none (text_input_target state ~compact_viewport) ->
           (match browser_lane_on_screen state with
            | Some _ -> leave_browser_lane state ~mailbox:async_messages
            | None ->
                Masc_tui_surface_requests.Lane_browser_requests.open_browser_lane state ~mailbox:async_messages);
           Render_schedule.request render_schedule Render_schedule.Force
       (* Writing an answer takes every printable key, the way the row search
          and the app form do, and it sits above the answering arm because
          that arm reads digits as choices and [s]/[c] as commands. An
          operator typing "1 second" must not have the 1 picked for them. *)
       | Some k
         when state.view = Approvals
              && Option.is_some state.ask_text_entry
              && not (modal_owns_keys state) ->
           (match k with
            | "esc" -> Masc_tui_operator_actions.Ask_actions.cancel_ask_text_entry state
            | "\r" | "\n" | "enter" -> Masc_tui_operator_actions.Ask_actions.commit_ask_text_entry state
            | "\127" | "\b" | "backspace" ->
                Masc_tui_operator_actions.Ask_actions.edit_ask_text state Masc_tui_message_layout.drop_last_utf8_scalar
            | s
              when (String.length s = 1 && Char.code s.[0] >= 32)
                   || (String.length s > 1 && Char.code s.[0] >= 0x80) ->
                Masc_tui_operator_actions.Ask_actions.edit_ask_text state (fun text -> text ^ s)
            | _ -> ());
           Render_schedule.request render_schedule Render_schedule.Force
       (* Answering is modal. A question needs a key per choice, and this
          surface already spent its arrows and its y/n on the approval queue,
          so the keys have to come from somewhere. Quit and the chrome
          toggles stay above this on purpose: an operator who wants out of
          the terminal should not have to leave a draft first. *)
       | Some k
         when state.view = Approvals
              && (match state.ask_answer_mode with
                  | Ask_answering _ -> true
                  | Ask_browsing -> false)
              && not (modal_owns_keys state) ->
           (match k with
            | "esc" ->
                Masc_tui_operator_actions.Ask_actions.leave_ask_answering state;
                (match state.home_opened_request with
                 | Some (Home_question _) ->
                     goto_surface state ~mailbox:async_messages Overview
                 | Some (Home_held_call _) | None | Some (Home_gate_request _)
                 | Some (Home_operator_request _) | Some (Home_goal_confirmation _) -> ())
            | "left" | "up" | "k" -> Masc_tui_operator_actions.Ask_actions.move_ask_question_cursor state (-1)
            | "right" | "down" | "j" -> Masc_tui_operator_actions.Ask_actions.move_ask_question_cursor state 1
            | "pageup" | "pagedown" | "wheel-up" | "wheel-down" ->
                let delta = match k with
                  | "pageup" -> -(Masc_tui_render_approvals.ask_question_page_size state)
                  | "pagedown" -> Masc_tui_render_approvals.ask_question_page_size state
                  | "wheel-up" -> -1 | _ -> 1 in
                state.ask_question_scroll <- max 0
                  (min (Masc_tui_render_approvals.ask_question_scroll_limit state)
                     (state.ask_question_scroll + delta))
            (* This arm takes every key while a question is open, so the
               surface Home and End below never reach it -- and reaching it
               would be worse than nothing, moving the approvals cursor under
               a reader that is drawing something else. The question's own
               ends, against the same limit the page keys clamp to. *)
            | "home" -> state.ask_question_scroll <- 0
            | "end" ->
                state.ask_question_scroll <-
                  Masc_tui_render_approvals.ask_question_scroll_limit state
            | "[" -> state.home_opened_request <- None; Masc_tui_operator_actions.Ask_actions.move_ask_cursor state (-1)
            | "]" -> state.home_opened_request <- None; Masc_tui_operator_actions.Ask_actions.move_ask_cursor state 1
            | "o" -> toggle_selected_ask_origin state
            | "O" -> Masc_tui_operator_actions.Ask_actions.inspect_selected_ask_origin state ~mailbox:async_messages
            | "s" | "S" -> Masc_tui_operator_actions.Ask_actions.skip_ask_question state
            | "c" | "C" -> Masc_tui_operator_actions.Ask_actions.clear_ask_question state
            (* Ahead of the digit arm below, which takes every one-character
               key and drops the ones that are not positions -- [t] landed
               there and did nothing. *)
            | "t" | "T" -> Masc_tui_operator_actions.Ask_actions.begin_ask_text_entry state
            (* Terminals send Enter as CR. "enter" is the name the Kitty
               protocol gives codepoint 13, and this was the only site in the
               file waiting for it -- the other twelve read "\r" -- so the
               answer could be composed and never sent. *)
            | "\r" | "\n" | "enter" ->
                Masc_tui_operator_actions.Ask_actions.handle_ask_submit state ~mailbox:async_messages
            | digit when String.length digit = 1 -> (
                (* Parsed, not matched: a choice is picked by its position in
                   the list the server sent, and anything that is not a
                   position is not a choice. *)
                match int_of_string_opt digit with
                | Some position when position >= 1 && position <= 9 ->
                    (match selected_ask_question state with
                     | Some question when Ask.alternative_position question = Some position ->
                         Masc_tui_operator_actions.Ask_actions.begin_ask_text_entry state
                     | Some _ | None -> Masc_tui_operator_actions.Ask_actions.toggle_ask_choice state (position - 1))
                | Some _ | None -> ())
            | _ -> ());
           Render_schedule.request render_schedule Render_schedule.Force
       | Some ("o" | "O" as key)
         when state.view = Approvals
              && not state.context_inspector_open
              && Option.is_none (text_input_target state ~compact_viewport)
              && (not state.approval_detail_open)
              && not (modal_owns_keys state) ->
           (if String.equal key "o" then toggle_selected_ask_origin state
            else Masc_tui_operator_actions.Ask_actions.inspect_selected_ask_origin state ~mailbox:async_messages);
           Render_schedule.request render_schedule Render_schedule.Force
       (* The same two keys the answering mode uses, so the walk does not
          change shape when the operator commits. j/k cannot serve here: the
          approval queue above owns them, which is why this list had no way to
          move at all -- [a] opened whichever ask the cursor had been left on,
          and with more than one waiting there was no way to reach the rest
          without answering the first. *)
       (* The text check is the one the Activity pane above already makes.
          Without it these two keys were taken from the command palette while
          it was open over this surface, so a query with a bracket in it --
          a task title, [#31874] -- arrived with the brackets missing and the
          ask cursor moved behind the overlay. *)
       | Some ("[" | "]" as k)
         when state.view = Approvals
              && Option.is_none (text_input_target state ~compact_viewport)
              && (match state.ask_answer_mode with
                  | Ask_browsing -> true
                  | Ask_answering _ -> false)
              && (not state.approval_detail_open)
              && not (modal_owns_keys state) ->
           Masc_tui_operator_actions.Ask_actions.move_ask_cursor state (if String.equal k "[" then -1 else 1);
           Render_schedule.request render_schedule Render_schedule.Force
       (* [/context] is modal: the summary and exact input text must not leak
          keys into the composer underneath. The quit confirmation and chrome
          toggles remain global above it, matching Help and Palette. An
          active surface search outranks it: typing during a search is the
          search, and the search arm below owns those keys. *)
       | Some k when Option.is_some (current_board_reader state) ->
           let reader=state.board_reader in
           let document=Masc_tui_board_reader.document reader in
           let count,height=Masc_tui_render_overlays.detail_reading_viewport state document in
           let _,cols=get_terminal_size () in
           (match Masc_tui_board_reader.search_key
             ~width:(Masc_tui_render_overlays.detail_reading_width cols) ~height ~key:k reader with
            | Some reader -> state.board_reader <- reader
            | None -> match k with
            | "esc" -> close_board_reader state
            | "r" ->
                (match state.board_reader_owner, Masc_tui_board_reader.key reader with
                 | Some (_,_,kind), Some key -> launch_board_read state ~mailbox:async_messages ~kind key
                 | (Some _ | None), (Some _ | None) -> ())
            | "u" | "m" | "h" ->
                cancel_board_preparation state;
                state.board_reader <- Masc_tui_board_reader.select
                  (match k with "m" -> Markdown | "h" -> Html | _ -> Source) reader
            | "y" -> (match Masc_tui_board_reader.source reader with
                | Ok source ->
                    let outcome = copy_reference render_schedule source in
                    report_action state "system"
                      (if state.ui_language = Lang_ko then
                         "첨부 원본을 " ^ Masc_tui_clipboard.copy_outcome_text_korean outcome
                       else
                         "Original attachment " ^ Masc_tui_clipboard.copy_outcome_text outcome)
                | Error error -> report_action state "error" error)
            | "s" -> use_board_read state ~mailbox:async_messages ~action:Save_board_original
            | "o" ->
                if !share_interrupt_barrier || Masc_tui_exit_signals.pending_signal exit_signals then
                  report_action state "system" "Image opening interrupted; use the key again when ready."
                else if Option.exists (fun (_,_,kind) -> kind = Ak_image) state.board_reader_owner then
                  use_board_read state ~mailbox:async_messages ~action:Open_board_image
            | "j" | "down" | "wheel-down" | "k" | "up" | "wheel-up"
            | "pagedown" | "pageup" | "home" | "g" | "end" | "G" ->
                let movement=match k with
                  | "j" | "down" | "wheel-down" -> Masc_tui_detail_reading.By 1
                  | "k" | "up" | "wheel-up" -> By (-1)
                  | "pagedown" -> Page_down | "pageup" -> Page_up
                  | "home" | "g" -> First | _ -> Last in
                state.board_reader <- Masc_tui_board_reader.move ~count ~height movement reader
            | _ -> ())
       | Some k when Option.is_some (current_chat_call_reader state) ->
           (match state.chat_call_reader with
            | None -> ()
            | Some (origin,reader) ->
              let update reader = state.chat_call_reader <- Some (origin,reader) in
              let count,height = Masc_tui_render_overlays.detail_reading_viewport state
                (Masc_tui_chat_call_reader.document reader) in
              let _,cols=get_terminal_size () in
              match Masc_tui_chat_call_reader.search_key
                ~width:(Masc_tui_render_overlays.detail_reading_width cols) ~height ~key:k reader with
              | Some reader -> update reader
              | None -> match Masc_tui_chat_call_reader.action ~key:k reader with
              | Close ->
                  if Masc_tui_chat_call_reader.choosing reader then Masc_tui_work_requests.Schedule_call_requests.close_chat_call_reader state
                  else begin Masc_tui_work_requests.Schedule_call_requests.cancel_chat_call_pending state;
                    update (Masc_tui_chat_call_reader.back reader) end
              | Choose delta -> update (Masc_tui_chat_call_reader.choose delta reader)
              | Open | Retry -> Masc_tui_work_requests.Schedule_call_requests.launch_chat_call_read state ~mailbox:async_messages
              | Move movement -> update (Masc_tui_chat_call_reader.move ~count ~height movement reader)
              | Ignore -> ())
       | Some k when Option.is_some (current_task_inspector state) ->
           (match current_task_inspector state with
            | None -> ()
            | Some reader ->
              let original=reader.tci_original in
              let source=task_inspection_source original in
              let count,height=Masc_tui_render_overlays.detail_reading_viewport state
                (Masc_tui_original_task_read.document source) in
              let _,cols=get_terminal_size () in
              match Masc_tui_original_task_read.search_key
                ~width:(Masc_tui_render_overlays.detail_reading_width cols) ~height ~key:k source with
              | Some source -> set_task_inspection_source original source
              | None -> if k="esc" then Masc_tui_chat_dispatch.Task_dispatch.close_task_inspection_reader state
              else if k="r" then
                (match Masc_tui_original_task_read.displayed_source source with
                 | Origin -> (match Masc_tui_original_task_read.origin source with
                   | Task_creation _ -> Masc_tui_chat_dispatch.Task_dispatch.launch_task_creation_read state ~mailbox:async_messages
                   | Answered_ask _ -> Masc_tui_chat_dispatch.Task_dispatch.launch_original_task_read state ~mailbox:async_messages)
                 | Task -> Masc_tui_chat_dispatch.Task_dispatch.launch_original_task_read state ~mailbox:async_messages
                 | History -> Masc_tui_chat_dispatch.Task_dispatch.launch_original_history_read state ~mailbox:async_messages ~earlier:false ~limit:(max 1 height)
                 | Evidence -> Masc_tui_chat_dispatch.Task_dispatch.launch_original_evidence_read state ~mailbox:async_messages ~next:false)
              else if k="[" || k="]" then
                (match task_creation_neighbor state ~older:(k="[") with
                 | None -> ()
                 | Some original ->
                   Masc_tui_chat_dispatch.Task_dispatch.close_task_inspection_reader state;
                   if select_task_creation_inspection state original then
                     Masc_tui_chat_dispatch.Task_dispatch.launch_task_creation_read state ~mailbox:async_messages)
              else if k="o" then Masc_tui_chat_dispatch.Task_dispatch.launch_original_task_read state ~mailbox:async_messages
              else if k="h" || k="H" then Masc_tui_chat_dispatch.Task_dispatch.launch_original_history_read state ~mailbox:async_messages ~earlier:(k="H") ~limit:(max 1 height)
              else if k="v" then Masc_tui_chat_dispatch.Task_dispatch.launch_original_evidence_read state ~mailbox:async_messages ~next:true
              else if k="b" then begin
                Masc_tui_chat_dispatch.Task_dispatch.cancel_task_inspection_read state;
                set_task_inspection_source original (Masc_tui_original_task_read.back_to_origin (task_inspection_source original))
              end
              else
                let movement=match k with
                  | "j" | "down" | "wheel-down" -> Some (Masc_tui_detail_reading.By 1)
                  | "k" | "up" | "wheel-up" -> Some (Masc_tui_detail_reading.By (-1))
                  | "pagedown" -> Some Masc_tui_detail_reading.Page_down
                  | "pageup" -> Some Masc_tui_detail_reading.Page_up
                  | "home" | "g" -> Some Masc_tui_detail_reading.First
                  | "end" | "G" -> Some Masc_tui_detail_reading.Last
                  | _ -> None in
                Option.iter (fun movement -> set_task_inspection_source original
                  (Masc_tui_original_task_read.move ~count ~height movement source)) movement)
       | Some k when Option.is_some (current_detail_reading state) ->
           (match current_detail_reading state with
            | None -> ()
            | Some reading ->
                let count, height = Masc_tui_render_overlays.detail_reading_viewport state reading in
                let _,cols=get_terminal_size () in
                match Masc_tui_detail_reading.search_key
                  ~width:(Masc_tui_render_overlays.detail_reading_width cols) ~height ~key:k reading with
                | Some reading -> update_detail_reading state reading
                | None ->
                  if k="esc" || k="v" then close_detail_reading state
                  else if Option.is_some state.keeper_peer_reading && (k="[" || k="]") then
                    (match move_keeper_peer_selection state
                       ~move:(if k="[" then Masc_tui_queue_inspection.Previous_peer
                              else Masc_tui_queue_inspection.Next_peer) with
                     | Ok () -> ()
                     | Error detail -> report_action state "info" detail)
                  else if Option.is_some state.keeper_peer_reading
                          && (k="enter" || k="\r" || k="\n") then begin
                    let terminal_rows, terminal_cols = Masc_tui_ansi.get_terminal_size () in
                    let target = match Masc_tui_ansi.probe_terminal_size () with
                      | Some physical when physical = (terminal_rows, terminal_cols)
                          && not (Terminal_write_repair.damage_pending ())
                          && not (Masc_tui_shell.Terminal_session.resize_requested terminal_session) ->
                          (match !presented_peer_target,
                                 peer_target_on_screen ~terminal_rows ~terminal_cols with
                           | Some presented, Some current
                             when same_keeper_peer_target presented current -> Some presented
                           | (Some _ | None), (Some _ | None) -> None)
                      | Some _ | None -> None in
                    (match target with
                     | None -> report_action state "info"
                         "Show the complete selected relationship before opening its sender"
                     | Some target ->
                         (match keeper_peer_sender_target state target with
                          | Error detail -> report_action state "error" detail
                          | Ok keeper ->
                              close_detail_reading state;
                              state.detail_tab <- Detail_info;
                              open_keeper_detail state ~mailbox:async_messages keeper))
                  end
                  else if Option.is_some state.keeper_peer_reading
                          && (k="<" || k=">" || k="r" || k="R") then begin
                    let move = match k with
                      | "<" -> Peer_previous
                      | ">" -> Peer_next
                      | "R" -> Peer_restart
                      | _ -> Peer_refresh in
                    Option.iter (fun (keeper_name, token, after_sequence) ->
                      Masc_tui_collab_queue.Keeper_queue.launch_keeper_queue state ~mailbox:async_messages ~keeper_name
                        (Masc_tui_queue_inspection.Inspect_peers (token, after_sequence)))
                      (request_keeper_peer_page state move)
                  end
                  else
                  let movement = match k with
                    | "j" | "down" | "wheel-down" -> Some (Masc_tui_detail_reading.By 1)
                    | "k" | "up" | "wheel-up" -> Some (Masc_tui_detail_reading.By (-1))
                    | "pagedown" -> Some Masc_tui_detail_reading.Page_down
                    | "pageup" -> Some Masc_tui_detail_reading.Page_up
                    | "home" | "g" -> Some Masc_tui_detail_reading.First
                    | "end" | "G" -> Some Masc_tui_detail_reading.Last
                    | _ -> None in
                  Option.iter (fun movement ->
                    update_detail_reading state
                      (Masc_tui_detail_reading.move ~count ~height movement reading)) movement)
       | Some "S"
         when state.view=Board && not state.composer_focused
              && not (modal_owns_keys state) && not state.palette_open
              && not state.answering_open && not state.link_modal_open
              && Option.is_none (text_input_target state ~compact_viewport)
              && (match state.board_mode with Board_read _ -> true | Board_list | Board_compose -> false) ->
           (match board_successor state with
            | None -> report_action state "info" "This post has no recorded successor"
            | Some (origin, successor) ->
                state.followed_from <- Some (Board, Some origin);
                open_board_post_id state ~mailbox:async_messages ~focus:Right_pane successor)
       | Some "b"
         when state.view = Planning && state.planning_mode = Planning_list
              && not (Masc_tui_overview_tasks.is_focused state.task_focus)
              && not state.composer_focused
              && not (modal_owns_keys state) && not state.palette_open
              && not state.answering_open && not state.link_modal_open
              && Option.is_none (text_input_target state ~compact_viewport) ->
           open_detail_reading state
             (Masc_tui_render_work.planning_summary_reading ~cols:terminal_columns state)
       | Some "v"
         when not state.composer_focused
              && not (modal_owns_keys state) && not state.palette_open
              && not state.answering_open && not state.link_modal_open
              && Option.is_none (text_input_target state ~compact_viewport)
              && ((state.view=Overview && not state.keeper_navigation_open)
                  || (state.view=Repositories && Option.is_none state.workspace_activity_repo)
                  || (state.view=Config && state.config_pane=Config_models)
                  || (state.view=Memory && Option.is_none state.memory_facts_keeper)) ->
           let reading = if state.view=Overview then
               Some (Masc_tui_render.operator_actions_reading state)
             else if state.view=Repositories then
               Masc_tui_render_repositories.selected_repository_reading state
             else if state.view=Memory then
               Some (Masc_tui_render_memory.memory_overview_reading ~cols:terminal_columns state)
             else Masc_tui_render_config.selected_model_reading state in
           (match reading with
            | Some reading -> open_detail_reading state reading
            | None -> report_action state "info" "No selected reading is available")
       | Some k when state.keeper_deletions_open ->
           (match k with
            | "esc" | "D" -> state.keeper_deletions_open <- false
            | "r" -> Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_deletions state ~mailbox:async_messages ()
            | "j" | "down" | "k" | "up" ->
              let count = match state.keeper_deletions with
                | Some (Ok inventory) -> List.length inventory.operations | Some (Error _) | None -> 0 in
              let delta = if k = "j" || k = "down" then 1 else -1 in
              state.keeper_deletions_cursor <- max 0 (min (count - 1) (state.keeper_deletions_cursor + delta));
              state.keeper_deletions_scroll <- 0
            | "J" | "K" | "pageup" | "pagedown" | "wheel-up" | "wheel-down" ->
              let count, height = Masc_tui_render.keeper_deletions_viewport state in
              let delta = match k with "J" | "wheel-down" -> 1 | "K" | "wheel-up" -> -1
                | "pagedown" -> height | _ -> -height in
              state.keeper_deletions_scroll <- Masc_tui_scroll.normalize ~count ~height
                (state.keeper_deletions_scroll + delta)
            | "t" ->
              (match state.keeper_deletions with
               | Some (Ok inventory) ->
                 (match List.nth_opt inventory.operations state.keeper_deletions_cursor with
                  | Some row when row.can_retry && Option.is_none state.keeper_deletions_retry_receipt ->
                      Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_deletions state ~mailbox:async_messages ~retry:row ()
                  | _ -> ())
               | Some (Error _) | None -> ())
            | _ -> ())
       | Some k when Option.is_some state.client_detail ->
           if k = "esc" then (
             state.client_detail <- None;
             state.client_detail_scroll <- 0)
           else (
             let page = max 1 (surface_page_rows state - 1) in
             let delta = match k with
               | "j" | "down" -> 1 | "k" | "up" -> -1
               | "pagedown" -> page | "pageup" -> -page | _ -> 0 in
             match k with
             | "g" | "home" -> state.client_detail_scroll <- 0
             | "G" | "end" -> state.client_detail_scroll <- max_int
             | _ -> state.client_detail_scroll <-
                 Masc_tui_scroll.step_uncounted ~delta state.client_detail_scroll)
       | Some ("\r" | "\n" | "enter")
         when state.view = Clients && not (modal_owns_keys state)
              && not state.palette_open && not state.answering_open
              && not state.link_modal_open
              && Option.is_none (text_input_target state ~compact_viewport) ->
           (match state.clients_surface with
            | None -> ()
            | Some snapshot ->
                state.client_detail <- List.nth_opt snapshot.Masc.Tui_decode.cls_clients state.clients_surface_cursor;
                state.client_detail_scroll <- 0)
       | Some k when state.link_modal_open ->
           let close () =
             state.link_modal_open <- false;
             state.link_modal_scroll <- 0
           in
           (match k with
            | "esc" | "q" | "Q" -> close ()
            (* Same door the footer stamps on this row; read-only over a
               reader modal. *)
            | "?" ->
                state.help_open <- true;
                state.help_scroll <- 0
            | "j" | "down" ->
                state.link_modal_scroll <-
                  Masc_tui_types.scroll_down_from state.link_modal_scroll ~by:1
            | "k" | "up" ->
                state.link_modal_scroll <- max 0 (state.link_modal_scroll - 1)
            | "d" | "pagedown" ->
                let _, height = Masc_tui_render.link_modal_viewport state in
                state.link_modal_scroll <-
                  Masc_tui_types.scroll_down_from state.link_modal_scroll
                    ~by:height
            | "u" | "pageup" ->
                let _, height = Masc_tui_render.link_modal_viewport state in
                state.link_modal_scroll <- max 0 (state.link_modal_scroll - height)
            | "g" | "home" ->
                state.link_modal_scroll <- 0
            | "G" | "end" ->
                state.link_modal_scroll <-
                  Masc_tui_types.clamped_scroll_end
            | "n" | "right" | "\t" ->
                let count = List.length state.link_modal_links in
                if count > 1 then begin
                  let next_idx = (state.link_modal_cursor + 1) mod count in
                  state.link_modal_cursor <- next_idx;
                  state.link_modal_url <- List.nth_opt state.link_modal_links next_idx;
                  state.link_modal_scroll <- 0
                end
            | "p" | "left" ->
                let count = List.length state.link_modal_links in
                if count > 1 then begin
                  let prev_idx = (state.link_modal_cursor - 1 + count) mod count in
                  state.link_modal_cursor <- prev_idx;
                  state.link_modal_url <- List.nth_opt state.link_modal_links prev_idx;
                  state.link_modal_scroll <- 0
                end
            | "o" | "O" | "\r" | "\n" | "enter" ->
                (match state.link_modal_url with
                 | Some url -> (
                     match Masc_tui_browser.open_url url with
                     | Ok opener ->
                         report_action state "system" (Printf.sprintf "Opened in browser (%s): %s" opener url)
                     | Error err ->
                         report_action state "system" (Printf.sprintf "Could not open browser: %s" err))
                 | None -> ())
            | "y" | "Y" ->
                (match state.link_modal_url with
                 | Some url ->
                     let outcome = copy_reference render_schedule url in
                     report_action state "system"
                       (if state.ui_language = Lang_ko then
                          "URL을 " ^ Masc_tui_clipboard.copy_outcome_text_korean outcome ^ ": " ^ url
                        else
                          "URL " ^ Masc_tui_clipboard.copy_outcome_text outcome ^ ": " ^ url)
                 | None -> ())
            | "r" | "R" ->
                (match state.link_modal_url with
                 | Some url ->
                     let preview = Masc_tui_link_preview.get_preview url in
                     Option.iter retry_image_mosaic preview.image_url
                 | None -> ())
            | "v" | "V" ->
                (match state.link_modal_url with
                 | Some url ->
                     let p = Masc_tui_link_preview.get_preview url in
                     let notice = Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:state.msg_target_keeper_name in
                     let img_url =
                       match p.image_url with Some i -> i | None -> url
                     in
                     let title =
                       match p.title with Some t -> "  " ^ t | None -> "  " ^ url
                     in
                     let caption =
                       (match p.description with Some d -> [ "  " ^ d ] | None -> [])
                       @ [ "  " ^ Masc_tui_link_preview.site_label p ^ " \xc2\xb7 " ^ url ]
                     in
                     launch_image_render state ~mailbox:async_messages ~notice ~title
                       ~caption ~page_url:url img_url
                 | None -> ())
            | _ -> ())
       (* The Git-changes overlay is a modal like the agenda sheet: while
          it is open it owns every key, answering its own and swallowing
          the rest, so a surface binding under it -- a scroll, a refresh,
          a destructive letter -- cannot act on the wrong pane. Its arms
          used to live below beside their unguarded twins, and every new
          surface key had to remember to stand aside for it; the guard
          now lives here once, the way [modal_owns_keys] names it. *)
       | Some k when state.repository_changes_open ->
           (match k with
            | ("shift-left" | "shift-right") as key
              when Option.is_some state.repository_changes_diff_path ->
              let direction = if String.equal key "shift-left" then -1 else 1 in
              state.repository_changes_diff_hscroll <-
                max 0 (min (max 0 (state.repository_changes_diff_max_width - 1))
                  (state.repository_changes_diff_hscroll + direction))

            | "esc" ->
              if Option.is_some state.repository_changes_diff_path then
                close_repository_changes_diff state
              else begin
                let return_chat = state.repository_changes_return_chat in
                close_repository_changes state;
                if return_chat then begin
                  state.view <- Keepers Keeper_message
                end
              end

            | "left" ->
              if Option.is_some state.repository_changes_diff_path then
                close_repository_changes_diff state
              else begin
                let return_chat = state.repository_changes_return_chat in
                close_repository_changes state;
                if return_chat then begin
                  state.view <- Keepers Keeper_message
                end
              end

            | ("j" | "down" | "wheel-down") ->
              (match state.repository_changes_diff_path with
               | Some _ ->
                   state.repository_changes_diff_scroll <-
                     Masc_tui_types.scroll_down_from state.repository_changes_diff_scroll ~by:1
               | None -> move_list state Masc_tui_scroll.Line_down)

            | ("k" | "up" | "wheel-up") ->
              (match state.repository_changes_diff_path with
               | Some _ ->
                   state.repository_changes_diff_scroll <-
                     max 0 (state.repository_changes_diff_scroll - 1)
               | None -> move_list state Masc_tui_scroll.Line_up)

            | ("\r" | "\n" | "enter" | "right") -> (
              match state.repository_changes_diff_path with
              | Some _ -> ()
              | None -> (
                  match state.repository_changes, state.repository_changes_scope with
                  | Some snapshot, Some scope -> (
                      match
                        List.nth_opt snapshot.Masc.Tui_decode.rcs_changes
                          state.repository_changes_cursor
                      with
                      | None -> ()
                      | Some change ->
                          open_repository_change_diff state
                            ~mailbox:async_messages ~scope change)
                  | _ -> ()))

            | "g" | "G" ->
              let path_opt =
                match state.repository_changes_diff_path with
                | Some path -> Some path
                | None -> (
                    match state.repository_changes with
                    | Some snapshot ->
                        Option.map
                          (fun (c : Tui_decode.repository_change) -> c.rc_path)
                          (List.nth_opt snapshot.Masc.Tui_decode.rcs_changes
                             state.repository_changes_cursor)
                    | None -> None)
              in
              let change_ctx =
                Masc_tui_render_prim.resolve_change_context state ~path_opt
              in
              if Option.is_some change_ctx.Masc_tui_render_prim.ctx_goal_id
                 && not (repository_change_context_visible state) then
                report_action state "error" "Wait for the related record or resize before opening its Goal"
              else begin
              goto_surface state ~mailbox:async_messages Planning;
              state.planning_mode <- Planning_list;
              (match change_ctx.Masc_tui_render_prim.ctx_goal_id with
               | Some gid ->
                   (match state.planning with
                    | Some snap ->
                        (* The cursor indexes the rows the pane draws, which
                           [clamp_planning_cursor] also bounds by that list. The
                           raw goal list is in the order the server sent; the
                           filter hides goals and the sort reorders them, so an
                           index found in it lands on a different row than the
                           goal it was found for. *)
                        let rec find_idx i = function
                          | [] -> ()
                          | (g : planning_goal) :: rest ->
                              if String.equal g.pg_id gid then
                                state.planning_cursor <- i
                              else find_idx (i + 1) rest
                        in
                        find_idx 0
                          (planning_visible_goals ~filter:state.planning_filter
                             ~sort:state.planning_sort snap.pl_goals)
                    | None -> ());
                   clamp_planning_cursor state
               | None ->
                   state.planning_cursor <- 0)
              end

            | "d" -> (
              match state.repository_changes_diff_path with
              | Some _ -> ()
              | None -> (
                  match state.repository_changes, state.repository_changes_scope with
                  | Some snapshot, Some scope -> (
                      match
                        List.nth_opt snapshot.Masc.Tui_decode.rcs_changes
                          state.repository_changes_cursor
                      with
                      | None -> ()
                      | Some change ->
                          open_repository_change_diff state
                            ~mailbox:async_messages ~scope change)
                  | _ -> ()))

            | "t" | "T" ->
              let path_opt =
                match state.repository_changes_diff_path with
                | Some path -> Some path
                | None -> (
                    match state.repository_changes with
                    | Some snapshot ->
                        Option.map
                          (fun (c : Tui_decode.repository_change) -> c.rc_path)
                          (List.nth_opt snapshot.Masc.Tui_decode.rcs_changes
                             state.repository_changes_cursor)
                    | None -> None)
              in
              let change_ctx =
                Masc_tui_render_prim.resolve_change_context state ~path_opt
              in
              if Option.is_some change_ctx.Masc_tui_render_prim.ctx_task_id
                 && not (repository_change_context_visible state) then
                report_action state "error" "Wait for the related record or resize before opening its Task"
              else begin
              goto_surface state ~mailbox:async_messages Planning;
              state.planning_mode <- Planning_list;
              (match change_ctx.Masc_tui_render_prim.ctx_task_id with
               | Some tid ->
                   state.task_detail_id <- Some tid;
                   reset_task_detail_scroll state;
                   prepare_task_history_for_open state ~task_id:tid;
                   Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size state ~mailbox:async_messages tid;
                   state.task_focus <-
                     Masc_tui_overview_tasks.land_on state.tasks ~task_id:tid
               | None ->
                   state.task_detail_id <- None;
                   reset_task_detail_scroll state;
                   state.task_focus <-
                     Masc_tui_overview_tasks.focus_list state.tasks)
              end

            | "v" -> (
              match state.repository_changes, state.repository_changes_scope with
              | Some snapshot, Some scope -> (
                  let change_opt =
                    match state.repository_changes_diff_path with
                    | Some diff_path ->
                        List.find_opt
                          (fun (c : Tui_decode.repository_change) ->
                            String.equal c.rc_path diff_path)
                          snapshot.Masc.Tui_decode.rcs_changes
                    | None ->
                        List.nth_opt snapshot.Masc.Tui_decode.rcs_changes
                          state.repository_changes_cursor
                  in
                  match change_opt with
                  | None -> report_action state "error" "no change under the cursor"
                  | Some change ->
                      open_repository_change_in_code state
                        ~mailbox:async_messages ~scope change)
              | _ -> ())

            | "p" | "P" ->
              let path_opt =
                match state.repository_changes_diff_path with
                | Some path -> Some path
                | None -> (
                    match state.repository_changes with
                    | Some snapshot ->
                        Option.map
                          (fun (c : Tui_decode.repository_change) -> c.rc_path)
                          (List.nth_opt snapshot.Masc.Tui_decode.rcs_changes
                             state.repository_changes_cursor)
                    | None -> None)
              in
              let change_ctx =
                Masc_tui_render_prim.resolve_change_context state ~path_opt
              in
              (match change_ctx.Masc_tui_render_prim.ctx_pr with
               | None ->
                   report_action state "git"
                     "no PR to open: this change names no github.com/…/pull/N link or PR-N token"
               | Some _ when not (repository_change_context_visible state) ->
                   report_action state "error" "Wait for the related record or resize before opening its PR"
               | Some reference -> (
                   let number = Masc_tui_pr_ref.number reference in
                   match change_ctx.Masc_tui_render_prim.ctx_pr_slug with
                   | None ->
                       report_action state "error"
                         (Printf.sprintf
                            "PR-%d: the scope has no GitHub remote to open it in"
                            number)
                   | Some slug -> (
                       match
                         Masc_tui_browser.open_url
                           (Masc_tui_pr_ref.pull_url ~slug ~number)
                       with
                       | Ok opener ->
                           report_action state "git"
                             (Printf.sprintf "opened %s#%d with %s" slug number opener)
                       | Error _ ->
                           (* No opener on this machine; gh may still have one
                              configured. Named repository, waited on, reported
                              after the fact: run in the TUI's cwd and detached,
                              it opened the wrong checkout's PR and the pane
                              said "opening" whether or not it did. *)
                           let status, _stdout, stderr =
                             Process_eio.run_argv_with_status_split
                               ~timeout_sec:gh_open_timeout_sec
                               [ "gh"; "pr"; "view"; string_of_int number; "--web"
                               ; "-R"; slug ]
                           in
                           (match status with
                            | Unix.WEXITED 0 ->
                                report_action state "git"
                                  (Printf.sprintf "opened %s#%d with gh" slug number)
                            | Unix.WEXITED code ->
                                report_action state "error"
                                  (Printf.sprintf "gh pr view %d -R %s exited %d: %s"
                                     number slug code (String.trim stderr))
                            | Unix.WSIGNALED signal | Unix.WSTOPPED signal ->
                                report_action state "error"
                                  (Printf.sprintf "gh pr view %d -R %s stopped by signal %d"
                                     number slug signal)))))

            | ("home" | "end") as key ->
              (match state.repository_changes_diff_path with
               | Some _ ->
                   state.repository_changes_diff_scroll <-
                     if String.equal key "home" then 0 else clamped_scroll_end
               | None ->
                   move_list state
                     (if String.equal key "home" then Masc_tui_scroll.To_top else Masc_tui_scroll.To_end))

            | ("pageup" | "pagedown") as page_key ->
              (* A surface page at a time, as the shared page arm moved the
                 overlay before its keys were gathered here. *)
              let direction = if String.equal page_key "pagedown" then 1 else -1 in
              (match state.repository_changes_diff_path with
               | Some path ->
                   let terminal_rows, cols = get_terminal_size () in
                   let page =
                     Masc_tui_render_prim.repository_changes_diff_page_rows state
                       ~terminal_rows ~cols ~path
                   in
                   state.repository_changes_diff_scroll <-
                     Masc_tui_scroll.step_uncounted ~delta:(direction * page) state.repository_changes_diff_scroll
               | None ->
                   move_list state
                     (if direction > 0 then Masc_tui_scroll.Page_down else Masc_tui_scroll.Page_up))
            | "r" | "R" ->
              refresh_shared_sources ();
              refresh_repository_changes state ~mailbox:async_messages;
              add_event state "system" "Manual refresh"
            | _ -> ())
       (* The palette is the same kind of modal, but typed: printable keys
          build the query, arrows move the cursor, Enter runs the highlighted
          jump through the exact goto/chat paths the bound keys use. *)
       | Some k
         when text_input_target state ~compact_viewport = Some Text_palette ->
           let close () =
             close_code_finder state
           in
           let typed_question =
             match state.palette_mode with
             | Palette_jump -> Masc_tui_palette.palette_typed_question state.palette_query
             | Palette_choice _ | Palette_files _ | Palette_locations _ | Palette_branches _
             | Palette_worktrees _ | Palette_search _ -> None
           in
           let move_palette by =
             state.code_finder_file <- Masc_tui_fetched.clear state.code_finder_file;
             let last = max 0 (List.length (Masc_tui_palette.palette_matches state) - 1) in
             let current = max 0 (min state.palette_cursor last) in
             state.palette_cursor <- max 0 (min last (current + by))
           in
           (match k with
            | "esc" -> close ()
            | "\r" when (match state.palette_mode with
                | Palette_search _ -> true
                | Palette_jump | Palette_choice _ | Palette_files _ | Palette_locations _ | Palette_branches _
                | Palette_worktrees _ -> false) ->
                (match Masc_tui_palette.search_enter state with
                 | Masc_tui_palette.Enter_searches ->
                     Masc_tui_code_requests.launch_search state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                       ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)
                 | Masc_tui_palette.Enter_opens found ->
                     match Code_results.choose_search_match state found with
                     | Code_results.No_followup | Code_results.Choose_location -> ()
                     | Code_results.Reveal_cursor ->
                         state.code_file_scroll <- Masc_tui_scroll.ensure_visible
                           ~cursor:state.code_file_cursor
                           ~height:(Masc_tui_render_code.code_pane_content_height state)
                           state.code_file_scroll
                     | Code_results.Read_location_file (owner, request) ->
                         Masc_tui_code_requests.launch_navigation_read state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                           ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) owner request)
            | "\r" when (match state.palette_mode with
                | Palette_locations _ -> true
                | Palette_jump | Palette_choice _ | Palette_files _ | Palette_branches _
                | Palette_worktrees _ | Palette_search _ -> false) ->
                (match Masc_tui_palette.selected_location state with
                 | None -> ()
                 | Some (offer, location) ->
                     match Code_results.choose_lsp_location state offer location with
                     | Code_results.No_followup | Code_results.Choose_location -> ()
                     | Code_results.Reveal_cursor ->
                         state.code_file_scroll <- Masc_tui_scroll.ensure_visible
                           ~cursor:state.code_file_cursor
                           ~height:(Masc_tui_render_code.code_pane_content_height state)
                           state.code_file_scroll
                     | Code_results.Read_location_file (owner, request) ->
                         Masc_tui_code_requests.launch_navigation_read state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                           ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) owner request)
            | "\r" when (match state.palette_mode with
                | Palette_branches _ | Palette_worktrees _ -> true
                | Palette_files _
                | Palette_jump | Palette_choice _ | Palette_locations _ | Palette_search _ -> false) ->
                (* The lists are read-only: a branch or a worktree offers
                   nothing to open, so Enter closes it the way Esc does. *)
                close ()
            | "\r" when (match state.palette_mode with
                | Palette_files _ -> true
                | Palette_jump | Palette_choice _ | Palette_locations _ | Palette_branches _
                | Palette_worktrees _ | Palette_search _ -> false) ->
                Option.iter (fun path ->
                    Masc_tui_code_requests.open_found_file state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                      ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~path)
                  (Masc_tui_palette.selected_file state)
            | "\r" when Option.is_some typed_question ->
                (match typed_question with
                 | None -> ()
                 | Some (question, None) ->
                  (* Bare "def " or "hover ": run the highlighted candidate
                     entry -- the cursor line's names ride the palette list,
                     so Enter alone picks the one in view. *)
                  let matches = Masc_tui_palette.palette_matches state in
                  let chosen =
                    List.nth_opt matches
                      (max 0
                         (min state.palette_cursor
                            (List.length matches - 1)))
                  in
                  close ();
                  (match chosen with
                  | Some (_, Masc_tui_palette.Palette_lsp (question, symbol))
                    ->
                      Masc_tui_code_requests.start_lsp_question state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~report:(report_action state) ~question ~symbol
                  | Some
                      ( _,
                        ( Masc_tui_palette.Palette_browser_lane
                        | Masc_tui_palette.Palette_hide_browser_lane
                        | Masc_tui_palette.Palette_connectors
                        | Masc_tui_palette.Palette_collab | Masc_tui_palette.Palette_msx
                        | Masc_tui_palette.Palette_dos
                        | Masc_tui_palette.Palette_lane_addons
                        | Masc_tui_palette.Palette_addon_results _
                        | Masc_tui_palette.Palette_lane_history _
                        | Masc_tui_palette.Palette_goto _
                        | Masc_tui_palette.Palette_usage_scope _
                        | Masc_tui_palette.Palette_config _
                        | Masc_tui_palette.Palette_ui_language _
                        | Masc_tui_palette.Palette_gate_mode _
                        | Masc_tui_palette.Palette_chat _
                        | Masc_tui_palette.Palette_task _
                        | Masc_tui_palette.Palette_task_creation _
                        | Masc_tui_palette.Palette_board_hearth _
                        | Masc_tui_palette.Palette_board_post _
                        | Masc_tui_palette.Palette_code_file _
                        | Masc_tui_palette.Palette_code_location _
                        | Masc_tui_palette.Palette_code_branch _
                        | Masc_tui_palette.Palette_code_worktree _
                        | Masc_tui_palette.Palette_code_search_match _ ) )
                  | None ->
                      report_action state "error"
                        (question ^ " needs a symbol: :" ^ question
                       ^ " <name>"))
                 | Some (question, Some symbol) ->
                  close ();
                  if state.view <> Code || Option.is_none (Masc_tui_fetched.current_key state.code_file)
                  then
                    report_action state "error"
                      "hover, def and refs ask about the file open on the \
                       Code surface"
                  else
                    Masc_tui_code_requests.start_lsp_question state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~report:(report_action state)
                      ~question ~symbol)
            | "\r" when Masc_tui_palette.command_enter_has_nothing state ->
                (* No command matches the typed text, so there is nothing to
                   run. The list already says so. The palette stays open with
                   its text so a typo can be edited; closing here looked like a
                   command had run. *)
                ()
            | "\r" ->
                let matches = Masc_tui_palette.palette_matches state in
                let chosen =
                  List.nth_opt matches
                    (max 0 (min state.palette_cursor (List.length matches - 1)))
                in
                close ();
                (match chosen, state.lane_addons with
                 | Some _, Some view ->
                     state.lane_addons_cached <- view;
                     state.lane_addons <- None
                 | Some _, None | None, (Some _ | None) -> ());
                (match chosen with
                 | Some (_, Masc_tui_palette.Palette_hide_browser_lane) ->
                     leave_browser_lane state ~mailbox:async_messages
                 | Some (_, Masc_tui_palette.Palette_collab) ->
                     Masc_tui_collab_queue.Collab_play.open_collab state ~mailbox:async_messages
                 | Some (_, Masc_tui_palette.Palette_msx) ->
                     open_msx_screen state ~mailbox:async_messages
                 | Some (_, Masc_tui_palette.Palette_dos) ->
                     open_dos_screen state ~mailbox:async_messages
                 | Some (_, Masc_tui_palette.Palette_lane_addons) ->
                     Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox:async_messages
                       Masc_tui_lane_addons.Inspect
                 | Some (_, Masc_tui_palette.Palette_addon_results declaration_id) ->
                     open_installation_results state ~mailbox:async_messages declaration_id
                 | Some (_, Masc_tui_palette.Palette_lane_history lane) ->
                     goto_surface state ~mailbox:async_messages Lanes;
                     open_lane_run_list state ~mailbox:async_messages lane
                 | Some (_, Masc_tui_palette.Palette_browser_lane) ->
                     Masc_tui_surface_requests.Lane_browser_requests.open_browser_lane state ~mailbox:async_messages
                 | Some (_, Masc_tui_palette.Palette_connectors) ->
                     (* Close the lane first: Connectors renders the lane
                        whenever it is on screen, so asking for the transport
                        list has to say the lane is not. [hide_browser_lane]
                        puts the view back where the lane was opened from,
                        which [goto_surface] then replaces. *)
                     hide_browser_lane state;
                     goto_surface state ~mailbox:async_messages
                       Masc_tui_types.Connectors
                 | Some (_, Masc_tui_palette.Palette_goto destination) ->
                     goto_surface state ~mailbox:async_messages destination
                 | Some (_, Masc_tui_palette.Palette_gate_mode (lane, mode)) ->
                     Masc_tui_work_requests.Approval_gate_requests.launch_gate_mode_set state ~mailbox:async_messages ~lane
                       ~mode:(Masc.Keeper_gate_mode.to_string mode)
                 | Some (_, Masc_tui_palette.Palette_usage_scope scope_id) ->
                     state.usage_scope_id <- scope_id;
                     state.usage_telemetry_open <- false;
                     (* Keepers and Calls read the whole workspace, so an account
                        chosen there lands on the section it narrows. *)
                     (match state.usage_section with
                      | Usage_keepers | Usage_calls -> state.usage_section <- Usage_plan
                      | Usage_plan | Usage_trend -> ());
                     reset_metrics_scroll state;
                     goto_surface state ~mailbox:async_messages Metrics
                 | Some (_, Masc_tui_palette.Palette_config pane) ->
                     state.config_pane <- pane;
                     if pane = Config_runtime then state.runtime_config_status_open <- false;
                     state.config_scroll <- 0;
                     state.runtime_params_cursor <- 0;
                     state.runtime_param_edit <- None;
                     state.runtime_params_notice <- None;
                     goto_surface state ~mailbox:async_messages Config
                 | Some (_, Masc_tui_palette.Palette_ui_language lang) ->
                     apply_ui_language state ~mailbox:async_messages lang
                 | Some (_, Masc_tui_palette.Palette_chat keeper_name) ->
                     Masc_tui_chat_dispatch.Chat_journals.enter_keeper_chat ~return_to:Keeper_chat_return_list state
                       ~keeper_name ~drain_queue:(fun () ->
                         Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox:async_messages)
                       ~load_history:(fun keeper_name ->
                         launch_keeper_history_load state ~mailbox:async_messages ~keeper_name)
                 | Some (_, Masc_tui_palette.Palette_task_creation original) ->
                     let keeper = (Masc_tui_task_dispatch.intent original.tdr_dispatch).keeper in
                     if state.msg_target_keeper_name = Some keeper
                        && List.exists ((==) original) (task_creation_inspectable state ~keeper)
                     then begin
                       Masc_tui_chat_dispatch.Task_dispatch.close_task_inspection_reader state;
                       if select_task_creation_inspection state original then
                         Masc_tui_chat_dispatch.Task_dispatch.launch_task_creation_read state ~mailbox:async_messages
                     end else
                       report_action state "error"
                         "Original Task creation is unavailable for this Keeper and confirmed workspace"
                 | Some (_, Masc_tui_palette.Palette_task task_id) ->
                     (* Open the exact Task in Work, as the task list does. *)
                     goto_surface state ~mailbox:async_messages Planning;
                     state.planning_mode <- Planning_list;
                     state.task_detail_id <- Some task_id;
                     reset_task_detail_scroll state;
                     prepare_task_history_for_open state ~task_id;
                     Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size state ~mailbox:async_messages
                       task_id;
                     state.task_focus <-
                       Masc_tui_overview_tasks.land_on state.tasks ~task_id
                 | Some (_, Masc_tui_palette.Palette_board_hearth hearth) ->
                     state.board_hearth <- hearth;
                     state.board_cursor <- 0;
                     state.board_mode <- Board_list;
                     goto_surface state ~mailbox:async_messages Board;
                     start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
                       ~intent:Operator_key ~refresh_inflight:http_refresh_inflight
                       ~scoped_refresh_inflight:http_scoped_refresh_inflight
                       ~scoped_refresh_followup ~mailbox:async_messages
                 | Some (_, Masc_tui_palette.Palette_board_post post_id) ->
                     goto_surface state ~mailbox:async_messages Board;
                     let rec find i = function
                       | [] -> None
                       | (p : Masc_tui_types.board_post) :: rest ->
                           if String.equal p.bp_id post_id then Some (i, p)
                           else find (i + 1) rest
                     in
                     (match find 0 (board_posts state) with
                      | Some (index, post) ->
                          state.board_cursor <- index;
                          open_board_post state ~mailbox:async_messages
                            ~focus:Right_pane post
                      | None -> ())
                 | Some (_, Masc_tui_palette.Palette_lsp (question, symbol))
                   ->
                     Masc_tui_code_requests.start_lsp_question state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~report:(report_action state)
                       ~question ~symbol
                 | Some (_, (Masc_tui_palette.Palette_code_file _
                     | Masc_tui_palette.Palette_code_location _
                     | Masc_tui_palette.Palette_code_branch _
                     | Masc_tui_palette.Palette_code_worktree _
                     | Masc_tui_palette.Palette_code_search_match _)) | None -> ())
            | "down" | "\014" -> move_palette 1
            | "up" | "\016" -> move_palette (-1)
            | "home" -> move_palette (-state.palette_cursor)
            | "end" -> move_palette (List.length (Masc_tui_palette.palette_matches state))
            | "\021" ->
                state.code_finder_file <- Masc_tui_fetched.clear state.code_finder_file;
                state.palette_query <- ""; state.palette_cursor <- 0
            | "\127" | "\b" ->
                state.code_finder_file <- Masc_tui_fetched.clear state.code_finder_file;
                state.palette_query <-
                  Masc_tui_message_layout.drop_last_utf8_scalar
                    state.palette_query;
                state.palette_cursor <- 0
            | s
              when (String.length s = 1 && Char.code s.[0] >= 32)
                   || (String.length s > 1 && Char.code s.[0] >= 0x80) ->
                state.code_finder_file <- Masc_tui_fetched.clear state.code_finder_file;
                state.palette_query <- state.palette_query ^ s;
                state.palette_cursor <- 0
            | _ -> ())
       (* Row search: typing moves the surface's row cursor live to the
          first match from the top; Enter keeps the query for n/N, Esc keeps
          nothing. The list itself never narrows -- see [search] in types. *)
       | Some k when text_input_target state ~compact_viewport = Some Text_row_search ->
           handle_row_search_key k
       (* The app form takes every printable key while it is open, the way
          the filter does. Three fields in order, enter to advance and to
          send on the last, esc to abandon -- and abandoning clears the
          secret rather than leaving it in the process. *)
       | Some k
         when text_input_target state ~compact_viewport
              = Some Text_identity_app_form ->
           Masc_tui_identity_input.app_form_key state ~save:(fun ~form -> Masc_tui_identity_requests.launch_app_save state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state async_messages) ~fork:(Masc_tui_transport.Workspace_admission.fork_job state ~mailbox:async_messages) ~form) k
       | Some k
         when (state.view = Runtime || state.view = Lanes)
              && (match state.runtime_lane_pick with
                  | None -> false
                  | Some (_, list) ->
                      Option.is_some
                        (Masc_tui_pick_list.action_of_key
                           ~close_keys:Masc_tui_chat_dispatch.Runtime_picker.runtime_picker_close_keys list k)
                      || Option.is_some list.Masc_tui_pick_list.query) ->
           (* The picker is open: arrows or j/k step, PgUp/PgDn page, Home/End
              jump, [/] types a filter over the drawn rows, Enter appends, and
              e or Esc drop the filter and then close. While the filter is
              being typed it holds every key, so a letter never reaches the
              surface under it. The Runtime surface opens it for a
              conversation lane or a lane being created, the Lanes surface for
              a standalone lane's walk order. *)
           (match state.runtime_lane_pick with
            | None -> ()
            | Some (pick, list) ->
            match
              Masc_tui_pick_list.action_of_key
                ~close_keys:Masc_tui_chat_dispatch.Runtime_picker.runtime_picker_close_keys list k
            with
            | None -> ()
            | Some action ->
                let terminal_rows, cols = get_terminal_size () in
                let page = Masc_tui_types.runtime_exact_picker_page state ~terminal_rows ~cols in
                let already, _providers, catalog =
                  Masc_tui_types.runtime_picker_rows state pick
                in
                (match
                   (match action, list.Masc_tui_pick_list.query, pick with
                    | Masc_tui_pick_list.Back, Some "",
                      (Masc_tui_types.Pick_exact_lane _ | Masc_tui_types.Pick_exact_lane_replacement _) ->
                        Masc_tui_pick_list.Dismissed
                    | ( ( Masc_tui_pick_list.Move _ | Masc_tui_pick_list.Open_query
                        | Masc_tui_pick_list.Type _ | Masc_tui_pick_list.Erase
                        | Masc_tui_pick_list.Back | Masc_tui_pick_list.Choose ),
                        _,
                        ( Masc_tui_types.Pick_route_default | Masc_tui_types.Pick_conversation_lane _
                        | Masc_tui_types.Pick_exact_lane _
                        | Masc_tui_types.Pick_exact_lane_replacement _
                        | Masc_tui_types.Pick_new_lane _ | Masc_tui_types.Pick_media_failover ) ) -> Masc_tui_pick_list.apply
                     ~page
                     ~label:(Masc_tui_types.runtime_picker_label_for pick) catalog
                     list action)
                 with
                 | Masc_tui_pick_list.Stay list ->
                     state.runtime_lane_pick <- Some (pick, list)
                 | Masc_tui_pick_list.Chosen (Masc_tui_types.Runtime_choice runtime) ->
                     Masc_tui_chat_dispatch.Runtime_picker.launch_runtime_lane_pick state ~mailbox:async_messages
                       ~pick ~runtime ~existing:already
                 | Masc_tui_pick_list.Chosen (Masc_tui_types.Lane_choice lane) ->
                     (match pick with
                      | Masc_tui_types.Pick_route_default ->
                          Masc_tui_chat_dispatch.Runtime_picker.launch_runtime_default_route state ~mailbox:async_messages
                            lane.Masc.Tui_decode.rrl_id
                      | Masc_tui_types.Pick_conversation_lane _
                      | Masc_tui_types.Pick_exact_lane _
                      | Masc_tui_types.Pick_exact_lane_replacement _
                      | Masc_tui_types.Pick_new_lane _
                      | Masc_tui_types.Pick_media_failover -> ())
                 | Masc_tui_pick_list.Dismissed ->
                     state.runtime_lane_pick <- None))
       | Some k when state.view = Tools && Option.is_some state.tools_skill_source_picker ->
           if not compact_viewport then Masc_tui_editor_forms.Skill_prompt_forms.handle_skill_source_key state ~mailbox:async_messages ~terminal_session ~page:(Masc_tui_render_tools.skill_source_picker_page state ~terminal_rows:(fst (get_terminal_size ()))) k
           else if String.equal k "esc" then state.tools_skill_source_picker <- None
       | Some k
         when state.view = Tools
              && Option.is_some (tools_volume_gc_parent_scroll state.tools_pane)
              && not (List.mem k
                [ "?"; ":"; "q"; "\t"; "shift-tab"; "p"; "P"; "r"; "R"
                ; "j"; "k"; "up"; "down"; "wheel-up"; "wheel-down"
                ; "pageup"; "pagedown"; "home"; "end" ]) ->
           (* This reading owns its action keys. Skill edits and Keeper
              selection belong to the catalog, not the volume report. *)
           if String.equal k Masc_tui_volume_gc.key then
             Masc_tui_surface_requests.Connector_volume_requests.press_tools_volume_gc state ~mailbox:async_messages
           else if String.equal k "esc" then
             Option.iter (fun catalog_scroll ->
               enter_tools_pane state (Tools_catalog Tools_catalog_list);
               tools_task_user_scroll state catalog_scroll)
               (tools_volume_gc_parent_scroll state.tools_pane)
       | Some k
         when state.view = Keepers Keeper_runtime_pick
              && (Option.is_some (Masc_tui_chat_dispatch.Runtime_picker.keeper_runtime_picker_action state.runtime_pick_list k)
                  || text_input_target state ~compact_viewport
                     = Some Text_keeper_runtime_picker_filter) ->
           (* The Keeper runtime picker: arrows or j/k step, PgUp/PgDn page,
              Home/End jump, [/] types a filter over the drawn lanes and
              runtimes, Enter assigns, and Esc drops the filter and then
              closes. While the filter is typed it holds every key, so [d]
              and the quit key are letters in it. [d] outside a filter is its
              own arm below. *)
           let terminal_rows, _ = get_terminal_size () in
           Masc_tui_chat_dispatch.Runtime_picker.keeper_runtime_pick_key state ~terminal_rows k
       | Some k
         when state.view = Runtime
              && Option.exists (fun parent ->
                   Masc_tui_types.runtime_parent_blocks_listing_key parent k)
                   runtime_parent_before_input ->
           ()
       | Some ("home" | "end" as edge)
         when state.view = Runtime && Option.is_some state.runtime_detail_target ->
           state.runtime_detail_scroll <-
             (if String.equal edge "home" then 0
              else Masc_tui_types.clamped_scroll_end)
       | Some ("home" | "end" | "pageup" | "pagedown" as key)
         when state.view = Runtime
              && (match Masc_tui_types.runtime_parent state with
                  | Some Runtime_media_parent -> true
                  | Some (Runtime_prompt_parent _) | None -> false) ->
           let terminal_rows, cols = get_terminal_size () in
           (match Masc_tui_types.runtime_parent_projection state ~terminal_rows ~cols with
            | None -> ()
            | Some projection ->
                let count = List.length (Masc_tui_types.slot_editor_rows state) in
                if count > 0 then begin
                  let selected = Masc_tui_types.slot_editor_cursor_index state in
                  let next = match key, selected with
                    | "home", _ | "pagedown", None -> 0
                    | "end", _ | "pageup", None -> count - 1
                    | "pageup", Some current -> max 0 (current - projection.rpp_page)
                    | "pagedown", Some current -> min (count - 1) (current + projection.rpp_page)
                    | _, (Some _ | None) -> Option.value selected ~default:0 in
                  Masc_tui_types.select_slot_editor_row state next
                end)
       | Some "h"
         when state.view = Runtime
              && Option.is_none state.runtime_detail_target
              && Option.is_none state.runtime_lane_pick
              && Option.is_none state.slot_editor
              && Option.is_none (Masc_tui_types.runtime_lane_prompt state) ->
           Masc_tui_types.toggle_runtime_dim_refusals state
       | Some "v"
         when state.view = Runtime
              && Option.is_none state.runtime_detail_target
              && Option.is_none state.runtime_lane_pick
              && (match state.slot_editor with
                  | None | Some { se_target = Masc_tui_types.Media_failover_slots; _ } -> true
                  | Some { se_target = Masc_tui_types.Exact_lane_slots _; _ } -> false)
              && Option.is_none (Masc_tui_types.runtime_lane_prompt state) ->
           (* Read above the media editor without closing it or retiring its
              notice. The detail's Esc returns to the same editor selection. *)
           state.runtime_detail_target <- Some Runtime_routes;
           state.runtime_detail_scroll <- 0
       | Some "e" | Some "E"
         when state.view = Runtime
              && state.runtime_mode = Masc_tui_types.Runtime_lanes
              && Option.is_none state.runtime_detail_target ->
           (* Add a failover candidate to the lane under the cursor. The
              catalogue is fetched on open so the list is the server's now. *)
           (* The lane under the row cursor. Rows are lane-by-candidate, so
              two rows can name one lane; either selects it. *)
           (match state.runtime_surface with
            | None -> ()
            | Some snapshot ->
                (match
                   List.nth_opt snapshot.Masc.Tui_decode.rss_candidates
                     state.runtime_cursor
                 with
                 | None -> ()
                 | Some row ->
                     Masc_tui_types.open_runtime_lane_pick state
                       (Masc_tui_types.Pick_conversation_lane
                          row.Masc.Tui_decode.rcr_lane_id);
                     Masc_tui_types.dismiss_runtime_lane_notice state;
                     Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load state ~mailbox:async_messages))
       (* The roster opens the same fresh Config Models editor as Runtime
          detail and Standalone slots; no second form or writer owns it. *)
       | Some "e"
         when state.view = Runtime && state.runtime_mode = Masc_tui_types.Runtime_all
              && Option.is_none state.runtime_detail_target
              && Option.is_none state.runtime_lane_pick ->
           (match state.runtime_surface with
            | None -> ()
            | Some snapshot ->
              (match List.nth_opt snapshot.Masc.Tui_decode.rss_resolved.rrs_runtimes state.runtime_cursor with
               | None -> ()
               | Some runtime ->
                 Masc_tui_types.dismiss_runtime_lane_notice state;
                 Masc_tui_editor_forms.Runtime_config_forms.open_runtime_model_settings state ~mailbox:async_messages runtime.Masc.Tui_decode.ro_id))
       (* The route editor holds the Runtime reading's own keys while it is
          open: [a] adds to the route rather than naming a new lane, and
          x/J/K act on the route's entry under its cursor. *)
       | Some "f"
         when state.view = Runtime
              && state.runtime_mode = Masc_tui_types.Runtime_lanes
              && Option.is_none state.runtime_detail_target
              && Option.is_none state.runtime_lane_pick ->
           (* [\[runtime\].default]: the lane or runtime a keeper with no
              assignment walks. One route, so the picker replaces it. *)
           Masc_tui_types.open_runtime_lane_pick state Masc_tui_types.Pick_route_default;
           Masc_tui_types.dismiss_runtime_lane_notice state;
           Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load state ~mailbox:async_messages
       | Some "m"
         when state.view = Runtime
              && state.runtime_mode = Masc_tui_types.Runtime_lanes
              && Option.is_none state.runtime_detail_target
              && Option.is_none state.runtime_lane_pick ->
           (* [\[runtime\].media_failover]: the vision runtimes, in the order they
              are called. Opened in the same editor an exact lane's slots use --
              both are an ordered list of runtime ids, and neither is a lane. *)
           (match state.slot_editor with
            | Some { se_target = Masc_tui_types.Media_failover_slots; _ } ->
                state.slot_editor <- None
            | Some { se_target = Masc_tui_types.Exact_lane_slots _; _ } | None ->
                Masc_tui_types.open_slot_editor state Masc_tui_types.Media_failover_slots);
           Masc_tui_types.dismiss_runtime_lane_notice state
       | Some "a"
         when state.view = Runtime
              && Option.is_none state.runtime_detail_target
              && Option.is_some state.slot_editor
              && Option.is_none state.runtime_lane_pick ->
           Masc_tui_types.open_runtime_lane_pick state Masc_tui_types.Pick_media_failover;
           Masc_tui_types.dismiss_runtime_lane_notice state;
           Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load state ~mailbox:async_messages
       | Some k
         when state.view = Runtime
              && state.runtime_mode = Masc_tui_types.Runtime_lanes
              && Option.is_none state.runtime_detail_target
              && Option.is_none state.runtime_lane_pick
              && Option.is_none state.slot_editor
              && Option.is_some (Masc_tui_types.runtime_lane_edit_of_key k) ->
           Option.iter
             (Masc_tui_chat_dispatch.Runtime_picker.handle_runtime_lane_edit state ~mailbox:async_messages)
             (Masc_tui_types.runtime_lane_edit_of_key k)
       (* The slot editor takes its keys before the surface does, the way the
          candidate picker does above: j/k walk the declared slots, x drops
          one, J/K move it, and Esc closes. *)
       | Some "r"
         when (state.view = Lanes || state.view = Runtime)
              && (state.view = Lanes || Option.is_none state.runtime_detail_target)
              && (match state.slot_editor with
                  | Some { se_target = Masc_tui_types.Exact_lane_slots _; _ } -> true
                  | Some { se_target = Masc_tui_types.Media_failover_slots; _ } | None -> false)
              && Option.is_none state.runtime_lane_pick ->
           if Masc_tui_types.runtime_lane_write_busy state then
             state.runtime_lane_notice <- Some Masc_tui_types.Lane_write_pending
           else
           (match state.slot_editor, Masc_tui_types.slot_editor_cursor_row state with
            | Some { se_target = Masc_tui_types.Exact_lane_slots lane; _ }, Some row ->
                let group = match row.Masc_tui_types.sr_kind with
                  | Masc_tui_types.Catalog_slot -> Tui_decode.Exact_http_slots
                  | Masc_tui_types.Official_client_slot -> Tui_decode.Exact_cli_slots
                  | Masc_tui_types.Media_route_slot -> Tui_decode.Exact_output_unsupported in
                Masc_tui_types.open_runtime_lane_pick state
                  (Masc_tui_types.Pick_exact_lane_replacement (lane, row.sr_slot, group));
                Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load state ~mailbox:async_messages;
                Masc_tui_types.dismiss_runtime_lane_notice state
            | Some { se_target = Masc_tui_types.Media_failover_slots; _ }, _
            | Some { se_target = Masc_tui_types.Exact_lane_slots _; _ }, None
            | None, _ -> ())
       | Some ("j" | "k" | "up" | "down" | "wheel-up" | "wheel-down" | "x" | "J" | "K" | "1" | "esc")
         when (state.view = Lanes || state.view = Runtime)
              && (state.view = Lanes || Option.is_none state.runtime_detail_target)
              && Option.is_some state.slot_editor
              && Option.is_none state.runtime_lane_pick ->
           (match state.slot_editor, key with
            | None, _ -> ()
            | Some _, Some "esc" -> Masc_tui_types.close_slot_editor state
            | Some _, Some ("j" | "down" | "wheel-down") ->
                Masc_tui_types.navigate_slot_editor state Masc_tui_types.Move_down;
                Masc_tui_types.dismiss_runtime_lane_notice state
            | Some _, Some ("k" | "up" | "wheel-up") ->
                Masc_tui_types.navigate_slot_editor state Masc_tui_types.Move_up;
                Masc_tui_types.dismiss_runtime_lane_notice state
            | Some _, Some k ->
                Option.iter
                  (Masc_tui_chat_dispatch.Runtime_picker.handle_slot_edit state ~mailbox:async_messages)
                  (Masc_tui_types.slot_edit_of_key k)
            | Some _, None -> ())
       | Some (" " | "space") when state.view=Lanes && state.lanes_mode=Lanes_overview
           && Option.is_none state.runtime_lane_pick && Option.is_none state.slot_editor ->
           (match selected_inventory_lane state with
            | Some {Masc.Tui_decode_lane_inventory.selection=Exact lane;_} ->
                open_exact_activity state ~mailbox:async_messages lane
            | Some {selection=Machine machine;_} ->
                open_machine_activity state ~mailbox:async_messages machine
            | Some {selection=Browser _;_} ->
                show_lanes_action_error state
                  (Masc_tui_lane_inventory.browser_switch_line ~ko:(state.ui_language = Lang_ko))
            | None | Some {selection=(Declaration _ | Manual_instance _);_} ->
                show_lanes_action_error state
                  (ui_text state
                     ~ko:"활동을 바꾸려면 정확 출력 Lane 이나 머신 Lane 을 고르세요."
                     ~en:"Select an Exact or machine Lane to change activity."))
       | Some "s"
         when state.view = Lanes
              && Option.is_none state.runtime_lane_pick
              && Option.is_none state.slot_editor ->
           (* Open the slot editor on the lane the overview's cursor or one
              Lane's inventory detail names. Its rows come from the lane
              list, which is already loaded here. *)
           Masc_tui_types.open_lanes_slot_editor state;
           (* [d] resolves an HTTP slot's provider table through the
              catalogue, so the editor reads it as it opens. *)
           if Option.is_some state.slot_editor then
             Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load state ~mailbox:async_messages
       | Some "a"
         when state.view = Lanes
              && (state.lanes_mode = Lanes_overview || Option.is_some state.slot_editor)
              && Option.is_none state.runtime_lane_pick ->
           (* Append a failover candidate to the open slot editor's lane, over
              whichever screen it covers, or else to the standalone lane under
              the overview's cursor. The pick is typed as a standalone lane so
              the routing write resolves the walk-order table rather than the
              conversation lane of the same-looking id. *)
           (match
              Masc_tui_types.slot_editor_exact_lane state,
              Masc_tui_types.selected_standalone_lane state
            with
            | None, None -> ()
            | Some lane, _ | None, Some { Masc.Tui_decode.sl_lane = lane; _ } ->
                Masc_tui_types.open_runtime_lane_pick state
                  (Masc_tui_types.Pick_exact_lane lane);
                Masc_tui_types.dismiss_runtime_lane_notice state;
                state.lanes_action_error <- None;
                Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load state ~mailbox:async_messages)
        | Some ("T" | "t")
          when state.view = Keepers Keeper_detail
               && state.detail_tab = Detail_identity ->
           Masc_tui_identity_input.toggle state
             ~switch:(fun ~keeper_name ~provider_id ~enabled -> Masc_tui_identity_requests.launch_switch state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state async_messages) ~fork:(Masc_tui_transport.Workspace_admission.fork_job state ~mailbox:async_messages) ~keeper_name ~provider_id ~enabled)
             ~report:(fun level detail -> report_action state level detail)
        | Some ("A" | "a")
          when state.view = Keepers Keeper_detail
               && state.detail_tab = Detail_identity ->
           Masc_tui_identity_input.open_app_form state
        | Some ("O" | "o")
          when state.view = Keepers Keeper_detail
               && state.detail_tab = Detail_identity
               && Option.is_none (text_input_target state ~compact_viewport) ->
           Masc_tui_identity_input.next_order state
        | Some ("V" | "v")
          when state.view = Keepers Keeper_detail
               && state.detail_tab = Detail_identity
               && Option.is_none (text_input_target state ~compact_viewport) ->
           Masc_tui_identity_input.next_show state
        | Some ("D" | "d")
          when state.view = Keepers Keeper_detail
               && state.detail_tab = Detail_identity
               && Option.is_none (text_input_target state ~compact_viewport) ->
           Masc_tui_identity_input.disconnect state
             ~unbind:(fun ~keeper_name ~provider_id -> Masc_tui_identity_requests.launch_disconnect state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state async_messages) ~fork:(Masc_tui_transport.Workspace_admission.fork_job state ~mailbox:async_messages) ~keeper_name ~provider_id)
             ~report:(fun level detail -> report_action state level detail)
       (* The Identity list narrows as you type, which the row search above
          deliberately does not: sixty-seven rows is a list to look things up
          in rather than scroll. While it is open every printable key is
          text, so R, q, [ and the rest come back only when it closes -- esc,
          or backspace on an empty query. The arrows are named keys rather
          than characters and keep moving the cursor through what is left. *)
       | Some k
         when text_input_target state ~compact_viewport
              = Some Text_identity_filter ->
           Masc_tui_identity_input.filter_key state
             ~move_cursor:(fun ~delta -> move_identity_cursor state ~delta)
             ~login:(fun ~keeper_name ~provider_id ~label -> Masc_tui_identity_requests.launch_login state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state async_messages) ~fork:(Masc_tui_transport.Workspace_admission.fork_job state ~mailbox:async_messages) ~keeper_name ~provider_id ~label) k
       | Some k
         when text_input_target state ~compact_viewport
              = Some Text_github_token ->
           Masc_tui_github_ui.token_key state ~save:(fun keeper token -> Masc_tui_github_requests.launch_token_save state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state async_messages) ~fork:(Masc_tui_transport.Workspace_admission.fork_job state ~mailbox:async_messages) ~check:(Masc_tui_transport.Workspace_admission.capture_admission state ~mailbox:async_messages) keeper token) k
       | Some "/"
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_identity ->
           state.identity_filter <- Some "";
           state.identity_cursor <- 0
       | Some key
         when (match browser_lane_on_screen state with
           | Some view -> Option.is_some view.client_picker | None -> false)
              && Option.is_none (browser_history_on_screen state)
              && not (List.mem key ["q"; "tab"; "shift-tab"; "\t"; "?"; ":"; "h"]) ->
           (match state.browser_lane with
            | None -> ()
            | Some view ->
                let open Browser_lane_view in
                let cursor = Option.value ~default:0 view.client_picker in
                (match key with
                 | "esc" | "b" ->
                     state.browser_lane_generation <- state.browser_lane_generation + 1;
                     state.browser_lane <- Some { view with client_picker = None;
                       load = (match view.load with
                          | Loading (_, Discover _) -> Idle
                          | (Idle | No_browser | Failed _
                            | Loading
                                (_, ( Read | Screenshot _
                                    | Read_refresh | Scene_read _ | Scene_regions _
                                    | Scene_refresh _ | Scene_scroll _ | Scene_focus _
                                    | Scene_click _ | Scene_follow _ | Scene_follow_refresh _
                                    | Viewport_refresh _ | Viewport_observed _
                                    | Viewport_pointer _ ))) as other -> other) }
                 | "r" when not (busy view) ->
                     Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages (Discover Choose_client)
                 | "A" when not (busy view) ->
                     state.browser_lane <- Some {view with advanced_choices = not view.advanced_choices; client_picker=Some 0}
                 | "j" | "down" | "k" | "up" when not (busy view) ->
                     let delta = if key = "j" || key = "down" then 1 else -1 in
                     state.browser_lane <- Some { view with client_picker = Some
                       (max 0 (min (List.length (browser_choices view) - 1) (cursor + delta))) }
                 | "\r" | "\n" | "enter" when not (busy view) ->
                     (match List.nth_opt (browser_choices view) cursor with
                      | None -> ()
                      | Some choice ->
                          let selected = choose_browser choice view in
                          state.browser_lane <- Some selected;
                          Option.iter (Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages)
                            (browser_choice_operation choice ~before:view selected))
                 | _ -> ()))
       | Some key when String.length key = 1 && Char.code key.[0] = 15
                       && Option.is_none (browser_history_on_screen state)
                       && Option.is_some (browser_lane_on_screen state) ->
           (match state.browser_lane with
            | None -> ()
            | Some view when Browser_lane_view.busy view -> ()
            | Some view ->
                let refuse detail =
                  state.browser_lane <- Some { view with load = Failed detail }
                in
                match !terminal_draws_images, view.selected_tab with
                | Some false, _ -> refuse terminal_draws_no_images
                | _, None -> refuse "Read and select a browser tab before taking a screenshot"
                | (Some true | None), Some tab_id ->
                    Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                      (Browser_lane_view.Screenshot tab_id))
       | Some key when Browser_history.owns_key key && Option.is_some (browser_history_on_screen state) ->
           (match state.browser_history with
            | None -> ()
            | Some history ->
                (match key with
                 | "esc" | "left" | "h" ->
                     close_browser_history state;
                     Option.iter (fun operation -> Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages operation)
                       (Option.bind state.browser_lane Browser_lane_view.pending_read)
                 | "[" | "]" ->
                     Option.iter (fun next ->
                       state.browser_history <- Some next;
                       Masc_tui_surface_requests.Lane_browser_requests.launch_browser_history state ~mailbox:async_messages ~reload:false)
                       (Browser_history.move (if key="[" then -1 else 1) history)
                 | "r" ->
                     state.browser_history <- Some (Browser_history.create history.keeper_name);
                     Masc_tui_surface_requests.Lane_browser_requests.launch_browser_history state ~mailbox:async_messages ~reload:true
                 | "y" ->
                     Option.iter
                       (fun context ->
                         let outcome = copy_reference render_schedule context in
                         report_action state "system"
                           (if state.ui_language = Lang_ko then
                              "브라우저 기록 맥락을 " ^ Masc_tui_clipboard.copy_outcome_text_korean outcome
                            else
                              "Browser history context " ^ Masc_tui_clipboard.copy_outcome_text outcome))
                       (Browser_history.context history)
                 | "j" | "down" | "k" | "up" | "pageup" | "pagedown" | "home" ->
                     let terminal_rows, cols = get_terminal_size () in
                     let limit = Masc_tui_render.browser_history_scroll_limit state ~terminal_rows ~cols history in
                     let delta = match key with "j" | "down" -> 1 | "k" | "up" -> -1
                       | "pagedown" -> max 1 (terminal_rows-10) | "pageup" -> -(max 1 (terminal_rows-10)) | _ -> -history.scroll in
                     state.browser_history <- Some {history with scroll=max 0 (min limit (min limit history.scroll+delta))}
                 | _ -> ()))
       | Some "h" when Option.is_some (browser_lane_on_screen state) ->
           (match selected_keeper state with
            | None -> report_action state "system" "Choose a Keeper to read its retained observations"
            | Some keeper ->
                state.browser_history <- Some (Browser_history.create keeper.k_name);
                Masc_tui_surface_requests.Lane_browser_requests.launch_browser_history state ~mailbox:async_messages ~reload:true)
       | Some "B" when state.view = Connectors ->
           Masc_tui_surface_requests.Lane_browser_requests.open_browser_lane state ~mailbox:async_messages
       | Some (("esc" | "left" | "c" | "A" | "[" | "]" | "j" | "k" | "J" | "K" | "N" | "P"
               | "up" | "down" | "pageup" | "pagedown" | "home" | "r"
               | "b" | "m" | "s" | "v" | "n" | "p" | "y" | "tab" | "\t" | "shift-tab" | "\r" | "\n" | "enter"
               | "1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9") as key)
         when state.view = Connectors && Option.is_some (browser_lane_on_screen state)
           && Option.is_none (browser_history_on_screen state)
           && (not (List.mem key ["tab"; "\t"; "shift-tab"])
               || match browser_lane_on_screen state with
                  | Some view ->
                      Option.is_none view.client_picker
                      && (Option.is_some view.scene || Browser_lane_view.busy view)
                  | None -> false) ->
           (match state.browser_lane with
            | None -> ()
            | Some view ->
                let open Browser_lane_view in
                let scroll delta =
                  let terminal_rows, cols = get_terminal_size () in
                  let limit = Masc_tui_render.browser_lane_scroll_limit state ~terminal_rows ~cols view in
                  state.browser_lane <- Some
                    { view with scroll = max 0 (min limit (min limit view.scroll + delta)) }
                in
                let read view =
                  state.browser_lane <- Some view;
                  Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages Read
                in
                let reveal_selection selected =
                  let terminal_rows, cols = get_terminal_size () in
                  let scroll = Masc_tui_render.browser_lane_selection_scroll
                    state ~terminal_rows ~cols selected in
                  state.browser_lane <- Some { selected with scroll }
                in
                (match key with
                 | "esc" | "left" ->
                     leave_browser_lane state ~mailbox:async_messages
                 | "A" when not (busy view) ->
                     state.browser_lane <- Some {view with advanced_choices = true; client_picker=Some 0};
                     Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages (Discover Choose_client)
                 | "b" when not (busy view) ->
                     state.browser_lane <- Some { view with client_picker = Some 0 };
                     Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages (Discover Choose_client)
                 | "[" | "]" when not (busy view) ->
                     read (select_tab (if key = "[" then -1 else 1) view)
                 | ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9") as key
                   when not (busy view) ->
                     let index = Char.code key.[0] - Char.code '1' in
                     let selected = select_tab_index index view in
                     if selected.selected_tab <> view.selected_tab then read selected
                 | "v" when not (busy view) ->
                     (match view.selected_tab with
                      | Some tab_id ->
                          (match view.scene_guard with
                           | Some guard -> Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                               (Scene_follow_refresh {tab_id;guard;scene_view=Browser_lane.Regions})
                           | None -> Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages (Scene_regions tab_id))
                      | None -> ())
                 | "m" when not (busy view) ->
                     (match Browser_lane_view.primary_region_action view with
                      | Primary_regions {tab_id} ->
                          (* First [m] observes the landmark map. A second
                             [m] focuses the exact main/article reference;
                             no label or URL heuristic is used. *)
                          Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                            (Scene_regions tab_id)
                      | Primary_guarded_regions {tab_id;guard} ->
                          Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                            (Scene_follow_refresh {tab_id;guard;scene_view=Browser_lane.Regions})
                      | Primary_focus {tab_id;index;target} ->
                          let focused = {view with scene_cursor = index;
                            scene_scope = Browser_lane_view.scene_scope_context_for_index view index} in
                          state.browser_lane <- Some focused;
                          Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                            (Scene_focus {tab_id;target})
                      | Primary_error Browser_lane_view.No_primary_region ->
                          state.browser_lane <- Some {view with
                            load = Failed "No unambiguous main/article region observed; use v:regions"}
                      | Primary_error Browser_lane_view.Ambiguous_primary_region ->
                          state.browser_lane <- Some {view with
                            load = Failed "Multiple main/article regions observed; use v:regions"}
                      | Primary_unavailable -> ())
                 | "s" when not (busy view) ->
                     (match view.scene, view.selected_tab with
                      | Some _, _ -> read {view with scene = None; scene_delta = None; scroll = 0}
                      | None, Some tab_id ->
                          (match view.scene_guard with
                           | Some guard -> Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                               (Scene_follow_refresh {tab_id;guard;scene_view=Browser_lane.Content})
                           | None -> Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages (Scene_read tab_id))
                      | None, None -> ())
                 | "r" ->
                     (match view.scene, view.selected_tab with
                      | None, Some tab_id ->
                          (match view.scene_guard with
                           | Some guard -> Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                               (Scene_follow_refresh {tab_id;guard;scene_view=Browser_lane.Content})
                           | None -> Masc_tui_surface_requests.Lane_browser_requests.refresh_browser_lane state ~mailbox:async_messages)
                      | Some scene, Some tab_id ->
                          let operation = match scene.content.scope, scene.content.view with
                            | Some target, _ -> Scene_focus {tab_id;target}
                            | None, Browser_lane.Regions -> Scene_regions tab_id
                            | None, Browser_lane.Content -> Scene_read tab_id in
                          Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages operation
                      | None, None | Some _, None -> Masc_tui_surface_requests.Lane_browser_requests.refresh_browser_lane state ~mailbox:async_messages)
                 | "J" | "K" when Option.is_some view.scene && not (busy view) ->
                     (match view.scene, view.selected_tab with
                      | Some scene, Some tab_id ->
                          let distance = int_of_float scene.content.height in
                          let delta_y = if key = "J" then distance else -distance in
                          Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                            (Scene_scroll {tab_id;document_id=scene.content.document_id;
                              expected_url=scene.content.url;
                              scene_view=scene.content.view;scope=scene.content.scope;delta_y})
                      | _ -> ())
                 | "n" | "p" when Option.is_some view.scene && not (busy view) ->
                     let count = List.length (scene_targets view) in
                     if count > 0 then reveal_selection {view with scene_cursor =
                       (view.scene_cursor + (if key = "n" then 1 else count - 1)) mod count}
                 | "N" | "P" when Option.is_some view.scene
                                      && scene_has_articles view && not (busy view) ->
                     reveal_selection (move_scene_article ~backwards:(key = "P") view)
                 | "tab" | "\t" | "shift-tab" when Option.is_some view.scene && not (busy view) ->
                     reveal_selection (move_scene_action ~backwards:(key = "shift-tab") view)
                 | "y" when not (busy view) ->
                     (match scene_context view with
                      | Some context ->
                          let outcome = copy_reference render_schedule context in
                          report_action state "system"
                            (if state.ui_language = Lang_ko then
                               "브라우저 요소 맥락을 " ^ Masc_tui_clipboard.copy_outcome_text_korean outcome
                             else
                               "Browser element context " ^ Masc_tui_clipboard.copy_outcome_text outcome)
                      | None -> ())
                 | "\r" | "\n" | "enter" when not (busy view) ->
                     (match view.scene, selected_scene_target view with
                      | Some scene, Some node ->
                          (match scene_target_action node with
                           | Some Read_region ->
                          state.browser_lane <- Some {view with
                            scene_scope = Browser_lane_view.scene_scope_context_for_node view node};
                          Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                            (Scene_focus {tab_id=scene.tab_id;target={document_id=scene.content.document_id;node_id=node.node_id}})
                           | Some Follow_link -> Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                          (Scene_follow {tab_id=scene.tab_id;document_id=scene.content.document_id;
                            node_id=node.node_id;expected_url=scene.content.url})
                           | Some Click_control -> Masc_tui_surface_requests.Lane_browser_requests.launch_browser_lane state ~mailbox:async_messages
                          (Scene_click {tab_id=scene.tab_id;document_id=scene.content.document_id;
                            node_id=node.node_id;expected_url=scene.content.url;scope=scene.content.scope})
                           | None -> ())
                      | _ -> ())
                 | "j" | "down" -> scroll 1
                 | "k" | "up" -> scroll (-1)
                 | "pagedown" | "pageup" ->
                     let rows, _ = get_terminal_size () in
                     let delta = max 1 (rows - 10) in
                     scroll (if key = "pagedown" then delta else -delta)
                 | "home" -> state.browser_lane <- Some { view with scroll = 0 }
                 | _ -> ()))
       | Some "R" when Option.is_some (browser_history_on_screen state) ->
           (* History's [r] reloads observations. [R] rechecks workspace
              authority even when retained rows cannot authorize that read.
              Do not refresh the live browser hidden underneath history. *)
           start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
             ~intent:Operator_key ~refresh_inflight:http_refresh_inflight
             ~scoped_refresh_inflight:http_scoped_refresh_inflight
             ~scoped_refresh_followup ~mailbox:async_messages
       | Some key
         when state.view = Connectors && Option.is_some (browser_lane_on_screen state)
              && not (List.mem key ["q"; "tab"; "shift-tab"; "\t"; "?"; ":"]) ->
           (* The child owns its keys. In particular b/u must never mutate a
              hidden connector binding while browser content is on screen. *)
           ()
       | Some ("j" | "down" | "k" | "up" as move)
         when state.view = Keepers Keeper_detail && state.detail_tab = Detail_runs
              && not (Masc_tui_roster_pane.arrows_go_left
                ~hidden:(roster_pane_hidden state) ~cols:terminal_columns
                ~preferring_left:(state.keeper_detail_focus = Left_pane)) ->
           let count = List.length (Masc_tui_fusion_model.selected_keeper_runs state) in
           let delta = if move = "j" || move = "down" then 1 else -1 in
           state.keeper_run_cursor <- max 0 (min (count - 1) (state.keeper_run_cursor + delta));
           state.detail_scroll <- state.keeper_run_cursor
       | Some ("\r" | "\n" | "right")
         when state.view = Keepers Keeper_detail && state.detail_tab = Detail_runs
              && not (Masc_tui_roster_pane.arrows_go_left
                ~hidden:(roster_pane_hidden state) ~cols:terminal_columns
                ~preferring_left:(state.keeper_detail_focus = Left_pane)) ->
           (match Masc_tui_fusion_model.selected_keeper_run state with
            | None -> ()
            | Some (_, run) ->
                state.followed_from <- Some (state.view, None);
                goto_surface ~from_reference:true state ~mailbox:async_messages Fusion;
                state.fusion_mode <- Fusion_detail run.fur_run_id;
                state.fusion_scroll <- 0;
                state.fusion_detail <- None;
                state.fusion_detail_stale <- false;
                state.fusion_detail_error <- None;
                Masc_tui_work_actions.Detail_navigation.launch_fusion_detail_load ~demand:Masc_tui_fusion_updates.After_change
                  state ~mailbox:async_messages ~run_id:run.fur_run_id)
       | Some "a" when state.view = Fusion && state.fusion_mode = Fusion_list ->
           launch_fusion_launch_options_load state ~mailbox:async_messages
       | Some "K" when state.view = Fusion
           && (match state.fusion_mode, Masc_tui_fusion_model.selected_fusion_entry state with
               | Fusion_historical_detail _, _
               | Fusion_list, Some (Masc.Tui_decode_fusion.Fusion_historical_evidence _) -> true
               | (Fusion_list, Some (Masc.Tui_decode_fusion.Fusion_retained_run _))
               | (Fusion_list, None) | (Fusion_detail _, _) -> false) ->
           report_action state "system" "Historical Board evidence has no retained caller identity"
       | Some "K" when state.view = Fusion ->
           let run = match state.fusion_mode, Masc_tui_fusion_model.fusion_snapshot state with
             | Fusion_detail id, Some snapshot -> List.find_opt
                 (fun (run : Masc.Tui_decode_fusion.fusion_run) -> String.equal run.fur_run_id id) snapshot.fus_runs
             | Fusion_list, Some _ ->
                 (match Masc_tui_fusion_model.selected_fusion_entry state with
                  | Some (Masc.Tui_decode_fusion.Fusion_retained_run run) -> Some run
                  | Some (Masc.Tui_decode_fusion.Fusion_historical_evidence _) | None -> None)
             | Fusion_historical_detail _, _ | _, None -> None in
           (match Option.bind run (fun (run : Masc.Tui_decode_fusion.fusion_run) ->
              List.find_index (fun (k : keeper) -> String.equal k.k_name run.fur_keeper) state.keepers) with
            | None -> report_action state "system" "The calling Keeper is not in the current roster"
            | Some index ->
                state.followed_from <- Some (state.view, None);
                state.keeper_cursor <- index;
                Option.iter (open_keeper_detail state ~mailbox:async_messages) (selected_keeper state);
                state.detail_tab <- Detail_runs;
                state.keeper_run_cursor <-
                  Option.bind run (fun (run : Masc.Tui_decode_fusion.fusion_run) ->
                    List.find_index (fun (candidate : Masc.Tui_decode_fusion.fusion_run) ->
                      String.equal candidate.fur_run_id run.fur_run_id)
                      (Masc_tui_fusion_model.selected_keeper_runs state))
                  |> Option.value ~default:0)
       | Some "B" when state.view = Fusion
           && state.fusion_mode = Fusion_list ->
           (match Masc_tui_fusion_model.selected_fusion_entry state with
            | Some (Masc.Tui_decode_fusion.Fusion_historical_evidence reference) ->
                state.followed_from <- Some (state.view, None);
                state.board_mode <- Board_read reference.fhe_post_id;
                state.board_history_post_id <- None;
                state.board_detail <- Board_detail.clear state.board_detail;
                state.board_scroll <- 0;
                state.board_comment_scroll <- 0;
                state.board_comment_landing <- None;
                state.board_comments_focused <- false;
                state.board_focus <- Right_pane;
                goto_surface ~from_reference:true state ~mailbox:async_messages Board;
                owe_board_post_read state ~mailbox:async_messages ~post_id:reference.fhe_post_id
            | Some (Masc.Tui_decode_fusion.Fusion_retained_run _) | None ->
                report_action state "system" "Open a Fusion run to follow its Board evidence")
       | Some "B" when state.view = Fusion ->
           (match state.fusion_mode, state.fusion_detail with
            | Fusion_historical_detail reference, _ ->
                state.followed_from <- Some (state.view, None);
                state.board_mode <- Board_read reference.fhe_post_id;
                state.board_history_post_id <- None;
                state.board_detail <- Board_detail.clear state.board_detail;
                state.board_scroll <- 0;
                state.board_comment_scroll <- 0;
                state.board_comment_landing <- None;
                state.board_comments_focused <- false;
                state.board_focus <- Right_pane;
                goto_surface ~from_reference:true state ~mailbox:async_messages Board;
                owe_board_post_read state ~mailbox:async_messages ~post_id:reference.fhe_post_id
            | Fusion_detail id, Some detail when id = detail.fud_run.fur_run_id ->
                (match detail.fud_evidence with
                 | None -> report_action state "system" "No Board evidence has been recorded for this run"
                 | Some evidence ->
                     state.followed_from <- Some (state.view, Some id);
                     state.board_mode <- Board_read evidence.fe_post_id;
                     state.board_history_post_id <- None;
                     state.board_detail <- Board_detail.clear state.board_detail;
                     state.board_scroll <- 0;
                     state.board_comment_scroll <- 0;
                     state.board_comment_landing <- None;
                     state.board_comments_focused <- false;
                     state.board_focus <- Right_pane;
                     goto_surface ~from_reference:true state ~mailbox:async_messages Board;
                     owe_board_post_read state ~mailbox:async_messages ~post_id:evidence.fe_post_id)
            | (Fusion_list | Fusion_detail _), _ -> report_action state "system" "Open a Fusion run to follow its Board evidence")
       | Some ("h" | "H") when state.view = Repositories && Option.is_none state.workspace_activity_repo ->
           (match state.repositories with
            | None -> ()
            | Some snapshot ->
                Option.iter (fun (repo : Tui_decode.repository) ->
                  state.workspace_activity_repo <- Some repo.rp_id;
                  state.workspace_activity_cursor <- 0;
                  state.workspace_activity_context_scroll <- None;
                  launch_workspace_activity state ~mailbox:async_messages ~repo_id:repo.rp_id)
                  (List.nth_opt snapshot.rs_repositories state.repositories_cursor))
       | Some ("v" | "V") when state.view = Repositories && Option.is_some state.workspace_activity_repo && Option.is_none state.workspace_activity_context_scroll ->
           let _, _, selected = workspace_activity_selection state in
           if Option.is_some selected then state.workspace_activity_context_scroll <- Some 0
       | Some ("esc" | "left") when state.view = Repositories && Option.is_some state.workspace_activity_context_scroll ->
           state.workspace_activity_context_scroll <- None
       | Some ("j" | "down" | "k" | "up" | "pageup" | "pagedown" | "home" | "end" | "g" | "G" as move)
         when state.view = Repositories && Option.is_some state.workspace_activity_repo
              && Option.is_some state.workspace_activity_context_scroll ->
           let terminal_rows, cols = get_terminal_size () in
           let count = List.length (workspace_activity_context_lines state ~cols) in
           let height = workspace_activity_context_height state
             ~budget:(Masc_tui_render_prim.surface_chrome_budget ~frame:Masc_tui_render_prim.Chrome_screen state ~terminal_rows) in
           let maximum = max 0 (count - height) in
           let old = match state.workspace_activity_context_scroll with Some scroll -> max 0 (min maximum scroll) | None -> 0 in
           let next = match move with
             | "home" | "g" -> 0 | "end" | "G" -> maximum
             | "j" | "down" -> old + 1 | "k" | "up" -> old - 1
             | "pageup" -> old - Masc_tui_scroll.page_step ~height
             | _ -> old + Masc_tui_scroll.page_step ~height in
           state.workspace_activity_context_scroll <- Some (max 0 (min maximum next))
       | Some ("esc" | "left") when state.view = Repositories && Option.is_some state.workspace_activity_repo ->
           state.workspace_activity_repo <- None;
           state.workspace_activity_context_scroll <- None
       | Some ("r" | "R") when state.view = Repositories && Option.is_some state.workspace_activity_repo ->
           Option.iter (fun repo_id -> launch_workspace_activity state ~mailbox:async_messages ~repo_id)
             state.workspace_activity_repo
       | Some ("j" | "down" | "k" | "up" | "pageup" | "pagedown" as move)
         when state.view = Repositories && Option.is_some state.workspace_activity_repo ->
           let terminal_rows, _ = get_terminal_size () in
           let page = workspace_activity_page_rows ~surface_rows:(surface_body_rows state ~terminal_rows) in
           let delta = match move with "j" | "down" -> 1 | "k" | "up" -> -1 | "pageup" -> -page | _ -> page in
           state.workspace_activity_cursor <- max 0 (min (List.length (workspace_activity_rows state) - 1)
             (state.workspace_activity_cursor + delta));
           state.workspace_activity_context_scroll <- None
       | Some ("\r" | "\n" | "right")
         when state.view = Repositories && Option.is_some state.workspace_activity_repo ->
           let _, _, selected = workspace_activity_selection state in
           (match state.workspace_activity_repo, selected with
            | Some repo_id, Some (change, relative_path) ->
                let path = Playground_paths.bundle_relative_repo_path ~repo_id relative_path in
                enter_keeper_code_file state ~keeper:change.Tui_decode.fc_keeper ~path;
                Masc_tui_code_requests.launch_entries_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages);
                Masc_tui_code_requests.launch_file_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~path
            | None, _ | _, None -> ())
       | Some key when state.view = Repositories && Option.is_some state.workspace_activity_repo
           && not (List.mem key ["tab"; "shift-tab"; "\t"; "q"; "?"; ":"]) -> ()
       | Some (("S" | "C" | "u" | "U" | "X") as key)
         when state.view = Config && state.config_pane = Config_runtime
              && not state.runtime_config_status_open && Option.is_none state.runtime_account_form ->
           Masc_tui_editor_forms.Runtime_config_forms.handle_runtime_config_draft state ~mailbox:async_messages key
       | Some ("v" | "V")
         when state.view = Config && state.config_pane = Config_runtime ->
           state.runtime_config_status_open <- not state.runtime_config_status_open;
           state.runtime_config_status_scroll <- 0
       | Some ("e" | "E" | "enter" | "\r" | "\n" | "/" | "n" | "N")
         when state.view = Config && state.config_pane = Config_runtime
              && state.runtime_config_status_open ->
           (* This pane reads metadata. A source cursor retained behind it
              cannot authorize an edit or a search of that hidden source. *)
           ()
       | Some (("esc" | "left" | "j" | "k" | "up" | "down" | "pageup" | "pagedown" | "home" | "end" | "g" | "G") as key)
         when state.view = Config && state.config_pane = Config_runtime
              && state.runtime_config_status_open ->
           (match key with
            | "esc" | "left" -> state.runtime_config_status_open <- false
            | "home" | "g" -> state.runtime_config_status_scroll <- 0
            | _ ->
                let terminal_rows, cols = get_terminal_size () in
                let limit = Masc_tui_render.runtime_config_status_scroll_limit state ~terminal_rows ~cols in
                (match key with
                 | "end" | "G" -> state.runtime_config_status_scroll <- limit
                 | _ ->
                     let step = match key with
                       | "pageup" | "pagedown" ->
                           Masc_tui_render_prim.surface_chrome_budget
                             ~frame:Masc_tui_render_prim.Chrome_screen state ~terminal_rows
                       | _ -> 1
                     in
                     let delta = if List.mem key ["k"; "up"; "pageup"] then -step else step in
                     state.runtime_config_status_scroll <-
                       max 0 (min limit (min limit state.runtime_config_status_scroll + delta))))
       | Some "!"
         when state.view = Keepers Keeper_list && not state.composer_focused
              && Option.is_none (text_input_target state ~compact_viewport)
              && not (modal_owns_keys state) ->
           Option.iter (open_detail_reading state)
             (Masc_tui_render_keepers.keeper_observation_reading state)
       | Some (("." | "…" | "\015") as key)
         when state.view = Memory && state.memory_page = Memory_changes
              && not state.composer_focused && not (modal_owns_keys state) ->
           (match state.memory_facts_keeper with
            | None -> ()
            | Some keeper_name ->
                Option.iter
                  (fun preview -> open_selected_image state ~mailbox:async_messages preview)
                  ((if key = "\015" then Masc_tui_render_keeper_memory.change_diagram
                    else Masc_tui_render_keeper_memory.change_focus_diagram) state ~keeper_name))
       | Some ("1" | "2" | "3" | "4" as page)
         when state.view = Memory && not state.memory_fact_detail_open
              && not state.composer_focused && not (modal_owns_keys state) ->
           let target = match state.memory_facts_keeper with
             | Some keeper -> Some keeper
             | None -> Option.map (fun (keeper : Masc.Tui_decode_memory_health.memory_keeper_health) ->
                 keeper.mkh_keeper_id) (selected_memory_keeper state) in
           if String.equal page "4" then begin
             state.memory_page <- Memory_facts;
             state.memory_facts_keeper <- None;
             state.search <- None; state.search_last <- ""
           end else
             (match target with
              | None -> report_action state "info" "Select a Keeper to browse its memory"
              | Some "*" when String.equal page "3" ->
                  report_action state "info" "Changes require an individual Keeper; select one from storage"
              | Some keeper ->
                if Option.is_none state.memory_facts_keeper then begin
                  state.search <- None; state.search_last <- ""
                end;
                state.memory_facts_keeper <- Some keeper;
                state.memory_facts_cursor <- 0; state.memory_facts_scroll <- 0;
                state.memory_changes_cursor <- 0;
                if String.equal page "3" then state.memory_page <- Memory_changes
                else begin
                  state.memory_page <- Memory_facts;
                  state.memory_facts_sort <- if String.equal page "2" then Sort_retrieved_count else Sort_recency
                end)
       | Some ("j" | "k" | "up" | "down" | "wheel-up" | "wheel-down" | "pageup" | "pagedown"
              | "g" | "G" | "home" | "end" | "[" | "]" | "\r" | "\n" | "enter" as key)
         when state.view = Memory && state.memory_page = Memory_changes
              && not state.composer_focused && not (modal_owns_keys state) ->
           (match state.memory_facts_keeper with
            | None -> ()
            | Some keeper_name ->
              let count = Masc_tui_render_keeper_memory.change_count state ~keeper_name in
              let maximum = max 0 (count - 1) in
              match key with
              | "\r" | "\n" | "enter" ->
                  Option.iter (open_detail_reading state)
                    (Masc_tui_render_keeper_memory.change_reading state ~keeper_name)
              | "g" | "home" -> state.memory_changes_cursor <- 0
              | "G" | "end" -> state.memory_changes_cursor <- maximum
              | _ ->
                  let page = max 1 (Masc_tui_render_keeper_memory.changes_page_size state
                    ~max_lines:(Masc_tui_render_prim.surface_chrome_budget
                      ~frame:Masc_tui_render_prim.Chrome_screen state
                      ~terminal_rows:(fst (get_terminal_size ()))) ~keeper_name) in
                  let delta = match key with
                    | "k" | "up" | "wheel-up" | "[" -> -1
                    | "pageup" -> -page | "pagedown" -> page | _ -> 1 in
                  state.memory_changes_cursor <- max 0 (min maximum (min maximum state.memory_changes_cursor + delta)))
       | Some "/"
         when Option.is_some (Masc_tui_surface_search.surface_row_texts ~cols:(snd (get_terminal_size ())) state state.view) ->
           state.search <- Some ""
       | Some (("[" | "]") as bracket)
         when state.view = Keepers Keeper_detail ->
           (* Tabs inside the detail pane: [ and ] walk the same short list
              the pane's title row draws. Non-Info tabs read over HTTP on
              entry; the stamped keeper name keeps a slow answer from being
              drawn under a different selection. *)
           let tabs = Masc_tui_types.keeper_detail_tabs in
           let count = List.length tabs in
           let index =
             let rec find i = function
               | [] -> 0
               | tab :: rest ->
                   if tab = state.detail_tab then i else find (i + 1) rest
             in
             find 0 tabs
           in
           let step = if bracket = "]" then 1 else count - 1 in
           enter_keeper_detail_tab state ~mailbox:async_messages
             (List.nth tabs ((index + step) mod count))
       (* One step through the list a detail was opened from, on every surface
          that has one. Each reuses the same open the Enter arm uses, so a
          step cannot fetch less than an open does. Guarded on the detail
          being open: with the list showing, [ / ] is free for the surface to
          mean something else, and on Changes and the Keeper detail tabs it
          already does. *)
       | Some (("[" | "]") as bracket)
         when state.view = Schedules && Option.is_some (Masc_tui_work_actions.Board_schedule_actions.schedule_detail_on_screen state) ->
           Masc_tui_work_actions.Detail_navigation.step_detail_cursor
             ~count:
               (match state.schedules with
                | None -> 0
                | Some snapshot -> List.length snapshot.scs_rows)
             ~cursor:state.schedule_cursor
             ~delta:(if bracket = "]" then 1 else -1)
             ~set_cursor:(fun n -> state.schedule_cursor <- n)
             ~reopen:(fun () ->
               Masc_tui_work_actions.Detail_navigation.open_schedule_detail state ~mailbox:async_messages)
       | Some (("[" | "]") as bracket)
         when state.view = Verification
              && Option.is_some state.verification_detail_request_id ->
           Masc_tui_work_actions.Detail_navigation.step_detail_cursor
             ~count:
               (match state.verification with
                | None -> 0
                | Some s -> List.length s.Masc.Tui_decode.vs_requests)
             ~cursor:state.verification_cursor
             ~delta:(if bracket = "]" then 1 else -1)
             ~set_cursor:(fun n -> state.verification_cursor <- n)
             ~reopen:(fun () ->
               Masc_tui_work_actions.Detail_navigation.open_verification_detail state ~mailbox:async_messages)
       | Some (("[" | "]") as bracket)
         when state.view = Harness && Option.is_some state.harness_detail ->
           Masc_tui_work_actions.Detail_navigation.step_detail_cursor
             ~count:
               (match state.harness with
                | None -> 0
                | Some s -> List.length s.Masc.Tui_decode.hs_verdicts)
             ~cursor:state.harness_cursor
             ~delta:(if bracket = "]" then 1 else -1)
             ~set_cursor:(fun n -> state.harness_cursor <- n)
             ~reopen:(fun () -> Masc_tui_work_actions.Detail_navigation.open_harness_detail state)
       | Some (("[" | "]") as bracket)
         when Option.is_some (selected_planning_goal_id state) ->
           state.home_opened_request <- None;
           Masc_tui_work_actions.Detail_navigation.step_detail_cursor
             ~count:
               (match state.planning with
                | None -> 0
                | Some p ->
                    List.length
                      (planning_visible_goals ~filter:state.planning_filter
                         ~sort:state.planning_sort p.pl_goals))
             ~cursor:state.planning_cursor
             ~delta:(if bracket = "]" then 1 else -1)
             ~set_cursor:(fun n -> state.planning_cursor <- n)
             ~reopen:(fun () ->
               Masc_tui_work_actions.Detail_navigation.open_planning_detail state ~mailbox:async_messages)
       | Some (("[" | "]") as bracket)
         when state.view = Fusion
              && (match state.fusion_mode with
                  | Fusion_detail _ | Fusion_historical_detail _ -> true
                  | Fusion_list -> false) ->
           (match Masc_tui_fusion_model.fusion_detail_entry_index state with
            | None ->
                state.fusion_mode <- Fusion_list;
                state.fusion_scroll <- 0;
                state.fusion_detail_error <- None;
                state.fusion_detail_generation <- state.fusion_detail_generation + 1
            | Some cursor ->
                Masc_tui_work_actions.Detail_navigation.step_detail_cursor
                  ~count:(List.length (Masc_tui_fusion_model.fusion_list_entries state))
                  ~cursor
                  ~delta:(if bracket = "]" then 1 else -1)
                  ~set_cursor:(fun n -> state.fusion_cursor <- n)
                  ~reopen:(fun () -> Masc_tui_work_actions.Detail_navigation.open_fusion_detail state ~mailbox:async_messages))
       (* Approvals holds no id -- the detail is a flag over the row under the
          cursor -- so stepping is the cursor move, and the pane follows. *)
       | Some (("[" | "]") as bracket)
         when state.view = Approvals && state.approval_detail_open ->
           state.home_opened_request <- None;
           Masc_tui_work_actions.Detail_navigation.step_detail_cursor ~count:(List.length (Masc_tui_approvals_model.approval_items state))
             ~cursor:state.approval_cursor
             ~delta:(if bracket = "]" then 1 else -1)
             ~set_cursor:(fun n -> state.approval_cursor <- n)
             ~reopen:(fun () -> state.approval_detail_scroll <- 0)
       | Some (("[" | "]") as bracket)
         when state.view = System_logs
              && system_log_detail_open state ->
           Masc_tui_work_actions.Detail_navigation.step_detail_cursor
             ~count:
               (List.length (Masc_tui_types.visible_system_log_entries state))
             ~cursor:(system_logs_page state).lp_cursor
             ~delta:(if bracket = "]" then 1 else -1)
             ~set_cursor:(fun cursor -> edit_system_logs_page state (fun page -> {page with lp_cursor=cursor}))
             ~reopen:(fun () -> Masc_tui_work_actions.Detail_navigation.open_selected_system_log state)
       | Some (("[" | "]") as bracket) when state.view = Board ->
           step_board_read state ~mailbox:async_messages
             ~delta:(if bracket = "]" then 1 else -1)
       | Some (("[" | "]") as bracket) when state.view = Changes ->
           cycle_changes_keeper state ~mailbox:async_messages
             ~delta:(if bracket = "]" then 1 else -1)
       | Some "f" when state.view = Resources ->
           Masc_tui_resources_updates.select_scope state
             (Masc_tui_resource_catalog.next_scope state.resource_scope)
       | Some "s" when state.view = Resources -> open_resource_save_prompt state
       | Some "o" when state.view = Resources -> open_resource_in_dashboard state ~mailbox:async_messages
       | Some "c" when state.view = Resources ->
           launch_artifact_check_change state ~mailbox:async_messages
       | Some ("P" | "U" | "Y" | "!")
           when state.view = Resources && state.resource_focus = Right_pane
                && (!share_interrupt_barrier || Masc_tui_exit_signals.pending_signal exit_signals) ->
           report_action state "system" "Share action interrupted; use the key again when ready."
       | Some "P" when state.view = Resources && state.resource_focus = Right_pane ->
           toggle_resource_external_share state ~mailbox:async_messages
             ~dispatch_allowed:(resource_share_dispatch_allowed ())
       | Some "U" when state.view = Resources && state.resource_focus = Right_pane ->
           recover_resource_external_share state ~mailbox:async_messages ~confirm:false
             ~dispatch_allowed:(resource_share_dispatch_allowed ())
       | Some "!" when state.view = Resources && state.resource_focus = Right_pane
             && Option.is_some state.resource_share_recovery_prompt ->
           if Masc_tui_shell.Terminal_session.resize_requested terminal_session || Masc_tui_exit_signals.pending_signal exit_signals then begin
             Option.iter (fun prompt -> Masc_tui_artifact_share_confirmation.withdraw prompt.recovery_confirmation)
               state.resource_share_recovery_prompt;
             report_action state "system" "Wait for pending terminal or signal changes before confirming."
           end else recover_resource_external_share state ~mailbox:async_messages ~confirm:true
             ~dispatch_allowed:(resource_share_dispatch_allowed ())
       | Some "Y" when state.view = Resources && state.resource_focus = Right_pane ->
           (match open_resource_report state with
            | Error detail -> report_action state "error" detail
            | Ok report ->
              let key = Masc_tui_resource_catalog.Report_revision report in
              launch_resources_read state ~mailbox:async_messages ~key;
              (match state.resource_read_owner with
               | Some owner ->
                 state.resource_copy_pending <- Some {Masc_tui_resource_catalog.key;owner};
                 report_action state "system" "Refreshing external sharing before copying the public link"
               | None -> report_action state "error" "Could not verify sharing before copying the public link"))
       | Some "R" when state.view = Resources && state.resource_focus = Right_pane ->
           (match Masc_tui_resource_document.current state with
            | Some reading ->
                launch_resources_read state ~mailbox:async_messages
                  ~key:(Masc_tui_resource_catalog.key reading.entry)
            | None -> report_action state "error" "Open a resource to reread it")
       | Some "u" when state.view = Resources ->
           (match Masc_tui_resources_updates.select_next_unchecked state with
            | Error (Request_failed detail) -> report_action state "error" detail
            | Error (Request_withdrawn refusal) ->
                Masc_tui_transport.Request_notice.report_withdrawn state ~request:Kept_request.Unchecked_report_move refusal
            | Ok None -> report_action state "system" "No unchecked reports in the current format and date selection"
            | Ok (Some key) ->
              if state.resource_focus = Right_pane then
                launch_resources_read state ~mailbox:async_messages ~key)
       | Some "t" when state.view = Resources ->
           Masc_tui_resources_updates.toggle_today state ~now:(Unix.gettimeofday ())
       | Some "w" when state.view = Resources ->
           Masc_tui_resources_updates.toggle_layout state
       | Some "v"
         when state.view = Approvals && not state.approval_detail_open
              && state.ask_answer_mode = Ask_browsing
              && not state.composer_focused
              && not (modal_owns_keys state) && not state.palette_open
              && not state.answering_open && not state.link_modal_open
              && Option.is_none (text_input_target state ~compact_viewport) ->
           (match Masc_tui_render_approvals.answer_feedback_reading state with
            | Some reading -> open_detail_reading state reading
            | None -> report_action state "info" "No answer receipt in this workspace")
       | Some "v"
         when state.view = Approvals && state.approval_detail_open
              && not state.composer_focused
              && not (modal_owns_keys state) && not state.palette_open
              && not state.answering_open && not state.link_modal_open
              && Option.is_none (text_input_target state ~compact_viewport) ->
           (match Masc_tui_approvals_model.toggle_value_reading state ~presented:(!presented).approval with
            | Masc_tui_approvals_model.Value_reading_opened | Value_reading_closed -> ()
            | Value_reading_unavailable ->
              report_action state "system" "No decoded Gate string values to read"
            | Value_reading_waiting_for_source ->
              report_action state "system" "Waiting for a Gate queue read in this workspace"
            | Value_reading_changed ->
              report_action state "system" "Approval input changed; review the updated row")
       | Some "v" when state.view = Resources && state.resource_focus = Right_pane ->
           Masc_tui_resources_updates.toggle_presentation state
       | Some "i" when state.view = Resources && state.resource_focus = Right_pane ->
           state.resource_metadata_expanded <- not state.resource_metadata_expanded;
           state.resource_scroll <- Masc_tui_scroll.Position.first;
           state.resource_search_position <- Masc_tui_resource_reading.first
       | Some "\015" when state.view = Resources && state.resource_focus = Right_pane ->
           open_resource_image state ~mailbox:async_messages
       | Some (("(" | ")") as direction)
         when state.view = Resources && state.resource_focus = Right_pane ->
           Masc_tui_resources_updates.step_text_part state
             ~delta:(if direction = ")" then 1 else -1)
       | Some (("," | ".") as direction)
         when state.view = Resources && state.resource_focus = Right_pane ->
           step_resource_image state ~delta:(if direction = "." then 1 else -1)
       | Some (("{" | "}") as bracket)
         when state.view = Resources && state.resource_focus = Right_pane ->
           Masc_tui_resources_updates.step_revision state
             ~direction:(if bracket = "{" then Masc_tui_resource_catalog.Older else Newer)
             ~read:(launch_resources_read state ~mailbox:async_messages)
       | Some (("[" | "]") as bracket)
         when state.view = Resources && state.resource_focus = Right_pane ->
           Masc_tui_work_actions.Detail_navigation.step_detail_cursor
             ~count:
               (match visible_resources state with
                | None -> 0
                | Some resources -> List.length resources)
             ~cursor:state.resources_cursor
             ~delta:(if bracket = "]" then 1 else -1)
             ~set_cursor:(fun cursor -> state.resources_cursor <- cursor)
             ~reopen:(fun () ->
               Masc_tui_resources_updates.open_selected state
                 ~read:(launch_resources_read state ~mailbox:async_messages))
       | Some (("[" | "]") as bracket)
         when state.view = Lanes && state.lanes_mode = Lanes_overview ->
           (* A package row's exact outputs, chosen by name (RFC operator-quiz
              §4.8); e then opens the chosen one's table. *)
           (match selected_inventory_lane state with
            | None -> ()
            | Some row ->
              (match
                 Masc_tui_lane_inventory.step_exact_output
                   ~selected:(lanes_exact_output_name state row)
                   ~direction:(if bracket = "]" then 1 else -1) row
               with
               | Some (_, name) ->
                 state.lanes_exact_output <- Some (row.Masc.Tui_decode_lane_inventory.id, name)
               | None -> ()))

       (* The run before or after the open one, with the detail left open:
          what [ and ] mean on every other detail (RFC tui-one-screen-grammar,
          section 3.1). On the run list they do nothing -- ] used to read the
          older page there, and that is > now. *)
       | Some (("[" | "]") as bracket) when state.view = Lanes ->
           (match state.lanes_mode with
            | Lanes_run_detail (lane, _) ->
              Masc_tui_work_actions.Detail_navigation.step_detail_cursor
                ~count:(List.length (Option.value state.lane_runs ~default:[]))
                ~cursor:state.lane_runs_cursor
                ~delta:(if bracket = "]" then 1 else -1)
                ~set_cursor:(fun n -> state.lane_runs_cursor <- n)
                ~reopen:(fun () ->
                  open_selected_lane_run state ~mailbox:async_messages ~lane)
            | Lanes_overview | Lanes_run_list _ | Lanes_measurement_detail _
            | Lanes_inventory_detail _ -> ())
       (* The next page the server holds, as > is on Schedules and
          Verification. The page is appended, so there is no < to go back
          to: the rows already read stay above. *)
       | Some ">" when state.view = Lanes ->
           (match state.lanes_mode, state.lane_runs_next, state.lane_runs_loading with
            | Lanes_run_list lane, Some before, false ->
              launch_lane_runs_load ~before state ~mailbox:async_messages ~lane
            | ( ( Lanes_overview | Lanes_run_list _ | Lanes_run_detail _
                | Lanes_measurement_detail _ | Lanes_inventory_detail _ ),
                _,
                _ ) -> ())
       | Some "[" when state.view = Tools && state.tools_pane = Tools_surface -> handle_skill_run 1
       | Some "]" when state.view = Tools && state.tools_pane = Tools_surface -> handle_skill_run (-1)
       | Some (("[" | "]") as bracket) when state.view = Tools ->
           Masc_tui_work_requests.Tools_task_requests.cycle_tools_keeper state ~mailbox:async_messages
             ~delta:(if bracket = "]" then 1 else -1)
       | Some ("J" | "K")
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_channels ->
           let count =
             match Masc_tui_editor_forms.Connector_forms.selected_connector state with
             | None -> 0
             | Some connector -> List.length connector.cn_bindings
           in
           state.connector_unbind_armed <- None;
           state.connectors_binding_cursor <-
             (if key = Some "J" then
                Masc_tui_scroll.cursor_down ~count
                  state.connectors_binding_cursor
              else
                Masc_tui_scroll.cursor_up ~count
                  state.connectors_binding_cursor)
       | Some "b"
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_info ->
           (match selected_keeper state, state.board_quarantine_requeue_inflight with
            | Some _, Some partition ->
                report_action state "system"
                  ("A Board requeue is still waiting for its answer: "
                   ^ Terminal_text.single_line partition)
            | None, _ -> ()
            | Some keeper, None ->
                (match
                   Masc_tui_fetched.view_for ~equal:String.equal
                     state.keeper_board_quarantines ~key:keeper.k_name
                 with
                 | Masc_tui_fetched.Ready quarantines ->
                     (match Masc_tui_board_quarantine.oldest_waiting quarantines with
                      | Some item ->
                          Masc_tui_surface_requests.Keeper_surface_requests.launch_board_quarantine_requeue state
                            ~mailbox:async_messages ~keeper_name:keeper.k_name item
                      | None ->
                          report_action state "system"
                            "No blocked Board partition to requeue")
                 | Masc_tui_fetched.Absent | Masc_tui_fetched.Loading
                 | Masc_tui_fetched.Stale _ | Masc_tui_fetched.Failed _ ->
                     report_action state "error"
                       "Board partitions are not read yet; nothing requeued"))
       | Some "B"
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_info ->
           (match selected_keeper state, state.board_quarantine_requeue_inflight with
            | Some _, Some partition ->
                report_action state "system"
                  ("A Board requeue is still waiting for its answer: "
                   ^ Terminal_text.single_line partition)
            | None, _ -> ()
            | Some keeper, None ->
                (match
                   Masc_tui_board_quarantine.decide_bulk_requeue
                     (Masc_tui_fetched.view_for ~equal:String.equal
                        state.keeper_board_quarantines ~key:keeper.k_name)
                 with
                 | Masc_tui_board_quarantine.Bulk_requeue items ->
                     Masc_tui_surface_requests.Keeper_surface_requests.launch_board_quarantines_bulk_requeue state
                       ~mailbox:async_messages ~keeper_name:keeper.k_name items
                 | Masc_tui_board_quarantine.Bulk_nothing_waiting ->
                     report_action state "system"
                       "No blocked Board partitions to requeue"
                 | Masc_tui_board_quarantine.Bulk_not_read ->
                     report_action state "error"
                       "Board partitions are not read yet; nothing requeued"))
       | Some "L"
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_github ->
           Masc_tui_github_ui.start_login state ~login:(fun keeper -> Masc_tui_github_requests.launch_login state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state async_messages) ~fork:(Masc_tui_transport.Workspace_admission.fork_job state ~mailbox:async_messages) ~check:(Masc_tui_transport.Workspace_admission.capture_admission state ~mailbox:async_messages) keeper)
       | Some digit
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_github
              && String.length digit = 1
              && digit.[0] >= '1'
              && digit.[0] <= '9' ->
           Masc_tui_github_ui.toggle_scope state ~index:(Char.code digit.[0] - Char.code '1')
       | Some ("P" | "p")
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_github ->
           Masc_tui_github_ui.open_token state
       (* The number the Identity tab printed. Both sides index
          [identity_connectable], so what the screen numbered and what this
          starts are the same list. *)
       | Some digit
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_identity
              && String.length digit = 1
              && digit.[0] >= '1'
              && digit.[0] <= '9' ->
           Masc_tui_identity_input.start_numbered state
             ~login:(fun ~keeper_name ~provider_id ~label -> Masc_tui_identity_requests.launch_login state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state async_messages) ~fork:(Masc_tui_transport.Workspace_admission.fork_job state ~mailbox:async_messages) ~keeper_name ~provider_id ~label)
             ~index:(Char.code digit.[0] - Char.code '1')
       | Some ("R" | "r")
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_identity ->
           Masc_tui_identity_input.refresh_attached state
             ~refresh:(fun ~keeper_name ~provider_ids -> Masc_tui_identity_requests.launch_refresh state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state async_messages) ~fork:(Masc_tui_transport.Workspace_admission.fork_job state ~mailbox:async_messages) ~keeper_name ~provider_ids)
       | Some "T" when state.view = Approvals && not (modal_owns_keys state)
           && Option.is_none (text_input_target state ~compact_viewport) ->
           Masc_tui_chat_dispatch.Task_dispatch.cancel_task_inspection_read state;
           if open_ask_task_inspection state then Masc_tui_chat_dispatch.Task_dispatch.launch_original_task_read state ~mailbox:async_messages
           else report_action state "system" "The last answered Ask has no confirmed original Task link to inspect";
           Render_schedule.request render_schedule Render_schedule.Force
       | Some "R" when state.view = Approvals ->
           (match
              Approval_authority.retry_target ~presented:(!presented).approval
                ~current:(Masc_tui_approvals_model.approval_items state)
            with
            | Approval_authority.Listed (Approval_authority.Retry_gate pending) ->
                Masc_tui_work_requests.Approval_gate_requests.launch_gate_auto_judge_retry state ~mailbox:async_messages pending
            | Approval_authority.Listed Approval_authority.Not_retryable ->
                report_action state "system"
                  (ui_text state
                     ~ko:"Auto Judge 다시 시도는 Gate 행에서만 됨 · 이 행은 y/n 으로 결정"
                     ~en:"R retries Auto Judge on Gate rows only; decide this row with y/n")
            | Approval_authority.No_row_presented ->
                report_action state "system"
                  (ui_text state ~ko:"화면에 다시 시도할 행 없음"
                     ~en:"No approval row on screen to retry")
            | Approval_authority.Presented_row_gone ->
                report_action state "system"
                  "Approval list changed; review the updated row before retrying")
       | Some "\r" when state.view = Resources ->
           Masc_tui_resources_updates.open_selected state
             ~read:(launch_resources_read state ~mailbox:async_messages)
       | Some "J" when state.view = Resources ->
           move_resource_document state (Masc_tui_scroll.Position.By 1)
       | Some "K" when state.view = Resources ->
           move_resource_document state (Masc_tui_scroll.Position.By (-1))
       | Some "H" when state.view=Planning && state.planning_mode=Planning_list
           && Option.is_some state.task_detail_id ->
           Option.iter (Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size ~older:true state ~mailbox:async_messages) state.task_detail_id
       | Some "H" when state.view=Tools && state.tools_pane=Tools_async
           && state.tools_async_detail_open && Option.is_some state.tools_async_task_source ->
           Masc_tui_work_requests.Tools_task_requests.launch_tools_async_task_history ~terminal_size:Masc_tui_render_prim.get_terminal_size ~older:true state ~mailbox:async_messages
       | Some ("o" | "O") when state.view = Tools && state.tools_pane = Tools_async ->
           Masc_tui_editor_forms.Skill_prompt_forms.handle_async_request_lookup state ~mailbox:async_messages ~terminal_session
       | Some ("t" | "T") when state.view = Tools && state.tools_pane = Tools_async && state.tools_async_detail_open ->
           Masc_tui_work_requests.Tools_task_requests.open_tools_async_source_task ~terminal_size:Masc_tui_render_prim.get_terminal_size state ~mailbox:async_messages
       | Some "\x0f" when state.view = Tools && state.tools_pane <> Tools_async -> handle_skill_diagram ()
       (* The diagnostics heading is not a row the cursor stops on, so the
          chat's fold key folds it. Back to the top, where the heading is,
          so the rows that appear or go are in view. *)
       | Some k
         when String.equal k Masc_tui_keys.expand_turn_key
              && state.view = Tools && state.tools_pane = Tools_surface ->
           state.tools_diagnostics_folded <- not state.tools_diagnostics_folded;
           tools_task_user_scroll state 0
       | Some "Y" when state.view = Tools && state.tools_pane = Tools_surface ->
           (match Masc_tui_render_tools.tools_diagnostics_copy_text state with
            | None ->
                report_action state "system"
                  (ui_text state ~ko:"복사할 진단이 없습니다" ~en:"No diagnostics to copy")
            | Some text ->
                let outcome = copy_reference render_schedule text in
                report_action state "system"
                  (ui_text state
                     ~ko:("진단을 " ^ Masc_tui_clipboard.copy_outcome_text_korean outcome)
                     ~en:("Diagnostics " ^ Masc_tui_clipboard.copy_outcome_text outcome)))
       | Some "f" when state.view = Tools && state.tools_pane <> Tools_async ->
           let profiles = tools_skill_profiles state in
           let compositions = List.mapi (fun index profile -> index, profile) profiles
             |> List.filter (fun (_, profile) -> match profile.Masc.Tui_decode_tools.esp_io with
                  | Model_orchestrated -> false | Composition_io _ -> true) in
           let next = List.find_opt (fun (index, _) -> index > state.tools_skill_cursor) compositions in
           (match (match next with Some _ -> next | None -> List.nth_opt compositions 0) with
            | None -> report_action state "system" "No Composition Skill is available on this Keeper surface"
            | Some (index, _) ->
                state.tools_skill_cursor <- index;
                Masc_tui_list_moves.show_tools_pane state Tools_surface;
                handle_skill_evidence ();
                (* f is for the chosen Composition's performance, so it
                   reads the page where that card is. Esc goes back to the
                   list, on the Composition. *)
                Masc_tui_list_moves.read_skill_page state;
                tools_task_user_scroll state (tools_performance_card_top state))
       | Some k
         when String.equal k Masc_tui_volume_gc.key
              && state.view = Tools && state.tools_pane = Tools_catalog Tools_catalog_list ->
           let catalog_scroll = tools_task_render_scroll state in
           (* Opening cannot reuse an arm retained from a different view.
              Disarming leaves an actual in-flight request alone. *)
           state.volume_gc <- Masc_tui_volume_gc.disarm state.volume_gc;
           enter_tools_pane state
             (Tools_catalog (Tools_catalog_volumes {catalog_scroll}));
           Masc_tui_surface_requests.Connector_volume_requests.press_tools_volume_gc state ~mailbox:async_messages
       | Some "d" when state.view = Tools && state.tools_pane <> Tools_async ->
           Masc_tui_editor_forms.Skill_prompt_forms.handle_skill_delete state ~mailbox:async_messages
       | Some "\r" when state.view = Tools && state.tools_pane = Tools_async ->
           if Option.is_some state.tools_async_selection then begin
             state.tools_async_detail_open <- true;
             tools_task_user_scroll state 0;
             Masc_tui_work_requests.Tools_task_requests.launch_tools_async_detail state ~mailbox:async_messages
           end
       | Some "\r" when state.view = Tools ->
           (* Enter loads the selected revision's evidence as before, and
              again (the latest) while the page is read. On Available it
              also turns the move keys from the list to that page. *)
           handle_skill_evidence ();
           Masc_tui_list_moves.read_skill_page state
       | Some ("\r" | "\n" | "enter")
         when state.view = Config && state.config_pane = Config_params ->
           Masc_tui_editor_forms.Runtime_config_forms.handle_runtime_param_edit_open state ~advanced:false
       | Some ("\r" | "\n" | "enter")
         when state.view = Config && state.config_pane = Config_themes ->
           (* Applying draws it: the palette's generation bumps and every
              cached colour rebuilds, which is the same road a theme switch
              reported by the terminal takes. Storing it is what makes the
              pick still be there on the next start -- boot reads the same
              key back. A name no bundled scheme answers to leaves the screen
              alone rather than quietly dropping to colours nobody picked,
              and nothing is stored for it either.

              All three spellings, because a terminal sends CR, a Kitty-
              protocol one sends the name, and a footer that says "Enter" has
              to mean whichever one arrived. *)
           let entries = filtered_theme_entries state in
           (match List.nth_opt entries state.theme_cursor with
            | None -> ()
            | Some entry ->
              if Masc_tui_theme_choice.apply entry.Masc_tui_theme_choice.name
              then begin
                state.theme_choice <- Some entry.Masc_tui_theme_choice.name;
                (* Committed: there is nothing to go back to any more. *)
                state.theme_before_preview <- None;
                (* The ink changed; the page has to change with it. A light
                   scheme picks dark text because it expects a light page, so
                   leaving the terminal's own background is what made "light
                   theme is still black". *)
                sync_theme_page state;
                store_theme_choice (Some entry.Masc_tui_theme_choice.name)
              end)
       | Some "c" when state.view = Tools -> Masc_tui_editor_forms.Skill_prompt_forms.handle_skill_create state ~mailbox:async_messages ~terminal_session ~composition:false
       | Some "C" when state.view = Tools -> Masc_tui_editor_forms.Skill_prompt_forms.handle_skill_create state ~mailbox:async_messages ~terminal_session ~composition:true
       | Some "c"
         when state.view = Memory && state.memory_page = Memory_facts
              && Option.is_some state.memory_facts_keeper ->
           (* Cycle the category filter: All, then each category the loaded
              store holds, in sorted order. *)
           enter_memory_category state
             (Masc_tui_types.next_memory_category state.memory_facts_category
                (Masc_tui_types.memory_fact_categories state))
       | Some "C"
         when state.view = Memory && state.memory_page = Memory_facts
              && Option.is_some state.memory_facts_keeper ->
           enter_memory_category state
             (Masc_tui_types.prev_memory_category state.memory_facts_category
                (Masc_tui_types.memory_fact_categories state))
       | Some ("s" | "S")
         when state.view = Memory && state.memory_page = Memory_facts
              && Option.is_some state.memory_facts_keeper ->
           state.memory_facts_sort <-
             Masc_tui_types.next_memory_sort state.memory_facts_sort;
           state.memory_facts_cursor <- 0;
           state.memory_facts_scroll <- 0
       | Some ("s" | "S")
         when state.view = Memory
              && Option.is_none state.memory_facts_keeper ->
           state.memory_overview_sort <-
             Masc_tui_types.next_memory_overview_sort state.memory_overview_sort;
           state.memory_health_cursor <- 0;
           state.memory_health_scroll <- 0
       | Some ("u" | "U")
         when state.view = Memory && Option.is_none state.memory_facts_keeper ->
           state.memory_unit <- Masc_tui_memory_usage.next_unit state.memory_unit
       | Some ("d" | "D")
         when state.view = Memory && state.memory_page = Memory_facts && Option.is_some state.memory_facts_keeper ->
           toggle_memory_facts_categories ~cols:terminal_columns state
       | Some ("d" | "D")
         when state.view = Lanes && (match state.lanes_mode, state.lane_run_detail with
           | Lanes_run_detail (_, _), Some {Tui_decode.lrd_librarian_preflight=Some _;_} -> true
           | (Lanes_run_detail (_, _), Some { lrd_librarian_preflight = None;_})
           | (Lanes_run_detail (_, _), None)
           | ((Lanes_overview | (Lanes_run_list _ | (Lanes_measurement_detail _ | Lanes_inventory_detail _))), _) -> false) ->
           state.lane_run_preflight_details <- not state.lane_run_preflight_details;
           state.lane_run_detail_scroll <- 0
       | Some ("d" | "D")
         when state.view = Memory
              && Option.is_none state.memory_facts_keeper ->
           state.memory_overview_detail <- not state.memory_overview_detail
       | Some ("a" | "A") when state.view = Memory ->
           Masc_tui_surface_requests.Memory_repository_requests.open_all_fleet_memory state ~mailbox:async_messages
       (* Resources and Tools hang off Config the way Connectors hangs off
          Runtime: not on the Tab ring, one key from their parent. Both
          cases, like every other hang-off hop (c|C, f|F, p|P), and no
          param-edit guard: while a field is open, the capture arm earlier
          in this match owns every key before these can see one. *)
       | Some ("s" | "S") when state.view = Config ->
           goto_surface state ~mailbox:async_messages Resources
       | Some "9" when state.view = Config ->
           goto_surface state ~mailbox:async_messages Runtime
       | Some ("t" | "T") when state.view = Config ->
           goto_surface state ~mailbox:async_messages Tools
       | Some "A" when state.view = Config ->
           goto_surface state ~mailbox:async_messages Acting
       | Some "L" when state.view = Config ->
           goto_surface state ~mailbox:async_messages System_logs
       (* System logs hang off Activity the same way: one key from the
          parent, off the Tab ring. *)
       | Some ("esc" | "left") when state.view = Memory && state.memory_fact_detail_open ->
           state.memory_fact_detail_open <- false;
           state.memory_fact_detail_scroll <- 0
       | Some ("j" | "down" | "k" | "up" | "pageup" | "pagedown" | "g" | "G" as move)
         when state.view = Memory && state.memory_fact_detail_open ->
           let terminal_rows, _ = get_terminal_size () in
           let page = max 1 (surface_body_rows state ~terminal_rows) in
           (match move with
            | "g" -> state.memory_fact_detail_scroll <- 0
            | "G" ->
                (* Rendering clamps this to the claim's final wrapped page, the
                   way the acting reading clamps its own. *)
                state.memory_fact_detail_scroll <- max_int
            | _ ->
                let delta = match move with
                  | "j" | "down" -> 1 | "k" | "up" -> -1
                  | "pageup" -> -page | _ -> page in
                state.memory_fact_detail_scroll <-
                  Masc_tui_scroll.step_uncounted ~delta state.memory_fact_detail_scroll)
       | Some ("\r" | "\n" | "enter")
         when state.view = Memory && state.memory_page = Memory_facts && Option.is_some state.memory_facts_keeper ->
           (* A browser with no fact has no reading to open. *)
           if not (List.is_empty (Masc_tui_types.memory_fact_rows state)) then begin
             state.memory_fact_detail_open <- true;
             state.memory_fact_detail_scroll <- 0
           end
       | Some ("esc" | "left")
         when state.view = Acting && Option.is_some state.acting_detail ->
           state.acting_detail <- None;
           state.acting_detail_scroll <- 0
       | Some ("j" | "down" | "k" | "up" | "pageup" | "pagedown" | "g" | "G" as move)
         when state.view = Acting && Option.is_some state.acting_detail ->
           let terminal_rows, _ = get_terminal_size () in
           let page = Masc_tui_render_activity.acting_evidence_page_rows state ~terminal_rows in
           (match move with
            | "g" -> state.acting_detail_scroll <- 0
            | "G" ->
                (* Rendering clamps this to the final wrapped evidence page. *)
                state.acting_detail_scroll <- max_int
            | _ ->
                let delta = match move with
                  | "j" | "down" -> 1 | "k" | "up" -> -1
                  | "pageup" -> -page | _ -> page in
                (* G above leaves the sentinel here, and a frame that drew no
                   evidence pane reports no clamp to replace it, so a step
                   down in between would carry it into [+]. *)
                state.acting_detail_scroll <-
                  Masc_tui_scroll.step_uncounted ~delta state.acting_detail_scroll)
       (* The flat event list is a row list ([list_on_screen]): its page is
          the rows the list drew. *)
       | Some ("j" | "down" | "k" | "up" | "pageup" | "pagedown" as move)
         when state.view = Acting && state.acting_filter <> Masc_tui_acting.Turns ->
           Option.iter (move_list state) (Masc_tui_scroll.move_of_key move)
       | Some ("\r" | "\n" | "enter") when state.view = Acting ->
           (match state.acting_detail, state.acting_filter with
            | Some _, _ -> ()
            | None, Masc_tui_acting.Turns ->
                report_action state "system" "Turns are aggregates; press f for Actions, then Enter for exact event evidence"
            | None, (Actions | Everything) ->
                state.acting_detail <- selected_acting_entry state;
                state.acting_detail_scroll <- 0)
       | Some "e" when state.view = Acting || state.view = System_logs ->
           goto_surface state ~mailbox:async_messages Acting
       | Some ("l" | "L") when state.view = Acting ->
           goto_surface state ~mailbox:async_messages System_logs
       | Some key when state.keeper_navigation_open ->
           (match key with
            | "right" | "esc" | "\t" | "tab" ->
                state.keeper_navigation_open <- false;
                state.keeper_message_focus <- Right_pane
            | "down" | "j" ->
                state.keeper_cursor <- Masc_tui_scroll.cursor_down
                  ~count:(List.length state.keepers) state.keeper_cursor
            | "up" | "k" ->
                state.keeper_cursor <- Masc_tui_scroll.cursor_up
                  ~count:(List.length state.keepers) state.keeper_cursor
            | "\r" | "\n" | "enter" ->
                (match selected_keeper state with
                 | None -> ()
                 | Some keeper ->
                     let return_to = if state.view = Overview then
                       Keeper_chat_return_home else state.msg_return in
                     Masc_tui_chat_input.Message_draft_recall.open_message_for_keeper ~return_to state keeper.k_name
                       ~drain_queue:(fun () -> Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state
                         ~base_path ~mailbox:async_messages);
                     set_msg_scroll state 0;
                     state.view <- Keepers Keeper_message;
                     launch_keeper_history_load state ~mailbox:async_messages
                       ~keeper_name:keeper.k_name)
            (* The row this overlay draws names the door on Overview, and
               the chat's minimal rows name it too -- while navigation is
               open this arm owns the key, so both rows need it to answer
               here rather than in the surface under them. *)
            | "?" ->
                state.help_open <- true;
                state.help_scroll <- 0
            | _ -> ())
       | Some "left"
         when state.view = Overview
              || (message_mode
                  && state.keeper_message_focus = Right_pane
                  && Option.is_none state.voice_capture
                  && Masc_tui_message_input.can_leave_left state.msg_input) ->
           state.acting_pane_cursor <- None;
           state.keeper_navigation_open <- true;
           state.keeper_message_focus <- Left_pane
       | Some ("j" | "down" | "k" | "up" as key) when state.view = Overview ->
           move_list state
             (if key = "k" || key = "up" then Masc_tui_scroll.Line_up else Masc_tui_scroll.Line_down)
       | Some ("p" | "P") when state.view = Overview ->
           Masc_tui_home.open_approvals state
             ~navigate:(goto_surface ~from_reference:true state ~mailbox:async_messages)
       | Some ("g" | "G") when state.view = Overview ->
           (* The door to the operator quiz installation's Results. [g] for
              the same reason Approvals answers [g]: the door to one
              installation's Results. [q] stays the quit key. *)
           open_installation_results state ~mailbox:async_messages "operator-quiz"
       | Some ("\r" | "\n" | "enter") when state.view = Overview ->
           (match Masc_tui_home.home_selected_action (Masc_tui_home.prepare state) with
            | None -> report_action state "system" "Selection changed; choose again"
            | Some action ->
              state.home_selected <- Some action;
              (match action with
            | Home_approvals ->
                Masc_tui_home.open_approvals state
                  ~navigate:(goto_surface ~from_reference:true state ~mailbox:async_messages)
            | Home_request request ->
                let navigate destination =
                  goto_surface ~from_reference:true state ~mailbox:async_messages destination;
                  state.followed_from <- Some (Overview, None);
                  state.home_opened_request <- Some request
                in
                (match request with
                 | Home_held_call _ | Home_gate_request _ | Home_operator_request _ ->
                     (match List.find_index
                              (fun row ->
                                 equal_home_request (Masc_tui_home.home_request_of_approval row) request)
                              (Masc_tui_approvals_model.approval_items state) with
                      | None -> report_action state "system" "Request changed; choose again"
                      | Some cursor ->
                          navigate Approvals;
                          state.approval_cursor <- cursor;
                          state.approval_detail_open <- true;
                          state.approval_detail_scroll <- 0)
                 | Home_question ask ->
                     (match List.find_index
                              (fun row -> Masc.Tui_decode_asks.(equal_ask_key ask (ask_key row)))
                              (open_ask_rows state) with
                      | None -> report_action state "system" "Question changed; choose again"
                      | Some cursor ->
                          navigate Approvals;
                          state.ask_cursor <- Ask.On cursor;
                          Masc_tui_operator_actions.Ask_actions.enter_ask_answering state)
                 | Home_goal_confirmation goal_id ->
                     (match state.planning_filter with
                      | Planning_filter_all | Planning_filter_active -> ()
                      | Planning_filter_completed | Planning_filter_dropped ->
                          state.planning_filter <- Planning_filter_active);
                     navigate Planning;
                     state.task_focus <- Masc_tui_overview_tasks.No_task_focus;
                     state.planning_mode <- Planning_detail goal_id;
                     Masc_tui_home.reconcile_home_request_detail state;
                     state.planning_scroll <- Planning_scroll_offset 0;
                     state.goal_timeline <- Masc_tui_fetched.clear state.goal_timeline;
                     Masc_tui_work_requests.Tools_task_requests.launch_goal_timeline_load state ~mailbox:async_messages goal_id)
            | Home_agenda ->
                state.agenda_open <- true;
                state.agenda_scroll <- 0;
                state.agenda_navigation <- Agenda_read_rows;
                state.agenda_selected <- Masc_tui_agenda.Nowhere
            | Home_resume keeper_name ->
                Masc_tui_chat_input.Message_draft_recall.open_message_for_keeper ~return_to:Keeper_chat_return_home state
                  keeper_name ~drain_queue:(fun () ->
                    Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox:async_messages);
                state.view <- Keepers Keeper_message;
                launch_keeper_history_load state ~mailbox:async_messages ~keeper_name
            | Home_read_last keeper_name ->
                Masc_tui_chat_input.Message_draft_recall.open_message_for_keeper ~remember_home_chat:false
                  ~return_to:Keeper_chat_return_home state keeper_name
                  ~drain_queue:(fun () -> ());
                state.view <- Keepers Keeper_message;
                launch_keeper_history_load state ~mailbox:async_messages ~keeper_name
            | Home_choose_keeper ->
                goto_surface state ~mailbox:async_messages (Keepers Keeper_list)
            | Home_operator_action (authority,_,item) ->
                let original () = open_detail_reading state
                    (Masc_tui_render.operator_action_reading state item) in
                let terminal_rows, _ = get_terminal_size () in
                let body = Masc_tui_home.home_body (Masc_tui_home.prepare state)
                    ~scroll:state.home_decision_scroll
                    ~budget:(Masc_tui_render_prim.surface_chrome_budget
                      ~frame:Masc_tui_render_prim.Chrome_screen state ~terminal_rows) in
                if not (List.exists (fun (current,_) -> equal_home_action action current) body.hb_rows) then
                  report_action state "info" "Selected action is not visible; enlarge the window"
                else if authority <> state.workspace_authority || not (server_authority_ready state) then original ()
                else
                  (match item.Masc.Operator_action_reason.cause with
                   | Memory_attention _ ->
                       (match Masc_tui_render_memory.memory_action_reading
                                ~cols:terminal_columns state ~action:item with
                        | Some reading -> open_detail_reading state reading
                        | None ->
                            original ();
                            report_action state "info" "Memory observation unavailable; original action retained")
                   | Shutdown_fenced_backlog {keepers=Some [(keeper,_)]; complete=true;_} ->
                       Masc_tui_collab_queue.Keeper_queue.open_keeper_queue_panel state ~mailbox:async_messages ~keeper_name:keeper
                   | Shutdown_fenced_backlog _ | Other_reported -> original ())
            | Home_create_keeper -> Masc_tui_editor_forms.Workspace_review_forms.handle_keeper_create ~return_to:Keeper_chat_return_home state ~mailbox:async_messages ~terminal_session ~show_keeper_list:(fun () -> goto_surface state ~mailbox:async_messages (Keepers Keeper_list))))
        | Some "s" when state.view = Overview ->
            (match open_music () with
             | Ok () -> ()
             | Error detail -> report_action state "error" detail)
        | Some ("m" | "M") when state.view = Overview ->
            goto_surface state ~mailbox:async_messages Metrics
        | Some ("1" | "2" | "3" | "4" as digit) when state.view = Overview ->
            let index = int_of_string digit in
            if List.mem index state.overview_collapsed_cards then
              state.overview_collapsed_cards <-
                List.filter (fun n -> n <> index) state.overview_collapsed_cards
            else
              let _, full_cols = get_terminal_size () in
              let inner_width = Masc_tui_ansi.framed_inner_width full_cols in
              if
                Masc_tui_card.columns_that_fit ~inner_width ~gap:2
                  ~min_card_width:44 ~max_columns:2 >= 2
              then
                state.overview_collapsed_cards <- index :: state.overview_collapsed_cards
        | Some "f" when state.view = Metrics && not state.usage_telemetry_open ->
            state.palette_open <- true;
            state.palette_mode <- Palette_jump;
            state.palette_query <- "usage account / ";
            state.palette_cursor <- 0
        | Some "a" when state.view = Metrics && not state.usage_telemetry_open ->
            state.usage_scope_id <- None;
            reset_metrics_scroll state
        | Some "x" when state.view = Metrics && not state.usage_telemetry_open ->
            state.usage_show_limit_exhausted <- not state.usage_show_limit_exhausted;
            reset_metrics_scroll state
        | Some "v" when state.view = Metrics && not state.usage_telemetry_open ->
            state.usage_section <- next_usage_section state.usage_section;
            reset_metrics_scroll state
        | Some "V" when state.view = Metrics && not state.usage_telemetry_open ->
            state.usage_section <- previous_usage_section state.usage_section;
            reset_metrics_scroll state
        | Some ("p" | "P") when state.view = Metrics ->
            state.usage_telemetry_open <- not state.usage_telemetry_open;
            reset_metrics_scroll state
        | Some ("1" | "2" | "3") as section
          when state.view = Metrics && state.usage_telemetry_open ->
            enter_metrics_section state
              (match section with
               | Some "1" -> Section_fleet
               | Some "2" -> Section_resources
               | Some "3" | None | Some _ -> Section_tools)
        | Some ("1" | "2" | "3" | "4") as section
          when state.view = Metrics && not state.usage_telemetry_open ->
            state.usage_section <-
              (match section with
               | Some "1" -> Usage_plan
               | Some "2" -> Usage_trend
               | Some "3" -> Usage_keepers
               | Some "4" | None | Some _ -> Usage_calls);
            reset_metrics_scroll state
        | Some ("w" | "W")
          when state.view = Metrics && not state.usage_telemetry_open ->
            let needs = cycle_usage_history_window state in
            (* The operator's key: the window it picks is read at once, during
               a [/health] wait too (RFC tui-one-screen-grammar §2). *)
            start_http_scoped_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
              ~port:state.port ~ask:Masc_tui_refresh_pace.Operator_change
              ~refresh_inflight:http_scoped_refresh_inflight
              ~full_refresh_inflight:http_refresh_inflight ~scoped_refresh_followup
              ~mailbox:async_messages ~needs
       (* In chat, printable keys normally belong to the draft. Keep [?] as
          the documented global Help key when the draft is empty; once a
          sentence has started it remains an ordinary question mark. This
          makes shortcuts and slash commands discoverable without discarding
          text the operator is already writing. *)
       | Some "?" when message_mode && Masc_tui_message_input.length state.msg_input = 0 ->
           state.help_open <- true;
           state.help_scroll <- 0
       | Some k when message_mode ->
           (* Ctrl-R/Ctrl-D/Ctrl-F/Ctrl-N shape what the transcript draws,
              not what the composer holds, so a viewport too small for the
              composer still owes them a working transcript. Named as one set
              because they were admitted one by one and forgotten one by one:
              Ctrl-F never made this list, then Ctrl-N repeated the miss. *)
           let display_toggle_key =
             String.length k = 1
             &&
             let byte = Char.code k.[0] in
             byte = 18 || byte = 4 || byte = 6 || byte = 14
           in
           let switch_key = String.length k = 1 && Char.code k.[0] = 7 in
           let queue_management_key =
             String.length k = 1
             && (let c = Char.code k.[0] in
                 c = 11 || c = 16 || c = 17 || c = 20)
           in
           let scroll_recovery_key =
             String.equal k "down" || String.equal k "pagedown"
             || String.equal k "end"
           in
           if
             Masc_tui_chat_input.Message_keymap.keeper_message_input_supported ~terminal_size:Masc_tui_render_prim.get_terminal_size state
             || String.equal k "esc"
             (* Q reaches the composer handler for the same reason Esc does:
                the quiet leave must not disappear exactly when the terminal
                is too small to draw the composer -- a transcript-only
                viewport is when an operator most needs to step away from a
                running turn. Hidden drafts are preserved, never edited. *)
             || (String.equal k "Q" && not (Masc_tui_chat_input.Message_keymap.keeper_message_input_supported ~terminal_size:Masc_tui_render_prim.get_terminal_size state))
             || display_toggle_key
             || switch_key
             || queue_management_key
             || scroll_recovery_key
           then
             if switch_key then begin
               Masc_tui_chat_dispatch.Chat_journals.switch_to_next_keeper_message state
                 ~drain_queue:(fun () ->
                   Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path
                     ~mailbox:async_messages)
                 ~load_history:(fun keeper_name ->
                   launch_keeper_history_load state ~mailbox:async_messages ~keeper_name)
             end else
               let (_handled : bool) =
                 Masc_tui_chat_input.Message_keymap.handle_message_key ~terminal_size:Masc_tui_render_prim.get_terminal_size ~wheel_notch_rows state
                   ~submit_message:
                     (send_operator_text state ~base_path
                        ~mailbox:async_messages)
                   ~load_older:(fun ~cursor ->
                     match state.msg_target_keeper_name with
                     | Some keeper_name ->
                         launch_keeper_older_page state
                           ~mailbox:async_messages ~keeper_name ~cursor
                     | None -> ())
                   ~paste_image:(fun () -> paste_clipboard_image state)
                   ~open_named_image:(fun () -> open_named_image state ~mailbox:async_messages)
                   ~inspect_context:(fun () ->
                     match state.msg_target_keeper_name with
                     | Some keeper_name ->
                         Masc_tui_chat_dispatch.Chat_journals.open_context_inspector state ~mailbox:async_messages
                           ~keeper_name
                     | None -> ())
                   ~inspect_queue:(fun () ->
                     match state.msg_target_keeper_name with
                     | Some keeper_name ->
                         Masc_tui_collab_queue.Keeper_queue.open_keeper_queue_panel state ~mailbox:async_messages ~keeper_name
                     | None -> ())
                   ~load_preparation:(fun () -> Masc_tui_chat_dispatch.Chat_journals.launch_selected_preparation_operation_read state ~mailbox:async_messages)
                   ~load_tool_changes:(fun () ->
                     match state.msg_target_keeper_name with
                     | Some keeper_name ->
                         launch_keeper_chat_tool_details_load ~force:true state
                           ~mailbox:async_messages ~keeper_name
                     | None -> ())
                   ~drain_queue:(fun () ->
                     Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path
                       ~mailbox:async_messages)
                   ~start_voice:(fun () ->
                     match state.msg_target_keeper_name with
                     | Some keeper when state.voice_capture = None ->
                         Masc_tui_operator_actions.Voice_actions.launch_voice_capture state ~mailbox:async_messages ~keeper
                     (* The same toggle the composer row carries. *)
                     | Some _ ->
                         request_voice_stop state Masc.Voice_bridge.Keep_what_was_heard;
                         set_last_action state (Some ("voice: stopping", Unix.gettimeofday ()))
                     | None -> ())
                   ~toggle_voice_continuous:(fun () ->
                     match state.voice_continuous, state.msg_target_keeper_name with
                     | Some _, _ ->
                         state.voice_continuous <- None;
                         state.voice_floor <- None;
                         set_last_action state (Some ("voice: continuous off", Unix.gettimeofday ()))
                     | None, Some _ when Option.is_some state.voice_capture ->
                         let notice =
                           if state.voice_capture_withdrawn
                           then "voice: discarding previous capture"
                           else "voice: recording in progress" in
                         set_last_action state (Some (notice, Unix.gettimeofday ()))
                     | None, Some keeper ->
                         state.voice_continuous <- Some keeper;
                         state.voice_floor <- None;
                         set_last_action state (Some ("voice: continuous on", Unix.gettimeofday ()));
                         if state.voice_capture = None
                         then
                           Masc_tui_operator_actions.Voice_actions.launch_voice_capture ~calibrate:true state ~mailbox:async_messages ~keeper
                     | None, None -> ())
                   k
               in
               ()
       | Some k
         when (match text_input_target state ~compact_viewport with
               | Some (Text_board_draft | Text_board_attach_path) -> true
               | Some
                   (Text_collab_form | Text_account_login
                   | Text_ask_answer | Text_fusion_launch | Text_preset_name | Text_resource_save
                   | Text_runtime_lane_name | Text_runtime_param
                   | Text_runtime_model_form | Text_runtime_account_form | Text_memory_recall_form
                   | Text_typesafeai_exclusion_form
                   | Text_voice_wizard | Text_palette | Text_row_search
                   | Text_runtime_picker_filter | Text_keeper_runtime_picker_filter | Text_skill_source_filter
                   | Text_identity_app_form | Text_identity_filter
                   | Text_goal_drop_reason | Text_github_token)
               | None -> false) ->
           (* Same shape as the chat pane: while a draft is being written,
              printable keys belong to the draft. A key the handler declines
              (Tab) keeps its global meaning, so the cycle works mid-compose
              as this comment always claimed. *)
           let handled =
             Masc_tui_operator_actions.Board_compose_actions.handle_board_compose_key state ~mailbox:async_messages
               ~restore:(fun () -> Masc_tui_shell.Terminal_session.hand_off terminal_session) ~reenter:(fun () -> Masc_tui_shell.Terminal_session.take_back terminal_session) k
           in
           if not handled then
             (match k with
              | "\t" | "shift-tab" ->
                  cycle_surface state ~mailbox:async_messages
                    ~backwards:(k = "shift-tab")
              | _ -> ())
       | Some "?" ->
           state.help_open <- true;
           state.help_scroll <- 0
      | Some "&" -> Masc_tui_collab_queue.Collab_play.open_collab state ~mailbox:async_messages
       | Some ";" ->
           state.agenda_open <- true;
           state.agenda_scroll <- 0;
           state.agenda_navigation <- Agenda_read_rows;
           (* Start with the scheduled rows. A target is selected explicitly
              with j/k, and Enter opens only a marked row in the window. *)
           state.agenda_selected <- Masc_tui_agenda.Nowhere
       | Some ("d" | "i" as key)
         when state.view = Lanes && state.lanes_mode = Lanes_overview
              && Option.is_none state.slot_editor && Option.is_none state.runtime_lane_pick ->
           let target = if key = "i" then None else
             Option.map (fun (row : Masc.Tui_decode_lane_inventory.row) -> row.id)
               (selected_inventory_lane state) in
           state.lanes_mode <- Lanes_inventory_detail target;
           state.lane_run_detail_scroll <- 0
       | Some "i" when state.view = Verification
           && Option.is_some state.verification_detail_request_id ->
           state.verification_evidence_index_open <- not state.verification_evidence_index_open;
           state.verification_detail_scroll <- 0
       | Some (("e" | "E") as key) when state.view = Verification
           && Option.is_some state.verification_detail_request_id ->
           Masc_tui_work_actions.Verification_actions.step_verification_evidence state (if key = "e" then 1 else -1)
       | Some (("o" | "s") as key) when state.view = Verification
           && Option.is_some state.verification_detail_request_id ->
           Masc_tui_work_actions.Verification_actions.export_verification_evidence state ~mailbox:async_messages ~open_file:(key = "o")
       | Some "i" when state.view = Overview ->
           goto_surface state ~mailbox:async_messages (Keepers Keeper_list)
       | Some "i"
         when (not message_mode)
              && (match state.msg_target_keeper_name with
                 | Some _ -> true
                 | None ->
                   (* With no conversation open, the shown keeper is whoever
                      the list cursor names; that is who the composer
                      addresses. *)
                   Option.is_some (selected_keeper state))
              && not (state.view = Config && state.config_pane = Config_prompts) ->
           (* The sheet has promised [i] as "focus the composer" as long as
              it promised [r]. It opens the chat of the keeper the screen is
              about — the open conversation's keeper, else the one under the
              list cursor. The config pane keeps its own i. *)
           let target =
             match state.msg_target_keeper_name with
             | Some keeper_name -> Some keeper_name
             | None ->
               (match selected_keeper state with
                | Some keeper -> Some keeper.k_name
                | None -> None)
           in
           Option.iter
             (fun keeper_name ->
                Masc_tui_chat_dispatch.Chat_journals.enter_keeper_chat ~return_to:state.msg_return state
                       ~keeper_name ~drain_queue:(fun () ->
                         Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox:async_messages)
                       ~load_history:(fun keeper_name ->
                         launch_keeper_history_load state ~mailbox:async_messages ~keeper_name))
             target
       | Some "@" ->
           state.answering_open <- true;
           state.answering_scroll <- 0;
           (* Open with the cursor on the first actionable row (the badge's
              lead keeper), so Enter straight after @ goes where the badge
              was pointing. Prose-only sheets keep the cursor parked at 0. *)
           state.answering_cursor <-
             (match
                Masc_tui_answering.target_indexes
                  (Masc_tui_render_prim.answering_lines state)
              with
              | index :: _ -> index
              | [] -> 0)
       | Some "w" when state.view = Approvals ->
           state.palette_open <- true;
           state.palette_mode <- Palette_jump;
           state.palette_query <- "gate Workspace / ";
           state.palette_cursor <- 0
       | Some "H" when state.view = Board && state.board_mode <> Board_compose ->
           state.palette_open <- true;
           state.palette_mode <- Palette_jump;
           state.palette_query <- "hearth ";
           state.palette_cursor <- 0
       | Some "b" when state.view = Board ->
           (match state.board_mode with
            | Board_read post_id ->
                if Masc_tui_types.board_read_focus state ~cols:terminal_columns = Left_pane
                then begin
                  state.board_focus <- Right_pane;
                  state.board_comments_focused <- false
                end else
                  (match Board_detail.view_for state.board_detail ~post_id with
                   | Board_detail.Ready (_, _ :: _, _) ->
                       state.board_comments_focused <-
                         not state.board_comments_focused;
                       if state.board_comments_focused then
                         ignore
                           (Masc_tui_work_actions.Board_schedule_actions.select_board_comment state ~post_id : string option)
                   | Board_detail.Absent | Board_detail.Loading
                   | Board_detail.Ready (_, [], _) | Board_detail.Failed _ -> ())
            | Board_list | Board_compose -> ())
       | Some ":" ->
           state.palette_open <- true;
           state.palette_mode <- Masc_tui_types.Palette_jump;
           state.palette_query <- "";
           state.palette_cursor <- 0
       | Some "\025" ->
           let all_urls = Masc_tui_types.conversation_urls state in
           state.link_modal_links <- all_urls;
           (match all_urls with
            | first :: _ ->
                state.link_modal_open <- true;
                state.link_modal_url <- Some first;
                state.link_modal_scroll <- 0;
                state.link_modal_cursor <- 0
            | [] ->
                Masc_tui_collab_queue.Chat_notice.chat_notice state ~keeper_name:state.msg_target_keeper_name ~kind:Masc_tui_collab_queue.Chat_notice.Notice_reply
                  "No web links found in this conversation to preview.")
       | Some "\023"
         when state.view = Board
              && (match
                    board_read_layout ~cols:terminal_columns
                      ~wide:state.board_detail_wide
                  with
                  | Board_read_split -> true
                  | Board_read_wide | Board_read_one_pane -> false) ->
           (match state.board_mode with
            | Board_read _ -> (
                match state.board_focus with
                | Left_pane -> state.board_focus <- Right_pane
                | Right_pane ->
                    (* The Activity pane is the cycle's last stop when the
                       frame draws it; otherwise the cycle closes. *)
                    if not (acting_pane_drawn state && focus_acting_pane state)
                    then state.board_focus <- Left_pane)
            | Board_list ->
                if acting_pane_drawn state then focus_acting_pane_or_say_why state
            | Board_compose -> ())
       | Some "\023" when state.view = Board && state.board_mode <> Board_compose ->
           (* One pane on screen: the surface and the Activity pane take turns. *)
           if acting_pane_drawn state then focus_acting_pane_or_say_why state
       | Some "\023" when state.view = Resources -> (
           match state.resource_focus with
           | Left_pane -> state.resource_focus <- Right_pane
           | Right_pane ->
               if not (acting_pane_drawn state && focus_acting_pane state)
               then state.resource_focus <- Left_pane)
       | Some ("shift-left" | "shift-right") as key
         when state.view = Changes && Option.is_some (opened_file_change state) ->
           let direction = if key = Some "shift-left" then -1 else 1 in
           state.changes_diff_hscroll <-
             max 0 (min (max 0 (state.changes_diff_max_width - 1))
               (state.changes_diff_hscroll + direction))
       | Some ("esc" | "left" | "K") when Option.is_some (current_code_hover state) ->
           state.code_hover <- None
       | Some ("j" | "down" | "k" | "up" | "pageup" | "pagedown" | "home" | "end" as key)
           when Option.is_some (current_code_hover state) ->
           let count, height = Masc_tui_render_code.code_hover_viewport state in
           let move = match key with
             | "j" | "down" -> `Down | "k" | "up" -> `Up
             | "pageup" -> `Page_up | "pagedown" -> `Page_down
             | "home" -> `First | "end" -> `Last | _ -> `First in
           Code_results.scroll_hover state ~count ~height move
       | Some key when Option.is_some (current_code_hover state)
           && not (List.mem key ["tab"; "shift-tab"; "\t"; "q"; "?"; ":"]) -> ()
       | Some "e" when state.view = Code && code_edit_focus state -> edit_code_draft ()
       | Some "S" when state.view = Code && code_edit_focus state ->
           (match Masc_tui_code_requests.save_draft state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
             ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) with
            | Ok () -> ()
            | Error (Request_failed detail) -> report_action state "error" detail
            | Error (Request_withdrawn refusal) ->
                Masc_tui_transport.Request_notice.report_kept_back state ~request:Kept_request.File_save
                  (fun ~ko -> workspace_refusal_reason ~ko refusal) Draft_kept)
       | Some "V" when state.view = Code && code_edit_focus state ->
           (match current_code_draft state with
            | None -> report_action state "system" "No draft for this file"
            | Some _ -> state.code_draft_open <- not state.code_draft_open;
                state.code_draft_scroll <- 0)
       | Some "X" when state.view = Code && code_edit_focus state ->
           (match Code_results.discard_draft state with
            | Ok () -> report_action state "system" "Local draft discarded; server file is unchanged"
            | Error detail -> report_action state "error" detail)
       | Some "A" when state.view = Code && state.code_draft_open && code_edit_focus state ->
           (match Code_results.adopt_draft_revision state with
            | Ok () -> report_action state "system" "Compared server revision adopted; review the draft before S saves"
            | Error detail -> report_action state "error" detail)
       | Some ("r" | "R") when state.view = Code && state.code_draft_open && code_edit_focus state ->
           (match Masc_tui_code_requests.reread_draft state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
               ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) with
            | Ok () -> () | Error detail -> report_action state "error" detail)
       | Some ("esc" | "left") when state.view = Code && state.code_draft_open ->
           state.code_draft_open <- false
       | Some ("j" | "k" | "up" | "down" | "pageup" | "pagedown" | "home" | "end" as key)
           when state.view = Code && state.code_draft_open ->
           let _, cols = get_terminal_size () in
           let pane_cols = if cols >= keeper_split_threshold_cols then cols - keeper_roster_pane_cols else cols in
           let height = Masc_tui_render_code.code_pane_content_height state in
           let maximum = max 0 (List.length (Masc_tui_render_code.code_draft_rows state ~cols:pane_cols) - height) in
           let step = match key with "pageup" | "pagedown" -> Masc_tui_scroll.page_step ~height | _ -> 1 in
           let next = match key with
             | "home" -> 0 | "end" -> maximum
             | "k" | "up" | "pageup" -> state.code_draft_scroll - step
             | _ -> state.code_draft_scroll + step in
           state.code_draft_scroll <- max 0 (min maximum next)
       | Some key when state.view = Code && state.code_draft_open
           && not (List.mem key ["tab"; "shift-tab"; "\t"; "q"; "?"; ":"]) -> ()
       | Some "shift-left"
         when state.view = Code && state.code_focus_file = Right_pane ->
           pan_code_content state ~direction:(-1)
       | Some "shift-right"
         when state.view = Code && state.code_focus_file = Right_pane ->
           pan_code_content state ~direction:1
       | Some "\016" when state.view = Code ->
           Masc_tui_code_requests.launch_file_finder state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
             ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)
       | Some "\018" when state.view = Code ->
           Masc_tui_code_requests.launch_branches state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
             ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)
       | Some "W" when state.view = Code ->
           Masc_tui_code_requests.launch_worktrees state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
             ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)
       | Some "\007" when state.view = Code ->
           if server_authority_ready state then open_code_search state
           else report_action state "error" "Search needs a confirmed workspace"
       | Some "B" when state.view = Code ->
           Masc_tui_code_requests.return_to_reading state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
             ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)
       | Some (("K" | "D" | "R") as key_name)
         when state.view = Code && state.code_focus_file = Right_pane
              && Option.is_some (Masc_tui_fetched.current_key state.code_file)
              && not state.code_history_open
              && not state.code_diff_open
              && not state.code_notes_open ->
           (* Ask the language server about a name on the cursor line. The
              pane has no character cursor, so the line's own names are the
              candidates: one name is asked about at once, several open the
              palette with each as an entry (typing still narrows, and a
              typed "def <name>" keeps working), and none says so. *)
           let question =
             match key_name with
             | "K" -> "hover"
             | "R" -> "references"
             | "D" | _ -> "definition"
           in
           (match Masc_tui_palette.code_cursor_line_symbols state with
            | [] ->
                state.code_lsp_note <- Some Code_note_no_name_on_line
            | [ symbol ] ->
                Masc_tui_code_requests.start_lsp_question state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~report:(report_action state)
                  ~question ~symbol
            | _ :: _ :: _ ->
                state.palette_open <- true;
                state.palette_mode <-
                  Masc_tui_types.Palette_choice
                    { choice_question = question
                    ; choice_line = state.code_file_cursor + 1
                    };
                state.palette_query <- "";
                state.palette_cursor <- 0)
       | Some "b" when state.view = Code && state.code_focus_file = Right_pane
                       && Option.is_some (Masc_tui_fetched.current_key state.code_file) ->
           (* Who last touched each run of lines, in the margin beside the
              code. A margin rather than a view: blame answers a question
              about the line you are reading, and a separate screen would
              take that line away to answer it.

              Loaded is showing, so this toggles by fetching or dropping.
              Re-fetched rather than kept on a second press: an edit or a
              commit since the last read moves the runs, and a stale margin
              names the wrong author with no sign that it is stale. *)
           (match Masc_tui_fetched.current_key state.code_file with
            | None -> ()
            | Some path ->
                (* A second press puts the margin away, whatever state it is
                   in -- including one still being read, which is the press an
                   operator makes when a slow blame is taking too long. *)
                if Option.is_some (Masc_tui_fetched.current state.code_blame)
                then state.code_blame <- Masc_tui_fetched.clear state.code_blame
                else Masc_tui_code_requests.launch_blame_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~path)
       | Some ("pageup" | "pagedown" | "home" | "end" as move)
         when state.view = Code && state.code_focus_file = Right_pane
              && state.code_notes_open ->
           let count, height = Masc_tui_render_code.code_notes_viewport state in
           let maximum = max 0 (count - height) in
           let current = max 0 (min state.code_notes_scroll maximum) in
           let page = Masc_tui_scroll.page_step ~height in
           state.code_notes_scroll <-
             (match move with
              | "home" -> 0 | "end" -> maximum
              | "pageup" -> max 0 (current - page)
              | "pagedown" -> min maximum (current + page)
              | _ -> current)
       | Some "t" when state.view = Code && state.code_focus_file = Right_pane
                       && state.code_history_open ->
           (match Masc_tui_render_code.code_history_selected state with
            | None | Some (Hist_commit _) ->
                report_action state "system" "Select a Keeper record with a Task to inspect"
            | Some (Hist_keeper_change change) ->
                (match change.Masc.Tui_decode.fc_task_id with
                 | None -> report_action state "system" "No Task link on this record"
                 | Some task_id ->
                     (* The current domain read owns the destination. An absent
                        row must not turn into an unrelated Tasks list, and an
                        unavailable read must not be called a missing Task. *)
                     if state.workspace_identity <> Workspace_identity_match then
                       report_action state "error" "Task workspace has not been confirmed"
                     else
                       match state.task_reading with
                       | Masc_tui_overview_tasks.Rows_unread ->
                           report_action state "system" "Tasks have not been read; refresh to retry"
                       | Masc_tui_overview_tasks.Rows_unavailable detail ->
                           report_action state "error" ("Tasks unavailable: " ^ detail)
                       | Masc_tui_overview_tasks.Rows_read _ ->
                           match Masc_tui_task_selection.detail_row
                             ~detail_id:(Some task_id) ~tasks:(Masc_tui_types.task_domain_values state) with
                           | None -> report_action state "system"
                               ("Task not in backlog: " ^ task_id)
                           | Some _ ->
                               state.followed_from <- Some (Code, None);
                               goto_surface ~from_reference:true state
                                 ~mailbox:async_messages Planning;
                               state.planning_mode <- Planning_list;
                               state.task_detail_id <- Some task_id;
                               reset_task_detail_scroll state;
                               prepare_task_history_for_open state ~task_id;
                               state.task_focus <-
                                 Masc_tui_overview_tasks.land_on state.tasks ~task_id;
                               Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size state
                                 ~mailbox:async_messages task_id))
       | Some "m" when state.view = Code && state.code_focus_file = Right_pane
                       && Option.is_some (Masc_tui_fetched.current_key state.code_file) ->
           (* The memos in the open file: comments in the file's own syntax
              that read as Ide_memo's grammar, taken off the rows already
              lexed. Nothing to fetch, so the overlay opens on what is
              loaded, and the same key closes it. *)
           if state.code_notes_open then state.code_notes_open <- false
           else begin
             state.code_notes_open <- true;
             state.code_notes_scroll <- 0;
             state.code_diff_open <- false;
             state.code_history_open <- false
           end
       | Some "d" when state.view = Code && state.code_focus_file = Right_pane
                       && state.code_history_open ->
           (* A commit row opens what that commit changed in this file, over
              the same overlay the working-tree diff uses; a Keeper record
              expands its recorded text in place. *)
           (match
              history_commit_diff_target
                ~file_path:(Masc_tui_fetched.current_key state.code_file)
                (Masc_tui_render_code.code_history_selected state)
            with
            | Some target ->
                state.code_diff_open <- true;
                state.code_history_open <- false;
                state.code_notes_open <- false;
                (* A failed or stale read starts again, so an ambiguous
                   abbreviation or a refused read can be retried by pressing
                   d once more. *)
                (match Masc_tui_fetched.current state.code_diff with
                 | Some (loaded, (Masc_tui_fetched.Ready _ | Masc_tui_fetched.Loading))
                   when code_diff_target_equal loaded target -> ()
                 | Some (_, (Masc_tui_fetched.Ready _ | Masc_tui_fetched.Loading
                            | Masc_tui_fetched.Absent | Masc_tui_fetched.Stale (_, _)
                            | Masc_tui_fetched.Failed _))
                 | None ->
                     Masc_tui_code_requests.launch_diff_load state
                       ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                       ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~target)
            | None ->
                if not (Masc_tui_render_code.toggle_history_change state) then
                  report_action state "error"
                    "Select a commit or a Keeper record to see its change")
       | Some "d" when state.view = Code && state.code_focus_file = Right_pane
                       && Option.is_some (Masc_tui_fetched.current_key state.code_file) ->
           (* The working tree against HEAD, over the open file. One overlay
              at a time: opening this closes the history, and H the reverse.
              Same key closes it; a diff already fetched for this path is
              shown as it stands. *)
           (match Masc_tui_fetched.current_key state.code_file with
            | None -> ()
            | Some path ->
                if state.code_diff_open then close_code_diff state
                else begin
                  state.code_diff_open <- true;
                  state.code_history_open <- false;
                  state.code_notes_open <- false;
                  let target = Diff_worktree { path; base_ref = tree_diff_base_ref } in
                  (match Masc_tui_fetched.current state.code_diff with
                   | Some (loaded, _) when code_diff_target_equal loaded target -> ()
                   | Some _ | None ->
                       Masc_tui_code_requests.launch_diff_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)
                         ~target)
                end)
       | Some ("pageup" | "pagedown" | "home" | "end" as move)
         when state.view = Code && state.code_focus_file = Right_pane
              && state.code_history_open ->
           let count, height = Masc_tui_render_code.code_history_viewport state in
           let current = Masc_tui_scroll.normalize ~count ~height:1 state.code_history_scroll in
           let maximum = Masc_tui_scroll.maximum ~count ~height:1 in
           let page = Masc_tui_scroll.page_step ~height in
           state.code_history_scroll <-
             (match move with
              | "home" -> 0 | "end" -> maximum
              | "pageup" -> max 0 (current - page)
              | "pagedown" -> min maximum (current + page)
              | _ -> current)
       | Some ("pageup" | "pagedown" | "home" | "end" as move)
         when state.view = Code && state.code_focus_file = Right_pane
              && state.code_diff_open ->
           (* The diff covers the file, so these keys move the diff. The page
              keys of the arm below move the file cursor, which the overlay
              hides. *)
           Option.iter (fun (count, height) ->
             state.code_diff_scroll <-
               (match move with
                | "home" -> 0
                | "end" -> Masc_tui_scroll.maximum ~count ~height
                | "pageup" -> Masc_tui_scroll.page_up ~count ~height state.code_diff_scroll
                | "pagedown" -> Masc_tui_scroll.page_down ~count ~height state.code_diff_scroll
                | _ -> Masc_tui_scroll.normalize ~count ~height state.code_diff_scroll))
             (Masc_tui_render_code.code_diff_viewport state)
       | Some "H" when state.view = Code && state.code_focus_file = Right_pane ->
           (* History over the open file. The capital only: lowercase h/l
              choose panes, while shifted arrows pan the file. Same key closes
              it; a listing already fetched for this path is shown as it stands. *)
           (match Masc_tui_fetched.current_key state.code_file with
            | None -> ()
            | Some path ->
                if state.code_history_open then
                  state.code_history_open <- false
                else begin
                  state.code_history_open <- true;
                  state.code_history_scroll <- 0;
                  state.code_diff_open <- false;
                  state.code_notes_open <- false;
                  (* Already about this file in this scope -- loaded,
                     reading, or failed -- so opening the overlay shows what
                     there is rather than asking again. *)
                  (match Masc_tui_fetched.current_key state.code_history with
                   | Some key when code_scope_path_equal key (state.code_scope, path)
                     -> ()
                   | Some _ | None ->
                       Masc_tui_code_requests.launch_history_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~path)
                end)
       | Some "\015"
         when state.view = Board
              && (match state.board_mode with Board_read _ -> true | Board_list | Board_compose -> false)
              && board_read_focus state ~cols:terminal_columns = Right_pane ->
           open_board_diagram state ~mailbox:async_messages
       | Some (("," | ".") as direction)
         when state.view = Board
              && (match state.board_mode with Board_read _ -> true | Board_list | Board_compose -> false)
              && board_read_focus state ~cols:terminal_columns = Right_pane ->
           step_board_diagram state ~delta:(if direction = "." then 1 else -1)
       | Some key
         when state.view = Board
              && (match state.board_mode with
                  | Board_read _ -> true
                  | Board_list | Board_compose -> false)
              && not state.board_comments_focused
              && Option.is_some (board_attachment_digit_of_key key) ->
           (* The ATTACHMENTS block numbers entries [1..9]; the number opens
              the same entry, whatever its kind wants done with it. *)
           Option.iter
             (fun digit -> open_board_attachment state ~mailbox:async_messages ~digit ~host ~port)
             (board_attachment_digit_of_key key)
       | Some "O" when state.view = Board
           && (match state.board_mode with Board_read _ -> true | Board_list | Board_compose -> false) ->
           (match state.board_image_selection with
            | Some subject when board_preview_subject_is_current state subject
                && server_authority_ready state ->
                ignore (board_image_source_reader state ~message:"Original image selected." subject)
            | Some _ | None ->
                state.board_attachment_status <- Some "Select an image attachment first")
       | Some "o" when state.view = Board ->
           (match state.board_mode with
            | Board_read post_id
              when Board_detail.is_ready state.board_detail ~post_id
                   || (state.board_history_post_id = Some post_id
                       && match Board_detail.view_for state.board_detail ~post_id with
                      | Board_detail.Failed _ -> true
                      | Board_detail.Absent | Board_detail.Loading
                      | Board_detail.Ready _ -> false) ->
                state.board_history_post_id <-
                  (if state.board_history_post_id = Some post_id then None
                   else Some post_id);
                (* A mode swap owns a fresh request generation. History starts
                   at its first row; newest-page reads can resolve a page anchor. *)
                state.board_scroll <- 0;
                state.board_comment_scroll <- 0;
                state.board_comment_landing <- None;
                state.board_detail <- Board_detail.clear state.board_detail;
                owe_board_post_read state ~mailbox:async_messages ~post_id
            | Board_list | Board_compose | Board_read _ -> ());
       | Some ("z" | "Z") when state.view = Board ->
           (match state.board_mode with
            | Board_read _ -> toggle_board_read_wide state ~cols:terminal_columns
            | Board_list | Board_compose -> ())
       | Some (("o" | "O" | "l") as sandbox_log_key)
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_sandbox
              && (not (String.equal sandbox_log_key "l")
                  || terminal_columns < keeper_split_threshold_cols
                  || state.keeper_detail_focus = Right_pane) ->
           (match selected_keeper state with
            | None -> ()
            | Some keeper ->
              state.keeper_sandbox_logs <- None;
              state.keeper_sandbox_logs_error <- None;
              Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_sandbox_logs state ~mailbox:async_messages
                keeper.k_name)
       (* The Story window under the list takes its keys before the list and the
          surface ring do: an open window owns Tab, Esc, [s] and [m] (RFC-0515
          section 2.5, E15). W explicitly selects the World dock. *)
       | Some key
         when state.view = Keepers Keeper_list
              && Option.is_some (keeper_story_action state key) ->
           Option.iter (apply_keeper_story_action state ~mailbox:async_messages)
             (keeper_story_action state key)
       | Some "v" when state.view = Keepers Keeper_list ->
           cycle_keeper_list_view state;
           let preference = keeper_view_preference state in
           ignore (Masc_tui_config.submit_keeper_preference state.keeper_preference_writer
             ~on_request_id:(fun request_id -> note_keeper_preference_submission state ~request_id preference)
             ~sw:(Eio_context.get_switch_opt ()) ~base_path preference)
       | Some "V" when state.view = Keepers Keeper_list ->
           cycle_keeper_list_density state;
           let preference = keeper_view_preference state in
           ignore (Masc_tui_config.submit_keeper_preference state.keeper_preference_writer
             ~on_request_id:(fun request_id -> note_keeper_preference_submission state ~request_id preference)
             ~sw:(Eio_context.get_switch_opt ()) ~base_path preference)
       | Some (("[" | "]") as bracket)
         when state.view = Keepers Keeper_list && Option.is_none (current_detail_reading state) ->
           jump_keeper_list_group state
             (if bracket = "]" then Masc_tui_keeper_list_model.Next_group
              else Masc_tui_keeper_list_model.Previous_group)
       (* On a heading Left folds and Right unfolds, before Left's back and
          Right's detail; on a row both keep those meanings (RFC-0515 E12). *)
       | Some (("left" | "right") as arrow)
         when state.view = Keepers Keeper_list && Option.is_none (current_detail_reading state)
              && keeper_list_on_heading state ->
           refold_keeper_list_focus state
             (if arrow = "left" then Masc_tui_keeper_list_model.Fold
              else Masc_tui_keeper_list_model.Unfold)
       | Some "o" when state.view = Keepers Keeper_list ->
           cycle_keeper_list_sort state;
           let preference =
             Masc_tui_config.Keeper_order (Masc_tui_keeper_list_model.sort_label state.keeper_list_sort) in
           ignore (Masc_tui_config.submit_keeper_preference state.keeper_preference_writer
             ~on_request_id:(fun request_id -> note_keeper_preference_submission state ~request_id preference)
             ~sw:(Eio_context.get_switch_opt ()) ~base_path preference)
       | Some "J" when state.view = Keepers Keeper_list ->
           (match selected_keeper state with
            | None -> ()
            | Some keeper ->
                state.detail_tab <- Detail_automation;
                open_keeper_detail state ~mailbox:async_messages keeper)
       | Some "K" when state.view = Keepers Keeper_list ->
           (match selected_keeper state with
            | None -> report_action state "error" "Select a Keeper to inspect its queued relationships"
            | Some keeper ->
                let token = begin_keeper_peer_reading state ~keeper_name:keeper.k_name in
                Masc_tui_collab_queue.Keeper_queue.launch_keeper_queue state ~mailbox:async_messages ~keeper_name:keeper.k_name
                  (Masc_tui_queue_inspection.Inspect_peers (token, None)))
       | Some "v" when state.view = Keepers Keeper_detail && state.detail_tab = Detail_items ->
           cycle_item_browser state
       | Some " " when state.view = Keepers Keeper_detail && state.detail_tab = Detail_items ->
           state.item_preview <- not state.item_preview
       | Some "a" when state.view = Keepers Keeper_detail && state.detail_tab = Detail_items ->
           Masc_tui_chat_dispatch.Chat_journals.prepare_item_request state
             ~drain_queue:(fun () -> Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path ~mailbox:async_messages)
             ~load_history:(fun keeper_name ->
               launch_keeper_history_load state ~mailbox:async_messages ~keeper_name)
       (* Absolute Sandbox intent; the owned save supplies a fresh revision. *)
       | Some "d" when state.view = Keepers Keeper_detail && state.detail_tab = Detail_sandbox ->
           Masc_tui_editor_forms.Skill_prompt_forms.set_sandbox_backend state ~mailbox:async_messages ~profile:Keeper_sandbox_config.Docker
       | Some "m" when state.view = Keepers Keeper_detail && state.detail_tab = Detail_sandbox ->
           Masc_tui_editor_forms.Skill_prompt_forms.set_sandbox_backend state ~mailbox:async_messages ~profile:Keeper_sandbox_config.Micro_vm
       | Some "s" when state.view = Keepers Keeper_detail && state.detail_tab = Detail_sandbox ->
           Masc_tui_editor_forms.Skill_prompt_forms.set_sandbox_backend state ~mailbox:async_messages ~profile:Keeper_sandbox_config.Remote_ssh
       | Some ("h" | "l")
         (* The width belongs to the screen that needs two panes, not to the
            key. Keeper detail below the threshold draws the detail alone and
            never reads the focus -- its footer drops [h/l] there for that
            reason -- while Resources and Code draw whichever pane the focus
            names at every width, so the key was refused on screens already
            drawing its answer. On Code that also left a file open with no way
            back to the tree but [Esc], which closes the file. *)
         when (match state.view with
                  | Keepers Keeper_detail ->
                      terminal_columns >= keeper_split_threshold_cols
                  | Resources -> true
                  | Board ->
                      (match state.board_mode with
                       | Board_read _ -> (
                           match
                             board_read_layout ~cols:terminal_columns
                               ~wide:state.board_detail_wide
                           with
                           | Board_read_split -> true
                           | Board_read_wide | Board_read_one_pane -> false)
                       | Board_list | Board_compose -> false)
                  | Code -> Masc_tui_keys.code_file_is_current state
                  | Overview | Acting | Metrics
                  | Keepers (Keeper_list | Keeper_logs | Keeper_calls | Keeper_message
                             | Keeper_runtime_pick)
                  | Lanes | Clients
                  | Approvals | Planning
                  | Schedules | Verification | Harness | Fusion
                  | Memory | Repositories | Changes | Connectors | Runtime | Config
                  | Tools | System_logs -> false) ->
           let focus = if key = Some "h" then Left_pane else Right_pane in
           (match state.view with
            | Board ->
                (match state.board_mode with
                 | Board_read _ -> state.board_focus <- focus
                 | Board_list | Board_compose -> ())
            | Keepers Keeper_detail -> state.keeper_detail_focus <- focus
            | Resources -> state.resource_focus <- focus
            | Code when Masc_tui_keys.code_file_is_current state ->
                state.code_focus_file <- focus
            | Overview | Acting | Metrics
            | Keepers (Keeper_list | Keeper_logs | Keeper_calls | Keeper_message
                       | Keeper_runtime_pick)
            | Lanes | Clients | Approvals
            | Planning | Schedules
            | Memory | Verification | Harness | Fusion | Repositories | Changes
            | Connectors | Runtime | Config | Code | Tools
            | System_logs -> ())
       | Some k when Masc_tui_keys.opens_keepers ~message_mode k ->
           goto_surface state ~mailbox:async_messages (Keepers Keeper_list)
       (* Following preserves the source surface; Esc returns to it. *)
       | Some "\x1d" ->
           (match
              Option.bind (presented_surface_reference ()) (fun reference ->
                Option.bind (Link.parse reference) (fun (kind, id) ->
                  Option.map (fun target -> (reference, kind, target))
                    (follow_target kind id)))
            with
            | None -> ()
            | Some (reference, kind, (destination, opened)) ->
                (* Recorded before the move, so the way back is where the
                   operator actually was rather than where they land. *)
                state.followed_from <- Some (state.view, None);
                goto_surface ~from_reference:true state ~mailbox:async_messages destination;
                (* Landing on the surface is half the move. Every one of
                   these already has a "this one is open" state, and without
                   setting it the operator arrives at the top of a list and
                   goes looking for the row they just followed. *)
                (match kind, destination, opened with
                 | Link.Task, Planning, Some task_id ->
                     state.planning_mode <- Planning_list;
                     state.task_detail_id <- Some task_id;
                     reset_task_detail_scroll state;
                     prepare_task_history_for_open state ~task_id;
                     state.task_focus <-
                       Masc_tui_overview_tasks.land_on state.tasks ~task_id;
                     Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size state ~mailbox:async_messages
                       task_id
                 | Link.Goal, Planning, Some goal_id ->
                     state.task_focus <- Masc_tui_overview_tasks.No_task_focus;
                     state.planning_mode <- Planning_detail goal_id;
                     state.planning_scroll <- Planning_scroll_offset 0;
                     state.goal_timeline <- Masc_tui_fetched.clear state.goal_timeline;
                     Masc_tui_work_requests.Tools_task_requests.launch_goal_timeline_load state ~mailbox:async_messages
                       goal_id
                 | Link.Board_post, Board, Some post_id -> state.board_mode <- Board_read post_id
                 | Link.Schedule, Schedules, Some schedule_id ->
                     state.schedule_detail_id <- Some schedule_id;
                     state.schedule_wake_history <- None;
                     state.schedule_wake_history_error <- None;
                     Masc_tui_work_requests.Schedule_call_requests.launch_schedule_wake_history_load state
                       ~mailbox:async_messages ~schedule_id
                 | Link.Fusion_run, Fusion, Some run_id ->
                     state.fusion_mode <- Fusion_detail run_id;
                     Masc_tui_work_actions.Detail_navigation.launch_fusion_detail_load ~demand:Masc_tui_fusion_updates.After_change
                       state ~mailbox:async_messages ~run_id
                 | Link.Keeper, Keepers _, Some keeper_name ->
                     (* The roster is a cursor, not an id, so this puts the
                        cursor on the named keeper and leaves it there. A name
                        the roster does not carry leaves the cursor alone
                        rather than moving it somewhere arbitrary. *)
                     (match
                        List.find_index
                          (fun (keeper : Tui_decode.keeper) ->
                             String.equal keeper.k_name keeper_name)
                          (keepers_for_selection state)
                      with
                      | Some index -> choose_keeper_row state index
                      | None -> ())
                 | (Link.Board_post | Link.Goal | Link.Schedule | Link.Task
                   | Link.Fusion_run | Link.Keeper),
                   (Overview | Acting | Metrics
                   | Keepers (Keeper_list | Keeper_detail | Keeper_logs | Keeper_calls
                              | Keeper_message | Keeper_runtime_pick)
                   | Memory | Lanes | Clients | Board | Approvals | Planning | Schedules
                   | Verification | Harness | Fusion | Repositories | Code | Changes
                   | Connectors | Runtime | Config | Resources | Tools | System_logs),
                   _ -> ());
                report_action state "system" ("followed " ^ reference))
       | Some "Y" ->
           (match presented_surface_reference () with
            | Some reference ->
                let outcome = copy_reference render_schedule reference in
                report_action state "system"
                  (if state.ui_language = Lang_ko then
                     reference ^ " · " ^ Masc_tui_clipboard.copy_outcome_text_korean outcome
                   else
                     reference ^ " " ^ Masc_tui_clipboard.copy_outcome_text outcome)
            | None when state.view = Approvals ->
                answer_presented_approval Confirm
            | None ->
                report_action state "system"
                  (ui_text state ~ko:"이 화면에는 복사할 링크가 없습니다" ~en:"nothing on this surface has a link"))
       | Some "y" ->
           (match state.view with
            | Approvals -> answer_presented_approval Confirm
            | Harness -> Masc_tui_editor_forms.Workspace_review_forms.handle_harness_agree state ~mailbox:async_messages
            | Resources ->
                (match Masc_tui_resource_document.copy_source state with
                 | Error detail -> report_action state "error" detail
                 | Ok (label, source) ->
                     let outcome = copy_reference render_schedule source in
                     report_action state "system"
                       (if state.ui_language = Lang_ko then
                          Printf.sprintf "%s 원본 (%d바이트)을 %s"
                            label (String.length source)
                            (Masc_tui_clipboard.copy_outcome_text_korean outcome)
                        else
                          Printf.sprintf "%s source (%d bytes) %s"
                            label (String.length source)
                            (Masc_tui_clipboard.copy_outcome_text outcome)))
            | Code ->
                (match Masc_tui_code_results.copy_file_source state with
                 | Error detail -> report_action state "error" detail
                 | Ok (path, source) ->
                     let outcome = copy_reference render_schedule source in
                     report_action state "system"
                       (if state.ui_language = Lang_ko then
                          Printf.sprintf "%s 원본 (%d바이트)을 %s"
                            path (String.length source)
                            (Masc_tui_clipboard.copy_outcome_text_korean outcome)
                        else
                          Printf.sprintf "%s source (%d bytes) %s"
                            path (String.length source)
                            (Masc_tui_clipboard.copy_outcome_text outcome)))
            | Overview | Acting | Metrics | Memory | Lanes | Clients | Board | Planning | Schedules
            | Verification | Fusion | Repositories | Changes | Connectors | Runtime | Config
            | Tools | System_logs | Keepers _ -> ())
       (* Stepping the last search is what [n] means on a surface that binds
          it to nothing else, so it is the tail of this arm rather than an
          arm of its own above it. As its own arm it sat above every surface
          that binds the key, and [search_last] is one string for the whole
          session: a surface with row texts and its own [n] would lose that
          key permanently after any search anywhere. Nothing is in that
          position today -- Harness was, and its overrule moved to [x] --
          and this shape is what keeps it that way.

          The match is exhaustive on purpose. A surface added later has to
          say whether [n] is its own key or the search step. *)
       | Some (("n" | "N") as direction) ->
           (match state.view with
            | Approvals -> answer_presented_approval Deny
            | Schedules -> Masc_tui_editor_forms.Workspace_review_forms.handle_schedule_create state ~mailbox:async_messages ~terminal_session
            (* The presets pane says [n] is its own key: a new preset from
               the live state, named in the line the pane opens. *)
            | Config when state.config_pane = Config_presets ->
                if state.preset_busy then
                  report_action state "system" (ui_text state ~ko:"프리셋 작업이 아직 끝나지 않았습니다" ~en:"A preset operation is still in progress")
                else begin
                  state.preset_armed <- None;
                  let workspace = if server_authority_ready state
                    then workspace_input_identity_of_server state.server_identity else None in
                  match workspace with
                  | Some origin ->
                    (match List.assoc_opt origin state.preset_save_suspended_drafts with
                     | Some draft ->
                       state.preset_save_draft <- Some draft.psd_name;
                       state.preset_save_draft_description <- draft.psd_description;
                       state.preset_save_draft_source <- draft.psd_source;
                       state.preset_save_draft_workspace <- Some origin;
                       state.preset_save_suspended_drafts <-
                         List.remove_assoc origin state.preset_save_suspended_drafts;
                       report_action state "system"
                         (ui_text state ~ko:"이 워크스페이스의 저장 이름 초안을 복원했습니다"
                            ~en:"Restored this workspace's preset name draft")
                     | None ->
                       state.preset_save_draft <- Some "";
                       state.preset_save_draft_description <- "";
                       state.preset_save_draft_source <- Preset_form_local;
                       state.preset_save_draft_workspace <- Some origin)
                  | None ->
                    state.preset_save_draft <- Some "";
                    state.preset_save_draft_description <- "";
                    state.preset_save_draft_source <- Preset_form_local;
                    state.preset_save_draft_workspace <- None
                end
            | Overview | Acting | Metrics | Keepers _ | Memory | Lanes | Clients | Board
            | Planning
            | Verification | Harness | Fusion | Repositories | Code | Changes
            | Connectors | Runtime | Config | Resources | Tools | System_logs ->
                if
                  state.search_last <> ""
                  && Option.is_some (Masc_tui_surface_search.surface_row_texts ~cols:(snd (get_terminal_size ())) state state.view)
                then
                  let after =
                    Option.value (search_row_cursor state) ~default:0
                  in
                  search_jump state ~query:state.search_last ~after
                    ~backwards:(String.equal direction "N"))
       (* The log reads newest first, so Home is the live end of the file and
          End is the oldest row the tail window holds. An operator who has
          paged back wants one key to return to now. *)
       | Some "home" when state.view = Keepers Keeper_logs ->
           state.log_scroll <- 0
       | Some "end" when state.view = Keepers Keeper_logs ->
           state.log_scroll <-
             Metrics_tail.maximum_scroll
               ~entry_count:(keeper_log_row_count state)
               ~content_height:(keeper_log_content_height state)
       (* The Tools readings. Its two lists take the edge keys below, through
          [list_moves], as every other list does. *)
       | Some "home"
         when state.view = Tools && Option.is_none (Masc_tui_list_moves.tools_list state) ->
           tools_task_user_scroll state 0
       | Some "end"
         when state.view = Tools && Option.is_none (Masc_tui_list_moves.tools_list state) ->
           if not (tools_task_select_end state) then
             tools_task_user_scroll state
               (move_surface_to_end state ~rows:(surface_rows state)
                  ~current:state.tools_scroll)
       | Some ("home" | "end")
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_items ->
           state.item_cursor <-
             if key = Some "home" then 0
             else max 0 (List.length (item_browser_items state) - 1);
           state.detail_scroll <- 0
       (* Reading a post with the list pane focused: j/k and the page keys move
          the list and open what they land on, so the edge keys reach the first
          and last post the same way. This cannot go through [row_list] -- the
          cursor alone would leave the reader on the old post, and opening one
          needs the mailbox a place callback does not have. *)
       | Some ("home" | "end")
         when state.view = Board
              && (match state.board_mode with
                  | Board_read _ -> true
                  | Board_list | Board_compose -> false)
              && Masc_tui_types.board_read_focus state ~cols:terminal_columns = Left_pane ->
           let count = List.length (board_posts state) in
           let target = if key = Some "end" then count - 1 else 0 in
           step_board_read state ~mailbox:async_messages
             ~delta:(target - state.board_cursor)
       | Some ("pageup" | "pagedown" | "home" | "end" as move)
         when state.view = Config && state.config_pane = Config_prompts
              ->
           let count, height = Masc_tui_render.prompts_detail_viewport state in
           state.config_scroll <-
             (match move with
              | "home" -> 0
              | "end" -> Masc_tui_scroll.maximum ~count ~height
              | "pageup" -> Masc_tui_scroll.page_up ~count ~height state.config_scroll
              | "pagedown" -> Masc_tui_scroll.page_down ~count ~height state.config_scroll
              | _ -> Masc_tui_scroll.normalize ~count ~height state.config_scroll)
       (* Resources retains the selected edge through reflow. *)
       | Some ("home" | "end")
         when state.view = Resources && state.resource_focus = Right_pane ->
           move_resource_document state
             (if key = Some "end" then Masc_tui_scroll.Position.Last else First)
       | Some ("home" | "end")
         when state.view = Approvals && state.approval_detail_open ->
           Option.iter (fun _viewport ->
             ignore (Masc_tui_approvals_model.detail_edge state
               ~to_bottom:(key = Some "end")))
             (approval_detail_viewport_of_reader (!presented).reader)
       (* A reading pane before the list behind it: a detail that is open owns
          the scroll keys, and moving the list under it would leave the cursor
          somewhere the reader cannot see. The pane reports its own clamp, so
          End names a row past the end and the frame corrects it -- the same
          report its j/k already relies on. *)
       | Some ("home" | "end")
         when Option.is_some (reading_pane state ~cols:terminal_columns) ->
           Option.iter
             (fun clamped ->
               match task_detail_of_reader (Some (clamped 0)) with
               | Some _ when key = Some "end" ->
                   let cols = task_document_columns state ~terminal_cols:terminal_columns in
                   task_detail_select_end state ~cols
               | Some _ ->
                   task_detail_user_scroll state 0
               | None ->
                   apply_clamped_scroll state
                     (clamped (if key = Some "end" then clamped_scroll_end else 0)))
             (reading_pane state ~cols:terminal_columns)
       (* Every other list. The two surfaces above answer first because their
          rows are drawn newest first, so their Home is the live end rather
          than the first row -- the rest read oldest first and take the plain
          meaning. A surface [surface_list_count] cannot count falls through
          to whatever else claims the key. *)
       | Some ("home" | "end") when Option.is_some (list_moves state) ->
           move_list state (if key = Some "end" then Masc_tui_scroll.To_end else Masc_tui_scroll.To_top)
       | Some ("pageup" | "pagedown") ->
           (* A list pages by the rows it drew ([list_on_screen]), so its arm
              below names the key and no page. [page] is for the readings
              and for the cursors that are not a row list. *)
           let page = surface_page_rows state in
           let direction = if key = Some "pagedown" then 1 else -1 in
           let page_key =
             if direction > 0 then Masc_tui_scroll.Page_down else Masc_tui_scroll.Page_up
           in
           (match state.view with
            | Planning when state.planning_mode = Planning_list
                            && Masc_tui_overview_tasks.is_focused state.task_focus
                            && Option.is_some (task_detail_on_screen state) ->
                let count, height = task_detail_presented_viewport state
                    ~fallback:(fun () -> Masc_tui_render.task_detail_viewport state) in
                let move = if direction > 0 then Masc_tui_scroll.page_down else Masc_tui_scroll.page_up in
                move_task_detail (move ~count ~height state.task_detail_scroll)
            (* Applying a scheme used to live on the page keys, where the
               footer never said it was and where PageDown is a scroll
               everywhere else; it answers to Enter. Emptying the arm left the
               53-row list with j/k alone, so the page keys move the selection
               a page, previewing where they land as j/k do. *)
            | Config when state.config_pane = Config_themes ->
                state.theme_cursor <-
                  Masc_tui_scroll.cursor_move
                    ~count:(List.length (filtered_theme_entries state))
                    ~delta:(direction * page) state.theme_cursor;
                preview_theme_under_cursor state
            (* A stacked item taller than the pane: the page keys walk its
               lines and the cursor stays on its binding, which is how the
               lines past the pane are read. *)
            | Config
              when state.config_pane = Config_models
                   && (let terminal_rows, cols = get_terminal_size () in
                       match Masc_tui_render_config.config_models_list state ~terminal_rows ~cols with
                       | Some list -> list.ml_reads_selected
                       | None -> false) ->
                (match scrolled_surface state state.view with
                 | None -> ()
                 | Some scrolled ->
                     let height = surface_body_height ~rows:(surface_rows state) scrolled in
                     let move =
                       if direction > 0 then Masc_tui_scroll.page_down
                       else Masc_tui_scroll.page_up
                     in
                     state.config_scroll <-
                       move ~count:scrolled.sc_count ~height state.config_scroll)
            (* Otherwise the bindings are read by a cursor [e] acts on: its
               row list. *)
            | Config when state.config_pane = Config_models -> move_list state page_key
            | Planning when Option.is_some (Masc_tui_work_actions.Goal_actions.goal_detail_on_screen state) ->
                let count, height = Masc_tui_render.planning_detail_viewport state in
                state.planning_scroll <- Planning_scroll_offset
                  ((if direction > 0 then Masc_tui_scroll.page_down ~count ~height
                    else Masc_tui_scroll.page_up ~count ~height)
                     (planning_scroll_value state.planning_scroll))
            | Code ->
                move_list state page_key
            | Board ->
                (match state.board_mode with
                 | Board_list -> move_list state page_key
                 | Board_read _ ->
                     (match Masc_tui_types.board_read_focus state ~cols:terminal_columns with
                      | Left_pane ->
                          move_board_posts_pane state ~mailbox:async_messages
                            ~delta:(direction * page)
                      | Right_pane ->
                          Masc_tui_types.page_board_read state ~direction)
                 | Board_compose -> ())
            | Fusion ->
                (match state.fusion_mode with
                 | Fusion_list -> move_list state page_key
                 | Fusion_detail _ | Fusion_historical_detail _ ->
                     state.fusion_scroll <-
                       Masc_tui_scroll.step_uncounted ~delta:(direction * page) state.fusion_scroll)
            | Schedules ->
                if Option.is_some (Masc_tui_work_actions.Board_schedule_actions.schedule_detail_on_screen state) then
                  let count, height = Masc_tui_render.schedule_detail_viewport state in
                  state.schedule_scroll <-
                    (if direction > 0 then Masc_tui_scroll.page_down ~count ~height
                     else Masc_tui_scroll.page_up ~count ~height) state.schedule_scroll
                else move_list state page_key
            | Verification ->
                if Option.is_some state.verification_detail_request_id then
                  state.verification_detail_scroll <-
                    Masc_tui_scroll.step_uncounted ~delta:(direction * page) state.verification_detail_scroll
                else
                  move_list state page_key
            | Harness ->
                if Option.is_some state.harness_detail then
                  state.harness_detail_scroll <-
                    Masc_tui_scroll.step_uncounted ~delta:(direction * page) state.harness_detail_scroll
                else
                  move_list state page_key
            (* Presets draw their detail from the same scroll prompts do, and
               the key reached only prompts: a preset longer than its pane
               showed its first screen and nothing past it. *)
            | Config
              when state.config_pane = Config_presets ->
                let count, height = Masc_tui_render.presets_viewport state in
                let move = if direction > 0 then Masc_tui_scroll.page_down else Masc_tui_scroll.page_up in
                state.config_scroll <- move ~count ~height state.config_scroll
            | Config when state.config_pane = Config_params ->
                let terminal_rows, _ = get_terminal_size () in
                let _, detail_height =
                  Masc_tui_types.runtime_params_viewport state ~terminal_rows in
                (* One repeated row anchors consecutive pages. The key uses
                   the same detail height as the renderer, including forms. *)
                let page = max 1 (detail_height - 1) in
                state.config_scroll <-
                  Masc_tui_scroll.step_uncounted ~delta:(direction * page) state.config_scroll
            | Config when state.config_pane = Config_voice ->
                state.config_scroll <-
                  Masc_tui_scroll.step_uncounted ~delta:(direction * page) state.config_scroll
            | Config when state.config_pane = Config_runtime ->
                set_runtime_config_cursor_near state ~direction
                  ~target:(state.runtime_config_cursor + (direction * page))
            | Runtime when Option.is_some state.runtime_detail_target ->
                state.runtime_detail_scroll <-
                  Masc_tui_scroll.step_uncounted ~delta:(direction * page) state.runtime_detail_scroll
            | System_logs when system_log_detail_open state ->
                edit_system_logs_page state (fun logs -> {logs with lp_detail_scroll=
                  Masc_tui_scroll.step_uncounted ~delta:(direction * page) logs.lp_detail_scroll})
            (* The Runs tab is read by a cursor, so its page key names a run
               the way Home and End do. Scrolling it instead wrote a value the
               drawing pulled straight back to the selected run, which is the
               same reason the edge keys had to move the cursor. *)
            | Keepers Keeper_detail when state.detail_tab = Detail_items ->
                move_item_browser state ~delta:(direction * page)
            | Keepers Keeper_detail when state.detail_tab = Detail_runs ->
                move_list state page_key
            (* Identity as well: the drawing keeps the cursor's row in view,
               so a page key that only scrolled was pulled straight back. *)
            | Keepers Keeper_detail when state.detail_tab = Detail_identity ->
                move_identity_cursor state ~delta:(direction * page)
            | Keepers Keeper_detail when state.detail_tab = Detail_terminal ->
                Masc_tui_types.move_keeper_terminal state ~by:(-direction * page)
            | Keepers Keeper_detail ->
                state.detail_scroll <-
                  Masc_tui_scroll.step_uncounted ~delta:(direction * page) state.detail_scroll
            (* The log pane owns its own height, so it pages by that rather
               than by [page]: the generic surface size counts chrome this
               pane does not have, and a page that overshoots the window skips
               rows. Rows are drawn newest first, so PageDown walks back in
               time. *)
            | Keepers Keeper_logs ->
                let entry_count = keeper_log_row_count state in
                let content_height = keeper_log_content_height state in
                state.log_scroll <-
                  (if direction > 0 then
                     Metrics_tail.page_down ~entry_count ~content_height
                       state.log_scroll
                   else
                     Metrics_tail.page_up ~entry_count ~content_height
                       state.log_scroll)
             | Clients ->
                 move_list state page_key
             | Lanes ->
                (match state.lanes_mode with
                 | Lanes_run_detail _ | Lanes_measurement_detail _ | Lanes_inventory_detail _ ->
                     let page =
                       Masc_tui_scroll.page_step
                         ~height:state.lane_run_detail_content_height
                     in
                     state.lane_run_detail_scroll <-
                       Masc_tui_scroll.step_uncounted ~delta:(direction * page) state.lane_run_detail_scroll
                 | Lanes_run_list _ | Lanes_overview -> move_list state page_key)
             | Metrics ->
                 let page = Masc_tui_scroll.page_step ~height:state.metrics_content_height in
                 state.metrics_scroll <-
                   Masc_tui_scroll.step_uncounted ~delta:(direction * page) state.metrics_scroll
             | Approvals when state.approval_detail_open ->
                 Option.iter (fun viewport ->
                   ignore (Masc_tui_approvals_model.page_detail state
                     ~forward:(direction > 0) ~count:viewport.adv_count ~height:viewport.adv_height))
                   (approval_detail_viewport_of_reader (!presented).reader)
             (* The surfaces whose page key used to be silent. Each has a
                row list, so a page moves the cursor and the window follows --
                the same move Home and End make, by a page rather than to an
                edge. [move_list] finds the list itself and answers
                to nothing when there is none; the arm below is where there
                is none. *)
             | Keepers (Keeper_list | Keeper_calls | Keeper_message | Keeper_runtime_pick)
             | Overview | Approvals | Planning | Memory | Repositories
             | Changes | Connectors | Runtime | System_logs ->
                 move_list state page_key
             (* Two panes, two meanings: the list moves a cursor like the
                arm above, the reading scrolls. [move_list] finds the
                list only while the list is focused, so the reading's own
                page is spelled here rather than left silent. *)
             | Resources ->
                 (match state.resource_focus with
                  | Right_pane ->
                      move_resource_document state
                        (Masc_tui_scroll.Position.By (direction * page))
                  | Left_pane -> move_list state page_key)
             (* A Tools list pages by the rows of the Tools window
                ([list_on_screen]), the same window the readings below page
                by. *)
             | Tools when Option.is_some (Masc_tui_list_moves.tools_list state) ->
                 move_list state page_key
             | Tools ->
                 let count, height = tools_scroll_viewport state in
                 move_tools_task
                   (if direction > 0 then
                      Masc_tui_scroll.page_down ~count ~height state.tools_scroll
                    else
                      Masc_tui_scroll.page_up ~count ~height state.tools_scroll)
             (* Flat event lists and evidence have already answered above.
                Turns owns a scroll, and the renderer clamps its folded rows. *)
             | Acting ->
                 let terminal_rows, _ = get_terminal_size () in
                 let page = Masc_tui_render_activity.acting_page_rows state ~terminal_rows in
                 state.acting_scroll <- Masc_tui_scroll.step_uncounted
                   ~delta:(direction * page) state.acting_scroll;
                 if state.acting_scroll = 0 then state.acting_unseen <- 0
             (* Config's panes carry cursors of their own. *)
             | Config -> ())
       (* On Config, s and t hop to Resources and Tools and r is the global
          refresh, so the pane takes u, twice, for the destructive restore,
          and D, twice, for the delete. Its save key is n, answered inside
          the [n] dispatch below, which the surface list there requires. *)
       | Some "v" when state.view = Config && state.config_pane = Config_presets ->
           if recoverable_preset_save_commands state <> [] then begin
             reveal_unsent_preset_save_receipts state;
             state.config_scroll <- 0
           end
       | Some "c" when state.view = Config && state.config_pane = Config_presets ->
           (match recoverable_preset_save_commands state with
            | [] -> report_action state "system"
                (ui_text state ~ko:"복사할 미전송 채팅 명령이 없습니다"
                   ~en:"No unsent chat command to copy")
            | commands ->
              let index = state.preset_save_copy_cursor mod List.length commands in
              let name, input = List.nth commands index in
              let outcome = copy_reference render_schedule input in
              state.preset_save_copy_cursor <- (index + 1) mod List.length commands;
              report_action state "system"
                (match state.ui_language with
                 | Lang_ko ->
                     Printf.sprintf "%s 명령을 %s"
                       (Terminal_text.single_line name)
                       (Masc_tui_clipboard.copy_outcome_text_korean outcome)
                 | Lang_en ->
                     Printf.sprintf "%s command %s"
                       (Terminal_text.single_line name)
                       (Masc_tui_clipboard.copy_outcome_text outcome)))
       | Some "x" | Some "X"
         when state.view = Config && state.config_pane = Config_presets ->
           if visible_preset_save_receipts state <> [] then begin
             dismiss_latest_preset_save_receipt state;
             state.config_scroll <- 0
           end
       | Some "u" | Some "U"
         when state.view = Config && state.config_pane = Config_presets ->
           (match Masc_tui_surface_requests.Prompt_preset_requests.selected_preset_for_state state with
            | None -> report_action state "error" (ui_text state ~ko:"복원할 프리셋을 고르세요" ~en:"Select a preset to restore")
            | Some manifest ->
              let name = manifest.Tui_decode.pm_name in
              if state.preset_busy || workspace_preset_save_pending state <> [] then
                report_action state "system" (ui_text state ~ko:"프리셋 작업이 아직 끝나지 않았습니다" ~en:"A preset operation is still in progress")
              else if state.preset_armed = Some (Restore_armed name) then begin
                state.preset_armed <- None;
                state.preset_busy <- true;
                report_action state "system" (name ^ ui_text state ~ko:" 복원 중 · 지금 상태는 먼저 저장됩니다" ~en:" restoring · current settings are backed up first");
                Masc_tui_surface_requests.Prompt_preset_requests.launch_preset_call state ~mailbox:async_messages
                  ~call:(fun ~host ~port -> Masc_tui_loader.restore_preset ~host ~port ~name)
                  ~wrap:(fun result -> Preset_msg (Preset_restored (Preset_to_pane, result)))
              end
              else begin
                state.preset_armed <- Some (Restore_armed name);
                report_action state "system"
                  (Printf.sprintf (if state.ui_language = Lang_ko then "u 를 한 번 더 누르면 %s 로 복원합니다" else "Press u again to restore %s") name)
              end)
       | Some "D"
         when state.view = Config && state.config_pane = Config_presets ->
           (match Masc_tui_surface_requests.Prompt_preset_requests.selected_preset_for_state state with
            | None -> report_action state "error" (ui_text state ~ko:"지울 프리셋을 고르세요" ~en:"Select a preset to delete")
            | Some manifest ->
              let name = manifest.Tui_decode.pm_name in
              if state.preset_busy || workspace_preset_save_pending state <> [] then
                report_action state "system" (ui_text state ~ko:"프리셋 작업이 아직 끝나지 않았습니다" ~en:"A preset operation is still in progress")
              else if state.preset_armed = Some (Delete_armed name) then begin
                state.preset_armed <- None;
                state.preset_busy <- true;
                report_action state "system" (name ^ ui_text state ~ko:" 삭제 중" ~en:" deleting");
                Masc_tui_surface_requests.Prompt_preset_requests.launch_preset_call state ~mailbox:async_messages
                  ~call:(fun ~host ~port -> Masc_tui_loader.delete_preset ~host ~port ~name)
                  ~wrap:(fun result -> Preset_msg (Preset_deleted (Preset_to_pane, result)))
              end
              else begin
                state.preset_armed <- Some (Delete_armed name);
                report_action state "system"
                  (Printf.sprintf (if state.ui_language = Lang_ko then "D 를 한 번 더 누르면 %s 를 지웁니다" else "Press D again to delete %s") name)
              end)
       | Some key when state.view = Planning && String.equal key Masc_tui_keys.goal_candle_refresh_key ->
           let read_candle goal_id =
             start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port ~intent:Operator_key
               ~refresh_inflight:http_refresh_inflight ~scoped_refresh_inflight:http_scoped_refresh_inflight
               ~scoped_refresh_followup ~mailbox:async_messages;
             clear_goal_candle_revalidation state ~goal_id;
             Masc_tui_work_requests.Tools_task_requests.launch_goal_candle_load state ~mailbox:async_messages goal_id
           in
           let follow_candle goal =
             let target = Masc_tui_render_work.planning_detail_candle_scroll state goal in
             let count, height = Masc_tui_render.planning_detail_viewport state in
             state.planning_scroll <- Planning_scroll_candle
               (Masc_tui_scroll.normalize ~count ~height target)
           in
           let open_candle () =
             Masc_tui_work_actions.Detail_navigation.open_planning_detail state ~mailbox:async_messages;
             Option.iter follow_candle (Masc_tui_work_actions.Goal_actions.goal_detail_on_screen state)
           in
           (match Masc_tui_work_actions.Goal_actions.goal_detail_on_screen state with
            | Some goal ->
              read_candle goal.pg_id;
              follow_candle goal
            | None ->
              (match selected_planning_goal_id state with
               | None when not (Masc_tui_overview_tasks.is_focused state.task_focus) ->
                   open_candle ()
               | Some goal_id when Masc_tui_render_work.planning_missing_goal_notice state ~goal_id ->
                   read_candle goal_id
               | Some _
                 when not (Masc_tui_overview_tasks.is_focused state.task_focus) ->
                   open_candle ()
               | None | Some _ -> ()))
       | Some key when state.view = Planning
           && Option.is_some (Masc_tui_work_actions.Goal_actions.goal_detail_action state key) ->
           (* Detail actions take precedence over global navigation.
              The displayed keys and parser share one owner. *)
           Option.iter
             (fun action -> Masc_tui_work_actions.Goal_actions.handle_goal_action_key state ~mailbox:async_messages ~action)
             (Masc_tui_work_actions.Goal_actions.goal_detail_action state key)
       | Some "r" | Some "R" ->
           refresh_shared_sources ();
           (* Also reload logs / Board detail if viewing them. *)
           (match state.view with
            | Code ->
                if state.code_history_open then
                  (match Masc_tui_fetched.current_key state.code_file with
                   | None -> ()
                   | Some path ->
                       Masc_tui_code_requests.launch_history_load state
                         ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                         ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages) ~path)
                else
                  Masc_tui_code_requests.launch_entries_load state
                    ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                    ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)
            | Keepers Keeper_list ->
                Masc_tui_surface_requests.Memory_repository_requests.launch_memory_health_load state ~mailbox:async_messages
            | Keepers Keeper_logs ->
                ignore (launch_current_keeper_logs state ~mailbox:async_messages ~intent:Snapshot_read.Refresh)
            | Keepers Keeper_calls ->
                (match selected_keeper state with
                 | Some keeper ->
                     owe_keeper_calls_read state ~mailbox:async_messages
                       ~keeper_name:keeper.k_name
                 | None -> ())
            | Keepers Keeper_detail ->
                ignore (launch_current_keeper_logs state ~mailbox:async_messages ~intent:Snapshot_read.Refresh);
                refresh_keeper_detail_selection state
                  ~mailbox:async_messages
            | Board ->
                (match state.board_mode with
                 | Board_read post_id ->
                     owe_board_post_read state ~mailbox:async_messages ~post_id
                 | Board_list | Board_compose -> ())
            | Keepers Keeper_message ->
                (match state.msg_target_keeper_name with
                 | Some keeper_name ->
                     launch_keeper_history_load ~force:true ~load_file_changes:false state
                       ~mailbox:async_messages ~keeper_name;
                     launch_keeper_chat_tool_details_load ~force:true state
                       ~mailbox:async_messages ~keeper_name
                 | None -> ())
            | Verification ->
                launch_verification_load state ~mailbox:async_messages
            | Planning ->
                launch_verification_load state ~mailbox:async_messages;
                (* The open Task's history asks for its first page again, and
                   the open Goal's timeline is read again. The drawn
                   observation stays until the answer replaces it; nothing
                   else re-reads either while the authority holds. *)
                (match state.planning_mode with
                 | Planning_list ->
                     Option.iter (Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size state ~mailbox:async_messages)
                       state.task_detail_id
                 | Planning_detail goal_id ->
                     Masc_tui_work_requests.Tools_task_requests.launch_goal_timeline_load state ~mailbox:async_messages goal_id)
             | Clients -> owe_clients_read state
             | Lanes ->
                launch_lanes_reread state ~mailbox:async_messages;
                if Option.is_some state.runtime_lane_pick || Option.is_some state.slot_editor then
                  Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load ~intent:Snapshot_read.Refresh state ~mailbox:async_messages;
                (match state.lanes_mode with
                 | Lanes_run_list lane ->
                     launch_lane_runs_load state ~mailbox:async_messages
                       ~lane
                 | Lanes_run_detail (_, run_id) ->
                     launch_lane_run_detail_load state ~mailbox:async_messages
                       ~run_id
                 | Lanes_measurement_detail sha256 ->
                     launch_measurement_artifact_load state ~mailbox:async_messages
                       ~sha256
                 | Lanes_overview | Lanes_inventory_detail _ -> ())
            | Harness -> launch_harness_load state ~mailbox:async_messages
            | Fusion ->
                launch_fusion_runs_load state ~mailbox:async_messages;
                (match state.fusion_mode with
                 | Fusion_list -> ()
                 | Fusion_detail run_id ->
                     Masc_tui_work_actions.Detail_navigation.launch_fusion_detail_load state ~mailbox:async_messages ~run_id
                 | Fusion_historical_detail reference ->
                     Masc_tui_work_actions.Detail_navigation.launch_fusion_historical_detail_load state ~mailbox:async_messages ~reference)
            | Memory ->
                Masc_tui_surface_requests.Memory_repository_requests.launch_memory_health_load state ~mailbox:async_messages;
                (match state.memory_facts_keeper with
                 | Some "*" ->
                     Masc_tui_surface_requests.Memory_repository_requests.launch_all_memory_facts_load state ~mailbox:async_messages
                 | Some keeper_name ->
                     Masc_tui_surface_requests.Memory_repository_requests.launch_memory_facts_load state ~mailbox:async_messages
                       ~keeper_name
                 | None -> ())
            | Repositories ->
                Masc_tui_surface_requests.Memory_repository_requests.launch_repositories_load state ~mailbox:async_messages
            | Changes -> (
                match state.changes_keeper with
                | Some keeper_name ->
                    launch_file_changes_load state ~mailbox:async_messages
                      ~keeper_name
                | None -> ())
            | Connectors ->
                (match browser_lane_on_screen state with
                 | None -> Masc_tui_surface_requests.Connector_volume_requests.launch_connectors_load state ~mailbox:async_messages
                 | Some _ -> Masc_tui_surface_requests.Lane_browser_requests.refresh_browser_lane state ~mailbox:async_messages)
            | Runtime ->
                Masc_tui_surface_requests.Memory_repository_requests.launch_runtime_surface_load state ~mailbox:async_messages ~force:true;
                if Option.is_some state.runtime_lane_pick || Option.is_some state.slot_editor then
                  Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load ~intent:Snapshot_read.Refresh state ~mailbox:async_messages
            | Tools ->
                if Option.is_some state.tools_async_task_source then
                  Masc_tui_work_requests.Tools_task_requests.launch_tools_async_task ~terminal_size:Masc_tui_render_prim.get_terminal_size ~force:true state ~mailbox:async_messages
                else if state.tools_pane=Tools_async && state.tools_async_detail_open then
                  Masc_tui_work_requests.Tools_task_requests.launch_tools_async_detail ~force:true state ~mailbox:async_messages
                else begin
                  owe_async_requests_read state;
                  owe_tools_reads state;
                  Masc_tui_work_requests.Tools_task_requests.launch_tools_load state ~mailbox:async_messages
                end
            | Config -> (
                (* Same per-pane dispatch as goto_surface: each Config pane
                   loads its own source, so a manual refresh must not
                   quietly fall back to runtime.toml's loader for panes
                   that read somewhere else (presets, prompts, params,
                   voice). *)
                match state.config_pane with
                | Config_prompts -> Masc_tui_surface_requests.Prompt_preset_requests.launch_prompts_load state ~mailbox:async_messages
                | Config_presets -> Masc_tui_surface_requests.Prompt_preset_requests.launch_presets_load state ~mailbox:async_messages
                | Config_params ->
                    Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_params_load state ~mailbox:async_messages
                | Config_voice ->
                    Masc_tui_work_requests.Voice_requests.launch_voice_config_load state ~mailbox:async_messages
                | Config_runtime | Config_models | Config_themes ->
                    Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_config_load ~force:true state ~mailbox:async_messages)
            | Resources ->
                launch_resources_load state ~mailbox:async_messages
            | Schedules -> Masc_tui_work_requests.Schedule_call_requests.launch_schedules_load state ~mailbox:async_messages
            | Keepers Keeper_runtime_pick ->
                Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load ~intent:Snapshot_read.Refresh state ~mailbox:async_messages
            | Metrics ->
                Masc_tui_surface_requests.Memory_repository_requests.launch_memory_health_load state ~mailbox:async_messages;
                Masc_tui_work_requests.Approval_gate_requests.launch_keeper_tool_modes_load state ~mailbox:async_messages
            | Overview | Acting | Approvals | System_logs -> ());
           add_event state "system" "Manual refresh"
       | Some "\t" | Some "shift-tab" ->
           cycle_surface state ~mailbox:async_messages
             ~backwards:(key = Some "shift-tab")
       (* Readonly editor preparation is the innermost cancellable intent. *)
       | Some "esc" when Option.is_some state.keeper_settings_intent ->
           Masc_tui_types.retire_keeper_settings_editor state;
           report_action state "system" "Settings editor preparation cancelled"
       (* A followed reference is the outermost thing Esc can return from, and
          the only one that knows a destination other than this surface's own
          default. Checked before the per-surface arms because those answer
          "leave this screen" with a fixed answer, and this one has the
          reader's actual origin. A surface with its own inner state to close
          -- an open detail, a preview -- is not reached this way: the follow
          landed on the row, and closing the row first would need two presses
          to undo one. *)
       | Some "esc" when Option.is_some state.followed_from ->
           (match state.followed_from with
            | None -> ()
            | Some (origin, opened) ->
                state.followed_from <- None;
                goto_surface state ~mailbox:async_messages origin;
                (match origin, opened with
                 | Board, Some post_id ->
                     open_board_post_id state ~mailbox:async_messages ~focus:Right_pane post_id
                 | (Overview | Acting | Metrics | Keepers _ | Memory | Lanes | Clients | Approvals
                   | Planning | Schedules | Verification | Harness | Fusion | Repositories | Changes
                   | Connectors | Runtime | Config | Resources | Tools | Code | System_logs), _
                 | Board, None -> ());
                (* A Home return must retain the decision's receipt or
                   failure notice; navigation is not its replacement. *)
                if origin <> Overview then report_action state "system" "back")
       | Some "esc" ->
           (* Esc goes back *)
           (* A running preview is the innermost thing Esc can go back from:
              the reader is looking at a scheme they have not picked, and the
              way out is the one they walked in with. Without this the preview
              is not a preview -- moving the cursor would be a decision. *)
           (match state.view with
            | Config
              when state.config_pane = Config_themes
                   && state.theme_before_preview <> None ->
                cancel_theme_preview state
            | Code ->
                step_code_back state ~mailbox:async_messages
                  ~leave:(fun () ->
                    (* Off-ring child: the way out of the project root is the
                       ring parent, loaded, same as Connectors and Lanes. *)
                    goto_surface state ~mailbox:async_messages Repositories)
            | Keepers Keeper_detail ->
                state.detail_focus_recovery <- None;
                transition_keeper_view state (Keepers Keeper_list);
                state.detail_scroll <- 0
            (* The picker's own arm takes Esc. *)
            | Keepers Keeper_runtime_pick -> ()
            | Keepers Keeper_logs ->
                state.view <- Keepers Keeper_detail;
                state.keeper_detail_focus <- Right_pane;
                state.log_scroll <- 0;
                state.detail_scroll <- 0
            | Keepers Keeper_calls ->
                state.view <- Keepers Keeper_detail;
                state.keeper_detail_focus <- Right_pane;
                state.keeper_calls_scroll <- 0;
                state.detail_scroll <- 0
            (* Esc on this surface never arrives here: the composer takes it
               first ([handle_message_key], which the dispatch above routes
               every key to while the chat is open) and answers it there,
               interrupt included. *)
            | Keepers Keeper_message -> ()
            | Board ->
                (match state.board_mode with
                 | Board_read _ ->
                     Masc_tui_board_updates.leave_board_detail state
                 | Board_list -> state.view <- Overview
                 | Board_compose -> ())
            | Planning ->
                (match state.planning_mode with
                 | Planning_detail _ ->
                     state.planning_mode <- Planning_list;
                     state.planning_scroll <- Planning_scroll_offset 0
                 | Planning_list when Option.is_some state.task_detail_id ->
                     state.task_detail_id <- None;
                     reset_task_detail_scroll state
                 | Planning_list
                   when Masc_tui_overview_tasks.is_focused state.task_focus ->
                     state.task_focus <- Masc_tui_overview_tasks.No_task_focus
                 | Planning_list -> state.view <- Overview)
            | Fusion ->
                (match state.fusion_mode with
                 | Fusion_detail _ | Fusion_historical_detail _ ->
                     state.fusion_mode <- Fusion_list;
                     state.fusion_scroll <- 0;
                     state.fusion_detail <- None;
                     state.fusion_detail_stale <- false;
                     state.fusion_detail_error <- None;
                     state.fusion_detail_generation <-
                       state.fusion_detail_generation + 1
                 | Fusion_list ->
                     goto_surface state ~mailbox:async_messages Overview)
            | Overview ->
                (* Dashboard holds no list or detail to back out of: Work owns
                   the task list and its detail. *)
                ()
            | Schedules ->
                if Option.is_some state.schedule_detail_id then begin
                  state.schedule_detail_id <- None;
                  state.schedule_scroll <- 0
                end
                else goto_surface state ~mailbox:async_messages Planning
            | Verification ->
                if Option.is_some state.verification_detail_request_id then begin
                  Masc_tui_work_actions.Verification_actions.cancel_verification_evidence_load state
                    ~reason:(Verification_evidence_read.Interrupted "The original verification detail was closed.");
                  state.verification_detail_request_id <- None;
                  state.verification_detail_scroll <- 0
                end
                else goto_surface state ~mailbox:async_messages Planning
            | Harness ->
                if Option.is_some state.harness_detail then begin
                  state.harness_detail <- None;
                  state.harness_detail_scroll <- 0
                end
                else goto_surface state ~mailbox:async_messages Planning
            | Resources ->
                if state.resource_focus = Right_pane then
                  state.resource_focus <- Left_pane
                else
                  goto_surface state ~mailbox:async_messages
                    (Masc_tui_surface_navigation.surface_ring_family state.view)
             | Clients ->
                 goto_surface state ~mailbox:async_messages
                   (Masc_tui_surface_navigation.surface_ring_family state.view)
             | Lanes ->
                state.lanes_action_error <- None;
                (match state.lanes_mode with
                 | Lanes_measurement_detail _ | Lanes_inventory_detail _ ->
                     state.lanes_mode <- Lanes_overview;
                     state.measurement_report <- None;
                     state.lane_run_detail_error <- None;
                     state.lane_run_detail_scroll <- 0
                 | Lanes_run_detail (lane, _) -> close_lane_run_detail state ~lane
                 | Lanes_run_list _ ->
                     state.lanes_mode <- Lanes_overview;
                     state.lane_runs <- None;
                     state.lane_runs_error <- None;
                     state.lane_runs_cursor <- 0;
                     state.lane_runs_scroll <- 0
                 | Lanes_overview ->
                     (* Lanes is a primary surface; Esc returns to the ring. *)
                     goto_surface state ~mailbox:async_messages Overview)
            | Acting | Metrics | Keepers Keeper_list ->
                state.detail_focus_recovery <- None;
                state.view <- Overview
            | Approvals ->
                (* Esc leaves the ask and returns to the list with the cursor
                   where it was, the way the Changes diff does. *)
                if state.approval_detail_open then begin
                  if not (Masc_tui_approvals_model.close_value_reading state) then begin
                    state.approval_detail_open <- false;
                    state.approval_detail_scroll <- 0
                  end
                end
                else goto_surface state ~mailbox:async_messages Planning
            | Changes ->
                (* Esc closes the open diff and leaves the list where it was,
                   so the row an operator was reading is still under the
                   cursor when they come back. *)
                if
                  Option.is_some state.changes_diff_row
                  || Option.is_some state.changes_tree_diff_path
                then begin
                  state.changes_diff_row <- None;
                  state.changes_diff_scroll <- 0;
                  state.changes_tree_diff <- None;
                  state.changes_tree_diff_error <- None;
                  state.changes_tree_diff_path <- None
                end
                else begin
                  (* Changes opens from a keeper surface, so Esc goes back to
                     the one it was opened from rather than to Overview. The
                     detail draws whoever the roster cursor names, and the
                     roster can shrink while this surface is up: with nobody
                     under the cursor the detail has nothing to draw, so the
                     way back is the roster. The chat pane demotes its own
                     return for the same reason. *)
                  let destination =
                    match state.changes_return, selected_keeper state with
                    | Changes_return_chat, (Some _ | None) ->
                        state.changes_return <- Changes_return_list;
                        Keepers Keeper_message
                    | Changes_return_detail, Some _ -> Keepers Keeper_detail
                    | Changes_return_detail, None
                    | Changes_return_list, (Some _ | None) ->
                        Keepers Keeper_list
                  in
                  transition_keeper_view state destination
                end
            | Repositories -> state.view <- Overview
            | Runtime ->
                if Option.is_some state.runtime_detail_target then begin
                  state.runtime_detail_target <- None;
                  state.runtime_detail_scroll <- 0
                end
                else goto_surface state ~mailbox:async_messages Config
            | System_logs ->
                if system_log_detail_open state then begin
                  edit_system_logs_page state (fun page -> {page with lp_detail_seq=None});
                  edit_system_logs_page state (fun page -> {page with lp_detail_scroll=0})
                end
                else
                  (* Off-ring child: the way out of the list is Activity,
                     the ring parent, same as the other hang-offs. *)
                  goto_surface state ~mailbox:async_messages Acting
            | Connectors ->
                goto_surface state ~mailbox:async_messages
                  (Masc_tui_surface_navigation.surface_ring_family state.view)
            | Memory ->
                (match memory_back state with
                 | Memory_stays -> ()
                 | Memory_leaves ->
                   match state.memory_return with
                   | None -> state.view <- Overview
                   | Some origin ->
                     state.memory_return <- None;
                     goto_surface state ~mailbox:async_messages (Keepers Keeper_list);
                     state.search <- origin.mr_search;
                     state.search_last <- origin.mr_search_last;
                     select_keeper_name state origin.mr_keeper;
                     (match selected_keeper state with
                      | Some keeper when String.equal keeper.k_name origin.mr_keeper ->
                          state.keeper_story <- Some Masc_tui_keeper_story.Memory
                      | Some _ | None -> ()))
            | Tools ->
                if Option.is_some state.tools_async_task_source then begin
                  Masc_tui_work_requests.Tools_task_requests.close_tools_async_task state;
                  Masc_tui_work_requests.Tools_task_requests.launch_tools_async_detail state ~mailbox:async_messages
                end else if state.tools_async_detail_open then begin
                  (* Back on the request list, which reads on its own pushes
                     ([launch_owed_async_requests]), with the request just
                     read on screen. *)
                  Masc_tui_work_requests.Tools_task_requests.close_tools_async_detail state;
                  follow_tools_selection state
                end else if Masc_tui_list_moves.choose_skill_again state then
                  (* From the page back to the Skill list, with the selected
                     Skill on screen again. *)
                  follow_tools_list state Masc_tui_list_moves.Tools_skills
                else goto_surface state ~mailbox:async_messages
                  (Masc_tui_surface_navigation.surface_ring_family state.view)
            | Config ->
                state.runtime_model_jump <- None;
                state.runtime_config_jump_section <- None;
                state.view <- Overview)
       | Some "left" ->
           (* Left is the non-destructive structural back key. Unlike Esc it
              never interrupts a live chat turn; it only closes a detail the
              matching Right key can open. *)
           (match state.view with
            | Code ->
                step_code_back state ~mailbox:async_messages
                  ~leave:(fun () -> ())
            | Keepers Keeper_detail ->
                state.detail_focus_recovery <- None;
                transition_keeper_view state (Keepers Keeper_list);
                state.detail_scroll <- 0
            | Keepers Keeper_logs | Keepers Keeper_calls ->
                state.view <- Keepers Keeper_detail;
                state.keeper_detail_focus <- Right_pane;
                state.log_scroll <- 0;
                state.keeper_calls_scroll <- 0;
                state.detail_scroll <- 0
            | Board ->
                (match state.board_mode with
                 | Board_read _ -> Masc_tui_board_updates.leave_board_detail state
                 | Board_list | Board_compose -> ())
            | Planning ->
                (match state.planning_mode with
                 | Planning_detail _ ->
                     state.planning_mode <- Planning_list;
                     state.planning_scroll <- Planning_scroll_offset 0
                 | Planning_list when Option.is_some state.task_detail_id ->
                     (* The Task detail is the second detail Work owns, and its
                        footer says [Left / Esc:back]. Esc closes it the same
                        way in the arm for Esc above. *)
                     state.task_detail_id <- None;
                     reset_task_detail_scroll state
                 | Planning_list -> ())
            | Fusion ->
                (match state.fusion_mode with
                 | Fusion_detail _ | Fusion_historical_detail _ ->
                     state.fusion_mode <- Fusion_list;
                     state.fusion_scroll <- 0;
                     state.fusion_detail <- None;
                     state.fusion_detail_stale <- false;
                     state.fusion_detail_error <- None;
                     state.fusion_detail_generation <-
                       state.fusion_detail_generation + 1
                 | Fusion_list -> ())
            | Overview -> ()
            | Schedules ->
                state.schedule_detail_id <- None;
                state.schedule_scroll <- 0
            | Verification ->
                Masc_tui_work_actions.Verification_actions.cancel_verification_evidence_load state
                  ~reason:(Verification_evidence_read.Interrupted "The original verification detail was closed.");
                state.verification_detail_request_id <- None;
                state.verification_detail_scroll <- 0
            | Harness ->
                state.harness_detail <- None;
                state.harness_detail_scroll <- 0
            | Resources -> state.resource_focus <- Left_pane
            | Changes ->
                state.changes_diff_row <- None;
                state.changes_diff_scroll <- 0;
                state.changes_tree_diff <- None;
                state.changes_tree_diff_error <- None;
                state.changes_tree_diff_path <- None
            | Lanes when Option.is_some state.slot_editor ->
                (* The slot editor covers the screen it was opened from.
                   Closing that screen under it would send the editor's Esc
                   to the overview instead of back where it opened. *)
                ()
            | Lanes ->
                (* Left closes a drill-down level but never leaves the surface;
                   Esc owns leaving it. *)
                (match state.lanes_mode with
                 | Lanes_measurement_detail _ | Lanes_inventory_detail _ ->
                     state.lanes_mode <- Lanes_overview;
                     state.measurement_report <- None;
                     state.lane_run_detail_error <- None;
                     state.lane_run_detail_scroll <- 0
                 | Lanes_run_detail (lane, _) -> close_lane_run_detail state ~lane
                 | Lanes_run_list _ ->
                     state.lanes_mode <- Lanes_overview;
                     state.lane_runs <- None;
                     state.lane_runs_error <- None;
                     state.lane_runs_cursor <- 0;
                     state.lane_runs_scroll <- 0
                 | Lanes_overview -> ())
            | Runtime ->
                state.runtime_detail_target <- None;
                state.runtime_detail_scroll <- 0
            | System_logs ->
                edit_system_logs_page state (fun page -> {page with lp_detail_seq=None});
                edit_system_logs_page state (fun page -> {page with lp_detail_scroll=0})
            | Keepers Keeper_runtime_pick | Keepers Keeper_message
            | Keepers Keeper_list | Acting | Metrics | Approvals
             | Memory | Repositories | Connectors | Config | Tools | Clients -> ())
       | Some "j" | Some "down" | Some "wheel-down" ->
           (match state.view with
            | Code ->
                if state.code_focus_file = Right_pane then (
                  if state.code_notes_open then (
                    let count, height = Masc_tui_render_code.code_notes_viewport state in
                    state.code_notes_scroll <-
                      Masc_tui_scroll.down ~count ~height state.code_notes_scroll)
                  else if state.code_diff_open then (
                    Option.iter (fun (count, height) ->
                      state.code_diff_scroll <-
                        Masc_tui_scroll.down ~count ~height state.code_diff_scroll)
                      (Masc_tui_render_code.code_diff_viewport state))
                  else if state.code_history_open then (
                    let count, _ = Masc_tui_render_code.code_history_viewport state in
                    state.code_history_scroll <-
                      Masc_tui_scroll.down ~count ~height:1 state.code_history_scroll)
                  (* The open file's rows, or nothing while it is read
                     or failed: the walk's row list says which. *)
                  else move_list state Masc_tui_scroll.Line_down)
                else move_list state Masc_tui_scroll.Line_down
            | Keepers Keeper_list -> move_list state Masc_tui_scroll.Line_down
            | Keepers Keeper_detail ->
                if
                  Masc_tui_roster_pane.arrows_go_left
                    ~hidden:(roster_pane_hidden state) ~cols:terminal_columns
                    ~preferring_left:(state.keeper_detail_focus = Left_pane)
                then begin
                  state.keeper_cursor <-
                    Masc_tui_scroll.cursor_down
                      ~count:(List.length state.keepers)
                      state.keeper_cursor;
                  state.detail_scroll <- 0;
                  refresh_keeper_detail_selection state
                    ~mailbox:async_messages
                end
                else if state.detail_tab = Detail_items then begin
                  move_item_browser state ~delta:1
                end
                else if state.detail_tab = Detail_identity then
                  move_identity_cursor state ~delta:1
                else if state.detail_tab = Detail_channels then begin
                  let count =
                    match state.connectors with
                    | None -> 0
                    | Some snapshot -> List.length snapshot.cs_connectors
                  in
                  state.connectors_cursor <-
                    Masc_tui_scroll.cursor_down ~count state.connectors_cursor;
                  state.connectors_binding_cursor <- 0;
                  state.detail_scroll <- 0
                end
                else if state.detail_tab = Detail_terminal then
                  Masc_tui_types.move_keeper_terminal state ~by:(-1)
                else state.detail_scroll <- Masc_tui_types.scroll_down_from state.detail_scroll ~by:1
            | Keepers Keeper_logs ->
                state.log_scroll <-
                  Metrics_tail.scroll_down
                    ~entry_count:(keeper_log_row_count state)
                    ~content_height:(keeper_log_content_height state)
                    state.log_scroll
            | Keepers Keeper_calls ->
                state.keeper_calls_scroll <- Masc_tui_types.scroll_down_from state.keeper_calls_scroll ~by:1
            | Config when state.config_pane = Config_themes ->
                let last = List.length (filtered_theme_entries state) - 1 in
                state.theme_cursor <- min (max 0 last) (state.theme_cursor + 1);
                preview_theme_under_cursor state
            | Config when state.config_pane = Config_presets ->
                let count = List.length (Masc_tui_surface_requests.Prompt_preset_requests.preset_rows_for_state state) in
                if state.presets_cursor < count - 1 then begin
                  state.presets_cursor <- state.presets_cursor + 1;
                  state.config_scroll <- 0;
                  (* The next frame measures the new document; until then a
                     notch goes to the list. *)
                  state.config_document_max_scroll <- 0;
                  state.preset_armed <- None;
                  Masc_tui_surface_requests.Prompt_preset_requests.ensure_preset_detail state ~mailbox:async_messages
                end
            | Config when state.config_pane = Config_prompts ->
                let count = Masc_tui_surface_requests.Prompt_preset_requests.prompt_catalog_count_for_state state in
                if state.prompts_cursor < count - 1 then begin
                  state.prompts_cursor <- state.prompts_cursor + 1;
                  state.config_scroll <- 0;
                  state.prompts_librarian_input <- None;
                  state.prompts_librarian_input_error <- None;
                  state.prompts_librarian_input_loading <- false
                end
            | Config when state.config_pane = Config_params ->
                let next_cursor =
                  min
                    (max 0 (Option.fold ~none:0 ~some:List.length state.runtime_params - 1))
                    (state.runtime_params_cursor + 1) in
                if next_cursor <> state.runtime_params_cursor then begin
                  state.runtime_params_cursor <- next_cursor;
                  state.config_scroll <- 0;
                  (* The next frame measures the new document; until then a
                     notch goes to the list. *)
                  state.config_document_max_scroll <- 0;
                  state.runtime_params_notice <- None
                end
            | Approvals when state.approval_detail_open ->
                Option.iter (fun viewport ->
                  ignore (Masc_tui_approvals_model.step_detail state ~forward:true
                    ~count:viewport.adv_count ~height:viewport.adv_height))
                  (approval_detail_viewport_of_reader (!presented).reader)
            | Approvals ->
                let count = List.length (Masc_tui_approvals_model.approval_items state) in
                if state.approval_cursor < count - 1 then begin
                  state.pending_approval_action <- None;
                  state.approval_cursor <- state.approval_cursor + 1
                end
            | Board ->
                (match state.board_mode with
                 | Board_list -> move_list state Masc_tui_scroll.Line_down
                 | Board_read post_id ->
                     (match Masc_tui_types.board_read_focus state ~cols:terminal_columns with
                      | Left_pane ->
                          move_board_posts_pane state ~mailbox:async_messages
                            ~delta:1
                      | Right_pane ->
                          step_board_reading state ~post_id
                            ~by_wheel:(key = Some "wheel-down") ~delta:1)
                 | Board_compose -> ())
            | Planning ->
                (match state.planning_mode with
                 | Planning_list
                   when Masc_tui_overview_tasks.is_focused state.task_focus ->
                     if Option.is_some (task_detail_on_screen state) then begin
                       move_task_detail
                         (Masc_tui_types.scroll_down_from state.task_detail_scroll ~by:1)
                     end else
                       task_list_user_focus state (
                         Masc_tui_overview_tasks.move state.tasks state.task_focus
                           Masc_tui_overview_tasks.Next)
                 | Planning_list -> move_list state Masc_tui_scroll.Line_down
                 | Planning_detail _ ->
                     state.planning_scroll <- Planning_scroll_offset
                       (Masc_tui_types.scroll_down_from (planning_scroll_value state.planning_scroll) ~by:1))
            | Fusion ->
                (match state.fusion_mode with
                 | Fusion_list -> move_list state Masc_tui_scroll.Line_down
                 | Fusion_detail _ | Fusion_historical_detail _ ->
                     state.fusion_scroll <- Masc_tui_types.scroll_down_from state.fusion_scroll ~by:1)
            | Schedules ->
                if Option.is_some (Masc_tui_work_actions.Board_schedule_actions.schedule_detail_on_screen state) then
                  state.schedule_scroll <- Masc_tui_types.scroll_down_from state.schedule_scroll ~by:1
                else move_list state Masc_tui_scroll.Line_down
            | Overview -> ()
            | Verification ->
                if Option.is_some state.verification_detail_request_id then
                  state.verification_detail_scroll <-
                    Masc_tui_types.scroll_down_from state.verification_detail_scroll ~by:1
                else
                  move_list state Masc_tui_scroll.Line_down
            | Clients ->
                move_list state Masc_tui_scroll.Line_down
            | Lanes ->
                (match state.lanes_mode with
                 | Lanes_run_detail _ | Lanes_measurement_detail _ | Lanes_inventory_detail _ ->
                     state.lane_run_detail_scroll <-
                       Masc_tui_types.scroll_down_from state.lane_run_detail_scroll ~by:1
                 | Lanes_run_list _ ->
                     (let cursor, scroll =
                        move_row_cursor state ~delta:1
                          ~cursor:state.lane_runs_cursor
                          ~scroll:state.lane_runs_scroll
                      in
                     state.lane_runs_cursor <- cursor;
                     state.lane_runs_scroll <- scroll)
                 | Lanes_overview -> move_list state Masc_tui_scroll.Line_down)
            | Harness ->
                if Option.is_some state.harness_detail then
                  state.harness_detail_scroll <- Masc_tui_types.scroll_down_from state.harness_detail_scroll ~by:1
                else
                  move_list state Masc_tui_scroll.Line_down
            (* Memory's row list is the facts of the Keeper open in it, or
               the health rows when none is. *)
            | Memory -> move_list state Masc_tui_scroll.Line_down
            | Repositories ->
                move_list state Masc_tui_scroll.Line_down
            | Changes -> (
                (* An open diff owns the scroll keys: the list is behind it and
                   moving both would put the cursor somewhere the operator
                   cannot see. *)
                match state.changes_diff_row with
                | Some _ ->
                    state.changes_diff_scroll <- Masc_tui_types.scroll_down_from state.changes_diff_scroll ~by:1
                | None ->
                    move_list state Masc_tui_scroll.Line_down)
            | Connectors ->
                move_list state Masc_tui_scroll.Line_down
            | Runtime ->
                if Option.is_some state.runtime_detail_target then
                  state.runtime_detail_scroll <- Masc_tui_types.scroll_down_from state.runtime_detail_scroll ~by:1
                else
                  move_list state Masc_tui_scroll.Line_down
            (* The Skill list and the request list move their selection; the
               readings scroll. The wheel scrolls the page in both focuses,
               so the tool table under the Skill list is in its reach. *)
            | Tools
              when Option.is_some (Masc_tui_list_moves.tools_list state)
                   && key <> Some "wheel-down" ->
                move_list state Masc_tui_scroll.Line_down
            | Tools ->
                let count, height = tools_scroll_viewport state in
                move_tools_task (Masc_tui_scroll.down ~count ~height state.tools_scroll)
            (* A cursor, not a bare scroll: [e] acts on a row, so the reader
               has to be able to say which one. The window moves only when
               the row leaves it, so the column names stay. *)
            | Config when state.config_pane = Config_models ->
                move_list state Masc_tui_scroll.Line_down
            | Config when state.config_pane = Config_runtime ->
                move_runtime_config_cursor state ~delta:1
            (* The frame counts the voice lines and reports the offset back. *)
            | Config when state.config_pane = Config_voice ->
                state.config_scroll <-
                  Masc_tui_types.scroll_down_from state.config_scroll ~by:1
            | Config -> state.config_scroll <-
                  move_surface_scroll state ~rows:(surface_rows state) ~delta:1
                    ~current:state.config_scroll
            | Resources ->
                if state.resource_focus = Right_pane then
                  move_resource_document state (Masc_tui_scroll.Position.By 1)
                else
                  move_list state Masc_tui_scroll.Line_down
            | Acting -> state.acting_scroll <- Masc_tui_types.scroll_down_from state.acting_scroll ~by:1
            | Metrics ->
                state.metrics_scroll <-
                  Masc_tui_types.scroll_down_from state.metrics_scroll ~by:1
            | System_logs ->
                if system_log_detail_open state then
                  edit_system_logs_page state (fun page -> {page with lp_detail_scroll=
                    Masc_tui_types.scroll_down_from page.lp_detail_scroll ~by:1})
                else
                  move_list state Masc_tui_scroll.Line_down
            (* The picker's own arm takes these keys. *)
            | Keepers Keeper_runtime_pick -> ()
            | Keepers Keeper_message -> ())
       | Some "k" | Some "up" | Some "wheel-up" ->
           (match state.view with
            | Code ->
                if state.code_focus_file = Right_pane then (
                  if state.code_notes_open then (
                    let count, height = Masc_tui_render_code.code_notes_viewport state in
                    state.code_notes_scroll <-
                      Masc_tui_scroll.up ~count ~height state.code_notes_scroll)
                  else if state.code_diff_open then (
                    Option.iter (fun (count, height) ->
                      state.code_diff_scroll <-
                        Masc_tui_scroll.up ~count ~height state.code_diff_scroll)
                      (Masc_tui_render_code.code_diff_viewport state))
                  else if state.code_history_open then (
                    let count, _ = Masc_tui_render_code.code_history_viewport state in
                    state.code_history_scroll <-
                      Masc_tui_scroll.up ~count ~height:1 state.code_history_scroll)
                  (* The open file's rows, or nothing while it is read
                     or failed: the walk's row list says which. *)
                  else move_list state Masc_tui_scroll.Line_up)
                else move_list state Masc_tui_scroll.Line_up
            | Keepers Keeper_list -> move_list state Masc_tui_scroll.Line_up
            | Keepers Keeper_detail ->
                if
                  Masc_tui_roster_pane.arrows_go_left
                    ~hidden:(roster_pane_hidden state) ~cols:terminal_columns
                    ~preferring_left:(state.keeper_detail_focus = Left_pane)
                then begin
                  state.keeper_cursor <-
                    Masc_tui_scroll.cursor_up
                      ~count:(List.length state.keepers)
                      state.keeper_cursor;
                  state.detail_scroll <- 0;
                  refresh_keeper_detail_selection state
                    ~mailbox:async_messages
                end
                else if state.detail_tab = Detail_items then begin
                  move_item_browser state ~delta:(-1)
                end
                else if state.detail_tab = Detail_identity then
                  move_identity_cursor state ~delta:(-1)
                else if state.detail_tab = Detail_channels then begin
                  let count =
                    match state.connectors with
                    | None -> 0
                    | Some snapshot -> List.length snapshot.cs_connectors
                  in
                  state.connectors_cursor <-
                    Masc_tui_scroll.cursor_up ~count state.connectors_cursor;
                  state.connectors_binding_cursor <- 0;
                  state.detail_scroll <- 0
                end
                else if state.detail_tab = Detail_terminal then
                  Masc_tui_types.move_keeper_terminal state ~by:1
                else if state.detail_scroll > 0 then
                  state.detail_scroll <- state.detail_scroll - 1
            | Keepers Keeper_logs ->
                state.log_scroll <-
                  Metrics_tail.scroll_up
                    ~entry_count:(keeper_log_row_count state)
                    ~content_height:(keeper_log_content_height state)
                    state.log_scroll
            | Keepers Keeper_calls ->
                if state.keeper_calls_scroll > 0 then
                  state.keeper_calls_scroll <- state.keeper_calls_scroll - 1
            | Config when state.config_pane = Config_themes ->
                state.theme_cursor <- max 0 (state.theme_cursor - 1);
                preview_theme_under_cursor state
            | Config when state.config_pane = Config_presets ->
                let next = max 0 (state.presets_cursor - 1) in
                if next <> state.presets_cursor then begin
                  state.presets_cursor <- next;
                  state.config_scroll <- 0;
                  (* The next frame measures the new document; until then a
                     notch goes to the list. *)
                  state.config_document_max_scroll <- 0;
                  state.preset_armed <- None;
                  Masc_tui_surface_requests.Prompt_preset_requests.ensure_preset_detail state ~mailbox:async_messages
                end
            | Config when state.config_pane = Config_prompts ->
                let next = max 0 (state.prompts_cursor - 1) in
                if next <> state.prompts_cursor then begin
                  state.prompts_cursor <- next;
                  state.config_scroll <- 0;
                  state.prompts_librarian_input <- None;
                  state.prompts_librarian_input_error <- None;
                  state.prompts_librarian_input_loading <- false
                end
            | Config when state.config_pane = Config_params ->
                let next_cursor = max 0 (state.runtime_params_cursor - 1) in
                if next_cursor <> state.runtime_params_cursor then begin
                  state.runtime_params_cursor <- next_cursor;
                  state.config_scroll <- 0;
                  (* The next frame measures the new document; until then a
                     notch goes to the list. *)
                  state.config_document_max_scroll <- 0;
                  state.runtime_params_notice <- None
                end
            | Approvals when state.approval_detail_open ->
                Option.iter (fun viewport ->
                  ignore (Masc_tui_approvals_model.step_detail state ~forward:false
                    ~count:viewport.adv_count ~height:viewport.adv_height))
                  (approval_detail_viewport_of_reader (!presented).reader)
            | Approvals ->
                if state.approval_cursor > 0 then begin
                  state.pending_approval_action <- None;
                  state.approval_cursor <- state.approval_cursor - 1
                end
            | Board ->
                (match state.board_mode with
                 | Board_list -> move_list state Masc_tui_scroll.Line_up
                 | Board_read post_id ->
                     (match Masc_tui_types.board_read_focus state ~cols:terminal_columns with
                      | Left_pane ->
                          move_board_posts_pane state ~mailbox:async_messages
                            ~delta:(-1)
                      | Right_pane ->
                          step_board_reading state ~post_id
                            ~by_wheel:(key = Some "wheel-up") ~delta:(-1))
                 | Board_compose -> ())
            | Planning ->
                (match state.planning_mode with
                 | Planning_list
                   when Masc_tui_overview_tasks.is_focused state.task_focus ->
                     if Option.is_some (task_detail_on_screen state) then begin
                       move_task_detail (max 0 (state.task_detail_scroll - 1))
                     end else
                       task_list_user_focus state (
                         Masc_tui_overview_tasks.move state.tasks state.task_focus
                           Masc_tui_overview_tasks.Previous)
                 | Planning_list -> move_list state Masc_tui_scroll.Line_up
                 | Planning_detail _ ->
                     state.planning_scroll <- Planning_scroll_offset
                       (max 0 (planning_scroll_value state.planning_scroll - 1)))
            | Fusion ->
                (match state.fusion_mode with
                 | Fusion_list -> move_list state Masc_tui_scroll.Line_up
                 | Fusion_detail _ | Fusion_historical_detail _ ->
                     if state.fusion_scroll > 0 then
                       state.fusion_scroll <- state.fusion_scroll - 1)
            | Schedules ->
                if Option.is_some (Masc_tui_work_actions.Board_schedule_actions.schedule_detail_on_screen state) then
                  state.schedule_scroll <- max 0 (state.schedule_scroll - 1)
                else move_list state Masc_tui_scroll.Line_up
            | Overview -> ()
            | Verification ->
                if Option.is_some state.verification_detail_request_id then
                  state.verification_detail_scroll <-
                    max 0 (state.verification_detail_scroll - 1)
                else
                  move_list state Masc_tui_scroll.Line_up
            | Clients ->
                move_list state Masc_tui_scroll.Line_up
            | Lanes ->
                (match state.lanes_mode with
                 | Lanes_run_detail _ | Lanes_measurement_detail _ | Lanes_inventory_detail _ ->
                     state.lane_run_detail_scroll <-
                       max 0 (state.lane_run_detail_scroll - 1)
                 | Lanes_run_list _ ->
                     (let cursor, scroll =
                        move_row_cursor state ~delta:(-1)
                          ~cursor:state.lane_runs_cursor
                          ~scroll:state.lane_runs_scroll
                      in
                     state.lane_runs_cursor <- cursor;
                     state.lane_runs_scroll <- scroll)
                 | Lanes_overview -> move_list state Masc_tui_scroll.Line_up)
            | Harness ->
                if Option.is_some state.harness_detail then
                  state.harness_detail_scroll <-
                    max 0 (state.harness_detail_scroll - 1)
                else
                  move_list state Masc_tui_scroll.Line_up
            (* Memory's row list is the facts of the Keeper open in it, or
               the health rows when none is. *)
            | Memory -> move_list state Masc_tui_scroll.Line_up
            | Repositories ->
                move_list state Masc_tui_scroll.Line_up
            | Changes -> (
                match state.changes_diff_row with
                | Some _ ->
                    state.changes_diff_scroll <-
                      max 0 (state.changes_diff_scroll - 1)
                | None ->
                    move_list state Masc_tui_scroll.Line_up)
            | Connectors ->
                move_list state Masc_tui_scroll.Line_up
            | Runtime ->
                if Option.is_some state.runtime_detail_target then
                  state.runtime_detail_scroll <-
                    max 0 (state.runtime_detail_scroll - 1)
                else
                  move_list state Masc_tui_scroll.Line_up
            | Tools
              when Option.is_some (Masc_tui_list_moves.tools_list state)
                   && key <> Some "wheel-up" ->
                move_list state Masc_tui_scroll.Line_up
            | Tools ->
                if state.tools_scroll > 0 || tools_task_following_end state then begin
                  let count, height = tools_scroll_viewport state in
                  move_tools_task (Masc_tui_scroll.up ~count ~height state.tools_scroll)
                end
            | Config when state.config_pane = Config_models ->
                move_list state Masc_tui_scroll.Line_up
            | Config when state.config_pane = Config_runtime ->
                move_runtime_config_cursor state ~delta:(-1)
            | Config when state.config_pane = Config_voice ->
                state.config_scroll <- max 0 (state.config_scroll - 1)
            | Config ->
                if state.config_scroll > 0 then
                  state.config_scroll <-
                  move_surface_scroll state ~rows:(surface_rows state) ~delta:(-1)
                    ~current:state.config_scroll
            | Resources ->
                if state.resource_focus = Right_pane then
                  move_resource_document state (Masc_tui_scroll.Position.By (-1))
                else move_list state Masc_tui_scroll.Line_up
            | Metrics ->
                state.metrics_scroll <- max 0 (state.metrics_scroll - 1)
            | Acting ->
                if state.acting_scroll > 0 then begin
                  state.acting_scroll <- state.acting_scroll - 1;
                  if state.acting_scroll = 0 then state.acting_unseen <- 0
                end
            | System_logs ->
                if system_log_detail_open state then
                  edit_system_logs_page state (fun page -> {page with lp_detail_scroll=
                    max 0 (page.lp_detail_scroll - 1)})
                else
                  move_list state Masc_tui_scroll.Line_up
            (* The picker's own arm takes these keys. *)
            | Keepers Keeper_runtime_pick -> ()
            | Keepers Keeper_message -> ())
       (* Enter starts the provider the arrows are on. The digits below still
          work for the first nine; past that a number is no longer a key, so
          the cursor is the only way to reach a row. *)
       | Some "\r" | Some "\n"
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_identity ->
           Masc_tui_identity_input.start_cursor state
             ~login:(fun ~keeper_name ~provider_id ~label -> Masc_tui_identity_requests.launch_login state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.workspace_enqueue state async_messages) ~fork:(Masc_tui_transport.Workspace_admission.fork_job state ~mailbox:async_messages) ~keeper_name ~provider_id ~label)
       | Some "\r" | Some "\n" | Some "right" ->
           (* Enter remains compatible; Right makes list -> detail and Left
              makes detail -> list consistent across the TUI. *)
           (match state.view with
            | Code -> (
                if state.code_history_open && state.code_focus_file = Right_pane then (
                  (* The top visible row is the selected one, the way the
                     Changes list treats its scroll. A commit answers with
                     its PR; a durable Keeper change jumps to its
                     producer-recorded line without claiming it was
                     committed. *)
                  match Masc_tui_fetched.current state.code_history with
                  | Some (_, Masc_tui_fetched.Ready _) -> (
                      match
                        Masc_tui_render_code.code_history_selected state
                      with
                      | None -> ()
                      | Some (Hist_keeper_change change) -> (
                          match Masc_tui_fetched.current state.code_file with
                          | Some (_, Masc_tui_fetched.Ready { cfd_rows = rows; _ }) ->
                            Code_results.push_code_jump state;
                            state.code_history_open <- false;
                            let cursor =
                              max 0
                                (min
                                   (Masc.Tui_decode.file_change_target_line change
                                    - 1)
                                   (Array.length rows - 1))
                            in
                            state.code_file_cursor <- cursor;
                            state.code_file_scroll <-
                              Masc_tui_scroll.ensure_visible ~cursor
                                ~height:
                                  (Masc_tui_render_code.code_pane_content_height state)
                                state.code_file_scroll
                          (* No rows on screen to jump within. *)
                          | Some (_, Goal_confirmation_read.Absent) | None
                          | Some (_, Goal_confirmation_read.Loading)
                          | Some (_, Goal_confirmation_read.Stale (_, _))
                          | Some (_, Goal_confirmation_read.Failed _) -> ())
                      | Some (Hist_commit row) ->
                          let open Masc.Tui_decode in
                          state.code_lsp_note <-
                            Some
                              (match pr_number_of_subject row.gl_subject with
                               | None ->
                                   Code_note_no_pr_number row.gl_hash
                               | Some number -> (
                                   let remote =
                                     match state.code_scope with
                                     | Code_scope_repo repo_id -> (
                                         match state.repositories with
                                         | None -> None
                                         | Some snapshot ->
                                             Option.map
                                               (fun r -> r.rp_url)
                                               (List.find_opt
                                                  (fun r ->
                                                    String.equal r.rp_id
                                                      repo_id)
                                                  snapshot.rs_repositories))
                                     | Code_scope_keeper _
                                     | Code_scope_project -> None
                                   in
                                   match remote with
                                   | None ->
                                       Code_note_pr_without_remote number
                                   | Some remote -> (
                                       match
                                         Masc_tui_pr_ref.github_pr_url ~remote
                                           ~number
                                       with
                                       | Some url -> Code_note_pr_link url
                                       | None -> Code_note_pr_remote_not_github number))))
                  (* Nothing listed to jump from. *)
                  | Some (_, Goal_confirmation_read.Absent) | None
                  | Some (_, Goal_confirmation_read.Loading)
                  | Some (_, Goal_confirmation_read.Stale (_, _))
                  | Some (_, Goal_confirmation_read.Failed _) -> ())
                else if state.code_focus_file = Right_pane then ()
                else
                  match List.nth_opt (code_entries state) state.code_cursor with
                  | Some node ->
                      if node.Masc.Tui_decode.wt_has_children then begin
                        state.code_dir <- node.Masc.Tui_decode.wt_path;
                        state.code_cursor <- 0;
                        state.code_listing <- Masc_tui_fetched.clear state.code_listing;
                        Masc_tui_code_requests.launch_entries_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)
                      end
                      else
                        Masc_tui_code_requests.launch_file_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)
                          ~path:node.Masc.Tui_decode.wt_path
                  | None -> ())
            (* The picker's own arm takes Enter. *)
            | Keepers Keeper_runtime_pick -> ()
            | Overview -> ()
            | Keepers Keeper_list ->
                (match selected_keeper state with
                 | Some keeper ->
                     open_keeper_detail state
                       ~mailbox:async_messages keeper
                 | None -> ())
            | Lanes ->
                (* The slot editor answers Enter over whichever screen it
                   covers, the overview or one Lane's inventory detail. *)
                (match state.slot_editor, state.runtime_lane_pick, state.lanes_mode with
                 | Some _, None, _ -> Masc_tui_editor_forms.Runtime_config_forms.open_selected_slot_config state ~mailbox:async_messages
                 | Some _, Some _, _ -> ()
                 | None, (None | Some _), Lanes_run_list lane ->
                     open_selected_lane_run state ~mailbox:async_messages ~lane
                 | None, (None | Some _),
                   (Lanes_run_detail _ | Lanes_measurement_detail _ | Lanes_inventory_detail _) -> ()
                 | None, (None | Some _), Lanes_overview ->
                     open_lane_inventory_selection state ~mailbox:async_messages)
            | Approvals ->
                (* The list draws the ask on one row; this is where the whole
                   thing is readable before [y] answers it. *)
                if List.length (Masc_tui_approvals_model.approval_items state) > 0 then begin
                  state.approval_detail_open <- true;
                  state.approval_detail_scroll <- 0
                end
            | Board ->
                (match state.board_mode with
                 | Board_list ->
                     (match List.nth_opt (board_posts state) state.board_cursor with
                      | Some p ->
                          open_board_post state ~mailbox:async_messages
                            ~focus:Right_pane p
                      | None -> ())
                 | Board_read _ | Board_compose -> ())
            | Schedules ->
                (match Masc_tui_work_actions.Board_schedule_actions.schedule_detail_on_screen state with
                 | None -> Masc_tui_work_actions.Detail_navigation.open_schedule_detail state ~mailbox:async_messages
                 | Some _ -> ())
            | Verification ->
                (match state.verification_detail_request_id with
                 | Some _ -> ()
                 | None ->
                     Masc_tui_work_actions.Detail_navigation.open_verification_detail state ~mailbox:async_messages)
            | Harness ->
                (match state.harness_detail with
                 | None -> Masc_tui_work_actions.Detail_navigation.open_harness_detail state
                 | Some _ -> ())
            | Planning ->
                (match state.planning_mode with
                 | Planning_list
                   when Masc_tui_overview_tasks.is_focused state.task_focus ->
                     (* Under task focus with no row chosen the footer says why
                        nothing opened. *)
                     (match
                        Masc_tui_overview_tasks.opening state.tasks state.task_focus
                      with
                      | Some (Masc_tui_overview_tasks.Open task) ->
                          state.task_detail_id <- Some task.id;
                          reset_task_detail_scroll state;
                          prepare_task_history_for_open state ~task_id:task.id;
                          Masc_tui_work_requests.Tools_task_requests.launch_task_history_load ~terminal_size:Masc_tui_render_prim.get_terminal_size state
                            ~mailbox:async_messages task.id
                      | Some Masc_tui_overview_tasks.No_held_task ->
                          report_action state "system"
                            "Enter: Work has no open task, so there is no row to open"
                      | Some Masc_tui_overview_tasks.No_selection ->
                          report_action state "system"
                            "Enter: no task row is chosen; j/k chooses one"
                      | None -> ())
                 | Planning_list ->
                     Masc_tui_work_actions.Detail_navigation.open_planning_detail state ~mailbox:async_messages
                 | Planning_detail _ -> ())
            | Fusion ->
                (match state.fusion_mode with
                 | Fusion_list ->
                     Masc_tui_work_actions.Detail_navigation.open_fusion_detail state ~mailbox:async_messages
                 | Fusion_detail _ | Fusion_historical_detail _ -> ())
            | Changes -> (
                (* The row under the cursor, read as the lines it removed and
                   added. Held as an index rather than a copy: a refresh
                   replaces the list, and a copy would keep drawing a change
                   the answer no longer holds. *)
                match state.changes with
                | None -> report_action state "error" "no changes loaded yet"
                | Some snapshot -> (
                    match
                      List.nth_opt snapshot.Masc.Tui_decode.fcs_changes
                        state.changes_cursor
                    with
                    | None ->
                        report_action state "error" "no change under the cursor"
                    | Some _ ->
                        state.changes_diff_row <- Some state.changes_cursor;
                        refresh_recorded_diff_bounds state ~reset:true;
                        state.changes_diff_scroll <- 0;
                        state.changes_tree_diff <- None;
                        state.changes_tree_diff_error <- None;
                        state.changes_tree_diff_path <- None))
            | Memory -> (
                match state.memory_facts_keeper with
                | Some _ ->
                    (* The browser's rows are leaves; the detail lines
                       already follow the cursor. *)
                    ()
                | None -> (
                    (* Enter opens what the health row only counts: the
                       keeper's facts themselves. *)
                    match state.memory_health with
                    | None -> ()
                    | Some _ -> (
                        match
                          selected_memory_keeper state
                        with
                        | None -> ()
                        | Some keeper ->
                            let keeper_name =
                              keeper.Masc.Tui_decode_memory_health.mkh_keeper_id
                            in
                            state.memory_facts_keeper <- Some keeper_name;
                            state.memory_facts <-
                              Masc_tui_fetched.clear state.memory_facts;
                            state.memory_facts_cursor <- 0;
                            state.memory_facts_scroll <- 0;
                            state.memory_facts_category <- Category_all;
                            Masc_tui_surface_requests.Memory_repository_requests.launch_memory_facts_load state
                              ~mailbox:async_messages ~keeper_name)))
            | Repositories -> (
                (* Enter opens the repository's own tree on the Code surface,
                   through the ?repo_id= axis its row already names. *)
                match state.repositories with
                | None -> ()
                | Some snapshot -> (
                    match
                      List.nth_opt
                        snapshot.Masc.Tui_decode.rs_repositories
                        state.repositories_cursor
                    with
                    | None -> ()
                    | Some repo ->
                        set_code_scope state
                          (Code_scope_repo repo.Masc.Tui_decode.rp_id);
                        state.code_dir <- "";
                        state.code_cursor <- 0;
                        state.code_listing <- Masc_tui_fetched.clear state.code_listing;
                        state.code_file <- Masc_tui_fetched.clear state.code_file;
                        state.code_file_resume_intent <- Refresh_code_file;
                        state.code_focus_file <- Left_pane;
                        state.view <- Code;
                        Masc_tui_code_requests.launch_entries_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)))
            | Runtime ->
                (* A media slot has no row-detail action. Its [v] reader owns
                   complete IDs/results; Enter must not open a hidden lane. *)
                if Option.is_none (Masc_tui_types.runtime_parent state) then
                  Masc_tui_types.open_runtime_row_detail state
            | System_logs -> Masc_tui_work_actions.Detail_navigation.open_selected_system_log state
            | Keepers Keeper_detail | Keepers Keeper_logs | Keepers Keeper_calls
            | Keepers Keeper_message
            | Acting | Metrics
             | Connectors | Config | Resources | Tools | Clients -> ())
       (* Changes reads one keeper's file writes and already binds to the
          roster cursor on entry, so it opens from a keeper surface rather
          than from the Tab ring. Both of them list [f] in their footer and
          both name the keeper with the same cursor; detail listed the key
          with no arm behind it, so the hint was dead there.

          One arm each rather than one arm with a disjunction, because each
          also records where Esc goes back to. *)
       | Some "f" | Some "F" when state.view = Keepers Keeper_list ->
           state.changes_return <- Changes_return_list;
           goto_surface state ~mailbox:async_messages Changes
       | Some "f" | Some "F" when state.view = Keepers Keeper_detail ->
           state.changes_return <- Changes_return_detail;
           goto_surface state ~mailbox:async_messages Changes
       | Some "f" | Some "F" when state.view = Acting ->
           state.acting_filter <- Masc_tui_acting.next_filter state.acting_filter;
           state.acting_cursor <- 0;
           state.acting_scroll <- 0;
           state.acting_unseen <- 0
       | Some "f" | Some "F"
         when state.view = Config && state.config_pane = Config_themes ->
            enter_theme_filter state
              (match state.theme_filter with
               | `All -> `Dark
               | `Dark -> `Light
               | `Light -> `All)
       | Some "f" | Some "F"
         when state.view = Board && state.board_mode <> Board_compose ->
           (* All, then each hearth the unnarrowed list showed, busiest first,
              then all again. The narrowing is the server's -- see
              [fetch_board] -- so this refetches rather than filtering the
              page in hand. *)
           state.board_hearth <-
             (if key = Some "F" then Board_hearth.previous else Board_hearth.next)
               ~current:state.board_hearth ~census:(board_census_values state);
           state.board_cursor <- 0;
           state.board_mode <- Board_list;
           report_action state "system"
             (match state.board_hearth with
              | None -> "Board: every hearth"
              | Some hearth -> "Board hearth: " ^ hearth);
           start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
             ~intent:Operator_key ~refresh_inflight:http_refresh_inflight
             ~scoped_refresh_inflight:http_scoped_refresh_inflight
             ~scoped_refresh_followup ~mailbox:async_messages
        | Some "f" | Some "F" when state.view = Planning ->
            (* Client-side over the loaded goals: no refetch. *)
            state.planning_filter <- next_planning_filter state.planning_filter;
            clamp_planning_cursor state
        | Some "g" when state.view = Approvals && state.ask_answer_mode = Ask_browsing ->
           open_answered_installation_results state ~mailbox:async_messages
        | Some "g" when state.view = Acting ->
           state.acting_cursor <- 0;
           state.acting_scroll <- 0;
           state.acting_unseen <- 0
       | Some "g"
         when (match state.view with
               | Keepers Keeper_list | Keepers Keeper_detail -> true
               | Keepers (Keeper_logs | (Keeper_calls | (Keeper_message | Keeper_runtime_pick)))
               | Overview | Acting | Metrics | Memory | Lanes | Clients | Board | Approvals
               | Planning | Schedules | Verification | Harness | Fusion | Repositories | Code
               | Changes | Connectors | Runtime | Config | Resources | Tools | System_logs -> false)
              && state.keeper_cursor < List.length state.keepers ->
           (* Toggle the approval gate for the keeper under the cursor. One
              press: the stance is in-memory and a restart returns it to
              auto, and the event line plus the red roster name say loudly
              what was armed. *)
           Option.iter
             (fun (keeper : Tui_decode.keeper) ->
               let mode =
                 if List.mem keeper.k_name state.keeper_yolo_names then
                   Masc.Keeper_tool_approval_mode.Auto
                 else Masc.Keeper_tool_approval_mode.Yolo
               in
               Masc_tui_work_requests.Approval_gate_requests.launch_keeper_tool_mode_set state ~mailbox:async_messages
                 ~keeper_name:keeper.k_name ~mode)
             (selected_keeper state)
       | Some "u" | Some "U"
         when (match state.view with
               | Keepers Keeper_list -> true
               | Keepers Keeper_detail ->
                   (* The Channels tab takes [U] for unbind-all, as it takes
                      [u] for removing one binding. *)
                   key = Some "U" && state.detail_tab <> Detail_channels
               | Keepers (Keeper_logs | (Keeper_calls | (Keeper_message | Keeper_runtime_pick)))
               | Overview | Acting | Metrics | Memory | Lanes | Clients | Board | Approvals
               | Planning | Schedules | Verification | Harness | Fusion | Repositories | Code
               | Changes | Connectors | Runtime | Config | Resources | Tools | System_logs -> false)
              && state.keeper_cursor < List.length state.keepers ->
           (* Open the runtime picker for the keeper under the cursor. The
              catalogue is fetched on open so the list reflects the server
              now, not the last visit. *)
           Option.iter
             (fun (keeper : Tui_decode.keeper) ->
               state.runtime_pick_keeper <- Some keeper.k_name;
               state.runtime_pick_list <- Masc_tui_pick_list.closed;
               Masc_tui_chat_dispatch.Chat_journals.launch_runtime_catalog_load state ~mailbox:async_messages;
               state.detail_focus_recovery <- None;
               transition_keeper_view state (Keepers Keeper_runtime_pick))
             (selected_keeper state)
       | Some "d" | Some "D"
         when state.view = Keepers Keeper_runtime_pick ->
           (match state.runtime_pick_keeper with
            | Some keeper_name ->
                if Masc_tui_chat_dispatch.Runtime_picker.launch_runtime_assignment_set state
                     ~keeper_name ~runtime_id:None then Masc_tui_chat_dispatch.Runtime_picker.close_keeper_runtime_pick state
            | None -> Masc_tui_chat_dispatch.Runtime_picker.close_keeper_runtime_pick state)
       | Some "D" when (match state.view with
           | Keepers (Keeper_list | Keeper_detail) -> true | Keepers (Keeper_logs | (Keeper_calls | (Keeper_message | Keeper_runtime_pick)))
                                                           | Overview | Acting | Metrics | Memory
                                                           | Lanes | Clients | Board | Approvals
                                                           | Planning | Schedules | Verification
                                                           | Harness | Fusion | Repositories | Code
                                                           | Changes | Connectors | Runtime | Config
                                                           | Resources | Tools | System_logs -> false) ->
           state.keeper_deletions_open <- true;
           state.keeper_deletions_scroll <- 0;
           Masc_tui_surface_requests.Keeper_surface_requests.launch_keeper_deletions state ~mailbox:async_messages ()
       (* Confirmed deletion owns shutdown and cleanup as one operation. *)
       | Some "x" | Some "X"
         when (match state.view with
               | Keepers (Keeper_list | Keeper_detail) -> true
               | Keepers (Keeper_logs | (Keeper_calls | (Keeper_message | Keeper_runtime_pick)))
               | Overview | Acting | Metrics | Memory | Lanes | Clients | Board | Approvals
               | Planning | Schedules | Verification | Harness | Fusion | Repositories | Code
               | Changes | Connectors | Runtime | Config | Resources | Tools | System_logs -> false) ->
           Masc_tui_operator_actions.Keeper_actions.handle_keeper_action state ~base_path ~mailbox:async_messages
             Keeper_control.Delete
       | Some "d"
         when (match state.view with
               | Keepers (Keeper_list | Keeper_detail) -> true
               | Keepers (Keeper_logs | (Keeper_calls | (Keeper_message | Keeper_runtime_pick)))
               | Overview | Acting | Metrics | Memory | Lanes | Clients | Board | Approvals
               | Planning | Schedules | Verification | Harness | Fusion | Repositories | Code
               | Changes | Connectors | Runtime | Config | Resources | Tools | System_logs -> false) ->
           open_repository_changes state ~mailbox:async_messages
             ~scope:Tui_decode.Repository_change_project
       | Some "d"
         when state.view = Code
              && (Masc_tui_keys.code_tree_opens_changes state.code_scope
                  && state.code_focus_file = Left_pane) ->
           open_repository_changes state ~mailbox:async_messages
             ~scope:Tui_decode.Repository_change_project
       | Some "d" when state.view = Repositories ->
             (match state.repositories with
              | None -> report_action state "error" "no repositories loaded yet"
              | Some snapshot ->
                  (match
                     List.nth_opt snapshot.Masc.Tui_decode.rs_repositories
                       state.repositories_cursor
                   with
                   | None -> report_action state "error" "no repository under the cursor"
                   | Some repo ->
                       let repository_id = repo.Masc.Tui_decode.rp_id in
                       open_repository_changes state ~mailbox:async_messages
                         ~scope:
                           (Tui_decode.Repository_change_repository
                              repository_id)))
        | Some "G" when state.view = Acting ->
            (* Past the end on purpose; the frame clamps it to the last page.
               The held count rather than max_int, because an event arriving
               before that frame adds one to it. *)
            state.acting_scroll <- List.length state.acting;
            state.acting_cursor <- max 0 (List.length (acting_flat_entries state) - 1)
        | Some ("p" | "P") when state.view = Planning ->
            goto_surface state ~mailbox:async_messages Approvals
        | Some "t" | Some "T" ->
           (* Focus Work's task list. The Goals pane owns j/k until the
              operator asks for tasks. Focus lands on the first row, so Enter
              opens something at once; pressing [t] again hands j/k back to
              Goals and lets go of the choice. *)
           (match state.view with
            | Code -> ()
            | Keepers Keeper_runtime_pick -> ()
            | Planning when state.planning_mode = Planning_list
                            && Option.is_none (task_detail_on_screen state) ->
                task_list_user_focus state
                  (Masc_tui_overview_tasks.toggle state.tasks state.task_focus)
            | Keepers (Keeper_list | Keeper_detail) ->
                (* Tool calls, from the roster and from detail, the way logs
                   are: the keeper under the cursor is the one asked about. *)
                (match selected_keeper state with
                 | Some keeper ->
                     state.keeper_calls <- None;
                     state.keeper_calls_error <- None;
                     state.keeper_calls_scroll <- 0;
                     transition_keeper_view state (Keepers Keeper_calls);
                     owe_keeper_calls_read state ~mailbox:async_messages
                       ~keeper_name:keeper.k_name
                 | None -> ())
            | Overview | Acting | Metrics | Keepers (Keeper_logs | Keeper_calls | Keeper_message)
            | Lanes | Board | Approvals | Planning | Schedules
            | Memory | Verification | Harness | Fusion | Repositories | Changes | Connectors | Runtime | Config | Resources | Tools | Clients
            | System_logs -> ())
       | Some "d" when state.view = Changes ->
           (* The same file, read from the tree instead of from the log. Two
              keys rather than one view: the log says what the keeper tried to
              write and the tree says what survived, and merging them would
              make both untrue. *)
           (match state.changes with
            | None -> report_action state "error" "no changes loaded yet"
            | Some snapshot -> (
                match
                  List.nth_opt snapshot.Masc.Tui_decode.fcs_changes
                    state.changes_cursor
                with
                | None -> report_action state "error" "no change under the cursor"
                | Some change -> (
                    match change_bundle_relative_path change with
                    | None ->
                        report_action state "error"
                          "this write is outside the playground; the tree \
                           reading needs a path under it"
                    | Some path ->
                        state.changes_diff_row <- Some state.changes_cursor;
                        refresh_recorded_diff_bounds state ~reset:true;
                        state.changes_diff_scroll <- 0;
                        state.changes_tree_diff <- None;
                        state.changes_tree_diff_error <- None;
                        state.changes_tree_diff_path <- Some path;
                        state.changes_diff_max_width <- 0;
                        launch_git_diff_load state ~mailbox:async_messages
                          ~keeper:(Some change.Masc.Tui_decode.fc_keeper) ~path)))
       | Some ("1" | "2" | "3" as digit)
         when (state.view = Planning || state.view = Verification || state.view = Harness)
              && not state.composer_focused
              && not (modal_owns_keys state) && not state.palette_open
              && not state.answering_open && not state.link_modal_open
              && Option.is_none (text_input_target state ~compact_viewport) ->
           goto_surface state ~mailbox:async_messages
             (match digit with
              | "1" -> Planning
              | "2" -> Verification
              | "3" | _ -> Harness)
       | Some "v" | Some "V"
         when state.view = Planning || state.view = Verification
              || state.view = Harness ->
           (* Work cycles from Goals through pending review to recorded verdicts. *)
           goto_surface state ~mailbox:async_messages
             (match state.view with
              | Planning -> Verification
              | Verification -> Harness
              | Harness | Overview | Acting | Metrics | Keepers _ | Memory | Lanes | Clients | Board
              | Approvals | Schedules | Fusion | Repositories | Code | Changes | Connectors
              | Runtime | Config | Resources | Tools | System_logs -> Planning)
       | Some "v" when state.view = Changes ->
           (* View the selected change on the Code surface. The clone-relative
              address resolves through the same ?keeper= axis the git-diff
              read uses, so the bytes shown are the keeper's own checkout --
              not a same-named file in the project tree. Absolute-path writes
              have no such address; the row says so instead of guessing. *)
           (match state.changes with
            | None -> report_action state "error" "no changes loaded yet"
            | Some snapshot -> (
                match
                  List.nth_opt snapshot.Masc.Tui_decode.fcs_changes
                    state.changes_cursor
                with
                | None -> report_action state "error" "no change under the cursor"
                | Some change -> (
                    match change_bundle_relative_path change with
                    | None ->
                        report_action state "error"
                          "an absolute-path write has no address in the \
                           keeper's workspace; o opens it in $EDITOR"
                    | Some path ->
                        let keeper = change.Masc.Tui_decode.fc_keeper in
                        set_code_scope state (Code_scope_keeper keeper);
                        let parent = Filename.dirname path in
                        state.code_dir <-
                          (if String.equal parent "." then "" else parent);
                        state.code_listing <- Masc_tui_fetched.clear state.code_listing;
                        state.code_cursor <- 0;
                        state.code_file <- Masc_tui_fetched.clear state.code_file;
                        state.code_file_resume_intent <- Refresh_code_file;
                        state.code_focus_file <- Left_pane;
                        state.code_target_line <-
                          Some (Masc.Tui_decode.file_change_target_line change);
                        state.view <- Code;
                        Masc_tui_code_requests.launch_entries_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages);
                        Masc_tui_code_requests.launch_file_load state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~deliver:(Masc_tui_transport.Workspace_admission.deliver_code state async_messages)
                          ~path)))
       | Some "o" | Some "O" | Some "A" when state.view = Lanes ->
           Masc_tui_surface_requests.Lane_browser_requests.launch_lane_addons state ~mailbox:async_messages
             Masc_tui_lane_addons.Inspect
       | Some "o" when state.view = Changes ->
           (* Hand the selected change to the operator's editor. The row is
              the one the list marks, which the arrow keys move. *)
           (match state.changes with
            | None -> report_action state "error" "no changes loaded yet"
            | Some snapshot -> (
                match
                  List.nth_opt snapshot.Masc.Tui_decode.fcs_changes
                    state.changes_cursor
                with
                | None -> report_action state "error" "no change under the cursor"
                | Some change -> (
                    let path = change_absolute_path ~base_path change in
                    if not (Sys.file_exists path) then
                      (* A Docker keeper's bundle is not on this filesystem.
                         Saying so beats opening an empty buffer named after a
                         file that does exist somewhere else. *)
                      report_action state "error"
                        ("not on this machine: " ^ path)
                    else
                      let line = Masc.Tui_decode.file_change_target_line change in
                      let target =
                        { Masc_tui_editor_jump.path; Masc_tui_editor_jump.line }
                      in
                      match Masc_tui_editor_jump.route () with
                      | Masc_tui_editor_jump.No_editor ->
                          report_action state "error"
                            (Masc_tui_shell.Editor_notice.editor_jump_unset state)
                      | Masc_tui_editor_jump.Remote_neovim { server } -> (
                          (* The editor is already on screen. Nothing here
                             gives up the terminal, so this surface keeps
                             drawing while the buffer opens over there. *)
                          match
                            Masc_tui_editor_jump.send_to_neovim ~server target
                          with
                          | Ok () ->
                              report_action state "system"
                                (Printf.sprintf "opened %s:%d in Neovim" path line)
                          | Error detail -> report_action state "error" detail)
                      | Masc_tui_editor_jump.Terminal_handoff { editor } ->
                          (* No editor to send to, so one is started on this
                             terminal and this surface stands down until it
                             exits -- the same handoff the settings round-trip
                             makes. *)
                          Masc_tui_shell.Terminal_session.hand_off terminal_session;
                          let command =
                            Printf.sprintf "%s +%d %s" editor line
                              (Filename.quote path)
                          in
                          let _ : Unix.process_status = Unix.system command in
                          Masc_tui_shell.Terminal_session.take_back terminal_session;
                          report_action state "system"
                            (Printf.sprintf "closed %s:%d" path line))))
       | Some ("a" | "A") when state.view = Planning
           && Option.is_some (Masc_tui_work_actions.Goal_actions.goal_detail_on_screen state) ->
           Masc_tui_work_actions.Goal_actions.handle_goal_confirmation_key state ~mailbox:async_messages
       | Some "c" | Some "C" when state.view = Board ->
           (* Reply to the post being read. Same pane as a new post; the
              reply target decides the payload and where the operator
              lands after it sends. *)
           (match state.board_mode with
            | Board_read post_id ->
                state.board_mode <- Board_compose;
                state.board_compose_armed <- false;
                state.board_compose_reply_to <- Some post_id;
                state.board_compose_hearth <- None;
                state.board_compose_attach_input <- None;
                state.board_post_error <- None;
                (match Board_detail.view_for state.board_detail ~post_id with
                 | Absent ->
                     owe_board_post_read state ~mailbox:async_messages ~post_id
                 | Loading | Ready _ | Failed _ -> ())
            | Board_list | Board_compose -> ())
       | Some "v" | Some "V" when state.view = Board ->
           (* Lowercase votes up, uppercase votes down -- the shift is the
              direction, so neither reading needs a second keypress to
              choose one. *)
           Masc_tui_work_actions.Board_schedule_actions.handle_board_vote_key state ~cols:terminal_columns ~mailbox:async_messages
             ~up:(match key with Some "v" -> true | _ -> false)
       | Some "x" | Some "X" when state.view = Schedules ->
           (* Two presses, like every irreversible action here: the first
              names the schedule, the second cancels it. Whether the row is
              still cancellable is the server's store rules to say. *)
           Masc_tui_work_actions.Board_schedule_actions.handle_schedule_cancel_key state ~mailbox:async_messages
       | Some ("o" | "O") when state.view = System_logs ->
           let source=match System_logs_view.source state.system_logs with
             | Server -> System_logs_view.This_tui | This_tui -> Server in
           state.system_logs <- System_logs_view.select source state.system_logs;
           Masc_tui_refresh_settlement.System_log_stream.refresh_client_system_logs state
       | Some ("l" | "L") when state.view = System_logs && not (system_log_detail_open state) ->
           edit_system_logs_page state (fun page -> {page with
             lp_min_level=Masc.Tui_decode.next_system_log_min_level page.lp_min_level;
             lp_scroll=0;lp_cursor=0});
           Masc_tui_refresh_settlement.System_log_stream.refresh_system_logs_source state
       | Some ("v" | "V") when state.view = System_logs && not (system_log_detail_open state) ->
           edit_system_logs_page state (fun page -> {page with
             lp_min_level=Masc.Tui_decode.toggle_system_log_verbose page.lp_min_level;
             lp_scroll=0;lp_cursor=0});
           Masc_tui_refresh_settlement.System_log_stream.refresh_system_logs_source state
       | Some ("c" | "C") when state.view = System_logs && not (system_log_detail_open state) ->
           edit_system_logs_page state (fun page ->
             let entries=match page.lp_snapshot with None -> [] | Some snapshot -> snapshot.sys_entries in
             {page with lp_category=Masc.Tui_decode.next_system_log_category
               ~current:page.lp_category entries;lp_scroll=0;lp_cursor=0})
       | Some "x" | Some "X"
         when state.view = Planning && state.planning_mode = Planning_list
              && Masc_tui_overview_tasks.is_focused state.task_focus
              && Option.is_some (task_detail_on_screen state) ->
           (* Cancel wants a reason, and $EDITOR is the form we already
              have; the editor itself is the confirmation step. *)
           Masc_tui_editor_forms.Workspace_review_forms.handle_task_cancel state ~mailbox:async_messages ~terminal_session
       | Some "x" | Some "X" when state.view = Verification ->
           (* Reject wants a reason, and $EDITOR is the form we already
              have; the editor itself is the confirmation step. *)
           Masc_tui_editor_forms.Workspace_review_forms.handle_verification_reject state ~mailbox:async_messages ~terminal_session
       | Some (("<" | ">") as key)
         when state.view = Schedules && Option.is_none state.schedule_detail_id
              ->
           let page =
             if String.equal key "<" then schedule_previous_page state.schedules_page
             else Option.bind state.schedules (schedule_next_page state.schedules_page)
           in
           (match page with
            | None -> ()
            | Some page when not (schedule_navigation_pending state page) ->
                state.schedule_cancel_armed <- None;
                Masc_tui_work_requests.Schedule_call_requests.launch_schedules_load ~intent:Snapshot_read.Refresh ~page state
                  ~mailbox:async_messages
            | Some _ -> ())
       | Some (("<" | ">") as key)
         when state.view = Keepers Keeper_detail && state.detail_tab = Detail_automation
              && (terminal_columns < keeper_split_threshold_cols
                  || state.keeper_detail_focus = Right_pane) ->
           (match selected_keeper state with
            | None -> ()
            | Some keeper ->
                (match state.keeper_schedules_page, state.keeper_schedules with
                 | Some (page_keeper, page), Some (snapshot_keeper, snapshot)
                   when String.equal page_keeper keeper.k_name
                        && String.equal snapshot_keeper keeper.k_name ->
                     let destination =
                       if String.equal key "<" then schedule_previous_page page
                       else schedule_next_page page snapshot
                     in
                     Option.iter
                       (fun page ->
                          if not (keeper_schedule_navigation_pending state ~keeper_name:keeper.k_name page) then
                            Masc_tui_work_requests.Schedule_call_requests.launch_keeper_schedules_load ~page state ~mailbox:async_messages
                              ~keeper_name:keeper.k_name)
                       destination
                 | (Some _ | None), (Some _ | None) -> ()))
       (* Refused while a load is in flight rather than changing the state
          without sending a request: [launch_verification_load] returns early
          when one is already out, so the view and the page would move while
          the answer on its way stayed the old one, and the next refresh would
          read a state nothing had asked the server for. *)
       | Some "h"
         when state.view = Verification && not state.verification_inflight ->
           (* The other list. The store keeps every submission ever made, so
              the history holds rows whose task finished weeks ago; the queue
              holds what a task is still waiting on. Asking which one is a
              key rather than a filter the reader applies by eye. *)
           state.verification_view <-
             (match state.verification_view with
              | Masc.Tui_decode.Awaiting_queue -> Masc.Tui_decode.Full_history
              | Masc.Tui_decode.Full_history -> Masc.Tui_decode.Awaiting_queue);
           state.verification_offset <- 0;
           reset_verification_rows state;
           launch_verification_load state ~mailbox:async_messages
       | Some ">"
         when state.view = Verification && not state.verification_inflight ->
           (* Forward only while the server says a further page exists, so the
              last page does not silently reload itself. *)
           (match state.verification with
            | Some snapshot when snapshot.Masc.Tui_decode.vs_truncated ->
                state.verification_offset <-
                  snapshot.Masc.Tui_decode.vs_offset
                  + List.length snapshot.Masc.Tui_decode.vs_requests;
                reset_verification_rows state;
                launch_verification_load state ~mailbox:async_messages
            | Some _ | None -> ())
       | Some "<"
         when state.view = Verification && not state.verification_inflight ->
           (match state.verification with
            | Some snapshot when snapshot.Masc.Tui_decode.vs_offset > 0 ->
                (* Step back by the page that is on screen. A page shorter
                   than the request limit only happens at the end, and
                   stepping back by it still lands inside the list. *)
                let page =
                  max 1 (List.length snapshot.Masc.Tui_decode.vs_requests)
                in
                state.verification_offset <-
                  max 0 (snapshot.Masc.Tui_decode.vs_offset - page);
                reset_verification_rows state;
                launch_verification_load state ~mailbox:async_messages
            | Some _ | None -> ())
       | Some "x" | Some "X" when state.view = Harness ->
           (* The negative verdict, spelled the way Verification spells its
              own. It was [n], which this surface cannot keep: Harness
              answers the row search, and [n] steps that search on every
              surface that does not bind the key itself. *)
           Masc_tui_editor_forms.Workspace_review_forms.handle_harness_overrule state ~mailbox:async_messages ~terminal_session
       | Some (("l" | "L" | "o") as log_key)
         when (match log_key, state.view with
               | ("l" | "L"), Keepers (Keeper_list | Keeper_detail)
               | "o", Keepers Keeper_detail -> true
               | _, (Keepers (Keeper_list | Keeper_detail | Keeper_logs | Keeper_calls
                             | Keeper_message | Keeper_runtime_pick)
                    | Overview | Acting | Metrics | Memory | Lanes | Clients | Board
                    | Approvals | Planning | Schedules | Verification | Harness | Fusion
                    | Repositories | Code | Changes | Connectors | Runtime | Config
                    | Resources | Tools | System_logs) -> false) ->
           (* Logs, from the roster as well as from detail, for the same reason
              chat is reachable from both: the keeper an operator wants the
              logs of is the one under the cursor. *)
           let keeper = selected_keeper state in
           (match keeper with
            | Some _ ->
                state.log_scroll <- 0;
                transition_keeper_view state (Keepers Keeper_logs);
                ignore (launch_current_keeper_logs state ~mailbox:async_messages ~intent:Snapshot_read.Join)
            | None -> ())
| Some "c" | Some "C"
         when state.view = Runtime
              && Option.is_none state.runtime_detail_target ->
            (* The third Runtime reading: not what the lanes call, not what
               the workspace could call, but who is attached to it — the
               clients roster, off the ring under Runtime the way Lanes is.
               This arm sits above the chat arm because that one takes [c]
               unguarded on every surface that names a Keeper. *)
            goto_surface state ~mailbox:async_messages Clients
       | Some "c" when state.view = Config && state.config_pane = Config_models ->
           Masc_tui_editor_forms.Runtime_config_forms.handle_model_form_open state Masc_tui_model_form.Copy
       | Some "m" when state.view = Config && state.config_pane = Config_models ->
           handle_config_models_open_source ()
       (* [m] on the runtime.toml pane: memory recall. Above the chat arm below,
          which takes [m] on every surface that names a Keeper. The status
          reading hides the source, so it does not open there. *)
       | Some ("m" | "M")
         when state.view = Config && state.config_pane = Config_runtime
              && not state.runtime_config_status_open ->
           Masc_tui_editor_forms.Runtime_config_forms.handle_memory_recall_form_open state ~mailbox:async_messages
       (* [x] on the runtime.toml pane: the [typesafeai] exclusion list, under
          the same condition as [m]. Lower case only: [X] on this pane is the
          draft's discard, read by the draft keys above. *)
       | Some "x"
         when state.view = Config && state.config_pane = Config_runtime
              && not state.runtime_config_status_open ->
           Masc_tui_editor_forms.Runtime_config_forms.handle_typesafeai_exclusion_form_open state
| Some "m" | Some "M" | Some "c" | Some "C" ->
           (* Chat from every row that names a Keeper. Standalone Lanes carry
              no Keeper identity; Keeper chat is owned by the Keepers surface.
              [c] is an alias for [m] because the footer names the action rather
              than the mnemonic. *)
           (match state.view with
            | Code -> ()
            | Keepers Keeper_runtime_pick -> ()
            | Lanes ->
                (match state.lanes_mode with
                 | Lanes_run_list _ | Lanes_run_detail _ | Lanes_measurement_detail _ | Lanes_inventory_detail _ -> ()
                 | Lanes_overview ->
                     show_lanes_action_error state
                       "Cannot open chat: These lanes have no Keeper; use Keepers")
            | Keepers (Keeper_list | Keeper_detail)
              when Option.fold ~none:false
                ~some:(fun (keeper : Tui_decode.keeper) ->
                  keeper.k_origin = Tui_decode.Remote_keeper)
                (selected_keeper state) ->
              report_action state "error"
                "Chat requires a matching workspace for attachments and pasted files"
            | Keepers Keeper_list
              when Option.fold ~none:false
                     ~some:(fun (keeper : Tui_decode.keeper) ->
                       keeper_available_for_new_message state keeper.k_name)
                     (selected_keeper state) ->
                (match selected_keeper state with
                 | Some keeper ->
                     Masc_tui_chat_input.Message_draft_recall.open_message_for_keeper ~return_to:Keeper_chat_return_list state
                       keeper.k_name ~drain_queue:(fun () ->
                         Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path
                           ~mailbox:async_messages);
                     state.view <- Keepers Keeper_message;
                     launch_keeper_history_load state ~mailbox:async_messages
                       ~keeper_name:keeper.k_name
                 | None -> ())
            | Keepers Keeper_detail
              when Option.fold ~none:false
                     ~some:(fun (keeper : Tui_decode.keeper) ->
                       keeper_available_for_new_message state keeper.k_name)
                     (selected_keeper state) ->
                (match selected_keeper state with
                 | Some keeper ->
                     Masc_tui_chat_input.Message_draft_recall.open_message_for_keeper ~return_to:Keeper_chat_return_detail
                       state keeper.k_name ~drain_queue:(fun () ->
                         Masc_tui_chat_dispatch.Queue_steer.drain_queued_message state ~base_path
                           ~mailbox:async_messages);
                     state.view <- Keepers Keeper_message;
                     launch_keeper_history_load state ~mailbox:async_messages
                       ~keeper_name:keeper.k_name
                 | None -> ())
            | Keepers Keeper_detail | Keepers Keeper_list
            | Overview | Acting | Metrics | Keepers Keeper_logs | Keepers Keeper_calls
            | Keepers Keeper_message
            | Board | Approvals | Planning | Schedules | Verification | Harness
            | Memory | Fusion | Repositories | Changes | Connectors | Runtime | Config | Resources | Tools | Clients
            | System_logs -> ())
       | Some "x" | Some "X"
         when state.view = Config && state.config_pane = Config_params ->
           Masc_tui_editor_forms.Runtime_config_forms.handle_runtime_param_clear state ~mailbox:async_messages
       | Some "x" | Some "X"
         when state.view = Config && state.config_pane = Config_themes ->
           (* Back to whatever the terminal reports. Persist the explicit
              [terminal] sentinel so restarts honour terminal-follow instead
              of re-applying the Truecolor default scheme. *)
           Masc_tui_theme_choice.follow_terminal ();
           state.theme_choice <- None;
           state.theme_before_preview <- None;
           (* Withdrawing the choice withdraws the background with it. *)
           sync_theme_page state;
           store_theme_choice (Some Masc_tui_theme_choice.terminal_choice_name)
       | Some "i" | Some "I"
         when state.view = Config && state.config_pane = Config_prompts ->
           if state.prompts_show_runtime_assets
           then
             report_action state "system"
               (ui_text state
                  ~ko:"런타임 프롬프트 자산에는 기록된 모델 입력이 없습니다"
                  ~en:"Runtime prompt assets have no recorded model input")
           else Masc_tui_editor_forms.Skill_prompt_forms.handle_librarian_input_read state ~mailbox:async_messages
       | Some "p" | Some "P"
         when state.view = Runtime
              && Option.is_none state.runtime_detail_target ->
           (* The lane view answers what each lane calls and in what order.
              It cannot answer what this workspace could call: a runtime no
              lane names is absent from it, which is exactly the runtime an
              operator is looking for when they go to assign one. Same [p]
              that moves panes on Tools and Config. The third stop is the
              standalone service lanes, off the ring the way Task Review
              hangs off Planning; [p] there returns here. *)
           (match state.runtime_mode with
            | Masc_tui_types.Runtime_lanes ->
                enter_runtime_mode state ~mailbox:async_messages
                  Masc_tui_types.Runtime_all
            | Masc_tui_types.Runtime_all ->
                enter_standalone_lanes state ~mailbox:async_messages)
       | Some "p" | Some "P" when state.view = Clients ->
           goto_surface state ~mailbox:async_messages
             (Masc_tui_surface_navigation.surface_ring_family state.view)
       | Some "p" | Some "P"
         when state.view = Lanes && state.lanes_mode = Lanes_overview ->
           goto_surface state ~mailbox:async_messages Runtime
       | Some ("1" | "2" | "3" | "4" | "5" | "6" as digit)
         when state.view = Tools
              && not state.composer_focused
              && not (modal_owns_keys state) && not state.palette_open
              && not state.answering_open && not state.link_modal_open
              && Option.is_none (text_input_target state ~compact_viewport) ->
           enter_tools_pane state
             (match digit with
              | "1" -> Tools_surface
              | "2" -> Tools_async
              | "3" -> Tools_activations
              | "4" -> Tools_usage
              | "5" -> Tools_catalog Tools_catalog_list
              | "6" | _ -> Tools_storage)
       | Some "p" | Some "P" when state.view = Tools ->
           (* Six sections, one at a time. Concatenated the first five ran to 326 rows
              on this workspace and the terminal draws twenty, so four of
              them sat behind a per-tool list that never ends. [p] is the
              same key that moves between the Config surface's panes. *)
           enter_tools_pane state
             (match state.tools_pane with
              | Tools_surface -> Tools_async
              | Tools_async -> Tools_activations
              | Tools_activations -> Tools_usage
              | Tools_usage -> Tools_catalog Tools_catalog_list
              | Tools_catalog (Tools_catalog_list | Tools_catalog_volumes _) -> Tools_storage
              | Tools_storage -> Tools_surface)
       | Some "p" | Some "P" when state.view = Config ->
           (* One surface, two files the server reads: runtime.toml and the
              prompt registry. [p] moves between them and loads the list the
              first time it is asked for. *)
           (* Two of the three are files the server reads; the third is this
              reader's own colours, which no server has an opinion about. *)
           enter_config_pane state ~mailbox:async_messages
             (match state.config_pane with
              | Config_runtime -> Config_models
              | Config_models -> Config_params
              | Config_params -> Config_prompts
              | Config_prompts -> Config_presets
              | Config_presets -> Config_themes
              | Config_themes -> Config_voice
              | Config_voice -> Config_runtime)
       | Some "p" | Some "P" ->
           (* The toggle: whichever of pause / resume / boot this reading
              offers first. One key for "stop" and "play" because which one
              applies is a fact about the keeper, not a choice the operator
              should have to make. *)
           (match state.view with
            | Code -> ()
            | Keepers Keeper_runtime_pick -> ()
            | Keepers (Keeper_list | Keeper_detail) -> (
                match
                  Option.map (keeper_reading state) (selected_keeper state)
                  |> Option.map Keeper_control.primary
                with
                | Some (Some action) ->
                    Masc_tui_operator_actions.Keeper_actions.handle_keeper_action state ~base_path
                      ~mailbox:async_messages action
                | Some None ->
                    report_action state "system"
                      (if state.ui_language = Lang_ko then "이 키퍼에 아직 쓸 수 있는 동작 없음"
                       else "No lifecycle action applies to this keeper yet")
                | None -> ())
            | Overview | Acting | Metrics | Keepers Keeper_logs | Keepers Keeper_calls
            | Keepers Keeper_message | Lanes
            | Board | Approvals | Planning | Schedules | Verification | Harness
            | Memory | Fusion | Repositories | Changes | Connectors | Runtime | Config | Resources | Tools | Clients
            | System_logs -> ())
       | Some "s" | Some "S" ->
           (match state.view with
            | Code -> ()
            | Keepers Keeper_runtime_pick -> ()
            | Keepers (Keeper_list | Keeper_detail) ->
                (match state.connection_status with
                 | Disconnected ->
                     (* RFC tui-server-lifecycle: with no server up there is
                        no keeper to shut down, so "s" starts one here. *)
                     Masc_tui_transport.Server_contact.start_here_then_read server_contact state ~base_path ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                       ~port:state.port
                 | Connecting | Booting | Account_server _ | Degraded | Connected ->
                     Masc_tui_operator_actions.Keeper_actions.handle_keeper_action state ~base_path
                       ~mailbox:async_messages Keeper_control.Shutdown)
            | Board ->
                (match state.board_mode with
                 | Board_compose -> ()
                 | Board_list | Board_read _ ->
                     state.board_sort <- next_board_sort state.board_sort;
                     Masc_tui_shell.Preferences.store state
                       (Masc.Tui_preference.Board_sort_chosen (board_sort_order state.board_sort));
                     (* The session log row is read away from Board, so it
                        says the order rather than the token the request
                        carries. *)
                     report_action state "system"
                       ("Board order: "
                        ^ board_sort_explanation state.board_sort);
                     start_http_refresh ~server_contact state ~host:Masc_tui_transport.Workspace_admission.server_peer_host
                       ~port:state.port ~intent:Operator_key
                       ~refresh_inflight:http_refresh_inflight
                       ~scoped_refresh_inflight:http_scoped_refresh_inflight
                       ~scoped_refresh_followup
                       ~mailbox:async_messages)
            | Planning ->
                (* Client-side re-order of the loaded goals: no refetch. *)
                state.planning_sort <- next_planning_sort state.planning_sort;
                clamp_planning_cursor state
            | Overview | Acting | Metrics | Keepers Keeper_logs | Keepers Keeper_calls
            | Keepers Keeper_message | Lanes
            | Approvals | Schedules | Verification | Harness
             | Memory | Fusion | Repositories | Changes | Connectors | Runtime | Config | Resources | Tools | System_logs | Clients -> ())
       | Some "w" | Some "W" ->
           (* Two unrelated bindings share a key: "write" on the Board list,
              "wake up" on a keeper row. The surface decides which one is
              live, and Board compose takes the key only from the list --
              inside the compose pane the letter is draft text. *)
           (match state.view with
            | Code -> ()
            | Keepers Keeper_runtime_pick -> ()
            | Board ->
                (match state.board_mode with
                 | Board_list ->
                     state.board_mode <- Board_compose;
                     state.board_compose_armed <- false;
                     state.board_compose_reply_to <- None;
                     state.board_compose_hearth <- state.board_hearth;
                     state.board_compose_attach_input <- None;
                     state.board_post_error <- None
                 | Board_read _ | Board_compose -> ())
            | Keepers (Keeper_list | Keeper_detail) ->
                Masc_tui_operator_actions.Keeper_actions.handle_keeper_action state ~base_path ~mailbox:async_messages
                  Keeper_control.Wakeup
            | Overview | Acting | Metrics | Keepers Keeper_logs | Keepers Keeper_calls
            | Keepers Keeper_message | Lanes
            | Approvals | Planning | Schedules | Verification | Harness
             | Memory | Fusion | Repositories | Changes | Connectors | Runtime | Config | Resources | Tools | System_logs | Clients
            -> ())
       | Some "E"
         when state.view = Config && state.config_pane = Config_params ->
           Masc_tui_editor_forms.Runtime_config_forms.handle_runtime_param_edit_open state ~advanced:true
       | Some "e" | Some "E"
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_channels ->
           Masc_tui_editor_forms.Connector_forms.handle_connector_edit state ~mailbox:async_messages ~terminal_session
       | Some "e"
         when state.view = Runtime && Option.is_some state.runtime_detail_target ->
           (match state.runtime_detail_target with
            | Some (Runtime_lane_candidate { runtime_id; _ }
                  | Runtime_catalog_entry { runtime_id }) -> Masc_tui_editor_forms.Runtime_config_forms.open_runtime_model_settings state ~mailbox:async_messages runtime_id
            | Some Runtime_routes -> report_action state "info" "Select a runtime to edit its model settings"
            | None -> ())
       | Some "d"
         when state.view = Lanes && Option.is_some state.slot_editor ->
           (* The editor answers over the overview or the inventory detail it
              covers. The picker owns focus while it is open. *)
           if Option.is_none state.runtime_lane_pick then
             Masc_tui_editor_forms.Runtime_config_forms.open_selected_slot_config state ~mailbox:async_messages
       | Some (("e" | "E") as edit_key) ->
           (* The terminal roundtrip stays here; preparation and the guarded
              save run as owned asynchronous operations around it. *)
           (match state.view with
            | Code -> ()
            | Keepers Keeper_runtime_pick -> ()
            | Keepers (Keeper_list | Keeper_detail) ->
                let format = if String.equal edit_key "e"
                  then Masc_tui_keeper_config.Toml else Masc_tui_keeper_config.Json in
                Masc_tui_editor_forms.Skill_prompt_forms.handle_keeper_settings_edit state ~mailbox:async_messages ~format
            | Lanes ->
                (* [missing] is the note for a table runtime.toml does not
                   have yet. *)
                let open_lane_table path ~missing =
                  let section = runtime_config_path_text path in
                  state.view <- Config;
                  state.config_pane <- Config_runtime;
                  state.runtime_config_jump_section <- Some path;
                  (* The answer to [e] is Config opening on the table, so
                     these notes stay in the session log. On the footer
                     they named the table before the pane had drawn it. *)
                  (* A change the server announced while Lanes was on screen
                     is still owed, and the table may be the one it added, so
                     the jump waits for that read instead of searching the
                     reading on hand. *)
                  let read_first () =
                    add_event state "info"
                      (Printf.sprintf "loading runtime.toml for [%s]" section);
                    Masc_tui_surface_requests.Runtime_config_requests.launch_runtime_config_load state ~mailbox:async_messages
                  in
                  (match state.runtime_config_view, state.runtime_config_owed with
                   | None, _
                   | Some _,
                     ( Masc_tui_owed_read.Owed _ | Masc_tui_owed_read.Reading _
                     | Masc_tui_owed_read.Waiting _ ) ->
                     read_first ()
                   | Some _, Masc_tui_owed_read.Settled ->
                     (match apply_runtime_config_jump state with
                      | Some (_, true) ->
                        add_event state "info"
                          (Printf.sprintf
                             "runtime.toml at [%s] - e to edit" section)
                      | Some (_, false) -> report_action state "error" (missing section)
                      | None -> ());
                     (* Lanes [e] opens Config_runtime without
                        [launch_surface_reads], so the arrival owes its read
                        here. [read_first] above is that read already. *)
                     owe_runtime_config_read state)
                in
                (* The open slot editor names its own lane over whichever
                   screen it covers; with none open, the overview names the
                   lane under its cursor. *)
                (match
                   Masc_tui_types.slot_editor_exact_lane state, state.lanes_mode,
                   selected_standalone_lane state
                 with
                 | Some lane, _, _ | None, Lanes_overview, Some { Tui_decode.sl_lane = lane; _ } ->
                   open_lane_table
                     [ Runtime_toml_namespace.(key Runtime); "exact_output_lanes"
                     ; Standalone_lane.to_id lane ]
                     ~missing:(Printf.sprintf "runtime.toml has no [%s] section")
                 | None, Lanes_overview, None ->
                   (match selected_inventory_lane state with
                    | None ->
                      show_lanes_action_error state
                        "Cannot open config: no standalone lane is selected"
                    | Some row ->
                      (match
                         Masc_tui_lane_inventory.selected_exact_output
                           ~selected:(lanes_exact_output_name state row) row
                       with
                       | None ->
                         show_lanes_action_error state
                           "Cannot open config: the selected row has no exact-output lane"
                       | Some (installation_id, output) ->
                         (match
                            Masc_tui_lane_inventory.exact_output_table_path ~installation_id output
                          with
                          | Error reason -> show_lanes_action_error state ("Cannot open config: " ^ reason)
                          | Ok path ->
                            open_lane_table path
                              ~missing:(Printf.sprintf
                                "runtime.toml has no [%s] section yet; e edits runtime.toml to add it"))))
                 | None,
                   (Lanes_run_list _ | Lanes_run_detail _ | Lanes_measurement_detail _ | Lanes_inventory_detail _),
                   _ -> ())
            | Config ->
                (match state.config_pane with
                 | Config_prompts ->
                   if state.prompts_show_runtime_assets
                   then
                     report_action state "system"
                       (ui_text state ~ko:"런타임 프롬프트 자산은 읽기 전용입니다" ~en:"Runtime prompt assets are read-only")
                   else Masc_tui_editor_forms.Skill_prompt_forms.handle_prompt_edit state ~mailbox:async_messages ~terminal_session
                 | Config_runtime -> Masc_tui_editor_forms.Runtime_config_forms.handle_runtime_config_edit state ~mailbox:async_messages ~terminal_session
                 | Config_params ->
                   Masc_tui_editor_forms.Runtime_config_forms.handle_runtime_param_edit_open state ~advanced:false
                 (* Structured fields still use the same preview/commit writer. *)
                 | Config_models -> Masc_tui_editor_forms.Runtime_config_forms.handle_model_form_open state Masc_tui_model_form.Edit
                 (* The preset pane writes through n and u, never $EDITOR. *)
                 | Config_presets | Config_themes -> ()
                 (* The voice pane was a reading. It now opens the wizard,
                    which writes through the setup route rather than $EDITOR:
                    [voice] is one table among many in runtime.toml, and an
                    editor would hand the operator all of them to edit one. *)
                 | Config_voice ->
                   (match state.voice_setup with
                    | Some (`Assoc fields) ->
                      (* No revision, no session: the save carries it, and a
                         wizard opened without one could only fail at the end. *)
                      (match
                         ( List.assoc_opt "revision" fields
                         , Option.bind (List.assoc_opt "source" fields) (function
                             | `Assoc source ->
                               (match
                                  ( List.assoc_opt "kind" source
                                  , List.assoc_opt "path" source )
                                with
                                | Some (`String "standalone_json"), Some (`String path) ->
                                  Some path
                                | _ -> None)
                             | _ -> None) )
                       with
                       (* Voice is read from the standalone JSON. The wizard
                          writes runtime.toml, where a first section would
                          replace everything that file sets; the server refuses
                          that write, so the draft is not started only to be
                          refused at the end. *)
                       | Some (`String _), Some path ->
                         report_action state "system"
                           (Printf.sprintf
                              "voice is read from %s; set it up in that file, or \
                               move it into runtime.toml first"
                              (Terminal_text.single_line path))
                       | Some (`String revision), None ->
                         state.config_scroll <- 0;
                         state.voice_wizard
                           <- Some
                                (Masc_tui_voice_wizard_session.voice_wizard_open
                                   ~section:Voice_setup.Tts
                                   ~provider:Voice_wizard.Elevenlabs ~revision)
                       | (Some _ | None), _ -> ())
                    | Some _ | None -> ()))
            | Tools -> Masc_tui_editor_forms.Skill_prompt_forms.handle_skill_edit state ~mailbox:async_messages ~terminal_session
            | Schedules -> Masc_tui_editor_forms.Workspace_review_forms.handle_schedule_modify state ~mailbox:async_messages ~terminal_session
            | Approvals ->
                state.palette_open <- true;
                state.palette_mode <- Palette_jump;
                state.palette_query <- "gate Outside services / ";
                state.palette_cursor <- 0
            | Overview | Acting | Metrics | Keepers Keeper_logs | Keepers Keeper_calls
            | Keepers Keeper_message
            | Board | Planning | Verification | Harness
             | Memory | Fusion | Repositories | Changes | Connectors | Runtime | Resources | System_logs | Clients -> ())
       | Some "x" | Some "X"
         when state.view = Config && state.config_pane = Config_prompts ->
           if state.prompts_show_runtime_assets
           then
             report_action state "system"
               (ui_text state ~ko:"런타임 프롬프트 자산은 읽기 전용입니다" ~en:"Runtime prompt assets are read-only")
           else Masc_tui_editor_forms.Skill_prompt_forms.handle_prompt_clear state ~mailbox:async_messages
       (* [a] on the runtime.toml pane: one more account of a Claude Code,
          Codex, Antigravity or Muse provider the file already declares. The status
          reading hides the source, so it does not open there. *)
       | Some ("a" | "A")
         when state.view = Config && state.config_pane = Config_runtime
              && not state.runtime_config_status_open ->
           Masc_tui_editor_forms.Runtime_config_forms.handle_runtime_account_open state
       (* [a] on the voice pane: the keepers this workspace has on one axis and
          the voices the section's first endpoint answers to on the other. The
          revision the pane read is what the save carries, so a screen opened
          against one configuration cannot write over another. *)
       | Some "a" | Some "A"
         when state.view = Config && state.config_pane = Config_voice
              && Option.is_none state.voice_wizard ->
           (match state.voice_setup with
            | None ->
                report_action state "system"
                  "voice setup has not been read yet; press r first"
            | Some setup ->
              (match Masc_tui_work_requests.Voice_requests.voice_setup_revision setup, Masc_tui_work_requests.Voice_requests.voice_setup_first_tts_endpoint state with
               | None, _ ->
                   report_action state "system"
                     "the voice setup answer named no revision to write against"
               | Some _, None ->
                   report_action state "system"
                     "[voice.tts] names no endpoint whose voices could be listed"
               | Some revision, Some (kind, api_key_env) ->
                 (match
                    List.map (fun (keeper : keeper) -> keeper.k_name) state.keepers
                  with
                  (* The roster arrives with the refresh tick. Empty is a
                     workspace with no keeper yet, or a read that failed; either
                     way there is nobody to assign a voice to, and a screen with
                     one empty axis cannot say which. *)
                  | [] ->
                      report_action state "system"
                        (match state.keepers_error with
                         | Some error ->
                             Printf.sprintf "the roster could not be read: %s"
                               (Terminal_text.single_line error)
                         | None -> "no keeper on the roster to give a voice to")
                  | agents ->
                 state.config_scroll <- 0;
                 state.voice_agent_voices
                   <- Some (Masc_tui_types.voice_agent_open ~agents ~revision);
                 Masc_tui_work_requests.Voice_requests.launch_voice_agent_voices state ~mailbox:async_messages ~kind
                   ~api_key_env)))
       | Some "a" | Some "A"
         when state.view = Config && state.config_pane = Config_prompts
              && not state.prompts_show_runtime_assets ->
           state.prompts_show_fragments <- not state.prompts_show_fragments;
           state.prompts_cursor <- 0;
           state.config_scroll <- 0;
           state.prompts_librarian_input <- None;
           state.prompts_librarian_input_error <- None;
           state.prompts_librarian_input_loading <- false;
           report_action state "system"
             (if state.prompts_show_fragments then
                ui_text state ~ko:"프롬프트 목록에 내부 조각을 표시합니다" ~en:"Showing internal fragments in Prompts"
              else
                ui_text state ~ko:"프롬프트 목록에 주 프롬프트만 표시합니다" ~en:"Showing primary prompts only in Prompts")
       | Some "o" | Some "O"
         when state.view = Config && state.config_pane = Config_prompts ->
           state.prompts_show_runtime_assets <- not state.prompts_show_runtime_assets;
           state.prompts_cursor <- 0;
           state.config_scroll <- 0;
           state.prompts_librarian_input <- None;
           state.prompts_librarian_input_error <- None;
           state.prompts_librarian_input_loading <- false;
           report_action state "system"
             (if state.prompts_show_runtime_assets then
                ui_text state ~ko:"읽기 전용 런타임 프롬프트 자산을 표시합니다" ~en:"Showing read-only runtime prompt assets"
              else
                ui_text state ~ko:"재정의 가능한 프롬프트 레지스트리를 표시합니다" ~en:"Showing overridable prompt registry")
       | Some "b"
         when state.view = Connectors
               || (state.view = Keepers Keeper_detail
                   && state.detail_tab = Detail_channels) ->
            Masc_tui_editor_forms.Connector_forms.handle_connector_bind state ~mailbox:async_messages ~terminal_session
       | Some "u"
         when state.view = Connectors
              || (state.view = Keepers Keeper_detail
                  && state.detail_tab = Detail_channels) ->
           Masc_tui_editor_forms.Connector_forms.handle_connector_unbind state ~mailbox:async_messages ~terminal_session
       | Some "U"
         when state.view = Keepers Keeper_detail
              && state.detail_tab = Detail_channels ->
           Masc_tui_editor_forms.Connector_forms.handle_connector_unbind_all state ~mailbox:async_messages
       | Some "a" | Some "A" ->
           (match state.view with
            | Code -> ()
            | Keepers Keeper_runtime_pick -> ()
            | Keepers (Keeper_list | Keeper_detail) -> Masc_tui_editor_forms.Workspace_review_forms.handle_keeper_create state ~mailbox:async_messages ~terminal_session ~show_keeper_list:(fun () -> goto_surface state ~mailbox:async_messages (Keepers Keeper_list))
            (* The route and its permission already existed; only the TUI had
               no way to reach them, so Workspace could list what was registered
               and never register anything. *)
            | Repositories -> Masc_tui_editor_forms.Workspace_review_forms.handle_repository_add state ~mailbox:async_messages ~terminal_session
            | Verification ->
                (* Two presses, like every irreversible action here: the
                   first names the task, the second sends the approval. *)
                Masc_tui_work_actions.Verification_actions.handle_verification_approve_key state ~mailbox:async_messages
            | Approvals ->
                (* The approval queue owns this surface's arrows and its y/n,
                   so answering a Keeper's question opens as its own mode. *)
                Masc_tui_operator_actions.Ask_actions.enter_ask_answering state
            | Overview | Acting | Metrics | Keepers Keeper_logs | Keepers Keeper_calls
            | Keepers Keeper_message | Memory | Lanes
            | Board | Planning | Schedules | Harness
            | Fusion | Changes | Connectors | Runtime | Config | Resources | Tools | System_logs | Clients -> ())
      | _ -> ());

      (* A signal can precede already-buffered keys, including after a
         graphics reply. Keep the share barrier until that input is drained. *)
      if !share_interrupt_barrier || Masc_tui_exit_signals.pending_signal exit_signals then
        withdraw_pending_image_open state;
      if !share_interrupt_barrier
         && not (input_reader_has_unsettled_input input_reader)
         && Queue.is_empty hangul_latin_queue
         && (match paste_phase input_reader with No_paste -> true | Pasting _ | Draining_tail _ -> false)
      then share_interrupt_barrier := false;

      (* Surface navigation asks only for datasets the destination adds. The
         full refresh owns aggregate connection status and global badges; replaying
         it for every Tab made an Overview -> Tools walk spend those requests
         once per distinct [surface_needs] record. A scoped refresh revalidates
         identity before its datasets but keeps aggregate connection status. *)
      if state.view = System_logs && !drawn_needs <> current_surface_needs state then
        Masc_tui_refresh_settlement.System_log_stream.refresh_client_system_logs state;
      let needed =
        current_surface_needs state
      in
      if
        needed <> !drawn_needs
        && ((not !http_refresh_inflight && not !http_scoped_refresh_inflight)
            || server_authority_ready state)
      then begin
        let delta =
          Masc_tui_types.surface_needs_delta ~previous:!drawn_needs ~next:needed
        in
        drawn_needs := needed;
        Masc_tui_types.note_drawn_surface_needs state needed;
        (* The operator moved to another screen or view, and it reads what
           the destination adds at once, during a [/health] wait too (RFC
           tui-one-screen-grammar §2). [drawn_needs] already holds the
           destination, so a held read here would be lost; it is not held. *)
        if Masc_tui_types.surface_needs_any delta then
          start_http_scoped_refresh ~server_contact state ~host:(Masc_tui_transport.Workspace_admission.server_peer_host)
            ~port:state.port ~ask:Masc_tui_refresh_pace.Operator_change
            ~refresh_inflight:http_scoped_refresh_inflight
            ~full_refresh_inflight:http_refresh_inflight ~scoped_refresh_followup
            ~mailbox:async_messages ~needs:delta
      end;

      Eio.Fiber.yield ();
      (* Shares the deadline set when the wait ended: when the
         pass budget is spent this applies nothing and the mailbox waits for
         the next pass. *)
      retire_music_editor_for_input ();
      if
        drain_async_messages ~server_contact ~delivery_round:async_delivery_round ~deferred_share_messages ~deferred_share_sweep ~resource_copy_sweep ~deadline_ns:!drain_deadline_ns
          ~input_pending:(fun () -> input_reader_has_ready_input input_reader
              || Masc_tui_exit_signals.pending_signal exit_signals
              || Option.is_some state.quit_armed
              || Frame_presenter.last_frame_is_compact frame_presenter)
          ~share_input_pending:asynchronous_input_pending state ~base_path
          ~http_refresh_inflight
          ~http_scoped_refresh_inflight ~scoped_refresh_followup
          ~frame_presenter ~render_schedule async_messages
      then Render_schedule.request render_schedule Render_schedule.Background;

      if Masc_tui_types.reconcile_keeper_settings_editor state
          ~available:(Masc_tui_surface_requests.Keeper_surface_requests.keeper_settings_editor_available state) then
        Render_schedule.request render_schedule Render_schedule.Background;

      Masc_tui_transport.Event_streams.reconcile_observer_machine ~browser_scope:observer_browser_scope state ~host:Masc_tui_transport.Workspace_admission.server_peer_host ~port:state.port
        ~mailbox:async_messages;
      (* Only an owned, live observer stream carries waiting-inventory
         changes; a watcher holding an unverified request reads this to know
         whether waiting for one can end (#36205). *)
      Masc_tui_waiting_inventory.observe_hearing state.waiting_inventory
        (match state.observer with
         | Observer_live _ -> Keeper_chat.Observer_stream_live
         | Observer_off | Observer_opening | Observer_closed_before_answer _
         | Observer_closed_after_live _ -> Keeper_chat.No_observer_stream);
      launch_owed_machine_live state ~mailbox:async_messages;
      launch_owed_lanes state ~mailbox:async_messages;
      launch_owed_lane_addons state ~mailbox:async_messages;
      launch_owed_browser_observation state ~mailbox:async_messages;
      launch_owed_memory_input state ~mailbox:async_messages;
      Masc_tui_chat_dispatch.Chat_journals.reconcile_context_inspector_part state ~mailbox:async_messages;
      if Masc_tui_transport.Local_sources.reconcile_live_context state ~mailbox:async_messages then
        Render_schedule.request render_schedule Render_schedule.Background;
      if reconcile_keeper_logs state ~mailbox:async_messages then
        Render_schedule.request render_schedule Render_schedule.Background;
      if Masc_tui_work_requests.Tools_task_requests.reconcile_task_documents ~terminal_size:Masc_tui_render_prim.get_terminal_size state ~mailbox:async_messages then
        Render_schedule.request render_schedule Render_schedule.Background;

      (* Without new data only time text changes: the zone-1 clock, moments
         and lengths (RFC tui-one-screen-grammar §8). The last built frame
         said when its first such text reads differently; the frame for that
         is drawn on the following whole second, and a frame with no such
         text schedules none. About keeps its independent clock below. *)
      (match !time_redraw_due with
       | Some due
         when Masc_tui_wake.reached_wall Masc_tui_wake.Time_text
                ~now:(Unix.gettimeofday ()) ~at:due ->
           time_redraw_due := None;
           Render_schedule.request render_schedule Render_schedule.Background
       | Some _ | None -> ());
      (* /about has a finite arrival. A closed overlay and a final frame
         schedule no further candle work, even when the previous frame drew
         motion immediately before the reader left. *)
      (match Masc_tui_emblem_screen.drawn () with
       | Masc_tui_emblem_screen.Moving when state.about_open ->
           let now = Masc_tui_wake.Mono.now () in
           if
             Masc_tui_wake.reached_mono Masc_tui_wake.Emblem_step ~now
               ~at:(Masc_tui_wake.Mono.after !emblem_last_step Masc_tui_types.motion_step_s)
           then begin
             emblem_last_step := now;
             state.emblem_frame <-
               min Masc_tui_emblem_screen.final_frame (state.emblem_frame + 1);
             Render_schedule.request render_schedule Render_schedule.Background
           end
       | Masc_tui_emblem_screen.Moving
       | Masc_tui_emblem_screen.Still
       | Masc_tui_emblem_screen.Absent ->
           if not state.about_open then state.emblem_frame <- -1);
      if expire_identity_logins state ~now:(Unix.gettimeofday ()) then
        Render_schedule.request render_schedule Render_schedule.Background;

      (* A confirmation sees the event just handled in its old phase. Only
         after that event is finished may a drained confirmation become ready. *)
      state.quit_armed <- Option.map (fun arm ->
          { arm with qa_confirmation =
              Masc_tui_action_notice.quit_after_drain arm.qa_confirmation
                ~currently_visible:(last_visible_quit
                  ~presented_rows:(Frame_presenter.presented_rows frame_presenter) ())
                ~input_pending:(input_unsettled ()
                  || Masc_tui_exit_signals.interrupt_pending exit_signals) }) state.quit_armed;
      (* An armed quit is withdrawn when its notice leaves the screen. *)
      Option.iter (fun arm ->
          let _, shown_at = Masc_tui_action_notice.quit_ordinary arm.qa_confirmation in
          ignore (Masc_tui_wake.reached_wall Masc_tui_wake.Quit_notice_expiry
                    ~now:(Unix.gettimeofday ()) ~at:(shown_at +. last_action_window_s)))
        state.quit_armed;
      (match state.quit_armed with
       | Some arm when Option.is_none (current_quit_confirmation state ~now:(Unix.gettimeofday ())) ->
           let kind = Masc_tui_action_notice.quit_kind arm.qa_confirmation in
           Masc_tui_shell.Quit_guard.withdraw state;
           (match kind with
            | Masc_tui_action_notice.Interrupt -> Masc_tui_exit_signals.withdraw_interrupt exit_signals
            | Masc_tui_action_notice.Quit_key -> ())
       | Some _ | None -> ());
      let ready_input = input_reader_has_ready_input input_reader || not (Queue.is_empty hangul_latin_queue) in
      (* An incomplete sequence with no ready bytes must not starve recovery
         frames. A post-presentation hold keeps its eventual tail quarantined. *)
      let granted_search_paste =
        Option.is_some (!presented).context_search
        && panel_owner_current () = Some Presented.Context_search
        && panel_owner_matches (Some Presented.Context_search)
        && (match paste_phase input_reader with
            | Pasting paste -> not (cancel_armed paste)
            | No_paste | Draining_tail _ -> false) in
      (* Slash gives this unfinished paste to the query. Let that reader
         finish before committing the search frame, even between buffers;
         an explicit cancel and unrelated incomplete sequences still allow
         recovery instructions to be presented. *)
      let transition_input_pending = ready_input || Option.is_some interrupted_paste
        || granted_search_paste in
      reconcile_task_detail_scroll state;
      reconcile_tools_task_scroll state;
      if Masc_tui_refresh_settlement.System_log_stream.reads_in_flight state <> reads_before then
        Render_schedule.request render_schedule Render_schedule.Background;
      let terminal_rows, _ = get_terminal_size () in
      let frame_choice = Masc_tui_render.frame_choice state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) in
      let owned_frame = match frame_choice with
        | `Queue _ | `Play_card _ | `Help -> true
        | `Too_small _ | `Account_login _ | `Account_server _ | `Palette | `Collab _ | `Lane_addons _
        | `Detail_reading _ | `About | `Context | `Keeper_deletions
        | `Agenda | `Answering | `Link | `Client_detail _ | `Surface -> false in
      let compact_recovery = match frame_choice with
        | `Too_small _ -> not ready_input
        | `Queue _ | `Play_card _ | `Account_login _ | `Account_server _ | `Palette | `Collab _ | `Lane_addons _
        | `Detail_reading _ | `About | `Context | `Keeper_deletions | `Help
        | `Agenda | `Answering | `Link | `Client_detail _ | `Surface -> false in
      let panel_changed = Presented.panel_presentation_changed !presented
          ~current_owner:(Masc_tui_render.panel_input_owner state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ())) in
      let defer_owned_frame = transition_input_pending && not compact_recovery
        && (owned_frame || Option.is_some (queue_owner_of_reader (!presented).reader)
            || Option.is_some (play_card_of_reader (!presented).reader)
            || help_is_presented (!presented).reader || panel_changed) in
      (* A picture drawn outside the presenter has the terminal. With frame
         timing on, a frame start that draws nothing marks where it took
         over, so the request probe can tell it from the surface underneath
         (scripts/harness/perf/tui_request_surfaces.py). The machine screen
         records its own batches. *)
      if state.image_open && not state.msx_open then
        Masc_tui_frame_timing.note_external ~surface:"image" ~write:write_terminal_text
          ~frame_start:Frame_presenter.external_frame_start;
      (* A failed write left the terminal short of what the presenter
         recorded; diffing against that record would leave rows wrong. *)
      if Masc_tui_terminal_out.take_lost () then begin
        Frame_presenter.invalidate frame_presenter;
        Render_schedule.request render_schedule Render_schedule.Force
      end;
      (match
         Render_schedule.take
           ~input_pending:ready_input
           render_schedule
           ~now_ns:(Mtime_clock.elapsed_ns ())
       with
       (* The terminal has not taken the last frame yet. A new one waits a
          frame interval instead of queueing behind it, so a terminal that
          stops reading holds one frame, not one per pass. *)
       | Render_schedule.Render when Masc_tui_terminal_out.behind () ->
           Render_schedule.request render_schedule Render_schedule.Background
       (* The terminal belongs to the picture until it is dismissed. A frame
          drawn now would clear the rows it occupies and leave the rest. *)
       | Render_schedule.Render when state.image_open || state.msx_open ->
           (* This frame is the picture's, so no candle is on screen and
              nothing should keep stepping one, and a candle placed over the
              last frame comes down rather than float over the picture.
              Closing the picture repaints in full, and the candle steps
              again from that frame. *)
           Masc_tui_emblem_screen.begin_frame ();
           Masc_tui_portrait_view.begin_frame ();
           Masc_tui_message_layout.begin_frame ();
           Masc_tui_approval_detail.begin_frame ();
           (* The picture draws no time text. Closing it repaints in full,
              and that frame says when time next changes its text. *)
           time_redraw_due := None;
           Masc_tui_portrait_view.flush Frame_presenter.Unchanged ~write:write_to_terminal;
           frame_drawn := true
       | Render_schedule.Render when defer_owned_frame ->
           Render_schedule.request render_schedule Render_schedule.Background
       | Render_schedule.Render ->
           (* A response may arrive before a key that still belongs to the
              displayed reader. Settle only when this exact reader is about to
              be drawn and unfinished terminal input has been handled. *)
           (match frame_choice, current_detail_reading state with
            | `Detail_reading shown, Some current when shown == current ->
                (match settle_keeper_peer_reading state
                         ~input_pending:(asynchronous_input_pending ()) with
                 | Peer_waiting_input -> Render_schedule.request render_schedule Render_schedule.Background
                 | Peer_no_result | Peer_result_applied -> ())
            | (`Too_small _ | `Play_card _ | `Account_login _ | `Account_server _ | `Palette | `Collab _
              | `Lane_addons _ | `Detail_reading _ | `About | `Context | `Keeper_deletions
              | `Help | `Agenda | `Answering | `Queue _ | `Link | `Client_detail _
              | `Surface), (Some _ | None) -> ());
           (* Keys and async updates can change the pane reservation after
              the interaction snapshot. Store the focus the next frame shows. *)
           reconcile_chat_focus ();
           let drawn_detail_reading = ref None in
           let frame, clamped, approval, presses, panes, acting_pane, chat_row_actions, drawn_tools_task,
               lists_drawn =
             Masc_tui_frame_timing.time_tagged Masc_tui_frame_timing.Build
               ~tag:(fun (frame, _, _, _, _, _, _, _, _) -> frame.Frame_presenter.surface_key)
               (fun () ->
                 Masc_tui_value.Redraw.begin_frame ();
                 Masc_tui_types.begin_drawn_reads ();
                 Masc_tui_message_layout.begin_frame ();
                 Masc_tui_approval_detail.begin_frame ();
                 Masc_tui_approvals_model.reconcile_value_reading state;
                 (* Event folding is frame preparation, so its cost belongs
                    inside Build timing even though only the loop stores it. *)
                 let terminal_rows, terminal_cols = Masc_tui_ansi.get_terminal_size () in
                 (match acting_pane_chunk_projection state ~terminal_rows ~terminal_cols ~now:(Unix.gettimeofday ()) with
                  | None -> ()
                  | Some projection -> state.acting_chunk_projection <- Some projection);
                 (* This lazy belongs to one synchronous Build on the UI
                    domain. Its first force precedes only Home focus/scroll
                    updates, which preserve the reading used by drawing. *)
                 let home = lazy (
                   if Masc_tui_frame_timing.enabled then begin
                     let reading = match Masc_tui_approvals_model.approvals_questions_reading state with
                       | Masc_tui_approvals_model.List_read -> Masc_tui_frame_timing.Questions_current
                       | List_not_read (Approval_unread | Approval_kept_back _) -> Masc_tui_frame_timing.Questions_unread
                       | List_not_read (Approval_stale _) -> Masc_tui_frame_timing.Questions_stale
                       | List_not_read (Approval_failed _) -> Masc_tui_frame_timing.Questions_failed
                       | List_not_read (Approval_unavailable _) -> Masc_tui_frame_timing.Questions_unavailable in
                     Masc_tui_frame_timing.note_home_forced reading
                   end;
                   let prepare_started = Masc_tui_frame_timing.start_stage () in
                   let prepared = Masc_tui_home.prepare state in
                   Masc_tui_frame_timing.finish_stage ~name:"home.prepare" prepare_started;
                   prepared) in
                 (match state.view, Masc_tui_render.frame_choice state ~terminal_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) with
                  | Overview, `Surface ->
                      let prepared = Lazy.force home in
                      let selection_started = Masc_tui_frame_timing.start_stage () in
                      let selected = Masc_tui_home.home_selected_action prepared in
                      if Option.is_none state.home_selected
                         && Masc_tui_home.home_initial_reading_ready prepared then
                        state.home_selected <- selected;
                      let body = Masc_tui_home.home_body prepared
                          ~scroll:state.home_decision_scroll
                          ~budget:(Masc_tui_render_prim.surface_chrome_budget
                            ~frame:Masc_tui_render_prim.Chrome_screen state ~terminal_rows) in
                      state.home_decision_scroll <- body.hb_first;
                      Masc_tui_frame_timing.finish_stage ~name:"home.selection" selection_started
                  | Overview, `Detail_reading _ -> ()
                  | (Overview, (`Palette | (`Link | (`Help | (`About | (`Play_card _ | (`Client_detail _ | (`Account_login _ | `Account_server _ | (`Keeper_deletions | (`Agenda | (`Too_small _ | (`Collab _ | (`Context | (`Lane_addons _ | (`Answering | `Queue _)))))))))))))))
                  | ((Acting | (Metrics | (Memory | (Lanes | (Clients | (Board | (Approvals | (Planning | (Schedules | (Verification | (Harness | (Fusion | (Repositories | (Code | (Changes | (Connectors | (Runtime | (Config | (Resources | (Tools | (System_logs | Keepers _))))))))))))))))))))), _) -> ());
                 let compact_recovery_notice =
                   if input_holds_incomplete_sequence input_reader then
                     Some "Terminal sequence incomplete; Ctrl-C cancels it"
                   else None in
                 (* This is the renderer's typed choice at its content height;
                    the emitted frame later decides whether it is compact. *)
                 let content_rows, _ = Masc_tui_render_prim.get_terminal_size () in
                 drawn_detail_reading := (match Masc_tui_render.frame_choice state ~terminal_rows:content_rows ~terminal_cols:(snd (Masc_tui_ansi.get_terminal_size ())) ~now:(Unix.gettimeofday ()) with
                   | `Detail_reading reading -> Some reading
                   | `Too_small _ | `Play_card _ | `Account_login _ | `Account_server _ | `Palette | `Collab _
                   | `Lane_addons _ | `About | `Context | `Keeper_deletions | `Help | `Agenda
                   | `Answering | `Queue _ | `Link | `Client_detail _ | `Surface -> None);
                 let built = render ~home ~compact_recovery_notice state in
                 (* What this frame drew is what the readers' next answers
                    are compared with (RFC tui-one-screen-grammar §8). *)
                 Masc_tui_types.note_drawn_reads state;
                 built)
           in
           time_redraw_due :=
             Render_schedule.Time_redraw.due ~now:(Unix.gettimeofday ())
               (Masc_tui_value.Redraw.next_change ());
           let terminal_rows, cols = get_terminal_size () in
           let change_authority = Masc_tui_render_repositories.repository_changes_authority state
               ~surface_key:frame.Frame_presenter.surface_key ~terminal_rows ~cols in
           (* The frame is what the operator will act on next, so the scroll it
              had to clamp is the scroll the next keypress moves from. Applied
              here rather than inside the drawing: a surface whose row count
              only exists once the frame is built cannot be bounded before it,
              but the drawing does not have to be the thing that stores it. *)
           Option.iter (fun value ->
             if not (task_detail_following_end state
                     && Option.is_some (task_detail_of_reader (Some value))) then
               apply_clamped_scroll state value) clamped;
           (* So are the lists it drew: a page key moves each by the rows
              this frame drew it in. *)
           state.lists_drawn <- lists_drawn;
           Masc_tui_shell.Terminal_session.present_title terminal_session state;
           Masc_tui_frame_timing.time_present
             ~tag:frame.Frame_presenter.surface_key
             ~write:Masc_tui_terminal_out.write ~flush:Masc_tui_terminal_out.flush
             (present_frame frame approval presses panes acting_pane chat_row_actions change_authority
                ~drawn_detail_reading:!drawn_detail_reading ~drawn_tools_task
                ~input_pending:asynchronous_input_pending clamped);
           (* An overrun must leave time to consume the input it accumulated.
              Measuring the interval from Build start made every queued key
              start another overdue frame before the reader could catch up.
              Drained input still bypasses the interval in [take]. *)
           Render_schedule.completed render_schedule ~now_ns:(Mtime_clock.elapsed_ns ());
           frame_drawn := true
       | Render_schedule.Idle | Render_schedule.Wait_until _ -> ())
    done
  in
  Fun.protect ~finally:(fun () ->
    Masc_tui_shell.Terminal_session.restore terminal_session;
    Masc_tui_config.close_keeper_preference_writer state.keeper_preference_writer;
    Masc_tui_config.drain_keeper_preferences state.keeper_preference_writer
      ~can_take:(fun () -> true)
      ~apply:(fun completion -> ignore (apply_keeper_preference_completion state completion));
    Masc_tui_shell.Terminal_session.set_keeper_preference_exit_warnings terminal_session
      (keeper_preference_unresolved_warnings state);
    Masc_tui_preference_writer.close state.preference_writer;
    ignore (Masc_tui_shell.Preferences.drain_completions state ~can_take:(fun () -> true))) run_loop

let () =
  (* Informational flags terminate during parsing, before base-path
     resolution and before the TUI installs its runtime/terminal context. *)
  let args = Masc_tui_shell.Bootstrap.parse_args () in
  Masc_tui_shell.Bootstrap.run_with_eio_context (main args)
